--
-- Name: fn_refresh_schema_dependency_map(); Type: FUNCTION; Schema: archive; Owner: -
--

CREATE FUNCTION archive.fn_refresh_schema_dependency_map() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'archive', 'pg_catalog'
    AS $$
DECLARE
  v_inserted int := 0;
BEGIN
  -- Limpa snapshot anterior
  DELETE FROM archive.schema_dependency_map;

  -- 1. Foreign Keys
  INSERT INTO archive.schema_dependency_map
    (from_schema, from_table, from_column, to_schema, to_table, to_column,
     constraint_name, delete_rule, category)
  SELECT
    tc.table_schema, tc.table_name, kcu.column_name,
    ccu.table_schema, ccu.table_name, ccu.column_name,
    tc.constraint_name, rc.delete_rule,
    'foreign_key'
  FROM information_schema.table_constraints tc
  JOIN information_schema.key_column_usage kcu
    ON tc.constraint_name=kcu.constraint_name AND tc.table_schema=kcu.table_schema
  JOIN information_schema.constraint_column_usage ccu
    ON ccu.constraint_name=tc.constraint_name
  JOIN information_schema.referential_constraints rc
    ON rc.constraint_name=tc.constraint_name
  WHERE tc.constraint_type='FOREIGN KEY'
    AND tc.table_schema NOT IN ('pg_catalog','information_schema');

  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  -- 2. View dependencies (cross-schema)
  INSERT INTO archive.schema_dependency_map
    (from_schema, from_table, from_column, to_schema, to_table, to_column, category)
  SELECT DISTINCT
    v.table_schema, v.table_name, '—',
    d.table_schema, d.table_name, '—',
    'view_dependency'
  FROM information_schema.views v
  JOIN information_schema.view_table_usage d
    ON v.table_name=d.view_name AND v.table_schema=d.view_schema
  WHERE v.table_schema NOT IN ('pg_catalog','information_schema');

  RETURN jsonb_build_object(
    'foreign_keys_mapped', v_inserted,
    'captured_at', NOW(),
    'total_rows', (SELECT COUNT(*) FROM archive.schema_dependency_map)
  );
END;
$$;


--
-- Name: fn_schema_migration_readiness(text); Type: FUNCTION; Schema: archive; Owner: -
--

CREATE FUNCTION archive.fn_schema_migration_readiness(p_schema text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'archive', 'pg_catalog'
    AS $$
DECLARE
  v_result       jsonb := '{}';
  v_blocker_fk   int;
  v_blocker_view int;
  v_table_count  int;
  v_safe         boolean;
BEGIN
  -- Tabelas no schema
  SELECT COUNT(*) INTO v_table_count
  FROM pg_tables WHERE schemaname = p_schema;

  -- FKs bloqueantes: tabelas em OUTROS schemas que apontam para ESTE schema
  SELECT COUNT(*) INTO v_blocker_fk
  FROM archive.schema_dependency_map
  WHERE category='foreign_key'
    AND to_schema = p_schema
    AND from_schema != p_schema
    AND from_schema NOT IN ('auth','storage','_realtime','realtime','pg_catalog');

  -- Views em OUTROS schemas que dependem deste schema
  SELECT COUNT(*) INTO v_blocker_view
  FROM archive.schema_dependency_map
  WHERE category='view_dependency'
    AND to_schema = p_schema
    AND from_schema != p_schema
    AND from_schema NOT IN ('pg_catalog','information_schema');

  v_safe := (v_blocker_fk = 0 AND v_blocker_view = 0);

  RETURN jsonb_build_object(
    'schema',              p_schema,
    'table_count',         v_table_count,
    'safe_to_migrate',     v_safe,
    'blocking_fks',        v_blocker_fk,
    'blocking_views',      v_blocker_view,
    'verdict',             CASE
      WHEN v_safe THEN '✅ Pode migrar sem impacto'
      ELSE '🚫 Bloqueado — resolva dependências primeiro'
    END
  );
END;
$$;


