    email text NOT NULL,
    nome text,
    role text DEFAULT 'fechamento'::text NOT NULL,
    ativo boolean DEFAULT true NOT NULL,
    criado_em timestamp with time zone DEFAULT now() NOT NULL,
    atualizado_em timestamp with time zone DEFAULT now() NOT NULL,
    bitrix_user_id integer,
    CONSTRAINT app_usuarios_role_check CHECK ((role = ANY (ARRAY['admin'::text, 'fechamento'::text])))
);


--
-- Name: TABLE usuarios; Type: COMMENT; Schema: artes; Owner: -
--

COMMENT ON TABLE artes.usuarios IS 'Roles da app de Fechamento de Artes (admin | fechamento) + flag ativo';


--
-- Name: COLUMN usuarios.bitrix_user_id; Type: COMMENT; Schema: artes; Owner: -
--

COMMENT ON COLUMN artes.usuarios.bitrix_user_id IS 'ID do usuário no Bitrix24 (promobrindes.bitrix24.com.br) para enviar notificações via im.notify.system.add';


--
-- Name: admin_atualizar_usuario(uuid, text, boolean, text); Type: FUNCTION; Schema: artes; Owner: -
--

CREATE FUNCTION artes.admin_atualizar_usuario(p_user_id uuid, p_role text DEFAULT NULL::text, p_ativo boolean DEFAULT NULL::boolean, p_nome text DEFAULT NULL::text) RETURNS artes.usuarios
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'artes'
    AS $$
DECLARE rec artes.usuarios;
BEGIN
  IF NOT artes.is_admin() THEN RAISE EXCEPTION 'Acesso negado'; END IF;
  IF p_role IS NOT NULL AND p_role NOT IN ('admin','fechamento') THEN RAISE EXCEPTION 'Role inválida: %', p_role; END IF;
  IF p_user_id = auth.uid() AND (p_ativo = FALSE OR p_role = 'fechamento') THEN
    RAISE EXCEPTION 'Você não pode desativar ou remover seu próprio acesso de admin';
  END IF;

  UPDATE artes.usuarios
  SET role = COALESCE(p_role, role),
      ativo = COALESCE(p_ativo, ativo),
      nome = COALESCE(p_nome, nome),
      atualizado_em = now()
  WHERE user_id = p_user_id
  RETURNING * INTO rec;
  RETURN rec;
END;
$$;


--
-- Name: admin_criar_usuario(text, text, text, text); Type: FUNCTION; Schema: artes; Owner: -
--

CREATE FUNCTION artes.admin_criar_usuario(p_email text, p_senha text, p_nome text, p_role text DEFAULT 'fechamento'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'artes', 'auth', 'extensions'
    AS $$
DECLARE
  v_user_id UUID;
  v_email TEXT;
BEGIN
  IF NOT artes.is_admin() THEN RAISE EXCEPTION 'Acesso negado'; END IF;
  IF p_email IS NULL OR length(trim(p_email)) = 0 THEN RAISE EXCEPTION 'Email obrigatório'; END IF;
  IF p_senha IS NULL OR length(p_senha) < 6 THEN RAISE EXCEPTION 'Senha precisa ter no mínimo 6 caracteres'; END IF;
  IF p_role NOT IN ('admin','fechamento') THEN RAISE EXCEPTION 'Role inválida: %', p_role; END IF;

  v_email := lower(trim(p_email));
  v_user_id := gen_random_uuid();

  INSERT INTO auth.users (
    instance_id, id, aud, role, email, encrypted_password,
    email_confirmed_at, raw_app_meta_data, raw_user_meta_data,
    created_at, updated_at, confirmation_token,
    email_change, email_change_token_new, recovery_token
  ) VALUES (
    '00000000-0000-0000-0000-000000000000',
    v_user_id, 'authenticated', 'authenticated',
    v_email, extensions.crypt(p_senha, extensions.gen_salt('bf')),
    now(),
    '{"provider":"email","providers":["email"]}',
    jsonb_build_object('nome', p_nome, 'role', p_role),
    now(), now(), '', '', '', ''
  );
  INSERT INTO auth.identities (
    id, user_id, identity_data, provider, provider_id,
    last_sign_in_at, created_at, updated_at
  ) VALUES (
    gen_random_uuid(), v_user_id,
    jsonb_build_object('sub', v_user_id::text, 'email', v_email, 'email_verified', true),
    'email', v_email, now(), now(), now()
  );

  INSERT INTO artes.usuarios (user_id, email, nome, role, ativo)
  VALUES (v_user_id, v_email, p_nome, p_role, TRUE)
  ON CONFLICT (user_id) DO UPDATE
  SET nome = EXCLUDED.nome, role = EXCLUDED.role, ativo = TRUE, atualizado_em = now();

  RETURN v_user_id;
END;
$$;


--
-- Name: admin_listar_usuarios(); Type: FUNCTION; Schema: artes; Owner: -
--

CREATE FUNCTION artes.admin_listar_usuarios() RETURNS TABLE(user_id uuid, email text, nome text, role text, ativo boolean, criado_em timestamp with time zone, ultimo_login timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'artes'
    AS $$
BEGIN
  IF NOT artes.is_admin() THEN RAISE EXCEPTION 'Acesso negado'; END IF;
  RETURN QUERY
  SELECT u.user_id, u.email, u.nome, u.role, u.ativo, u.criado_em, au.last_sign_in_at
  FROM artes.usuarios u
  LEFT JOIN auth.users au ON au.id = u.user_id
  ORDER BY u.ativo DESC, u.email;
END;
$$;


--
-- Name: admin_remover_usuario(uuid); Type: FUNCTION; Schema: artes; Owner: -
--

CREATE FUNCTION artes.admin_remover_usuario(p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'artes', 'auth'
    AS $$
BEGIN
  IF NOT artes.is_admin() THEN RAISE EXCEPTION 'Acesso negado'; END IF;
  IF p_user_id = auth.uid() THEN RAISE EXCEPTION 'Você não pode remover a si mesmo'; END IF;
  DELETE FROM auth.users WHERE id = p_user_id;
END;
$$;


--
-- Name: admin_resetar_senha(uuid, text); Type: FUNCTION; Schema: artes; Owner: -
--

CREATE FUNCTION artes.admin_resetar_senha(p_user_id uuid, p_nova_senha text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'artes', 'auth', 'extensions'
    AS $$
BEGIN
  IF NOT artes.is_admin() THEN RAISE EXCEPTION 'Acesso negado'; END IF;
  IF p_nova_senha IS NULL OR length(p_nova_senha) < 6 THEN RAISE EXCEPTION 'Senha precisa ter no mínimo 6 caracteres'; END IF;
  UPDATE auth.users
  SET encrypted_password = extensions.crypt(p_nova_senha, extensions.gen_salt('bf')),
      updated_at = now()
  WHERE id = p_user_id;
END;
$$;


--
-- Name: garantir_auth_tokens_nao_null(); Type: FUNCTION; Schema: artes; Owner: -
--

CREATE FUNCTION artes.garantir_auth_tokens_nao_null() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'artes', 'auth', 'extensions'
    AS $$
BEGIN
  BEGIN
    NEW.confirmation_token := COALESCE(NEW.confirmation_token, '');
    NEW.recovery_token := COALESCE(NEW.recovery_token, '');
    NEW.email_change_token_new := COALESCE(NEW.email_change_token_new, '');
    NEW.email_change_token_current := COALESCE(NEW.email_change_token_current, '');
    NEW.email_change := COALESCE(NEW.email_change, '');
    NEW.phone_change := COALESCE(NEW.phone_change, '');
    NEW.phone_change_token := COALESCE(NEW.phone_change_token, '');
    NEW.reauthentication_token := COALESCE(NEW.reauthentication_token, '');
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO ops.trigger_error_log (fn, err_code, err_msg, ctx)
    VALUES ('artes.garantir_auth_tokens_nao_null', SQLSTATE, SQLERRM, jsonb_build_object('user_id', NEW.id));
  END;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION garantir_auth_tokens_nao_null(); Type: COMMENT; Schema: artes; Owner: -
--

COMMENT ON FUNCTION artes.garantir_auth_tokens_nao_null() IS 'Workaround para bug do GoTrue: campos token devem ser string vazia, nunca NULL. Sem isso, login retorna "Database error querying schema".';


--
-- Name: handle_new_auth_user(); Type: FUNCTION; Schema: artes; Owner: -
--

CREATE FUNCTION artes.handle_new_auth_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'artes'
    AS $$
DECLARE
  v_role TEXT;
  v_apps JSONB;
  v_pertence_artes BOOLEAN;
BEGIN
  BEGIN
    v_role := NEW.raw_user_meta_data->>'role';
    v_apps := COALESCE(NEW.raw_user_meta_data->'apps', '{}'::jsonb);
    v_pertence_artes := (
      COALESCE(v_role, '') IN ('admin','fechamento')
      OR (v_apps->>'artes')::boolean IS TRUE
      OR (v_apps->>'fechamento')::boolean IS TRUE
      OR (v_apps->>'atendimento')::boolean IS TRUE
    );
    IF NOT v_pertence_artes THEN
      RETURN NEW;
    END IF;
    IF v_role IS NULL OR v_role NOT IN ('admin','fechamento') THEN
      v_role := 'fechamento';
    END IF;
    INSERT INTO artes.usuarios (user_id, email, nome, role, ativo)
    VALUES (NEW.id, NEW.email, COALESCE(NEW.raw_user_meta_data->>'nome', split_part(NEW.email, '@', 1)), v_role, TRUE)
    ON CONFLICT (user_id) DO NOTHING;
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO ops.trigger_error_log (fn, err_code, err_msg, ctx)
    VALUES ('artes.handle_new_auth_user', SQLSTATE, SQLERRM, jsonb_build_object('user_id', NEW.id, 'email', NEW.email));
  END;
  RETURN NEW;
END;
$$;


--
-- Name: is_admin(); Type: FUNCTION; Schema: artes; Owner: -
--

CREATE FUNCTION artes.is_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'artes'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM artes.usuarios
    WHERE user_id = auth.uid()
      AND role = 'admin'
      AND ativo = TRUE
  );
$$;


--
-- Name: listar_pedidos_novos(timestamp with time zone); Type: FUNCTION; Schema: artes; Owner: -
--

CREATE FUNCTION artes.listar_pedidos_novos(desde timestamp with time zone) RETURNS TABLE(id bigint, pedido text, empresa text, cliente text, produto text, cor text, qtd_pedido numeric, tipo_gravacao text, data_entrega date, prioridade text, ano integer, mes integer, criado_em timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'vendas', 'artes'
    AS $$
  SELECT
    oc.id, oc.pedido, oc.empresa, oc.cliente, oc.produto, oc.cor,
    oc.qtd_pedido, oc.tipo_gravacao, oc.data_entrega, oc.prioridade,
    oc.ano, oc.mes, oc.criado_em
  FROM vendas.ordens_compra oc
  WHERE oc.criado_em >= desde
    AND oc.excluido_em IS NULL
    AND (
      oc.ano > EXTRACT(YEAR FROM now())::integer
      OR (oc.ano = EXTRACT(YEAR FROM now())::integer 
          AND oc.mes >= EXTRACT(MONTH FROM now())::integer)
    )
  ORDER BY oc.criado_em DESC
  LIMIT 20;
$$;


--
-- Name: me(); Type: FUNCTION; Schema: artes; Owner: -
--

CREATE FUNCTION artes.me() RETURNS TABLE(user_id uuid, email text, nome text, role text, ativo boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'artes', 'auth'
    AS $$
DECLARE
  v_uid uuid;
  v_sub text;
BEGIN
  BEGIN v_uid := auth.uid(); EXCEPTION WHEN OTHERS THEN v_uid := NULL; END;
  IF v_uid IS NULL OR v_uid = '00000000-0000-0000-0000-000000000000'::uuid THEN
    v_sub := current_setting('request.jwt.claim.sub', true);
    IF v_sub IS NOT NULL AND v_sub <> '' THEN v_uid := v_sub::uuid; END IF;
  END IF;
  IF v_uid IS NULL THEN
    BEGIN
      v_sub := (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub');
      IF v_sub IS NOT NULL THEN v_uid := v_sub::uuid; END IF;
    EXCEPTION WHEN OTHERS THEN v_uid := NULL; END;
  END IF;
  IF v_uid IS NULL THEN RETURN; END IF;

  RETURN QUERY
  SELECT u.user_id, u.email, u.nome, u.role, u.ativo
  FROM artes.usuarios u
  WHERE u.user_id = v_uid;
END;
$$;


--
-- Name: notificar_bitrix_fechamento_concluido(); Type: FUNCTION; Schema: artes; Owner: -
--

CREATE FUNCTION artes.notificar_bitrix_fechamento_concluido() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'artes', 'net'
    AS $$
DECLARE
  v_disparar boolean := false;
  v_bitrix_user_id integer;
  v_responsavel_nome text;
BEGIN
  -- Guardrail 1: não envia se já enviou antes
  IF NEW.enviado_bitrix_em IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- Guardrail 2: precisa estar CONCLUIDO
  IF NEW.status IS DISTINCT FROM 'CONCLUIDO' THEN
    RETURN NEW;
  END IF;

  -- Guardrail 3: precisa ter arquivo anexado
  IF NEW.arquivo_url IS NULL AND NEW.arquivo_path IS NULL THEN
    RETURN NEW;
  END IF;

  -- Detecta transição
  IF TG_OP = 'INSERT' THEN
    v_disparar := true;
  ELSIF TG_OP = 'UPDATE' THEN
    IF OLD.status IS DISTINCT FROM 'CONCLUIDO' THEN
      v_disparar := true;
    ELSIF (OLD.arquivo_url IS NULL AND OLD.arquivo_path IS NULL) THEN
      v_disparar := true;
    END IF;
  END IF;

  IF NOT v_disparar THEN
    RETURN NEW;
  END IF;

  -- Busca bitrix_user_id do responsável (match pelo nome)
  IF NEW.responsavel IS NOT NULL THEN
    SELECT u.bitrix_user_id, u.nome
      INTO v_bitrix_user_id, v_responsavel_nome
    FROM artes.usuarios u
    WHERE LOWER(TRIM(u.nome)) = LOWER(TRIM(NEW.responsavel))
      AND u.ativo = true
      AND u.bitrix_user_id IS NOT NULL
    LIMIT 1;
  END IF;

  -- Fallback: usa o nome do fechamento mesmo se não achou bitrix_user_id
  IF v_responsavel_nome IS NULL THEN
    v_responsavel_nome := COALESCE(NEW.responsavel, 'Time de Artes');
  END IF;

  -- Dispara webhook com fechamento_id + bitrix_user_id + nome
  BEGIN
    PERFORM net.http_post(
      url := 'https://webhook.atomicabr.com.br/webhook/artes-fechamento-concluido',
      body := jsonb_build_object(
        'fechamento_id', NEW.id,
        'bitrix_user_id', v_bitrix_user_id,
        'responsavel_nome', v_responsavel_nome
      ),
      headers := jsonb_build_object('Content-Type', 'application/json'),
      timeout_milliseconds := 5000
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING '[notificar_bitrix_fechamento] Erro: %', SQLERRM;
  END;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION notificar_bitrix_fechamento_concluido(); Type: COMMENT; Schema: artes; Owner: -
--

COMMENT ON FUNCTION artes.notificar_bitrix_fechamento_concluido() IS 'Trigger AFTER INSERT/UPDATE em artes.fechamentos. Envia fechamento_id + bitrix_user_id do responsável pro webhook do n8n. Idempotente (enviado_bitrix_em).';


--
-- Name: notificar_bitrix_novo_pedido(); Type: FUNCTION; Schema: artes; Owner: -
--

CREATE FUNCTION artes.notificar_bitrix_novo_pedido() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'artes', 'net'
    AS $$
BEGIN
  -- Guardrails: ignora pedidos excluídos ou re-importações antigas
  IF NEW.excluido_em IS NOT NULL THEN
    RETURN NEW;
  END IF;
  
  -- Só notifica pedidos criados há menos de 6h (evita notificar em re-imports massivos)
  IF NEW.criado_em IS NULL OR NEW.criado_em < (now() - interval '6 hours') THEN
    RETURN NEW;
  END IF;
  
  -- Só notifica pedidos do mês atual ou futuro
  IF NEW.ano IS NOT NULL AND NEW.mes IS NOT NULL THEN
    IF NEW.ano < EXTRACT(YEAR FROM now())::integer 
       OR (NEW.ano = EXTRACT(YEAR FROM now())::integer 
           AND NEW.mes < EXTRACT(MONTH FROM now())::integer) THEN
      RETURN NEW;
    END IF;
  END IF;
  
  -- Dispara webhook async (pg_net retorna request_id, não bloqueia o INSERT)
  -- Se der erro, NÃO bloqueia o INSERT — só registra no log do pg_net
  BEGIN
    PERFORM net.http_post(
      url := 'https://webhook.atomicabr.com.br/webhook/artes-novo-pedido',
      body := jsonb_build_object('pedido_id', NEW.id),
      headers := jsonb_build_object('Content-Type', 'application/json'),
      timeout_milliseconds := 5000
    );
  EXCEPTION WHEN OTHERS THEN
    -- Loga mas não falha o INSERT
    RAISE WARNING '[notificar_bitrix] Erro ao chamar webhook: %', SQLERRM;
  END;
  
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION notificar_bitrix_novo_pedido(); Type: COMMENT; Schema: artes; Owner: -
--

COMMENT ON FUNCTION artes.notificar_bitrix_novo_pedido() IS 'Trigger AFTER INSERT em vendas.ordens_compra que chama webhook n8n para notificar usuários ativos via Bitrix24';


--
-- Name: fechamentos; Type: TABLE; Schema: artes; Owner: -
--

CREATE TABLE artes.fechamentos (
    id bigint NOT NULL,
    ordem_compra_id bigint NOT NULL,
    status text DEFAULT 'NA_FILA'::text NOT NULL,
    motivo_pendencia text,
    arquivo_url text,
    arquivo_tipo text,
    responsavel text,
    iniciado_em timestamp with time zone,
    concluido_em timestamp with time zone,
    enviado_bitrix_em timestamp with time zone,
    bitrix_chat_msg_id text,
    observacoes text,
    criado_em timestamp with time zone DEFAULT now() NOT NULL,
    atualizado_em timestamp with time zone DEFAULT now() NOT NULL,
    arquivo_path text,
    arquivo_nome text,
    arquivo_tamanho bigint,
    CONSTRAINT arte_fechamentos_arquivo_tipo_check CHECK (((arquivo_tipo = ANY (ARRAY['PNG'::text, 'COREL'::text])) OR (arquivo_tipo IS NULL))),
    CONSTRAINT arte_fechamentos_status_check CHECK ((status = ANY (ARRAY['NA_FILA'::text, 'INICIADO'::text, 'CONCLUIDO'::text, 'PENDENTE'::text])))
);


--
-- Name: TABLE fechamentos; Type: COMMENT; Schema: artes; Owner: -
--

COMMENT ON TABLE artes.fechamentos IS 'Controle de fechamento de artes. Vinculado 1:1 com vendas.ordens_compra(id)';


--
-- Name: salvar_fechamento_completo(bigint, text, text, text, text, text, text, text, text, bigint); Type: FUNCTION; Schema: artes; Owner: -
--

CREATE FUNCTION artes.salvar_fechamento_completo(p_ordem_compra_id bigint, p_status text DEFAULT NULL::text, p_responsavel text DEFAULT NULL::text, p_motivo_pendencia text DEFAULT NULL::text, p_observacoes text DEFAULT NULL::text, p_arquivo_url text DEFAULT NULL::text, p_arquivo_path text DEFAULT NULL::text, p_arquivo_nome text DEFAULT NULL::text, p_arquivo_tipo text DEFAULT NULL::text, p_arquivo_tamanho bigint DEFAULT NULL::bigint) RETURNS artes.fechamentos
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'artes', 'vendas'
    AS $$
DECLARE
  v_result artes.fechamentos;
  v_existe boolean;
  v_status_atual text;
  v_status_final text;
BEGIN
  -- Validações
  IF p_ordem_compra_id IS NULL THEN
    RAISE EXCEPTION 'ordem_compra_id obrigatório';
  END IF;

  IF p_status = 'PENDENTE' AND COALESCE(TRIM(p_motivo_pendencia), '') = '' THEN
    RAISE EXCEPTION 'Motivo de pendência é obrigatório quando status=PENDENTE';
  END IF;

  IF p_arquivo_tipo IS NOT NULL AND p_arquivo_tipo NOT IN ('PNG', 'COREL') THEN
    RAISE EXCEPTION 'arquivo_tipo inválido: %', p_arquivo_tipo;
  END IF;

  -- Verifica se já existe fechamento
  SELECT status INTO v_status_atual
  FROM artes.fechamentos
  WHERE ordem_compra_id = p_ordem_compra_id;

  v_existe := FOUND;
  v_status_final := COALESCE(p_status, v_status_atual, 'NA_FILA');

  IF NOT v_existe THEN
    -- INSERT
    INSERT INTO artes.fechamentos (
      ordem_compra_id, status, responsavel, motivo_pendencia, observacoes,
      arquivo_url, arquivo_path, arquivo_nome, arquivo_tipo, arquivo_tamanho,
      iniciado_em, concluido_em, criado_em, atualizado_em
    ) VALUES (
      p_ordem_compra_id,
      v_status_final,
      p_responsavel,
      CASE WHEN v_status_final = 'PENDENTE' THEN p_motivo_pendencia ELSE NULL END,
      p_observacoes,
      p_arquivo_url, p_arquivo_path, p_arquivo_nome, p_arquivo_tipo, p_arquivo_tamanho,
      CASE WHEN v_status_final IN ('INICIADO','CONCLUIDO') THEN now() ELSE NULL END,
      CASE WHEN v_status_final = 'CONCLUIDO' THEN now() ELSE NULL END,
      now(), now()
    )
    RETURNING * INTO v_result;
  ELSE
    -- UPDATE atômico (todos os campos de uma vez → trigger dispara 1x só)
    UPDATE artes.fechamentos SET
      status = v_status_final,
      responsavel = COALESCE(p_responsavel, responsavel),
      motivo_pendencia = CASE 
        WHEN v_status_final = 'PENDENTE' THEN COALESCE(p_motivo_pendencia, motivo_pendencia)
        ELSE NULL 
      END,
      observacoes = COALESCE(p_observacoes, observacoes),
      arquivo_url = COALESCE(p_arquivo_url, arquivo_url),
      arquivo_path = COALESCE(p_arquivo_path, arquivo_path),
      arquivo_nome = COALESCE(p_arquivo_nome, arquivo_nome),
      arquivo_tipo = COALESCE(p_arquivo_tipo, arquivo_tipo),
      arquivo_tamanho = COALESCE(p_arquivo_tamanho, arquivo_tamanho),
      iniciado_em = CASE 
        WHEN v_status_final IN ('INICIADO','CONCLUIDO') AND iniciado_em IS NULL THEN now()
        ELSE iniciado_em 
      END,
      concluido_em = CASE 
        WHEN v_status_final = 'CONCLUIDO' AND concluido_em IS NULL THEN now()
        WHEN v_status_final != 'CONCLUIDO' THEN NULL
        ELSE concluido_em 
      END,
      atualizado_em = now()
    WHERE ordem_compra_id = p_ordem_compra_id
    RETURNING * INTO v_result;
  END IF;

  RETURN v_result;
END;
$$;


--
-- Name: FUNCTION salvar_fechamento_completo(p_ordem_compra_id bigint, p_status text, p_responsavel text, p_motivo_pendencia text, p_observacoes text, p_arquivo_url text, p_arquivo_path text, p_arquivo_nome text, p_arquivo_tipo text, p_arquivo_tamanho bigint); Type: COMMENT; Schema: artes; Owner: -
--

COMMENT ON FUNCTION artes.salvar_fechamento_completo(p_ordem_compra_id bigint, p_status text, p_responsavel text, p_motivo_pendencia text, p_observacoes text, p_arquivo_url text, p_arquivo_path text, p_arquivo_nome text, p_arquivo_tipo text, p_arquivo_tamanho bigint) IS 'UPSERT atômico do fechamento (status + arquivo no MESMO UPDATE). Garante trigger Bitrix24 dispara 1x só.';


--
-- Name: set_fechamento(bigint, text, text, text, text); Type: FUNCTION; Schema: artes; Owner: -
--

CREATE FUNCTION artes.set_fechamento(p_ordem_compra_id bigint, p_status text, p_motivo text DEFAULT NULL::text, p_responsavel text DEFAULT NULL::text, p_observacoes text DEFAULT NULL::text) RETURNS artes.fechamentos
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'artes'
    AS $$
DECLARE
  rec artes.fechamentos;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM artes.usuarios WHERE user_id = auth.uid() AND ativo) THEN
    RAISE EXCEPTION 'Acesso negado';
  END IF;
  IF p_status NOT IN ('NA_FILA','INICIADO','PENDENTE','CONCLUIDO') THEN
    RAISE EXCEPTION 'Status inválido: %', p_status;
  END IF;
  IF p_status = 'PENDENTE' AND (p_motivo IS NULL OR length(trim(p_motivo)) = 0) THEN
    RAISE EXCEPTION 'Motivo obrigatório para PENDENTE';
  END IF;

  INSERT INTO artes.fechamentos AS af (
    ordem_compra_id, status, motivo_pendencia, responsavel, observacoes,
    iniciado_em, concluido_em, atualizado_em
  ) VALUES (
    p_ordem_compra_id, p_status,
    CASE WHEN p_status = 'PENDENTE' THEN p_motivo ELSE NULL END,
    p_responsavel, p_observacoes,
    CASE WHEN p_status = 'INICIADO' THEN now() END,
    CASE WHEN p_status = 'CONCLUIDO' THEN now() END,
    now()
  )
  ON CONFLICT (ordem_compra_id) DO UPDATE
  SET status = EXCLUDED.status,
      motivo_pendencia = CASE WHEN EXCLUDED.status = 'PENDENTE' THEN EXCLUDED.motivo_pendencia ELSE NULL END,
      responsavel = COALESCE(EXCLUDED.responsavel, af.responsavel),
      observacoes = COALESCE(EXCLUDED.observacoes, af.observacoes),
      iniciado_em = CASE WHEN EXCLUDED.status = 'INICIADO' AND af.iniciado_em IS NULL THEN now() ELSE af.iniciado_em END,
      concluido_em = CASE WHEN EXCLUDED.status = 'CONCLUIDO' THEN now()
                          WHEN EXCLUDED.status <> 'CONCLUIDO' THEN NULL
                          ELSE af.concluido_em END,
      atualizado_em = now()
  RETURNING * INTO rec;
  RETURN rec;
END;
$$;


--
-- Name: set_fechamento_arquivo(bigint, text, text, text, text, bigint); Type: FUNCTION; Schema: artes; Owner: -
--

CREATE FUNCTION artes.set_fechamento_arquivo(p_ordem_compra_id bigint, p_arquivo_url text, p_arquivo_path text, p_arquivo_tipo text, p_arquivo_nome text DEFAULT NULL::text, p_arquivo_tamanho bigint DEFAULT NULL::bigint) RETURNS artes.fechamentos
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'artes'
    AS $$
DECLARE rec artes.fechamentos;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM artes.usuarios WHERE user_id = auth.uid() AND ativo) THEN
    RAISE EXCEPTION 'Acesso negado';
  END IF;
  IF p_arquivo_tipo NOT IN ('PNG','COREL') THEN
    RAISE EXCEPTION 'Tipo inválido (use PNG ou COREL)';
  END IF;

  INSERT INTO artes.fechamentos AS af (
    ordem_compra_id, status, arquivo_url, arquivo_path, arquivo_tipo,
    arquivo_nome, arquivo_tamanho, atualizado_em
  ) VALUES (
    p_ordem_compra_id, 'INICIADO', p_arquivo_url, p_arquivo_path, p_arquivo_tipo,
    p_arquivo_nome, p_arquivo_tamanho, now()
  )
  ON CONFLICT (ordem_compra_id) DO UPDATE
  SET arquivo_url = EXCLUDED.arquivo_url,
      arquivo_path = EXCLUDED.arquivo_path,
      arquivo_tipo = EXCLUDED.arquivo_tipo,
      arquivo_nome = COALESCE(EXCLUDED.arquivo_nome, af.arquivo_nome),
      arquivo_tamanho = COALESCE(EXCLUDED.arquivo_tamanho, af.arquivo_tamanho),
      atualizado_em = now()
  RETURNING * INTO rec;
  RETURN rec;
END;
$$;


