--
-- Name: fn_audit_rmq_durability_risk(interval); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_audit_rmq_durability_risk(p_window interval DEFAULT '24:00:00'::interval) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'evo'
    AS $$
DECLARE
  v_health_gaps      jsonb;
  v_total_dlq        bigint := 0;
  v_result           jsonb;
BEGIN
  SELECT jsonb_agg(jsonb_build_object(
    'gap_start',    prev_check,
    'gap_end',      this_check,
    'gap_minutes',  gap_minutes
  ) ORDER BY gap_minutes DESC)
  INTO v_health_gaps
  FROM (
    SELECT
      LAG(created_at) OVER (ORDER BY created_at) AS prev_check,
      created_at                                  AS this_check,
      EXTRACT(EPOCH FROM (created_at - LAG(created_at) OVER (ORDER BY created_at))) / 60 AS gap_minutes
    FROM evo.evolution_health_logs
    WHERE created_at >= now() - p_window
  ) t
  WHERE gap_minutes > 10
  LIMIT 5;

  SELECT COUNT(*) INTO v_total_dlq
  FROM evo.evolution_webhook_dlq
  WHERE created_at >= now() - p_window;

  RETURN jsonb_build_object(
    'audited_at',             now(),
    'window',                 p_window,
    'health_log_gaps_found',  COALESCE(jsonb_array_length(v_health_gaps), 0),
    'health_log_gaps',        COALESCE(v_health_gaps, '[]'::jsonb),
    'dlq_entries_in_window',  v_total_dlq,
    'durability_risk',        CASE
                                WHEN jsonb_array_length(COALESCE(v_health_gaps,'[]'::jsonb)) > 0
                                  AND v_total_dlq > 10
                                THEN 'HIGH — health gap + DLQ spike suggests non-durable queue loss'
                                WHEN jsonb_array_length(COALESCE(v_health_gaps,'[]'::jsonb)) > 0
                                THEN 'MEDIUM — health gap detected; verify queue durable=true'
                                ELSE 'LOW — no health gaps in window'
                              END,
    'fix_action',             'Set durable=true and deliveryMode=2 (persistent) on all RabbitMQ queues; '
                              || 'verify with: rabbitmqctl list_queues name durable'
  );
END;
$$;


--
-- Name: FUNCTION fn_audit_rmq_durability_risk(p_window interval); Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON FUNCTION evo.fn_audit_rmq_durability_risk(p_window interval) IS 'E8-04: Audits RabbitMQ durability risk by correlating health log gaps (possible broker restarts) with DLQ spikes. Infers risk from DB-side signals. Root fix: set durable=true + deliveryMode=2 on all queues.';


--
-- Name: fn_auto_assign_contact(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_auto_assign_contact() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo'
    AS $$
DECLARE v_connection_id uuid; v_agent uuid;
BEGIN
  BEGIN
    SELECT wc.id INTO v_connection_id FROM public.whatsapp_connections wc
    WHERE wc.instance_name = NEW.instance_name::text AND wc.is_active = true
    ORDER BY wc.last_connected_at DESC NULLS LAST LIMIT 1;
    SELECT r.agent_id INTO v_agent FROM public.client_wallet_rules r
    WHERE r.is_active = true AND (r.whatsapp_connection_id IS NULL OR r.whatsapp_connection_id = v_connection_id)
    ORDER BY r.priority DESC, r.created_at ASC LIMIT 1;
    IF v_agent IS NOT NULL THEN NEW.assigned_to := v_agent::text; END IF;
  EXCEPTION WHEN OTHERS THEN NULL;
  END;
  RETURN NEW;
END $$;


--
-- Name: FUNCTION fn_auto_assign_contact(); Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON FUNCTION evo.fn_auto_assign_contact() IS 'Paridade Lovable (auto_assign_contact) adaptada: resolve conexão via instance_name; carteira de clientes (client_wallet_rules). Exception-safe: nunca bloqueia ingestão.';


--
-- Name: fn_auto_create_next_partitions(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_auto_create_next_partitions() RETURNS text[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo'
    AS $$
DECLARE
  v_results TEXT[] := '{}';
  v_next      DATE := date_trunc('month', NOW() + INTERVAL '1 month');
  v_next_next DATE := date_trunc('month', NOW() + INTERVAL '2 months');
  v_result    TEXT;
BEGIN
  SELECT evo.fn_create_monthly_partition('evo','evolution_webhook_events_v2', EXTRACT(YEAR FROM v_next)::INT, EXTRACT(MONTH FROM v_next)::INT) INTO v_result;
  v_results := v_results || v_result;
  SELECT evo.fn_create_monthly_partition('evo','evolution_webhook_events_v2', EXTRACT(YEAR FROM v_next_next)::INT, EXTRACT(MONTH FROM v_next_next)::INT) INTO v_result;
  v_results := v_results || v_result;
  RETURN v_results;
END;
$$;


--
-- Name: FUNCTION fn_auto_create_next_partitions(); Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON FUNCTION evo.fn_auto_create_next_partitions() IS 'Cria automaticamente as partições dos próximos 2 meses. Chamar via pg_cron no dia 1 de cada mês.';


--
-- Name: fn_block_internal_media_url(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_block_internal_media_url() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_url    text;
  v_pattern text;
  -- APENAS padrões que o fn_rewrite_media_url NÃO consegue corrigir:
  -- localhost, 127.0.0.1, 0.0.0.0 = hostnames arbitrários de máquina local
  -- Não inclui 'kong:' porque fn_rewrite_media_url converte kong → public URL
  v_irrecoverable_patterns text[] := ARRAY[
    'http://localhost',
    'http://127.0.0.1',
    'http://0.0.0.0',
    '://localhost:',
    '://127.0.0.1:',
    '://0.0.0.0:'
  ];
BEGIN
  -- Determinar a URL a verificar baseado na tabela
  IF TG_TABLE_NAME LIKE 'evolution_messages%' THEN
    v_url := NEW.media_url;
  ELSIF TG_TABLE_NAME = 'evolution_media' THEN
    v_url := NEW.storage_url;
  ELSIF TG_TABLE_NAME = 'evolution_contacts' THEN
    v_url := NEW.profile_picture_url;
  END IF;

  IF v_url IS NOT NULL AND v_url <> '' THEN
    FOREACH v_pattern IN ARRAY v_irrecoverable_patterns LOOP
      IF v_url ILIKE ('%' || v_pattern || '%') THEN
        RAISE EXCEPTION '[ZAPP-SECURITY] URL localhost/loopback irrecuperável em %.%: "%" (padrão: "%")',
          TG_TABLE_SCHEMA, TG_TABLE_NAME, v_url, v_pattern
          USING ERRCODE = 'check_violation';
      END IF;
    END LOOP;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_blockers_auto_detect(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_blockers_auto_detect() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo'
    AS $$
DECLARE
  v_e301_likely_fixed BOOLEAN;
  v_e804_evidence JSONB;
  v_e801_evidence JSONB;
  v_open_risk INT;
BEGIN
  SELECT (MAX(created_at) > NOW()-INTERVAL '30 minutes') INTO v_e301_likely_fixed
  FROM evo.evolution_webhook_events_v2
  WHERE event_type IN ('messages.upsert','messages.update') AND status='processed';

  SELECT jsonb_build_object(
    'hours_since_restore', ROUND(EXTRACT(EPOCH FROM (NOW()-'2026-07-10T16:43:54+00'::TIMESTAMPTZ))/3600,1),
    'events_since_restore', COUNT(*),
    'no_gap_detected', (MAX(created_at) > NOW()-INTERVAL '30 minutes')
  ) INTO v_e804_evidence
  FROM evo.evolution_webhook_events_v2
  WHERE created_at >= '2026-07-10T16:43:54+00'::TIMESTAMPTZ;

  SELECT jsonb_build_object(
    'total_events_1h', COUNT(*),
    'distinct_events_1h', COUNT(DISTINCT (payload->>'key')::TEXT),
    'duplicates_detected', COUNT(*) - COUNT(DISTINCT (payload->>'key')::TEXT)
  ) INTO v_e801_evidence
  FROM evo.evolution_webhook_events_v2
  WHERE created_at > NOW()-INTERVAL '1 hour';

  -- FIX: COALESCE para retornar 0 quando todos os cenarios estao done
  SELECT COALESCE(SUM(s.risk_score), 0) INTO v_open_risk
  FROM vps_scenarios s JOIN vps_scenario_status vs ON vs.scenario_id=s.id
  WHERE vs.status!='done';

  RETURN jsonb_build_object(
    'checked_at', NOW(),
    'open_risk', v_open_risk,
    'system_complete', (v_open_risk = 0),
    'E3-01', jsonb_build_object('likely_fixed_by_evidence', v_e301_likely_fixed, 'evidence', 'messages.upsert recent = n8n/consumer active'),
    'E1-01', jsonb_build_object('needs_portainer', TRUE, 'action', 'docker service ps evolution_evolution'),
    'E8-04', v_e804_evidence,
    'E8-01', v_e801_evidence,
    'E3-06', jsonb_build_object('needs_docker_secrets', TRUE, 'action', 'update panel stacks with new API key'),
    'E1-02', jsonb_build_object('check_healthcheck', TRUE, 'action', 'docker service ps evolution_evolution')
  );
END;
$$;


--
-- Name: FUNCTION fn_blockers_auto_detect(); Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON FUNCTION evo.fn_blockers_auto_detect() IS 'Auto-detecao do estado dos 6 blockers restantes via evidencias do banco. Chamada: SELECT evo.fn_blockers_auto_detect(). E3-01/E8-04/E8-01 podem ser auto-detectados; E1-01/E1-02/E3-06 requerem acao infra.';


