--

CREATE FUNCTION evo.fn_bootstrap_wpp2_instance(p_instance_id text, p_trigger text DEFAULT 'manual'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo'
    AS $$
DECLARE
  v_result jsonb;
  v_instance_name text := 'wpp2';
BEGIN
  -- Registrar o bootstrap (sem FK check - apenas registra a necessidade)
  INSERT INTO evo.evolution_bootstrap_log (
    instance_name, instance_id, triggered_by,
    settings_applied, rabbitmq_events_count, status, notes
  ) VALUES (
    v_instance_name,
    p_instance_id,
    p_trigger,
    '{"rejectCall":true,"msgCall":"Nao atendemos ligacoes neste numero. Envie sua mensagem por texto. Equipe Promo Brindes","groupsIgnore":false,"alwaysOnline":false,"readMessages":false,"readStatus":false,"syncFullHistory":false}'::jsonb,
    17,
    'registered',
    'Bootstrap function called - operator must apply settings via EVO API and RabbitMQ config'
  );

  v_result := jsonb_build_object(
    'status', 'registered',
    'instance_id', p_instance_id,
    'instance_name', v_instance_name,
    'trigger', p_trigger,
    'action_required', jsonb_build_array(
      jsonb_build_object('step', 1, 'action', 'Apply settings via EVO API: rejectCall=true, msgCall<=92chars'),
      jsonb_build_object('step', 2, 'action', 'Verify RabbitMQ 17 events in vhost=evolution for wpp2'),
      jsonb_build_object('step', 3, 'action', 'Confirm S3 bucket access zapp-whatsapp-media'),
      jsonb_build_object('step', 4, 'action', 'Send canary message to own number to test half-duplex')
    ),
    'timestamp', now()
  );

  RETURN v_result;
END;
$$;


