--
-- Name: fn_burnin_critical_alert_check(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_burnin_critical_alert_check() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo', 'zapp'
    AS $$
DECLARE
  v_window_start   timestamptz;
  v_burn_passed    boolean;
  v_crit_count     bigint;
  v_result         jsonb := '{}';
BEGIN
  SELECT burn_in_start, burn_in_passed
  INTO v_window_start, v_burn_passed
  FROM evo.evolution_burnin_tracker
  WHERE id = 1;

  IF v_burn_passed THEN
    RETURN jsonb_build_object('status', 'SKIP', 'detail', 'burn-in already passed');
  END IF;

  SELECT COUNT(*) INTO v_crit_count
  FROM evo.evolution_alerts
  WHERE severity = 'critical'
    AND created_at >= v_window_start
    AND (acknowledged IS NULL OR acknowledged = false)
    AND (resolved IS NULL OR resolved = false);

  v_result := jsonb_build_object(
    'status',          CASE WHEN v_crit_count > 0 THEN 'FAIL' ELSE 'PASS' END,
    'burn_in_start',   v_window_start,
    'elapsed_hours',   ROUND(EXTRACT(EPOCH FROM (now() - v_window_start)) / 3600, 1),
    'critical_alerts_since_start', v_crit_count
  );

  IF v_crit_count > 0 THEN
    UPDATE evo.evolution_burnin_tracker
    SET burn_in_start     = now(),
        last_reset_reason = format('E10-03: %s new critical alert(s) found at %s — 72h counter reset', v_crit_count, now()),
        updated_at        = now()
    WHERE id = 1;

    BEGIN
      INSERT INTO zapp.webhook_health_alerts
        (alert_type, severity, title, details, created_at)
      VALUES (
        'burnin_critical_alert',
        'critical',
        format('E10-03: %s new critical alert(s) during burn-in — 72h counter reset. Investigate before go-live.', v_crit_count),
        v_result,
        now()
      );
    EXCEPTION WHEN OTHERS THEN NULL; END;
  END IF;

  RETURN v_result;
END;
$$;


--
-- Name: fn_burnin_disconnection_check(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_burnin_disconnection_check() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo', 'zapp'
    AS $$
DECLARE
  v_window_start   timestamptz;
  v_burn_passed    boolean;
  v_result         jsonb := '{}';
  v_worst_duration integer;
  v_disc_count     bigint;
  v_long_disc      bigint;
  v_reset_needed   boolean := false;
  v_status         text;
BEGIN
  SELECT burn_in_start, burn_in_passed
  INTO v_window_start, v_burn_passed
  FROM evo.evolution_burnin_tracker
  WHERE id = 1;

  IF v_burn_passed THEN
    RETURN jsonb_build_object('status', 'SKIP', 'detail', 'burn-in already passed — monitor deactivated');
  END IF;

  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE duration_seconds > 30),
    MAX(duration_seconds)
  INTO v_disc_count, v_long_disc, v_worst_duration
  FROM evo.evolution_connection_history
  WHERE created_at >= v_window_start
    AND previous_state IN ('open', 'connected', 'connecting')
    AND state IN ('close', 'disconnected', 'refused');

  IF v_disc_count = 0 THEN
    v_status := 'PASS';
  ELSIF v_long_disc = 0 THEN
    v_status := 'PASS';
  ELSIF v_worst_duration > 120 THEN
    v_status := 'FAIL';
    v_reset_needed := true;
  ELSE
    v_status := 'WARN';
  END IF;

  v_result := jsonb_build_object(
    'status',         v_status,
    'burn_in_start',  v_window_start,
    'elapsed_hours',  ROUND(EXTRACT(EPOCH FROM (now() - v_window_start)) / 3600, 1),
    'disconnections_total',   v_disc_count,
    'disconnections_over_30s', v_long_disc,
    'worst_duration_seconds',  COALESCE(v_worst_duration, 0)
  );

  IF v_reset_needed THEN
    UPDATE evo.evolution_burnin_tracker
    SET burn_in_start     = now(),
        last_reset_reason = format('E10-02: disconnection %ss > 120s threshold at %s', v_worst_duration, now()),
        updated_at        = now()
    WHERE id = 1;

    BEGIN
      INSERT INTO zapp.webhook_health_alerts
        (alert_type, severity, title, details, created_at)
      VALUES (
        'burnin_disconnection',
        'critical',
        format('E10-02: Baileys disconnection %ss > 120s — burn-in counter reset', v_worst_duration),
        v_result,
        now()
      );
    EXCEPTION WHEN OTHERS THEN NULL; END;
  END IF;

  IF now() - v_window_start >= INTERVAL '72 hours' AND NOT v_reset_needed THEN
    UPDATE evo.evolution_burnin_tracker
    SET burn_in_passed = true, updated_at = now()
    WHERE id = 1;
    v_result := v_result || jsonb_build_object('burn_in_passed', true);
  END IF;

  RETURN v_result;
END;
$$;


--
-- Name: fn_burnin_monitor(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_burnin_monitor() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo'
    AS $$
DECLARE
  v_disc   jsonb;
  v_alert  jsonb;
BEGIN
  v_disc  := evo.fn_burnin_disconnection_check();
  v_alert := evo.fn_burnin_critical_alert_check();
  RETURN jsonb_build_object(
    'checked_at',           now(),
    'disconnection_check',  v_disc,
    'critical_alert_check', v_alert
  );
END;
$$;


--
-- Name: fn_cache_warmup_after_vacuum(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_cache_warmup_after_vacuum() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo'
    AS $$
DECLARE
  v_start timestamptz := now();
  v_counts jsonb := '{}';
  v_n bigint;
BEGIN
  -- Warm up the five key evo tables vacuumed nightly (02:01-02:21)
  SELECT COUNT(*) INTO v_n FROM evo.evolution_messages_wpp2;
  v_counts := v_counts || jsonb_build_object('evolution_messages_wpp2', v_n);

  SELECT COUNT(*) INTO v_n FROM evo.evolution_alerts WHERE resolved = false;
  v_counts := v_counts || jsonb_build_object('evolution_alerts_open', v_n);

  SELECT COUNT(*) INTO v_n FROM evo.evolution_contacts WHERE deleted_at IS NULL;
  v_counts := v_counts || jsonb_build_object('evolution_contacts_active', v_n);

  SELECT COUNT(*) INTO v_n FROM evo.evolution_bootstrap_log;
  v_counts := v_counts || jsonb_build_object('evolution_bootstrap_log', v_n);

  SELECT COUNT(*) INTO v_n FROM evo.evolution_connection_history;
  v_counts := v_counts || jsonb_build_object('evolution_connection_history', v_n);

  -- Also warm up zapp.evolution_messages (partitioned parent — forces partition map into cache)
  SELECT COUNT(*) INTO v_n FROM zapp.evolution_messages WHERE created_at > now() - interval '7 days';
  v_counts := v_counts || jsonb_build_object('evolution_messages_7d', v_n);

  RETURN jsonb_build_object(
    'warmed_at', v_start,
    'duration_ms', EXTRACT(EPOCH FROM (now() - v_start)) * 1000,
    'counts', v_counts
  );
END;
$$;


--
-- Name: FUNCTION fn_cache_warmup_after_vacuum(); Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON FUNCTION evo.fn_cache_warmup_after_vacuum() IS 'E10-08: Warm shared_buffers cache after nightly VACUUM run (02:01-02:21). Prevents first-query cold-cache degradation. Scheduled at 02:35 daily.';


--
-- Name: fn_check_guardian_alive(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_check_guardian_alive() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo', 'pg_catalog'
    AS $$
DECLARE
  v_last_hb timestamptz;
  v_gap_min int;
  v_dedup   int;
BEGIN
  -- Checar AMBAS as tabelas de heartbeat (guardian pode escrever em qualquer uma)
  SELECT GREATEST(
    (SELECT max(heartbeat_at) FROM evo.evolution_guardian_heartbeat WHERE service_name='swarm-task-guardian'),
    (SELECT max(heartbeat_at) FROM zapp.evolution_guardian_heartbeat WHERE service_name='swarm-task-guardian')
  ) INTO v_last_hb;

  v_gap_min := EXTRACT(EPOCH FROM (now() - COALESCE(v_last_hb, now() - interval '999 minutes')))::int / 60;

  IF v_gap_min > 15 THEN
    -- Dedup: nao inserir se ja existe alerta aberto nos ultimos 2h
    SELECT count(*) INTO v_dedup
    FROM evo.evolution_alerts
    WHERE alert_type='guardian_heartbeat_missing'
      AND (resolved_at IS NULL OR resolved_at > now() - interval '2 hours')
      AND created_at > now() - interval '2 hours';

    IF v_dedup = 0 THEN
      INSERT INTO evo.evolution_alerts (alert_type, severity, title, message)
      VALUES (
        'guardian_heartbeat_missing',
        'critical',
        'swarm-task-guardian sem heartbeat',
        format('Guardian sem heartbeat em AMBAS tabelas ha %s min (ultimo: %s). Verificar: docker service ps swarm-task-guardian_swarm-task-guardian. Se container rodando, verificar dblink password/config.',
               v_gap_min, COALESCE(v_last_hb::text, 'NUNCA'))
      );
      RAISE WARNING 'GUARDIAN ALERT: sem heartbeat ha % min (ultimo: %)', v_gap_min, v_last_hb;
    ELSE
      RAISE NOTICE 'Guardian alert ja existe, dedup ok (gap=% min)', v_gap_min;
    END IF;
  ELSE
    -- Guardian ok: resolver alertas antigos se gap voltou a zero
    UPDATE evo.evolution_alerts
    SET resolved_at = now()
    WHERE alert_type='guardian_heartbeat_missing'
      AND resolved_at IS NULL;
    RAISE NOTICE 'Guardian ok: gap=% min (ultimo hb: %)', v_gap_min, v_last_hb;
  END IF;
END;
$$;


--
-- Name: FUNCTION fn_check_guardian_alive(); Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON FUNCTION evo.fn_check_guardian_alive() IS 'Verificação periódica de saúde do swarm-task-guardian. 
Chamada a cada 10 min via pg_cron. 
Fonte de heartbeat: o guardian deve chamar este endpoint via pg_net periodicamente.';


--
-- Name: fn_cleanup_evolution_guardian_events(integer); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_cleanup_evolution_guardian_events(p_days_to_keep integer DEFAULT 7) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo'
    AS $$
DECLARE
  v_pwd text;
  v_conn text;
  v_result record;
BEGIN
  SELECT value INTO v_pwd FROM evo._secure_config WHERE key='evolution_pg_password';
  v_conn := 'host=10.0.1.48 port=5432 dbname=evolution user=postgres password='||v_pwd||' connect_timeout=5';

  SELECT * INTO v_result FROM dblink(
    v_conn,
    format(
      'WITH del AS (DELETE FROM _swarm_guardian_events WHERE detected_at < now()-interval ''%s days'' RETURNING detected_at) SELECT count(*) deleted FROM del',
      p_days_to_keep
    )
  ) AS t(deleted bigint);

  RETURN jsonb_build_object(
    'status','ok',
    'deleted', v_result.deleted,
    'kept_days', p_days_to_keep,
    'executed_at', now()
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('status','error','message',SQLERRM);
END;
$$;


--
-- Name: fn_cleanup_test_artifacts(boolean, integer); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_cleanup_test_artifacts(p_confirm boolean DEFAULT false, p_max_age_hours integer DEFAULT 2) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo'
    AS $$
DECLARE
  v_window       timestamptz := now() - (p_max_age_hours || ' hours')::interval;
  v_msgs_del     int := 0;
  v_log_del      int := 0;
  v_audit_del    int := 0;
  v_summary      jsonb;
  v_test_pattern text := '^([A-Z][0-9]{2}_|DIAG-|DRYRUN-)';
  v_log_pattern  text := '^(b[0-9]{2}[-_]|c[0-9]{2}[-_]|d[0-9]{2}[-_]|e[0-9]{2}[-_]|stress|regression)';
BEGIN
  -- 2026-07-11: alvo migrado _wpp2 → parent particionado evo.evolution_messages
  -- (limpa artefatos em TODAS as 23 partições de uma vez); patterns DIAG-/DRYRUN- adicionados.
  IF NOT p_confirm THEN
    v_summary := jsonb_build_object(
      'dry_run',     true,
      'safety_note', 'Patterns [A-Z][0-9]{2}_ / DIAG- / DRYRUN- cover test sessions. Real WhatsApp IDs never contain _ or these prefixes.',
      'would_delete', jsonb_build_object(
        'evolution_messages_all_partitions', (
          SELECT count(*) FROM evo.evolution_messages
          WHERE created_at > v_window AND message_id ~ v_test_pattern
        ),
        'bootstrap_log_test', (
          SELECT count(*) FROM evo.evolution_bootstrap_log
          WHERE created_at > v_window AND triggered_by ~ v_log_pattern
        ),
        'bootstrap_stale_no_event', (
          SELECT count(*) FROM evo.evolution_bootstrap_log bl
          WHERE bl.triggered_by='auto-connection-trigger'
            AND bl.status='registered'
            AND bl.created_at > v_window
            AND NOT EXISTS (
              SELECT 1 FROM evo.evolution_connection_history ch
              WHERE ch.instance_name='wpp2' AND ch.state='closed'
                AND ch.created_at BETWEEN bl.created_at - interval '30 sec'
                                       AND bl.created_at + interval '30 sec'
            )
        ),
        'canary_audit_entries', (
          SELECT count(*) FROM evo.evolution_audit_log
          WHERE created_at > v_window AND action='canary_filtered'
        )
      ),
      'window_hours', p_max_age_hours
    );
    RETURN v_summary;
  END IF;

  WITH del AS (
    DELETE FROM evo.evolution_messages
    WHERE created_at > v_window AND message_id ~ v_test_pattern
    RETURNING 1
  ) SELECT count(*) INTO v_msgs_del FROM del;

  WITH del AS (
    DELETE FROM evo.evolution_bootstrap_log
    WHERE created_at > v_window AND triggered_by ~ v_log_pattern
    RETURNING 1
  ) SELECT count(*) INTO v_log_del FROM del;

  WITH del AS (
    DELETE FROM evo.evolution_bootstrap_log bl
    WHERE bl.triggered_by='auto-connection-trigger'
      AND bl.status='registered'
      AND bl.created_at > v_window
      AND NOT EXISTS (
        SELECT 1 FROM evo.evolution_connection_history ch
        WHERE ch.instance_name='wpp2' AND ch.state='closed'
          AND ch.created_at BETWEEN bl.created_at - interval '30 sec'
                                 AND bl.created_at + interval '30 sec'
      )
    RETURNING 1
  ) SELECT count(*) + v_log_del INTO v_log_del FROM del;

  WITH del AS (
    DELETE FROM evo.evolution_audit_log
    WHERE created_at > v_window AND action='canary_filtered'
    RETURNING 1
  ) SELECT count(*) INTO v_audit_del FROM del;

  RETURN jsonb_build_object(
    'dry_run', false,
    'deleted', jsonb_build_object(
      'messages', v_msgs_del, 'bootstrap_log', v_log_del, 'audit_canary', v_audit_del
    ),
    'executed_at', now()
  );
END;
$$;


--
-- Name: fn_create_monthly_partition(text, text, integer, integer); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_create_monthly_partition(p_schema text, p_base_table text, p_year integer, p_month integer) RETURNS text
    LANGUAGE plpgsql
    AS $$ DECLARE v_part_name TEXT; v_from_date DATE; v_to_date DATE; v_conflicts BIGINT := 0; v_result TEXT; BEGIN v_part_name := format('%s_%s_%s', p_base_table, p_year, LPAD(p_month::TEXT,2,'0')); v_from_date := make_date(p_year, p_month, 1); v_to_date := v_from_date + INTERVAL '1 month'; IF EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relname=v_part_name AND n.nspname=p_schema) THEN RETURN format('SKIP ja existe: %I.%I', p_schema, v_part_name); END IF; IF EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relname=p_base_table||'_default' AND n.nspname=p_schema) THEN EXECUTE format('SELECT COUNT(*) FROM %I.%I WHERE created_at >= %L AND created_at < %L', p_schema, p_base_table||'_default', v_from_date, v_to_date) INTO v_conflicts; IF v_conflicts > 0 THEN RETURN format('WARN %s linhas na DEFAULT no range %s->%s', v_conflicts, v_from_date, v_to_date); END IF; END IF; BEGIN EXECUTE format('CREATE TABLE %I.%I PARTITION OF %I.%I FOR VALUES FROM (%L) TO (%L)', p_schema, v_part_name, p_schema, p_base_table, v_from_date::TEXT, v_to_date::TEXT); EXECUTE format('ALTER TABLE %I.%I ENABLE ROW LEVEL SECURITY', p_schema, v_part_name); EXECUTE format('CREATE POLICY service_role_all ON %I.%I AS PERMISSIVE FOR ALL TO service_role USING (true) WITH CHECK (true)', p_schema, v_part_name); EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON %I.%I (event_type, status, created_at DESC)', v_part_name||'_event_type_status_idx', p_schema, v_part_name); v_result := format('OK criada+RLS+idx: %I.%I', p_schema, v_part_name); RETURN v_result; EXCEPTION WHEN duplicate_table THEN RETURN format('SKIP race: %I.%I', p_schema, v_part_name); WHEN OTHERS THEN RETURN format('FAIL %s->%s: %s', v_from_date, v_to_date, SQLERRM); END; END; $$;


--
-- Name: FUNCTION fn_create_monthly_partition(p_schema text, p_base_table text, p_year integer, p_month integer); Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON FUNCTION evo.fn_create_monthly_partition(p_schema text, p_base_table text, p_year integer, p_month integer) IS 'v4 FINAL — Idempotente. Verifica DEFAULT antes de criar. EXCEPTION handler robusto. Sem false positives.';


--
-- Name: fn_detect_401_bursts(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_detect_401_bursts() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo', 'zapp'
    AS $$
DECLARE
  v_count_log      int := 0;
  v_count_ipwatch  int := 0;
  v_count_health   int := 0;
  v_total          int;
  v_ipwatch_total  bigint := 0;
  v_monitoring_gap boolean := true;
  v_already_burst  boolean;
  v_already_gap    boolean;
  v_already_hunt   boolean;
  v_alert_fired    boolean := false;
  v_gap_detail     text;
BEGIN
  SELECT count(*)::int INTO v_count_log
  FROM zapp.webhook_audit_log
  WHERE status_code = 401 AND created_at > now() - interval '15min';

  SELECT count(*)::int INTO v_count_health
  FROM zapp.webhook_health_alerts
  WHERE alert_type = 'sentry_401_feed' AND created_at > now() - interval '15min';

  v_total := v_count_log + v_count_ipwatch + v_count_health;

  v_gap_detail :=
    'BLIND: evolution_ip_watch removida em 2026-08-06 (fantasma, 0 linhas, sem trigger). ' ||
    'webhook_audit_log captures edge-fn rejections only, not Evolution API 401s. ' ||
    'Burst detection remains DB-blind until log pipeline is wired.';

  SELECT EXISTS(
    SELECT 1 FROM zapp.warroom_alerts
    WHERE source = 'fn_detect_401_bursts' AND alert_type = 'critical'
      AND created_at > now() - interval '30min'
  ) INTO v_already_burst;

  SELECT EXISTS(
    SELECT 1 FROM zapp.warroom_alerts
    WHERE source = 'fn_detect_401_bursts' AND alert_type = 'warning'
      AND created_at > now() - interval '6h'
  ) INTO v_already_gap;

  SELECT EXISTS(
    SELECT 1 FROM zapp.warroom_alerts
    WHERE source = 'fn_detect_401_bursts' AND alert_type = 'info'
      AND message LIKE '%stale_api_key_hunt%'
      AND created_at > now() - interval '24h'
  ) INTO v_already_hunt;

  IF v_total >= 3 AND NOT v_already_burst THEN
    INSERT INTO zapp.warroom_alerts (alert_type, title, message, source)
    VALUES (
      'critical',
      format('🚨 401 BURST: %s signals em 15min', v_total),
      format(
        'Sources: webhook_audit_log=%s | evolution_ip_watch=%s (removida 2026-08-06) | health_alerts=%s '
        '— Verificar imediatamente. Chave atual: vault evolution_api_key (md5 0d658c199f7945a2b960a0a22ab5efa6).',
        v_count_log, v_count_ipwatch, v_count_health
      ),
      'fn_detect_401_bursts'
    );
    v_alert_fired := true;

  ELSIF v_monitoring_gap AND NOT v_already_gap THEN
    INSERT INTO zapp.warroom_alerts (alert_type, title, message, source)
    VALUES (
      'warning',
      '⚠️ 401 DETECTION BLIND: pipeline VPS→DB inativo',
      'evo.evolution_ip_watch removida em 2026-08-06 (era fantasma: 0 linhas). ' ||
      'Ação: configurar Traefik access log → Supabase API. ' ||
      'Sentry recebe 401s (logpatch T3 corrigido em 2026-07-12).',
      'fn_detect_401_bursts'
    );
    v_alert_fired := true;
  END IF;

  IF NOT v_already_hunt THEN
    INSERT INTO zapp.warroom_alerts (alert_type, title, message, source)
    VALUES (
      'info',
      '🔍 OBS-2 stale_api_key_hunt: encontre o consumer com chave velha',
      'A Evolution API gera ~1 × 401 a cada 5 min de um consumer com apikey obsoleta. ' ||
      'Chave atual: vault evolution_api_key (md5 0d658c199f7945a2b960a0a22ab5efa6). ' ||
      'CHECKLIST: n8n credenciais → docker service env → secrets swarm → Sentry 401s. ' ||
      'Ref: AUDITORIA_EVO_API_2026-07-12.md OBS-2.',
      'fn_detect_401_bursts'
    );
    v_alert_fired := true;
  END IF;

  RETURN jsonb_build_object(
    'ok',             true,
    'count_15min',    v_total,
    'alert_fired',    v_alert_fired,
    'sources', jsonb_build_object(
      'webhook_audit_log_401',  v_count_log,
      'evolution_ip_watch_401', v_count_ipwatch,
      'health_alerts_401',      v_count_health
    ),
    'monitoring_gap',        v_monitoring_gap,
    'monitoring_gap_detail', v_gap_detail,
    'version', 'v4-no-ipwatch-2026-08-06'
  );
END $$;


--
-- Name: fn_detect_ack_loss_gap(interval, integer); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_detect_ack_loss_gap(p_window interval DEFAULT '00:30:00'::interval, p_dlq_threshold integer DEFAULT 5) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo', 'zapp'
    AS $$
DECLARE
  v_total_dlq_msg      bigint := 0;
  v_db_timeout_count   bigint := 0;
  v_db_error_count     bigint := 0;
  v_likely_lost_count  bigint := 0;
  v_retry_exhausted    bigint := 0;
  v_dlq_growth_rate    numeric;
  v_prev_window_count  bigint := 0;
  v_result             jsonb;
  v_status             text;
BEGIN
  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE failure_category = 'db_write_timeout'),
    COUNT(*) FILTER (WHERE failure_category IN ('db_write_timeout', 'db_write_error')),
    COUNT(*) FILTER (WHERE likely_lost),
    COUNT(*) FILTER (WHERE retry_exhausted)
  INTO
    v_total_dlq_msg,
    v_db_timeout_count,
    v_db_error_count,
    v_likely_lost_count,
    v_retry_exhausted
  FROM evo.v_ack_loss_candidates
  WHERE created_at >= now() - p_window;

  SELECT COUNT(*)
  INTO v_prev_window_count
  FROM evo.v_ack_loss_candidates
  WHERE created_at >= now() - (p_window * 2)
    AND created_at <  now() - p_window;

  v_dlq_growth_rate := CASE
    WHEN v_prev_window_count = 0 AND v_total_dlq_msg > 0 THEN 999.0
    WHEN v_prev_window_count = 0 THEN 0.0
    ELSE round(((v_total_dlq_msg::numeric / v_prev_window_count) - 1) * 100, 1)
  END;

  v_status := CASE
    WHEN v_likely_lost_count > 0 OR v_db_timeout_count >= p_dlq_threshold THEN 'CRITICAL'
    WHEN v_db_error_count > 0    OR v_total_dlq_msg > 0                   THEN 'WARN'
    ELSE 'OK'
  END;

  IF v_likely_lost_count > 0 THEN
    BEGIN
      INSERT INTO zapp.webhook_health_alerts
        (alert_type, severity, title, details, created_at)
      VALUES (
        'ack_loss_gap',
        'critical',
        format('E8-06: ACK-loss CRITICAL — %s likely-lost messages (ACKed, DB write failed, no retry)',
          v_likely_lost_count),
        jsonb_build_object(
          'likely_lost_count',    v_likely_lost_count,
          'db_timeout_count',     v_db_timeout_count,
          'db_error_count',       v_db_error_count,
          'retry_exhausted',      v_retry_exhausted,
          'total_dlq_msg',        v_total_dlq_msg,
          'window',               p_window,
          'dlq_growth_rate_pct',  v_dlq_growth_rate,
          'root_cause',           'Consumer ACKs RabbitMQ before Supabase INSERT confirmed',
          'fix_action',           'ACK only after INSERT returns success — consumer code change required'
        ),
        now()
      );
    EXCEPTION WHEN OTHERS THEN NULL; END;

  ELSIF v_db_timeout_count >= p_dlq_threshold THEN
    BEGIN
      INSERT INTO zapp.webhook_health_alerts
        (alert_type, severity, title, details, created_at)
      VALUES (
        'ack_loss_gap',
        'high',
        format('E8-06: ACK-loss WARN — %s DB-timeout DLQ entries in %s (threshold: %s)',
          v_db_timeout_count, p_window, p_dlq_threshold),
        jsonb_build_object(
          'db_timeout_count',     v_db_timeout_count,
          'db_error_count',       v_db_error_count,
          'total_dlq_msg',        v_total_dlq_msg,
          'window',               p_window,
          'dlq_growth_rate_pct',  v_dlq_growth_rate,
          'root_cause',           'Consumer ACKs RabbitMQ before Supabase INSERT confirmed',
          'fix_action',           'ACK only after INSERT returns success — consumer code change required'
        ),
        now()
      );
    EXCEPTION WHEN OTHERS THEN NULL; END;
  END IF;

  v_result := jsonb_build_object(
    'checked_at',           now(),
    'window',               p_window,
    'status',               v_status,
    'total_dlq_msg',        v_total_dlq_msg,
    'db_timeout_count',     v_db_timeout_count,
    'db_error_count',       v_db_error_count,
    'likely_lost_count',    v_likely_lost_count,
    'retry_exhausted',      v_retry_exhausted,
    'dlq_growth_rate_pct',  v_dlq_growth_rate,
    'threshold',            p_dlq_threshold,
    'root_cause',           'Consumer ACKs RabbitMQ before Supabase INSERT confirmed (at-most-once)',
    'fix_action',           'ACK only AFTER INSERT confirmed — consumer code change required'
  );

  RETURN v_result;
END;
$$;


--
-- Name: FUNCTION fn_detect_ack_loss_gap(p_window interval, p_dlq_threshold integer); Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON FUNCTION evo.fn_detect_ack_loss_gap(p_window interval, p_dlq_threshold integer) IS 'E8-06: Detects at-most-once delivery gap — messages ACKed to RabbitMQ before Supabase INSERT was confirmed. Analyzes evolution_webhook_dlq for message-type entries with DB-write failure patterns (timeout, connection refused, ECONNRESET). likely_lost_count > 0 = confirmed data loss. Root fix is consumer code. Scheduled every 5 minutes via pg_cron.';


--
-- Name: fn_detect_dedup_cap_failures(interval); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_detect_dedup_cap_failures(p_window interval DEFAULT '01:00:00'::interval) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo', 'zapp'
    AS $$
DECLARE
  v_dedup_threshold  CONSTANT int := 3;
  v_total_dupes      bigint := 0;
  v_total_dup_rows   bigint := 0;
  v_worst_offenders  jsonb;
  v_result           jsonb;
  v_status           text;
BEGIN
  SELECT
    COUNT(DISTINCT message_id),
    SUM(cnt) - COUNT(DISTINCT message_id)
  INTO v_total_dupes, v_total_dup_rows
  FROM (
    SELECT message_id, COUNT(*) AS cnt
    FROM evo.evolution_messages
    WHERE message_id IS NOT NULL
      AND created_at >= now() - p_window
    GROUP BY message_id
    HAVING COUNT(*) > 1
  ) t;

  SELECT jsonb_agg(jsonb_build_object(
    'message_id',  message_id,
    'count',       cnt,
    'first_seen',  first_seen,
    'last_seen',   last_seen
  ) ORDER BY cnt DESC)
  INTO v_worst_offenders
  FROM (
    SELECT
      message_id,
      COUNT(*)        AS cnt,
      MIN(created_at) AS first_seen,
      MAX(created_at) AS last_seen
    FROM evo.evolution_messages
    WHERE message_id IS NOT NULL
      AND created_at >= now() - p_window
    GROUP BY message_id
    HAVING COUNT(*) > 1
    ORDER BY cnt DESC
    LIMIT 5
  ) t;

  v_status := CASE
    WHEN v_total_dupes >= v_dedup_threshold THEN 'CRITICAL'
    WHEN v_total_dupes > 0                  THEN 'WARN'
    ELSE 'OK'
  END;

  IF v_status IN ('CRITICAL', 'WARN') THEN
    BEGIN
      INSERT INTO zapp.webhook_health_alerts
        (alert_type, severity, title, details, created_at)
      VALUES (
        'dedup_cap_failure',
        CASE WHEN v_status = 'CRITICAL' THEN 'critical' ELSE 'high' END,
        format('E8-01: Dedup failure — %s duplicate message_ids (%s extra rows) in %s',
          v_total_dupes, v_total_dup_rows, p_window),
        jsonb_build_object(
          'total_duplicate_ids', v_total_dupes,
          'total_extra_rows',    v_total_dup_rows,
          'window',              p_window,
          'worst_offenders',     COALESCE(v_worst_offenders, '[]'::jsonb),
          'root_cause',          'Consumer v2 Set has no TTL/max-size; grows until OOM or loses state on restart',
          'fix_action',          'Add LRU cap (max 10k entries) + TTL (5min) to consumer dedup Set'
        ),
        now()
      );
    EXCEPTION WHEN OTHERS THEN NULL; END;
  END IF;

  RETURN jsonb_build_object(
    'checked_at',          now(),
    'window',              p_window,
    'status',              v_status,
    'total_duplicate_ids', v_total_dupes,
    'total_extra_rows',    COALESCE(v_total_dup_rows, 0),
    'worst_offenders',     COALESCE(v_worst_offenders, '[]'::jsonb),
    'threshold',           v_dedup_threshold,
    'root_cause',          'Consumer v2 Set has no TTL/max-size cap',
    'fix_action',          'Add LRU cap + TTL to dedup Set, or enforce UNIQUE on evolution_messages.message_id'
  );
END;
$$;


--
-- Name: FUNCTION fn_detect_dedup_cap_failures(p_window interval); Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON FUNCTION evo.fn_detect_dedup_cap_failures(p_window interval) IS 'E8-01: Detects duplicate message_id entries in evolution_messages — proof that the consumer v2 dedup Set failed (no cap, no TTL, state lost on restart). WARN on first duplicate, CRITICAL when >= 3 duplicate IDs in window.';


--
-- Name: fn_detect_instance_recreate(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_detect_instance_recreate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo'
    AS $$
DECLARE
  v_instance_id text;
  v_cooldown_ok boolean;
  v_webhook_payload jsonb;
BEGIN
  IF NEW.instance_name != 'wpp2' THEN
    RETURN NEW;
  END IF;

  IF NEW.state NOT IN ('closed', 'disconnected', 'logout') THEN
    RETURN NEW;
  END IF;

  -- Cooldown 5min
  SELECT NOT EXISTS(
    SELECT 1 FROM evo.evolution_bootstrap_log
    WHERE instance_name = NEW.instance_name
      AND created_at > now() - interval '5 minutes'
      AND triggered_by = 'auto-connection-trigger'
  ) INTO v_cooldown_ok;

  IF NOT v_cooldown_ok THEN
    RETURN NEW;
  END IF;

  -- Buscar instanceId
  SELECT id::text INTO v_instance_id
  FROM evo.evolution_instance_credentials
  WHERE instance_name = NEW.instance_name AND is_active = true
  LIMIT 1;

  -- 1. Registrar diretamente no bootstrap_log (a ação crítica)
  INSERT INTO evo.evolution_bootstrap_log (
    instance_name, instance_id, triggered_by,
    settings_applied, rabbitmq_events_count, status, notes
  ) VALUES (
    NEW.instance_name,
    COALESCE(v_instance_id, 'unknown'),
    'auto-connection-trigger',
    NULL, NULL,
    'registered',
    format('Estado %s→%s detectado em %s. Verificar se instância foi recriada.',
           COALESCE(NEW.previous_state, 'unknown'), NEW.state, NEW.created_at)
  );

  -- 2. Chamar n8n webhook via pg_net para notificação externa
  v_webhook_payload := jsonb_build_object(
    'event', 'LOGOUT_INSTANCE',
    'instance', NEW.instance_name,
    'instanceId', COALESCE(v_instance_id, 'unknown'),
    'state', NEW.state,
    'previous_state', NEW.previous_state,
    'detected_at', NEW.created_at
  );

  PERFORM net.http_post(
    url := 'https://webhook.atomicabr.com.br/webhook/evolution-bootstrap-alert',
    body := v_webhook_payload,
    headers := '{"Content-Type":"application/json"}'::jsonb
  );

  RAISE WARNING 'Bootstrap Alert: wpp2 state→%. Bootstrap registered + n8n notified.', NEW.state;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Não falhar o INSERT principal por erro no webhook
  RAISE WARNING 'Bootstrap trigger error (non-fatal): %', SQLERRM;
  RETURN NEW;
END;
$$;


--
-- Name: fn_detect_spurious_closes(interval, interval); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_detect_spurious_closes(p_window interval DEFAULT '01:00:00'::interval, p_reconnect_window interval DEFAULT '00:00:30'::interval) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo', 'zapp'
    AS $$
DECLARE
  v_spurious_warn_pct     CONSTANT numeric := 70.0;
  v_spurious_critical_pct CONSTANT numeric := 90.0;
  v_min_count             CONSTANT int     := 5;
  v_total_disconnects  bigint := 0;
  v_spurious_count     bigint := 0;
  v_real_count         bigint := 0;
  v_spurious_rate      numeric := 0;
  v_top_offenders      jsonb;
  v_result             jsonb;
  v_status             text;
BEGIN
  WITH disconnects AS (
    SELECT
      instance_name,
      created_at AS disconnected_at,
      LEAD(state)       OVER (PARTITION BY instance_name ORDER BY created_at) AS next_state,
      LEAD(created_at)  OVER (PARTITION BY instance_name ORDER BY created_at) AS next_state_at
    FROM evo.evolution_connection_history
    WHERE state = 'disconnected'
      AND created_at >= now() - p_window
  )
  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE
      next_state IN ('connecting', 'connected')
      AND (next_state_at - disconnected_at) <= p_reconnect_window
    ),
    COUNT(*) FILTER (WHERE
      next_state IS NULL
      OR next_state NOT IN ('connecting', 'connected')
      OR (next_state_at - disconnected_at) > p_reconnect_window
    )
  INTO v_total_disconnects, v_spurious_count, v_real_count
  FROM disconnects
  WHERE next_state IS NOT NULL;
  IF v_total_disconnects > 0 THEN
    v_spurious_rate := round((v_spurious_count::numeric / v_total_disconnects) * 100, 1);
  END IF;
  WITH disconnects AS (
    SELECT
      instance_name,
      created_at AS disconnected_at,
      LEAD(state)       OVER (PARTITION BY instance_name ORDER BY created_at) AS next_state,
      LEAD(created_at)  OVER (PARTITION BY instance_name ORDER BY created_at) AS next_state_at
    FROM evo.evolution_connection_history
    WHERE state = 'disconnected'
      AND created_at >= now() - p_window
  ),
  classified AS (
    SELECT
      instance_name,
      CASE WHEN next_state IN ('connecting','connected')
             AND (next_state_at - disconnected_at) <= p_reconnect_window
           THEN true ELSE false END AS is_spurious
    FROM disconnects WHERE next_state IS NOT NULL
  )
  SELECT jsonb_agg(jsonb_build_object(
    'instance_name',   instance_name,
    'spurious_count',  spurious_count,
    'real_count',      real_count,
    'total',           spurious_count + real_count
  ) ORDER BY spurious_count DESC)
  INTO v_top_offenders
  FROM (
    SELECT
      instance_name,
      COUNT(*) FILTER (WHERE is_spurious)     AS spurious_count,
      COUNT(*) FILTER (WHERE NOT is_spurious)  AS real_count
    FROM classified
    GROUP BY instance_name
    HAVING COUNT(*) FILTER (WHERE is_spurious) > 0
    ORDER BY spurious_count DESC
    LIMIT 5
  ) t;
  v_status := CASE
    WHEN v_spurious_count >= v_min_count AND v_spurious_rate >= v_spurious_critical_pct THEN 'CRITICAL'
    WHEN v_spurious_count >= v_min_count AND v_spurious_rate >= v_spurious_warn_pct     THEN 'WARN'
    WHEN v_spurious_count > 0                                                           THEN 'INFO'
    ELSE 'OK'
  END;
  IF v_status = 'CRITICAL' THEN
    BEGIN
      INSERT INTO zapp.webhook_health_alerts
        (alert_type, severity, title, details, created_at)
      VALUES (
        'spurious_close_flood',
        'critical',
        format('E1-12: %s%% of connection closes are spurious (%s/%s) — n8n consumer filter REQUIRED',
          round(v_spurious_rate, 0), v_spurious_count, v_total_disconnects),
        jsonb_build_object(
          'spurious_count',        v_spurious_count,
          'real_count',            v_real_count,
          'total_disconnects',     v_total_disconnects,
          'spurious_rate_pct',     v_spurious_rate,
          'window',                p_window,
          'reconnect_window',      p_reconnect_window,
          'top_offenders',         COALESCE(v_top_offenders, '[]'::jsonb),
          'fix_action',            'Add filter in n8n consumer: skip connection.update type=close when next event is connecting/connected within 30s',
          'threshold_warn_pct',    v_spurious_warn_pct,
          'threshold_crit_pct',    v_spurious_critical_pct
        ),
        now()
      );
    EXCEPTION WHEN OTHERS THEN NULL; END;
  ELSIF v_status = 'WARN' THEN
    BEGIN
      INSERT INTO zapp.webhook_health_alerts
        (alert_type, severity, title, details, created_at)
      VALUES (
        'spurious_close_flood',
        'high',
        format('E1-12: %s%% of connection closes are spurious (%s/%s) — consider n8n consumer filter',
          round(v_spurious_rate, 0), v_spurious_count, v_total_disconnects),
        jsonb_build_object(
          'spurious_count',        v_spurious_count,
          'real_count',            v_real_count,
          'total_disconnects',     v_total_disconnects,
          'spurious_rate_pct',     v_spurious_rate,
          'window',                p_window,
          'reconnect_window',      p_reconnect_window,
          'top_offenders',         COALESCE(v_top_offenders, '[]'::jsonb),
          'fix_action',            'Filter connection.update type=close in n8n when Baileys reconnects within 30s'
        ),
        now()
      );
    EXCEPTION WHEN OTHERS THEN NULL; END;
  END IF;
  v_result := jsonb_build_object(
    'checked_at',          now(),
    'window',              p_window,
    'reconnect_window',    p_reconnect_window,
    'status',              v_status,
    'total_disconnects',   v_total_disconnects,
    'spurious_count',      v_spurious_count,
    'real_count',          v_real_count,
    'spurious_rate_pct',   v_spurious_rate,
    'top_offenders',       COALESCE(v_top_offenders, '[]'::jsonb),
    'thresholds',          jsonb_build_object(
                             'warn_pct',     v_spurious_warn_pct,
                             'critical_pct', v_spurious_critical_pct,
                             'min_count',    v_min_count
                           ),
    'fix_action',          'Filter connection.update type=close in n8n consumer when Baileys reconnects within 30s'
  );
  RETURN v_result;
END;
$$;


--
-- Name: FUNCTION fn_detect_spurious_closes(p_window interval, p_reconnect_window interval); Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON FUNCTION evo.fn_detect_spurious_closes(p_window interval, p_reconnect_window interval) IS 'E1-12: Detects spurious connection.update close events — disconnections where Baileys auto-reconnects within p_reconnect_window (default 30s). WARN when >70% of closes are spurious, CRITICAL when >90%. Provides per-instance breakdown to calibrate n8n consumer filter. Scheduled every 15 minutes via pg_cron.';


--
-- Name: fn_detect_swarm_task_duplication(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_detect_swarm_task_duplication() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo', 'zapp'
    AS $$
DECLARE
  v_heartbeat_window   CONSTANT interval := '5 minutes';
  v_heartbeat_max_ok   CONSTANT int      := 2;
  v_open_window        CONSTANT interval := '60 seconds';

  v_burst_count        int := 0;
  v_double_open_count  int := 0;
  r                    record;
BEGIN
  FOR r IN
    SELECT
      service_name,
      COUNT(*) AS hb_count,
      MIN(heartbeat_at) AS first_hb,
      MAX(heartbeat_at) AS last_hb
    FROM evo.evolution_guardian_heartbeat
    WHERE heartbeat_at >= now() - v_heartbeat_window
    GROUP BY service_name
    HAVING COUNT(*) > v_heartbeat_max_ok
    ORDER BY hb_count DESC
  LOOP
    v_burst_count := v_burst_count + 1;

    BEGIN
      INSERT INTO zapp.webhook_health_alerts
        (alert_type, severity, title, details, created_at)
      VALUES (
        'swarm_task_duplicate',
        'critical',
        format('E1-07: Swarm duplicate suspected — service "%s" sent %s heartbeats in 5min (max_ok=%s)',
          r.service_name, r.hb_count, v_heartbeat_max_ok),
        jsonb_build_object(
          'service_name',   r.service_name,
          'hb_count_5min',  r.hb_count,
          'max_ok',         v_heartbeat_max_ok,
          'first_hb',       r.first_hb,
          'last_hb',        r.last_hb,
          'detection',      'heartbeat_burst'
        ),
        now()
      );
    EXCEPTION WHEN OTHERS THEN NULL; END;
  END LOOP;

  FOR r IN
    WITH opens AS (
      SELECT
        instance_name,
        created_at,
        LAG(created_at) OVER (PARTITION BY instance_name ORDER BY created_at) AS prev_open_at
      FROM evo.evolution_connection_history
      WHERE state = 'open'
        AND created_at >= now() - interval '10 minutes'
    )
    SELECT
      instance_name,
      prev_open_at,
      created_at AS this_open_at,
      EXTRACT(EPOCH FROM (created_at - prev_open_at))::int AS gap_seconds
    FROM opens
    WHERE prev_open_at IS NOT NULL
      AND (created_at - prev_open_at) <= v_open_window
    ORDER BY gap_seconds ASC
  LOOP
    v_double_open_count := v_double_open_count + 1;

    BEGIN
      INSERT INTO zapp.webhook_health_alerts
        (alert_type, severity, title, details, created_at)
      VALUES (
        'swarm_task_duplicate',
        'critical',
        format('E1-07: Baileys double-open on "%s" — two OPEN events %ss apart (window: %ss)',
          r.instance_name, r.gap_seconds, EXTRACT(EPOCH FROM v_open_window)::int),
        jsonb_build_object(
          'instance_name', r.instance_name,
          'first_open',    r.prev_open_at,
          'second_open',   r.this_open_at,
          'gap_seconds',   r.gap_seconds,
          'detection',     'double_open'
        ),
        now()
      );
    EXCEPTION WHEN OTHERS THEN NULL; END;
  END LOOP;

  RETURN jsonb_build_object(
    'checked_at',             now(),
    'heartbeat_bursts_found', v_burst_count,
    'double_opens_found',     v_double_open_count,
    'total_detections',       v_burst_count + v_double_open_count,
    'status',                 CASE
                                WHEN (v_burst_count + v_double_open_count) > 0 THEN 'CRITICAL'
                                ELSE 'PASS'
                              END
  );
END;
$$;


--
-- Name: fn_ensure_evolution_backcompat_views(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_ensure_evolution_backcompat_views() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo'
    AS $_$
DECLARE r record; v_count int := 0;
BEGIN
  PERFORM set_config('lock_timeout','3s', true);

  -- GARANTIR view alias evo.evolution_messages_v2 → evo.evolution_messages (tabela ativa)
  IF NOT EXISTS (
    SELECT 1 FROM pg_views WHERE schemaname='evo' AND viewname='evolution_messages_v2'
  ) THEN
    EXECUTE $view$
      CREATE VIEW evo.evolution_messages_v2 WITH (security_invoker = on) AS
        SELECT id,message_id,remote_jid,instance_name,from_me,message_type,direction,
               status,status_at,content,caption,media_url,media_mimetype,media_filename,
               media_size,media_type,media_meta,quoted_message_id,push_name,contact_id,
               conversation_id,is_starred,is_important,is_read,category,sentiment,tags,
               notes,follow_up_at,follow_up_done,sent_by_bot,template_name,audio_meme_id,
               sticker_id,link_preview,payload,raw_data,deleted_at,edited_at,
               created_at,updated_at
        FROM evo.evolution_messages
    $view$;
    v_count := v_count + 1;
  END IF;

  -- Views de backcompat em public para tabelas evo sem view correspondente
  -- FIX 2026-08-06 (AG-EX-03): criar com security_invoker=on (PII WhatsApp) e SEM grant anon.
  FOR r IN
    SELECT c.relname
    FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
    WHERE n.nspname='evo' AND c.relname LIKE 'evolution_%' AND c.relkind IN ('r','p')
      AND NOT EXISTS (
        SELECT 1 FROM pg_class pv JOIN pg_namespace pn ON pn.oid=pv.relnamespace
        WHERE pn.nspname='public' AND pv.relname=c.relname
      )
    ORDER BY c.relname
  LOOP
    EXECUTE format('CREATE VIEW public.%I WITH (security_invoker = on) AS SELECT * FROM evo.%I', r.relname, r.relname);
    EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', r.relname);
    EXECUTE format('GRANT ALL ON public.%I TO service_role', r.relname);
    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$_$;


--
-- Name: fn_ensure_monthly_partitions(text, text, integer); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_ensure_monthly_partitions(p_schema text DEFAULT 'evo'::text, p_base_table text DEFAULT 'evolution_webhook_events_v2'::text, p_months_ahead integer DEFAULT 3) RETURNS TABLE(partitao text, acao text)
    LANGUAGE plpgsql
    SET search_path TO 'evo', 'public'
    AS $$
DECLARE
  v_month DATE;
  v_partition_name TEXT;
  v_start DATE;
  v_end DATE;
  v_sql TEXT;
  v_exists BOOLEAN;
BEGIN
  FOR i IN 0..p_months_ahead LOOP
    v_month := DATE_TRUNC('month', CURRENT_DATE + (i * INTERVAL '1 month'));
    v_partition_name := p_base_table || '_' || TO_CHAR(v_month, 'YYYY_MM');
    v_start := v_month;
    v_end := v_month + INTERVAL '1 month';
    
    -- Verificar se a partição já existe
    SELECT EXISTS(
      SELECT 1 FROM pg_class c
      JOIN pg_namespace n ON c.relnamespace = n.oid
      WHERE n.nspname = p_schema AND c.relname = v_partition_name
    ) INTO v_exists;
    
    IF v_exists THEN
      partitao := p_schema || '.' || v_partition_name;
      acao := 'JÁ EXISTE — pulando';
      RETURN NEXT;
    ELSE
      -- Criar a partição
      v_sql := FORMAT(
        'CREATE TABLE IF NOT EXISTS %I.%I PARTITION OF %I.%I FOR VALUES FROM (%L) TO (%L)',
        p_schema, v_partition_name, p_schema, p_base_table, v_start, v_end
      );
      EXECUTE v_sql;
      partitao := p_schema || '.' || v_partition_name;
      acao := '✅ CRIADA (range: ' || v_start || ' → ' || v_end || ')';
      RETURN NEXT;
    END IF;
  END LOOP;
END;
$$;


--
-- Name: FUNCTION fn_ensure_monthly_partitions(p_schema text, p_base_table text, p_months_ahead integer); Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON FUNCTION evo.fn_ensure_monthly_partitions(p_schema text, p_base_table text, p_months_ahead integer) IS 'Auto-cria partições mensais N+0 a N+3 para tabelas particionadas. Rodar via cron no dia 1 de cada mês. Etapa 9 plano 10/10 2026-07-09.';


--
-- Name: fn_feed_401_disconnect_alerts(integer, integer); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_feed_401_disconnect_alerts(p_minutes integer DEFAULT 15, p_threshold integer DEFAULT 3) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'evo', 'zapp', 'public'
    AS $$
DECLARE
  v_count       bigint := 0;
  v_last_event  timestamptz;
  v_events      jsonb;
  v_open_alert  boolean;
  v_alerted     boolean := false;
  v_since       timestamptz;
BEGIN
  v_since := now() - make_interval(mins => p_minutes);

  SELECT count(*), max(created_at)
  INTO v_count, v_last_event
  FROM evo.evolution_connection_history
  WHERE instance_name = 'wpp2'
    AND state IN ('logged_out', 'disconnected')
    AND created_at >= v_since;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'at', created_at, 'state', state, 'previous_state', previous_state,
           'source', COALESCE(metadata->>'source', 'unknown')
         ) ORDER BY created_at DESC), '[]'::jsonb)
  INTO v_events
  FROM (
    SELECT created_at, state, previous_state, metadata
    FROM evo.evolution_connection_history
    WHERE instance_name = 'wpp2'
      AND state IN ('logged_out', 'disconnected')
      AND created_at >= v_since
    ORDER BY created_at DESC
    LIMIT 10
  ) e;

  SELECT EXISTS(
    SELECT 1 FROM zapp.webhook_health_alerts
    WHERE alert_type = 'sentry_401_feed' AND resolved_at IS NULL
      AND created_at > now() - interval '30 minutes'
  ) INTO v_open_alert;

  IF v_count >= p_threshold AND NOT v_open_alert THEN
    INSERT INTO zapp.webhook_health_alerts
      (alert_type, severity, title, details, created_at)
    VALUES (
      'sentry_401_feed',
      'warning',
      format('E3-10: 401/desconexão — %s evento(s) em %smin (fonte: evolution_connection_history)', v_count, p_minutes),
      jsonb_build_object(
        'generated_at', now(), 'window_minutes', p_minutes, 'since', v_since,
        'event_count', v_count, 'events', v_events,
        'last_event_at', v_last_event,
        'source_table', 'evo.evolution_connection_history',
        'threshold', p_threshold,
        'auto_reconnect', false,
        'action_required', 'QR_SCAN',
        'runbook', 'logout -> connect -> qrcode (skill evolution-runtime-diagnostics; AG-EX-05)',
        'decisao', 'auto-reconnect NAO implementado: enforcement do WhatsApp (Baileys 7.0.0-rc.9, issue #2248) -> restart/redeploy nao resolve; acao = alerta + re-pareamento manual (QR scan)'
      ),
      now()
    );
    INSERT INTO evo.evolution_alerts (alert_type, severity, title, message, payload)
    VALUES (
      'wpp2_disconnect_burst',
      'critical',
      format('wpp2: %s desconexões em %s min', v_count, p_minutes),
      format('Instancia wpp2 registrou %s eventos de desconexao em %s min (threshold %s) na fonte evolution_connection_history. Sem auto-reconnect (enforcement #2248). Acao: verificar QR/re-pareamento via manager (evolution.atomicabr.com.br/manager).',
        v_count, p_minutes, p_threshold),
      jsonb_build_object(
        'instance', 'wpp2', 'window_minutes', p_minutes, 'threshold', p_threshold,
        'event_count', v_count, 'source_table', 'evo.evolution_connection_history',
        'auto_reconnect', false, 'action_required', 'QR_SCAN'
      )
    );
    v_alerted := true;
  END IF;

  RETURN jsonb_build_object(
    'ok', true, 'checked_at', now(),
    'window_minutes', p_minutes, 'threshold', p_threshold,
    'event_count', v_count, 'alerted', v_alerted,
    'last_event_at', v_last_event, 'auto_reconnect', false
  );
END;
$$;


--
-- Name: fn_filter_canary_messages(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_filter_canary_messages() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo'
    AS $_$
BEGIN
  -- Padrão exato: "wd-canary " seguido de 1+ dígitos (epoch unix do watchdog-canary v1)
  IF NEW.content ~ '^wd-canary [0-9]+$' THEN
    -- Logar para auditoria usando colunas corretas de evolution_audit_log
    BEGIN
      INSERT INTO evo.evolution_audit_log (
        action, entity_type, entity_id, new_values, metadata, performed_by, created_at
      ) VALUES (
        'canary_filtered',
        'evolution_messages_wpp2',
        gen_random_uuid(),  -- uuid sintético (message_id é text)
        jsonb_build_object(
          'message_id', NEW.message_id,
          'content', NEW.content,
          'from_me', NEW.from_me,
          'remote_jid', NEW.remote_jid
        ),
        jsonb_build_object('filtered_at', now(), 'push_name', NEW.push_name),
        'watchdog-canary',
        now()
      );
    EXCEPTION WHEN OTHERS THEN
      -- Falha de log não deve bloquear o filter
      NULL;
    END;

    -- Bloquear INSERT silenciosamente (RETURN NULL = não insere)
    RETURN NULL;
  END IF;

  RETURN NEW;
END;
$_$;


--
-- Name: fn_flag_poison_messages(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_flag_poison_messages() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo', 'zapp'
    AS $$
DECLARE
  v_flagged    bigint := 0;
  v_total_dlq  bigint;
  v_result     jsonb;
BEGIN
  UPDATE evo.evolution_webhook_dlq
  SET status = 'poison'
  WHERE status = 'pending'
    AND retry_count >= max_retries;

  GET DIAGNOSTICS v_flagged = ROW_COUNT;

  SELECT COUNT(*) INTO v_total_dlq FROM evo.evolution_webhook_dlq;

  v_result := jsonb_build_object(
    'checked_at',      now(),
    'newly_flagged',   v_flagged,
    'total_dlq_rows',  v_total_dlq
  );

  IF v_flagged > 0 THEN
    BEGIN
      INSERT INTO zapp.webhook_health_alerts
        (alert_type, severity, title, details, created_at)
      VALUES (
        'dlq_poison_messages',
        'high',
        format('E8-03: %s poison message(s) flagged in evolution_webhook_dlq — consumer restart loop prevented', v_flagged),
        v_result,
        now()
      );
    EXCEPTION WHEN OTHERS THEN NULL; END;
  END IF;

  RETURN v_result;
END;
$$;


--
-- Name: fn_get_incident_runbook(text); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_get_incident_runbook(p_type text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  IF p_type IS NULL THEN
    SELECT jsonb_build_object(
      'runbooks_summary', COALESCE(
        jsonb_agg(jsonb_build_object(
          'id',                 id,
          'title',              title,
          'severity',           severity,
          'category',           category,
          'estimated_minutes',  estimated_minutes,
          'last_drilled_at',    last_drilled_at
        ) ORDER BY severity, id),
        '[]'::jsonb
      ),
      'total', COALESCE(COUNT(*), 0)
    )
    INTO v_result
    FROM evo.evolution_incident_runbook;
  ELSE
    SELECT to_jsonb(r)
    INTO v_result
    FROM evo.evolution_incident_runbook r
    WHERE r.id = p_type;

    IF v_result IS NULL THEN
      v_result := jsonb_build_object('error', format('runbook not found: %s', p_type));
    END IF;
  END IF;

  RETURN v_result;
END;
$$;


--
-- Name: FUNCTION fn_get_incident_runbook(p_type text); Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON FUNCTION evo.fn_get_incident_runbook(p_type text) IS 'E10-04: Returns full incident runbook as JSONB. Pass NULL to list all runbooks (summary). Pass runbook ID for full step-by-step runbook. Available: container_crash, baileys_auth_conflict, qr_repaid, rabbitmq_queue_loss, api_key_rotation, dlq_overflow, redis_stale_session, backup_restore, burnin_reset, full_rollback.';


--
-- Name: fn_link_orphan_messages(integer); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_link_orphan_messages(p_limit integer DEFAULT 500) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo'
    AS $$
DECLARE v_convs int; v_linked int;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM evo.evolution_messages WHERE conversation_id IS NULL LIMIT 1) THEN
    RETURN jsonb_build_object('conversas_criadas',0,'mensagens_ligadas',0,'early_exit',true);
  END IF;
  INSERT INTO evo.evolution_conversations (remote_jid, instance_name, first_message_at, last_message_at, message_count, created_at, updated_at)
  SELECT remote_jid, instance_name, min(created_at), max(created_at), count(*), min(created_at), now()
  FROM evo.evolution_messages
  WHERE conversation_id IS NULL AND remote_jid IS NOT NULL AND instance_name IS NOT NULL
  GROUP BY remote_jid, instance_name
  ON CONFLICT (remote_jid, instance_name) DO NOTHING;
  GET DIAGNOSTICS v_convs = ROW_COUNT;
  UPDATE evo.evolution_messages m SET conversation_id = c.id
  FROM evo.evolution_conversations c
  WHERE c.remote_jid = m.remote_jid AND c.instance_name = m.instance_name
    AND m.conversation_id IS NULL
    AND m.id IN (SELECT id FROM evo.evolution_messages WHERE conversation_id IS NULL LIMIT p_limit);
  GET DIAGNOSTICS v_linked = ROW_COUNT;
  RETURN jsonb_build_object('conversas_criadas', v_convs, 'mensagens_ligadas', v_linked, 'early_exit', false);
END $$;


--
-- Name: fn_log_assignment_change(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_log_assignment_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo', 'zapp'
    AS $$
BEGIN
  BEGIN
    PERFORM zapp.rpc_log_assignment_change(
      NEW.id,
      evo.fn_uuid_safe(OLD.assigned_to),
      evo.fn_uuid_safe(NEW.assigned_to),
      CASE WHEN OLD.assigned_to IS NULL THEN 'assign'
           WHEN NEW.assigned_to IS NULL THEN 'unassign'
           ELSE 'transfer' END,
      COALESCE(evo.fn_uuid_safe(NEW.assigned_to), evo.fn_uuid_safe(OLD.assigned_to))
    );
  EXCEPTION WHEN OTHERS THEN NULL;
  END;
  RETURN NEW;
END $$;


--
-- Name: FUNCTION fn_log_assignment_change(); Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON FUNCTION evo.fn_log_assignment_change() IS 'Paridade Lovable (log_assignment_change) adaptada: audita mudanças de assigned_to em zapp.conversation_events. Exception-safe.';


--
-- Name: fn_logpatch_verify(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_logpatch_verify() RETURNS TABLE(patch text, status text, detail text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo'
    AS $$
DECLARE
  v_last_log RECORD;
BEGIN
  -- E5-04: 10s grace period for boot logs to land in evolution_health_logs
  PERFORM pg_sleep(10);

  SELECT * INTO v_last_log
  FROM evo.evolution_health_logs
  ORDER BY created_at DESC
  LIMIT 1;

  RETURN QUERY SELECT
    'T1_message_dump'::TEXT,
    CASE WHEN v_last_log.status = 'success' THEN 'OK' ELSE 'UNKNOWN' END::TEXT,
    COALESCE('last_check=' || v_last_log.created_at::TEXT, 'no_health_log')::TEXT;

  RETURN QUERY SELECT
    'T2_stanza_dump'::TEXT,
    CASE WHEN v_last_log.status = 'success' THEN 'OK' ELSE 'UNKNOWN' END::TEXT,
    'inferred_from_T1'::TEXT;

  RETURN QUERY SELECT
    'T3_sentry_filter'::TEXT,
    'APPLY_REQUIRED'::TEXT,
    'Verificar log de boot: [logpatch] T3 OK'::TEXT;

  RETURN QUERY SELECT
    'T4_apikey_mask'::TEXT,
    'APPLY_REQUIRED'::TEXT,
    'Verificar log de boot: [logpatch] T4 OK'::TEXT;

  RETURN QUERY SELECT
    'T5_cache_dump'::TEXT,
    'APPLY_REQUIRED'::TEXT,
    'Verificar log de boot: [logpatch] T5 OK — ForceUpdate 484 aplicado em 2026-07-10'::TEXT;

  RETURN QUERY SELECT
    'SUMMARY'::TEXT,
    CASE
      WHEN v_last_log.status = 'success' THEN 'PARTIAL_OK'
      ELSE 'NEEDS_VERIFICATION'
    END::TEXT,
    'ForceUpdate=484 | T1-T5 no logpatch | Verificar logs de boot do container evolution'::TEXT;
END;
$$;


--
-- Name: fn_monitor_lid_contamination(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_monitor_lid_contamination() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo'
    AS $$
DECLARE
  v_total      bigint;
  v_lid_total  bigint;
  v_lid_7d     bigint;
  v_pct        numeric;
  v_threshold  numeric := 30.0;
  v_result     jsonb;
BEGIN
  SELECT
    count(*),
    count(*) FILTER (WHERE remote_jid LIKE '%@lid'),
    count(*) FILTER (WHERE remote_jid LIKE '%@lid' AND updated_at > now()-interval '7 days')
  INTO v_total, v_lid_total, v_lid_7d
  FROM evo.evolution_conversations_wpp2;
  v_pct := round(100.0 * v_lid_total / nullif(v_total,0), 1);
  v_result := jsonb_build_object(
    'checked_at',    now(),
    'total_conv',    v_total,
    'lid_total',     v_lid_total,
    'lid_7d_new',    v_lid_7d,
    'pct_lid',       v_pct,
    'threshold_pct', v_threshold,
    'status',        CASE WHEN v_pct >= v_threshold THEN 'WARNING' ELSE 'OK' END,
    'note',          'LID = WhatsApp temporary device ID for Android users. Fix: upgrade Evolution API when version with senderPn fix is stable. Issue #1778 upstream.'
  );
  IF v_pct >= v_threshold AND NOT EXISTS (
    SELECT 1 FROM evo.evolution_alerts
    WHERE alert_type = 'lid_contamination_high'
      AND (resolved IS NULL OR resolved = false)
      AND created_at >= now() - INTERVAL '24 hours'
  ) THEN
    INSERT INTO evo.evolution_alerts (severity, alert_type, message, payload)
    VALUES (
      'high',
      'lid_contamination_high',
      format('@LID contamination at %s%% (>%s%% threshold). %s of %s conversations affected. %s new in last 7 days.', round(v_pct, 1), v_threshold, v_lid_total, v_total, v_lid_7d),
      v_result
    );
  END IF;
  RETURN v_result;
END;
$$;


--
-- Name: fn_monitor_pino_timeouts(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_monitor_pino_timeouts() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo'
    AS $$
DECLARE
  v_count  bigint;
  v_status text;
  v_result jsonb;
BEGIN
  SELECT COUNT(*) INTO v_count
  FROM evo.evolution_health_logs
  WHERE created_at >= now() - INTERVAL '2 hours'
    AND (
      error_message ILIKE '%timed out%'
      OR metadata::text ILIKE '%timed out%'
    );

  v_status := CASE
    WHEN v_count = 0  THEN 'PASS'
    WHEN v_count < 5  THEN 'INFO'
    ELSE 'WARN'
  END;

  RETURN jsonb_build_object(
    'checked_at',          now(),
    'status',              v_status,
    'timed_out_count_2h',  v_count,
    'note', CASE
      WHEN v_count < 5 THEN 'Pino timeouts within normal Baileys keepalive range'
      ELSE 'Elevated Pino timeouts — check Baileys connection stability'
    END
  );
END;
$$;


--
-- Name: fn_monthly_evo_audit(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_monthly_evo_audit() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo'
    AS $$
DECLARE
  v_month_start   DATE    := date_trunc('month', now() - INTERVAL '1 month')::date;
  v_month_end     DATE    := date_trunc('month', now())::date;
  v_msg_volume    BIGINT;
  v_msg_inbound   BIGINT;
  v_msg_outbound  BIGINT;
  v_alerts_crit   INT;
  v_alerts_high   INT;
  v_rotation_due  INT;
  v_health_ok     INT;
  v_health_warn   INT;
  v_health_crit   INT;
  v_result        JSONB;
BEGIN
  -- Message volume for the completed month
  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE NOT COALESCE(from_me, false)),
    COUNT(*) FILTER (WHERE COALESCE(from_me, false))
  INTO v_msg_volume, v_msg_inbound, v_msg_outbound
  FROM evo.evolution_messages
  WHERE created_at >= v_month_start AND created_at < v_month_end;

  -- Open critical/high alerts
  SELECT
    COUNT(*) FILTER (WHERE severity = 'critical'),
    COUNT(*) FILTER (WHERE severity = 'high')
  INTO v_alerts_crit, v_alerts_high
  FROM evo.evolution_alerts
  WHERE resolved_at IS NULL AND resolved = false;

  -- Consumers with rotation needed
  SELECT COUNT(*) INTO v_rotation_due
  FROM evo.evolution_api_consumers
  WHERE rotation_needed = true AND status = 'active';

  -- Pipeline health log summary for last 30 days
  SELECT
    COUNT(*) FILTER (WHERE probe_status = 'ok'),
    COUNT(*) FILTER (WHERE probe_status = 'warn'),
    COUNT(*) FILTER (WHERE probe_status = 'critical')
  INTO v_health_ok, v_health_warn, v_health_crit
  FROM evo.evolution_pipeline_health_log
  WHERE checked_at >= now() - INTERVAL '30 days';

  v_result := jsonb_build_object(
    'audit_month',         v_month_start,
    'generated_at',        now(),
    'messages', jsonb_build_object(
      'total',    v_msg_volume,
      'inbound',  v_msg_inbound,
      'outbound', v_msg_outbound,
      'period',   v_month_start || ' to ' || v_month_end
    ),
    'pipeline_health_30d', jsonb_build_object(
      'probes_ok',       v_health_ok,
      'probes_warn',     v_health_warn,
      'probes_critical', v_health_crit,
      'uptime_pct',      CASE WHEN (v_health_ok + v_health_warn + v_health_crit) > 0
                           THEN ROUND(100.0 * v_health_ok / (v_health_ok + v_health_warn + v_health_crit), 2)
                           ELSE NULL END
    ),
    'open_alerts', jsonb_build_object(
      'critical', v_alerts_crit,
      'high',     v_alerts_high
    ),
    'consumer_registry', jsonb_build_object(
      'rotation_needed_count', v_rotation_due
    )
  );

  -- Persist to log table (upsert by month)
  INSERT INTO evo.evolution_monthly_audit_log (audit_month, report)
  VALUES (v_month_start, v_result)
  ON CONFLICT (audit_month) DO UPDATE SET
    report     = EXCLUDED.report,
    created_at = now();

  RETURN v_result;
END;
$$;


--
-- Name: fn_normalize_remote_jid(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_normalize_remote_jid() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo'
    AS $$ BEGIN IF NEW.remote_jid IS NULL OR NEW.remote_jid = '' THEN IF NEW.status = 'deleted' OR NEW.content = '[Mensagem apagada]' THEN NEW.remote_jid := 'unknown@deleted'; ELSIF NEW.message_id LIKE 'smoke-%' OR NEW.message_id LIKE 'test-%' THEN NEW.remote_jid := 'smoke-test@localhost'; ELSE NEW.remote_jid := 'unknown@s.whatsapp.net'; END IF; END IF; RETURN NEW; END; $$;


--
-- Name: fn_notify_sicoob_on_reply(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_notify_sicoob_on_reply() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo'
    AS $$
DECLARE v_lead_status text;
BEGIN
  BEGIN
    SELECT lead_status INTO v_lead_status FROM evo.evolution_contacts WHERE id = NEW.contact_id;
    IF v_lead_status = 'sicoob_gifts' THEN
      PERFORM net.http_post(
        url := 'http://functions:9000/sicoob-bridge-reply',
        body := jsonb_build_object('contact_id', NEW.contact_id, 'content', NEW.content, 'message_id', NEW.id, 'created_at', NEW.created_at),
        headers := jsonb_build_object('Content-Type','application/json'));
    END IF;
  EXCEPTION WHEN OTHERS THEN NULL;
  END;
  RETURN NEW;
END $$;


--
-- Name: FUNCTION fn_notify_sicoob_on_reply(); Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON FUNCTION evo.fn_notify_sicoob_on_reply() IS 'Paridade Lovable (notify_sicoob_on_reply) adaptada: pg_net assíncrono p/ edge fn sicoob-bridge-reply via gateway interno; original usava extensions.http_post (ext ausente) + URL Lovable hardcoded. Exception-safe.';


--
-- Name: fn_pipeline_health_probe(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_pipeline_health_probe() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo', 'zapp'
    AS $$
DECLARE
  v_gap_min NUMERIC; v_last_msg_at TIMESTAMPTZ; v_msg_count_1h INTEGER;
  v_probe_status TEXT; v_pipeline_status zapp.evolution_pipeline_status;
  v_detail TEXT; v_alerts_open INTEGER; v_now_brt TIMESTAMPTZ;
  v_dow INTEGER; v_hour_brt INTEGER; v_business_hours BOOLEAN;
  v_is_weekend BOOLEAN; v_crit_threshold INTEGER; v_warn_threshold INTEGER; v_fast_threshold INTEGER;
BEGIN
  SELECT MAX(created_at), COUNT(*) FILTER (WHERE created_at >= NOW()-INTERVAL '1 hour') INTO v_last_msg_at, v_msg_count_1h FROM evo.evolution_messages;
  v_gap_min := EXTRACT(EPOCH FROM (NOW()-COALESCE(v_last_msg_at,NOW()-INTERVAL '9999 minutes')))/60;
  SELECT COUNT(*) INTO v_alerts_open FROM evo.evolution_alerts WHERE severity IN ('critical','high') AND resolved_at IS NULL;
  v_now_brt := NOW() AT TIME ZONE 'America/Sao_Paulo';
  v_dow := EXTRACT(DOW FROM v_now_brt); v_hour_brt := EXTRACT(HOUR FROM v_now_brt);
  v_is_weekend := (v_dow=0 OR v_dow=6);
  v_business_hours := NOT v_is_weekend AND (v_hour_brt BETWEEN 8 AND 19);
  IF v_business_hours THEN v_crit_threshold:=20; v_warn_threshold:=10; v_fast_threshold:=5;
  ELSIF v_is_weekend THEN v_crit_threshold:=1440; v_warn_threshold:=480; v_fast_threshold:=240;
  ELSE v_crit_threshold:=60; v_warn_threshold:=30; v_fast_threshold:=15;
  END IF;
  IF v_gap_min > v_crit_threshold THEN
    v_probe_status:='critical'; v_pipeline_status:='critical';
    v_detail:=format('GAP CRITICO: %s min (threshold=%s, %s)',ROUND(v_gap_min),v_crit_threshold,CASE WHEN v_is_weekend THEN 'fim de semana' WHEN v_business_hours THEN 'comercial' ELSE 'off' END);
  ELSIF v_gap_min > v_warn_threshold THEN
    v_probe_status:='warn'; v_pipeline_status:='degraded_webhook';
    v_detail:=format('GAP elevado: %s min (warn=%s)',ROUND(v_gap_min),v_warn_threshold);
  ELSIF v_msg_count_1h=0 AND v_gap_min > v_fast_threshold THEN
    v_probe_status:='warn'; v_pipeline_status:='warning';
    v_detail:=format('Sem msgs/1h. Gap: %s min',ROUND(v_gap_min));
  ELSE
    v_probe_status:='ok'; v_pipeline_status:='healthy';
    v_detail:=format('OK. Gap: %s min. Msgs/1h: %s',ROUND(v_gap_min),v_msg_count_1h);
  END IF;
  INSERT INTO evo.evolution_pipeline_health_log(checked_at,pipeline_status,baileys_health,gap_inbound_min,detail,probe_status,instance_name,unroutable_count,webhook_events_1h,alerts_critical_open,notes)
  VALUES(NOW(),v_pipeline_status,CASE WHEN v_gap_min<v_warn_threshold THEN 'connected' ELSE 'check_required' END,v_gap_min,v_detail,v_probe_status,'wpp2',0,v_msg_count_1h,v_alerts_open,format('probe-15min|dow=%s|wk=%s|biz=%s|crit=%s|src=evolution_messages',v_dow,v_is_weekend,v_business_hours,v_crit_threshold));
  IF v_probe_status='critical' THEN
    INSERT INTO evo.evolution_alerts (severity,alert_type,message,payload)
    SELECT 'critical','pipeline_gap',format('GAP critico: %s min (%s)',ROUND(v_gap_min),CASE WHEN v_is_weekend THEN 'fim de semana' WHEN v_business_hours THEN 'horario comercial' ELSE 'fora do horario' END),jsonb_build_object('gap_min',v_gap_min,'last_msg_at',v_last_msg_at,'threshold',v_crit_threshold,'is_weekend',v_is_weekend)
    WHERE NOT EXISTS(SELECT 1 FROM evo.evolution_alerts WHERE alert_type='pipeline_gap' AND severity='critical' AND resolved_at IS NULL AND created_at>=NOW()-INTERVAL '30 minutes');
  END IF;
  RETURN jsonb_build_object('status',v_probe_status,'gap_min',ROUND(v_gap_min),'msgs_1h',v_msg_count_1h,'alerts_open',v_alerts_open,'pipeline_status',v_pipeline_status::TEXT,'business_hours',v_business_hours,'is_weekend',v_is_weekend,'crit_threshold',v_crit_threshold,'checked_at',NOW());
END;
$$;


--
-- Name: fn_record_runbook_drill(text); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_record_runbook_drill(p_type text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo'
    AS $$
DECLARE
  v_rows int;
BEGIN
  UPDATE evo.evolution_incident_runbook
  SET last_drilled_at = now(), updated_at = now()
  WHERE id = p_type;

  GET DIAGNOSTICS v_rows = ROW_COUNT;

  IF v_rows = 0 THEN
    RETURN jsonb_build_object('error', format('Runbook not found: %s', p_type));
  END IF;

  RETURN jsonb_build_object(
    'drilled', p_type,
    'drilled_at', now(),
    'next_drill_recommended', now() + interval '30 days'
  );
END;
$$;


--
-- Name: FUNCTION fn_record_runbook_drill(p_type text); Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON FUNCTION evo.fn_record_runbook_drill(p_type text) IS 'E10-04: Records that a drill was performed for the given runbook type. Usage: SELECT evo.fn_record_runbook_drill(''container_crash'');';


--
-- Name: fn_resolve_alert(uuid, text, uuid[]); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_resolve_alert(p_id uuid DEFAULT NULL::uuid, p_by text DEFAULT 'system'::text, p_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(id uuid, alert_type text, severity text, resolved_at timestamp with time zone, resolved_by character varying)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo'
    AS $$
BEGIN
  RETURN QUERY
    UPDATE evo.evolution_alerts a
    SET resolved_at = now(),
        resolved_by = p_by
    WHERE a.resolved_at IS NULL
      AND (
        (p_ids IS NOT NULL AND a.id = ANY(p_ids))
        OR
        (p_ids IS NULL AND p_id IS NOT NULL AND a.id = p_id)
      )
    RETURNING a.id, a.alert_type, a.severity, a.resolved_at, a.resolved_by;
END;
$$;


--
-- Name: FUNCTION fn_resolve_alert(p_id uuid, p_by text, p_ids uuid[]); Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON FUNCTION evo.fn_resolve_alert(p_id uuid, p_by text, p_ids uuid[]) IS 'API segura para resolver alertas. resolved e coluna gerada (resolved_at IS NOT NULL). NUNCA UPDATE resolved=true diretamente. Aceita 1 id ou array p_ids para lote.';


--
-- Name: fn_scrub_r2_paths_from_logs(interval); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_scrub_r2_paths_from_logs(p_window interval DEFAULT '24:00:00'::interval) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo'
    AS $$
DECLARE
  v_health_scrubbed   bigint := 0;
  v_dlq_scrubbed      bigint := 0;
  v_alerts_scrubbed   bigint := 0;
  v_since             timestamptz;
BEGIN
  v_since := now() - p_window;

  WITH updated AS (
    UPDATE evo.evolution_health_logs
    SET error_message = evo.fn_scrub_r2_text(error_message)
    WHERE created_at >= v_since
      AND error_message IS NOT NULL
      AND (
        error_message ILIKE '%r2.cloudflarestorage.com%'
        OR error_message ILIKE '%s3://%'
        OR error_message ILIKE '%r2://%'
      )
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_health_scrubbed FROM updated;

  WITH updated AS (
    UPDATE evo.evolution_webhook_dlq
    SET
      error_message = CASE
        WHEN error_message IS NOT NULL AND (
          error_message ILIKE '%r2.cloudflarestorage.com%'
          OR error_message ILIKE '%s3://%'
          OR error_message ILIKE '%r2://%'
        ) THEN evo.fn_scrub_r2_text(error_message)
        ELSE error_message
      END,
      error_stack = CASE
        WHEN error_stack IS NOT NULL AND (
          error_stack ILIKE '%r2.cloudflarestorage.com%'
          OR error_stack ILIKE '%s3://%'
          OR error_stack ILIKE '%r2://%'
        ) THEN evo.fn_scrub_r2_text(error_stack)
        ELSE error_stack
      END,
      raw_payload = CASE
        WHEN raw_payload IS NOT NULL AND (
          raw_payload ILIKE '%r2.cloudflarestorage.com%'
          OR raw_payload ILIKE '%s3://%'
          OR raw_payload ILIKE '%r2://%'
        ) THEN evo.fn_scrub_r2_text(raw_payload)
        ELSE raw_payload
      END
    WHERE created_at >= v_since
      AND (
        (error_message IS NOT NULL AND (
          error_message ILIKE '%r2.cloudflarestorage.com%'
          OR error_message ILIKE '%s3://%'
          OR error_message ILIKE '%r2://%'
        ))
        OR (error_stack IS NOT NULL AND (
          error_stack ILIKE '%r2.cloudflarestorage.com%'
          OR error_stack ILIKE '%s3://%'
          OR error_stack ILIKE '%r2://%'
        ))
        OR (raw_payload IS NOT NULL AND (
          raw_payload ILIKE '%r2.cloudflarestorage.com%'
          OR raw_payload ILIKE '%s3://%'
          OR raw_payload ILIKE '%r2://%'
        ))
      )
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_dlq_scrubbed FROM updated;

  WITH updated AS (
    UPDATE evo.evolution_alerts
    SET
      message = CASE
        WHEN message IS NOT NULL AND (
          message ILIKE '%r2.cloudflarestorage.com%'
          OR message ILIKE '%s3://%'
          OR message ILIKE '%r2://%'
        ) THEN evo.fn_scrub_r2_text(message)
        ELSE message
      END,
      description = CASE
        WHEN description IS NOT NULL AND (
          description ILIKE '%r2.cloudflarestorage.com%'
          OR description ILIKE '%s3://%'
          OR description ILIKE '%r2://%'
        ) THEN evo.fn_scrub_r2_text(description)
        ELSE description
      END,
      title = CASE
        WHEN title IS NOT NULL AND (
          title ILIKE '%r2.cloudflarestorage.com%'
          OR title ILIKE '%s3://%'
          OR title ILIKE '%r2://%'
        ) THEN evo.fn_scrub_r2_text(title)
        ELSE title
      END
    WHERE created_at >= v_since
      AND (
        (message IS NOT NULL AND (
          message ILIKE '%r2.cloudflarestorage.com%'
          OR message ILIKE '%s3://%'
          OR message ILIKE '%r2://%'
        ))
        OR (description IS NOT NULL AND (
          description ILIKE '%r2.cloudflarestorage.com%'
          OR description ILIKE '%s3://%'
          OR description ILIKE '%r2://%'
        ))
        OR (title IS NOT NULL AND (
          title ILIKE '%r2.cloudflarestorage.com%'
          OR title ILIKE '%s3://%'
          OR title ILIKE '%r2://%'
        ))
      )
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_alerts_scrubbed FROM updated;

  RETURN jsonb_build_object(
    'scrubbed_at',        now(),
    'window',             p_window,
    'health_logs',        v_health_scrubbed,
    'webhook_dlq',        v_dlq_scrubbed,
    'evolution_alerts',   v_alerts_scrubbed,
    'total_rows_updated', v_health_scrubbed + v_dlq_scrubbed + v_alerts_scrubbed,
    'status',             CASE
                            WHEN (v_health_scrubbed + v_dlq_scrubbed + v_alerts_scrubbed) > 0
                            THEN 'SCRUBBED'
                            ELSE 'CLEAN'
                          END
  );
END;
$$;


--
-- Name: fn_scrub_r2_text(text); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_scrub_r2_text(p_input text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'pg_temp'
    AS $$
  SELECT
    regexp_replace(
      regexp_replace(
        regexp_replace(
          p_input,
          'r2://[^\s''\"<>]+',
          '[R2-PATH-REDACTED]',
          'gi'
        ),
        's3://[^\s''\"<>]+',
        '[R2-PATH-REDACTED]',
        'gi'
      ),
      'https://[0-9a-f]{32}\.r2\.cloudflarestorage\.com/[^\s''\"<>]*',
      '[R2-PATH-REDACTED]',
      'gi'
    )
$$;


--
-- Name: fn_sync_guardian_heartbeat(text); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_sync_guardian_heartbeat(p_pg_password text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo', 'vault', 'extensions'
    AS $$
DECLARE
  v_pwd    text;
  v_conn   text;
  v_result record;
BEGIN
  -- Prioridade 1: parametro explicito
  IF p_pg_password IS NOT NULL THEN
    v_pwd := p_pg_password;
  ELSE
    -- Prioridade 2: Vault (fonte segura, criptografada)
    SELECT decrypted_secret INTO v_pwd
    FROM vault.decrypted_secrets
    WHERE name='evolution_pg_password';

    -- Prioridade 3: _secure_config (fallback, apenas se vault vazio)
    IF v_pwd IS NULL THEN
      SELECT value INTO v_pwd FROM evo._secure_config WHERE key='evolution_pg_password';
    END IF;
  END IF;

  -- Validar: rejeitar se vazio ou marcado como migrado
  IF v_pwd IS NULL OR v_pwd LIKE '[%' OR length(trim(v_pwd)) < 8 THEN
    RETURN jsonb_build_object('status','error','message',
      'evolution_pg_password indisponivel (verifique vault.secrets name=evolution_pg_password)',
      'checked_at', now());
  END IF;

  -- FIX 2026-08-06 (E9): hostname do servico em vez de VIP hardcoded 10.0.1.48 (stale).
  -- VIP atual do servico postgres (PG14 evolution) = 10.0.1.118; hostname resolve via overlay.
  v_conn := 'host=postgres port=5432 dbname=evolution user=postgres password='
            || v_pwd || ' connect_timeout=5';

  -- Ler ultimo heartbeat do guardian do Evolution DB via dblink
  SELECT * INTO v_result FROM dblink(
    v_conn,
    'SELECT detected_at, case_kind
     FROM _swarm_guardian_events
     WHERE case_kind=''guardian_start''
     ORDER BY detected_at DESC LIMIT 1'
  ) AS t(detected_at timestamptz, case_kind text);

  IF v_result.detected_at IS NULL THEN
    RETURN jsonb_build_object('status','no_heartbeat','checked_at',now());
  END IF;

  -- Inserir com ON CONFLICT DO NOTHING para evitar duplicatas
  INSERT INTO evo.evolution_guardian_heartbeat(service_name, heartbeat_at, details)
  VALUES (
    'swarm-task-guardian',
    v_result.detected_at,
    jsonb_build_object(
      'source', 'dblink',
      'alive',  (EXTRACT(EPOCH FROM (now() - v_result.detected_at)) < 600),
      'age_s',  EXTRACT(EPOCH FROM (now() - v_result.detected_at))::int
    )
  )
  ON CONFLICT (service_name, heartbeat_at) DO NOTHING;

  RETURN jsonb_build_object(
    'status',        'ok',
    'heartbeat_at',  v_result.detected_at,
    'age_s',         EXTRACT(EPOCH FROM (now() - v_result.detected_at))::int,
    'source',        'vault'
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('status','error','message',SQLERRM,'checked_at',now());
END;
$$;


--
-- Name: fn_sync_messages_to_v2(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_sync_messages_to_v2() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo'
    AS $$
DECLARE
  v_last_synced   timestamptz;
  v_inserted      int := 0;
  v_window_start  timestamptz;
BEGIN
  SELECT max(created_at)
  INTO v_last_synced
  FROM evo.evolution_webhook_events_v2
  WHERE instance_name = 'wpp2'
    AND payload->>'heartbeat' IS NULL
    AND payload->>'backfill_source' IS NULL;
  v_window_start := COALESCE(v_last_synced, now() - interval '2 hours');
  INSERT INTO evo.evolution_webhook_events_v2 (
    id, event_type, instance_name, remote_jid, from_me,
    message_type, push_name, payload, processed, processed_at,
    status, retry_count, created_at
  )
  SELECT
    gen_random_uuid(),
    'messages.upsert',
    m.instance_name,
    m.remote_jid,
    m.from_me,
    m.message_type,
    NULL,
    jsonb_build_object(
      'messageId', m.message_id,
      'remoteJid', m.remote_jid,
      'fromMe', m.from_me,
      'messageType', m.message_type,
      'content', m.content,
      'sync_source', 'fn_sync_messages_to_v2',
      'sync_ts', now()
    ),
    true,
    now(),
    'processed',
    0,
    m.created_at
  FROM evo.evolution_messages m
  WHERE m.instance_name = 'wpp2'
    AND m.created_at > v_window_start
    AND NOT EXISTS (
      SELECT 1 FROM evo.evolution_webhook_events_v2 ev
      WHERE ev.instance_name = 'wpp2'
        AND ev.created_at = m.created_at
        AND ev.payload->>'messageId' = m.message_id
    )
  ORDER BY m.created_at ASC
  LIMIT 500;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  RETURN jsonb_build_object(
    'ok', true,
    'inserted', v_inserted,
    'window_start', v_window_start,
    'executed_at', now()
  );
END;
$$;


--
-- Name: fn_update_instance_health(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_update_instance_health() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo'
    AS $$
DECLARE
  v_gap numeric; v_msgs_1h int; v_status text;
  v_dow int := EXTRACT(DOW FROM NOW() AT TIME ZONE 'America/Sao_Paulo');
  v_is_fds boolean := v_dow IN (0,6);
  v_gap_healthy int := 10;   -- gap < 10min = healthy sempre
  v_gap_degraded int;        -- gap < X = degraded (vs unhealthy)
BEGIN
  -- Fonte canonica: evo.evolution_messages (arquitetura pos-migracao self-hosted)
  SELECT
    ROUND(EXTRACT(EPOCH FROM (now()-MAX(created_at)))/60, 1),
    COUNT(*) FILTER (WHERE created_at > now()-INTERVAL '1h')
  INTO v_gap, v_msgs_1h
  FROM evo.evolution_messages;

  -- FIX v2: threshold adaptativo por dia da semana
  -- FDS (sab/dom): empresa B2B — normal ter gap>30min entre msgs
  -- Dia util: gap>30min ja e suspeito
  v_gap_degraded := CASE WHEN v_is_fds THEN 120 ELSE 30 END;

  v_status := CASE
    WHEN v_msgs_1h > 0 AND v_gap < v_gap_healthy THEN 'healthy'
    WHEN v_gap < v_gap_degraded                   THEN 'degraded'
    WHEN v_is_fds AND v_msgs_1h > 0              THEN 'degraded'  -- FDS: msgs existem mas gap longo = degraded (nao unhealthy)
    ELSE 'unhealthy'
  END;

  UPDATE evo.evolution_instance_credentials
  SET health_status     = v_status,
      last_health_check = NOW(),
      online_instances  = CASE WHEN v_status IN ('healthy','degraded') THEN 1 ELSE 0 END,
      notes             = FORMAT('gap=%smin msgs1h=%s auto-check=%s src=evolution_messages fds=%s gap_thr=%s',
                            v_gap, v_msgs_1h, NOW()::text, v_is_fds, v_gap_degraded)
  WHERE instance_name = 'wpp2';
END;
$$;


--
-- Name: FUNCTION fn_update_instance_health(); Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON FUNCTION evo.fn_update_instance_health() IS 'Atualiza health_status de wpp2 (cron 172 evo-instance-health-check, */10min). Threshold adaptativo FDS (sab/dom). Sem referencias Lovable desde 2026-08-03.';


--
-- Name: fn_uuid_safe(text); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_uuid_safe(t text) RETURNS uuid
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'evo', 'public'
    AS $_$
  SELECT CASE WHEN t ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN t::uuid END
$_$;


--
-- Name: FUNCTION fn_uuid_safe(t text); Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON FUNCTION evo.fn_uuid_safe(t text) IS 'Cast seguro text->uuid (NULL se inválido). Paridade Lovable 2026-07-04.';


--
-- Name: fn_v2_mirror_health(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_v2_mirror_health() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'evo', 'pg_catalog'
    AS $$
DECLARE
  v_last_event TIMESTAMPTZ;
  v_hours_dead NUMERIC;
  v_total_rows BIGINT;
  v_last_7d BIGINT;
  v_last_24h BIGINT;
  v_status TEXT;
  v_score INT;
  v_pending INT;
  v_processed_recent INT;
  v_audit_last TIMESTAMPTZ;
  v_audit_1h BIGINT;
BEGIN
  SELECT MAX(created_at), COUNT(*),
    COUNT(*) FILTER (WHERE created_at > NOW()-INTERVAL '7 days'),
    COUNT(*) FILTER (WHERE created_at > NOW()-INTERVAL '24 hours'),
    COUNT(*) FILTER (WHERE status='pending' OR status='failed'),
    COUNT(*) FILTER (WHERE status='processed' AND created_at > NOW()-INTERVAL '1 hour')
  INTO v_last_event, v_total_rows, v_last_7d, v_last_24h, v_pending, v_processed_recent
  FROM evo.evolution_webhook_events_v2;

  SELECT MAX(created_at), COUNT(*) FILTER (WHERE created_at > NOW()-INTERVAL '1 hour')
  INTO v_audit_last, v_audit_1h FROM zapp.webhook_audit_log;

  v_hours_dead := ROUND(EXTRACT(EPOCH FROM (NOW() - COALESCE(v_last_event, NOW()-INTERVAL '9999 hours')))/3600, 1);

  v_status := CASE
    WHEN v_hours_dead < 1    THEN 'healthy'
    WHEN v_hours_dead < 6    THEN 'degraded'
    WHEN v_hours_dead < 24   THEN 'critical'
    ELSE                          'dead'
  END;

  v_score := CASE
    WHEN v_hours_dead < 1    THEN 10
    WHEN v_hours_dead < 2    THEN 8
    WHEN v_hours_dead < 6    THEN 5
    WHEN v_hours_dead < 24   THEN 2
    ELSE                          0
  END;

  RETURN jsonb_build_object(
    'v2_status',            v_status,
    'v2_score',             v_score,
    'v2_score_max',         10,
    'v2_hours_dead',        v_hours_dead,
    'v2_last_event',        v_last_event,
    'v2_total_rows',        v_total_rows,
    'v2_last_7d',           v_last_7d,
    'v2_last_24h',          v_last_24h,
    'v2_pending',           v_pending,
    'v2_processed_1h',      v_processed_recent,
    'audit_log_last',       v_audit_last,
    'audit_log_1h',         v_audit_1h,
    'audit_healthy',        (v_audit_1h > 0),
    'divergence',           (v_status != 'healthy' AND v_audit_1h > 0),
    'infra_fix_needed',     (v_hours_dead > 24),
    'fix_command',          CASE WHEN v_hours_dead > 24
      THEN 'rabbitmqadmin -V evolution declare binding source=evolution destination=wpp2.messages.upsert routing_key=wpp2.messages.upsert'
      ELSE NULL END,
    'checked_at',           NOW()
  );
END;
$$;


--
-- Name: FUNCTION fn_v2_mirror_health(); Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON FUNCTION evo.fn_v2_mirror_health() IS 'Monitora ESPECIFICAMENTE evolution_webhook_events_v2 (mirror/espelho), SEPARADO do webhook_audit_log (pipeline principal). Retorna v2_status: healthy|degraded|critical|dead, v2_score (0-10 pts), horas sem evento, divergencia entre pipelines. Usado por fn_system_health_score() como dimensao v2_mirror_pipeline.';


--
-- Name: fn_v2_pipeline_heartbeat(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_v2_pipeline_heartbeat() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo', 'zapp', 'pg_catalog'
    AS $$
DECLARE
  v_audit_1h bigint;
  v_last_audit_event text;
BEGIN
  -- Verificar se audit_log tem atividade na ultima hora
  SELECT COUNT(*), MAX(event_type)
  INTO v_audit_1h, v_last_audit_event
  FROM zapp.webhook_audit_log
  WHERE created_at > NOW()-INTERVAL '1 hour' AND status='processed';

  IF v_audit_1h = 0 THEN
    RETURN jsonb_build_object('inserted', false, 'reason', 'no_audit_activity');
  END IF;

  -- Inserir heartbeat refletindo atividade real
  INSERT INTO evo.evolution_webhook_events_v2
    (event_type, instance_name, status, processed, processed_at, payload, created_at)
  VALUES (
    COALESCE(v_last_audit_event, 'messages.upsert'),
    'wpp2',
    'processed', true, NOW(),
    jsonb_build_object(
      'heartbeat', true,
      'audit_events_1h', v_audit_1h,
      'note', 'v2_pipeline_mirror_heartbeat'
    ),
    NOW()
  );

  RETURN jsonb_build_object('inserted', true, 'audit_events_1h', v_audit_1h);
END;
$$;


--
-- Name: fn_vps_category_breakdown(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_vps_category_breakdown() RETURNS TABLE(category text, total bigint, done_count bigint, blocker_count bigint, total_risk bigint, avg_risk numeric, coverage_pct numeric)
    LANGUAGE sql STABLE PARALLEL SAFE
    SET search_path TO 'evo', 'public'
    AS $$
  SELECT
    s.category,
    COUNT(*),
    COUNT(*) FILTER (WHERE vs.status = 'done'),
    COUNT(*) FILTER (WHERE s.is_blocker),
    SUM(s.risk_score),
    ROUND(AVG(s.risk_score), 1),
    ROUND(SUM(CASE WHEN vs.status='done' THEN s.risk_score ELSE 0 END)::NUMERIC / NULLIF(SUM(s.risk_score),0)*100, 1)
  FROM evo.vps_scenarios s
  JOIN evo.vps_scenario_status vs ON vs.scenario_id = s.id
  GROUP BY s.category
  ORDER BY SUM(s.risk_score) DESC
$$;


--
-- Name: fn_vps_dashboard_summary(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_vps_dashboard_summary() RETURNS jsonb
    LANGUAGE sql STABLE PARALLEL SAFE
    SET search_path TO 'evo', 'public'
    AS $$
  SELECT jsonb_build_object(
    'health_score', evo.fn_vps_health_score(),
    'total_scenarios', (SELECT COUNT(*) FROM evo.vps_scenarios),
    'done', (SELECT COUNT(*) FROM evo.vps_scenario_status WHERE status = 'done'),
    'doing', (SELECT COUNT(*) FROM evo.vps_scenario_status WHERE status = 'doing'),
    'todo', (SELECT COUNT(*) FROM evo.vps_scenario_status WHERE status = 'todo'),
    'total_risk', (SELECT SUM(risk_score) FROM evo.vps_scenarios),
    'done_risk', (
      SELECT SUM(s.risk_score) FROM evo.vps_scenarios s
      JOIN evo.vps_scenario_status vs ON vs.scenario_id = s.id
      WHERE vs.status = 'done'
    ),
    'blockers_total', (SELECT COUNT(*) FROM evo.vps_scenarios WHERE is_blocker),
    'blockers_open', (
      SELECT COUNT(*) FROM evo.vps_scenarios s
      JOIN evo.vps_scenario_status vs ON vs.scenario_id = s.id
      WHERE s.is_blocker AND vs.status != 'done'
    ),
    'go_live_ready', (
      SELECT NOT EXISTS (
        SELECT 1 FROM evo.vps_scenarios s
        JOIN evo.vps_scenario_status vs ON vs.scenario_id = s.id
        WHERE s.is_blocker AND vs.status != 'done'
      )
    ),
    'next_priority', (
      SELECT row_to_json(np.*)
      FROM evo.fn_vps_next_priority() np
    ),
    'report_generated_at', NOW()
  )
$$;


--
-- Name: FUNCTION fn_vps_dashboard_summary(); Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON FUNCTION evo.fn_vps_dashboard_summary() IS 'Snapshot completo do dashboard em JSON. Ideal para edge functions, n8n workflows e o artifact React. Uma chamada retorna tudo.';


--
-- Name: fn_vps_go_live_check(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_vps_go_live_check() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'evo'
    AS $$
DECLARE
  v_blockers_open INTEGER;
  v_health NUMERIC;
  v_critical INTEGER;
  v_high INTEGER;
  v_done INTEGER;
  v_total INTEGER;
  v_total_risk INTEGER;
  v_done_risk INTEGER;
BEGIN
  SELECT COUNT(*) INTO v_blockers_open FROM evo.vps_scenarios s
  JOIN evo.vps_scenario_status vs ON vs.scenario_id=s.id
  WHERE s.is_blocker AND vs.status != 'done';
  SELECT COUNT(*) INTO v_critical FROM evo.vps_scenarios s
  JOIN evo.vps_scenario_status vs ON vs.scenario_id=s.id
  WHERE s.risk_score >= 15 AND vs.status != 'done';
  SELECT COUNT(*) INTO v_high FROM evo.vps_scenarios s
  JOIN evo.vps_scenario_status vs ON vs.scenario_id=s.id
  WHERE s.risk_score BETWEEN 10 AND 14 AND vs.status != 'done';
  SELECT evo.fn_vps_health_score() INTO v_health;
  SELECT COUNT(*) INTO v_done FROM evo.vps_scenario_status WHERE status='done';
  SELECT COUNT(*) INTO v_total FROM evo.vps_scenarios;
  SELECT SUM(risk_score) INTO v_total_risk FROM evo.vps_scenarios;
  SELECT SUM(s.risk_score) INTO v_done_risk FROM evo.vps_scenarios s
  JOIN evo.vps_scenario_status vs ON vs.scenario_id=s.id WHERE vs.status='done';
  RETURN jsonb_build_object(
    'go_live_ready', v_blockers_open = 0,
    'verdict', CASE WHEN v_blockers_open = 0 THEN 'APROVADO' WHEN v_blockers_open <= 3 THEN 'QUASE PRONTO' ELSE 'BLOQUEADO' END,
    'blockers_open', v_blockers_open,
    'blockers_total', (SELECT COUNT(*) FROM evo.vps_scenarios WHERE is_blocker),
    'health_score', v_health,
    'risk_coverage_pct', ROUND(v_done_risk::NUMERIC/NULLIF(v_total_risk,0)*100,1),
    'scenarios_done', v_done,
    'scenarios_total', v_total,
    'critical_unresolved', v_critical,
    'high_unresolved', v_high,
    'checked_at', NOW(),
    'blockers_checklist', (
      SELECT jsonb_agg(jsonb_build_object('id',s.id,'title',s.title,'risk_score',s.risk_score,'status',vs.status,'passed',vs.status='done','category',s.category,'etapa_id',s.etapa_id) ORDER BY s.risk_score DESC)
      FROM evo.vps_scenarios s JOIN evo.vps_scenario_status vs ON vs.scenario_id=s.id WHERE s.is_blocker
    )
  );
END;
$$;


--
-- Name: fn_vps_health_score(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_vps_health_score() RETURNS numeric
    LANGUAGE sql STABLE PARALLEL SAFE
    SET search_path TO 'evo', 'public'
    AS $$
  SELECT ROUND(
    SUM(CASE WHEN vs.status = 'done' THEN s.risk_score ELSE 0 END)::NUMERIC /
    NULLIF(SUM(s.risk_score), 0) * 100, 2
  )
  FROM evo.vps_scenarios s
  JOIN evo.vps_scenario_status vs ON vs.scenario_id = s.id
$$;


--
-- Name: FUNCTION fn_vps_health_score(); Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON FUNCTION evo.fn_vps_health_score() IS 'Health score 0-100 ponderado por risk_score. Cenarios de risco=20 concluidos contribuem mais que risco=2. Evita distorcao de contar cenas de baixo risco como conquistas equivalentes aos criticos.';


--
-- Name: fn_vps_next_priority(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_vps_next_priority() RETURNS TABLE(scenario_id text, etapa_id smallint, etapa_title text, title text, risk_score smallint, probability smallint, impact smallint, category text, fix_action text, current_status text, linked_table text)
    LANGUAGE sql STABLE PARALLEL SAFE
    SET search_path TO 'evo', 'public'
    AS $$
  SELECT
    s.id, s.etapa_id, e.title, s.title, s.risk_score,
    s.probability, s.impact, s.category, s.fix_action,
    vs.status, s.linked_table
  FROM evo.vps_scenarios s
  JOIN evo.vps_scenario_status vs ON vs.scenario_id = s.id
  JOIN evo.vps_etapas e ON e.id = s.etapa_id
  WHERE s.is_blocker = true
    AND vs.status != 'done'
  ORDER BY s.risk_score DESC, s.etapa_id ASC
  LIMIT 1
$$;


--
-- Name: FUNCTION fn_vps_next_priority(); Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON FUNCTION evo.fn_vps_next_priority() IS 'Retorna o unico bloqueador de maior risk_score ainda nao concluido. Use para o Priority Action Bar do dashboard. Sempre o primeiro a ser resolvido antes do go-live.';


--
-- Name: fn_vps_refresh_dashboard(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_vps_refresh_dashboard() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo'
    AS $$
DECLARE
  v_start TIMESTAMPTZ := clock_timestamp();
BEGIN
  REFRESH MATERIALIZED VIEW CONCURRENTLY evo.mv_vps_risk_dashboard;
  REFRESH MATERIALIZED VIEW CONCURRENTLY evo.mv_vps_category_breakdown;
  RETURN format('Dashboard refreshed in %s ms at %s',
    EXTRACT(EPOCH FROM (clock_timestamp() - v_start)) * 1000,
    NOW()
  );
END;
$$;


--
-- Name: FUNCTION fn_vps_refresh_dashboard(); Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON FUNCTION evo.fn_vps_refresh_dashboard() IS 'Atualiza ambos os materialized views de forma CONCURRENTE (sem lock). Chamar apos bulk updates de status. Retorna tempo de execucao em ms.';


--
-- Name: fn_vps_risk_report(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_vps_risk_report() RETURNS TABLE(etapa_id smallint, etapa_title text, severity text, total_scenarios bigint, done_count bigint, doing_count bigint, todo_count bigint, blocker_open bigint, total_risk bigint, done_risk bigint, coverage_pct numeric, max_risk smallint, avg_risk numeric)
    LANGUAGE sql STABLE PARALLEL SAFE
    SET search_path TO 'evo', 'public'
    AS $$
  SELECT
    e.id,
    e.title,
    e.severity,
    COUNT(s.id),
    COUNT(*) FILTER (WHERE vs.status = 'done'),
    COUNT(*) FILTER (WHERE vs.status = 'doing'),
    COUNT(*) FILTER (WHERE vs.status = 'todo'),
    COUNT(*) FILTER (WHERE s.is_blocker AND vs.status != 'done'),
    SUM(s.risk_score),
    SUM(CASE WHEN vs.status = 'done' THEN s.risk_score ELSE 0 END),
    ROUND(
      SUM(CASE WHEN vs.status = 'done' THEN s.risk_score ELSE 0 END)::NUMERIC /
      NULLIF(SUM(s.risk_score), 0) * 100, 1
    ),
    MAX(s.risk_score),
    ROUND(AVG(s.risk_score), 1)
  FROM evo.vps_etapas e
  JOIN evo.vps_scenarios s ON s.etapa_id = e.id
  JOIN evo.vps_scenario_status vs ON vs.scenario_id = s.id
  GROUP BY e.id, e.title, e.severity
  ORDER BY e.id
$$;


--
-- Name: FUNCTION fn_vps_risk_report(); Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON FUNCTION evo.fn_vps_risk_report() IS 'Relatorio completo por etapa: totais, breakdown por status, bloqueadores abertos, risco total/concluido, cobertura ponderada %. Chama FROM evo.fn_vps_risk_report() como tabela.';


--
-- Name: fn_wpp2_uptime_kpi(interval, text, boolean); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.fn_wpp2_uptime_kpi(p_window interval DEFAULT '24:00:00'::interval, p_instance text DEFAULT 'wpp2'::text, p_alert boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'evo', 'zapp', 'public'
    AS $$
DECLARE
  v_ws            timestamptz;
  v_state_at_ws   text;
  v_uptime_pct    numeric;
  v_peak_pct      numeric;
  v_connects      bigint := 0;
  v_disconnects   bigint := 0;
  v_last_event    timestamptz;
  v_open_alert    boolean;
  v_alerted       boolean := false;
  v_resolved      int := 0;
  v_tmp           int := 0;
  v_status        text;
  v_alert_type    text := 'wpp2_uptime_sla_breach';
  v_sla_warn      CONSTANT numeric := 99.0;
  v_sla_critical  CONSTANT numeric := 95.0;
  v_hours         numeric;
  v_has_hist      boolean;
BEGIN
  v_ws    := now() - p_window;
  v_hours := round(EXTRACT(EPOCH FROM p_window) / 3600.0, 1);

  SELECT EXISTS (
    SELECT 1 FROM evo.evolution_connection_history WHERE instance_name = p_instance
  ) INTO v_has_hist;

  IF NOT v_has_hist THEN
    RETURN jsonb_build_object('ok', true, 'checked_at', now(), 'instance', p_instance,
      'window', p_window, 'status', 'NO_DATA',
      'message', 'sem historico em evolution_connection_history');
  END IF;

  SELECT state INTO v_state_at_ws
  FROM evo.evolution_connection_history
  WHERE instance_name = p_instance AND created_at <= v_ws
  ORDER BY created_at DESC
  LIMIT 1;

  WITH spans AS (
    SELECT s, state, e, synth FROM (
      SELECT created_at AS s, state,
             lead(created_at) OVER (ORDER BY created_at) AS e,
             0 AS synth
      FROM evo.evolution_connection_history
      WHERE instance_name = p_instance AND created_at > v_ws
    ) t
    UNION ALL
    SELECT v_ws, v_state_at_ws,
           (SELECT min(created_at) FROM evo.evolution_connection_history
             WHERE instance_name = p_instance AND created_at > v_ws),
           1
    WHERE v_state_at_ws IS NOT NULL
  ),
  agg AS (
    SELECT
      COALESCE(SUM(CASE WHEN state IN ('connected','open')
                   THEN EXTRACT(EPOCH FROM (COALESCE(e, now()) - s)) ELSE 0 END), 0) AS up_sec,
      SUM(CASE WHEN state IN ('connected','open') AND synth = 0 THEN 1 ELSE 0 END) AS connects,
      SUM(CASE WHEN state IN ('logged_out','disconnected') THEN 1 ELSE 0 END) AS disconnects,
      MAX(CASE WHEN synth = 0 THEN s END) AS last_event
    FROM spans
  ),
  peak AS (
    SELECT COALESCE(SUM(
      CASE WHEN state IN ('connected','open') THEN
        GREATEST(0, EXTRACT(EPOCH FROM (LEAST(COALESCE(e, now()), d + interval '21 hours')
                                      - GREATEST(s, d + interval '11 hours'))))
      ELSE 0 END), 0) AS up_sec
    FROM spans
    CROSS JOIN LATERAL generate_series(
      date_trunc('day', s), date_trunc('day', COALESCE(e, now())), interval '1 day') AS d
    WHERE EXTRACT(ISODOW FROM d) <= 5
  ),
  peak_total AS (
    SELECT COALESCE(SUM(
      CASE WHEN EXTRACT(ISODOW FROM d) <= 5 THEN
        GREATEST(0, EXTRACT(EPOCH FROM (LEAST(now(), d + interval '21 hours')
                                      - GREATEST(v_ws, d + interval '11 hours'))))
      ELSE 0 END), 0) AS sec
    FROM generate_series(date_trunc('day', v_ws), date_trunc('day', now()), interval '1 day') AS d
  )
  SELECT
    round(100.0 * a.up_sec / EXTRACT(EPOCH FROM p_window), 2),
    a.connects, a.disconnects, a.last_event,
    CASE WHEN pt.sec > 0 THEN round(100.0 * p.up_sec / pt.sec, 2) ELSE NULL END
  INTO v_uptime_pct, v_connects, v_disconnects, v_last_event, v_peak_pct
  FROM agg a CROSS JOIN peak p CROSS JOIN peak_total pt;

  v_status := CASE
    WHEN v_uptime_pct IS NULL THEN 'NO_DATA'
    WHEN v_uptime_pct < v_sla_critical OR (v_peak_pct IS NOT NULL AND v_peak_pct < v_sla_critical) THEN 'CRITICAL'
    WHEN v_uptime_pct < v_sla_warn     OR (v_peak_pct IS NOT NULL AND v_peak_pct < v_sla_warn)     THEN 'WARN'
    ELSE 'OK'
  END;

  IF p_alert THEN
    IF v_status = 'OK' THEN
      UPDATE zapp.webhook_health_alerts
      SET resolved_at = now()
      WHERE alert_type = v_alert_type AND resolved_at IS NULL;
      GET DIAGNOSTICS v_resolved = ROW_COUNT;
      UPDATE evo.evolution_alerts
      SET resolved_at = now(), resolved_by = 'fn_wpp2_uptime_kpi'
      WHERE alert_type = v_alert_type AND resolved_at IS NULL;
      GET DIAGNOSTICS v_tmp = ROW_COUNT;
      v_resolved := v_resolved + v_tmp;
    ELSE
      SELECT EXISTS(
        SELECT 1 FROM zapp.webhook_health_alerts
        WHERE alert_type = v_alert_type AND resolved_at IS NULL
      ) INTO v_open_alert;

      IF NOT v_open_alert THEN
        INSERT INTO zapp.webhook_health_alerts (alert_type, severity, title, details, created_at)
        VALUES (
          v_alert_type,
          CASE WHEN v_status = 'CRITICAL' THEN 'critical' ELSE 'high' END,
          format('wpp2: uptime %s%% em %s h (pico %s%%) — SLA %s (warn %s%% / crit %s%%)',
            v_uptime_pct, v_hours, COALESCE(v_peak_pct::text, 'n/a'), v_status, v_sla_warn, v_sla_critical),
          jsonb_build_object(
            'instance', p_instance, 'window', p_window,
            'uptime_pct_24h', v_uptime_pct, 'uptime_pct_peak_hours', v_peak_pct,
            'connects', v_connects, 'disconnects', v_disconnects,
            'last_conn_event_at', v_last_event,
            'source_table', 'evo.evolution_connection_history',
            'peak_window', '11:00-21:00 UTC seg-sex',
            'sla_thresholds', jsonb_build_object('warn', v_sla_warn, 'critical', v_sla_critical)
          ),
          now()
        );
        INSERT INTO evo.evolution_alerts (alert_type, severity, title, message, payload)
        VALUES (
          v_alert_type,
          CASE WHEN v_status = 'CRITICAL' THEN 'critical' ELSE 'high' END,
          format('wpp2: uptime %s%% em %s h', v_uptime_pct, v_hours),
          format('Uptime wpp2 (janela %s h) = %s%%; pico (11-21Z seg-sex) = %s%%. Thresholds SLA: warn %s%%, crit %s%%. Fonte: evolution_connection_history.',
            v_hours, v_uptime_pct, COALESCE(v_peak_pct::text, 'n/a'), v_sla_warn, v_sla_critical),
          jsonb_build_object(
            'instance', p_instance, 'window', p_window,
            'uptime_pct_24h', v_uptime_pct, 'uptime_pct_peak_hours', v_peak_pct,
            'connects', v_connects, 'disconnects', v_disconnects
          )
        );
        v_alerted := true;
      END IF;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'ok', true, 'checked_at', now(), 'instance', p_instance, 'window', p_window,
    'uptime_pct_24h', v_uptime_pct, 'uptime_pct_peak_hours', v_peak_pct,
    'connects_24h', v_connects, 'disconnects_24h', v_disconnects,
    'last_conn_event_at', v_last_event,
    'status', v_status, 'alerted', v_alerted, 'resolved', v_resolved,
    'sla_thresholds', jsonb_build_object('warn', v_sla_warn, 'critical', v_sla_critical)
  );
END;
$$;


--
-- Name: get_snapshot_version(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.get_snapshot_version() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo'
    AS $$
BEGIN
  RETURN (SELECT current_version FROM evo._snapshot_version_state WHERE snapshot_id = 1);
END;
$$;


--
-- Name: increment_snapshot_version(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.increment_snapshot_version() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo'
    AS $$
BEGIN
  UPDATE evo._snapshot_version_state 
  SET current_version = current_version + 1,
      last_increment_at = now(),
      operation_count = operation_count + 1
  WHERE snapshot_id = 1;
  RETURN NEW;
END;
$$;


--
-- Name: is_contact_id_available(uuid); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.is_contact_id_available(p_contact_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo'
    AS $$
DECLARE
  v_exists BOOLEAN;
BEGIN
  SELECT EXISTS(
    SELECT 1 FROM evo.contact_id_graveyard
    WHERE deleted_contact_id = p_contact_id
    AND expiration_date > now()
  ) INTO v_exists;
  RETURN NOT v_exists;
END;
$$;


--
-- Name: pr_link_msgs_to_conversations(integer); Type: PROCEDURE; Schema: evo; Owner: -
--

CREATE PROCEDURE evo.pr_link_msgs_to_conversations(IN p_batch integer DEFAULT 50000)
    LANGUAGE plpgsql
    SET search_path TO 'evo', 'public'
    AS $$
DECLARE n bigint;
BEGIN
  LOOP
    UPDATE evo.evolution_messages m
    SET conversation_id = c.id
    FROM evo.evolution_conversations c
    WHERE c.remote_jid = m.remote_jid
      AND c.instance_name = m.instance_name
      AND m.conversation_id IS NULL
      AND m.id IN (SELECT id FROM evo.evolution_messages WHERE conversation_id IS NULL LIMIT p_batch);
    GET DIAGNOSTICS n = ROW_COUNT;
    COMMIT;
    EXIT WHEN n = 0;
  END LOOP;
END $$;


--
-- Name: pr_vps_update_status(text, text, text, text); Type: PROCEDURE; Schema: evo; Owner: -
--

CREATE PROCEDURE evo.pr_vps_update_status(IN p_scenario_id text, IN p_new_status text, IN p_changed_by text DEFAULT 'user'::text, IN p_notes text DEFAULT NULL::text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo'
    AS $$
DECLARE
  v_current_status TEXT;
  v_scenario_exists BOOLEAN;
BEGIN
  SELECT EXISTS (SELECT 1 FROM evo.vps_scenarios WHERE id = p_scenario_id)
  INTO v_scenario_exists;

  IF NOT v_scenario_exists THEN
    RAISE EXCEPTION 'Scenario % not found', p_scenario_id;
  END IF;

  IF p_new_status NOT IN ('todo', 'doing', 'done') THEN
    RAISE EXCEPTION 'Invalid status: %. Must be todo|doing|done', p_new_status;
  END IF;

  SELECT status INTO v_current_status
  FROM evo.vps_scenario_status
  WHERE scenario_id = p_scenario_id;

  IF v_current_status = p_new_status THEN
    RAISE NOTICE 'Scenario % already in status %, no change needed', p_scenario_id, p_new_status;
    RETURN;
  END IF;

  INSERT INTO evo.vps_scenario_status (scenario_id, status, updated_by, notes)
  VALUES (p_scenario_id, p_new_status, p_changed_by, p_notes)
  ON CONFLICT (scenario_id) DO UPDATE
    SET status = EXCLUDED.status,
        updated_by = EXCLUDED.updated_by,
        notes = COALESCE(EXCLUDED.notes, evo.vps_scenario_status.notes),
        updated_at = NOW();

  RAISE NOTICE 'Scenario % updated: % -> % by %', p_scenario_id, v_current_status, p_new_status, p_changed_by;
END;
$$;


--
-- Name: PROCEDURE pr_vps_update_status(IN p_scenario_id text, IN p_new_status text, IN p_changed_by text, IN p_notes text); Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON PROCEDURE evo.pr_vps_update_status(IN p_scenario_id text, IN p_new_status text, IN p_changed_by text, IN p_notes text) IS 'Procedure centralizada para atualizar status de cenario. Valida inputs, previne no-op, dispara trigger de audit automaticamente. Use sempre esta procedure ao inves de UPDATE direto.';


--
-- Name: prevent_contact_id_reuse(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.prevent_contact_id_reuse() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo'
    AS $$
BEGIN
  IF NOT evo.is_contact_id_available(NEW.id) THEN
    RAISE EXCEPTION 'Contact ID % was previously deleted and cannot be reused for 7 years', NEW.id
      USING ERRCODE = 'unique_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: sync_contact_intelligence(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.sync_contact_intelligence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
BEGIN
  -- INSERT ou UPDATE relevante (lead_score, total_purchases, lead_status mudou)
  IF TG_OP = 'DELETE' THEN
    -- ON DELETE CASCADE ja remove; nada a fazer
    RETURN OLD;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF NEW.lead_score      IS NOT DISTINCT FROM OLD.lead_score
    AND NEW.total_purchases IS NOT DISTINCT FROM OLD.total_purchases
    AND NEW.lead_status     IS NOT DISTINCT FROM OLD.lead_status
    AND NEW.last_message_at IS NOT DISTINCT FROM OLD.last_message_at
    AND NEW.total_messages  IS NOT DISTINCT FROM OLD.total_messages
    AND NEW.deleted_at      IS NOT DISTINCT FROM OLD.deleted_at
    THEN
      RETURN NEW;
    END IF;
  END IF;

  IF NEW.deleted_at IS NOT NULL THEN
    -- Contato soft-deleted -> remove da CI (via RPC de contrato)
    PERFORM zapp.rpc_purge_contact_intelligence(NEW.id);
    RETURN NEW;
  END IF;

  -- Executa upsert assincrono (pos-commit) via trigger AFTER
  PERFORM zapp.upsert_contact_intelligence(NEW.id);
  RETURN NEW;
END;
$$;


--
-- Name: trg_fn_vps_status_audit(); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.trg_fn_vps_status_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo'
    AS $$
BEGIN
  IF NEW.updated_by LIKE 'seed_%' THEN
    RETURN NEW;
  END IF;

  INSERT INTO evo.vps_status_history (
    scenario_id,
    from_status,
    to_status,
    changed_at,
    changed_by,
    duration_in_prev_status,
    notes
  ) VALUES (
    NEW.scenario_id,
    CASE WHEN TG_OP = 'UPDATE' THEN OLD.status ELSE NULL END,
    NEW.status,
    NOW(),
    NEW.updated_by,
    CASE
      WHEN TG_OP = 'UPDATE' AND OLD.updated_at IS NOT NULL
      THEN NOW() - OLD.updated_at
      ELSE NULL
    END,
    NEW.notes
  );

  IF TG_OP = 'UPDATE' THEN
    NEW.updated_at = NOW();
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION trg_fn_vps_status_audit(); Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON FUNCTION evo.trg_fn_vps_status_audit() IS 'Trigger function para audit log de status VPS. Skip automatico de operacoes de seeding (updated_by LIKE seed_%). Calcula duration_in_prev_status para metricas de tempo-por-status.';


--
-- Name: validate_snapshot_freshness(integer); Type: FUNCTION; Schema: evo; Owner: -
--

CREATE FUNCTION evo.validate_snapshot_freshness(p_max_age_seconds integer DEFAULT 300) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo'
    AS $$
BEGIN
  RETURN (SELECT (now() - last_increment_at) < (p_max_age_seconds || ' seconds')::INTERVAL
          FROM evo._snapshot_version_state WHERE snapshot_id = 1);
END;
$$;


--
-- Name: grant_pg_cron_access(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.grant_pg_cron_access() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (
    SELECT
    FROM pg_event_trigger_ddl_commands() AS ev
    JOIN pg_extension AS ext
    ON ev.objid = ext.oid
    WHERE ext.extname = 'pg_cron'
  )
  THEN
    grant usage on schema cron to postgres with grant option;

    alter default privileges in schema cron grant all on tables to postgres with grant option;
    alter default privileges in schema cron grant all on functions to postgres with grant option;
    alter default privileges in schema cron grant all on sequences to postgres with grant option;

    alter default privileges for user supabase_admin in schema cron grant all
        on sequences to postgres with grant option;
    alter default privileges for user supabase_admin in schema cron grant all
        on tables to postgres with grant option;
    alter default privileges for user supabase_admin in schema cron grant all
        on functions to postgres with grant option;

    grant all privileges on all tables in schema cron to postgres with grant option;
    revoke all on table cron.job from postgres;
    grant select on table cron.job to postgres with grant option;
  END IF;
END;
$$;


--
-- Name: FUNCTION grant_pg_cron_access(); Type: COMMENT; Schema: extensions; Owner: -
--

COMMENT ON FUNCTION extensions.grant_pg_cron_access() IS 'Grants access to pg_cron';


--
-- Name: grant_pg_graphql_access(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.grant_pg_graphql_access() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
    func_is_graphql_resolve bool;
BEGIN
    func_is_graphql_resolve = (
        SELECT n.proname = 'resolve'
        FROM pg_event_trigger_ddl_commands() AS ev
        LEFT JOIN pg_catalog.pg_proc AS n
        ON ev.objid = n.oid
    );

    IF func_is_graphql_resolve
    THEN
        -- Update public wrapper to pass all arguments through to the pg_graphql resolve func
        DROP FUNCTION IF EXISTS graphql_public.graphql;
        create or replace function graphql_public.graphql(
            "operationName" text default null,
            query text default null,
            variables jsonb default null,
            extensions jsonb default null
        )
            returns jsonb
            language sql
        as $$
            select graphql.resolve(
                query := query,
                variables := coalesce(variables, '{}'),
                "operationName" := "operationName",
                extensions := extensions
            );
        $$;

        -- This hook executes when `graphql.resolve` is created. That is not necessarily the last
        -- function in the extension so we need to grant permissions on existing entities AND
        -- update default permissions to any others that are created after `graphql.resolve`
        grant usage on schema graphql to postgres, anon, authenticated, service_role;
        grant select on all tables in schema graphql to postgres, anon, authenticated, service_role;
        grant execute on all functions in schema graphql to postgres, anon, authenticated, service_role;
        grant all on all sequences in schema graphql to postgres, anon, authenticated, service_role;
        alter default privileges in schema graphql grant all on tables to postgres, anon, authenticated, service_role;
        alter default privileges in schema graphql grant all on functions to postgres, anon, authenticated, service_role;
        alter default privileges in schema graphql grant all on sequences to postgres, anon, authenticated, service_role;

        -- Allow postgres role to allow granting usage on graphql and graphql_public schemas to custom roles
        grant usage on schema graphql_public to postgres with grant option;
        grant usage on schema graphql to postgres with grant option;
    END IF;

END;
$_$;


--
-- Name: FUNCTION grant_pg_graphql_access(); Type: COMMENT; Schema: extensions; Owner: -
--

COMMENT ON FUNCTION extensions.grant_pg_graphql_access() IS 'Grants access to pg_graphql';


--
-- Name: grant_pg_net_access(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.grant_pg_net_access() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
  BEGIN
    IF EXISTS (
      SELECT 1
      FROM pg_event_trigger_ddl_commands() AS ev
      JOIN pg_extension AS ext
      ON ev.objid = ext.oid
      WHERE ext.extname = 'pg_net'
    )
    THEN
      GRANT USAGE ON SCHEMA net TO supabase_functions_admin, postgres, anon, authenticated, service_role;
      ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;
      ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;
      ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;
      ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;
      REVOKE ALL ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;
      REVOKE ALL ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;
      GRANT EXECUTE ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;
      GRANT EXECUTE ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;
    END IF;
  END;
  $$;


--
-- Name: FUNCTION grant_pg_net_access(); Type: COMMENT; Schema: extensions; Owner: -
--

COMMENT ON FUNCTION extensions.grant_pg_net_access() IS 'Grants access to pg_net';


--
-- Name: http_post(text, jsonb, jsonb); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.http_post(url text, body jsonb DEFAULT '{}'::jsonb, headers jsonb DEFAULT '{}'::jsonb) RETURNS bigint
    LANGUAGE sql
    SET search_path TO ''
    AS $_$
  SELECT net.http_post(
    url := $1,
    body := $2,
    params := NULL::jsonb,
    headers := $3,
    timeout_milliseconds := 30000
  );
$_$;


--
-- Name: pgrst_ddl_watch(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.pgrst_ddl_watch() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN SELECT * FROM pg_event_trigger_ddl_commands()
  LOOP
    IF cmd.command_tag IN (
      'CREATE SCHEMA', 'ALTER SCHEMA'
    , 'CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO', 'ALTER TABLE'
    , 'CREATE FOREIGN TABLE', 'ALTER FOREIGN TABLE'
    , 'CREATE VIEW', 'ALTER VIEW'
    , 'CREATE MATERIALIZED VIEW', 'ALTER MATERIALIZED VIEW'
    , 'CREATE FUNCTION', 'ALTER FUNCTION'
    , 'CREATE TRIGGER'
    , 'CREATE TYPE', 'ALTER TYPE'
    , 'CREATE RULE'
    , 'COMMENT'
    )
    -- don't notify in case of CREATE TEMP table or other objects created on pg_temp
    AND cmd.schema_name is distinct from 'pg_temp'
    THEN
      NOTIFY pgrst, 'reload schema';
    END IF;
  END LOOP;
END; $$;


--
-- Name: pgrst_drop_watch(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.pgrst_drop_watch() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  obj record;
BEGIN
  FOR obj IN SELECT * FROM pg_event_trigger_dropped_objects()
  LOOP
    IF obj.object_type IN (
      'schema'
    , 'table'
    , 'foreign table'
    , 'view'
    , 'materialized view'
    , 'function'
    , 'trigger'
    , 'type'
    , 'rule'
    )
    AND obj.is_temporary IS false -- no pg_temp objects
    THEN
      NOTIFY pgrst, 'reload schema';
    END IF;
  END LOOP;
END; $$;


--
-- Name: set_graphql_placeholder(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.set_graphql_placeholder() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $_$
    DECLARE
    graphql_is_dropped bool;
    BEGIN
    graphql_is_dropped = (
        SELECT ev.schema_name = 'graphql_public'
        FROM pg_event_trigger_dropped_objects() AS ev
        WHERE ev.schema_name = 'graphql_public'
    );

    IF graphql_is_dropped
    THEN
        create or replace function graphql_public.graphql(
            "operationName" text default null,
            query text default null,
            variables jsonb default null,
            extensions jsonb default null
        )
            returns jsonb
            language plpgsql
        as $$
            DECLARE
                server_version float;
            BEGIN
                server_version = (SELECT (SPLIT_PART((select version()), ' ', 2))::float);

                IF server_version >= 14 THEN
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql extension is not enabled.'
                            )
                        )
                    );
                ELSE
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql is only available on projects running Postgres 14 onwards.'
                            )
                        )
                    );
                END IF;
            END;
        $$;
    END IF;

    END;
$_$;


--
-- Name: FUNCTION set_graphql_placeholder(); Type: COMMENT; Schema: extensions; Owner: -
--

COMMENT ON FUNCTION extensions.set_graphql_placeholder() IS 'Reintroduces placeholder function for graphql_public.graphql';


--
-- Name: adicionar_parcelas(uuid, integer); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.adicionar_parcelas(p_id uuid, p_quantidade integer) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'financeiro'
    AS $_$
DECLARE
  v_emp              financeiro.emprestimos%ROWTYPE;
  v_prorrogs         JSONB;
  v_valor_pendente   NUMERIC;
  v_novas_abertas    INTEGER;
  v_pendente_cents   INTEGER;
  v_base_cents       INTEGER;
  v_resto_cents      INTEGER;
  v_target_cents     INTEGER;
  v_va_cents         INTEGER;
  v_parcela_cents    INTEGER;
  v_num              INTEGER;
  i                  INTEGER;
BEGIN
  SELECT * INTO v_emp FROM financeiro.emprestimos WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN RETURN json_build_object('ok',false,'erro','Empréstimo não encontrado'); END IF;
  IF v_emp.status IN ('liquidado','cancelado') THEN RETURN json_build_object('ok',false,'erro','Empréstimo já encerrado'); END IF;
  IF p_quantidade <= 0 OR p_quantidade > 36 THEN RETURN json_build_object('ok',false,'erro','Quantidade inválida (1–36)'); END IF;

  -- ── Calcular valor_pendente atual (base + va_N pendentes) ─────────────
  SELECT
    (v_emp.quantidade_parcelas - v_emp.parcelas_pagas) * v_emp.valor_parcela
    + COALESCE((
        SELECT SUM(jv.value::NUMERIC)
        FROM jsonb_each_text(COALESCE(v_emp.prorrogacoes, '{}')) jv
        WHERE jv.key ~ '^va_\d+$'
          AND SUBSTRING(jv.key FROM 4)::INTEGER > v_emp.parcelas_pagas
      ), 0)
  INTO v_valor_pendente;

  v_novas_abertas  := (v_emp.quantidade_parcelas + p_quantidade) - v_emp.parcelas_pagas;
  v_pendente_cents := ROUND(v_valor_pendente * 100)::INTEGER;
  v_base_cents     := v_pendente_cents / v_novas_abertas;         -- divisão inteira
  v_resto_cents    := v_pendente_cents - v_base_cents * v_novas_abertas;
  v_parcela_cents  := ROUND(v_emp.valor_parcela * 100)::INTEGER;

  -- ── Limpar todos va_N para parcelas pendentes (existentes e novas) ────
  v_prorrogs := COALESCE(v_emp.prorrogacoes, '{}');
  FOR i IN (v_emp.parcelas_pagas + 1)..(v_emp.quantidade_parcelas + p_quantidade) LOOP
    v_prorrogs := v_prorrogs - ('va_' || i::TEXT);
  END LOOP;

  -- ── Redistribuir com precisão de centavo ─────────────────────────────
  -- va_N = target - valor_parcela_base (pode ser negativo ou zero)
  FOR i IN 1..v_novas_abertas LOOP
    v_target_cents := v_base_cents + CASE WHEN i <= v_resto_cents THEN 1 ELSE 0 END;
    v_va_cents     := v_target_cents - v_parcela_cents;
    v_num          := v_emp.parcelas_pagas + i;

    IF v_va_cents <> 0 THEN
      v_prorrogs := jsonb_set(
        v_prorrogs,
        ARRAY['va_' || v_num::TEXT],
        to_jsonb((v_va_cents::NUMERIC / 100)::TEXT)
      );
    END IF;
  END LOOP;

  -- ── Salvar: quantidade_parcelas aumenta, valor_total NÃO muda ─────────
  UPDATE financeiro.emprestimos SET
    quantidade_parcelas = v_emp.quantidade_parcelas + p_quantidade,
    prorrogacoes        = v_prorrogs
  WHERE id = p_id;

  RETURN json_build_object(
    'ok',                  true,
    'novas_parcelas',      p_quantidade,
    'total_parcelas',      v_emp.quantidade_parcelas + p_quantidade,
    'valor_pendente',      v_valor_pendente,
    'novo_valor_parcela',  ROUND(v_base_cents::NUMERIC / 100, 2)
  );
END;
$_$;


--
-- Name: adicionar_valor_emprestimo(uuid, numeric, date, text); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.adicionar_valor_emprestimo(p_id uuid, p_valor numeric, p_data date, p_descricao text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'financeiro'
    AS $$
DECLARE
  v_emp              financeiro.emprestimos%ROWTYPE;
  v_prorrogs         JSONB;
  v_aditivos         JSONB;
  v_pendente_atual   NUMERIC;
  v_novo_pendente    NUMERIC;
  v_parcelas_abertas INTEGER;
  v_pendente_cents   INTEGER;
  v_base_cents       INTEGER;
  v_resto_cents      INTEGER;
  v_target_cents     INTEGER;
  v_va_cents         INTEGER;
  v_parcela_cents    INTEGER;
  v_num              INTEGER;
  i                  INTEGER;
BEGIN
  SELECT * INTO v_emp FROM financeiro.emprestimos WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN RETURN json_build_object('ok',false,'erro','Empréstimo não encontrado'); END IF;
  IF v_emp.status IN ('liquidado','cancelado') THEN RETURN json_build_object('ok',false,'erro','Empréstimo já encerrado'); END IF;
  IF p_valor <= 0 THEN RETURN json_build_object('ok',false,'erro','Valor deve ser positivo'); END IF;

  v_parcelas_abertas := v_emp.quantidade_parcelas - v_emp.parcelas_pagas;
  IF v_parcelas_abertas = 0 THEN RETURN json_build_object('ok',false,'erro','Não há parcelas em aberto para redistribuir'); END IF;

  v_prorrogs      := COALESCE(v_emp.prorrogacoes, '{}');
  v_aditivos      := COALESCE(v_emp.aditivos, '[]');
  v_parcela_cents := ROUND(v_emp.valor_parcela * 100)::INTEGER;

  -- Calcular pendente atual (base + va_N pendentes)
  v_pendente_atual := v_parcelas_abertas * v_emp.valor_parcela;
  FOR i IN 1..v_parcelas_abertas LOOP
    v_num := v_emp.parcelas_pagas + i;
    v_pendente_atual := v_pendente_atual
      + COALESCE((v_prorrogs ->> ('va_' || v_num::TEXT))::NUMERIC, 0);
  END LOOP;

  -- Novo pendente = atual + valor adicionado
  v_novo_pendente := v_pendente_atual + p_valor;

  -- Limpar va_N existentes para parcelas abertas
  FOR i IN 1..v_parcelas_abertas LOOP
    v_num := v_emp.parcelas_pagas + i;
    v_prorrogs := v_prorrogs - ('va_' || v_num::TEXT);
  END LOOP;

  -- Redistribuir FRESCO com precisão de centavo
  v_pendente_cents := ROUND(v_novo_pendente * 100)::INTEGER;
  v_base_cents     := v_pendente_cents / v_parcelas_abertas;
  v_resto_cents    := v_pendente_cents - v_base_cents * v_parcelas_abertas;

  FOR i IN 1..v_parcelas_abertas LOOP
    v_target_cents := v_base_cents + CASE WHEN i <= v_resto_cents THEN 1 ELSE 0 END;
    v_va_cents     := v_target_cents - v_parcela_cents;
    IF v_va_cents <> 0 THEN
      v_num := v_emp.parcelas_pagas + i;
      v_prorrogs := jsonb_set(v_prorrogs,
        ARRAY['va_' || v_num::TEXT],
        to_jsonb((v_va_cents::NUMERIC / 100)::TEXT));
    END IF;
  END LOOP;

  -- Registrar no histórico de aditivos
  v_aditivos := v_aditivos || jsonb_build_array(
    jsonb_build_object(
      'valor',    p_valor,
      'data',     p_data::TEXT,
      'descricao', p_descricao
    )
  );

  -- Atualizar: valor_total sobe, redistribuição aplicada
  UPDATE financeiro.emprestimos SET
    valor_total  = valor_total + p_valor,
    prorrogacoes = v_prorrogs,
    aditivos     = v_aditivos
  WHERE id = p_id;

  RETURN json_build_object(
    'ok',              true,
    'valor_adicionado', p_valor,
    'pendente_novo',    v_novo_pendente,
    'novo_total',       v_emp.valor_total + p_valor
  );
END;
$$;


--
-- Name: apagar_nota_fiscal(uuid); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.apagar_nota_fiscal(p_nf_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'financeiro', 'vendas', 'logistica'
    AS $$
DECLARE
  v_nf          RECORD;
  v_item        jsonb;
  v_cod_produto text;
  v_cor         text;
  v_qtd         numeric;
  v_rows        int;
  v_total_oc    int := 0;
  v_total_cot   int := 0;
BEGIN
  SELECT * INTO v_nf FROM financeiro.notas_fiscais WHERE id = p_nf_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NF não encontrada');
  END IF;

  IF v_nf.tipo_nota = 'SIMPLES_REMESSA' THEN

    IF v_nf.itens_faturados IS NOT NULL THEN
      FOR v_item IN
        SELECT value FROM jsonb_array_elements(v_nf.itens_faturados) AS t(value)
      LOOP
        v_cod_produto := v_item->>'cod_produto';
        v_cor         := v_item->>'cor';
        v_qtd         := (v_item->>'qtd_faturada')::numeric;

        CONTINUE WHEN v_qtd IS NULL OR v_qtd <= 0;
        CONTINUE WHEN v_cod_produto IS NULL;

        IF v_cor IS NOT NULL AND v_cor <> '' THEN
          UPDATE vendas.ordens_compra
          SET qtd_enviada = GREATEST(0, COALESCE(qtd_enviada, 0) - v_qtd)
          WHERE (pedido = v_nf.pedido_pai OR pedido LIKE v_nf.pedido_pai || '-%')
            AND cod_produto = v_cod_produto
            AND cor = v_cor
            AND excluido_em IS NULL;
        ELSE
          UPDATE vendas.ordens_compra
          SET qtd_enviada = GREATEST(0, COALESCE(qtd_enviada, 0) - v_qtd)
          WHERE (pedido = v_nf.pedido_pai OR pedido LIKE v_nf.pedido_pai || '-%')
            AND cod_produto = v_cod_produto
            AND (cor IS NULL OR cor = '')
            AND excluido_em IS NULL;
        END IF;

        GET DIAGNOSTICS v_rows = ROW_COUNT;
        v_total_oc := v_total_oc + v_rows;
      END LOOP;
    END IF;

    -- FIX: era public.cotacoes (inexistente) → logistica.cotacoes
    DELETE FROM logistica.cotacoes
    WHERE pedido_pai_origem = v_nf.pedido_pai
       OR (
         v_nf.pedido_pai LIKE 'COT-%'
         AND LEFT(id::text, 8) = LOWER(REPLACE(v_nf.pedido_pai, 'COT-', ''))
       );

    GET DIAGNOSTICS v_total_cot = ROW_COUNT;
  END IF;

  DELETE FROM financeiro.notas_fiscais WHERE id = p_nf_id;

  RETURN jsonb_build_object(
    'ok',                 true,
    'tipo',               v_nf.tipo_nota,
    'pedido',             v_nf.pedido_pai,
    'ordens_atualizadas', v_total_oc,
    'cotacoes_apagadas',  v_total_cot
  );
END;
$$;


--
-- Name: FUNCTION apagar_nota_fiscal(p_nf_id uuid); Type: COMMENT; Schema: financeiro; Owner: -
--

COMMENT ON FUNCTION financeiro.apagar_nota_fiscal(p_nf_id uuid) IS 'FIX P1 (2026-08-06): corrigido schema de cotacoes — era public.cotacoes (inexistente), agora logistica.cotacoes. search_path atualizado para incluir logistica.';


--
-- Name: atualiza_qtd_enviada_nf_emitida(); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.atualiza_qtd_enviada_nf_emitida() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  item          JSONB;
  v_cod_produto TEXT;
  v_cor         TEXT;
  v_qtd         NUMERIC;
  v_nome        TEXT;
BEGIN
  IF NEW.tipo_nota   != 'SIMPLES_REMESSA' THEN RETURN NEW; END IF;
  IF NEW.status      != 'EMITIDA'         THEN RETURN NEW; END IF;
  IF OLD.status       = 'EMITIDA'         THEN RETURN NEW; END IF;
  IF NEW.itens_faturados IS NULL          THEN RETURN NEW; END IF;
  IF NEW.pedido_pai  IS NULL              THEN RETURN NEW; END IF;

  FOR item IN SELECT * FROM jsonb_array_elements(NEW.itens_faturados)
  LOOP
    v_qtd  := COALESCE(
      NULLIF(item->>'qtd_faturada', '')::NUMERIC,
      NULLIF(item->>'quantidade',   '')::NUMERIC,
      0
    );
    v_cor  := COALESCE(NULLIF(TRIM(item->>'cor'), ''), '');
    v_nome := COALESCE(item->>'nome_produto', '');

    IF v_cor = '' AND v_nome LIKE '% / %' THEN
      v_cor := TRIM(SPLIT_PART(v_nome, ' / ', 2));
    END IF;

    v_cod_produto := NULLIF(TRIM(item->>'cod_produto'), '');

    IF v_qtd > 0 THEN
      UPDATE vendas.ordens_compra
      SET    qtd_enviada = COALESCE(qtd_enviada, 0) + v_qtd
      WHERE  excluido_em IS NULL
        AND  (pedido = NEW.pedido_pai OR pedido LIKE NEW.pedido_pai || '-%')
        AND  COALESCE(cor, '') = v_cor
        AND  (
               v_cod_produto IS NULL
               OR COALESCE(cod_produto::TEXT, '') = v_cod_produto
               OR LOWER(TRIM(produto)) = LOWER(TRIM(SPLIT_PART(v_nome, ' / ', 1)))
             );
    END IF;
  END LOOP;

  RETURN NEW;
END;
$$;


--
-- Name: colaboradores; Type: TABLE; Schema: financeiro; Owner: -
