CREATE TABLE financeiro.colaboradores (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    nome text NOT NULL,
    cpf text NOT NULL,
    cargo text,
    departamento text,
    chave_pix text,
    cidade text NOT NULL,
