    CONSTRAINT colaboradores_cidade_check CHECK ((cidade = ANY (ARRAY['Rio Verde'::text, 'São Paulo'::text]))),
    CONSTRAINT colaboradores_tipo_chave_pix_check CHECK ((tipo_chave_pix = ANY (ARRAY['CPF'::text, 'CNPJ'::text, 'E-mail'::text, 'Telefone'::text, 'Chave aleatória'::text]))),
    CONSTRAINT colaboradores_tipo_contrato_check CHECK ((tipo_contrato = ANY (ARRAY['CONTABILIDADE'::text, 'INTERNO'::text])))
);


