--
-- Name: atualizar_colaborador(uuid, text, text, text, text, text, text, text, boolean); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.atualizar_colaborador(p_id uuid, p_nome text DEFAULT NULL::text, p_cpf text DEFAULT NULL::text, p_cargo text DEFAULT NULL::text, p_departamento text DEFAULT NULL::text, p_chave_pix text DEFAULT NULL::text, p_tipo_chave_pix text DEFAULT NULL::text, p_cidade text DEFAULT NULL::text, p_ativo boolean DEFAULT NULL::boolean) RETURNS SETOF financeiro.colaboradores
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'financeiro'
    AS $$
BEGIN
  UPDATE financeiro.colaboradores SET
    nome            = COALESCE(p_nome,           nome),
    cpf             = COALESCE(p_cpf,            cpf),
    cargo           = CASE WHEN p_cargo          IS NOT NULL THEN p_cargo           ELSE cargo           END,
    departamento    = CASE WHEN p_departamento   IS NOT NULL THEN p_departamento    ELSE departamento    END,
    chave_pix       = CASE WHEN p_chave_pix      IS NOT NULL THEN p_chave_pix       ELSE chave_pix       END,
    tipo_chave_pix  = CASE WHEN p_tipo_chave_pix IS NOT NULL THEN p_tipo_chave_pix  ELSE tipo_chave_pix  END,
    cidade          = COALESCE(p_cidade,          cidade),
    ativo           = COALESCE(p_ativo,           ativo)
  WHERE id = p_id;

  RETURN QUERY SELECT * FROM financeiro.colaboradores WHERE id = p_id;
END;
$$;


--
-- Name: atualizar_colaborador(uuid, text, text, text, text, text, text, text, boolean, text); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.atualizar_colaborador(p_id uuid, p_nome text DEFAULT NULL::text, p_cpf text DEFAULT NULL::text, p_cargo text DEFAULT NULL::text, p_departamento text DEFAULT NULL::text, p_chave_pix text DEFAULT NULL::text, p_tipo_chave_pix text DEFAULT NULL::text, p_cidade text DEFAULT NULL::text, p_ativo boolean DEFAULT NULL::boolean, p_tipo_contrato text DEFAULT NULL::text) RETURNS SETOF financeiro.colaboradores
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'financeiro'
    AS $$
BEGIN
  UPDATE financeiro.colaboradores SET
    nome            = COALESCE(p_nome,           nome),
    cpf             = COALESCE(p_cpf,            cpf),
    cargo           = CASE WHEN p_cargo          IS NOT NULL THEN p_cargo           ELSE cargo           END,
    departamento    = CASE WHEN p_departamento   IS NOT NULL THEN p_departamento    ELSE departamento    END,
    chave_pix       = CASE WHEN p_chave_pix      IS NOT NULL THEN p_chave_pix       ELSE chave_pix       END,
    tipo_chave_pix  = CASE WHEN p_tipo_chave_pix IS NOT NULL THEN p_tipo_chave_pix  ELSE tipo_chave_pix  END,
    cidade          = COALESCE(p_cidade,          cidade),
    ativo           = COALESCE(p_ativo,           ativo),
    tipo_contrato   = CASE WHEN p_tipo_contrato  IS NOT NULL THEN p_tipo_contrato   ELSE tipo_contrato   END
  WHERE id = p_id;

  RETURN QUERY SELECT * FROM financeiro.colaboradores WHERE id = p_id;
END;
$$;


--
-- Name: bulk_insert_parcelas(jsonb); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.bulk_insert_parcelas(p_payload jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'financeiro'
    AS $$
DECLARE
  v_item jsonb;
  v_count integer := 0;
  v_venda_id uuid;
BEGIN
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_payload)
  LOOP
    BEGIN
      SELECT id INTO v_venda_id FROM financeiro.vendas_unificadas
        WHERE pedido_pai = v_item->>'pedido_pai';
      IF v_venda_id IS NULL THEN CONTINUE; END IF;

      INSERT INTO financeiro.vendas_parcelas (
        venda_id, tipo, numero_parcela, data_vencimento, valor, status,
        data_pagamento, forma_pagamento, obs, aba_origem, ano_origem
      ) VALUES (
        v_venda_id,
        v_item->>'tipo',
        NULLIF(v_item->>'numero_parcela','')::smallint,
        NULLIF(v_item->>'data_vencimento','')::date,
        (v_item->>'valor')::numeric,
        COALESCE(v_item->>'status', 'ABERTO'),
        NULLIF(v_item->>'data_pagamento','')::date,
        v_item->>'forma_pagamento',
        v_item->>'obs',
        v_item->>'aba_origem',
        NULLIF(v_item->>'ano_origem','')::smallint
      );
      v_count := v_count + 1;
    EXCEPTION WHEN unique_violation THEN
      CONTINUE;
    END;
  END LOOP;
  RETURN v_count;
END;
$$;


--
-- Name: bulk_sync_parcelas_planilha(jsonb); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.bulk_sync_parcelas_planilha(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'financeiro'
    SET statement_timeout TO '120s'
    AS $$
DECLARE
  v_item jsonb;
  v_res  jsonb;
  v_ins integer := 0;
  v_upd integer := 0;
  v_bx  integer := 0;
  v_skip_nf integer := 0;
  v_skip_amb integer := 0;
  v_err integer := 0;
  v_total integer := 0;
  v_skipped_nf text[] := ARRAY[]::text[];
  v_skipped_amb text[] := ARRAY[]::text[];
  v_errors jsonb := '[]'::jsonb;
BEGIN
  -- Aumenta lock_timeout local (role authenticator tem 8s; precisamos esperar advisory locks)
  SET LOCAL lock_timeout = '60s';

  -- CRITICO: ordena items por pedido_pai antes de processar.
  -- Isso garante que todas as transacoes paralelas adquirem advisory locks na mesma ordem (alfabetica),
  -- eliminando o deadlock cruzado entre pedidos (Tx A pega lock X depois Y; Tx B pega Y depois X).
  -- Sem ordem total consistente, locks viram ciclo -> deadlock.
  FOR v_item IN
    SELECT elem
    FROM jsonb_array_elements(p_payload) WITH ORDINALITY AS t(elem, ord)
    ORDER BY (elem->>'pedido_pai') NULLS LAST,
             COALESCE(elem->>'tipo','PARCELA'),
             NULLIF(elem->>'numero_parcela','')::int NULLS LAST,
             ord
  LOOP
    v_total := v_total + 1;
    BEGIN
      v_res := financeiro.sync_parcela_planilha(v_item);
      CASE v_res->>'acao'
        WHEN 'INSERT'         THEN v_ins := v_ins + 1;
        WHEN 'UPDATE'         THEN v_upd := v_upd + 1;
        WHEN 'UPDATE_BAIXOU'  THEN v_bx  := v_bx  + 1;
        WHEN 'SKIP_VENDA_NAO_ENCONTRADA' THEN
          v_skip_nf := v_skip_nf + 1;
          v_skipped_nf := v_skipped_nf || (v_res->>'pedido_pai');
        WHEN 'SKIP_PEDIDO_AMBIGUO' THEN
          v_skip_amb := v_skip_amb + 1;
          v_skipped_amb := v_skipped_amb || (v_res->>'pedido_pai');
        ELSE NULL;
      END CASE;
    EXCEPTION WHEN OTHERS THEN
      v_err := v_err + 1;
      v_errors := v_errors || jsonb_build_object(
        'pedido_pai', v_item->>'pedido_pai',
        'tipo', v_item->>'tipo',
        'numero_parcela', v_item->>'numero_parcela',
        'erro', SQLERRM
      );
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'total', v_total,
    'inseridas', v_ins,
    'atualizadas', v_upd,
    'baixadas', v_bx,
    'puladas_venda_nao_encontrada', v_skip_nf,
    'puladas_pedido_ambiguo', v_skip_amb,
    'erros', v_err,
    'pedidos_nao_encontrados', to_jsonb(v_skipped_nf),
    'pedidos_ambiguos', to_jsonb(v_skipped_amb),
    'detalhes_erros', v_errors
  );
END;
$$;


--
-- Name: FUNCTION bulk_sync_parcelas_planilha(p_payload jsonb); Type: COMMENT; Schema: financeiro; Owner: -
--

COMMENT ON FUNCTION financeiro.bulk_sync_parcelas_planilha(p_payload jsonb) IS 'Recebe ARRAY JSONB de parcelas (vindo do n8n). Itera chamando sync_parcela_planilha. Retorna sumario completo com contagens + pedidos nao encontrados + detalhes de erros.';


--
-- Name: bulk_upsert_vendas(jsonb); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.bulk_upsert_vendas(p_payload jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'financeiro'
    AS $$
DECLARE
  v_item jsonb;
  v_count integer := 0;
BEGIN
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_payload)
  LOOP
    PERFORM financeiro.upsert_venda_unificada(v_item);
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;
$$;


--
-- Name: cadastrar_parcela_por_pedido(jsonb); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.cadastrar_parcela_por_pedido(p_payload jsonb) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_venda_id uuid;
  v_parcela_id uuid;
BEGIN
  SELECT id INTO v_venda_id FROM financeiro.vendas_unificadas
    WHERE pedido_pai = p_payload->>'pedido_pai';
  IF v_venda_id IS NULL THEN
    RAISE EXCEPTION 'Venda não encontrada para pedido_pai = %', p_payload->>'pedido_pai';
  END IF;

  INSERT INTO financeiro.vendas_parcelas (
    venda_id, tipo, numero_parcela, data_vencimento, valor, status,
    data_pagamento, forma_pagamento, obs, aba_origem, ano_origem
  ) VALUES (
    v_venda_id,
    p_payload->>'tipo',
    NULLIF(p_payload->>'numero_parcela','')::smallint,
    NULLIF(p_payload->>'data_vencimento','')::date,
    (p_payload->>'valor')::numeric,
    COALESCE(p_payload->>'status', 'ABERTO'),
    NULLIF(p_payload->>'data_pagamento','')::date,
    p_payload->>'forma_pagamento',
    p_payload->>'obs',
    p_payload->>'aba_origem',
    NULLIF(p_payload->>'ano_origem','')::smallint
  )
  RETURNING id INTO v_parcela_id;
  RETURN v_parcela_id;
END;
$$;


--
-- Name: calc_mes_ano_fallback(); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.calc_mes_ano_fallback() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.mes_referencia IS NULL AND NEW.data_venda IS NOT NULL THEN
    NEW.mes_referencia := EXTRACT(month FROM NEW.data_venda)::smallint;
  END IF;
  IF NEW.ano_referencia IS NULL AND NEW.data_venda IS NOT NULL THEN
    NEW.ano_referencia := EXTRACT(year FROM NEW.data_venda)::smallint;
  END IF;
  -- mes_ano_referencia sempre derivado de ano+mes
  IF NEW.ano_referencia IS NOT NULL AND NEW.mes_referencia IS NOT NULL THEN
    NEW.mes_ano_referencia := NEW.ano_referencia::text || '-' || lpad(NEW.mes_referencia::text, 2, '0');
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: desfazer_unificacao(uuid, text); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.desfazer_unificacao(p_grupo_id uuid, p_usuario text DEFAULT 'sistema'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'financeiro'
    AS $$
DECLARE
  v_qtd             int;
  v_qtd_com_parcela int;
BEGIN
  IF p_grupo_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Grupo nao informado.');
  END IF;

  SELECT COUNT(*) INTO v_qtd
  FROM financeiro.vendas_unificadas
  WHERE grupo_unificacao_id = p_grupo_id;

  IF v_qtd = 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Grupo de unificacao nao encontrado.');
  END IF;

  SELECT COUNT(*) INTO v_qtd_com_parcela
  FROM financeiro.vendas_parcelas vp
  JOIN financeiro.vendas_unificadas vu ON vu.id = vp.venda_id
  WHERE vu.grupo_unificacao_id = p_grupo_id
    AND vp.tipo IN ('PARCELA', 'ENTRADA');

  IF v_qtd_com_parcela > 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'O grupo ja possui parcelas/boleto. Remova a cobranca antes de desfazer.');
  END IF;

  UPDATE financeiro.vendas_unificadas
  SET valor_total          = COALESCE(valor_total_original, valor_total),
      valor_total_original = NULL,
      grupo_unificacao_id  = NULL,
      unif_papel           = NULL,
      pedidos_unificados   = NULL,
      atualizado_por       = p_usuario,
      atualizado_em        = now()
  WHERE grupo_unificacao_id = p_grupo_id;

  RETURN jsonb_build_object('ok', true, 'qtd_pedidos', v_qtd);
END;
$$;


--
-- Name: empresas_reativadas_ou_novas_hoje(); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.empresas_reativadas_ou_novas_hoje() RETURNS TABLE(empresa text, cnpj text, vendedor text, valor_total numeric, tipo text, ultima_venda_anterior date, dias_sem_comprar integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'financeiro', 'vendas'
    AS $$
DECLARE
  rec               RECORD;
  v_ultima_anterior DATE;
BEGIN

  FOR rec IN
    SELECT DISTINCT ON (COALESCE(v.cnpj, v.empresa))
      v.empresa,
      v.cnpj,
      v.vendedor,
      v.valor_total
    FROM financeiro.vendas_unificadas v
    WHERE v.data_venda = CURRENT_DATE
    ORDER BY COALESCE(v.cnpj, v.empresa), v.criado_em DESC
  LOOP

    SELECT MAX(h.data_venda) INTO v_ultima_anterior
    FROM financeiro.vendas_unificadas h
    WHERE h.data_venda < CURRENT_DATE
      AND h.data_venda IS NOT NULL
      AND (
        -- 1. Mesmo CNPJ
        (rec.cnpj IS NOT NULL AND h.cnpj = rec.cnpj)
        OR
        -- 2. Nome exato
        h.empresa = rec.empresa
        OR
        -- 3. Prefixo similar — mas o nome histórico deve ter pelo menos 2 palavras
        --    para evitar que "SICOOB" bata com "SICOOB ALTO VALE"
        (h.cnpj IS NULL
         AND h.empresa ILIKE '% %'          -- histórico tem 2+ palavras
         AND (
           rec.empresa ILIKE h.empresa || '%'
           OR h.empresa ILIKE rec.empresa || '%'
         )
        )
      );

    IF v_ultima_anterior IS NULL THEN
      empresa               := rec.empresa;
      cnpj                  := rec.cnpj;
      vendedor              := rec.vendedor;
      valor_total           := rec.valor_total;
      tipo                  := 'NOVA';
      ultima_venda_anterior := NULL;
      dias_sem_comprar      := NULL;
      RETURN NEXT;

    ELSIF v_ultima_anterior < CURRENT_DATE - INTERVAL '6 months' THEN
      empresa               := rec.empresa;
      cnpj                  := rec.cnpj;
      vendedor              := rec.vendedor;
      valor_total           := rec.valor_total;
      tipo                  := 'REATIVADA';
      ultima_venda_anterior := v_ultima_anterior;
      dias_sem_comprar      := (CURRENT_DATE - v_ultima_anterior)::integer;
      RETURN NEXT;
    END IF;

  END LOOP;
END;
$$;


--
-- Name: extrair_pedido_pai(text); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.extrair_pedido_pai(pedido_filho text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  partes text[];
  resultado text;
BEGIN
  IF pedido_filho IS NULL OR pedido_filho = '' THEN
    RETURN NULL;
  END IF;
  partes := string_to_array(trim(pedido_filho), '-');
  IF array_length(partes, 1) >= 2 THEN
    resultado := partes[1] || '-' || partes[2];
  ELSE
    resultado := trim(pedido_filho);
  END IF;
  RETURN resultado;
END;
$$;


