--

CREATE FUNCTION financeiro.fn_auto_liquidar_emprestimo() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'financeiro'
    AS $$
BEGIN
  IF NEW.parcelas_pagas >= NEW.quantidade_parcelas AND NEW.status = 'ativo' THEN
    NEW.status          := 'liquidado';
    NEW.data_liquidacao := COALESCE(NEW.data_liquidacao, CURRENT_DATE);
  END IF;
  RETURN NEW;
END;
$$;


