--
-- Name: fn_sync_nf_para_vendas(); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.fn_sync_nf_para_vendas() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'financeiro'
    AS $$
DECLARE
  v_pedidos text[];
  v_ped     text;
  v_nfs     text;
BEGIN
  v_pedidos := COALESCE(
    NULLIF(COALESCE(NEW.pedidos_unificados, OLD.pedidos_unificados), '{}'::text[]),
    ARRAY[COALESCE(NEW.pedido_pai, OLD.pedido_pai)]
  );

  IF v_pedidos IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  FOREACH v_ped IN ARRAY v_pedidos LOOP
    IF v_ped IS NULL THEN
      CONTINUE;
    END IF;

    SELECT string_agg(numero, '/' ORDER BY criado_em ASC)
      INTO v_nfs
    FROM financeiro.notas_fiscais
    WHERE tipo_nota = 'VENDA'
      AND status    = 'EMITIDA'
      AND numero    IS NOT NULL
      AND (
        pedido_pai = v_ped
        OR v_ped = ANY(COALESCE(pedidos_unificados, '{}'::text[]))
      );

    UPDATE financeiro.vendas_unificadas
    SET nf_venda      = v_nfs,
        atualizado_em = now()
    WHERE pedido_pai = v_ped;
  END LOOP;

  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: fn_sync_status_ordem(); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.fn_sync_status_ordem() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'financeiro', 'vendas'
    AS $$
BEGIN
  -- Só age quando o status muda para PAGO em PRODUTO ou GRAVAÇÃO
  IF NEW.status_pagamento = 'PAGO'
     AND NEW.tipo_pagamento IN ('PRODUTO', 'GRAVAÇÃO')
     AND (OLD.status_pagamento IS DISTINCT FROM 'PAGO')
  THEN
    -- Verifica se ainda existe algum pagamento não-PAGO para esse pedido
    IF NOT EXISTS (
      SELECT 1 FROM financeiro.pagamentos_diarios pd
      WHERE pd.pedido         = NEW.pedido
        AND pd.tipo_pagamento IN ('PRODUTO', 'GRAVAÇÃO')
        AND pd.status_pagamento != 'PAGO'
        AND pd.id != NEW.id
    ) THEN
      UPDATE vendas.ordens_compra
      SET status_pagamento = 'PAGO',
          atualizado_em    = NOW()
      WHERE pedido = NEW.pedido;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_sync_status_ordem_delete(); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.fn_sync_status_ordem_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'financeiro', 'vendas'
    AS $$
DECLARE
  v_total      INTEGER;
  v_pagos      INTEGER;
  v_aguardando INTEGER;
BEGIN
  -- Ignora tipos especiais (TROCA, REPOSIÇÃO etc.) — só age em PRODUTO / GRAVAÇÃO
  IF OLD.tipo_pagamento NOT IN ('PRODUTO', 'GRAVAÇÃO') THEN
    RETURN OLD;
  END IF;

  -- Conta o que ainda sobra após a exclusão
  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE status_pagamento = 'PAGO'),
    COUNT(*) FILTER (WHERE status_pagamento = 'AGUARDANDO PAGAMENTO')
  INTO v_total, v_pagos, v_aguardando
  FROM financeiro.pagamentos_diarios
  WHERE pedido         = OLD.pedido
    AND tipo_pagamento IN ('PRODUTO', 'GRAVAÇÃO');

  IF v_total = 0 THEN
    -- ▸ Não sobrou nenhum → limpa tudo, libera nova solicitação
    UPDATE vendas.ordens_compra
    SET status_pagamento = NULL,
        data_solicitacao = NULL,
        favorecido       = NULL,
        chave_pix        = NULL,
        pagamento        = NULL,
        restante         = NULL,
        atualizado_em    = NOW()
    WHERE pedido = OLD.pedido;

  ELSIF v_total = v_pagos THEN
    -- ▸ Ainda há pagamentos, mas todos PAGOS → mantém como PAGO
    UPDATE vendas.ordens_compra
    SET status_pagamento = 'PAGO',
        atualizado_em    = NOW()
    WHERE pedido = OLD.pedido;

  ELSE
    -- ▸ Ainda existe algum AGUARDANDO → mantém o bloqueio
    UPDATE vendas.ordens_compra
    SET status_pagamento = 'AGUARDANDO PAGAMENTO',
        atualizado_em    = NOW()
    WHERE pedido = OLD.pedido;
  END IF;

  RETURN OLD;
END;
$$;


--
-- Name: fn_trg_parcelas_recalc(); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.fn_trg_parcelas_recalc() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_target uuid;
BEGIN
  v_target := COALESCE(NEW.venda_id, OLD.venda_id);
  IF v_target IS NOT NULL THEN
    PERFORM financeiro.recalcular_venda_unificada(v_target);
    IF TG_OP <> 'DELETE' AND NEW.atualizado_por IS NOT NULL THEN
      UPDATE financeiro.vendas_unificadas
        SET atualizado_por = NEW.atualizado_por
        WHERE id = v_target;
    END IF;
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: fn_trg_vu_valor_total_recalc(); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.fn_trg_vu_valor_total_recalc() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.valor_total IS DISTINCT FROM OLD.valor_total THEN
    PERFORM financeiro.recalcular_venda_unificada(NEW.id);
  END IF;
  RETURN NEW;
END;
$$;


