--
-- Name: liquidar_parcela(uuid, numeric, text, date, text, text); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.liquidar_parcela(p_id uuid, p_valor numeric, p_desconto_tipo text, p_data_pagamento date, p_liquidado_por text, p_acao_restante text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'financeiro'
    AS $$
DECLARE
  v_emp              financeiro.emprestimos%ROWTYPE;
  v_novas_pagas      INTEGER;
  v_va_atual         NUMERIC;
  v_valor_efetivo    NUMERIC;
  v_restante         NUMERIC;
  v_parcelas_abertas INTEGER;
  v_prorrogs         JSONB;
  v_descontos        JSONB;
  v_proxima          INTEGER;
  v_va_existente     NUMERIC;
  v_total_futuro_cents INTEGER;
  v_base_cents         INTEGER;
  v_resto_cents        INTEGER;
  v_target_cents       INTEGER;
  v_va_cents           INTEGER;
  v_parcela_cents      INTEGER;
  i                    INTEGER;
BEGIN
  SELECT * INTO v_emp FROM financeiro.emprestimos WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN RETURN json_build_object('ok',false,'erro','Empréstimo não encontrado'); END IF;
  IF v_emp.status IN ('liquidado','cancelado') THEN RETURN json_build_object('ok',false,'erro','Empréstimo já encerrado'); END IF;

  v_novas_pagas    := v_emp.parcelas_pagas + 1;
  v_proxima        := v_novas_pagas + 1;
  v_prorrogs       := COALESCE(v_emp.prorrogacoes,'{}');
  v_descontos      := COALESCE(v_emp.desconto_tipo,'{}');
  v_parcela_cents  := ROUND(v_emp.valor_parcela * 100)::INTEGER;

  -- Ler va_N da parcela atual antes de remover
  v_va_atual      := COALESCE((v_prorrogs ->> ('va_' || v_novas_pagas::TEXT))::NUMERIC, 0);
  v_valor_efetivo := v_emp.valor_parcela + v_va_atual;

  -- Remover va_N da parcela atual (está sendo paga)
  v_prorrogs := v_prorrogs - ('va_' || v_novas_pagas::TEXT);

  -- Restante baseado no valor EFETIVO (positivo = déficit, negativo = superávit)
  v_restante := v_valor_efetivo - p_valor;

  v_parcelas_abertas := v_emp.quantidade_parcelas - v_novas_pagas;

  -- Gravar desconto, data e responsável
  v_descontos := jsonb_set(v_descontos, ARRAY[v_novas_pagas::TEXT], to_jsonb(p_desconto_tipo));
  v_prorrogs  := jsonb_set(v_prorrogs, ARRAY['data_liq_' || v_novas_pagas::TEXT], to_jsonb(p_data_pagamento::TEXT));
  v_prorrogs  := jsonb_set(v_prorrogs, ARRAY['liq_por_' || v_novas_pagas::TEXT], to_jsonb(p_liquidado_por));

  -- Gravar valor pago se diferente do base
  IF ABS(p_valor - v_emp.valor_parcela) > 0.01 THEN
    v_prorrogs := jsonb_set(v_prorrogs, ARRAY['pago_' || v_novas_pagas::TEXT], to_jsonb(p_valor::TEXT));
  END IF;

  -- ══════════════════════════════════════════════════════════
  -- CASO 1: DÉFICIT (pagou menos) → distribui conforme acao
  -- ══════════════════════════════════════════════════════════
  IF v_restante > 0.01 AND p_acao_restante IS NOT NULL AND v_parcelas_abertas > 0 THEN

    IF p_acao_restante = 'distribuir' THEN
      -- Redistribuição fresca: total futuro + déficit
      v_total_futuro_cents := v_parcelas_abertas * v_parcela_cents;
      FOR i IN 1..v_parcelas_abertas LOOP
        v_total_futuro_cents := v_total_futuro_cents
          + ROUND(COALESCE((v_prorrogs ->> ('va_' || (v_novas_pagas + i)::TEXT))::NUMERIC, 0) * 100)::INTEGER;
      END LOOP;
      v_total_futuro_cents := v_total_futuro_cents + ROUND(v_restante * 100)::INTEGER;

      FOR i IN 1..v_parcelas_abertas LOOP
        v_prorrogs := v_prorrogs - ('va_' || (v_novas_pagas + i)::TEXT);
      END LOOP;

      v_base_cents  := v_total_futuro_cents / v_parcelas_abertas;
      v_resto_cents := v_total_futuro_cents - v_base_cents * v_parcelas_abertas;

      FOR i IN 1..v_parcelas_abertas LOOP
        v_target_cents := v_base_cents + CASE WHEN i <= v_resto_cents THEN 1 ELSE 0 END;
        v_va_cents     := v_target_cents - v_parcela_cents;
        IF v_va_cents <> 0 THEN
          v_prorrogs := jsonb_set(v_prorrogs,
            ARRAY['va_' || (v_novas_pagas + i)::TEXT],
            to_jsonb((v_va_cents::NUMERIC / 100)::TEXT));
        END IF;
      END LOOP;

      UPDATE financeiro.emprestimos SET
        parcelas_pagas = v_novas_pagas,
        desconto_tipo  = v_descontos,
        prorrogacoes   = v_prorrogs
      WHERE id = p_id;

    ELSIF p_acao_restante = 'proxima' THEN
      v_va_existente := COALESCE((v_prorrogs ->> ('va_' || v_proxima::TEXT))::NUMERIC, 0);
      v_prorrogs := jsonb_set(v_prorrogs,
        ARRAY['va_' || v_proxima::TEXT],
        to_jsonb((v_va_existente + v_restante)::TEXT));

      UPDATE financeiro.emprestimos SET
        parcelas_pagas = v_novas_pagas,
        desconto_tipo  = v_descontos,
        prorrogacoes   = v_prorrogs
      WHERE id = p_id;
    END IF;

  -- ══════════════════════════════════════════════════════════
  -- CASO 2: SUPERÁVIT (pagou mais) → abate nas futuras
  -- ══════════════════════════════════════════════════════════
  ELSIF v_restante < -0.01 AND v_parcelas_abertas > 0 THEN

    -- Total futuro = (base das parcelas abertas) + (va_N existentes) + restante (negativo = abatimento)
    v_total_futuro_cents := v_parcelas_abertas * v_parcela_cents;
    FOR i IN 1..v_parcelas_abertas LOOP
      v_total_futuro_cents := v_total_futuro_cents
        + ROUND(COALESCE((v_prorrogs ->> ('va_' || (v_novas_pagas + i)::TEXT))::NUMERIC, 0) * 100)::INTEGER;
    END LOOP;
    v_total_futuro_cents := v_total_futuro_cents + ROUND(v_restante * 100)::INTEGER;

    -- Limpar va_N das parcelas futuras
    FOR i IN 1..v_parcelas_abertas LOOP
      v_prorrogs := v_prorrogs - ('va_' || (v_novas_pagas + i)::TEXT);
    END LOOP;

    IF v_total_futuro_cents <= 0 THEN
      -- Superávit cobre todas as parcelas restantes → empréstimo liquidado
      UPDATE financeiro.emprestimos SET
        parcelas_pagas  = quantidade_parcelas,
        desconto_tipo   = v_descontos,
        prorrogacoes    = v_prorrogs,
        status          = 'liquidado',
        liquidado_por   = p_liquidado_por,
        data_liquidacao = p_data_pagamento
      WHERE id = p_id;
    ELSE
      -- Redistribuição fresca com valor menor para cada parcela
      v_base_cents  := v_total_futuro_cents / v_parcelas_abertas;
      v_resto_cents := v_total_futuro_cents - v_base_cents * v_parcelas_abertas;

      FOR i IN 1..v_parcelas_abertas LOOP
        v_target_cents := v_base_cents + CASE WHEN i <= v_resto_cents THEN 1 ELSE 0 END;
        v_va_cents     := v_target_cents - v_parcela_cents;
        IF v_va_cents <> 0 THEN
          v_prorrogs := jsonb_set(v_prorrogs,
            ARRAY['va_' || (v_novas_pagas + i)::TEXT],
            to_jsonb((v_va_cents::NUMERIC / 100)::TEXT));
        END IF;
      END LOOP;

      UPDATE financeiro.emprestimos SET
        parcelas_pagas = v_novas_pagas,
        desconto_tipo  = v_descontos,
        prorrogacoes   = v_prorrogs
      WHERE id = p_id;
    END IF;

  -- ══════════════════════════════════════════════════════════
  -- CASO 3: PAGAMENTO NORMAL (ou última parcela)
  -- ══════════════════════════════════════════════════════════
  ELSE
    UPDATE financeiro.emprestimos SET
      parcelas_pagas  = v_novas_pagas,
      desconto_tipo   = v_descontos,
      prorrogacoes    = v_prorrogs,
      liquidado_por   = CASE WHEN v_novas_pagas >= quantidade_parcelas THEN p_liquidado_por ELSE liquidado_por END,
      data_liquidacao = CASE WHEN v_novas_pagas >= quantidade_parcelas THEN p_data_pagamento ELSE data_liquidacao END
    WHERE id = p_id;
  END IF;

  RETURN json_build_object(
    'ok',             true,
    'parcelas_pagas', v_novas_pagas,
    'valor_efetivo',  v_valor_efetivo,
    'restante',       v_restante,
    'liquidado',      v_novas_pagas >= v_emp.quantidade_parcelas OR v_restante < -0.01
  );
END;
$$;


--
-- Name: liquidar_vale(uuid, numeric, date, text, text); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.liquidar_vale(p_id uuid, p_valor numeric, p_data date, p_responsavel text, p_obs text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'financeiro'
    AS $$
DECLARE
  v_vale       financeiro.vales%ROWTYPE;
  v_novo_desc  NUMERIC;
  v_pendente   NUMERIC;
  v_novo_status TEXT;
  v_historico  JSONB;
BEGIN
  SELECT * INTO v_vale FROM financeiro.vales WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN RETURN json_build_object('ok',false,'erro','Vale não encontrado'); END IF;
  IF v_vale.status = 'liquidado' THEN RETURN json_build_object('ok',false,'erro','Vale já liquidado'); END IF;
  IF p_valor <= 0 THEN RETURN json_build_object('ok',false,'erro','Valor deve ser positivo'); END IF;

  v_pendente  := v_vale.valor - v_vale.valor_descontado;
  IF p_valor > v_pendente + 0.01 THEN
    RETURN json_build_object('ok',false,'erro','Valor maior que o saldo pendente (' || v_pendente || ')');
  END IF;

  v_novo_desc := v_vale.valor_descontado + p_valor;

  -- Adicionar ao histórico
  v_historico := v_vale.historico_desconto || jsonb_build_array(
    jsonb_build_object(
      'valor',       p_valor,
      'data',        p_data::TEXT,
      'responsavel', p_responsavel,
      'obs',         p_obs
    )
  );

  -- Determinar novo status
  IF v_novo_desc >= v_vale.valor - 0.01 THEN
    v_novo_status := 'liquidado';
  ELSE
    v_novo_status := 'parcial';
  END IF;

  UPDATE financeiro.vales SET
    valor_descontado  = v_novo_desc,
    status            = v_novo_status,
    historico_desconto = v_historico,
    data_liquidacao   = CASE WHEN v_novo_status = 'liquidado' THEN p_data ELSE data_liquidacao END,
    liquidado_por     = CASE WHEN v_novo_status = 'liquidado' THEN p_responsavel ELSE liquidado_por END
  WHERE id = p_id;

  RETURN json_build_object(
    'ok',              true,
    'status',          v_novo_status,
    'valor_descontado', v_novo_desc,
    'valor_pendente',  v_vale.valor - v_novo_desc
  );
END;
$$;


--
-- Name: listar_irmaos_faturaveis(text, integer); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.listar_irmaos_faturaveis(p_pedido_pai text, p_ano integer) RETURNS TABLE(id uuid, pedido_pai text, vendedor text, empresa text, cnpj text, valor_total numeric, eh_base boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'financeiro'
    AS $$
  WITH base AS (
    SELECT vendedor, empresa
    FROM financeiro.vendas_unificadas
    WHERE pedido_pai = p_pedido_pai AND ano_referencia = p_ano
    LIMIT 1
  )
  SELECT vu.id, vu.pedido_pai, vu.vendedor, vu.empresa, vu.cnpj, vu.valor_total,
         (vu.pedido_pai = p_pedido_pai) AS eh_base
  FROM financeiro.vendas_unificadas vu, base b
  WHERE vu.ano_referencia = p_ano
    AND COALESCE(vu.vendedor, '') = COALESCE(b.vendedor, '')
    AND COALESCE(vu.empresa, '')  = COALESCE(b.empresa, '')
    AND vu.grupo_unificacao_id IS NULL
    AND vu.nf_venda IS NULL
    AND NOT EXISTS (
      SELECT 1 FROM financeiro.vendas_parcelas vp
      WHERE vp.venda_id = vu.id AND vp.tipo IN ('PARCELA','ENTRADA')
    )
  ORDER BY vu.pedido_pai;
$$;


--
-- Name: marcar_parcela_paga(uuid, date, text, text); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.marcar_parcela_paga(p_parcela_id uuid, p_data_pagamento date DEFAULT CURRENT_DATE, p_forma_pagamento text DEFAULT NULL::text, p_obs text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE financeiro.vendas_parcelas
  SET status = 'PAGO',
      data_pagamento = p_data_pagamento,
      forma_pagamento = COALESCE(p_forma_pagamento, forma_pagamento),
      obs = COALESCE(p_obs, obs)
  WHERE id = p_parcela_id;
END;
$$;


--
-- Name: marcar_parcelas_vencidas(); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.marcar_parcelas_vencidas() RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE v_count integer;
BEGIN
  WITH atualizadas AS (
    UPDATE financeiro.vendas_parcelas
    SET status = 'VENCIDA'
    WHERE status = 'ABERTO' AND data_vencimento < CURRENT_DATE
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_count FROM atualizadas;
  RETURN v_count;
END;
$$;


--
-- Name: pagar_parcela_emprestimo(uuid, text); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.pagar_parcela_emprestimo(p_id uuid, p_liquidado_por text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'financeiro'
    AS $$
DECLARE
  v_emp financeiro.emprestimos%ROWTYPE;
  v_novas_pagas INTEGER;
BEGIN
  SELECT * INTO v_emp FROM financeiro.emprestimos WHERE id = p_id FOR UPDATE;

  IF NOT FOUND THEN
    RETURN json_build_object('ok', false, 'erro', 'Empréstimo não encontrado');
  END IF;

  IF v_emp.status IN ('liquidado', 'cancelado') THEN
    RETURN json_build_object('ok', false, 'erro', 'Empréstimo já encerrado — status: ' || v_emp.status);
  END IF;

  IF v_emp.parcelas_pagas >= v_emp.quantidade_parcelas THEN
    RETURN json_build_object('ok', false, 'erro', 'Todas as parcelas já foram pagas');
  END IF;

  v_novas_pagas := v_emp.parcelas_pagas + 1;

  UPDATE financeiro.emprestimos
  SET
    parcelas_pagas  = v_novas_pagas,
    liquidado_por   = CASE WHEN v_novas_pagas = quantidade_parcelas THEN p_liquidado_por ELSE liquidado_por END,
    data_liquidacao = CASE WHEN v_novas_pagas = quantidade_parcelas THEN CURRENT_DATE ELSE data_liquidacao END
  WHERE id = p_id;

  RETURN json_build_object(
    'ok',             true,
    'parcelas_pagas', v_novas_pagas,
    'parcelas_total', v_emp.quantidade_parcelas,
    'liquidado',      v_novas_pagas >= v_emp.quantidade_parcelas
  );
END;
$$;


--
-- Name: prorrogar_parcela(uuid, integer, date); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.prorrogar_parcela(p_id uuid, p_parcela_num integer, p_nova_data date) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'financeiro'
    AS $$
DECLARE
  v_emp        financeiro.emprestimos%ROWTYPE;
  v_data_atual DATE;
  v_delta      INTEGER;
  v_prorrogs   JSONB;
  i            INTEGER;
  v_d          DATE;
BEGIN
  SELECT * INTO v_emp FROM financeiro.emprestimos WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN RETURN json_build_object('ok',false,'erro','Não encontrado'); END IF;

  v_prorrogs := COALESCE(v_emp.prorrogacoes,'{}');

  IF v_prorrogs ? p_parcela_num::TEXT THEN
    v_data_atual := (v_prorrogs ->> p_parcela_num::TEXT)::DATE;
  ELSE
    v_data_atual := (v_emp.data_inicio::DATE
                     + ((p_parcela_num - 1)::TEXT || ' months')::INTERVAL)::DATE;
  END IF;

  v_delta := p_nova_data - v_data_atual;

  FOR i IN p_parcela_num .. v_emp.quantidade_parcelas LOOP
    IF v_prorrogs ? i::TEXT THEN
      v_d := (v_prorrogs ->> i::TEXT)::DATE + v_delta;
    ELSE
      v_d := (v_emp.data_inicio::DATE
              + ((i - 1)::TEXT || ' months')::INTERVAL)::DATE + v_delta;
    END IF;
    v_prorrogs := jsonb_set(v_prorrogs, ARRAY[i::TEXT], to_jsonb(v_d::TEXT));
  END LOOP;

  UPDATE financeiro.emprestimos SET prorrogacoes = v_prorrogs WHERE id = p_id;
  RETURN json_build_object('ok', true);
END;
$$;


--
-- Name: ranking_vendas_hoje(); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.ranking_vendas_hoje() RETURNS TABLE(vendedor text, total_vendido numeric, qtd_pedidos bigint, pct_meta numeric, falta numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'financeiro', 'vendas'
    AS $$
  WITH meta AS (SELECT 50000::numeric AS valor),
  vendas AS (
    SELECT
      v.vendedor,
      SUM(v.valor_total)  AS total_vendido,
      COUNT(*)            AS qtd_pedidos
    FROM financeiro.vendas_unificadas v
    WHERE v.data_venda = CURRENT_DATE
      AND v.vendedor IS NOT NULL
      AND NOT EXISTS (
        SELECT 1
        FROM financeiro.ranking_exclusoes e
        WHERE e.pedido_pai = v.pedido_pai
      )
    GROUP BY v.vendedor
  )
  SELECT
    v.vendedor,
    COALESCE(s.total_vendido, 0)                              AS total_vendido,
    COALESCE(s.qtd_pedidos,   0)                              AS qtd_pedidos,
    ROUND(COALESCE(s.total_vendido, 0) / m.valor * 100, 1)   AS pct_meta,
    GREATEST(0, m.valor - COALESCE(s.total_vendido, 0))       AS falta
  FROM (
    SELECT unnest(ARRAY[
      'Leticia','Danyelle','Gabryelly','Andriele',
      'Vanessa','Guilherme','Henrique','Sirlei'
    ]) AS vendedor
  ) v
  CROSS JOIN meta m
  LEFT JOIN vendas s ON s.vendedor = v.vendedor
  ORDER BY total_vendido DESC;
$$;


--
-- Name: ranking_vendas_semana(); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.ranking_vendas_semana() RETURNS TABLE(vendedor text, total_vendido numeric, qtd_pedidos bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'financeiro', 'vendas'
    AS $$WITH vendas AS (
    SELECT
      v.vendedor,
      SUM(v.valor_total) AS total_vendido,
      COUNT(*)           AS qtd_pedidos
    FROM financeiro.vendas_unificadas v
    WHERE v.data_venda BETWEEN '2026-08-03' AND '2026-08-07'
      AND v.vendedor IS NOT NULL
    GROUP BY v.vendedor
  )
  SELECT
    v.vendedor,
    COALESCE(s.total_vendido, 0) AS total_vendido,
    COALESCE(s.qtd_pedidos,   0) AS qtd_pedidos
  FROM (
    SELECT unnest(ARRAY[
      'Leticia','Danyelle','Gabryelly','Andriele',
      'Vanessa','Guilherme','Henrique','Sirlei'
    ]) AS vendedor
  ) v
  LEFT JOIN vendas s ON s.vendedor = v.vendedor
  ORDER BY total_vendido DESC;$$;


--
-- Name: recalcular_venda_unificada(uuid); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.recalcular_venda_unificada(p_venda_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_tolerancia numeric;
  v_valor_total numeric;
  v_valor_entrada numeric;
  v_valor_pago numeric;
  v_qtd_parcelas smallint;
  v_situacao_atual text;
  v_nova_situacao text;
  v_tem_vencida boolean;
  v_tem_paga boolean;
  v_tem_parcela boolean;
BEGIN
  -- IMPORTANTE: FRETE é controlado separadamente. Não conta como parcela do pedido,
  -- não soma em valor_pago, não influencia situacao_pagamento.
  SELECT EXISTS(
    SELECT 1 FROM financeiro.vendas_parcelas
    WHERE venda_id = p_venda_id AND tipo IN ('PARCELA','ENTRADA')
  ) INTO v_tem_parcela;

  SELECT COALESCE((SELECT valor::numeric FROM financeiro.config WHERE chave='tolerancia_pagamento_brl'), 5)
    INTO v_tolerancia;

  SELECT valor_total, situacao_pagamento
    INTO v_valor_total, v_situacao_atual
    FROM financeiro.vendas_unificadas WHERE id = p_venda_id;

  IF v_valor_total IS NULL THEN
    RETURN;
  END IF;

  -- Sem parcelas PARCELA/ENTRADA: nada a recalcular (preserva pagamento manual da planilha)
  IF NOT v_tem_parcela THEN
    RETURN;
  END IF;

  -- Agregação ignorando linhas de FRETE
  SELECT
    COALESCE(SUM(valor) FILTER (WHERE tipo='ENTRADA' AND status='PAGO'), 0),
    COALESCE(SUM(valor) FILTER (WHERE tipo IN ('PARCELA','ENTRADA') AND status='PAGO'), 0),
    COUNT(*) FILTER (WHERE tipo='PARCELA' AND status <> 'CANCELADA'),
    bool_or(
      tipo IN ('PARCELA','ENTRADA')
      AND (status='VENCIDA' OR (status='ABERTO' AND data_vencimento < CURRENT_DATE))
    ),
    bool_or(tipo IN ('PARCELA','ENTRADA') AND status='PAGO')
  INTO v_valor_entrada, v_valor_pago, v_qtd_parcelas, v_tem_vencida, v_tem_paga
  FROM financeiro.vendas_parcelas WHERE venda_id = p_venda_id;

  IF v_situacao_atual = 'CANCELADO' THEN
    v_nova_situacao := 'CANCELADO';
  ELSIF v_valor_total = 0 THEN
    v_nova_situacao := 'PENDENTE';
  ELSIF v_valor_pago >= (v_valor_total - v_tolerancia) THEN
    v_nova_situacao := 'PAGO';
  ELSIF COALESCE(v_tem_vencida, false) THEN
    v_nova_situacao := 'VENCIDO';
  ELSIF COALESCE(v_tem_paga, false) THEN
    v_nova_situacao := 'PAGANDO';
  ELSE
    v_nova_situacao := 'PENDENTE';
  END IF;

  UPDATE financeiro.vendas_unificadas
  SET valor_entrada = v_valor_entrada,
      valor_pago = v_valor_pago,
      qtd_parcelas = v_qtd_parcelas,
      situacao_pagamento = v_nova_situacao,
      atualizado_em = now()
  WHERE id = p_venda_id;
END;
$$;


--
-- Name: remover_parcelas(uuid, integer); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.remover_parcelas(p_id uuid, p_quantidade integer) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'financeiro'
    AS $$
DECLARE
  v_emp              financeiro.emprestimos%ROWTYPE;
  v_prorrogs         JSONB;
  v_parcelas_abertas INTEGER;
  v_novas_abertas    INTEGER;
  v_pendente         NUMERIC;
  v_pendente_cents   INTEGER;
  v_parcela_cents    INTEGER;
  v_base_cents       INTEGER;
  v_resto_cents      INTEGER;
  v_target_cents     INTEGER;
  v_va_cents         INTEGER;
  v_num              INTEGER;
  i                  INTEGER;
BEGIN
  SELECT * INTO v_emp FROM financeiro.emprestimos WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN RETURN json_build_object('ok',false,'erro','Empréstimo não encontrado'); END IF;
  IF v_emp.status IN ('liquidado','cancelado') THEN RETURN json_build_object('ok',false,'erro','Empréstimo já encerrado'); END IF;
  IF p_quantidade <= 0 THEN RETURN json_build_object('ok',false,'erro','Quantidade deve ser positiva'); END IF;

  v_parcelas_abertas := v_emp.quantidade_parcelas - v_emp.parcelas_pagas;

  IF p_quantidade >= v_parcelas_abertas THEN
    RETURN json_build_object('ok',false,'erro','Não é possível remover todas as parcelas em aberto');
  END IF;

  v_prorrogs      := COALESCE(v_emp.prorrogacoes, '{}');
  v_parcela_cents := ROUND(v_emp.valor_parcela * 100)::INTEGER;

  -- Calcular pendente atual (base + va_N)
  v_pendente := v_parcelas_abertas * v_emp.valor_parcela;
  FOR i IN 1..v_parcelas_abertas LOOP
    v_num := v_emp.parcelas_pagas + i;
    v_pendente := v_pendente + COALESCE((v_prorrogs ->> ('va_' || v_num::TEXT))::NUMERIC, 0);
  END LOOP;

  -- Limpar va_N e datas customizadas das parcelas que serão removidas
  FOR i IN 1..p_quantidade LOOP
    v_num := v_emp.quantidade_parcelas - i + 1;
    v_prorrogs := v_prorrogs - ('va_' || v_num::TEXT);
    v_prorrogs := v_prorrogs - (v_num::TEXT);
    v_prorrogs := v_prorrogs - ('data_liq_' || v_num::TEXT);
    v_prorrogs := v_prorrogs - ('liq_por_' || v_num::TEXT);
    v_prorrogs := v_prorrogs - ('pago_' || v_num::TEXT);
  END LOOP;

  v_novas_abertas := v_parcelas_abertas - p_quantidade;

  -- Limpar va_N das parcelas que permanecem abertas
  FOR i IN 1..v_novas_abertas LOOP
    v_num := v_emp.parcelas_pagas + i;
    v_prorrogs := v_prorrogs - ('va_' || v_num::TEXT);
  END LOOP;

  -- Redistribuição fresca com precisão de centavo
  v_pendente_cents := ROUND(v_pendente * 100)::INTEGER;
  v_base_cents     := v_pendente_cents / v_novas_abertas;
  v_resto_cents    := v_pendente_cents - v_base_cents * v_novas_abertas;

  FOR i IN 1..v_novas_abertas LOOP
    v_target_cents := v_base_cents + CASE WHEN i <= v_resto_cents THEN 1 ELSE 0 END;
    v_va_cents     := v_target_cents - v_parcela_cents;
    IF v_va_cents <> 0 THEN
      v_num := v_emp.parcelas_pagas + i;
      v_prorrogs := jsonb_set(v_prorrogs,
        ARRAY['va_' || v_num::TEXT],
        to_jsonb((v_va_cents::NUMERIC / 100)::TEXT));
    END IF;
  END LOOP;

  UPDATE financeiro.emprestimos SET
    quantidade_parcelas = v_emp.quantidade_parcelas - p_quantidade,
    prorrogacoes        = v_prorrogs
  WHERE id = p_id;

  RETURN json_build_object(
    'ok',            true,
    'novas_abertas', v_novas_abertas,
    'pendente',      v_pendente
  );
END;
$$;


--
-- Name: set_destinatarios_atualizado_em(); Type: FUNCTION; Schema: financeiro; Owner: -
