--
-- Name: sincronizar_nome_produto_nfs(text, text, text, text, text); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.sincronizar_nome_produto_nfs(p_pedido_pai text, p_cod_produto text, p_cor text, p_nome_antigo text, p_novo_nome text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'financeiro'
    AS $$
DECLARE
  v_nf              record;
  v_novos_itens     jsonb;
  v_item            jsonb;
  v_idx             int;
  v_nfs_afetadas    int := 0;
  v_itens_afetados  int := 0;
  v_mudou           boolean;
  v_tem_codigo      boolean;
BEGIN
  v_tem_codigo := p_cod_produto IS NOT NULL AND btrim(p_cod_produto) <> '';

  FOR v_nf IN
    SELECT id, itens_faturados
    FROM financeiro.notas_fiscais
    WHERE status = 'EMITIDA'
      AND tipo_nota = 'VENDA'
      AND itens_faturados IS NOT NULL
      AND jsonb_array_length(itens_faturados) > 0
      AND (pedido_pai = p_pedido_pai OR p_pedido_pai = ANY(pedidos_unificados))
  LOOP
    v_novos_itens := '[]'::jsonb;
    v_mudou := false;

    FOR v_idx IN 0 .. jsonb_array_length(v_nf.itens_faturados) - 1 LOOP
      v_item := v_nf.itens_faturados -> v_idx;

      IF COALESCE(v_item->>'cor', '') = COALESCE(p_cor, '')
         AND (
           (v_tem_codigo AND (v_item->>'cod_produto') = p_cod_produto)
           OR
           (NOT v_tem_codigo AND lower(btrim(v_item->>'nome_produto')) = lower(btrim(p_nome_antigo)))
         )
         AND (
           v_item->>'pedido_origem' IS NULL
           OR v_item->>'pedido_origem' = p_pedido_pai
         )
         AND (v_item->>'nome_produto') IS DISTINCT FROM p_novo_nome
      THEN
        v_item := jsonb_set(v_item, '{nome_produto}', to_jsonb(p_novo_nome));
        v_mudou := true;
        v_itens_afetados := v_itens_afetados + 1;
      END IF;

      v_novos_itens := v_novos_itens || jsonb_build_array(v_item);
    END LOOP;

    IF v_mudou THEN
      UPDATE financeiro.notas_fiscais
      SET itens_faturados = v_novos_itens
      WHERE id = v_nf.id;
      v_nfs_afetadas := v_nfs_afetadas + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'nfs_atualizadas', v_nfs_afetadas,
    'itens_atualizados', v_itens_afetados
  );
END;
$$;


--
-- Name: sync_parcela_planilha(jsonb); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.sync_parcela_planilha(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'financeiro'
    SET statement_timeout TO '120s'
    AS $$
DECLARE
  v_venda_id     uuid;
  v_parcela_id   uuid;
  v_pedido       text  := p->>'pedido_pai';
  v_tipo         text  := COALESCE(p->>'tipo', 'PARCELA');
  v_num          smallint := NULLIF(p->>'numero_parcela','')::smallint;
  v_data_venc    date  := NULLIF(p->>'data_vencimento','')::date;
  v_valor        numeric := (p->>'valor')::numeric;
  v_data_pgto    date  := NULLIF(p->>'data_pagamento','')::date;
  v_forma        text  := NULLIF(p->>'forma_pagamento','');
  v_obs_p        text  := NULLIF(p->>'obs','');
  v_aba          text  := COALESCE(p->>'aba_origem', 'ReceberDB');
  v_ano          smallint := NULLIF(p->>'ano_origem','')::smallint;
  v_status_calc  text;
  v_status_atual text;
  v_acao         text;
  v_qtd_vendas   integer;
  v_venda_ids    uuid[];
BEGIN
  -- 0) Aumenta lock_timeout local (role authenticator tem 8s; precisamos esperar advisory lock)
  SET LOCAL lock_timeout = '60s';

  -- 0.1) Advisory lock por pedido_pai: serializa transacoes que tocam no mesmo pedido.
  -- Elimina deadlocks entre chunks paralelos no n8n quando ambos atualizam parcelas da mesma venda.
  -- O lock libera automaticamente no fim da transacao (xact_lock).
  IF v_pedido IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtext(v_pedido)::bigint);
  END IF;

  -- 1) Override: se o payload trouxer venda_id explicito, usa direto
  IF (p->>'venda_id') IS NOT NULL AND length(p->>'venda_id') > 0 THEN
    v_venda_id := (p->>'venda_id')::uuid;
  ELSE
    -- Resolve venda_id por pedido_pai. Trata ambiguidade.
    SELECT array_agg(id) INTO v_venda_ids
      FROM financeiro.vendas_unificadas WHERE pedido_pai = v_pedido;
    v_qtd_vendas := COALESCE(array_length(v_venda_ids,1), 0);

    IF v_qtd_vendas = 0 THEN
      RETURN jsonb_build_object('acao','SKIP_VENDA_NAO_ENCONTRADA','pedido_pai',v_pedido);
    ELSIF v_qtd_vendas > 1 THEN
      RETURN jsonb_build_object(
        'acao','SKIP_PEDIDO_AMBIGUO',
        'pedido_pai', v_pedido,
        'qtd_vendas_encontradas', v_qtd_vendas,
        'venda_ids', to_jsonb(v_venda_ids),
        'hint','Use venda_id explicito no payload para desambiguar'
      );
    ELSE
      v_venda_id := v_venda_ids[1];
    END IF;
  END IF;

  -- 2) Status: tem data_pagamento -> PAGO; senao usa o que veio (default ABERTO)
  v_status_calc := CASE WHEN v_data_pgto IS NOT NULL THEN 'PAGO' ELSE COALESCE(p->>'status','ABERTO') END;

  -- 3) Procura parcela existente por chave natural
  IF v_tipo = 'ENTRADA' THEN
    SELECT id, status INTO v_parcela_id, v_status_atual
      FROM financeiro.vendas_parcelas
     WHERE venda_id=v_venda_id AND tipo='ENTRADA';
  ELSIF v_tipo = 'PARCELA' AND v_num IS NOT NULL THEN
    SELECT id, status INTO v_parcela_id, v_status_atual
      FROM financeiro.vendas_parcelas
     WHERE venda_id=v_venda_id AND tipo='PARCELA' AND numero_parcela=v_num;
  ELSIF v_tipo = 'FRETE' THEN
    SELECT id, status INTO v_parcela_id, v_status_atual
      FROM financeiro.vendas_parcelas
     WHERE venda_id=v_venda_id AND tipo='FRETE'
       AND data_vencimento IS NOT DISTINCT FROM v_data_venc
       AND valor = v_valor
     LIMIT 1;
  END IF;

  -- 4) INSERT ou UPDATE
  IF v_parcela_id IS NULL THEN
    INSERT INTO financeiro.vendas_parcelas (
      venda_id, tipo, numero_parcela, data_vencimento, valor, status,
      data_pagamento, forma_pagamento, obs, aba_origem, ano_origem, atualizado_por
    ) VALUES (
      v_venda_id, v_tipo, v_num, v_data_venc, v_valor, v_status_calc,
      v_data_pgto, v_forma, v_obs_p, v_aba, v_ano, 'n8n-sync-planilha'
    ) RETURNING id INTO v_parcela_id;
    v_acao := 'INSERT';
  ELSE
    UPDATE financeiro.vendas_parcelas SET
      data_vencimento = COALESCE(v_data_venc, data_vencimento),
      valor           = COALESCE(v_valor, valor),
      status          = CASE
                          WHEN v_status_calc = 'PAGO' THEN 'PAGO'
                          WHEN status = 'PAGO' THEN 'PAGO'
                          ELSE v_status_calc
                        END,
      data_pagamento  = COALESCE(v_data_pgto, data_pagamento),
      forma_pagamento = COALESCE(v_forma, forma_pagamento),
      obs             = COALESCE(obs, v_obs_p),
      aba_origem      = v_aba,
      ano_origem      = COALESCE(v_ano, ano_origem)
    WHERE id = v_parcela_id;
    v_acao := CASE WHEN v_status_atual <> 'PAGO' AND v_status_calc = 'PAGO' THEN 'UPDATE_BAIXOU' ELSE 'UPDATE' END;
  END IF;

  RETURN jsonb_build_object(
    'acao', v_acao,
    'pedido_pai', v_pedido,
    'parcela_id', v_parcela_id,
    'tipo', v_tipo,
    'numero_parcela', v_num,
    'status', v_status_calc
  );
END;
$$;


--
-- Name: FUNCTION sync_parcela_planilha(p jsonb); Type: COMMENT; Schema: financeiro; Owner: -
--

COMMENT ON FUNCTION financeiro.sync_parcela_planilha(p jsonb) IS 'UPSERT idempotente. Aceita venda_id explicito (override) OU resolve por pedido_pai. Se pedido_pai for ambiguo (>1 venda) retorna SKIP_PEDIDO_AMBIGUO com lista de venda_ids candidatos. Nunca regride PAGO->ABERTO. Preserva campos do app (banco_id, idboleto, cnpj).';


--
-- Name: sync_vendas_unificadas_from_oc(text, integer, integer); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.sync_vendas_unificadas_from_oc(p_pedido_pai text, p_ano integer, p_mes integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$
DECLARE
  r record;
  v_id uuid;
  v_existe_pago numeric;
  v_existe_situacao text;
  v_tem_parcela boolean;
BEGIN
  -- Corte fixo: somente Maio/2026 em diante. Meses anteriores (planilha) ficam intactos.
  IF (p_ano < 2026) OR (p_ano = 2026 AND p_mes < 5) THEN
    RETURN 'SKIP_PERIODO';
  END IF;

  -- Agrega itens da OC. NAO usa status_pagamento da OC (esse e o pagamento ao FORNECEDOR, nao do cliente).
  SELECT
    count(*) AS itens,
    sum(qtd_pedido * valor_vendido_unid) AS valor_total,
    max(vendedor) AS vendedor,
    max(empresa) AS empresa,
    max(cnpj) AS cnpj,
    max(cliente) AS cliente,
    min(data_venda)::date AS data_venda,
    max(data_entrega) AS data_entrega
  INTO r
  FROM vendas.ordens_compra
  WHERE regexp_replace(pedido, '-(\d+)$', '') = p_pedido_pai
    AND ano = p_ano AND mes = p_mes AND excluido_em IS NULL;

  IF r.itens IS NULL OR r.itens = 0 THEN
    DELETE FROM financeiro.vendas_unificadas
     WHERE pedido_pai = p_pedido_pai AND ano_referencia = p_ano AND mes_referencia = p_mes
       AND origem = 'OPERACIONAL';
    RETURN 'REMOVIDO_OU_VAZIO';
  END IF;

  -- Estado de pagamento existente (vem das PARCELAS do cliente, nunca da OC)
  SELECT v.valor_pago, v.situacao_pagamento,
         EXISTS(SELECT 1 FROM financeiro.vendas_parcelas p WHERE p.venda_id = v.id)
    INTO v_existe_pago, v_existe_situacao, v_tem_parcela
  FROM financeiro.vendas_unificadas v
  WHERE v.pedido_pai = p_pedido_pai AND v.ano_referencia = p_ano AND v.mes_referencia = p_mes;

  INSERT INTO financeiro.vendas_unificadas (
    pedido_pai, ano_referencia, mes_referencia, vendedor, data_venda, data_entrega,
    empresa, cnpj, cliente_contato, valor_total, valor_pago,
    situacao_pagamento, origem, criado_por
  ) VALUES (
    p_pedido_pai, p_ano, p_mes, r.vendedor, r.data_venda, r.data_entrega,
    r.empresa, r.cnpj, r.cliente, r.valor_total, 0,
    'PENDENTE', 'OPERACIONAL', 'sync_oc'
  )
  ON CONFLICT (pedido_pai, ano_referencia, mes_referencia) DO UPDATE SET
    vendedor = EXCLUDED.vendedor,
    data_venda = COALESCE(EXCLUDED.data_venda, financeiro.vendas_unificadas.data_venda),
    data_entrega = COALESCE(EXCLUDED.data_entrega, financeiro.vendas_unificadas.data_entrega),
    empresa = EXCLUDED.empresa,
    cnpj = COALESCE(EXCLUDED.cnpj, financeiro.vendas_unificadas.cnpj),
    cliente_contato = EXCLUDED.cliente_contato,
    valor_total = EXCLUDED.valor_total,
    -- pagamento NUNCA vem da OC: preserva o que as parcelas ja definiram
    valor_pago = COALESCE(v_existe_pago, 0),
    situacao_pagamento = COALESCE(v_existe_situacao, 'PENDENTE'),
    origem = 'OPERACIONAL',
    atualizado_em = now(),
    atualizado_por = 'sync_oc'
  RETURNING id INTO v_id;

  -- Se tem parcelas, recalcula pelo pagamento real do cliente
  IF v_tem_parcela THEN
    PERFORM financeiro.recalcular_venda_unificada(v_id);
  END IF;

  RETURN 'OK:' || v_id::text;
END;
$_$;


--
-- Name: unificar_pedidos(uuid[], uuid, text); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.unificar_pedidos(p_venda_ids uuid[], p_lider_id uuid, p_usuario text DEFAULT 'sistema'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'financeiro'
    AS $$
DECLARE
  v_ids             uuid[];
  v_grupo_id        uuid := gen_random_uuid();
  v_total_grupo     numeric;
  v_qtd             int;
  v_qtd_encontrados int;
  v_qtd_vendedores  int;
  v_qtd_empresas    int;
  v_qtd_unificados  int;
  v_qtd_com_parcela int;
  v_pedidos         text[];
  v_lider_pedido    text;
BEGIN
  SELECT array_agg(DISTINCT x) INTO v_ids
  FROM unnest(p_venda_ids) AS x
  WHERE x IS NOT NULL;

  v_qtd := COALESCE(array_length(v_ids, 1), 0);

  IF v_qtd < 2 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Selecione ao menos 2 pedidos para unificar.');
  END IF;

  IF p_lider_id IS NULL OR NOT (p_lider_id = ANY(v_ids)) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'O pedido principal (lider) precisa estar na selecao.');
  END IF;

  SELECT COUNT(*),
         COUNT(DISTINCT COALESCE(vendedor, '')),
         COUNT(DISTINCT COALESCE(empresa, '')),
         COUNT(*) FILTER (WHERE grupo_unificacao_id IS NOT NULL),
         COALESCE(SUM(valor_total), 0)
    INTO v_qtd_encontrados, v_qtd_vendedores, v_qtd_empresas, v_qtd_unificados, v_total_grupo
  FROM financeiro.vendas_unificadas
  WHERE id = ANY(v_ids);

  IF v_qtd_encontrados <> v_qtd THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Um ou mais pedidos nao foram encontrados.');
  END IF;

  IF v_qtd_vendedores > 1 OR v_qtd_empresas > 1 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'So e possivel unificar pedidos do mesmo vendedor e empresa.');
  END IF;

  IF v_qtd_unificados > 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Um ou mais pedidos ja estao unificados em outro grupo. Desfaca antes.');
  END IF;

  SELECT COUNT(*) INTO v_qtd_com_parcela
  FROM financeiro.vendas_parcelas vp
  WHERE vp.venda_id = ANY(v_ids)
    AND vp.tipo IN ('PARCELA', 'ENTRADA');

  IF v_qtd_com_parcela > 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Um ou mais pedidos ja possuem parcelas/boleto. Unifique ANTES de gerar a cobranca.');
  END IF;

  SELECT pedido_pai INTO v_lider_pedido
  FROM financeiro.vendas_unificadas WHERE id = p_lider_id;

  SELECT array_agg(pedido_pai ORDER BY pedido_pai) INTO v_pedidos
  FROM financeiro.vendas_unificadas WHERE id = ANY(v_ids);

  UPDATE financeiro.vendas_unificadas
  SET valor_total_original = valor_total,
      valor_total          = 0,
      grupo_unificacao_id  = v_grupo_id,
      unif_papel           = 'MEMBRO',
      atualizado_por       = p_usuario,
      atualizado_em        = now()
  WHERE id = ANY(v_ids) AND id <> p_lider_id;

  UPDATE financeiro.vendas_unificadas
  SET valor_total_original = valor_total,
      valor_total          = v_total_grupo,
      grupo_unificacao_id  = v_grupo_id,
      unif_papel           = 'LIDER',
      pedidos_unificados   = v_pedidos,
      atualizado_por       = p_usuario,
      atualizado_em        = now()
  WHERE id = p_lider_id;

  RETURN jsonb_build_object(
    'ok',                     true,
    'grupo_unificacao_id',    v_grupo_id,
    'lider_id',               p_lider_id,
    'lider_pedido',           v_lider_pedido,
    'pedidos',                to_jsonb(v_pedidos),
    'pedido_pai_concatenado', array_to_string(v_pedidos, ' / '),
    'valor_total_grupo',      v_total_grupo,
    'qtd_pedidos',            v_qtd
  );
END;
$$;


--
-- Name: upsert_venda_unificada(jsonb); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.upsert_venda_unificada(p_payload jsonb) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_id uuid;
  v_pedido_pai text;
BEGIN
  v_pedido_pai := p_payload->>'pedido_pai';
  IF v_pedido_pai IS NULL OR v_pedido_pai = '' THEN
    RAISE EXCEPTION 'pedido_pai obrigatório';
  END IF;

  INSERT INTO financeiro.vendas_unificadas (
    pedido_pai, vendedor, data_venda, data_entrega, empresa, razao_social, cnpj,
    cliente_contato, cidade_estado, valor_total, tipo_pagamento, qtd_parcelas,
    boleto_emitido, situacao_pagamento, nf_venda, nf_emitida_em, obs, origem,
    criado_por
  ) VALUES (
    v_pedido_pai,
    p_payload->>'vendedor',
    NULLIF(p_payload->>'data_venda','')::date,
    NULLIF(p_payload->>'data_entrega','')::date,
    p_payload->>'empresa',
    p_payload->>'razao_social',
    p_payload->>'cnpj',
    p_payload->>'cliente_contato',
    p_payload->>'cidade_estado',
    COALESCE((p_payload->>'valor_total')::numeric, 0),
    p_payload->>'tipo_pagamento',
    COALESCE((p_payload->>'qtd_parcelas')::smallint, 0),
    COALESCE((p_payload->>'boleto_emitido')::boolean, false),
    COALESCE(p_payload->>'situacao_pagamento', 'PENDENTE'),
    p_payload->>'nf_venda',
    NULLIF(p_payload->>'nf_emitida_em','')::timestamptz,
    p_payload->>'obs',
    COALESCE(p_payload->>'origem', 'MANUAL'),
    p_payload->>'criado_por'
  )
  ON CONFLICT (pedido_pai) DO UPDATE SET
    vendedor = COALESCE(EXCLUDED.vendedor, financeiro.vendas_unificadas.vendedor),
    data_venda = COALESCE(EXCLUDED.data_venda, financeiro.vendas_unificadas.data_venda),
    data_entrega = COALESCE(EXCLUDED.data_entrega, financeiro.vendas_unificadas.data_entrega),
    empresa = COALESCE(EXCLUDED.empresa, financeiro.vendas_unificadas.empresa),
    razao_social = COALESCE(EXCLUDED.razao_social, financeiro.vendas_unificadas.razao_social),
    cnpj = COALESCE(EXCLUDED.cnpj, financeiro.vendas_unificadas.cnpj),
    cliente_contato = COALESCE(EXCLUDED.cliente_contato, financeiro.vendas_unificadas.cliente_contato),
    cidade_estado = COALESCE(EXCLUDED.cidade_estado, financeiro.vendas_unificadas.cidade_estado),
    valor_total = EXCLUDED.valor_total,
    tipo_pagamento = COALESCE(EXCLUDED.tipo_pagamento, financeiro.vendas_unificadas.tipo_pagamento),
    qtd_parcelas = EXCLUDED.qtd_parcelas,
    boleto_emitido = EXCLUDED.boleto_emitido,
    nf_venda = COALESCE(EXCLUDED.nf_venda, financeiro.vendas_unificadas.nf_venda),
    nf_emitida_em = COALESCE(EXCLUDED.nf_emitida_em, financeiro.vendas_unificadas.nf_emitida_em),
    obs = COALESCE(EXCLUDED.obs, financeiro.vendas_unificadas.obs),
    atualizado_em = now(),
    atualizado_por = EXCLUDED.criado_por
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


--
-- Name: vendedores_acima_50k_hoje(); Type: FUNCTION; Schema: financeiro; Owner: -
--

CREATE FUNCTION financeiro.vendedores_acima_50k_hoje() RETURNS TABLE(vendedor text, total_vendido numeric, qtd_pedidos bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'financeiro', 'vendas'
    AS $$
  SELECT
    v.vendedor,
    SUM(v.valor_total)  AS total_vendido,
    COUNT(*)            AS qtd_pedidos
  FROM financeiro.vendas_unificadas v
  WHERE v.data_venda = CURRENT_DATE AT TIME ZONE 'America/Sao_Paulo'
  GROUP BY v.vendedor
  HAVING SUM(v.valor_total) >= 50000
  ORDER BY total_vendido DESC;
$$;


--
-- Name: fn_integration_health(); Type: FUNCTION; Schema: monitoring; Owner: -
--

CREATE FUNCTION monitoring.fn_integration_health() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'monitoring', 'evo', 'zapp'
    AS $$
DECLARE v_result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'checked_at', now(),
    'whatsapp_instances', (
      SELECT jsonb_agg(jsonb_build_object(
        'name', wc.name, 'instance_name', wc.instance_name, 'status', wc.status,
        'last_health_check', wc.last_health_check,
        'minutes_since_health', EXTRACT(EPOCH FROM (now()-wc.last_health_check))/60
      ) ORDER BY wc.name) FROM public.whatsapp_connections wc),
    'outbound_queue', (
      SELECT CASE WHEN count(*)=0 THEN jsonb_build_object('empty', true)
      ELSE jsonb_object_agg(coalesce(status,'unknown'), cnt) END
      FROM (SELECT status, count(*) AS cnt FROM zapp.outbound_message_queue GROUP BY status) q),
    'last_messages_wpp2', (
      SELECT jsonb_agg(jsonb_build_object(
        'id', m.id, 'remote_jid', m.remote_jid, 'from_me', m.from_me,
        'created_at', m.created_at, 'minutes_ago', EXTRACT(EPOCH FROM (now()-m.created_at))/60
      ) ORDER BY m.created_at DESC)
      FROM (SELECT id,remote_jid,from_me,created_at FROM evo.evolution_messages
            WHERE instance_name='wpp2' AND deleted_at IS NULL ORDER BY created_at DESC LIMIT 5) m),
    'reconcile_recent', (
      SELECT jsonb_agg(jsonb_build_object(
        'request_id', rj.request_id, 'dispatched_at', rj.dispatched_at,
        'applied_at', rj.applied_at, 'http_status', rj.http_status,
        'is_ok', (rj.http_status BETWEEN 200 AND 299)
      ) ORDER BY rj.dispatched_at DESC)
      FROM (SELECT request_id,dispatched_at,applied_at,http_status
            FROM evo.evolution_reconcile_jobs ORDER BY dispatched_at DESC LIMIT 10) rj),
    'rpcs_summary', (
      SELECT jsonb_build_object(
        'total_rpcs', count(*),
        'anon_accessible', count(*) FILTER (WHERE has_function_privilege('anon',p.oid,'EXECUTE')),
        'authenticated_only', count(*) FILTER (WHERE NOT has_function_privilege('anon',p.oid,'EXECUTE') AND has_function_privilege('authenticated',p.oid,'EXECUTE'))
      ) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
      WHERE n.nspname='public' AND p.proname LIKE 'rpc_%'),
    'open_alerts', (
      SELECT jsonb_build_object('total',count(*),'critical',count(*) FILTER (WHERE severity='critical'),'warning',count(*) FILTER (WHERE severity='warning'))
      FROM evo.evolution_alerts WHERE resolved=false),
    'partition_sizes', (
      SELECT jsonb_object_agg(relname, jsonb_build_object(
        'total_mb', round((pg_total_relation_size('evo.'||relname)/1048576.0)::numeric,1),
        'rows', n_live_tup))
      FROM pg_stat_user_tables
      WHERE schemaname='evo' AND relname IN ('evolution_messages_wpp2','evolution_messages_wpp_pink_test',
                                              'evolution_messages_default','evolution_conversations_wpp2')),
    'realtime_health', jsonb_build_object(
      'evo_messages_published', EXISTS(SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='evo' AND tablename='evolution_messages'),
      'evo_contacts_published', EXISTS(SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='evo' AND tablename='evolution_contacts'),
      'publish_via_root', (SELECT pubviaroot FROM pg_publication WHERE pubname='supabase_realtime'),
      'partitions_ri_full', (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='evo' AND c.relname LIKE 'evolution_messages_%' AND c.relkind='r' AND c.relreplident='f'),
      'partitions_ri_default', (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='evo' AND c.relname LIKE 'evolution_messages_%' AND c.relkind='r' AND c.relreplident='d'),
      'contacts_ri_full', (SELECT relreplident='f' FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='evo' AND c.relname='evolution_contacts')
    ),
    'schema_health', jsonb_build_object(
      'graveyard_regular_tables', (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='graveyard' AND c.relkind='r'),
      'graveyard_partitioned_parents', (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='graveyard' AND c.relkind='p'),
      'evo_messages_partitions', (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='evo' AND c.relname LIKE 'evolution_messages_%' AND c.relkind='r' AND EXISTS(SELECT 1 FROM pg_inherits i WHERE i.inhrelid=c.oid)),
      'conv_timeline_index_valid', (SELECT indisvalid FROM pg_index ix JOIN pg_class c ON c.oid=ix.indexrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='evo' AND c.relname='idx_evo_msgs_conv_timeline'),
      'conv_timeline_partitions_attached', (SELECT count(*) FROM pg_inherits pi JOIN pg_class c ON c.oid=pi.inhparent WHERE c.relname='idx_evo_msgs_conv_timeline')
    )
  ) INTO v_result;
  RETURN v_result;
END;
$$;


