--
-- Name: _bf_insert(jsonb, bigint); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops._bf_insert(p jsonb, ts bigint) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE v jsonb;
BEGIN
  v := zapp.fn_process_whatsapp_message(p, 'wpp2');
  IF (v->>'ok')::boolean AND v->>'message_pk' IS NOT NULL THEN
    UPDATE evo.evolution_messages_wpp2 SET created_at = to_timestamp(ts) WHERE id = (v->>'message_pk')::uuid;
  END IF;
  RETURN v;
END $$;


--
-- Name: auth_session_cleanup(integer, integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.auth_session_cleanup(p_keep_last integer DEFAULT 5, p_min_age_hours integer DEFAULT 24) RETURNS TABLE(sessions_deleted bigint, tokens_deleted bigint, execution_ms numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops, pg_temp'
    AS $$
DECLARE
  v_start        TIMESTAMPTZ := clock_timestamp();
  v_ses_del      BIGINT := 0;
  v_tok_del      BIGINT := 0;
  v_lock_acq     BOOLEAN;
BEGIN
  -- Advisory lock: previne execucoes concorrentes
  SELECT pg_try_advisory_xact_lock(hashtext('ops.auth_session_cleanup'))
  INTO v_lock_acq;
  IF NOT v_lock_acq THEN
    RAISE WARNING 'auth_session_cleanup: concorrencia detectada, abortando';
    RETURN QUERY SELECT 0::BIGINT, 0::BIGINT, 0::NUMERIC;
    RETURN;
  END IF;

  BEGIN
    -- Desabilitar triggers GoTrue para evitar FK cascade bloqueante
    SET LOCAL session_replication_role = replica;

    -- Deletar sessoes em excesso: manter p_keep_last mais recentes por usuario
    -- Guard: so sessoes com idade > p_min_age_hours E sem expiracao futura
    WITH ranked AS (
      SELECT id,
             ROW_NUMBER() OVER (
               PARTITION BY user_id
               ORDER BY updated_at DESC, id DESC
             ) AS rn
      FROM auth.sessions
      WHERE updated_at < NOW() - (p_min_age_hours || ' hours')::INTERVAL
        AND (not_after IS NULL OR not_after < NOW())
    ),
    del AS (
      DELETE FROM auth.sessions
      WHERE id IN (SELECT id FROM ranked WHERE rn > p_keep_last)
      RETURNING id
    )
    SELECT COUNT(*) INTO v_ses_del FROM del;

    -- Limpar refresh_tokens orfaos
    DELETE FROM auth.refresh_tokens
    WHERE session_id IS NOT NULL
      AND session_id NOT IN (SELECT id FROM auth.sessions)
      AND created_at < NOW() - INTERVAL '1 hour';

    GET DIAGNOSTICS v_tok_del = ROW_COUNT;

    -- Reset replication role
    SET LOCAL session_replication_role = DEFAULT;

  EXCEPTION WHEN OTHERS THEN
    SET LOCAL session_replication_role = DEFAULT;
    RAISE WARNING 'auth_session_cleanup ERRO: %', SQLERRM;
    RETURN QUERY SELECT 0::BIGINT, 0::BIGINT, 0::NUMERIC;
    RETURN;
  END;

  -- Log no changelog se houve trabalho
  IF v_ses_del > 0 OR v_tok_del > 0 THEN
    INSERT INTO ops.schema_changelog(
      session_label, change_type, object_schema, object_name,
      description, impact, severity
    ) VALUES (
      'auto-cron-' || TO_CHAR(NOW(), 'YYYY-MM-DD-HH24'),
      'FIX', 'auth', 'sessions',
      'Cleanup: ' || v_ses_del || ' sessions + ' || v_tok_del ||
        ' tokens (keep=' || p_keep_last || ', age=' || p_min_age_hours || 'h)',
      'GoTrue 500 prevention', 'LOW'
    ) ON CONFLICT DO NOTHING;
  END IF;

  RETURN QUERY SELECT
    COALESCE(v_ses_del, 0)::BIGINT,
    COALESCE(v_tok_del, 0)::BIGINT,
    ROUND(EXTRACT(EPOCH FROM(clock_timestamp() - v_start)) * 1000, 3);
END;
$$;


--
-- Name: FUNCTION auth_session_cleanup(p_keep_last integer, p_min_age_hours integer); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.auth_session_cleanup(p_keep_last integer, p_min_age_hours integer) IS 'Limpa sessoes auth em excesso. Parametros: keep_last=5, min_age_hours=24.
Protecoes: advisory_lock, session_replication_role, not_after guard, age guard, EXCEPTION handler.';


--
-- Name: calculate_tier(integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.calculate_tier(p_pct integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_pct >= 95 THEN 'EMERGENCY'
    WHEN p_pct >= 92 THEN 'FREEZE'
    WHEN p_pct >= 88 THEN 'THROTTLE'
    WHEN p_pct >= 80 THEN 'WARN'
    WHEN p_pct >= 70 THEN 'NOTICE'
    WHEN p_pct >= 60 THEN 'INFO'
    ELSE 'OK'
  END;
$$;


--
-- Name: schema_drift_log; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.schema_drift_log (
    id bigint NOT NULL,
    run_at timestamp with time zone DEFAULT now() NOT NULL,
    status text NOT NULL,
    missing_tables integer DEFAULT 0 NOT NULL,
    missing_columns integer DEFAULT 0 NOT NULL,
    detail jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT schema_drift_log_status_check CHECK ((status = ANY (ARRAY['OK'::text, 'DRIFT'::text])))
);


--
-- Name: TABLE schema_drift_log; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.schema_drift_log IS 'Histórico de execuções do guard de drift Lovable->canônico.';


--
-- Name: check_critical_fks(boolean); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.check_critical_fks(p_raise boolean DEFAULT false) RETURNS ops.schema_drift_log
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'zapp', 'evo', 'email_app', 'auth', 'pg_catalog'
    AS $$
DECLARE v_missing text[]; v_row ops.schema_drift_log;
BEGIN
  -- R23 FIX 2026-07-16: schemas corrigidos para Cenario B
  -- public.profiles/tags/permissions sao VIEWS, FKs devem apontar para zapp.*
  WITH esperadas(base_schema, base, child_schema, child) AS (VALUES
    ('zapp','role_permissions','zapp','permissions'),
    ('zapp','contact_tags','zapp','tags'),
    ('zapp','sales_deals','zapp','profiles'),
    ('zapp','conversation_events','zapp','profiles'),
    ('zapp','team_conversation_members','zapp','profiles'),
    ('zapp','team_messages','zapp','profiles'),
    ('zapp','user_roles','zapp','profiles'),
    ('zapp','contact_tags','evo','evolution_contacts'),
    ('zapp','sales_deals','evo','evolution_contacts'),
    ('zapp','conversation_events','zapp','queues'),
    ('zapp','followup_executions','zapp','followup_sequences'),
    ('zapp','followup_sequences','zapp','followup_steps'),
    ('zapp','chatbot_executions','zapp','chatbot_flows'),
    ('zapp','team_conversation_members','zapp','profiles'),
    ('zapp','conversation_sla','evo','evolution_contacts'),
    ('email_app','gmail_accounts','zapp','profiles'),
    ('email_app','gmail_accounts','auth','users'),
    ('email_app','email_threads','email_app','gmail_accounts'),
    ('email_app','email_messages','email_app','email_threads'),
    ('email_app','email_drafts','email_app','email_accounts'),
    ('email_app','email_labels','email_app','gmail_accounts')
  )
  SELECT array_agg(base_schema||'.'||base||' -> '||child_schema||'.'||child ORDER BY base_schema,base,child)
  INTO v_missing
  FROM esperadas e
  WHERE EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relname=e.base AND n.nspname=e.base_schema)
    AND NOT EXISTS (
      SELECT 1 FROM pg_constraint k
      JOIN pg_class bc ON bc.oid=k.conrelid JOIN pg_namespace bn ON bn.oid=bc.relnamespace
      JOIN pg_class cc ON cc.oid=k.confrelid JOIN pg_namespace cn ON cn.oid=cc.relnamespace
      WHERE k.contype='f' AND (
        (bc.relname=e.base AND bn.nspname=e.base_schema AND cc.relname=e.child AND cn.nspname=e.child_schema) OR
        (bc.relname=e.child AND bn.nspname=e.child_schema AND cc.relname=e.base AND cn.nspname=e.base_schema)
      ));
  INSERT INTO ops.schema_drift_log(status, missing_tables, missing_columns, detail)
  VALUES (CASE WHEN COALESCE(array_length(v_missing,1),0)>0 THEN 'DRIFT' ELSE 'OK' END,
    0, COALESCE(array_length(v_missing,1),0),
    jsonb_build_object('missing_fks', to_jsonb(COALESCE(v_missing, ARRAY[]::text[])),
      'checked_schemas','["public","zapp","evo","email_app","auth"]'::jsonb,
      'checked_pairs', 21, 'bidirectional', true,
      'generated_at', now(),
      'note','R23 FIX 2026-07-16: schemas corrigidos para Cenario B'
    )) RETURNING * INTO v_row;
  IF p_raise AND v_row.status='DRIFT' THEN RAISE EXCEPTION 'FKs criticas ausentes: %', v_row.detail; END IF;
  RETURN v_row;
END; $$;


--
-- Name: check_host_disk(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.check_host_disk() RETURNS TABLE(check_name text, status text, detail text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops'
    AS $$
DECLARE latest ops.host_disk_log%ROWTYPE; age_min numeric;
BEGIN
  SELECT * INTO latest FROM ops.host_disk_log ORDER BY checked_at DESC LIMIT 1;
  IF NOT FOUND THEN
    RETURN QUERY SELECT 'host_disk'::text, 'WARN'::text, 'nenhuma leitura de disco ainda (coletor iniciando?)'::text;
    RETURN;
  END IF;
  age_min := EXTRACT(EPOCH FROM (now() - latest.checked_at)) / 60;
  IF age_min > 20 THEN
    RETURN QUERY SELECT 'host_disk'::text, 'WARN'::text,
      format('leitura obsoleta: ultima ha %s min (coletor caiu?). ultimo: %s%% %s', round(age_min), latest.used_pct, latest.status);
    RETURN;
  END IF;
  RETURN QUERY SELECT 'host_disk'::text,
    CASE WHEN latest.status = 'CRIT' THEN 'FAIL' WHEN latest.status = 'WARN' THEN 'WARN' ELSE 'OK' END::text,
    format('%s%% usado (livre %s de %s) ha %s min [%s]', latest.used_pct, COALESCE(latest.avail_h, '?'), COALESCE(latest.total_h, '?'), round(age_min), latest.status);
END; $$;


--
-- Name: check_infrastructure(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.check_infrastructure() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'zapp', 'evo', 'extensions'
    AS $$ DECLARE v_result jsonb := '{}'::jsonb; v_issues jsonb := '[]'::jsonb; v_score int := 0; v_max int := 0; v_val int; v_txt text; v_num numeric; BEGIN v_max:=v_max+10; SELECT COUNT(*) INTO v_val FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_constraint pk ON pk.conrelid=c.oid AND pk.contype='p' WHERE c.relkind='r' AND n.nspname IN ('public','zapp','evo') AND pk.oid IS NULL; IF v_val=0 THEN v_score:=v_score+10; ELSE v_issues:=v_issues||jsonb_build_array(jsonb_build_object('check','missing_pk','count',v_val,'severity','high')); END IF; v_result:=v_result||jsonb_build_object('pk',jsonb_build_object('no_pk_tables',v_val,'score',CASE WHEN v_val=0 THEN 10 ELSE 0 END,'max',10)); v_max:=v_max+10; SELECT COUNT(DISTINCT client_addr) INTO v_val FROM pg_stat_activity WHERE application_name LIKE '%mcp%'; IF v_val=1 THEN v_score:=v_score+10; ELSIF v_val=0 THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('check','mcp_offline','severity','critical')); ELSE v_issues:=v_issues||jsonb_build_array(jsonb_build_object('check','mcp_ghost','count',v_val)); END IF; v_result:=v_result||jsonb_build_object('mcp',jsonb_build_object('conns',v_val,'score',CASE WHEN v_val=1 THEN 10 ELSE 0 END,'max',10)); v_max:=v_max+15; SELECT status INTO v_txt FROM zapp.whatsapp_connections WHERE instance_name='wpp2'; IF v_txt='connected' THEN v_score:=v_score+15;
  ELSIF v_txt IN ('connecting','reconnecting') THEN v_score:=v_score+8;
    v_issues:=v_issues||jsonb_build_array(jsonb_build_object('check','wpp2_connecting','severity','medium'));
  ELSE v_issues:=v_issues||jsonb_build_array(jsonb_build_object('check','wpp2_disconnected','severity','high')); END IF; v_result:=v_result||jsonb_build_object('wpp2',jsonb_build_object('status',v_txt,'score',CASE WHEN v_txt='connected' THEN 15 ELSE 0 END,'max',15)); v_max:=v_max+10; SELECT COUNT(*) INTO v_val FROM cron.job_run_details WHERE status='failed' AND start_time>now()-INTERVAL '2h' AND return_message NOT LIKE '%does not exist%' AND return_message NOT LIKE '%VACUUM cannot%'; IF v_val=0 THEN v_score:=v_score+10; ELSIF v_val<3 THEN v_score:=v_score+5; END IF; v_result:=v_result||jsonb_build_object('cron_2h',jsonb_build_object('failures',v_val,'score',CASE WHEN v_val=0 THEN 10 WHEN v_val<3 THEN 5 ELSE 0 END,'max',10)); v_max:=v_max+5; BEGIN EXECUTE 'SELECT COUNT(*) FROM extensions.pg_stat_statements' INTO v_val; v_score:=v_score+5; v_result:=v_result||jsonb_build_object('pss',jsonb_build_object('entries',v_val,'score',5,'max',5)); EXCEPTION WHEN OTHERS THEN v_result:=v_result||jsonb_build_object('pss',jsonb_build_object('score',0,'max',5,'err',SQLERRM)); END; v_max:=v_max+10; SELECT COUNT(*) INTO v_val FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind='r' AND n.nspname IN ('public','zapp') AND NOT c.relrowsecurity; IF v_val=0 THEN v_score:=v_score+10; ELSE v_issues:=v_issues||jsonb_build_array(jsonb_build_object('check','rls_off','tables',v_val,'severity','critical')); END IF; v_result:=v_result||jsonb_build_object('rls',jsonb_build_object('off',v_val,'score',CASE WHEN v_val=0 THEN 10 ELSE 0 END,'max',10)); v_max:=v_max+5; SELECT current_setting('log_min_duration_statement') INTO v_txt; IF v_txt NOT IN ('-1ms','-1') THEN v_score:=v_score+5; END IF; v_result:=v_result||jsonb_build_object('slow_log',jsonb_build_object('val',v_txt,'score',CASE WHEN v_txt NOT IN ('-1ms','-1') THEN 5 ELSE 0 END,'max',5)); v_max:=v_max+10; SELECT COUNT(*) INTO v_val FROM information_schema.views WHERE table_schema='public' AND table_name IN ('zapp_audit_log','contact_audit_log','conversation_audit_logs','webhook_audit_log','team_messages','app_notifications','whatsapp_official_credentials'); IF v_val=7 THEN v_score:=v_score+10; ELSE v_issues:=v_issues||jsonb_build_array(jsonb_build_object('check','bridges','count',v_val,'expected',7)); END IF; v_result:=v_result||jsonb_build_object('bridges',jsonb_build_object('count',v_val,'score',CASE WHEN v_val=7 THEN 10 ELSE 0 END,'max',10)); v_max:=v_max+10; SELECT round(EXTRACT(EPOCH FROM (now()-MAX(snapshot_date)))/3600,1) INTO v_num FROM zapp._db_size_snapshots; IF v_num IS NULL OR v_num>30 THEN v_score:=v_score+5; v_result:=v_result||jsonb_build_object('snapshot',jsonb_build_object('hours_ago',v_num,'score',5,'max',10)); ELSIF v_num<=26 THEN v_score:=v_score+10; v_result:=v_result||jsonb_build_object('snapshot',jsonb_build_object('hours_ago',v_num,'score',10,'max',10)); ELSE v_score:=v_score+7; v_result:=v_result||jsonb_build_object('snapshot',jsonb_build_object('hours_ago',v_num,'score',7,'max',10)); END IF; -- Backup freshness (10 pts)
  v_max:=v_max+10;
  DECLARE v_backup_h numeric; v_backup_tbls int;
  BEGIN
    SELECT round(EXTRACT(EPOCH FROM (now()-last_backup_at))/3600,1), last_backup_table_count
    INTO v_backup_h, v_backup_tbls FROM ops.backup_sentinel WHERE id=1;
    IF v_backup_h IS NOT NULL AND v_backup_h < 26 AND v_backup_tbls >= 400 THEN
      v_score:=v_score+10;
      v_result:=v_result||jsonb_build_object('backup',jsonb_build_object('hours_ago',v_backup_h,'tables',v_backup_tbls,'score',10,'max',10));
    ELSIF v_backup_h IS NOT NULL AND v_backup_h < 48 THEN
      v_score:=v_score+5;
      v_result:=v_result||jsonb_build_object('backup',jsonb_build_object('hours_ago',v_backup_h,'score',5,'max',10,'status','stale'));
    ELSE
      v_issues:=v_issues||jsonb_build_array(jsonb_build_object('check','backup_missing','hours_ago',v_backup_h,'severity','critical'));
      v_result:=v_result||jsonb_build_object('backup',jsonb_build_object('hours_ago',v_backup_h,'score',0,'max',10,'status','CRITICAL'));
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_result:=v_result||jsonb_build_object('backup',jsonb_build_object('score',0,'max',10,'error',SQLERRM));
  END;

  -- Redis health (5 pts)
  v_max:=v_max+5;
  DECLARE v_redis_fresh boolean; v_redis_mem numeric;
  BEGIN
    SELECT last_ping_at > NOW()-INTERVAL '10 minutes' AND maxmemory_policy='allkeys-lru',
      round(100.0*used_memory_mb/NULLIF(maxmemory_mb,0),1)
    INTO v_redis_fresh, v_redis_mem FROM ops.redis_sentinel WHERE id=1;
    IF COALESCE(v_redis_fresh,false) THEN
      v_score:=v_score+5;
      v_result:=v_result||jsonb_build_object('redis',jsonb_build_object('mem_pct',v_redis_mem,'score',5,'max',5,'policy','allkeys-lru'));
    ELSE
      v_issues:=v_issues||jsonb_build_array(jsonb_build_object('check','redis_stale','severity','medium'));
      v_result:=v_result||jsonb_build_object('redis',jsonb_build_object('score',2,'max',5,'status','stale'));
      v_score:=v_score+2;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_result:=v_result||jsonb_build_object('redis',jsonb_build_object('score',0,'max',5,'error',SQLERRM));
  END;

  INSERT INTO ops._infra_check_log(score,max_score,issues,detail,checked_at) VALUES(v_score,v_max,jsonb_array_length(v_issues),v_result,now()); RETURN jsonb_build_object('score',v_score,'max',v_max,'pct',round(100.0*v_score/v_max,1),'issues',v_issues,'detail',v_result,'ts',now()); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error',SQLERRM); END; $$;


--
-- Name: FUNCTION check_infrastructure(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.check_infrastructure() IS 'Verificacao completa da infraestrutura (10 checks): PKs, MCP, conexoes, wpp2, cron failures, pg_stat_statements, RLS, slow_log, bridge views, snapshots. Score /85pts. Cron horario. Criado em auditoria 2026-07-04.';


--
-- Name: check_lovable_parity(boolean); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.check_lovable_parity(p_raise boolean DEFAULT false) RETURNS ops.schema_drift_log
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'zapp', 'pg_catalog'
    AS $$
DECLARE
  v_missing text[] := ARRAY[]::text[];
  v_row ops.schema_drift_log;
BEGIN
  -- ── 1. 8 funções da paridade Lovable (F1 2026-07-03) ─────────────────────
  SELECT v_missing || COALESCE(array_agg('fn:'||e.f), ARRAY[]::text[]) INTO v_missing
  FROM (VALUES ('check_user_permission'),('generate_transfer_ticket'),('handle_new_user_settings'),
               ('is_queue_member_of_contact'),('log_rls_denied'),('on_role_change'),
               ('purge_old_query_telemetry'),('trg_fn_set_transfer_ticket')) e(f)
  WHERE NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
                    WHERE n.nspname='public' AND p.proname=e.f);

  -- ── 2. 3 triggers ────────────────────────────────────────────────────────
  SELECT v_missing || COALESCE(array_agg('trg:'||e.tg), ARRAY[]::text[]) INTO v_missing
  FROM (VALUES ('trg_set_transfer_ticket'),('on_profile_created_settings'),('tr_log_role_changes')) e(tg)
  WHERE NOT EXISTS (SELECT 1 FROM pg_trigger t WHERE t.tgname=e.tg AND NOT t.tgisinternal);

  -- ── 3. 4 views (devem ser VIEWS, não tabelas) ────────────────────────────
  SELECT v_missing || COALESCE(array_agg('view:'||e.s||'.'||e.v), ARRAY[]::text[]) INTO v_missing
  FROM (VALUES ('public','departments_safe'),('public','whatsapp_official_credentials_safe'),
               ('public','channel_connections_safe'),('zapp','channel_connections_safe')) e(s,v)
  WHERE NOT EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
                    WHERE n.nspname=e.s AND c.relname=e.v AND c.relkind='v');

  -- ── 4. Estruturas de suporte ──────────────────────────────────────────────
  -- FIX 2026-07-04 (auditoria exaustiva): processed_webhook_events foi dropada (residual/0 rows).
  -- Tabela canonica e zapp.webhook_events_processed (52.7k rows, RLS habilitado).
  IF to_regclass('zapp.webhook_events_processed') IS NULL THEN v_missing := v_missing || 'table:zapp.webhook_events_processed'; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_sequences WHERE sequencename='transfer_ticket_seq') THEN v_missing := v_missing || 'seq:transfer_ticket_seq'; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_indexes WHERE indexname='user_settings_user_id_key') THEN v_missing := v_missing || 'idx:user_settings_user_id_key'; END IF;
  -- FIX 2026-07-04: whatsapp_official_credentials migrada para zapp schema; buscar em ambos
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema IN ('public','zapp') AND table_name='whatsapp_official_credentials' AND column_name='app_id') THEN v_missing := v_missing || 'col:whatsapp_official_credentials.app_id'; END IF;

  -- ── 5. Cron jobs críticos ativos ─────────────────────────────────────────
  SELECT v_missing || COALESCE(array_agg('cron:'||e.j), ARRAY[]::text[]) INTO v_missing
  FROM (VALUES ('purge_query_telemetry_daily'),('vault_healthcheck'),('pipeline-watchdog'),
               ('ops-guardrails-deadman'),('ops-notify-critical-alerts')) e(j)
  WHERE NOT EXISTS (SELECT 1 FROM cron.job WHERE jobname=e.j AND active);

  -- ── 6. Realtime publication (3 tabelas Lovable) ───────────────────────────
  SELECT v_missing || COALESCE(array_agg('realtime:'||e.t), ARRAY[]::text[]) INTO v_missing
  FROM (VALUES ('message_reactions'),('conversation_transfers'),('transfer_comments')) e(t)
  WHERE NOT EXISTS (SELECT 1 FROM pg_publication_tables pt WHERE pt.pubname='supabase_realtime' AND pt.tablename=e.t);

  -- ── 7. pg_statistic health ─────────────────────────────────────────────
  IF EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid='cron.job_run_details'::regclass AND attname='command' AND attstattarget != 0) THEN
    v_missing := v_missing || 'pg_stat:cron.job_run_details.command.attstattarget_should_be_0';
  END IF;

  -- ── 8. Self-check ────────────────────────────────────────────────────────
  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='ops' AND p.proname='check_lovable_parity') THEN
    v_missing := v_missing || 'fn:ops.check_lovable_parity';
  END IF;

  -- ── Gravar resultado ──────────────────────────────────────────────────────
  INSERT INTO ops.schema_drift_log(status, missing_tables, missing_columns, detail)
  VALUES (
    CASE WHEN COALESCE(array_length(v_missing,1),0) > 0 THEN 'DRIFT' ELSE 'OK' END,
    0, COALESCE(array_length(v_missing,1),0),
    jsonb_build_object('check','lovable_parity','version','v2.1 2026-07-04-audit','missing_objects', to_jsonb(v_missing))
  ) RETURNING * INTO v_row;

  IF v_row.status = 'DRIFT' THEN
    INSERT INTO zapp.webhook_health_alerts(alert_type, severity, title, details)
    VALUES ('lovable_parity_drift', 'high', 'Drift de paridade Lovable detectado: '||array_length(v_missing,1)||' objeto(s)',
            jsonb_build_object('missing', to_jsonb(v_missing), 'source', 'ops.check_lovable_parity', 'version', 'v2.1'))
    ON CONFLICT DO NOTHING;
    IF p_raise THEN
      RAISE EXCEPTION 'LOVABLE PARITY DRIFT -> %', v_missing;
    END IF;
  END IF;

  RETURN v_row;
END;
$$;


--
-- Name: FUNCTION check_lovable_parity(p_raise boolean); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.check_lovable_parity(p_raise boolean) IS 'DEPRECATED (2026-08-03). Mantida porque ops.run_all_checks() (cron 106 run_all_checks_daily, 07:00) ainda a invoca. Valida objetos SQL da paridade Lovable-era (F1/F3) + crons críticos + pg_statistic health; DRIFT → alerta em zapp.webhook_health_alerts. Novo nome neutro: ops.check_schema_parity() (wrapper que delega a esta).';


--
-- Name: check_marketing_budget(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.check_marketing_budget() RETURNS TABLE(check_name text, status text, detail text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'evo'
    AS $_$ DECLARE cfg ops.wa_marketing_budget%ROWTYPE; sent_count bigint; tmpl_count bigint; spend numeric; pct numeric; pct_pc int; cfg_err text := NULL; BEGIN SELECT * INTO cfg FROM ops.wa_marketing_budget WHERE id = 1; IF NOT FOUND THEN RETURN QUERY SELECT 'wa_marketing_budget'::text, 'WARN'::text, 'config ausente (id=1)'::text; RETURN; END IF; IF cfg.monthly_budget_brl <= 0 THEN cfg_err := format('config invalida: monthly_budget_brl=%s (deve ser > 0)', cfg.monthly_budget_brl); ELSIF cfg.tariff_marketing_brl <= 0 THEN cfg_err := format('config invalida: tariff_marketing_brl=%s (deve ser > 0)', cfg.tariff_marketing_brl); ELSIF cfg.alert_threshold > cfg.hard_stop_threshold THEN cfg_err := format('config invalida: alert_threshold (%s) > hard_stop_threshold (%s)', cfg.alert_threshold, cfg.hard_stop_threshold); END IF; IF cfg_err IS NOT NULL THEN BEGIN INSERT INTO zapp.warroom_alerts (alert_type, title, message, source, entity) VALUES ('warning', 'WA Marketing: budget guard com config invalida', cfg_err, 'ops.check_marketing_budget', cfg.instance_name); EXCEPTION WHEN OTHERS THEN NULL; END; RETURN QUERY SELECT 'wa_marketing_budget'::text, 'WARN'::text, cfg_err; RETURN; END IF; SELECT count(*), count(*) FILTER (WHERE template_name IS NOT NULL) INTO sent_count, tmpl_count FROM evo.evolution_messages m WHERE m.instance_name = cfg.instance_name AND m.from_me IS TRUE AND m.created_at >= date_trunc('month', now()); spend := round(sent_count * cfg.tariff_marketing_brl, 2); pct := spend / cfg.monthly_budget_brl; pct_pc := round(pct * 100); IF pct >= cfg.hard_stop_threshold THEN BEGIN INSERT INTO zapp.warroom_alerts (alert_type, title, message, source, entity) VALUES ('critical', 'WA Marketing: budget ESTOURADO', format('Instancia %s: %s msgs no mes (%s templates, ~R$ %s) = %s%% do budget R$ %s. PAUSAR campanhas.', cfg.instance_name, sent_count, tmpl_count, spend, pct_pc, cfg.monthly_budget_brl), 'ops.check_marketing_budget', cfg.instance_name); EXCEPTION WHEN OTHERS THEN NULL; END; RETURN QUERY SELECT 'wa_marketing_budget'::text, 'FAIL'::text, format('%s msgs (%s templates, ~R$ %s) = %s%% do budget R$ %s', sent_count, tmpl_count, spend, pct_pc, cfg.monthly_budget_brl); ELSIF pct >= cfg.alert_threshold THEN BEGIN INSERT INTO zapp.warroom_alerts (alert_type, title, message, source, entity) VALUES ('warning', 'WA Marketing: budget em alerta', format('Instancia %s: %s msgs no mes (%s templates, ~R$ %s) = %s%% do budget R$ %s.', cfg.instance_name, sent_count, tmpl_count, spend, pct_pc, cfg.monthly_budget_brl), 'ops.check_marketing_budget', cfg.instance_name); EXCEPTION WHEN OTHERS THEN NULL; END; RETURN QUERY SELECT 'wa_marketing_budget'::text, 'WARN'::text, format('%s msgs (%s templates, ~R$ %s) = %s%% do budget', sent_count, tmpl_count, spend, pct_pc); ELSE RETURN QUERY SELECT 'wa_marketing_budget'::text, 'OK'::text, format('%s msgs (%s templates, ~R$ %s) = %s%% do budget R$ %s', sent_count, tmpl_count, spend, pct_pc, cfg.monthly_budget_brl); END IF; END; $_$;


--
-- Name: check_mirror_integrity(boolean); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.check_mirror_integrity(p_raise boolean DEFAULT false) RETURNS TABLE(check_id text, status text, severity text, detail jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'zapp', 'pg_catalog'
    AS $$ DECLARE v_issues jsonb:='[]'; v_n int; v_arr text[]; BEGIN SELECT array_agg(x.r) INTO v_arr FROM (SELECT c.relname r FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='zapp' AND c.relname IN('companies','departments','profiles','whatsapp_connections') AND c.relkind<>'r' UNION ALL SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='zapp' AND c.relname='messages' AND c.relkind<>'v') x; RETURN QUERY SELECT 'MI-01','VIEW_COLLISION_GUARD', CASE WHEN v_arr IS NOT NULL AND array_length(v_arr,1)>0 THEN 'CRITICAL' ELSE 'OK' END, CASE WHEN v_arr IS NOT NULL AND array_length(v_arr,1)>0 THEN jsonb_build_object('unexpected_state',to_jsonb(v_arr)) ELSE jsonb_build_object('verified','Cenario B v1.2 R23') END; SELECT count(*) INTO v_n FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='zapp' AND c.relkind='r' AND NOT EXISTS (SELECT 1 FROM information_schema.views v WHERE v.table_schema='public' AND (v.table_name=c.relname OR v.view_definition ILIKE '%zapp.'||c.relname||'%')); RETURN QUERY SELECT 'MI-02','VIEW_COVERAGE',CASE WHEN v_n<=25 THEN 'OK' WHEN v_n<=40 THEN 'WARN' ELSE 'CRITICAL' END,jsonb_build_object('uncovered_zapp_tables',v_n,'threshold_ok',25); IF v_n>40 THEN v_issues:=v_issues||jsonb_build_object('check','MI-02','u',v_n); END IF; SELECT count(*) INTO v_n FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname='public' AND t.typtype='e' AND t.typname IN('channel_type','ai_provider_type','app_role','service_account_type'); RETURN QUERY SELECT 'MI-03','CLOUD_ENUMS_PRESENT',CASE WHEN v_n=4 THEN 'OK' WHEN v_n>=2 THEN 'WARN' ELSE 'CRITICAL' END,jsonb_build_object('found_in_public',v_n,'expected',4); IF v_n<4 THEN v_issues:=v_issues||jsonb_build_object('check','MI-03','found',v_n); END IF; SELECT count(*) INTO v_n FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='zapp' AND c.relname='whatsapp_official_credentials' AND a.attnotnull AND a.attnum>0 AND NOT a.attisdropped AND NOT EXISTS(SELECT 1 FROM pg_attrdef d WHERE d.adrelid=a.attrelid AND d.adnum=a.attnum); RETURN QUERY SELECT 'MI-04','WPP_OFFICIAL_CREDS_CONTRACT',CASE WHEN v_n=6 THEN 'OK' ELSE 'WARN' END,jsonb_build_object('mandatory_cols_without_default',v_n,'expected_contract',6); IF EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='ops' AND c.relkind='r' AND c.relname='edge_function_registry') THEN SELECT count(*) INTO v_n FROM ops.edge_function_registry; RETURN QUERY SELECT 'MI-05','EDGE_FN_REGISTRY',CASE WHEN v_n>=100 THEN 'OK' WHEN v_n>=50 THEN 'WARN' ELSE 'CRITICAL' END,jsonb_build_object('registered_functions',v_n,'expected_min',100); ELSE RETURN QUERY SELECT 'MI-05','EDGE_FN_REGISTRY','CRITICAL',jsonb_build_object('error','edge_function_registry nao existe'); v_issues:=v_issues||jsonb_build_object('check','MI-05'); END IF; SELECT array_agg(c.relname ORDER BY c.relname) INTO v_arr FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='zapp' AND c.relkind='r' AND NOT EXISTS(SELECT 1 FROM information_schema.views v2 WHERE v2.table_schema='public' AND(v2.table_name=c.relname OR v2.view_definition ILIKE '%zapp.'||c.relname||'%')); RETURN QUERY SELECT 'MI-06','UNCOVERED_ZAPP_TABLES',CASE WHEN array_length(v_arr,1) IS NULL OR array_length(v_arr,1)<=25 THEN 'OK' ELSE 'WARN' END,jsonb_build_object('uncovered',COALESCE(to_jsonb(v_arr),'[]'::jsonb),'threshold',25); SELECT count(*) INTO v_n FROM information_schema.columns WHERE table_schema='zapp' AND table_name='audio_memes' AND column_name='uploaded_by' AND data_type IN('text','uuid','character varying'); RETURN QUERY SELECT 'MI-07','AUDIO_MEMES_UPLOADED_BY_TYPE',CASE WHEN v_n=1 THEN 'OK' ELSE 'WARN' END,jsonb_build_object('column_exists_with_acceptable_type',v_n=1); IF jsonb_array_length(v_issues)>0 THEN INSERT INTO ops.schema_drift_log(status,missing_tables,missing_columns,detail) VALUES('DRIFT',0,jsonb_array_length(v_issues),jsonb_build_object('check','mirror_integrity','version','v1.2 R23-2026-07-16','issues',v_issues)); IF p_raise THEN RAISE EXCEPTION 'MIRROR INTEGRITY -> %',v_issues; END IF; ELSE INSERT INTO ops.schema_drift_log(status,missing_tables,missing_columns,detail) VALUES('OK',0,0,jsonb_build_object('check','mirror_integrity','version','v1.2 R23-2026-07-16','checks_passed',7)); END IF; END; $$;


--
-- Name: FUNCTION check_mirror_integrity(p_raise boolean); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.check_mirror_integrity(p_raise boolean) IS 'v1.0 2026-07-05 — Verifica integridade do espelho Cloud→zapp (Cenário B canônico). Checks: MI-01 view-collision, MI-02 coverage, MI-03 enums, MI-04 wpp-creds-contract, MI-05 edge-fn-registry, MI-06 uncovered-tables, MI-07 type-parity.';


--
-- Name: check_schema_drift(boolean); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.check_schema_drift(p_raise boolean DEFAULT false) RETURNS ops.schema_drift_log
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'zapp', 'pg_catalog'
    AS $$
DECLARE
  v_missing_tabs text[];
  v_missing_cols text[];
  v_row ops.schema_drift_log;
BEGIN
  WITH expected(t) AS (VALUES ('agent_achievements'),('agent_skills'),('agent_stats'),('agent_visibility_grants'),('ai_conversation_tags'),('ai_providers'),('ai_usage_logs'),('allowed_countries'),('audio_meme_favorites'),('audio_memes'),('audit_logs'),('auto_close_config'),('automations'),('away_messages'),('blocked_countries'),('blocked_ips'),('business_hours'),('calls'),('campaign_ab_variants'),('campaign_contacts'),('campaigns'),('channel_connections'),('channel_routing_rules'),('chatbot_executions'),('chatbot_flows'),('client_wallet_rules'),('connection_alert_preferences'),('connection_health_logs'),('contact_custom_fields'),('contact_notes'),('contact_purchases'),('contact_tags'),('contacts'),('conversation_analyses'),('conversation_closures'),('conversation_events'),('conversation_memory'),('conversation_sla'),('conversation_snoozes'),('conversation_tasks'),('conversation_transfers'),('crisis_room_alerts'),('csat_auto_config'),('csat_surveys'),('custom_emojis'),('deal_activities'),('department_invitations'),('departments'),('dispatch_error_logs'),('dlq_audit_log'),('email_accounts'),('email_labels'),('email_messages'),('email_threads'),('entity_versions'),('evolution_health_logs'),('evolution_instance_credentials'),('evolution_retry_metrics'),('failed_messages'),('favorite_contacts'),('followup_executions'),('followup_sequences'),('followup_steps'),('geo_blocking_settings'),('global_settings'),('gmail_accounts'),('goals_configurations'),('inbox_custom_scopes'),('instance_auth_events'),('instance_processing_pauses'),('instance_registry'),('ip_whitelist'),('knowledge_base_articles'),('knowledge_base_files'),('login_attempts'),('message_reactions'),('message_templates'),('messages'),('meta_capi_events'),('mfa_sessions'),('notifications'),('nps_surveys'),('number_reputation'),('passkey_credentials'),('password_reset_requests'),('payment_links'),('performance_snapshots'),('permissions'),('pinned_conversations'),('playbooks'),('processed_webhook_events'),('products'),('profiles'),('qr_attempts'),('query_telemetry'),('queue_goals'),('queue_members'),('queue_positions'),('queue_skill_requirements'),('queues'),('rate_limit_configs'),('rate_limit_logs'),('reconnection_logs'),('reminders'),('rls_denied_log'),('role_permissions'),('route_permissions'),('sales_deals'),('sales_pipeline_stages'),('saved_filters'),('scheduled_messages'),('scheduled_report_configs'),('scheduled_reports'),('security_alerts'),('security_audit_logs'),('sicoob_contact_mapping'),('sla_configurations'),('sla_rules'),('stickers'),('tags'),('talkx_blacklist'),('talkx_campaigns'),('talkx_recipients'),('team_conversation_members'),('team_conversations'),('team_message_receipts'),('team_messages'),('training_sessions'),('transfer_comments'),('user_devices'),('user_roles'),('user_service_accounts'),('user_sessions'),('user_settings'),('voice_command_logs'),('warroom_alerts'),('webauthn_challenges'),('webhook_rate_limits'),('whatsapp_cloud_webhook_pings'),('whatsapp_connection_queues'),('whatsapp_connections'),('whatsapp_flows'),('whatsapp_groups'),('whatsapp_official_credentials'),('whatsapp_templates'),('whisper_messages')),
  ren(lov,canon) AS (VALUES ('processed_webhook_events','webhook_events_processed')),
  live AS (
    SELECT c.relname AS rel FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
    WHERE n.nspname IN ('zapp','public') AND c.relkind IN ('r','v','p')
  )
  SELECT array_agg(e.t ORDER BY e.t) INTO v_missing_tabs
  FROM expected e
  WHERE NOT EXISTS (SELECT 1 FROM live l WHERE l.rel = e.t)
    AND NOT EXISTS (SELECT 1 FROM ren r JOIN live l ON l.rel=r.canon WHERE r.lov=e.t);

  WITH expected_c(t,c) AS (VALUES ('instance_registry','owner_id'),('instance_registry','api_key'),('instance_registry','connection_status'),('instance_registry','proxy_pass'),('instance_registry','metadata'),('conversation_transfers','from_agent_id'),('conversation_transfers','to_queue_id'),('conversation_transfers','sla_deadline'),('conversation_transfers','metadata'),('transfer_comments','agent_id'),('transfer_comments','metadata'),('department_invitations','email'),('department_invitations','role'),('department_invitations','status'),('department_invitations','invited_by'),('department_invitations','updated_at'),('departments','whatsapp_mode'),('departments','whatsapp_api_key'),('departments','whatsapp_instance_id'),('profiles','_admin_user_id'),('profiles','online_status'),('evolution_health_logs','connection_id'),('evolution_health_logs','error_count'),('evolution_health_logs','success_count'),('evolution_health_logs','created_at'),('rls_denied_log','resource'),('rls_denied_log','required_role'),('rls_denied_log','context'),('security_audit_logs','event_type'),('security_audit_logs','status'),('security_audit_logs','details'),('security_audit_logs','ip_address'),('inbox_custom_scopes','name'),('inbox_custom_scopes','label'),('inbox_custom_scopes','filter_criteria'),('inbox_custom_scopes','is_active'),('dlq_audit_log','action'),('dlq_audit_log','item_id'),('dlq_audit_log','performed_by')),
  ren(lov,canon) AS (VALUES ('processed_webhook_events','webhook_events_processed')),
  livec AS (
    SELECT table_name AS rel, column_name AS col FROM information_schema.columns
    WHERE table_schema IN ('zapp','public')
  )
  SELECT array_agg((e.t||'.'||e.c) ORDER BY e.t, e.c) INTO v_missing_cols
  FROM expected_c e
  WHERE NOT EXISTS (SELECT 1 FROM livec l WHERE l.rel=e.t AND l.col=e.c)
    AND NOT EXISTS (SELECT 1 FROM ren r JOIN livec l ON l.rel=r.canon WHERE r.lov=e.t AND l.col=e.c);

  INSERT INTO ops.schema_drift_log(status, missing_tables, missing_columns, detail)
  VALUES (
    CASE WHEN COALESCE(array_length(v_missing_tabs,1),0) + COALESCE(array_length(v_missing_cols,1),0) > 0
         THEN 'DRIFT' ELSE 'OK' END,
    COALESCE(array_length(v_missing_tabs,1),0),
    COALESCE(array_length(v_missing_cols,1),0),
    jsonb_build_object(
      'missing_tables',  to_jsonb(COALESCE(v_missing_tabs, ARRAY[]::text[])),
      'missing_columns', to_jsonb(COALESCE(v_missing_cols, ARRAY[]::text[]))
    )
  )
  RETURNING * INTO v_row;

  IF p_raise AND v_row.status = 'DRIFT' THEN
    RAISE EXCEPTION 'DRIFT DETECTADO -> % tabela(s), % coluna(s): %',
      v_row.missing_tables, v_row.missing_columns, v_row.detail;
  END IF;

  RETURN v_row;
END;
$$;


--
-- Name: FUNCTION check_schema_drift(p_raise boolean); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.check_schema_drift(p_raise boolean) IS 'Verifica drift Lovable->canônico (146 tabelas + colunas críticas). Grava em ops.schema_drift_log. p_raise=true lança excecao (uso em CI).';


