COMMENT ON FUNCTION ops.check_schema_parity(p_raise boolean) IS 'Wrapper (2026-08-03) que delega a ops.check_lovable_parity() — mantida para o cron 106 via ops.run_all_checks(). Nome neutro (sem "lovable") para migração futura.';


--
-- Name: check_types_sync(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.check_types_sync() RETURNS TABLE(status text, current_fp text, captured_fp text, captured_at timestamp with time zone, days_since integer)
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE WHEN s.fingerprint IS NULL THEN 'FAIL'
              WHEN s.fingerprint = ops.fn_schema_fingerprint() THEN 'OK'
              ELSE 'WARN' END,
         ops.fn_schema_fingerprint(), s.fingerprint, s.captured_at,
         EXTRACT(day FROM now()-s.captured_at)::int
  FROM (SELECT * FROM ops.types_sync_state WHERE id=1) s
$$;


--
-- Name: check_wal_health(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.check_wal_health() RETURNS TABLE(slot_name text, status text, restart_lag text, flush_lag text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'pg_catalog'
    AS $$
DECLARE
  v_row ops.v_wal_health%ROWTYPE;
  v_overall text := 'OK';
  v_detail text := '';
BEGIN
  FOR v_row IN SELECT * FROM ops.v_wal_health LOOP
    v_detail := v_detail || v_row.slot_name || ': ' || v_row.health_status
      || ' lag=' || v_row.restart_lag
      || ' active=' || v_row.active::text || ' | ';
    IF v_row.health_status = 'CRITICAL' THEN
      v_overall := 'CRITICAL';
    ELSIF v_row.health_status IN ('WARNING','ELEVATED') AND v_overall = 'OK' THEN
      v_overall := v_row.health_status;
    END IF;
  END LOOP;
  INSERT INTO ops.uptime_log (at, probe, event, detail)
  VALUES (
    now(),
    'wal_replication',
    v_overall,
    left(v_detail, 500)
  );
  RETURN QUERY
    SELECT w.slot_name::text, w.health_status::text, w.restart_lag::text, w.flush_lag::text
    FROM ops.v_wal_health w;
END;
$$;


--
-- Name: cleanup_test_hosts(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.cleanup_test_hosts(p_prefix text) RETURNS TABLE(table_name text, rows_deleted bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
  protected_hosts text[] := ARRAY['swarm-manager', 'vps-main', 'manager', 'node-1'];
  v_del bigint;
BEGIN
  -- Verificacao de seguranca: prefixo nao pode coincidir com hosts protegidos
  IF EXISTS (
    SELECT 1 FROM unnest(protected_hosts) AS h
    WHERE h LIKE (p_prefix || '%')
  ) THEN
    RAISE EXCEPTION 'SEGURANCA: prefixo % pode deletar hosts protegidos (%)',
      p_prefix, array_to_string(protected_hosts, ', ');
  END IF;

  -- Cleanup seguro
  WITH d AS (DELETE FROM ops.host_disk_log WHERE host LIKE (p_prefix || '%') RETURNING 1)
  SELECT COUNT(*) INTO v_del FROM d;
  RETURN QUERY SELECT 'host_disk_log'::text, v_del;

  WITH d AS (DELETE FROM ops.disk_event_log
    WHERE detail->>'host' LIKE (p_prefix || '%') RETURNING 1)
  SELECT COUNT(*) INTO v_del FROM d;
  RETURN QUERY SELECT 'disk_event_log'::text, v_del;

  WITH d AS (DELETE FROM ops.alert_cooldown
    WHERE host LIKE (p_prefix || '%') RETURNING 1)
  SELECT COUNT(*) INTO v_del FROM d;
  RETURN QUERY SELECT 'alert_cooldown'::text, v_del;

  WITH d AS (DELETE FROM ops.disk_actions_queue
    WHERE executed_at IS NULL RETURNING 1)
  SELECT COUNT(*) INTO v_del FROM d;
  RETURN QUERY SELECT 'disk_actions_queue'::text, v_del;

  WITH d AS (DELETE FROM zapp.warroom_alerts
    WHERE entity LIKE (p_prefix || '%') RETURNING 1)
  SELECT COUNT(*) INTO v_del FROM d;
  RETURN QUERY SELECT 'warroom_alerts'::text, v_del;
END;
$$;


--
-- Name: FUNCTION cleanup_test_hosts(p_prefix text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.cleanup_test_hosts(p_prefix text) IS 'Limpa dados de hosts de teste COM protecao para hosts reais. Nunca usar LIKE diretamente - sempre usar esta funcao.';


--
-- Name: cloud_parity_report(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.cloud_parity_report() RETURNS TABLE(categoria text, total integer, cobertos integer, pct numeric, status text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'ops', 'pg_catalog'
    AS $_$
DECLARE
  v_tab int; v_col int; v_con_tot int; v_con_ok int; v_idx_tot int; v_idx_ok int;
  v_rpc int; v_rpc_ok int; v_typ int;
BEGIN
  -- Tabelas
  SELECT count(*) INTO v_tab FROM ops._cloud_schema_audit a
  WHERE a.kind='TABLE' AND (EXISTS (SELECT 1 FROM pg_views v WHERE v.schemaname='public' AND v.viewname=a.name)
    OR EXISTS (SELECT 1 FROM pg_tables t WHERE t.schemaname='public' AND t.tablename=a.name));
  RETURN NEXT; categoria:='tabelas'; total:=146; cobertos:=v_tab; pct:=round(v_tab::numeric/146*100,1);
  status:=CASE WHEN v_tab=146 THEN '✅ 100%' ELSE '⚠️ '||v_tab||'/146' END;

  -- Colunas
  SELECT count(*) INTO v_col FROM ops._cloud_schema_audit a
  JOIN information_schema.columns c ON c.table_schema='public' AND c.table_name=split_part(a.name,'.',1) AND c.column_name=split_part(a.name,'.',2)
  WHERE a.kind='COLUMN';
  RETURN NEXT; categoria:='colunas'; total:=1590; cobertos:=v_col; pct:=round(v_col::numeric/1590*100,1);
  status:=CASE WHEN v_col=1590 THEN '✅ 100%' ELSE '⚠️ '||v_col||'/1590' END;

  -- Constraints
  SELECT count(*) INTO v_con_tot FROM ops._cloud_schema_audit WHERE kind='CONSTRAINT';
  SELECT count(*) INTO v_con_ok FROM ops._cloud_schema_audit c WHERE kind='CONSTRAINT'
    AND (EXISTS (SELECT 1 FROM pg_constraint cc JOIN pg_class cl ON cl.oid=cc.conrelid JOIN pg_namespace n ON n.oid=cl.relnamespace
                 WHERE n.nspname IN ('public','zapp','evo','email_app','vendas','financeiro','ai','bpm') AND cc.conname=c.name)
      OR EXISTS (SELECT 1 FROM pg_constraint cc JOIN pg_class cl ON cl.oid=cc.conrelid JOIN pg_namespace n ON n.oid=cl.relnamespace
                 WHERE n.nspname IN ('public','zapp','evo','email_app','vendas','financeiro','ai','bpm')
                 AND regexp_replace(regexp_replace(pg_get_constraintdef(cc.oid),'[a-z_]+\.','','g'),'\s+',' ','g')
                   = regexp_replace(regexp_replace(c.ddl,'[a-z_]+\.','','g'),'\s+',' ','g')));
  RETURN NEXT; categoria:='constraints'; total:=v_con_tot; cobertos:=v_con_ok; pct:=round(v_con_ok::numeric/v_con_tot*100,1);
  status:=CASE WHEN v_con_ok=v_con_tot THEN '✅ 100%' ELSE '⚠️ '||v_con_ok||'/'||v_con_tot END;

  -- Índices
  SELECT count(*) INTO v_idx_tot FROM ops._cloud_schema_audit WHERE kind='INDEX';
  SELECT count(*) INTO v_idx_ok FROM ops._cloud_schema_audit i WHERE kind='INDEX'
    AND (EXISTS (SELECT 1 FROM pg_indexes WHERE schemaname IN ('public','zapp','evo','email_app','vendas','financeiro','ai','bpm') AND indexname=i.name)
      OR EXISTS (SELECT 1 FROM pg_indexes WHERE schemaname IN ('public','zapp','evo','email_app','vendas','financeiro','ai','bpm')
                 AND regexp_replace(substring(indexdef from 'USING .*$'),'[a-z_]+\.','','g')
                   = regexp_replace(substring(i.ddl from 'USING .*$'),'[a-z_]+\.','','g')));
  RETURN NEXT; categoria:='indices'; total:=v_idx_tot; cobertos:=v_idx_ok; pct:=round(v_idx_ok::numeric/v_idx_tot*100,1);
  status:=CASE WHEN v_idx_ok=v_idx_tot THEN '✅ 100%' ELSE '⚠️ '||v_idx_ok||'/'||v_idx_tot END;

  -- RPCs
  SELECT count(*) INTO v_rpc FROM ops._cloud_funcs_audit;
  SELECT count(*) INTO v_rpc_ok FROM ops._cloud_funcs_audit f
    WHERE EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public'
      AND p.proname=f.name
      AND btrim(lower(replace(regexp_replace(pg_get_function_identity_arguments(p.oid),'\s+',' ','g'),'''','')))
        = btrim(lower(replace(regexp_replace(regexp_replace(f.args,'\sDEFAULT\s+(''[^'']*''|[^,]+)','','gi'),'\s+',' ','g'),'''',''))));
  RETURN NEXT; categoria:='rpc_assinaturas'; total:=v_rpc; cobertos:=v_rpc_ok; pct:=round(v_rpc_ok::numeric/v_rpc*100,1);
  status:=CASE WHEN v_rpc_ok=v_rpc THEN '✅ 100%' ELSE '⚠️ '||v_rpc_ok||'/'||v_rpc END;

  -- Tipos divergentes não-benignos
  SELECT count(*) INTO v_typ FROM ops._cloud_schema_audit a
  JOIN information_schema.columns c ON c.table_schema='public' AND c.table_name=split_part(a.name,'.',1) AND c.column_name=split_part(a.name,'.',2)
  WHERE a.kind='COLUMN' AND c.data_type<>regexp_replace(a.ddl,' NOT NULL$','')
    AND NOT ((regexp_replace(a.ddl,' NOT NULL$','')='integer' AND c.data_type='numeric')
          OR (regexp_replace(a.ddl,' NOT NULL$','')='text' AND c.data_type IN ('character varying','uuid'))
          OR (regexp_replace(a.ddl,' NOT NULL$','')='date' AND c.data_type='timestamp with time zone')
          OR (regexp_replace(a.ddl,' NOT NULL$','')='bytea' AND c.data_type='text')
          OR (regexp_replace(a.ddl,' NOT NULL$','')='uuid' AND c.data_type IN ('text','character varying')));
  RETURN NEXT; categoria:='tipos_nao_benignos'; total:=v_typ; cobertos:=0; pct:=0;
  status:=CASE WHEN v_typ=0 THEN '✅ 0' ELSE '⚠️ '||v_typ||' divergentes' END;

  -- Guard FKs
  PERFORM ops.check_critical_fks();
  RETURN NEXT; categoria:='guard_fks'; total:=1; cobertos:=1; pct:=100; status:='✅ OK';

  RETURN;
END;
$_$;


--
-- Name: disk_health_score(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.disk_health_score(p_host text DEFAULT 'swarm-manager'::text) RETURNS TABLE(score integer, grade text, disk_pct integer, disk_tier text, services_paused integer, pending_actions integer, last_recovery_ago text, penalties jsonb)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_pct integer; v_tier text; v_paused integer; v_pending integer;
  v_score integer := 100; v_last_rec timestamptz;
  v_pen jsonb := '{}'::jsonb; v_t_pen integer;
BEGIN
  SELECT hdl.used_pct, hdl.tier INTO v_pct, v_tier
  FROM ops.host_disk_log hdl WHERE hdl.host=p_host ORDER BY hdl.checked_at DESC LIMIT 1;
  SELECT COUNT(*)::integer INTO v_paused FROM ops.paused_services WHERE unpaused_at IS NULL;
  SELECT COUNT(*)::integer INTO v_pending FROM ops.disk_actions_queue WHERE executed_at IS NULL;
  SELECT MAX(del.ts) INTO v_last_rec FROM ops.disk_event_log del WHERE del.event_type='RECOVERY_OK';

  v_t_pen := CASE v_tier
    WHEN 'OK' THEN 0 WHEN 'INFO' THEN 5 WHEN 'NOTICE' THEN 15
    WHEN 'WARN' THEN 35 WHEN 'THROTTLE' THEN 55 WHEN 'FREEZE' THEN 75
    WHEN 'EMERGENCY' THEN 95 ELSE 50 END;
  v_score := v_score - v_t_pen;
  v_pen := jsonb_build_object('tier_penalty',v_t_pen,'tier',COALESCE(v_tier,'?'));

  IF COALESCE(v_paused,0)>0 THEN
    v_score:=v_score-LEAST(v_paused*5,20);
    v_pen:=v_pen||jsonb_build_object('paused_penalty',LEAST(v_paused*5,20));
  END IF;
  IF COALESCE(v_pending,0)>0 THEN
    v_score:=v_score-LEAST(v_pending*2,10);
    v_pen:=v_pen||jsonb_build_object('pending_penalty',LEAST(v_pending*2,10));
  END IF;
  v_score:=GREATEST(0,LEAST(100,v_score));

  RETURN QUERY SELECT
    v_score,
    CASE WHEN v_score>=90 THEN 'A' WHEN v_score>=75 THEN 'B'
         WHEN v_score>=60 THEN 'C' WHEN v_score>=40 THEN 'D' ELSE 'F' END,
    COALESCE(v_pct,-1)::integer,
    COALESCE(v_tier,'UNKNOWN'),
    COALESCE(v_paused,0)::integer,
    COALESCE(v_pending,0)::integer,
    CASE WHEN v_last_rec IS NULL THEN 'nunca' ELSE (now()-v_last_rec)::text END,
    v_pen;
END;
$$;


--
-- Name: dispatch_disk_alert(text, text, integer, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.dispatch_disk_alert(p_tier text, p_host text, p_pct integer, p_avail text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_sev text;
  v_title text;
  v_msg text;
BEGIN
  v_sev := CASE p_tier
    WHEN 'EMERGENCY' THEN 'critical'
    WHEN 'FREEZE'    THEN 'critical'
    WHEN 'THROTTLE'  THEN 'warning'
    WHEN 'WARN'      THEN 'warning'
    WHEN 'NOTICE'    THEN 'info'
    WHEN 'INFO'      THEN 'info'
    ELSE 'info'
  END;
  v_title := format('[DISK %s] Host %s: %s%% usado', p_tier, p_host, p_pct);
  v_msg := format('Disco %s%% | Livre: %s | Tier: %s | Acao: %s',
    p_pct, p_avail, p_tier, ops.suggest_disk_action(p_tier));
  -- FIX 2026-08-06 (AG-EX-09 item 89): cast explicito para enum zapp.warroom_alert_type.
  -- Coluna alert_type virou enum; variavel text nao auto-casta -> chain de alerta de disco
  -- quebrada desde 2026-08-01 (ingest_host_disk aborta, host_disk_log congela, sem alertas).
  INSERT INTO zapp.warroom_alerts (alert_type, title, message, source, entity)
  VALUES (v_sev::zapp.warroom_alert_type, v_title, v_msg, 'ops.disk-defense', p_host);
  -- Log event
  INSERT INTO ops.disk_event_log (event_type, from_state, to_state, detail)
  VALUES ('ALERT_SENT', NULL, p_tier,
    jsonb_build_object('host', p_host, 'pct', p_pct, 'avail', p_avail, 'tier', p_tier));
  -- Enqueue automated actions for THROTTLE+
  IF p_tier = 'THROTTLE' THEN
    INSERT INTO ops.disk_actions_queue (action, target, reason)
    VALUES
      ('pause_tier', 'disposable', format('Entered THROTTLE @ %s%%', p_pct)),
      ('run_deep_clean', NULL, 'THROTTLE trigger'),
      ('suspend_cicd', NULL, 'THROTTLE trigger')
    ON CONFLICT DO NOTHING;
  ELSIF p_tier = 'FREEZE' THEN
    INSERT INTO ops.disk_actions_queue (action, target, reason)
    VALUES
      ('pause_tier', 'important', format('Entered FREEZE @ %s%%', p_pct)),
      ('backup_r2_only', NULL, 'FREEZE trigger')
    ON CONFLICT DO NOTHING;
  END IF;
END;
$$;


--
-- Name: dispatch_disk_recovery(text, text, text, integer, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.dispatch_disk_recovery(p_tier_from text, p_tier_to text, p_host text, p_pct integer, p_avail text) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Log do recovery
  INSERT INTO ops.disk_event_log(event_type, from_state, to_state, detail)
  VALUES ('RECOVERY_OK', p_tier_from, p_tier_to,
    jsonb_build_object('host',p_host,'pct',p_pct,'avail',p_avail,'recovered_at',now()));

  -- Alerta positivo no warroom
  INSERT INTO zapp.warroom_alerts(alert_type,title,message,source,entity)
  VALUES ('info',
    format('[DISK RECOVERY] %s: %s%% livre', p_host, p_pct),
    format('Disco recuperado de %s para %s. Atual: %s%% | Livre: %s. Servicos serao restaurados se auto_recover=true.',
           p_tier_from, p_tier_to, p_pct, p_avail),
    'ops.disk-defense', p_host);

  -- Limpar cooldowns antigos para este host (permite alertar imediatamente se disco subir novamente)
  DELETE FROM ops.alert_cooldown WHERE host = p_host;

  -- Se auto_recover ativado: enfileirar unpause dos servicos pausados
  IF ops.get_flag('auto_recover') THEN
    -- Unpause disposable (sempre que voltar de THROTTLE)
    IF p_tier_from IN ('THROTTLE','FREEZE','EMERGENCY') THEN
      INSERT INTO ops.disk_actions_queue(action,target,reason)
      VALUES ('unpause_tier','disposable',
        format('Recovery: %s -> %s @ %s%%', p_tier_from, p_tier_to, p_pct))
      ON CONFLICT DO NOTHING;
    END IF;
    -- Unpause important (apenas se veio de FREEZE)
    IF p_tier_from IN ('FREEZE','EMERGENCY') THEN
      INSERT INTO ops.disk_actions_queue(action,target,reason)
      VALUES ('unpause_tier','important',
        format('Recovery: %s -> %s @ %s%%', p_tier_from, p_tier_to, p_pct))
      ON CONFLICT DO NOTHING;
    END IF;
    -- Resumir CI/CD (se veio de THROTTLE+)
    IF p_tier_from IN ('THROTTLE','FREEZE','EMERGENCY') THEN
      INSERT INTO ops.disk_actions_queue(action,target,reason)
      VALUES ('resume_cicd', NULL,
        format('Recovery confirmed: %s -> %s', p_tier_from, p_tier_to))
      ON CONFLICT DO NOTHING;
    END IF;
  END IF;
END;
$$;


--
-- Name: fn_alert_consumer_halt(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fn_alert_consumer_halt() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'evo'
    AS $$
DECLARE
  v_msgs_5min    INT;
  v_msgs_30min   INT;
  v_hour         INT;
  v_dow          INT;  -- 0=Dom, 6=Sab
  v_gap_min      NUMERIC;
  v_rate_per_min NUMERIC;
  v_threshold    INT;
BEGIN
  v_hour := EXTRACT(HOUR FROM NOW() AT TIME ZONE 'America/Sao_Paulo');
  v_dow  := EXTRACT(DOW  FROM NOW() AT TIME ZONE 'America/Sao_Paulo');

  -- Pular fora do horário: seg-sex 08-22h BRT. Fim de semana: usar threshold maior
  IF v_dow = 0 OR v_dow = 6 THEN
    -- Fim de semana: apenas alertar se gap > 8 horas (480 min) e hora > 8
    v_threshold := 480;
    IF v_hour < 8 THEN
      RETURN jsonb_build_object('status','skip','reason','weekend_off_hours');
    END IF;
  ELSE
    -- Dia de semana
    IF v_hour < 8 OR v_hour > 22 THEN
      RETURN jsonb_build_object('status','skip','reason','out_of_business_hours');
    END IF;
    v_threshold := 15;  -- threshold normal seg-sex
  END IF;

  SELECT COUNT(*) INTO v_msgs_5min
  FROM evo.evolution_messages
  WHERE created_at >= NOW() - INTERVAL '5 minutes';

  SELECT COUNT(*) INTO v_msgs_30min
  FROM evo.evolution_messages
  WHERE created_at >= NOW() - INTERVAL '30 minutes';

  -- FIX: sem janela temporal para capturar qualquer ultima mensagem
  SELECT ROUND(EXTRACT(EPOCH FROM (NOW() - MAX(created_at))) / 60, 1)
  INTO v_gap_min
  FROM evo.evolution_messages;

  v_rate_per_min := ROUND(v_msgs_30min::NUMERIC / 30, 1);

  IF v_msgs_5min = 0 AND COALESCE(v_gap_min, 9999) > v_threshold THEN
    IF EXISTS (
      SELECT 1 FROM evo.evolution_alerts
      WHERE alert_type = 'consumer_halt'
        AND created_at > NOW() - INTERVAL '60 minutes'
        AND resolved_at IS NULL
    ) THEN
      RETURN jsonb_build_object('status','dedup','gap_min', v_gap_min, 'threshold', v_threshold);
    END IF;

    INSERT INTO evo.evolution_alerts (severity, alert_type, title, message, payload)
    VALUES (
      'critical', 'consumer_halt',
      'Consumer parou de processar mensagens',
      'Nenhuma mensagem nova em ' || COALESCE(v_gap_min::TEXT, 'N/A') ||
        ' minutos (threshold=' || v_threshold || 'min, ' ||
        CASE v_dow WHEN 6 THEN 'sabado' WHEN 0 THEN 'domingo' ELSE 'dia util' END || ')',
      jsonb_build_object('gap_min', v_gap_min, 'msgs_5min', v_msgs_5min,
                         'msgs_30min', v_msgs_30min, 'rate_per_min', v_rate_per_min,
                         'threshold', v_threshold, 'dow', v_dow)
    );
    RETURN jsonb_build_object('status','alerted','gap_min', v_gap_min, 'threshold', v_threshold);
  END IF;

  RETURN jsonb_build_object('status','ok','gap_min', v_gap_min, 'rate_per_min', v_rate_per_min,
                             'msgs_5min', v_msgs_5min, 'threshold', v_threshold, 'dow', v_dow);
END;
$$;


--
-- Name: fn_analytics_log_retention(integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fn_analytics_log_retention(p_days integer DEFAULT 14) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'pg_catalog'
    AS $_$
DECLARE
  v_conn text := 'host=/var/run/postgresql dbname=_supabase user=postgres';
  v_tbl  text;
  v_result jsonb := '[]'::jsonb;
  v_deleted text;
BEGIN
  IF p_days IS NULL OR p_days < 1 THEN
    RAISE EXCEPTION 'fn_analytics_log_retention: p_days invalido: %', p_days;
  END IF;
  FOR v_tbl IN
    SELECT t.relname
    FROM extensions.dblink(
      v_conn::text,
      ($q$SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
         WHERE n.nspname='_analytics' AND c.relkind='r'
           AND c.relname ~ '^log_events_[0-9a-f_]{36}$'$q$)::text
    ) AS t(relname text)
  LOOP
    v_deleted := extensions.dblink_exec(v_conn::text, format(
      $fmt$DELETE FROM _analytics.%I WHERE "timestamp" < (now() at time zone 'utc') - interval '%s days'$fmt$,
      v_tbl, p_days));
    v_result := v_result || jsonb_build_object('table', v_tbl, 'result', v_deleted);
  END LOOP;
  RETURN jsonb_build_object('retention_days', p_days, 'executed_at', now(), 'tables', v_result);
END $_$;


--
-- Name: FUNCTION fn_analytics_log_retention(p_days integer); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.fn_analytics_log_retention(p_days integer) IS 'S4-4 (2026-07-04): retencao de 14 dias nos logs do Logflare (_supabase/_analytics). Antes desta correcao o _supabase tinha 35 GB (76% do disco do host); apos rewrite-swap ficou com 709 MB. Roda diario via pg_cron (dblink local peer, sem senha).';


--
-- Name: fn_auth_can_read_front_views(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fn_auth_can_read_front_views() RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'pg_catalog'
    AS $$
DECLARE
  v_ok boolean := true;
  v_missing text := '';
BEGIN
  IF to_regclass('public.messages') IS NULL
     OR NOT has_table_privilege('authenticated', 'public.messages', 'SELECT') THEN
    v_ok := false; v_missing := v_missing || 'public.messages SELECT; ';
  END IF;
  IF to_regclass('public.contacts') IS NULL
     OR NOT has_table_privilege('authenticated', 'public.contacts', 'SELECT') THEN
    v_ok := false; v_missing := v_missing || 'public.contacts SELECT; ';
  END IF;
  IF to_regprocedure('zapp.current_user_is_privileged()') IS NULL
     OR NOT has_function_privilege('authenticated', 'zapp.current_user_is_privileged()', 'EXECUTE') THEN
    v_ok := false; v_missing := v_missing || 'current_user_is_privileged EXECUTE; ';
  END IF;
  IF to_regprocedure('zapp.is_admin_painel()') IS NULL
     OR NOT has_function_privilege('authenticated', 'zapp.is_admin_painel()', 'EXECUTE') THEN
    v_ok := false; v_missing := v_missing || 'is_admin_painel EXECUTE; ';
  END IF;
  IF v_missing <> '' THEN
    RAISE WARNING 'fn_auth_can_read_front_views: missing %', v_missing;
  END IF;
  RETURN v_ok;
END;
$$;


--
-- Name: fn_auth_session_overflow_alert(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fn_auth_session_overflow_alert() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops, pg_temp'
    AS $$
DECLARE
  v_max_sessions   INT;
  v_critical_users TEXT;
  v_alert_msg      TEXT;
BEGIN
  -- Verificar se há usuários com sessões acima do limiar
  SELECT
    MAX(session_count)::INT,
    STRING_AGG(email || '(' || session_count || ')', ', ')
  INTO v_max_sessions, v_critical_users
  FROM (
    SELECT u.email, COUNT(s.id) AS session_count
    FROM auth.users u
    JOIN auth.sessions s ON s.user_id = u.id
    GROUP BY u.email
    HAVING COUNT(s.id) >= 15
  ) sub;

  IF v_max_sessions IS NULL THEN
    RETURN; -- Nenhum usuario acima do limiar
  END IF;

  v_alert_msg := 'ALERTA: overflow de sessões GoTrue detectado. Users: ' ||
                 COALESCE(v_critical_users, 'N/A') ||
                 '. Max: ' || v_max_sessions ||
                 ' (limite GoTrue: 10). Risco de HTTP 500 em refresh_token.';

  -- Inserir na tabela de alertas da plataforma
  INSERT INTO zapp.warroom_alerts (
    alert_type, title, message, source, entity
  ) VALUES (
    'critical',
    'GoTrue: overflow de sessões detectado (' || v_max_sessions || ' max)',
    v_alert_msg,
    'pg_cron:auth-session-overflow-alert',
    'auth.sessions'
  ) ON CONFLICT DO NOTHING;

EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'fn_auth_session_overflow_alert ERRO: %', SQLERRM;
END;
$$;


--
-- Name: fn_auto_classify_check_type(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fn_auto_classify_check_type() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops, pg_temp'
    AS $$
BEGIN
  IF NEW.check_type IS NULL THEN
    NEW.check_type := CASE
      WHEN NEW.detail ? 'n_fn_obj' THEN 'reference_integrity'
      ELSE                               'infrastructure'
    END;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION fn_auto_classify_check_type(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.fn_auto_classify_check_type() IS 'Trigger BEFORE INSERT em ops._infra_check_log: preenche check_type automaticamente via presença da chave n_fn_obj no JSONB (exclusiva de fn_check_reference_integrity). Adicionado 2026-08-06 (GAP-LOG-DISCRIMINATOR-COMPLETO).';


--
-- Name: fn_auto_update_backup_sentinel(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fn_auto_update_backup_sentinel() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'pg_catalog'
    AS $$
DECLARE
  v_stale_hours numeric;
BEGIN
  SELECT EXTRACT(EPOCH FROM (now() - last_backup_at))/3600
  INTO v_stale_hours FROM ops.backup_sentinel;

  -- Se sentinel foi atualizado ha menos de 20h, nao precisa de acao
  IF COALESCE(v_stale_hours, 999) < 20 THEN
    RETURN jsonb_build_object('action','skipped','stale_hours', round(v_stale_hours::numeric,1));
  END IF;

  -- FIX: era format() com especificador printf-style de ponto flutuante, que o
  -- PostgreSQL nao suporta em format() — trocado por concat com round()
  INSERT INTO zapp.webhook_health_alerts(alert_type, severity, title, details)
  VALUES (
    'backup_sentinel_stale',
    CASE WHEN v_stale_hours > 48 THEN 'critical' ELSE 'high' END,
    'Sentinel de backup obsoleto ha ' || round(v_stale_hours)::text || ' horas',
    jsonb_build_object(
      'stale_hours', round(v_stale_hours::numeric,1),
      'action_required', 'Verificar container supabase-backup e chamar ops.fn_update_backup_sentinel()',
      'runbook', 'docs/RUNBOOK_EDGE_FN_SNAPSHOT.md'
    )
  )
  ON CONFLICT DO NOTHING;

  RETURN jsonb_build_object('action','alert_created','stale_hours', round(v_stale_hours::numeric,1));
END;
$$;


--
-- Name: FUNCTION fn_auto_update_backup_sentinel(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.fn_auto_update_backup_sentinel() IS 'v1.0 2026-07-07 — Detecta sentinel de backup obsoleto e cria alerta. Cron: daily-backup-sentinel-check (09:00 BRT diariamente).';


--
-- Name: fn_catalog_sanity_check(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fn_catalog_sanity_check() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'pg_catalog'
    AS $$
DECLARE
  r          record;
  n_bad      int    := 0;
  n_ok       int    := 0;
  bad_sample text[] := '{}';
  rel_name   text;
BEGIN
  -- Varre pg_statistic forcando detoast de stavalues
  FOR r IN
    SELECT starelid, staattnum
    FROM   pg_catalog.pg_statistic
  LOOP
    BEGIN
      -- So tenta ler stavalues1 (suficiente para detectar TOAST orfao)
      PERFORM (SELECT s.stavalues1
               FROM   pg_catalog.pg_statistic s
               WHERE  s.starelid  = r.starelid
               AND    s.staattnum = r.staattnum
               LIMIT 1);
      n_ok := n_ok + 1;
    EXCEPTION WHEN OTHERS THEN
      n_bad := n_bad + 1;
      BEGIN
        rel_name := r.starelid::regclass::text;
      EXCEPTION WHEN OTHERS THEN
        rel_name := r.starelid::text;
      END;
      IF array_length(bad_sample, 1) IS NULL OR array_length(bad_sample, 1) < 10 THEN
        bad_sample := array_append(bad_sample,
          rel_name || ' (att=' || r.staattnum || ')');
      END IF;
    END;
  END LOOP;

  -- Alerta se houver corrupcao
  IF n_bad > 0 THEN
    INSERT INTO evo.evolution_alerts (
      id, alert_type, severity, title, message, payload, created_at, resolved
    ) VALUES (
      gen_random_uuid(),
      'catalog_corruption',
      'critical',
      'Corrupção em pg_statistic detectada',
      format(
        '%s linha(s) com TOAST órfão em pg_toast_2619. '
        'Receita de cura: ALTER TABLE <t> ALTER COLUMN <col> SET STATISTICS 0; ANALYZE <t>; '
        'Ver playbook em ops.fn_catalog_sanity_check.',
        n_bad
      ),
      jsonb_build_object(
        'n_bad',       n_bad,
        'n_ok',        n_ok,
        'sample_rels', bad_sample,
        'recipe',      'ALTER TABLE t ALTER COLUMN c SET STATISTICS 0; ANALYZE t; -- then restore -1'
      ),
      now(),
      false
    );
  END IF;

  RETURN jsonb_build_object(
    'n_ok',    n_ok,
    'n_bad',   n_bad,
    'ts',      now(),
    'status',  CASE WHEN n_bad = 0 THEN 'CLEAN' ELSE 'CORRUPTED' END
  );
END;
$$;


--
-- Name: FUNCTION fn_catalog_sanity_check(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.fn_catalog_sanity_check() IS 'Detecta TOAST orfao em pg_statistic. Insere alerta em evo.evolution_alerts se corrompidas > 0. Executar apos crashes/restarts. Recipiente: cron catalog-sanity-weekly.';


--
-- Name: fn_check_cron_health(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fn_check_cron_health() RETURNS TABLE(jobs_with_recent_failures bigint, jobs_still_failing bigint, total_failures_24h bigint, details jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'ops', 'pg_catalog', 'cron'
    AS $$
DECLARE
  v_still_failing  BIGINT := 0;
  v_recent_fails   BIGINT := 0;
  v_total_fails    BIGINT := 0;
  v_details        JSONB;
BEGIN
  -- Jobs que ainda estão falhando (última execução = failed)
  SELECT COUNT(*) INTO v_still_failing
  FROM (
    SELECT j.jobname,
      MAX(CASE WHEN jrd.status='failed' THEN jrd.start_time END) AS last_fail,
      MAX(CASE WHEN jrd.status='succeeded' THEN jrd.start_time END) AS last_success
    FROM cron.job j
    JOIN cron.job_run_details jrd ON jrd.jobid=j.jobid
    WHERE jrd.start_time > NOW()-INTERVAL '24 hours'
      AND j.active = true
    GROUP BY j.jobname
    HAVING SUM(CASE WHEN jrd.status='failed' THEN 1 ELSE 0 END) > 0
  ) sub
  WHERE last_success IS NULL OR last_fail > last_success;

  -- Jobs que tiveram falhas (incluindo já corrigidos)
  SELECT COUNT(DISTINCT j.jobname) INTO v_recent_fails
  FROM cron.job j
  JOIN cron.job_run_details jrd ON jrd.jobid=j.jobid
  WHERE jrd.status='failed'
    AND jrd.start_time > NOW()-INTERVAL '24 hours'
    AND j.active = true;

  -- Total de execuções falhadas
  SELECT COUNT(*) INTO v_total_fails
  FROM cron.job_run_details jrd
  JOIN cron.job j ON j.jobid=jrd.jobid
  WHERE jrd.status='failed'
    AND jrd.start_time > NOW()-INTERVAL '24 hours'
    AND j.active = true;

  -- Detalhes: quais jobs ainda estão falhando
  SELECT jsonb_agg(jsonb_build_object('job', jobname, 'last_fail', last_fail)) INTO v_details
  FROM (
    SELECT j.jobname,
      MAX(CASE WHEN jrd.status='failed' THEN jrd.start_time END) AS last_fail,
      MAX(CASE WHEN jrd.status='succeeded' THEN jrd.start_time END) AS last_success
    FROM cron.job j
    JOIN cron.job_run_details jrd ON jrd.jobid=j.jobid
    WHERE jrd.start_time > NOW()-INTERVAL '24 hours'
      AND j.active = true
    GROUP BY j.jobname
    HAVING SUM(CASE WHEN jrd.status='failed' THEN 1 ELSE 0 END) > 0
  ) sub
  WHERE last_success IS NULL OR last_fail > last_success;

  RETURN QUERY SELECT
    v_recent_fails,
    v_still_failing,
    v_total_fails,
    COALESCE(v_details, '[]'::jsonb);
END;
$$;


--
-- Name: FUNCTION fn_check_cron_health(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.fn_check_cron_health() IS 'Check inteligente de cron: distingue jobs ainda falhando (last_run=failed) de jobs com historico de falhas mas ja corrigidos (last_run=succeeded). Muito mais util que contagem absoluta de failures_24h.';


--
-- Name: fn_check_reference_integrity(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fn_check_reference_integrity() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'pg_catalog', 'cron'
    AS $$
DECLARE
  v_fn_obj   jsonb;
  v_cron_fn  jsonb;
  v_n_pend   int;
  v_score    int;
BEGIN
  WITH fns AS (
    SELECT p.proname, p.prosrc FROM pg_catalog.pg_proc p
    WHERE p.pronamespace = 'zapp'::regnamespace
      AND p.prolang IN (SELECT oid FROM pg_catalog.pg_language WHERE lanname IN ('plpgsql','sql'))
      AND p.prosrc IS NOT NULL),
  calls AS (
    SELECT f.proname AS caller, m[1] AS sch, m[2] AS callee
    FROM fns f, LATERAL pg_catalog.regexp_matches(
           pg_catalog.regexp_replace(f.prosrc, '--[^\n]*', '', 'g'),
           '(zapp|public|evo|email_app|auth)\.([a-z_][a-z0-9_]+)\s*\(','g') AS m),
  pend AS (
    SELECT c.sch, c.callee, count(DISTINCT c.caller) AS callers,
           (array_agg(DISTINCT c.caller ORDER BY c.caller))[1:8] AS sample
    FROM calls c
    WHERE NOT EXISTS (SELECT 1 FROM pg_catalog.pg_proc p WHERE p.proname=c.callee
            AND p.pronamespace=(SELECT oid FROM pg_catalog.pg_namespace WHERE nspname=c.sch))
      AND NOT EXISTS (SELECT 1 FROM pg_catalog.pg_class x WHERE x.relname=c.callee
            AND x.relnamespace=(SELECT oid FROM pg_catalog.pg_namespace WHERE nspname=c.sch)
            AND x.relkind IN ('r','v','m','p','f'))
    GROUP BY c.sch, c.callee)
  SELECT COALESCE(jsonb_agg(jsonb_build_object('schema', sch, 'callee', callee, 'callers', callers, 'sample', sample) ORDER BY callers DESC), '[]'::jsonb)
    INTO v_fn_obj FROM pend;

  WITH j AS (SELECT jobid, jobname, command FROM cron.job),
  calls AS (SELECT jobid, jobname, m[1] AS sch, m[2] AS fn
    FROM j, LATERAL pg_catalog.regexp_matches(
           pg_catalog.regexp_replace(command, '--[^\n]*', '', 'g'),
           '(zapp|public|evo|email_app)\.([a-z_][a-z0-9_]+)\s*\(','g') AS m),
  pend AS (
    SELECT c.sch, c.fn, count(DISTINCT c.jobid) AS jobs,
           (array_agg(DISTINCT c.jobname ORDER BY c.jobname))[1:6] AS sample_jobs
    FROM calls c
    WHERE NOT EXISTS (SELECT 1 FROM pg_catalog.pg_proc p WHERE p.proname=c.fn
            AND p.pronamespace=(SELECT oid FROM pg_catalog.pg_namespace WHERE nspname=c.sch))
      AND NOT EXISTS (SELECT 1 FROM pg_catalog.pg_class x WHERE x.relname=c.fn
            AND x.relnamespace=(SELECT oid FROM pg_catalog.pg_namespace WHERE nspname=c.sch))
    GROUP BY c.sch, c.fn)
  SELECT COALESCE(jsonb_agg(jsonb_build_object('schema', sch, 'function', fn, 'jobs', jobs, 'sample_jobs', sample_jobs) ORDER BY jobs DESC), '[]'::jsonb)
    INTO v_cron_fn FROM pend;

  v_n_pend := jsonb_array_length(v_fn_obj) + jsonb_array_length(v_cron_fn);
  v_score  := 100 - v_n_pend;

  INSERT INTO ops._infra_check_log(score, max_score, issues, detail, checked_at)
  VALUES (v_score, 100, v_n_pend,
          jsonb_build_object(
            'check', 'reference_integrity',
            'n_fn_obj', jsonb_array_length(v_fn_obj),
            'n_cron_fn', jsonb_array_length(v_cron_fn),
            'fn_obj_pend', v_fn_obj,
            'cron_fn_pend', v_cron_fn
          ),
          now());

  RETURN jsonb_build_object(
    'status', CASE WHEN v_n_pend = 0 THEN 'OK' ELSE 'PENDING_REFERENCES' END,
    'n_fn_obj', jsonb_array_length(v_fn_obj),
    'n_cron_fn', jsonb_array_length(v_cron_fn),
    'n_pend', v_n_pend,
    'score', v_score,
    'max_score', 100,
    'checked_at', now(),
    'fn_obj_pend', v_fn_obj,
    'cron_fn_pend', v_cron_fn
  );
END;
$$;


--
-- Name: fn_check_wal_slots(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fn_check_wal_slots() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops'
    AS $$
DECLARE r record; v_state ops.wal_alert_state; v_acao text := ''; v_url text := 'https://n8n.atomicabr.com.br/webhook/warroom-alert';
BEGIN
  FOR r IN
    SELECT slot_name,
           coalesce((pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn)/1024/1024)::int, 0) AS mb
    FROM pg_replication_slots
  LOOP
    SELECT * INTO v_state FROM ops.wal_alert_state WHERE slot_name = r.slot_name;
    IF NOT FOUND THEN
      INSERT INTO ops.wal_alert_state(slot_name, last_mb) VALUES (r.slot_name, r.mb)
      RETURNING * INTO v_state;
    END IF;

    IF r.mb > 512 AND NOT v_state.alerting THEN
      UPDATE ops.wal_alert_state SET alerting=true, last_mb=r.mb, alerted_at=now(), updated_at=now() WHERE slot_name=r.slot_name;
      PERFORM net.http_post(
        url := v_url,
        headers := '{"Content-Type":"application/json"}'::jsonb,
        body := jsonb_build_object('service','wal-slot-monitor','event','critical',
          'detail', format('Replication slot %s retendo %s MB de WAL (limite 512MB). Risco de disco cheio. Verificar consumidor (cainophile/realtime).', r.slot_name, r.mb)),
        timeout_milliseconds := 10000);
      v_acao := v_acao || format('[ALERTA %s=%sMB]', r.slot_name, r.mb);
    ELSIF r.mb < 256 AND v_state.alerting THEN
      UPDATE ops.wal_alert_state SET alerting=false, last_mb=r.mb, resolved_at=now(), updated_at=now() WHERE slot_name=r.slot_name;
      PERFORM net.http_post(
        url := v_url,
        headers := '{"Content-Type":"application/json"}'::jsonb,
        body := jsonb_build_object('service','wal-slot-monitor','event','recovery',
          'detail', format('Slot %s normalizado: %s MB retidos.', r.slot_name, r.mb)),
        timeout_milliseconds := 10000);
      v_acao := v_acao || format('[RESOLVIDO %s=%sMB]', r.slot_name, r.mb);
    ELSE
      UPDATE ops.wal_alert_state SET last_mb=r.mb, updated_at=now() WHERE slot_name=r.slot_name;
    END IF;
  END LOOP;
  RETURN coalesce(nullif(v_acao,''),'sem mudanca de estado');
END $$;


--
-- Name: fn_dashboard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fn_dashboard() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'evo', 'zapp'
    AS $$
DECLARE
  v_msgs jsonb; v_webhooks jsonb; v_conns jsonb; v_disk jsonb; v_budget jsonb; v_alerts jsonb; v_health jsonb;
BEGIN
  -- Mensagens por instancia (24h e 7d, in/out)
  SELECT jsonb_agg(jsonb_build_object(
           'instance', instance_name,
           'msgs_24h', c24, 'enviadas_24h', out24, 'recebidas_24h', in24,
           'msgs_7d', c7d
         ) ORDER BY c7d DESC)
    INTO v_msgs
  FROM (
    SELECT instance_name,
           count(*) FILTER (WHERE created_at >= now() - interval '24h') AS c24,
           count(*) FILTER (WHERE created_at >= now() - interval '24h' AND from_me) AS out24,
           count(*) FILTER (WHERE created_at >= now() - interval '24h' AND NOT from_me) AS in24,
           count(*) FILTER (WHERE created_at >= now() - interval '7 days') AS c7d
    FROM evo.evolution_messages
    WHERE created_at >= now() - interval '7 days'
    GROUP BY instance_name
  ) m;

  -- Webhooks 24h + backlog nao processado
  SELECT jsonb_build_object(
           'eventos_24h', count(*) FILTER (WHERE created_at >= now() - interval '24h'),
           'nao_processados', count(*) FILTER (WHERE NOT COALESCE(processed, true)),
           'eventos_1h', count(*) FILTER (WHERE created_at >= now() - interval '1h')
         )
    INTO v_webhooks
  FROM evo.evolution_webhook_events_v2
  WHERE created_at >= now() - interval '24h';

  -- Conexoes WhatsApp (saude)
  SELECT jsonb_agg(jsonb_build_object(
           'instance', instance_name, 'nome', name, 'status', status,
           'ativa', is_active, 'health', health_status,
           'ultima_conexao', last_connected_at
         ) ORDER BY is_default DESC NULLS LAST, instance_name)
    INTO v_conns
  FROM zapp.whatsapp_connections;

  -- Disco (ultima leitura)
  SELECT jsonb_build_object('used_pct', used_pct, 'avail', avail_h, 'total', total_h, 'status', status, 'checked_at', checked_at)
    INTO v_disk
  FROM ops.host_disk_log ORDER BY checked_at DESC LIMIT 1;

  -- Budget marketing (via funcao)
  BEGIN SELECT jsonb_build_object('status', status, 'detail', detail) INTO v_budget FROM ops.check_marketing_budget();
  EXCEPTION WHEN OTHERS THEN v_budget := jsonb_build_object('status', 'ERR', 'detail', SQLERRM); END;

  -- Alertas abertos (nao resolvidos) por severidade, ultimos 7d
  SELECT jsonb_build_object(
           'criticos_abertos', count(*) FILTER (WHERE alert_type = 'critical' AND resolved_at IS NULL),
           'warnings_abertos', count(*) FILTER (WHERE alert_type = 'warning' AND resolved_at IS NULL),
           'total_7d', count(*),
           'ultimos', COALESCE((SELECT jsonb_agg(jsonb_build_object('tipo', alert_type, 'titulo', title, 'fonte', source, 'quando', created_at) ORDER BY created_at DESC)
                                FROM (SELECT alert_type, title, source, created_at FROM zapp.warroom_alerts WHERE resolved_at IS NULL ORDER BY created_at DESC LIMIT 5) x), '[]'::jsonb)
         )
    INTO v_alerts
  FROM zapp.warroom_alerts
  WHERE created_at >= now() - interval '7 days';

  -- Health score global
  BEGIN v_health := zapp.fn_system_health_score(); EXCEPTION WHEN OTHERS THEN v_health := jsonb_build_object('grade', 'N/A'); END;

  RETURN jsonb_build_object(
    'gerado_em', now(),
    'health_score', v_health,
    'mensagens', COALESCE(v_msgs, '[]'::jsonb),
    'webhooks', v_webhooks,
    'conexoes', COALESCE(v_conns, '[]'::jsonb),
    'disco', v_disk,
    'budget_marketing', v_budget,
    'alertas', v_alerts
  );
END; $$;


--
-- Name: fn_ddl_audit_drop(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fn_ddl_audit_drop() RETURNS event_trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'pg_catalog'
    AS $$
DECLARE r record;
BEGIN
  FOR r IN SELECT * FROM pg_event_trigger_dropped_objects() LOOP
    IF NOT r.is_temporary THEN
      INSERT INTO ops.ddl_audit(username, command_tag, object_type, object_identity, query)
      VALUES (current_user, 'DROP', r.object_type, r.object_identity, left(current_query(),2000));
    END IF;
  END LOOP;
END $$;


--
-- Name: fn_ddl_audit_log(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fn_ddl_audit_log() RETURNS event_trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'pg_catalog'
    AS $$
DECLARE r record;
BEGIN
  FOR r IN SELECT * FROM pg_event_trigger_ddl_commands() LOOP
    IF r.schema_name IS DISTINCT FROM 'pg_temp' THEN
      INSERT INTO ops.ddl_audit(username, command_tag, object_type, object_identity, query)
      VALUES (current_user, r.command_tag, r.object_type, r.object_identity, left(current_query(),2000));
    END IF;
  END LOOP;
END $$;


--
-- Name: fn_ddl_drop_alert(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fn_ddl_drop_alert() RETURNS event_trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'evo', 'pg_catalog'
    AS $$
DECLARE r record; v_schema text; v_dedup int;
BEGIN
  FOR r IN SELECT * FROM pg_event_trigger_dropped_objects() LOOP
    IF r.is_temporary THEN CONTINUE; END IF;
    v_schema := split_part(r.object_identity, '.', 1);

    -- Apenas schemas criticos
    IF NOT (v_schema = ANY(ARRAY['evo','zapp','public','ops','bpm','email_app'])) THEN
      CONTINUE;
    END IF;

    -- Apenas tipos crticos (tabelas, funcoes, views, schemas, triggers)
    -- NAO alertar para INDEX (muito ruido de migracoes automaticas)
    IF NOT (r.object_type = ANY(ARRAY['table','function','view','materialized view','schema','trigger'])) THEN
      CONTINUE;
    END IF;

    -- supabase_admin em modo de migracao planejada: suprimir INDEX drops
    -- Alertar SEMPRE para tabelas e funcoes (independente de quem dropou)
    IF current_user = 'supabase_admin'
       AND r.object_type NOT IN ('table','schema') THEN
      CONTINUE;  -- supabase_admin pode dropar funcoes/views/triggers: nao alertar
    END IF;

    -- Dedup: nao inserir se ja existe alerta identico na ultima hora
    SELECT count(*) INTO v_dedup FROM evo.evolution_alerts
      WHERE alert_type='ddl_drop_alert' AND resolved_at IS NULL
        AND message ILIKE '%' || r.object_identity || '%'
        AND created_at > now() - interval '1 hour';

    IF v_dedup = 0 THEN
      INSERT INTO evo.evolution_alerts(alert_type, severity, title, message)
        VALUES('ddl_drop_alert', 'high',
          format('DROP: %s %s', r.object_type, r.object_identity),
          format('Usuario: %s | Tipo: %s | Objeto: %s | Query: %s',
            current_user, r.object_type, r.object_identity,
            left(current_query(), 200)));
    END IF;
  END LOOP;
END;
$$;


--
-- Name: fn_ddl_weekly_summary(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fn_ddl_weekly_summary() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'evo', 'zapp'
    AS $$
DECLARE
  v_from timestamptz := now() - interval '7 days';
  v_resumo jsonb; v_total int; v_drops int; v_creates int; v_alters int;
  v_autores text; v_objetos_risco text; v_alert_id uuid;
BEGIN
  SELECT count(*), count(*) FILTER (WHERE command_tag='DROP'), count(*) FILTER (WHERE command_tag LIKE 'CREATE%'), count(*) FILTER (WHERE command_tag LIKE 'ALTER%'), string_agg(DISTINCT username, ', ')
    INTO v_total, v_drops, v_creates, v_alters, v_autores
    FROM ops.ddl_audit WHERE at >= v_from;
  SELECT string_agg(DISTINCT object_identity, E'\n' ORDER BY object_identity)
    INTO v_objetos_risco
    FROM ops.ddl_audit
    WHERE at >= v_from AND command_tag = 'DROP' AND object_type IN ('table','schema','function','view','index') LIMIT 20;
  v_resumo := jsonb_build_object('periodo', jsonb_build_object('de', v_from, 'ate', now()), 'total_operacoes', v_total, 'drops', v_drops, 'creates', v_creates, 'alters', v_alters, 'autores', v_autores, 'objetos_dropados', coalesce(v_objetos_risco, 'nenhum'), 'gerado_em', now());
  IF v_total > 0 THEN
    INSERT INTO evo.evolution_alerts(alert_type, severity, title, message, payload)
    VALUES('ddl_weekly_summary', 'info',
      format('DDL Semanal: %s op, %s DROPs, autores: %s', v_total, v_drops, coalesce(v_autores,'nenhum')),
      format('Periodo: %s ate %s', to_char(v_from, 'DD/MM HH24:MI'), to_char(now(), 'DD/MM HH24:MI')),
      v_resumo)
    RETURNING id INTO v_alert_id;
  END IF;
  RETURN v_resumo;
END;
$$;


--
-- Name: fn_edge_fn_staleness_check(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fn_edge_fn_staleness_check() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops, evo, zapp, pg_catalog'
    AS $$
DECLARE
  v_last_seen      timestamptz;
  v_days_stale     numeric;
  v_active_count   int;
  v_no_hash_count  int;
  v_result         jsonb;
BEGIN
  SELECT
    max(last_seen_at),
    count(*) FILTER (WHERE is_active),
    count(*) FILTER (WHERE is_active AND fn_hash_sha256 IS NULL)
  INTO v_last_seen, v_active_count, v_no_hash_count
  FROM ops.edge_function_registry;

  v_days_stale := EXTRACT(epoch FROM (now() - v_last_seen)) / 86400.0;

  v_result := jsonb_build_object(
    'last_seen_at',    v_last_seen,
    'days_stale',      round(v_days_stale::numeric, 1),
    'active_count',    v_active_count,
    'no_hash_count',   v_no_hash_count,
    'status',          CASE
                         WHEN v_days_stale > 14 THEN 'CRITICAL'
                         WHEN v_days_stale > 7  THEN 'WARN'
                         ELSE 'OK'
                       END,
    'checked_at',      now()
  );

  IF v_days_stale > 7 THEN
    INSERT INTO zapp.webhook_health_alerts(alert_type, severity, title, details)
    VALUES (
      'edge_fn_registry_stale',
      CASE WHEN v_days_stale > 14 THEN 'critical' ELSE 'high' END,
      format('edge_function_registry desatualizado há %s dias', round(v_days_stale::numeric, 0)),
      jsonb_build_object(
        'last_seen_at', v_last_seen,
        'days_stale', round(v_days_stale::numeric, 1),
        'active_functions', v_active_count,
        'action_required', 'Rodar: ops.fn_edge_function_snapshot(ARRAY[...], NULL) via Portainer',
        'runbook', 'docs/RUNBOOK_EDGE_FN_SNAPSHOT.md'
      )
    )
    ON CONFLICT DO NOTHING;
  END IF;

  RETURN v_result;
END;
$$;


--
-- Name: FUNCTION fn_edge_fn_staleness_check(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.fn_edge_fn_staleness_check() IS 'v1.0 2026-07-05 — Verifica freshness do ops.edge_function_registry. Alerta se desatualizado > 7 dias (WARN) ou > 14 dias (CRITICAL). Cron: weekly-edge-fn-freshness (toda segunda às 09:00 BRT).';


--
-- Name: fn_edge_function_snapshot(text[], text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fn_edge_function_snapshot(p_names text[], p_repo_sha text DEFAULT NULL::text) RETURNS TABLE(out_fn_name text, out_action text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'pg_catalog'
    AS $$
DECLARE
  v_name    text;
  v_now     timestamptz := now();
  v_existed boolean;
BEGIN
  -- Desativar as que sumiram da listagem
  UPDATE ops.edge_function_registry efr
    SET is_active = false,
        metadata  = efr.metadata || jsonb_build_object('deactivated_at', v_now)
    WHERE efr.deploy_source='vps' AND efr.is_active=true;

  FOREACH v_name IN ARRAY p_names LOOP
    -- Verificar se já existe
    SELECT EXISTS(
      SELECT 1 FROM ops.edge_function_registry
      WHERE fn_name=v_name AND deploy_source='vps'
    ) INTO v_existed;

    INSERT INTO ops.edge_function_registry
      (fn_name, fn_path, last_seen_at, is_active, deploy_source, repo_sha)
    VALUES (
      v_name,
      '/home/deno/functions/' || v_name || '/index.ts',
      v_now, true, 'vps', p_repo_sha
    )
    ON CONFLICT (fn_name, deploy_source) DO UPDATE
      SET is_active    = true,
          last_seen_at = v_now,
          repo_sha     = EXCLUDED.repo_sha,
          metadata     = ops.edge_function_registry.metadata
                         || jsonb_build_object('last_snapshot', v_now);

    out_fn_name := v_name;
    out_action  := CASE WHEN v_existed THEN 'upserted' ELSE 'inserted' END;
    RETURN NEXT;
  END LOOP;

  INSERT INTO ops.schema_drift_log(status, missing_tables, missing_columns, detail)
  VALUES ('OK', 0, 0, jsonb_build_object(
    'check', 'edge_function_snapshot',
    'version', 'v1.2 2026-07-05',
    'total_functions', array_length(p_names, 1),
    'repo_sha', p_repo_sha,
    'snapshot_at', v_now
  ));
END;
$$;


--
-- Name: fn_expire_stale_backups(integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fn_expire_stale_backups(p_max_age_days integer DEFAULT 90) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_dropped int := 0;
  v_skipped int := 0;
  v_rec record;
  v_tbl text;
  v_cutoff timestamptz := now() - make_interval(days := p_max_age_days);
  v_log jsonb := '[]';
BEGIN
  FOR v_rec IN
    SELECT table_name, backup_date, retention_until
    FROM _backups.backup_metadata
    WHERE (retention_until IS NOT NULL AND retention_until < now())
       OR (retention_until IS NULL AND backup_date < v_cutoff::date)
    ORDER BY backup_date
  LOOP
    v_tbl := '_backups.' || quote_ident(v_rec.table_name);
    IF to_regclass(v_tbl) IS NULL THEN
      -- tabela ja nao existe: limpa metadata orfao
      DELETE FROM _backups.backup_metadata WHERE table_name = v_rec.table_name;
      v_skipped := v_skipped + 1;  -- BUG-4 fix: era omitido, v_skipped ficava 0
      v_log := v_log || jsonb_build_object('table', v_rec.table_name, 'action', 'metadata_cleanup');
    ELSE
      EXECUTE format('DROP TABLE %s', v_tbl);
      DELETE FROM _backups.backup_metadata WHERE table_name = v_rec.table_name;
      v_dropped := v_dropped + 1;
      v_log := v_log || jsonb_build_object('table', v_rec.table_name, 'action', 'dropped', 'backup_date', v_rec.backup_date);
    END IF;
  END LOOP;
  RETURN jsonb_build_object('dropped', v_dropped, 'metadata_cleanup', v_skipped, 'checked_at', now(), 'log', v_log);
END $$;


--
-- Name: fn_guardrails_check(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fn_guardrails_check() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'evo', 'zapp'
    AS $$
DECLARE
  v_last_msg  timestamptz; v_gap_min int; v_alerts int:=0; v_conn record;
  v_now_sp    time    := (now() AT TIME ZONE 'America/Sao_Paulo')::time;
  v_dow       int     := extract(dow from now() AT TIME ZONE 'America/Sao_Paulo');
  v_threshold int     := 60;
  v_is_bizday boolean;
BEGIN
  -- FIX v2: seg-sex (1-5) dia util. Sabado(6) e Domingo(0) = FDS B2B
  -- BUG ORIGINAL: BETWEEN 1 AND 6 incluia sabado como dia util
  v_is_bizday := (v_dow BETWEEN 1 AND 5) AND (v_now_sp BETWEEN '08:00' AND '19:00');
  v_threshold := CASE WHEN v_dow IN (0,6) THEN 480 ELSE 60 END;

  IF (v_is_bizday OR (v_dow IN (0,6) AND v_now_sp BETWEEN '08:00' AND '19:00')) THEN
    SELECT max(created_at) INTO v_last_msg FROM evo.evolution_messages WHERE instance_name='wpp2';
    v_gap_min := EXTRACT(epoch FROM (now() - v_last_msg))/60;

    IF v_gap_min > v_threshold AND NOT EXISTS (
      SELECT 1 FROM evo.evolution_alerts WHERE alert_type='pipeline_dead_man'
        AND created_at > now() - interval '2 hours' AND resolved_at IS NULL
    ) THEN
      INSERT INTO evo.evolution_alerts(alert_type,severity,title,message,payload)
      VALUES ('pipeline_dead_man','critical','DEAD-MAN: pipeline sem mensagens',
        format('Nenhuma mensagem wpp2 ha %s minutos (%s)', v_gap_min,
               CASE WHEN v_is_bizday THEN 'horario comercial' ELSE 'FDS' END),
        jsonb_build_object('instance','wpp2','last_message_at',v_last_msg,'gap_minutes',v_gap_min,
                           'threshold_used',v_threshold,'is_bizday',v_is_bizday,'dow',v_dow));
      v_alerts := v_alerts+1;
    END IF;
  END IF;

  FOR v_conn IN
    SELECT instance_name,status,updated_at FROM zapp.whatsapp_connections
    WHERE instance_name='wpp2' AND lower(coalesce(status,'')) NOT IN ('open','connected')
      AND updated_at < now()-interval '15 minutes'
  LOOP
    IF NOT EXISTS (SELECT 1 FROM evo.evolution_alerts WHERE alert_type='qrcode_required'
      AND payload->>'instance'=v_conn.instance_name AND created_at > now()-interval '6 hours') THEN
      INSERT INTO evo.evolution_alerts(alert_type,severity,title,message,payload)
      VALUES ('qrcode_required','critical','Conexao WhatsApp caida',
        format('Conexao %s em [%s] ha 15min+ - requer pareamento',v_conn.instance_name,v_conn.status),
        jsonb_build_object('instance',v_conn.instance_name,'status',v_conn.status,'since',v_conn.updated_at));
      v_alerts := v_alerts+1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('ok',true,'alerts_created',v_alerts,'last_msg_gap_min',v_gap_min,
    'threshold_used',v_threshold,'is_bizday',v_is_bizday,'dow',v_dow,'fix_version','v2-saturday-fix','checked_at',now());
END;
$$;


--
-- Name: fn_host_disk_collector_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fn_host_disk_collector_guard() RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_latest  ops.host_disk_log%ROWTYPE;
  v_age_min numeric;
  v_open    boolean;
BEGIN
  SELECT * INTO v_latest FROM ops.host_disk_log ORDER BY checked_at DESC LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'nenhuma leitura em ops.host_disk_log');
  END IF;

  v_age_min := EXTRACT(EPOCH FROM (now() - v_latest.checked_at)) / 60;

  IF v_age_min <= 20 THEN
    RETURN jsonb_build_object('ok', true, 'age_min', round(v_age_min::numeric, 1),
                              'used_pct', v_latest.used_pct, 'checked_at', v_latest.checked_at);
  END IF;

  SELECT EXISTS(
    SELECT 1 FROM zapp.warroom_alerts
    WHERE source = 'fn_host_disk_collector_guard' AND resolved_at IS NULL
  ) INTO v_open;

  IF NOT v_open THEN
    INSERT INTO zapp.warroom_alerts (alert_type, title, message, source, entity, severity)
    VALUES (
      'critical',
      format('Coletor de disco parado há %s min', round(v_age_min::numeric)),
      format('Última leitura de ops.host_disk_log em %s (%s%% usado, status %s). Verificar host-disk-guard (stack 167).',
             v_latest.checked_at, v_latest.used_pct, v_latest.status),
      'fn_host_disk_collector_guard',
      'swarm-manager',
      'critical'
    );
  END IF;

  RETURN jsonb_build_object('ok', false, 'age_min', round(v_age_min::numeric, 1),
                            'alerted', NOT v_open, 'used_pct', v_latest.used_pct);
END;
$$;


--
-- Name: fn_mirror_warroom_criticals(integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fn_mirror_warroom_criticals(p_lookback_hours integer DEFAULT 24) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_mirrored int;
  v_synced   int;
BEGIN
  INSERT INTO evo.evolution_alerts (alert_type, severity, title, message, payload, created_at)
  SELECT
    'warroom_' || w.alert_type::text,
    CASE
      WHEN w.alert_type::text IN ('critical', 'sla_breach') THEN 'critical'
      WHEN w.severity = 'high' THEN 'high'
      ELSE 'medium'
    END,
    COALESCE(w.title, w.message),
    w.message,
    jsonb_build_object(
      'warroom_id',  w.id,
      'source',      w.source,
      'entity',      w.entity,
      'mirrored_from', 'zapp.warroom_alerts',
      'mirrored_at', now()
    ),
    w.created_at
  FROM zapp.warroom_alerts w
  WHERE w.resolved_at IS NULL
    AND w.created_at > now() - make_interval(hours => p_lookback_hours)
    AND (w.alert_type::text IN ('critical', 'sla_breach') OR w.severity IN ('critical', 'high'))
    AND NOT EXISTS (
      SELECT 1 FROM evo.evolution_alerts e
      WHERE e.payload->>'warroom_id' = w.id::text
    )
    AND NOT EXISTS (
      SELECT 1 FROM evo.evolution_alerts e2
      WHERE e2.alert_type = 'warroom_' || w.alert_type::text
        AND e2.payload->>'source' = w.source
        AND e2.created_at > now() - interval '1 hour'
    );
  GET DIAGNOSTICS v_mirrored = ROW_COUNT;

  UPDATE evo.evolution_alerts e
  SET resolved_at = w.resolved_at,
      resolved_by = 'warroom-sync'
  FROM zapp.warroom_alerts w
  WHERE e.payload->>'warroom_id' = w.id::text
    AND w.resolved_at IS NOT NULL
    AND e.resolved_at IS NULL;
  GET DIAGNOSTICS v_synced = ROW_COUNT;

  RETURN jsonb_build_object(
    'ok', true,
    'mirrored', v_mirrored,
    'resolved_synced', v_synced,
    'lookback_hours', p_lookback_hours,
    'version', 'v2-20260807'
  );
END;
$$;


--
-- Name: fn_monitor_ingestion_persistence_gap(interval, integer, numeric, interval); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fn_monitor_ingestion_persistence_gap(p_window interval DEFAULT '00:30:00'::interval, p_min_upserts integer DEFAULT 5, p_degraded_ratio numeric DEFAULT 0.05, p_cooldown interval DEFAULT '01:00:00'::interval) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'evo', 'zapp', 'pg_catalog'
    AS $$
DECLARE
  v_upserts   bigint;
  v_persisted bigint;
  v_canary    bigint;
  v_esperado  bigint;
  v_ratio     numeric;
  v_estado    text;
  v_msg       text;
  v_ja_alertou boolean := false;
  v_cooldown_efetivo interval;
BEGIN
  -- ====================================================================
  -- v2 (2026-07-26): guardas adicionadas apos bateria adversarial:
  --  * p_cooldown minimo de 1 minuto (0 seconds causava poluicao de
  --    alertas em testes — 5 alertas criados por chamadas de teste).
  --  * v_ja_alertou inicializado com false (antes era uninit em paths
  --    onde o SELECT EXISTS nao executava, mas era seguro por coalesce).
  -- ====================================================================

  -- Cooldown minimo: 1 minuto. Previne poluicao por testes ou chamadas rapidas.
  v_cooldown_efetivo := GREATEST(coalesce(p_cooldown, '1 hour'::interval), '1 minute'::interval);

  SELECT count(*) INTO v_upserts
    FROM zapp.webhook_events_processed
   WHERE event_type = 'messages.upsert'
     AND processed_at > now() - p_window;

  SELECT count(*) INTO v_persisted
    FROM evo.evolution_messages_wpp2
   WHERE created_at > now() - p_window;

  -- Canary bloqueado por design por trg_filter_canary_messages.
  SELECT count(*) INTO v_canary
    FROM evo.evolution_audit_log
   WHERE action = 'canary_filtered'
     AND created_at > now() - p_window;

  v_esperado := GREATEST(v_upserts - v_canary, 0);
  v_ratio := CASE WHEN v_esperado = 0 THEN NULL
                  ELSE round(v_persisted::numeric / v_esperado::numeric, 4) END;

  IF v_esperado < p_min_upserts THEN
    v_estado := 'sem_volume_suficiente';
  ELSIF v_persisted = 0 THEN
    v_estado := 'ROMPIDO';
  ELSIF v_ratio < p_degraded_ratio THEN
    v_estado := 'DEGRADADO';
  ELSE
    v_estado := 'ok';
  END IF;

  IF v_estado IN ('ROMPIDO','DEGRADADO') THEN
    SELECT EXISTS (
      SELECT 1 FROM evo.evolution_alerts
       WHERE alert_type = 'ingestion_persistence_gap'
         AND created_at > now() - v_cooldown_efetivo
    ) INTO v_ja_alertou;

    v_msg := format(
      'Ingestao viva, persistencia %s. Janela %s: %s webhooks messages.upsert ingeridos'
      ' (%s canary descontados), %s mensagens persistidas em evo.evolution_messages_wpp2'
      ' (ratio %s). Perda silenciosa de mensagens de cliente.',
      lower(v_estado), p_window::text, v_upserts, v_canary,
      v_persisted, coalesce(v_ratio::text,'n/a'));

    IF NOT v_ja_alertou THEN
      INSERT INTO evo.evolution_alerts (alert_type, severity, title, message, payload)
      VALUES ('ingestion_persistence_gap','critical',
              format('Perda silenciosa de mensagens — persistencia %s', lower(v_estado)),
              v_msg,
              jsonb_build_object(
                'upserts', v_upserts, 'canary_descontados', v_canary,
                'esperado', v_esperado, 'persistidas', v_persisted, 'ratio', v_ratio,
                'janela', p_window::text, 'estado', v_estado,
                'cooldown_aplicado', v_cooldown_efetivo::text, 'detectado_em', now()));

      INSERT INTO zapp.warroom_alerts (alert_type, title, message, source, entity)
      VALUES ('critical',
              format('Perda silenciosa de mensagens — persistencia %s', lower(v_estado)),
              v_msg, 'fn_monitor_ingestion_persistence_gap', 'evolution_messages_wpp2');
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'ok', true, 'estado', v_estado, 'janela', p_window::text,
    'upserts_ingeridos', v_upserts, 'canary_descontados', v_canary,
    'esperado', v_esperado, 'persistidas', v_persisted, 'ratio', v_ratio,
    'cooldown_efetivo', v_cooldown_efetivo::text,
    'alerta_emitido', (v_estado IN ('ROMPIDO','DEGRADADO') AND NOT v_ja_alertou)
  );
END;
$$;


--
-- Name: FUNCTION fn_monitor_ingestion_persistence_gap(p_window interval, p_min_upserts integer, p_degraded_ratio numeric, p_cooldown interval); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.fn_monitor_ingestion_persistence_gap(p_window interval, p_min_upserts integer, p_degraded_ratio numeric, p_cooldown interval) IS 'v2 2026-07-26. Detecta perda silenciosa de mensagens: webhooks ingeridos mas nao persistidos. Historico: 11 dias de perda (15/07) passaram invisiveis sem este monitor. v2: (1) cooldown minimo de 1 minuto (evita poluicao por testes com cooldown=0); (2) v_ja_alertou inicializado com false; (3) cooldown_efetivo no retorno para rastreabilidade.';


--
-- Name: fn_notify_critical_alerts(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fn_notify_critical_alerts() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'evo'
    AS $$
DECLARE 
  v_cfg          record; 
  v_alert        record; 
  v_sent_wpp     int := 0; 
  v_sent_ext     int := 0;
  v_pending      int := 0; 
  v_conn_open    boolean; 
  v_req          bigint; 
  v_url          text; 
  v_key          text;
  v_ext_url      text;
BEGIN
  SELECT * INTO v_cfg FROM ops.notification_config WHERE id=1 AND enabled;
  IF NOT FOUND THEN 
    RETURN jsonb_build_object('ok', false, 'reason', 'config_ausente_ou_desabilitada'); 
  END IF;
  
  SELECT decrypted_secret INTO v_url FROM vault.decrypted_secrets WHERE name='evolution_api_url';
  SELECT decrypted_secret INTO v_key FROM vault.decrypted_secrets WHERE name='evolution_api_key';
  
  -- Canal externo (n8n + Bitrix24) — SEMPRE disponível, sem dependência do wpp2
  v_ext_url := v_cfg.external_webhook_url;
  
  SELECT count(*) INTO v_pending 
  FROM evo.evolution_alerts 
  WHERE severity='critical' AND notified_at IS NULL 
    AND coalesce(resolved, false) = false 
    AND created_at > now() - interval '48 hours';
  
  IF v_pending = 0 THEN
    RETURN jsonb_build_object('ok', true, 'action', 'sem_pendentes', 'pendentes', 0);
  END IF;
  
  -- === LOOP: para cada alerta crítico não notificado ===
  FOR v_alert IN 
    SELECT id, alert_type, title, message, created_at 
    FROM evo.evolution_alerts 
    WHERE severity='critical' AND notified_at IS NULL 
      AND coalesce(resolved, false) = false 
      AND created_at > now() - interval '48 hours' 
    ORDER BY created_at 
    LIMIT 5 
  LOOP
    -- CANAL 1 — WhatsApp (wpp2) — apenas se conectado (sem bloquear canal externo)
    IF v_url IS NOT NULL AND v_key IS NOT NULL THEN
      SELECT lower(coalesce(status,'')) IN ('open','connected') INTO v_conn_open 
      FROM zapp.whatsapp_connections WHERE instance_name = v_cfg.instance;
      
      IF coalesce(v_conn_open, false) THEN
        SELECT net.http_post(
          url := rtrim(v_url,'/') || '/message/sendText/' || v_cfg.instance,
          headers := jsonb_build_object('Content-Type','application/json','apikey', v_key),
          body := jsonb_build_object(
            'number', v_cfg.target_jid,
            'text', '🚨 *ALERTA CRÍTICO ZAP WEBB*' || E'\n\n*' || 
                    coalesce(v_alert.title, v_alert.alert_type) || '*' || E'\n' || 
                    coalesce(v_alert.message, '') || E'\n\n⏰ ' || 
                    to_char(v_alert.created_at AT TIME ZONE 'America/Sao_Paulo','DD/MM HH24:MI') || 
                    E'\n#' || v_alert.alert_type
          )
        ) INTO v_req;
        v_sent_wpp := v_sent_wpp + 1;
      END IF;
    END IF;
    
    -- CANAL 2 — n8n → Bitrix24 (SEMPRE envia, independente do wpp2)
    IF v_ext_url IS NOT NULL AND v_ext_url != '' THEN
      SELECT net.http_post(
        url := v_ext_url,
        headers := '{"Content-Type":"application/json"}'::jsonb,
        body := jsonb_build_object(
          'severity', 'critical',
          'alert_type', v_alert.alert_type,
          'message', coalesce(v_alert.message, ''),
          'title', coalesce(v_alert.title, v_alert.alert_type),
          'created_at', v_alert.created_at::text,
          'source', 'fn_notify_critical_alerts'
        )
      ) INTO v_req;
      v_sent_ext := v_sent_ext + 1;
    END IF;
    
    -- Marcar como notificado (pelo menos um canal tentou)
    IF v_sent_wpp > 0 OR v_sent_ext > 0 THEN
      UPDATE evo.evolution_alerts 
      SET notified_at = now(), 
          payload = coalesce(payload, '{}'::jsonb) || 
                    jsonb_build_object('notify_request_id', v_req, 'canal_ext', v_sent_ext > 0, 'canal_wpp', v_sent_wpp > 0)
      WHERE id = v_alert.id;
    END IF;
  END LOOP;
  
  RETURN jsonb_build_object(
    'ok', true, 
    'enviados_wpp', v_sent_wpp,
    'enviados_ext', v_sent_ext,
    'pendentes_restantes', v_pending - GREATEST(v_sent_wpp, v_sent_ext),
    'dual_channel', true
  );
END
$$;


--
-- Name: fn_payload_retention(integer, boolean); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fn_payload_retention(p_days integer DEFAULT 60, p_dry_run boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'evo'
    AS $$
DECLARE v_count bigint; v_bytes bigint;
BEGIN
  SELECT count(*), coalesce(sum(pg_column_size(payload)),0) INTO v_count, v_bytes
  FROM evo.evolution_messages
  WHERE payload IS NOT NULL AND created_at < now() - make_interval(days=>p_days)
    AND (media_url IS NOT NULL OR message_type IN ('text','conversation','extendedTextMessage','contact','location'));
  IF p_dry_run THEN
    RETURN jsonb_build_object('dry_run',true,'elegiveis',v_count,'bytes',v_bytes);
  END IF;
  UPDATE evo.evolution_messages SET payload=NULL
  WHERE payload IS NOT NULL AND created_at < now() - make_interval(days=>p_days)
    AND (media_url IS NOT NULL OR message_type IN ('text','conversation','extendedTextMessage','contact','location'));
  RETURN jsonb_build_object('dry_run',false,'limpos',v_count,'bytes_liberados',v_bytes);
END $$;


--
-- Name: fn_performance_report(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fn_performance_report() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'zapp', 'evo', 'extensions'
    AS $$
DECLARE
  v_slow_queries jsonb; v_bloat jsonb; v_indexes jsonb;
  v_conn jsonb; v_db jsonb; v_result jsonb;
BEGIN
  -- Top 5 slow queries (pg_stat_statements)
  BEGIN
    SELECT jsonb_agg(q ORDER BY q->>'total_sec' DESC) INTO v_slow_queries
    FROM (
      SELECT jsonb_build_object(
        'mean_ms', round(mean_exec_time::numeric,0),
        'calls', calls,
        'total_sec', round((total_exec_time/1000)::numeric,1),
        'query', LEFT(query,100)
      ) q
      FROM extensions.pg_stat_statements
      WHERE calls > 10 AND mean_exec_time > 100
      ORDER BY total_exec_time DESC
      LIMIT 5
    ) sub;
  EXCEPTION WHEN OTHERS THEN
    v_slow_queries := jsonb_build_object('error', SQLERRM);
  END;

  -- Tabelas com maior dead_tup_ratio
  SELECT jsonb_agg(row_to_json(q)::jsonb ORDER BY (row_to_json(q)->>'dead_pct')::numeric DESC)
  INTO v_bloat
  FROM (
    SELECT schemaname as schema, relname as tabela,
      round(100.0*n_dead_tup/NULLIF(n_live_tup+n_dead_tup,0),2) as dead_pct,
      n_live_tup as live, n_dead_tup as dead,
      pg_size_pretty(pg_total_relation_size(schemaname||'.'||relname)) as size
    FROM pg_stat_user_tables
    WHERE n_dead_tup > 100
      AND schemaname IN ('public','zapp','evo')
    ORDER BY dead_pct DESC
    LIMIT 5
  ) q;

  -- Unused indexes (0 scans, > 128kB)
  SELECT jsonb_agg(row_to_json(q)::jsonb)
  INTO v_indexes
  FROM (
    SELECT s.schemaname as schema, s.relname as tabela, s.indexrelname as indice,
      pg_size_pretty(pg_relation_size(s.indexrelid)) as tamanho,
      s.idx_scan as scans_total
    FROM pg_stat_user_indexes s
    JOIN pg_index i ON i.indexrelid=s.indexrelid
    WHERE s.schemaname IN ('public','zapp','evo')
      AND s.idx_scan = 0
      AND NOT i.indisprimary
      AND NOT i.indisunique
      AND pg_relation_size(s.indexrelid) > 131072
    ORDER BY pg_relation_size(s.indexrelid) DESC
    LIMIT 10
  ) q;

  -- Conexoes por aplicacao
  SELECT jsonb_agg(row_to_json(q)::jsonb ORDER BY (row_to_json(q)->>'conns')::int DESC)
  INTO v_conn
  FROM (
    SELECT COALESCE(NULLIF(application_name,''),'unknown') as app,
      state, COUNT(*) as conns
    FROM pg_stat_activity
    WHERE datname='postgres'
    GROUP BY application_name, state
    ORDER BY conns DESC
    LIMIT 10
  ) q;

  -- Tamanho das tabelas top 10
  SELECT jsonb_agg(row_to_json(q)::jsonb ORDER BY (row_to_json(q)->>'bytes')::bigint DESC)
  INTO v_db
  FROM (
    SELECT n.nspname as schema, c.relname as tabela,
      pg_total_relation_size(c.oid) as bytes,
      pg_size_pretty(pg_total_relation_size(c.oid)) as size
    FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
    WHERE c.relkind='r' AND n.nspname IN ('public','zapp','evo')
    ORDER BY pg_total_relation_size(c.oid) DESC
    LIMIT 10
  ) q;

  RETURN jsonb_build_object(
    'generated_at', now(),
    'slow_queries_top5', COALESCE(v_slow_queries,'[]'::jsonb),
    'bloat_top5', COALESCE(v_bloat,'[]'::jsonb),
    'unused_indexes_top10', COALESCE(v_indexes,'[]'::jsonb),
    'connections', COALESCE(v_conn,'[]'::jsonb),
    'largest_tables_top10', COALESCE(v_db,'[]'::jsonb)
  );
END;
$$;


--
-- Name: FUNCTION fn_performance_report(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.fn_performance_report() IS 'Snapshot de performance: top slow queries, bloat, unused indexes, conexoes, maiores tabelas. Retorna jsonb. Cron semanal segundas 06:00. Criado em auditoria 2026-07-04.';


--
-- Name: fn_regression_tests(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fn_regression_tests() RETURNS TABLE(test_name text, status text, detail text, duration_ms numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'pg_catalog'
    AS $$
DECLARE
  v_start timestamptz; v_n int; v_r jsonb; v_txt text;
  v_pass boolean; v_b1 int; v_b2 int;
  v_uses_zapp boolean; v_no_public boolean; v_score numeric;
BEGIN
  v_start:=clock_timestamp();
  SELECT COUNT(*) INTO v_n FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind='v' AND c.relname IN('zapp_audit_log','contact_audit_log','conversation_audit_logs','webhook_audit_log','team_messages','app_notifications','whatsapp_official_credentials') AND (c.reloptions::text LIKE '%security_invoker%');
  RETURN QUERY SELECT 'RT01_bridge_views_security_invoker'::text,CASE WHEN v_n=7 THEN 'PASS' ELSE 'FAIL' END::text,v_n::text||'/7'::text,round(EXTRACT(MILLISECONDS FROM (clock_timestamp()-v_start))::numeric,1);
  v_start:=clock_timestamp();
  SELECT COUNT(*) INTO v_n FROM information_schema.column_privileges cp WHERE cp.grantee IN('authenticated','anon') AND cp.privilege_type='SELECT' AND cp.column_name='api_key' AND cp.table_schema IN('public','zapp','evo') AND NOT(cp.table_schema='public' AND cp.table_name='instance_registry');
  RETURN QUERY SELECT 'RT02_api_key_blocked_fullscope'::text,CASE WHEN v_n=0 THEN 'PASS' ELSE 'FAIL' END::text,'grants='||v_n::text,round(EXTRACT(MILLISECONDS FROM (clock_timestamp()-v_start))::numeric,1);
  v_start:=clock_timestamp();
  SELECT COUNT(*) INTO v_n FROM information_schema.role_table_grants WHERE table_schema='zapp' AND grantee='anon' AND table_name IN('zapp_audit_log','contact_audit_log','conversation_audit_logs','webhook_audit_log','team_messages','app_notifications','whatsapp_official_credentials');
  RETURN QUERY SELECT 'RT03_anon_zapp_zero'::text,CASE WHEN v_n=0 THEN 'PASS' ELSE 'FAIL' END::text,'grants='||v_n::text,round(EXTRACT(MILLISECONDS FROM (clock_timestamp()-v_start))::numeric,1);
  v_start:=clock_timestamp();
  SELECT COUNT(*) INTO v_n FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind='r' AND n.nspname IN('public','zapp') AND NOT c.relrowsecurity;
  RETURN QUERY SELECT 'RT04_rls_100pct'::text,CASE WHEN v_n=0 THEN 'PASS' ELSE 'FAIL' END::text,'rls_off='||v_n::text,round(EXTRACT(MILLISECONDS FROM (clock_timestamp()-v_start))::numeric,1);
  v_start:=clock_timestamp();
  v_txt:=(ops.check_lovable_parity()).status||(ops.check_schema_drift()).status||(ops.check_critical_fks()).status;
  RETURN QUERY SELECT 'RT05_ops_checks'::text,CASE WHEN v_txt='OKOKOK' THEN 'PASS' ELSE 'FAIL' END::text,v_txt,round(EXTRACT(MILLISECONDS FROM (clock_timestamp()-v_start))::numeric,1);
  v_start:=clock_timestamp(); v_pass:=true;
  SELECT COUNT(*) INTO v_b1 FROM zapp.app_notifications; SELECT COUNT(*) INTO v_b2 FROM zapp.app_notifications;
  IF v_b1!=v_b2 THEN v_pass:=false; END IF;
  SELECT COUNT(*) INTO v_b1 FROM zapp.webhook_audit_log; SELECT COUNT(*) INTO v_b2 FROM zapp.webhook_audit_log;
  IF v_b1!=v_b2 THEN v_pass:=false; END IF;
  RETURN QUERY SELECT 'RT06_bridge_parity'::text,CASE WHEN v_pass THEN 'PASS' ELSE 'FAIL' END::text,'ok'::text,round(EXTRACT(MILLISECONDS FROM (clock_timestamp()-v_start))::numeric,1);
  v_start:=clock_timestamp();
  v_r:=zapp.fn_system_health_score(); v_score:=(v_r->>'score')::numeric;
  RETURN QUERY SELECT 'RT07_health_score_85plus'::text,CASE WHEN v_score>=85 THEN 'PASS' WHEN v_score>=75 THEN 'WARN ('||v_score||')' ELSE 'FAIL' END::text,'score='||(v_r->>'score')||' grade='||(v_r->>'grade'),round(EXTRACT(MILLISECONDS FROM (clock_timestamp()-v_start))::numeric,1);
  v_start:=clock_timestamp();
  RETURN QUERY SELECT 'RT08_guardrails_catalog'::text,CASE WHEN (ops.fn_guardrails_check())->>'ok'='true' AND (ops.fn_catalog_sanity_check())->>'status'='CLEAN' THEN 'PASS' ELSE 'FAIL' END::text,'ok',round(EXTRACT(MILLISECONDS FROM (clock_timestamp()-v_start))::numeric,1);
  v_start:=clock_timestamp();
  SELECT COUNT(*) INTO v_n FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname='app_notifications' AND (t.tgtype & 64)::boolean;
  RETURN QUERY SELECT 'RT09_instead_of_triggers'::text,CASE WHEN v_n=3 THEN 'PASS' ELSE 'FAIL' END::text,v_n::text||'/3',round(EXTRACT(MILLISECONDS FROM (clock_timestamp()-v_start))::numeric,1);
  v_start:=clock_timestamp();
  SELECT pg_get_functiondef(oid) LIKE '%zapp.webhook_audit_log%' INTO v_uses_zapp FROM pg_proc WHERE proname='fn_system_health_score';
  SELECT regexp_replace(pg_get_functiondef(oid),chr(45)||chr(45)||'[^'||chr(10)||']+','','g') NOT LIKE ('%zapp.webhook_audit_log%') INTO v_no_public FROM pg_proc WHERE proname='fn_system_health_score';
  RETURN QUERY SELECT 'RT10_audit_log_uses_zapp'::text,CASE WHEN v_uses_zapp AND v_no_public THEN 'PASS' ELSE 'FAIL' END::text,'zapp='||v_uses_zapp::text||' no_public='||v_no_public::text,round(EXTRACT(MILLISECONDS FROM (clock_timestamp()-v_start))::numeric,1);
  v_start:=clock_timestamp();
  v_r:=ops.check_infrastructure();
  RETURN QUERY SELECT 'RT11_infra_pct'::text,CASE WHEN (v_r->>'pct')::numeric>=85 THEN 'PASS' ELSE 'WARN ('||(v_r->>'pct')||'%)' END::text,'pct='||(v_r->>'pct'),round(EXTRACT(MILLISECONDS FROM (clock_timestamp()-v_start))::numeric,1);
  v_start:=clock_timestamp();
  SELECT COUNT(*) INTO v_n FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_constraint pk ON pk.conrelid=c.oid AND pk.contype='p' WHERE c.relkind='r' AND n.nspname IN('public','zapp','evo') AND pk.oid IS NULL;
  RETURN QUERY SELECT 'RT12_pk_zero_missing'::text,CASE WHEN v_n=0 THEN 'PASS' ELSE 'FAIL' END::text,'missing='||v_n::text,round(EXTRACT(MILLISECONDS FROM (clock_timestamp()-v_start))::numeric,1);
  v_start:=clock_timestamp();
  SELECT COUNT(*) INTO v_n FROM jsonb_object_keys((zapp.fn_system_health_score())->'breakdown');
  RETURN QUERY SELECT 'RT13_health_18plus_dims'::text,CASE WHEN v_n>=18 THEN 'PASS' ELSE 'FAIL' END::text,v_n::text||'/18+',round(EXTRACT(MILLISECONDS FROM (clock_timestamp()-v_start))::numeric,1);
  v_start:=clock_timestamp();
  SELECT COUNT(*) INTO v_n FROM cron.job WHERE jobname='vacuum_critical_tables';
  RETURN QUERY SELECT 'RT14_no_broken_vacuum_cron'::text,CASE WHEN v_n=0 THEN 'PASS' ELSE 'FAIL' END::text,'exists='||v_n::text,round(EXTRACT(MILLISECONDS FROM (clock_timestamp()-v_start))::numeric,1);
  v_start:=clock_timestamp();
  SELECT COUNT(*) INTO v_n FROM ops.schema_changelog;
  RETURN QUERY SELECT 'RT15_schema_changelog'::text,CASE WHEN v_n>=20 THEN 'PASS' ELSE 'FAIL' END::text,v_n::text||' entries',round(EXTRACT(MILLISECONDS FROM (clock_timestamp()-v_start))::numeric,1);
  v_start:=clock_timestamp();
  IF EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='ops' AND c.relkind='r' AND c.relname='edge_function_registry') THEN SELECT COUNT(*) INTO v_n FROM ops.edge_function_registry WHERE is_active; ELSE v_n:=0; END IF;
  RETURN QUERY SELECT 'RT16_edge_fn_registry_100plus'::text,CASE WHEN v_n>=100 THEN 'PASS' WHEN v_n>=50 THEN 'WARN' ELSE 'FAIL' END::text,v_n::text||' ativas',round(EXTRACT(MILLISECONDS FROM (clock_timestamp()-v_start))::numeric,1);
  v_start:=clock_timestamp();
  SELECT COUNT(*) INTO v_n FROM ops.check_mirror_integrity() WHERE severity='CRITICAL';
  RETURN QUERY SELECT 'RT17_mirror_integrity_no_critical'::text,CASE WHEN v_n=0 THEN 'PASS' ELSE 'FAIL ('||v_n||' CRITICAL)' END::text,'critical_checks='||v_n::text,round(EXTRACT(MILLISECONDS FROM (clock_timestamp()-v_start))::numeric,1);
  v_start:=clock_timestamp();
  SELECT COUNT(*) INTO v_n FROM information_schema.column_privileges WHERE grantee IN('authenticated','anon') AND table_schema IN('zapp','evo') AND column_name='api_key' AND privilege_type='SELECT';
  RETURN QUERY SELECT 'RT18_api_key_no_plain_select_zapp_evo'::text,CASE WHEN v_n=0 THEN 'PASS' ELSE 'FAIL' END::text,'plain_grants='||v_n::text,round(EXTRACT(MILLISECONDS FROM (clock_timestamp()-v_start))::numeric,1);
  v_start:=clock_timestamp();
  SELECT COUNT(*) INTO v_n FROM information_schema.columns WHERE table_schema='public' AND table_name='evolution_instance_credentials' AND column_name IN('api_key','instance_token');
  RETURN QUERY SELECT 'RT19_evo_creds_view_no_secrets'::text,CASE WHEN v_n=0 THEN 'PASS' ELSE 'FAIL' END::text,'exposed_cols='||v_n::text,round(EXTRACT(MILLISECONDS FROM (clock_timestamp()-v_start))::numeric,1);
  v_start:=clock_timestamp();
  SELECT COUNT(*) INTO v_n FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='ops' AND(has_function_privilege('anon',p.oid,'EXECUTE') OR has_function_privilege('authenticated',p.oid,'EXECUTE'));
  RETURN QUERY SELECT 'RT20_ops_schema_private'::text,CASE WHEN v_n=0 THEN 'PASS' ELSE 'FAIL ('||v_n||' exposed)' END::text,'public_fns='||v_n::text,round(EXTRACT(MILLISECONDS FROM (clock_timestamp()-v_start))::numeric,1);
  v_start:=clock_timestamp();
  SELECT COUNT(*) INTO v_n FROM pg_roles r JOIN pg_db_role_setting s ON s.setrole=r.oid AND s.setdatabase=0 WHERE r.rolname IN('postgres','authenticated','anon') AND s.setconfig @> ARRAY['idle_in_transaction_session_timeout=60s'];
  RETURN QUERY SELECT 'RT21_idle_in_tx_timeout_configured'::text,CASE WHEN v_n=3 THEN 'PASS' ELSE 'FAIL ('||v_n||'/3 roles)' END::text,v_n::text||'/3 roles',round(EXTRACT(MILLISECONDS FROM (clock_timestamp()-v_start))::numeric,1);
  v_start:=clock_timestamp();
  SELECT COUNT(*) INTO v_n FROM(SELECT tablename FROM pg_tables WHERE schemaname='vendas' AND tablename IN('creditos','trocas') AND NOT rowsecurity UNION ALL SELECT t.tablename FROM pg_tables t WHERE t.schemaname='vendas' AND t.tablename IN('creditos','trocas') AND has_table_privilege('anon','vendas.'||t.tablename,'SELECT')) issues;
  RETURN QUERY SELECT 'RT22_vendas_g1_rls_fix'::text,CASE WHEN v_n=0 THEN 'PASS' ELSE 'FAIL ('||v_n||' issues)' END::text,'rls_off_or_anon_access='||v_n::text,round(EXTRACT(MILLISECONDS FROM (clock_timestamp()-v_start))::numeric,1);
  v_start:=clock_timestamp();
  v_r:=zapp.fn_score_security_acl(); v_n:=COALESCE((v_r->>'legacy_rls_off_anon')::int,-1);
  RETURN QUERY SELECT 'RT23_g8_legacy_sentinel'::text,CASE WHEN v_n=0 THEN 'PASS' WHEN v_n>0 THEN 'FAIL ('||v_n||' violations)' ELSE 'FAIL (vector missing)' END::text,'legacy_rls_off_anon='||v_n::text,round(EXTRACT(MILLISECONDS FROM (clock_timestamp()-v_start))::numeric,1);
  v_start:=clock_timestamp();
  SELECT COUNT(*) INTO v_n FROM pg_matviews WHERE schemaname IN('public','evo','zapp') AND ispopulated=false;
  RETURN QUERY SELECT 'RT24_matviews_all_populated'::text,CASE WHEN v_n=0 THEN 'PASS' ELSE 'FAIL ('||v_n||' unpopulated)' END::text,'unpopulated_matviews='||v_n::text,round(EXTRACT(MILLISECONDS FROM (clock_timestamp()-v_start))::numeric,1);
  v_start:=clock_timestamp();
  SELECT EXTRACT(EPOCH FROM (now() - GREATEST(
    (SELECT max(heartbeat_at) FROM evo.evolution_guardian_heartbeat WHERE service_name='swarm-task-guardian'),
    (SELECT max(heartbeat_at) FROM zapp.evolution_guardian_heartbeat WHERE service_name='swarm-task-guardian')
  )))/60 INTO v_score;
  RETURN QUERY SELECT 'RT25_guardian_heartbeat_fresh'::text,
    CASE WHEN v_score < 30 THEN 'PASS' ELSE 'FAIL (gap='||round(v_score::numeric,1)||'min)' END::text,
    'gap_min='||round(COALESCE(v_score::numeric,9999),1)||' (threshold:30min)',
    round(EXTRACT(MILLISECONDS FROM (clock_timestamp()-v_start))::numeric,1);
  v_start:=clock_timestamp();
  SELECT COUNT(DISTINCT p.oid) INTO v_n
  FROM pg_depend d
  JOIN pg_proc p ON p.oid = d.refobjid
  JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE d.classid = 'pg_policy'::regclass
    AND d.refclassid = 'pg_proc'::regclass
    AND n.nspname IN ('public','zapp','evo')
    AND p.prokind = 'f'
    AND NOT has_function_privilege('authenticated', p.oid, 'EXECUTE');
  RETURN QUERY SELECT 'RT26_rls_fns_exec_authenticated'::text,
    CASE WHEN v_n=0 THEN 'PASS' ELSE 'FAIL ('||v_n||' broken)' END::text,
    'broken='||v_n::text,
    round(EXTRACT(MILLISECONDS FROM (clock_timestamp()-v_start))::numeric,1);
  v_start:=clock_timestamp();
  SELECT ops.fn_auth_can_read_front_views() INTO v_pass;
  RETURN QUERY SELECT 'RT27_authenticated_reads_front_views'::text,
    CASE WHEN v_pass THEN 'PASS' ELSE 'FAIL (permission denied)' END::text,
    CASE WHEN v_pass THEN 'messages+contacts ok' ELSE 'authenticated blocked on front views' END,
    round(EXTRACT(MILLISECONDS FROM (clock_timestamp()-v_start))::numeric,1);
  v_start:=clock_timestamp();
  SELECT prosrc LIKE '%auth.uid() IS NOT NULL AND NOT zapp.is_admin_or_supervisor%' INTO v_pass FROM pg_proc WHERE proname='bulk_auto_merge_duplicates' AND pronamespace='zapp'::regnamespace;
  RETURN QUERY SELECT 'RT28_bulk_merge_auth_guard'::text,CASE WHEN v_pass THEN 'PASS' ELSE 'FAIL' END::text,'has_guard='||coalesce(v_pass::text,'missing'),round(EXTRACT(MILLISECONDS FROM (clock_timestamp()-v_start))::numeric,1);
  v_start:=clock_timestamp();
  SELECT NOT has_function_privilege('authenticated','public.purge_old_query_telemetry(integer)','EXECUTE') INTO v_pass;
  RETURN QUERY SELECT 'RT29_purge_telemetry_auth_blocked'::text,CASE WHEN v_pass THEN 'PASS' ELSE 'FAIL' END::text,'auth_blocked='||coalesce(v_pass::text,'err'),round(EXTRACT(MILLISECONDS FROM (clock_timestamp()-v_start))::numeric,1);
  v_start:=clock_timestamp();
  SELECT COUNT(*) INTO v_n FROM (VALUES ('vendas.envios_cotacao_id_seq'),('vendas.parabens_enviados_id_seq')) s(sq) WHERE has_sequence_privilege('anon',sq,'USAGE');
  RETURN QUERY SELECT 'RT30_vendas_seq_no_anon_usage'::text,CASE WHEN v_n=0 THEN 'PASS' ELSE 'FAIL ('||v_n||' exposed)' END::text,'anon_usage_count='||v_n::text,round(EXTRACT(MILLISECONDS FROM (clock_timestamp()-v_start))::numeric,1);
  v_start:=clock_timestamp();
  SELECT prosrc LIKE '%v_workspace_id IS NULL OR c.workspace_id = v_workspace_id%' INTO v_pass FROM pg_proc WHERE proname='get_contact_360_by_phone' AND pronamespace='zapp'::regnamespace;
  RETURN QUERY SELECT 'RT31_contact_360_workspace_isolation'::text,CASE WHEN v_pass THEN 'PASS' ELSE 'FAIL' END::text,'has_workspace_filter='||coalesce(v_pass::text,'missing'),round(EXTRACT(MILLISECONDS FROM (clock_timestamp()-v_start))::numeric,1);
  v_start:=clock_timestamp();
  SELECT NOT has_function_privilege('authenticated','zapp.get_contact_intelligence_by_phone(text)','EXECUTE') INTO v_pass;
  RETURN QUERY SELECT 'RT32_intelligence_zapp_direct_blocked'::text,CASE WHEN v_pass THEN 'PASS' ELSE 'FAIL' END::text,'auth_zapp_blocked='||coalesce(v_pass::text,'err'),round(EXTRACT(MILLISECONDS FROM (clock_timestamp()-v_start))::numeric,1);
  v_start:=clock_timestamp();
  SELECT(
    NOT has_function_privilege('authenticated','vendas.fn_listar_bling_tokens()','EXECUTE')
    AND NOT has_function_privilege('authenticated','financeiro.apagar_nota_fiscal(uuid)','EXECUTE')
    AND NOT has_function_privilege('authenticated','vendas.resetar_envios_pedido(text)','EXECUTE')
  ) INTO v_pass;
  RETURN QUERY SELECT 'RT33_p0_credential_and_delete_blocked'::text,CASE WHEN v_pass THEN 'PASS' ELSE 'FAIL' END::text,'bling_nf_reset_all_blocked='||coalesce(v_pass::text,'err'),round(EXTRACT(MILLISECONDS FROM (clock_timestamp()-v_start))::numeric,1);
END;
$$;


--
-- Name: FUNCTION fn_regression_tests(); Type: COMMENT; Schema: ops; Owner: -
