COMMENT ON FUNCTION ops.fn_regression_tests() IS 'Suite RT01-RT19. RT18=backup sentinel. RT19=ops privado. 2026-07-07.';


--
-- Name: fn_regression_tests_backup_check(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fn_regression_tests_backup_check() RETURNS TABLE(test_name text, status text, detail text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'zapp'
    AS $$
DECLARE v_pass boolean; v_txt text; v_conn_status text;
BEGIN
  SELECT (now()-last_backup_at)<interval '48 hours' AND last_backup_table_count>=600 INTO v_pass FROM ops.backup_sentinel;
  SELECT extract(hours FROM (now()-last_backup_at))::int||'h, '||last_backup_table_count||' tables' INTO v_txt FROM ops.backup_sentinel;
  RETURN QUERY SELECT 'RT21_backup_sentinel_fresh'::text, CASE WHEN COALESCE(v_pass,false) THEN 'PASS' ELSE 'FAIL' END::text, COALESCE(v_txt,'no sentinel');

  RETURN QUERY SELECT 'RT22_backup_cron_active'::text,
    CASE WHEN EXISTS(SELECT 1 FROM cron.job j WHERE j.jobname='daily-backup-sentinel-check' AND j.active) THEN 'PASS' ELSE 'FAIL' END::text,
    'jobid=127'::text;

  SELECT w.status||'|'||w.health_status INTO v_conn_status FROM zapp.whatsapp_connections w WHERE w.instance_name='wpp2';
  RETURN QUERY SELECT 'RT23_wpp2_connected'::text,
    CASE WHEN v_conn_status LIKE 'connected|%' THEN 'PASS' ELSE 'FAIL' END::text,
    COALESCE(v_conn_status,'not_found');
END;
$$;


--
-- Name: FUNCTION fn_regression_tests_backup_check(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.fn_regression_tests_backup_check() IS 'Suite suplementar RT21-RT23: backup sentinel, cron, wpp2. Criada 2026-07-07.';


--
-- Name: fn_schema_fingerprint(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fn_schema_fingerprint() RETURNS text
    LANGUAGE sql STABLE
    AS $$ SELECT md5( (SELECT COALESCE(string_agg(c.relname||'.'||a.attname||':'||format_type(a.atttypid,a.atttypmod)||':'||a.attnotnull::text, '|' ORDER BY c.relname, a.attname), '') FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','v','m','p') AND a.attnum>0 AND NOT a.attisdropped) || '#' || (SELECT COALESCE(string_agg(cn.nspname||'.'||cl.relname||'.'||con.conname, '|' ORDER BY cn.nspname, cl.relname, con.conname), '') FROM pg_constraint con JOIN pg_namespace cn ON cn.oid=con.connamespace JOIN pg_class cl ON cl.oid=con.conrelid WHERE con.contype IN ('f','p') AND cn.nspname IN ('public','zapp','evo','email_app','vendas','financeiro','ai','bpm')) ) $$;


--
-- Name: fn_secdef_search_path_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fn_secdef_search_path_guard() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'pg_catalog'
    AS $$
DECLARE
  v_fixed   int := 0;
  v_already int := 0;
  r         RECORD;
  v_sql     text;
BEGIN
  FOR r IN
    SELECT n.nspname, p.proname,
           pg_get_function_identity_arguments(p.oid) as args,
           p.oid
    FROM pg_proc p
    JOIN pg_namespace n ON p.pronamespace=n.oid
    WHERE n.nspname IN (
      'ops','evo','zapp','financeiro',
      'monitoring','artes','vendas','email_app',
      'ai','bpm','archive','logistica','pgbouncer'
    )
      AND p.prosecdef=true
      AND (
        p.proconfig IS NULL
        OR NOT EXISTS (
          SELECT 1 FROM unnest(p.proconfig) cfg
          WHERE cfg LIKE 'search_path=%'
        )
      )
    ORDER BY n.nspname, p.proname
  LOOP
    v_sql := format(
      'ALTER FUNCTION %I.%I(%s) SET search_path = %s',
      r.nspname, r.proname, r.args,
      CASE r.nspname
        WHEN 'ops'        THEN 'ops, evo, zapp, public, pg_catalog'
        WHEN 'evo'        THEN 'evo, public, pg_catalog'
        WHEN 'zapp'       THEN 'zapp, evo, public, pg_catalog'
        WHEN 'financeiro' THEN 'financeiro, vendas, public, pg_catalog'
        WHEN 'monitoring' THEN 'monitoring, zapp, evo, public, pg_catalog'
        WHEN 'artes'      THEN 'artes, public, pg_catalog'
        WHEN 'vendas'     THEN 'vendas, public, pg_catalog'
        WHEN 'email_app'  THEN 'email_app, zapp, public, pg_catalog'
        WHEN 'ai'         THEN 'ai, zapp, public, pg_catalog'
        WHEN 'bpm'        THEN 'bpm, zapp, public, pg_catalog'
        WHEN 'archive'    THEN 'archive, zapp, public, pg_catalog'
        WHEN 'logistica'  THEN 'logistica, zapp, public, pg_catalog'
        WHEN 'pgbouncer'  THEN 'pg_catalog, pg_temp'
        ELSE 'public, pg_catalog'
      END
    );
    BEGIN
      EXECUTE v_sql;
      v_fixed := v_fixed + 1;
      INSERT INTO ops.schema_changelog
        (session_date, session_label, change_type, object_schema, object_name, description, impact, severity, applied_by)
      VALUES
        (CURRENT_DATE, 'secdef-guard-auto', 'SECURITY', r.nspname, r.proname,
         'Auto-fix: SET search_path aplicado por fn_secdef_search_path_guard v3.0.',
         'Prevenir SQL injection via search_path manipulation', 'HIGH', 'cron:secdef-guard')
      ON CONFLICT DO NOTHING;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'fn_secdef_guard: falha ao alterar %.%(%): %', r.nspname, r.proname, r.args, SQLERRM;
    END;
  END LOOP;

  SELECT COUNT(*) INTO v_already
  FROM pg_proc p JOIN pg_namespace n ON p.pronamespace=n.oid
  WHERE n.nspname IN (
    'ops','evo','zapp','financeiro','monitoring','artes','vendas',
    'email_app','ai','bpm','archive','logistica','pgbouncer'
  )
    AND p.prosecdef=true
    AND p.proconfig IS NOT NULL
    AND EXISTS (
      SELECT 1 FROM unnest(p.proconfig) cfg WHERE cfg LIKE 'search_path=%'
    );

  RETURN jsonb_build_object(
    'fixed', v_fixed,
    'already_ok', v_already,
    'timestamp', now(),
    'version', '3.0-all-schemas'
  );
END;
$$;


