--
-- Name: fn_test_health_score_unmask(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fn_test_health_score_unmask() RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE v_base int; v_after int; v_pass boolean;
BEGIN
  -- Teste de regressao R13: injeta falha da classe historicamente mascarada e valida deteccao. Sempre faz rollback via exception... nao: usa subtransacao implicita? PL/pgSQL nao permite rollback interno; usa DELETE explicito do sintetico.
  SELECT (zapp.fn_system_health_score()->'breakdown'->'cron_health'->>'failures_1h')::int INTO v_base;
  INSERT INTO cron.job_run_details (jobid, runid, status, return_message, start_time, end_time)
  VALUES (99901, 999999999, 'failed', 'ERROR: relation "ops.regression_probe" does not exist', now()-interval '1 minute', now()-interval '1 minute');
  SELECT (zapp.fn_system_health_score()->'breakdown'->'cron_health'->>'failures_1h')::int INTO v_after;
  DELETE FROM cron.job_run_details WHERE runid = 999999999;
  v_pass := (v_after = v_base + 1);
  RETURN jsonb_build_object('test','R13_unmask_regression','pass',v_pass,'baseline',v_base,'after_injection',v_after,'expected',v_base+1,'checked_at',now());
END $$;


--
-- Name: fn_update_backup_sentinel(text, bigint, integer, boolean, boolean); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fn_update_backup_sentinel(p_file text, p_size_bytes bigint, p_table_count integer, p_offsite_ok boolean DEFAULT false, p_dry_run boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'pg_catalog'
    AS $_$
BEGIN
  IF p_file IS NULL OR trim(p_file) = '' THEN
    RETURN jsonb_build_object('error','file_empty'); END IF;
  IF length(p_file) > 200 THEN
    RETURN jsonb_build_object('error','filename_too_long','max',200,'len',length(p_file)); END IF;
  IF p_file !~ '^[a-zA-Z0-9_\.\-]+$' THEN
    RETURN jsonb_build_object('error','invalid_filename_pattern','file',left(p_file,50)); END IF;
  IF p_file ~ E'[/\\\\<>\'";&|\\n\\r\\t]' OR p_file ~ '--' OR p_file ILIKE '%.php%' THEN
    RETURN jsonb_build_object('error','invalid_filename_chars','file',left(p_file,50)); END IF;
  IF p_table_count < 400 THEN
    RETURN jsonb_build_object('error','table_count_too_low','count',p_table_count); END IF;
  IF p_size_bytes < 10000000 THEN
    RETURN jsonb_build_object('error','file_too_small','size_bytes',p_size_bytes); END IF;
  IF p_file NOT LIKE '%.%' THEN
    RETURN jsonb_build_object('error','filename_no_extension','file',p_file); END IF;
  -- DRY RUN: validar sem escrever
  IF p_dry_run THEN
    RETURN jsonb_build_object('dry_run',true,'valid',true,'file',p_file,
      'size_mb',round(p_size_bytes/1048576.0,1),'table_count',p_table_count); END IF;
  -- Atualizar sentinel
  UPDATE ops.backup_sentinel SET
    last_backup_at          = now(),
    last_backup_file        = p_file,
    last_backup_size_bytes  = p_size_bytes,
    last_backup_table_count = p_table_count,
    last_offsite_at         = CASE WHEN p_offsite_ok THEN now() ELSE last_offsite_at END,
    updated_at              = now()
  WHERE id = 1;
  RETURN jsonb_build_object('updated',true,'file',p_file,
    'size_mb',round(p_size_bytes/1048576.0,1),'table_count',p_table_count,'at',now());
END;$_$;


--
-- Name: fn_update_redis_sentinel(numeric, bigint, boolean, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fn_update_redis_sentinel(p_used_mb numeric DEFAULT NULL::numeric, p_evicted bigint DEFAULT NULL::bigint, p_defrag boolean DEFAULT NULL::boolean, p_policy text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops'
    AS $$
BEGIN
  UPDATE ops.redis_sentinel SET
    last_ping_at = now(),
    used_memory_mb = COALESCE(p_used_mb, used_memory_mb),
    evicted_keys = COALESCE(p_evicted, evicted_keys),
    activedefrag = COALESCE(p_defrag, activedefrag),
    maxmemory_policy = COALESCE(p_policy, maxmemory_policy),
    updated_at = now()
  WHERE id = 1;
  RETURN jsonb_build_object('updated', true, 'at', now());
END;
$$;


--
-- Name: FUNCTION fn_update_redis_sentinel(p_used_mb numeric, p_evicted bigint, p_defrag boolean, p_policy text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.fn_update_redis_sentinel(p_used_mb numeric, p_evicted bigint, p_defrag boolean, p_policy text) IS 'Atualiza metricas do Redis no sentinel. Chamada pelo watchdog externo (baileys-backup/evolution) a cada 5 min com dados reais do Redis. Fallback: cron PostgreSQL atualiza apenas last_ping_at.';


--
-- Name: fn_verify_alert_delivery(interval, integer, interval, integer, interval); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.fn_verify_alert_delivery(p_lookback interval DEFAULT '04:00:00'::interval, p_max_attempts integer DEFAULT 3, p_grace interval DEFAULT '00:05:00'::interval, p_batch integer DEFAULT 300, p_blackout_win interval DEFAULT '02:00:00'::interval) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops, pg_temp'
    AS $_$
DECLARE
  v_a          record;
  v_requeued   int := 0;  v_exhausted  int := 0;
  v_delivered  int := 0;  v_pending    int := 0;
  v_unverifiable int := 0; v_backlog   int := 0;
  v_ch_ok      bigint;   v_ch_fail    bigint;
  v_blackout   boolean;
  v_pgnet_ttl  interval;
BEGIN
  v_pgnet_ttl := COALESCE(current_setting('pg_net.ttl', TRUE)::interval, interval '1 hour');

  IF p_lookback >= v_pgnet_ttl THEN
    p_lookback := GREATEST(v_pgnet_ttl - interval '30 minutes', interval '1 minute');
  END IF;

  FOR v_a IN
    SELECT a.id, a.alert_type, a.notified_at,
           coalesce((a.payload->>'notify_attempts')::int, 1) AS attempts,
           r.status_code, r.error_msg,
           (r.id IS NOT NULL) AS has_response,
           coalesce((a.payload->>'delivery_confirmed')::boolean, NULL) AS ja_confirmado
    FROM evo.evolution_alerts a
    LEFT JOIN net._http_response r
           ON r.id = (a.payload->>'notify_request_id')::bigint
    WHERE a.severity = 'critical'
      AND a.notified_at IS NOT NULL
      AND coalesce(a.resolved, false) = false
      AND a.payload ? 'notify_request_id'
      AND (a.payload->>'notify_request_id') ~ '^[0-9]+$'
      AND a.created_at > now() - p_lookback
    ORDER BY a.id
    LIMIT p_batch
    FOR UPDATE OF a SKIP LOCKED
  LOOP
    IF v_a.has_response AND v_a.status_code BETWEEN 200 AND 299 THEN
      v_delivered := v_delivered + 1;
      IF v_a.ja_confirmado IS DISTINCT FROM true THEN
        UPDATE evo.evolution_alerts
           SET payload = payload || jsonb_build_object(
                 'delivery_confirmed', true,
                 'delivery_status', v_a.status_code,
                 'delivery_checked_at', now())
         WHERE id = v_a.id;
      END IF;
      CONTINUE;
    END IF;

    IF NOT v_a.has_response AND v_a.notified_at > now() - p_grace THEN
      v_pending := v_pending + 1;
      CONTINUE;
    END IF;

    IF NOT v_a.has_response THEN
      IF v_a.attempts < p_max_attempts THEN
        UPDATE evo.evolution_alerts
           SET notified_at = NULL,
               payload = payload || jsonb_build_object(
                 'delivery_confirmed', false,
                 'delivery_error', 'sem_resposta_pgnet_ttl',
                 'notify_attempts', v_a.attempts + 1,
                 'delivery_checked_at', now(),
                 'requeued_at', now())
         WHERE id = v_a.id;
        v_requeued := v_requeued + 1;
      ELSE
        UPDATE evo.evolution_alerts
           SET payload = payload || jsonb_build_object(
                 'delivery_confirmed', false,
                 'delivery_unverifiable', true,
                 'delivery_error', 'sem_resposta_pgnet_ttl',
                 'delivery_checked_at', now())
         WHERE id = v_a.id;
        v_unverifiable := v_unverifiable + 1;
      END IF;
    ELSE
      IF v_a.attempts < p_max_attempts THEN
        UPDATE evo.evolution_alerts
           SET notified_at = NULL,
               payload = payload || jsonb_build_object(
                 'delivery_confirmed', false,
                 'delivery_status', v_a.status_code,
                 'delivery_error', left(coalesce(v_a.error_msg, 'http_'||coalesce(v_a.status_code::text,'null')),200),
                 'notify_attempts', v_a.attempts + 1,
                 'delivery_checked_at', now(),
                 'requeued_at', now())
         WHERE id = v_a.id;
        v_requeued := v_requeued + 1;
      ELSE
        UPDATE evo.evolution_alerts
           SET payload = payload || jsonb_build_object(
                 'delivery_confirmed', false,
                 'delivery_status', v_a.status_code,
                 'delivery_exhausted', true,
                 'delivery_checked_at', now())
         WHERE id = v_a.id;
        v_exhausted := v_exhausted + 1;
      END IF;
    END IF;
  END LOOP;

  WITH b AS (
    UPDATE evo.evolution_alerts
       SET payload = payload || jsonb_build_object(
             'delivery_confirmed', false,
             'delivery_unverifiable', true,
             'delivery_error', 'resposta_pgnet_expirada_antes_da_verificacao',
             'delivery_checked_at', now())
     WHERE id IN (
       SELECT a.id FROM evo.evolution_alerts a
        WHERE a.severity = 'critical'
          AND a.notified_at IS NOT NULL
          AND coalesce(a.resolved, false) = false
          AND a.payload ? 'notify_request_id'
          AND NOT (a.payload ? 'delivery_checked_at')
          AND a.created_at <= now() - p_lookback
        ORDER BY a.id
        LIMIT p_batch
        FOR UPDATE SKIP LOCKED)
    RETURNING 1
  ) SELECT count(*) INTO v_backlog FROM b;

  SELECT count(*) FILTER (WHERE (payload->>'delivery_confirmed')::boolean IS TRUE),
         count(*) FILTER (WHERE (payload->>'delivery_confirmed')::boolean IS FALSE)
    INTO v_ch_ok, v_ch_fail
    FROM evo.evolution_alerts
   WHERE severity = 'critical'
     AND payload ? 'delivery_confirmed'
     AND (payload->>'delivery_checked_at')::timestamptz > now() - p_blackout_win;

  v_blackout := (
    v_ch_fail >= 3 AND
    (v_ch_ok::float / NULLIF(v_ch_ok + v_ch_fail, 0) < 0.05)
  );

  IF v_blackout
    AND NOT EXISTS (
      SELECT 1 FROM zapp.warroom_alerts
       WHERE source = 'fn_verify_alert_delivery'
         AND created_at > now() - LEAST(p_blackout_win, interval '30 minutes')
    ) THEN
    INSERT INTO zapp.warroom_alerts (alert_type, title, message, source, entity)
    VALUES ('critical',
            'BLACKOUT DE NOTIFICACAO — nenhum alerta critico esta sendo entregue',
            format('Ultimas %s no canal: %s entregas confirmadas, %s falhas (taxa sucesso < 5%%). Alertas criticos NAO chegam a ninguem.',
                   p_blackout_win::text, v_ch_ok, v_ch_fail),
            'fn_verify_alert_delivery', 'notification_channel');
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'versao', 'v7',
    'entregues', v_delivered,
    'reenfileirados', v_requeued,
    'esgotados', v_exhausted,
    'aguardando_graca', v_pending,
    'nao_verificaveis', v_unverifiable,
    'passivo_historico_marcado', v_backlog,
    'canal_confirmadas', v_ch_ok,
    'canal_falhas', v_ch_fail,
    'blackout', v_blackout,
    'lookback_efetivo', p_lookback::text,
    'pgnet_ttl', v_pgnet_ttl::text,
    'invariante_lookback_lt_ttl', p_lookback < v_pgnet_ttl
  );
END;
$_$;


--
-- Name: FUNCTION fn_verify_alert_delivery(p_lookback interval, p_max_attempts integer, p_grace interval, p_batch integer, p_blackout_win interval); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.fn_verify_alert_delivery(p_lookback interval, p_max_attempts integer, p_grace interval, p_batch integer, p_blackout_win interval) IS 'v4 2026-07-26. Fecha o laco de entrega de alertas criticos. Mudancas v4 (bateria adversarial): (1) p_blackout_win parametrizado — era hardcode 2h; (2) invariante lookback < pg_net.ttl enforçada — se violada, usa pgnet_ttl-30min automaticamente; (3) contadores reenfileirados/esgotados/nao_verificaveis agora mutuamente exclusivos — sem dupla contagem; (4) LOOP separa caso sem-resposta de caso com-resposta-4xx explicitamente.';


