--
-- Name: ingest_host_disk(integer, text, text, text, text, text, integer, integer, integer, boolean); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.ingest_host_disk(p_used_pct integer, p_used_h text DEFAULT NULL::text, p_avail_h text DEFAULT NULL::text, p_total_h text DEFAULT NULL::text, p_mount text DEFAULT '/'::text, p_host text DEFAULT 'swarm-manager'::text, p_warn integer DEFAULT NULL::integer, p_crit integer DEFAULT NULL::integer, p_cooldown_min integer DEFAULT NULL::integer, p_persist boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops'
    AS $$
DECLARE
  cfg          ops.host_disk_config%ROWTYPE;
  v_tier       text;
  v_prev_tier  text;
  v_transitioned boolean := false;
  v_should_alert boolean := false;
  v_recovery   boolean := false;  -- nunca NULL
  v_warn int; v_crit int;
  v_status text;
  -- BUG-01 FIX: RECOVERY_THRESHOLD como SET para IS ANY test seguro
  RECOVERY_THRESHOLD constant text[] := ARRAY['WARN','THROTTLE','FREEZE','EMERGENCY'];
BEGIN
  -- Validacao de entrada
  IF p_used_pct IS NULL OR p_used_pct < 0 OR p_used_pct > 100 THEN
    RETURN jsonb_build_object('ok',false,'error',format('used_pct invalido: %s',p_used_pct));
  END IF;

  SELECT * INTO cfg FROM ops.host_disk_config WHERE id=1;
  v_warn := COALESCE(p_warn, cfg.warn_pct, 75);
  v_crit := COALESCE(p_crit, cfg.crit_pct, 90);

  -- Tier novo (7 niveis)
  v_tier := ops.calculate_tier(p_used_pct);

  -- Status legado (retrocompat com 3-state)
  IF p_used_pct >= v_crit THEN v_status := 'CRIT';
  ELSIF p_used_pct >= v_warn THEN v_status := 'WARN';
  ELSE v_status := 'OK'; END IF;

  -- BUG-02 FIX: ORDER BY id DESC (deterministico, id sempre crescente)
  SELECT hdl.tier INTO v_prev_tier
  FROM ops.host_disk_log hdl
  WHERE hdl.host = p_host
  ORDER BY hdl.id DESC  -- <-- corrigido de checked_at DESC
  LIMIT 1;

  v_transitioned := (v_prev_tier IS DISTINCT FROM v_tier);

  -- BUG-01 FIX: COALESCE evita NULL quando v_prev_tier IS NULL
  -- NULL = ANY(array) => NULL (bug), COALESCE(NULL, false) => false
  v_recovery := (
    v_transitioned
    AND COALESCE(v_prev_tier = ANY(RECOVERY_THRESHOLD), false)  -- <-- corrigido
    AND v_tier NOT IN ('WARN','THROTTLE','FREEZE','EMERGENCY')
  );

  -- Persiste row
  IF p_persist THEN
    INSERT INTO ops.host_disk_log(
      host, mount, used_pct, used_h, avail_h, total_h,
      status, tier, transitioned
    ) VALUES (
      p_host, p_mount, p_used_pct, p_used_h, p_avail_h, p_total_h,
      v_status, v_tier, v_transitioned
    );
  END IF;

  -- Log tier transition
  IF v_transitioned AND p_persist THEN
    INSERT INTO ops.disk_event_log(event_type, from_state, to_state, detail)
    VALUES ('TIER_TRANSITION', v_prev_tier, v_tier,
      jsonb_build_object('host',p_host,'pct',p_used_pct,'avail',COALESCE(p_avail_h,'?')));
  END IF;

  -- Recovery dispatch (prioridade sobre alert)
  IF v_recovery AND p_persist THEN
    PERFORM ops.recover_tier(
      p_host, v_prev_tier, v_tier, p_used_pct, COALESCE(p_avail_h,'?'));
  -- Alert dispatch (apenas tiers acima de INFO)
  ELSIF v_tier NOT IN ('OK','INFO') AND p_persist THEN
    IF v_transitioned OR ops.should_alert(v_tier, p_host) THEN
      v_should_alert := true;
      PERFORM ops.dispatch_disk_alert(
        v_tier, p_host, p_used_pct, COALESCE(p_avail_h,'?'));
    END IF;
  END IF;

  -- Hi-res sampling para WARN+ (>=80%)
  IF p_used_pct >= 80 AND p_persist THEN
    PERFORM ops.ingest_host_disk_hires(p_used_pct);
  END IF;

  RETURN jsonb_build_object(
    'ok',          true,
    'tier',        v_tier,
    'prev_tier',   v_prev_tier,
    'status',      v_status,
    'used_pct',    p_used_pct,
    'transitioned',v_transitioned,
    'recovery',    v_recovery,     -- sempre boolean, nunca NULL
    'alerted',     v_should_alert,
    'persisted',   p_persist
  );
END;
$$;


--
-- Name: ingest_host_disk_hires(integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.ingest_host_disk_hires(p_pct integer) RETURNS void
    LANGUAGE sql
    AS $$
  INSERT INTO ops.host_disk_hires_log (pct, ts) VALUES (p_pct, now());
$$;


--
-- Name: prune_disk_baseline(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.prune_disk_baseline() RETURNS void
    LANGUAGE sql
    AS $$
  DELETE FROM ops.disk_baseline WHERE ts < now() - interval '90 days';
$$;


--
-- Name: prune_disk_hires(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.prune_disk_hires() RETURNS void
    LANGUAGE sql
    AS $$
  DELETE FROM ops.host_disk_hires_log WHERE ts < now() - interval '14 days';
$$;


--
-- Name: recover_tier(text, text, text, integer, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.recover_tier(p_host text, p_tier_from text, p_tier_to text, p_pct integer, p_avail text) RETURNS void
    LANGUAGE sql
    AS $$
  SELECT ops.dispatch_disk_recovery(p_tier_from, p_tier_to, p_host, p_pct, p_avail);
$$;


