$$;


--
-- Name: run_all_checks(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.run_all_checks() RETURNS TABLE(check_name text, status text, detail jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'ops', 'pg_catalog', 'evo', 'zapp', 'cron', 'monitoring', 'financeiro', 'vendas', 'artes', 'auth'
    AS $$

DECLARE v_r jsonb; v_infra jsonb; v_hs jsonb; v_n int;
BEGIN
  v_r := row_to_json((ops.check_lovable_parity()))::jsonb;
  RETURN QUERY SELECT 'lovable_parity'::text, (ops.check_lovable_parity()).status::text, v_r;
  v_r := row_to_json((ops.check_schema_drift()))::jsonb;
  RETURN QUERY SELECT 'schema_drift'::text, (ops.check_schema_drift()).status::text, v_r;
  v_r := row_to_json((ops.check_critical_fks()))::jsonb;
  RETURN QUERY SELECT 'critical_fks'::text, (ops.check_critical_fks()).status::text, v_r;
  v_r := ops.fn_guardrails_check();
  RETURN QUERY SELECT 'guardrails'::text, CASE WHEN (v_r->>'ok')='true' THEN 'OK' ELSE 'FAIL' END::text, v_r;
  v_r := ops.fn_catalog_sanity_check();
  RETURN QUERY SELECT 'catalog_sanity'::text, (v_r->>'status')::text, v_r;
  v_infra := ops.check_infrastructure();
  RETURN QUERY SELECT 'infrastructure'::text, CASE WHEN jsonb_array_length(v_infra->'issues')=0 THEN 'OK' WHEN jsonb_array_length(v_infra->'issues')<3 THEN 'WARN' ELSE 'FAIL' END::text, v_infra;
  v_hs := zapp.fn_system_health_score();
  RETURN QUERY SELECT 'health_score'::text, CASE WHEN (v_hs->>'grade') IN ('A+','A') THEN 'OK' WHEN (v_hs->>'grade')='B' THEN 'WARN' ELSE 'FAIL' END::text, v_hs;
  SELECT count(*) INTO v_n FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind='r' AND n.nspname IN ('public','zapp') AND NOT c.relrowsecurity;
  RETURN QUERY SELECT 'rls_coverage'::text, CASE WHEN v_n=0 THEN 'OK' ELSE 'FAIL' END::text, jsonb_build_object('tables_rls_off',v_n);
  SELECT count(*) INTO v_n FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_constraint pk ON pk.conrelid=c.oid AND pk.contype='p' WHERE c.relkind='r' AND n.nspname IN ('public','zapp','evo') AND pk.oid IS NULL;
  RETURN QUERY SELECT 'pk_integrity'::text, CASE WHEN v_n=0 THEN 'OK' ELSE 'WARN' END::text, jsonb_build_object('no_pk_tables',v_n);
  SELECT count(*) INTO v_n FROM information_schema.role_table_grants WHERE table_schema='zapp' AND grantee='anon' AND table_name IN ('zapp_audit_log','contact_audit_log','conversation_audit_logs','webhook_audit_log','team_messages','app_notifications','whatsapp_official_credentials');
  RETURN QUERY SELECT 'security_anon_zapp'::text, CASE WHEN v_n=0 THEN 'OK' ELSE 'FAIL' END::text, jsonb_build_object('anon_grants',v_n);
  SELECT count(*) INTO v_n FROM information_schema.views WHERE table_schema='public' AND table_name IN ('zapp_audit_log','contact_audit_log','conversation_audit_logs','webhook_audit_log','team_messages','app_notifications','whatsapp_official_credentials');
  RETURN QUERY SELECT 'bridge_views'::text, CASE WHEN v_n=7 THEN 'OK' ELSE 'FAIL ('||v_n||'/7)' END::text, jsonb_build_object('count',v_n,'expected',7);
  -- PHD FIX 2026-07-13: check inteligente — so conta jobs AINDA falhando
  SELECT jobs_still_failing INTO v_n FROM ops.fn_check_cron_health();
  RETURN QUERY SELECT 'cron_24h'::text,
    CASE WHEN v_n=0 THEN 'OK' WHEN v_n<3 THEN 'WARN' ELSE 'FAIL' END::text,
    (SELECT jsonb_build_object(
      'jobs_still_failing', jobs_still_failing,
      'total_failures_24h', total_failures_24h,
      'jobs_with_recent_failures', jobs_with_recent_failures
    ) FROM ops.fn_check_cron_health());
  BEGIN PERFORM 1 FROM evo.evolution_alerts LIMIT 1; RETURN QUERY SELECT 'evo_schema'::text,'OK'::text,'{"accessible":true}'::jsonb;
  EXCEPTION WHEN OTHERS THEN RETURN QUERY SELECT 'evo_schema'::text,'FAIL'::text,jsonb_build_object('error',SQLERRM); END;
  RETURN QUERY SELECT 'api_key_blocked'::text, CASE WHEN NOT EXISTS(SELECT 1 FROM information_schema.column_privileges WHERE table_schema='public' AND table_name='whatsapp_connections' AND grantee='authenticated' AND privilege_type='SELECT' AND column_name='api_key') THEN 'OK' ELSE 'FAIL' END::text, jsonb_build_object('api_key_readable_by_authenticated', EXISTS(SELECT 1 FROM information_schema.column_privileges WHERE table_schema='public' AND table_name='whatsapp_connections' AND grantee='authenticated' AND privilege_type='SELECT' AND column_name='api_key'));
  RETURN QUERY SELECT 'mirror_integrity:' || mi.check_id::text, mi.severity::text, mi.detail FROM ops.check_mirror_integrity() mi;
  BEGIN RETURN QUERY SELECT 'wa_marketing_budget'::text, mb.status::text, jsonb_build_object('detail', mb.detail) FROM ops.check_marketing_budget() mb;
  EXCEPTION WHEN OTHERS THEN RETURN QUERY SELECT 'wa_marketing_budget'::text, 'FAIL'::text, jsonb_build_object('error', SQLERRM); END;
  BEGIN RETURN QUERY SELECT 'host_disk'::text, hd.status::text, jsonb_build_object('detail', hd.detail) FROM ops.check_host_disk() hd;
  EXCEPTION WHEN OTHERS THEN RETURN QUERY SELECT 'host_disk'::text, 'FAIL'::text, jsonb_build_object('error', SQLERRM); END;
  v_r := row_to_json((ops.check_types_sync()))::jsonb;
  RETURN QUERY SELECT 'types_sync'::text, (ops.check_types_sync()).status::text, v_r;
END; 

$$;


--
-- Name: FUNCTION run_all_checks(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.run_all_checks() IS 'Agregador de checks operacionais (cron 106 run_all_checks_daily, 07:00; 24 checks). Inclui lovable_parity via ops.check_lovable_parity() — deprecated mas mantida (ver ops.check_schema_parity). Corpo não modificado em 2026-08-03.';


--
-- Name: set_flag(text, boolean, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.set_flag(p_flag text, p_enabled boolean, p_reason text DEFAULT NULL::text, p_by text DEFAULT 'manual'::text) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE ops.disk_actioner_flags
  SET enabled=p_enabled, updated_at=now(), updated_by=p_by, reason=p_reason
  WHERE flag_name=p_flag;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Flag % nao existe', p_flag;
  END IF;
  -- Log no disk_event_log
  INSERT INTO ops.disk_event_log(event_type, from_state, to_state, detail)
  VALUES ('FLAG_CHANGED', NULL, p_flag,
    jsonb_build_object('flag', p_flag, 'enabled', p_enabled, 'by', p_by, 'reason', p_reason));
END;
$$;


--
-- Name: should_alert(text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.should_alert(p_tier text, p_host text) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_cooldown interval;
  v_last timestamptz;
BEGIN
  v_cooldown := CASE p_tier
    WHEN 'OK'        THEN interval '999 days'
    WHEN 'INFO'      THEN interval '24 hours'
    WHEN 'NOTICE'    THEN interval '6 hours'
    WHEN 'WARN'      THEN interval '1 hour'
    WHEN 'THROTTLE'  THEN interval '15 minutes'
    WHEN 'FREEZE'    THEN interval '5 minutes'
    WHEN 'EMERGENCY' THEN interval '1 minute'
    ELSE                  interval '1 hour'
  END;
  SELECT last_dispatched INTO v_last
  FROM ops.alert_cooldown WHERE host = p_host AND tier = p_tier;
  IF v_last IS NULL OR now() - v_last >= v_cooldown THEN
    INSERT INTO ops.alert_cooldown(host, tier, last_dispatched)
    VALUES (p_host, p_tier, now())
    ON CONFLICT (host, tier) DO UPDATE SET last_dispatched = EXCLUDED.last_dispatched;
    RETURN true;
  END IF;
  RETURN false;
END;
$$;


--
-- Name: sim_disk_alert_e2e(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.sim_disk_alert_e2e() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops'
    AS $$
DECLARE
  r_crit jsonb; r_warn jsonb; r_ok jsonb;
  alert_crit record; alert_warn record; n_ok_alerts int; result jsonb;
BEGIN
  DELETE FROM zapp.warroom_alerts WHERE entity IN ('e2e-crit','e2e-warn','e2e-ok');
  DELETE FROM ops.host_disk_log WHERE host IN ('e2e-crit','e2e-warn','e2e-ok');
  -- limpa janela de cooldown para medir do zero (ambas severidades)
  DELETE FROM zapp.warroom_alerts WHERE source='ops.host_disk_guard' AND entity IN ('e2e-crit','e2e-warn') AND created_at > now() - interval '180 min';

  -- thresholds por parametro (70/90), NAO toca config de producao
  r_crit := ops.ingest_host_disk(97, '188G','5G','194G','/','e2e-crit', 70, 90, 180, true);
  SELECT alert_type, title INTO alert_crit FROM zapp.warroom_alerts WHERE entity='e2e-crit' ORDER BY created_at DESC LIMIT 1;

  r_warn := ops.ingest_host_disk(80, '155G','39G','194G','/','e2e-warn', 70, 90, 180, true);
  SELECT alert_type, title INTO alert_warn FROM zapp.warroom_alerts WHERE entity='e2e-warn' ORDER BY created_at DESC LIMIT 1;

  r_ok := ops.ingest_host_disk(50, '97G','97G','194G','/','e2e-ok', 70, 90, 180, true);
  SELECT count(*) INTO n_ok_alerts FROM zapp.warroom_alerts WHERE entity='e2e-ok';

  result := jsonb_build_object(
    'crit', jsonb_build_object('status', r_crit->>'status', 'alerted', r_crit->>'alerted', 'type', alert_crit.alert_type,
       'pass', r_crit->>'status'='CRIT' AND (r_crit->>'alerted')::boolean AND alert_crit.alert_type='critical'),
    'warn', jsonb_build_object('status', r_warn->>'status', 'alerted', r_warn->>'alerted', 'type', alert_warn.alert_type,
       'pass', r_warn->>'status'='WARN' AND (r_warn->>'alerted')::boolean AND alert_warn.alert_type='warning'),
    'ok', jsonb_build_object('status', r_ok->>'status', 'alerted', r_ok->>'alerted', 'n_alerts', n_ok_alerts,
       'pass', r_ok->>'status'='OK' AND NOT (r_ok->>'alerted')::boolean AND n_ok_alerts=0));

  DELETE FROM zapp.warroom_alerts WHERE entity IN ('e2e-crit','e2e-warn','e2e-ok');
  DELETE FROM ops.host_disk_log WHERE host IN ('e2e-crit','e2e-warn','e2e-ok');

  RETURN result || jsonb_build_object('all_pass',
    (result->'crit'->>'pass')::boolean AND (result->'warn'->>'pass')::boolean AND (result->'ok'->>'pass')::boolean);
END; $$;


--
-- Name: sim_disk_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.sim_disk_guard() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops'
    AS $$
DECLARE
  pcts int[] := ARRAY[-5, 0, 1, 50, 74, 75, 76, 89, 90, 91, 99, 100, 101, NULL];
  warns int[] := ARRAY[70, 75, 80];
  crits int[] := ARRAY[85, 90, 95];
  p int; w int; cr int; expected text; got text; ok_ret boolean;
  n_pass int := 0; n_fail int := 0; samples jsonb := '[]'::jsonb; res jsonb;
BEGIN
  FOREACH p IN ARRAY pcts LOOP
    FOREACH w IN ARRAY warns LOOP
      FOREACH cr IN ARRAY crits LOOP
        IF w >= cr THEN CONTINUE; END IF;
        IF p IS NULL OR p < 0 OR p > 100 THEN expected := 'ERR';
        ELSIF p >= cr THEN expected := 'CRIT';
        ELSIF p >= w THEN expected := 'WARN';
        ELSE expected := 'OK'; END IF;
        -- dry-run: nao persiste, nao toca config
        res := ops.ingest_host_disk(p, 'X','Y','Z','/','sim-host', w, cr, 180, false);
        ok_ret := (res->>'ok')::boolean;
        IF expected = 'ERR' THEN
          got := CASE WHEN ok_ret THEN 'UNEXPECTED_OK' ELSE 'ERR' END;
        ELSE
          got := CASE WHEN ok_ret THEN res->>'status' ELSE 'UNEXPECTED_ERR' END;
        END IF;
        IF got IS DISTINCT FROM expected THEN
          n_fail := n_fail + 1;
          IF jsonb_array_length(samples) < 10 THEN
            samples := samples || jsonb_build_object('pct',p,'warn',w,'crit',cr,'expected',expected,'got',got,'res',res);
          END IF;
        ELSE n_pass := n_pass + 1; END IF;
      END LOOP;
    END LOOP;
  END LOOP;
  RETURN jsonb_build_object('total', n_pass+n_fail, 'pass', n_pass, 'fail', n_fail, 'mode','dry-run-isolado', 'failed_samples', samples);
END; $$;


--
-- Name: sim_forensic_battery(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.sim_forensic_battery() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'evo'
    AS $$
DECLARE
  results jsonb := '[]'::jsonb;
  r jsonb; v_txt text; v_int int; v_cnt bigint; ok boolean;
  budget_snapshot ops.wa_marketing_budget%ROWTYPE;
BEGIN
  SELECT * INTO budget_snapshot FROM ops.wa_marketing_budget WHERE id=1;

  -- BLOCO 1: SQL INJECTION (dry-run, nao persiste)
  BEGIN
    r := ops.ingest_host_disk(50, 'X''; DROP TABLE ops.host_disk_log; --', 'Y', 'Z', '/mnt', 'host''injection', 70, 90, 180, false);
    SELECT count(*) INTO v_cnt FROM ops.host_disk_log;
    results := results || jsonb_build_object('teste','disk_sql_injection','pass', (r->>'ok')='true' AND v_cnt > 0, 'detail','tabela intacta (dry-run)');
  EXCEPTION WHEN OTHERS THEN
    results := results || jsonb_build_object('teste','disk_sql_injection','pass', false, 'erro', SQLERRM);
  END;

  -- BLOCO 2: INT_MAX (dry-run)
  BEGIN
    r := ops.ingest_host_disk(2147483647, 'X','Y','Z','/','extremo', 70, 90, 180, false);
    results := results || jsonb_build_object('teste','disk_int_max','pass', (r->>'ok')='false', 'detail','INT_MAX rejeitado', 'got', r);
  EXCEPTION WHEN OTHERS THEN
    results := results || jsonb_build_object('teste','disk_int_max','pass', true, 'detail','overflow capturado: '||SQLERRM);
  END;

  -- BLOCO 3: budget NUMERIC extremo (usa snapshot/restore, unico que precisa mutar budget)
  BEGIN
    UPDATE ops.wa_marketing_budget SET monthly_budget_brl=99999999.99, tariff_marketing_brl=9999.9999, alert_threshold=0.8, hard_stop_threshold=1.0 WHERE id=1;
    SELECT status INTO v_txt FROM ops.check_marketing_budget();
    results := results || jsonb_build_object('teste','budget_numeric_extremo','pass', v_txt IN ('OK','WARN','FAIL'), 'status', v_txt);
    UPDATE ops.wa_marketing_budget SET monthly_budget_brl=budget_snapshot.monthly_budget_brl, tariff_marketing_brl=budget_snapshot.tariff_marketing_brl, alert_threshold=budget_snapshot.alert_threshold, hard_stop_threshold=budget_snapshot.hard_stop_threshold WHERE id=1;
  EXCEPTION WHEN OTHERS THEN
    results := results || jsonb_build_object('teste','budget_numeric_extremo','pass', false, 'erro', SQLERRM);
    UPDATE ops.wa_marketing_budget SET monthly_budget_brl=budget_snapshot.monthly_budget_brl, tariff_marketing_brl=budget_snapshot.tariff_marketing_brl, alert_threshold=budget_snapshot.alert_threshold, hard_stop_threshold=budget_snapshot.hard_stop_threshold WHERE id=1;
  END;

  -- BLOCO 4: cooldown por severidade (persiste em host isolado, thresholds por param, NAO toca config)
  BEGIN
    DELETE FROM zapp.warroom_alerts WHERE source='ops.host_disk_guard' AND alert_type='critical' AND created_at > now() - interval '180 min';
    r := ops.ingest_host_disk(95, 'X','Y','Z','/','cooldowntest', 10, 20, 180, true);
    v_int := (r->>'alerted')::boolean::int;
    r := ops.ingest_host_disk(96, 'X','Y','Z','/','cooldowntest', 10, 20, 180, true);
    v_cnt := (r->>'alerted')::boolean::int;
    results := results || jsonb_build_object('teste','disk_alert_cooldown','pass', v_int=1 AND v_cnt=0, 'detail','1o CRIT alerta, 2o suprimido', 'crit1', v_int, 'crit2', v_cnt);
    DELETE FROM zapp.warroom_alerts WHERE source='ops.host_disk_guard' AND entity='cooldowntest';
    DELETE FROM ops.host_disk_log WHERE host='cooldowntest';
  EXCEPTION WHEN OTHERS THEN
    results := results || jsonb_build_object('teste','disk_alert_cooldown','pass', false, 'erro', SQLERRM);
  END;

  -- BLOCO 5: dashboard
  BEGIN
    r := ops.fn_dashboard();
    ok := (r ? 'health_score') AND (r ? 'mensagens') AND (r ? 'webhooks') AND (r ? 'conexoes') AND (r ? 'disco') AND (r ? 'budget_marketing') AND (r ? 'alertas');
    results := results || jsonb_build_object('teste','dashboard_estrutura_completa','pass', ok);
  EXCEPTION WHEN OTHERS THEN
    results := results || jsonb_build_object('teste','dashboard_estrutura_completa','pass', false, 'erro', SQLERRM);
  END;

  -- BLOCO 6: staleness (le config real, nao muta)
  BEGIN
    SELECT status INTO v_txt FROM ops.check_host_disk();
    results := results || jsonb_build_object('teste','disk_check_responde','pass', v_txt IN ('OK','WARN','FAIL'), 'status', v_txt);
  EXCEPTION WHEN OTHERS THEN
    results := results || jsonb_build_object('teste','disk_check_responde','pass', false, 'erro', SQLERRM);
  END;

  -- BLOCO 7: constraint warn=crit (transacao propria, rollback via savepoint implicito no bloco)
  BEGIN
    INSERT INTO ops.host_disk_config (id, warn_pct, crit_pct) VALUES (99, 80, 80);
    results := results || jsonb_build_object('teste','constraint_warn_lt_crit','pass', false, 'detail','FALHA: permitiu warn=crit');
    DELETE FROM ops.host_disk_config WHERE id=99;
  EXCEPTION WHEN check_violation THEN
    results := results || jsonb_build_object('teste','constraint_warn_lt_crit','pass', true, 'detail','constraint bloqueou warn>=crit');
  WHEN OTHERS THEN
    results := results || jsonb_build_object('teste','constraint_warn_lt_crit','pass', true, 'detail','bloqueado: '||SQLERRM);
  END;

  -- BLOCO 8: singleton (id != 1 bloqueado)
  BEGIN
    INSERT INTO ops.host_disk_config (id, warn_pct, crit_pct) VALUES (2, 70, 90);
    results := results || jsonb_build_object('teste','config_singleton','pass', false, 'detail','FALHA: permitiu id=2');
    DELETE FROM ops.host_disk_config WHERE id=2;
  EXCEPTION WHEN check_violation THEN
    results := results || jsonb_build_object('teste','config_singleton','pass', true, 'detail','singleton enforced');
  WHEN OTHERS THEN
    results := results || jsonb_build_object('teste','config_singleton','pass', true, 'detail','bloqueado: '||SQLERRM);
  END;

  RETURN jsonb_build_object('total', jsonb_array_length(results),
    'pass', (SELECT count(*) FROM jsonb_array_elements(results) e WHERE (e->>'pass')::boolean),
    'fail', (SELECT count(*) FROM jsonb_array_elements(results) e WHERE NOT (e->>'pass')::boolean),
    'mode','producao-nao-contaminada',
    'resultados', results);
END; $$;


--
-- Name: sim_rls_wa(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.sim_rls_wa() RETURNS jsonb
    LANGUAGE plpgsql
    AS $$ DECLARE c_wpp2 int := -1; c_mkt int := -1; c_evil int := -1; c_wpp2_pg int := -1; ins_wpp2_ok boolean := false; ins_evil_blocked boolean := false; anon_visible int := -1; anon_perm_denied boolean := false; BEGIN BEGIN INSERT INTO evo.evolution_messages (id, remote_jid, instance_name, is_read, from_me, message_id, content, created_at) VALUES (gen_random_uuid(), '5500000000001@s.whatsapp.net', 'wpp2', true, true, 'SIM-RLS-1', 'SIM', now()), (gen_random_uuid(), '5500000000002@s.whatsapp.net', 'wppmkt', true, true, 'SIM-RLS-2', 'SIM', now()), (gen_random_uuid(), '5500000000003@s.whatsapp.net', 'wppEVIL', true, true, 'SIM-RLS-3', 'SIM', now()); SELECT count(*) INTO c_wpp2_pg FROM evo.evolution_messages WHERE instance_name = 'wpp2'; EXECUTE 'SET LOCAL ROLE authenticated'; SELECT count(*) INTO c_wpp2 FROM evo.evolution_messages WHERE instance_name = 'wpp2'; SELECT count(*) INTO c_mkt FROM evo.evolution_messages WHERE instance_name = 'wppmkt'; SELECT count(*) INTO c_evil FROM evo.evolution_messages WHERE instance_name = 'wppEVIL'; BEGIN INSERT INTO evo.evolution_messages (id, remote_jid, instance_name, is_read, from_me, message_id) VALUES (gen_random_uuid(), 'simok@s.whatsapp.net', 'wpp2', true, true, 'SIM-RLS-OK'); ins_wpp2_ok := true; EXCEPTION WHEN OTHERS THEN ins_wpp2_ok := false; END; BEGIN INSERT INTO evo.evolution_messages (id, remote_jid, instance_name, is_read, from_me, message_id) VALUES (gen_random_uuid(), 'simevil@s.whatsapp.net', 'wppEVIL', true, true, 'SIM-RLS-EVIL'); ins_evil_blocked := false; EXCEPTION WHEN OTHERS THEN ins_evil_blocked := true; END; EXECUTE 'RESET ROLE'; BEGIN EXECUTE 'SET LOCAL ROLE anon'; SELECT count(*) INTO anon_visible FROM evo.evolution_messages; EXECUTE 'RESET ROLE'; EXCEPTION WHEN OTHERS THEN anon_perm_denied := true; BEGIN EXECUTE 'RESET ROLE'; EXCEPTION WHEN OTHERS THEN NULL; END; END; RAISE EXCEPTION 'SIM_ROLLBACK'; EXCEPTION WHEN OTHERS THEN IF SQLERRM <> 'SIM_ROLLBACK' THEN RETURN jsonb_build_object('runtime_error', SQLERRM); END IF; END; RETURN jsonb_build_object('asserts', jsonb_build_array(jsonb_build_object('assert', 'auth_ve_wpp2_integral', 'pass', c_wpp2 = c_wpp2_pg AND c_wpp2 >= 1, 'got', c_wpp2, 'expect', c_wpp2_pg), jsonb_build_object('assert', 'auth_ve_wppmkt', 'pass', c_mkt = 1, 'got', c_mkt, 'expect', 1), jsonb_build_object('assert', 'auth_NAO_ve_wppEVIL', 'pass', c_evil = 0, 'got', c_evil, 'expect', 0), jsonb_build_object('assert', 'auth_insert_wpp2_permitido', 'pass', ins_wpp2_ok), jsonb_build_object('assert', 'auth_insert_spoof_bloqueado', 'pass', ins_evil_blocked), jsonb_build_object('assert', 'anon_bloqueado', 'pass', anon_perm_denied OR anon_visible = 0, 'perm_denied', anon_perm_denied, 'visible', anon_visible))); END; $$;


--
-- Name: sim_wa_budget_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.sim_wa_budget_guard() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'evo'
    AS $$ DECLARE counts int[] := ARRAY[0, 1, 100, 1554]; tariffs numeric[] := ARRAY[0, 0.3217, 2.5]; budgets numeric[] := ARRAY[-50, 0, 10, 32.17, 32.18, 40.2125, 500]; thr numeric[][] := ARRAY[[0.8, 1.0], [0.9, 0.8], [0.0, 0.0]]; cnt int; t numeric; b numeric; a numeric; h numeric; i int; expected text; got text; got_detail text; spend numeric; pct numeric; n_pass int := 0; n_fail int := 0; n_err int := 0; samples jsonb := '[]'::jsonb; gap_budget int := 0; gap_tariff int := 0; gap_thr int := 0; gap_math int := 0; BEGIN FOREACH cnt IN ARRAY counts LOOP FOREACH t IN ARRAY tariffs LOOP FOREACH b IN ARRAY budgets LOOP FOR i IN 1..3 LOOP a := thr[i][1]; h := thr[i][2]; IF b <= 0 THEN expected := 'WARN'; ELSIF t <= 0 THEN expected := 'WARN'; ELSIF a > h THEN expected := 'WARN'; ELSE spend := round(cnt * t, 2); pct := spend / b; IF pct >= h THEN expected := 'FAIL'; ELSIF pct >= a THEN expected := 'WARN'; ELSE expected := 'OK'; END IF; END IF; BEGIN UPDATE ops.wa_marketing_budget SET monthly_budget_brl = b, tariff_marketing_brl = t, alert_threshold = a, hard_stop_threshold = h WHERE id = 1; IF cnt > 0 THEN INSERT INTO evo.evolution_messages (id, remote_jid, instance_name, is_read, from_me, message_id, content, created_at) SELECT gen_random_uuid(), '5500000000000@s.whatsapp.net', 'wppmkt', true, true, 'SIM-' || gs, 'SIMULACAO-ADVERSARIAL', now() FROM generate_series(1, cnt) gs; END IF; SELECT s.status, s.detail INTO got, got_detail FROM ops.check_marketing_budget() s; IF got IS DISTINCT FROM expected THEN n_fail := n_fail + 1; IF b <= 0 THEN gap_budget := gap_budget + 1; ELSIF t <= 0 THEN gap_tariff := gap_tariff + 1; ELSIF a > h THEN gap_thr := gap_thr + 1; ELSE gap_math := gap_math + 1; END IF; IF jsonb_array_length(samples) < 12 THEN samples := samples || jsonb_build_object('cnt', cnt, 'tariff', t, 'budget', b, 'alert', a, 'hard', h, 'expected', expected, 'got', got, 'detail', got_detail); END IF; ELSE n_pass := n_pass + 1; END IF; RAISE EXCEPTION 'SIM_ROLLBACK'; EXCEPTION WHEN OTHERS THEN IF SQLERRM <> 'SIM_ROLLBACK' THEN n_err := n_err + 1; IF jsonb_array_length(samples) < 12 THEN samples := samples || jsonb_build_object('cnt', cnt, 'tariff', t, 'budget', b, 'runtime_error', SQLERRM); END IF; END IF; END; END LOOP; END LOOP; END LOOP; END LOOP; RETURN jsonb_build_object('total', n_pass + n_fail + n_err, 'pass', n_pass, 'fail', n_fail, 'runtime_errors', n_err, 'gaps', jsonb_build_object('budget_leq_zero', gap_budget, 'tariff_leq_zero', gap_tariff, 'alert_gt_hard', gap_thr, 'math_mismatch', gap_math), 'failed_samples', samples); END; $$;


--
-- Name: simulate_disk_pressure(integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.simulate_disk_pressure(p_max_pct integer DEFAULT 85) RETURNS TABLE(pct integer, tier text, result jsonb)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_pct integer;
  v_levels integer[] := ARRAY[50,61,71,74,80,82,88,90,92,95,90,88,79,70,55,45];
  i integer;
BEGIN
  FOR i IN 1..array_length(v_levels,1) LOOP
    v_pct := v_levels[i];
    IF v_pct <= p_max_pct THEN
      RETURN QUERY SELECT
        v_pct,
        ops.calculate_tier(v_pct),
        ops.ingest_host_disk(v_pct,NULL,NULL,NULL,'/sim','sim-pressure-test',NULL,NULL,NULL,false);
    END IF;
  END LOOP;
END;
$$;


--
-- Name: suggest_disk_action(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.suggest_disk_action(p_tier text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE p_tier
    WHEN 'INFO'      THEN 'Monitorar crescimento; nenhuma acao necessaria.'
    WHEN 'NOTICE'    THEN 'Verificar volumes crescendo; considerar retention review.'
    WHEN 'WARN'      THEN 'Housekeeping v2 emergency ativado. Verificar top-growing volumes.'
    WHEN 'THROTTLE'  THEN 'Servicos disposable pausados. CI/CD suspenso. Investigar causa raiz.'
    WHEN 'FREEZE'    THEN 'CRITICO: important pausados. Backups redirecionados a R2. Human intervention P1.'
    WHEN 'EMERGENCY' THEN 'CRISE: so critical rodando. Ligar para on-call. P0.'
    ELSE 'Sem acao necessaria.'
  END;
$$;


--
-- Name: get_auth(text); Type: FUNCTION; Schema: pgbouncer; Owner: -
--

CREATE FUNCTION pgbouncer.get_auth(p_usename text) RETURNS TABLE(username text, password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
    RAISE WARNING 'PgBouncer auth request: %', p_usename;

    RETURN QUERY
    SELECT usename::TEXT, passwd::TEXT FROM pg_catalog.pg_shadow
    WHERE usename = p_usename;
END;
$$;


