    AS $$
BEGIN
  INSERT INTO evo.evolution_logpatch_audit
    (container_id, force_update, patch_version, t1_ok, t2_ok, t3_ok, t4_ok, t5_ok,
     patched_size_bytes, boot_at, verified_at, notes, instance_name, booted_at,
