--
-- Name: get_contact_intelligence_by_phone(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_contact_intelligence_by_phone(p_phone text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp, pg_catalog'
    AS $$
BEGIN
  -- [SEC 2026-08-01] Workspace isolation guard na camada publica
  -- service_role (auth.uid() IS NULL): acesso total (backend)
  -- authenticated: deve ter membership em algum workspace
  IF auth.uid() IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM zapp.workspace_members WHERE user_id = auth.uid()
    ) THEN
      RAISE EXCEPTION 'unauthorized: no workspace membership for this user'
        USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN zapp.get_contact_intelligence_by_phone(p_phone);
END;
$$;


