--
-- Name: rpc_app_bootstrap(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_app_bootstrap() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp, pg_catalog'
    AS $$
DECLARE
  v_user_id           uuid;
  v_profile           jsonb;
  v_roles             jsonb;
  v_perms             jsonb;
  v_role_perms        jsonb;
  v_settings          jsonb;
  v_departments       jsonb;
  v_notif_count       int := 0;
BEGIN
  -- auth.uid() = profiles.user_id (NOT profiles.id — they are different UUIDs)
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('error', 'not_authenticated');
  END IF;

  -- 1. Profile — FIX B1: WHERE user_id = v_user_id
  --             FIX B2: removed company_id (does not exist in zapp.profiles)
  --             Added: user_id, is_online, online_status, job_title, nickname
  SELECT to_jsonb(p) INTO v_profile
  FROM (
    SELECT id,
           user_id,
           name,
           email,
           avatar_url,
           is_active,
           is_online,
           role,
           department_id,
           phone,
           job_title,
           nickname,
           online_status,
           max_chats,
           can_download,
           permissions   AS profile_permissions,
           created_at,
           updated_at
    FROM zapp.profiles
    WHERE user_id = v_user_id  -- CORRECTED: auth.uid() = profiles.user_id
    LIMIT 1
  ) p;

  -- 2. User roles — FIX B3: explicit ::text cast on USER-DEFINED enum
  SELECT COALESCE(jsonb_agg(r.role::text ORDER BY r.role::text), '[]'::jsonb)
  INTO   v_roles
  FROM   zapp.user_roles r
  WHERE  r.user_id = v_user_id;

  -- 3. All permissions (quasi-static, ~5-10 rows)
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id',          p.id,
        'name',        p.name,
        'description', p.description,
        'category',    p.category
      )
      ORDER BY p.category, p.name
    ),
    '[]'::jsonb
  )
  INTO v_perms
  FROM zapp.permissions p;

  -- 4. Role→permission mapping — FIX B3: explicit ::text cast
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'role',          rp.role::text,
        'permission_id', rp.permission_id,
        'permission',    jsonb_build_object(
                           'id',          pm.id,
                           'name',        pm.name,
                           'description', pm.description,
                           'category',    pm.category
                         )
      )
    ),
    '[]'::jsonb
  )
  INTO v_role_perms
  FROM      zapp.role_permissions rp
  LEFT JOIN zapp.permissions pm ON pm.id = rp.permission_id;

  -- 5. Global settings (sorted by key)
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id',          gs.id,
        'key',         gs.key,
        'value',       gs.value,
        'description', gs.description
      )
      ORDER BY gs.key
    ),
    '[]'::jsonb
  )
  INTO v_settings
  FROM zapp.global_settings gs;

  -- 6. Active departments
  SELECT COALESCE(
    jsonb_agg(to_jsonb(d) ORDER BY d.name),
    '[]'::jsonb
  )
  INTO v_departments
  FROM zapp.departments d
  WHERE d.is_active = true;

  -- 7. Unread notifications count
  -- app_notifications.user_id = auth.uid() — CONFIRMED via join verification
  SELECT COALESCE(count(*), 0)
  INTO   v_notif_count
  FROM   zapp.app_notifications n
  WHERE  n.user_id  = v_user_id
    AND  n.is_read  = false;

  RETURN jsonb_build_object(
    'profile',              COALESCE(v_profile, 'null'::jsonb),
    'roles',                v_roles,
    'permissions',          v_perms,
    'role_permissions',     v_role_perms,
    'global_settings',      v_settings,
    'departments',          v_departments,
    'unread_notifications', v_notif_count,
    'fetched_at',           now()::text
  );
END;
$$;


--
-- Name: rpc_dashboard_init(uuid, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_dashboard_init(p_agent_id uuid DEFAULT NULL::uuid, p_queue_id uuid DEFAULT NULL::uuid, p_date_from timestamp with time zone DEFAULT date_trunc('day'::text, now()), p_date_to timestamp with time zone DEFAULT (date_trunc('day'::text, now()) + '1 day'::interval)) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp, pg_catalog'
    AS $$
DECLARE
  v_user_id       uuid;
  v_online_agents int := 0;
  v_total_agents  int := 0;
  v_contacts      jsonb;
  v_queues        jsonb;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('error', 'not_authenticated');
  END IF;

  -- 1. Agent stats — is_active = account enabled (consistent with original hook)
  SELECT
    count(*) FILTER (WHERE p.is_active = true),
    count(*)
  INTO v_online_agents, v_total_agents
  FROM zapp.profiles p
  WHERE (p_agent_id IS NULL OR p.id = p_agent_id OR p.user_id = p_agent_id);

  -- 2. Contacts for date range
  --    FIX B4: contacts.assigned_to is varchar — cast p_agent_id to text for comparison
  --    Safety: LIMIT 1000 prevents memory blow-up on wide date ranges
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id',          c.id,
        'name',        c.name,
        'phone',       c.phone,
        'assigned_to', c.assigned_to,
        'queue_id',    c.queue_id,
        'updated_at',  c.updated_at
      )
      ORDER BY c.updated_at DESC
    ),
    '[]'::jsonb
  )
  INTO v_contacts
  FROM (
    SELECT id, name, phone, assigned_to, queue_id, updated_at
    FROM   zapp.contacts c
    WHERE  c.updated_at >= p_date_from
      AND  c.updated_at <  p_date_to
      AND  (p_queue_id  IS NULL OR c.queue_id  = p_queue_id)
      AND  (p_agent_id  IS NULL OR c.assigned_to = p_agent_id::text)
    ORDER BY c.updated_at DESC
    LIMIT 1000  -- safety valve: prevents OOM on wide date windows
  ) c;

  -- 3. Queues with member + waiting stats
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id',            q.id,
        'name',          q.name,
        'color',         q.color,
        'total_members', q.total_members,
        'online_members',q.online_members,
        'waiting_count', q.waiting_count
      )
      ORDER BY q.name
    ),
    '[]'::jsonb
  )
  INTO v_queues
  FROM (
    SELECT
      qu.id,
      qu.name,
      qu.color,
      count(qm.profile_id)                                              AS total_members,
      count(qm.profile_id) FILTER (WHERE pr.is_active = true)          AS online_members,
      (
        SELECT count(*)
        FROM   zapp.contacts ct
        WHERE  ct.queue_id    = qu.id
          AND  ct.assigned_to IS NULL
          AND  ct.updated_at >= p_date_from
          AND  ct.updated_at <  p_date_to
      )                                                                 AS waiting_count
    FROM      zapp.queues       qu
    LEFT JOIN zapp.queue_members qm ON qm.queue_id   = qu.id
    LEFT JOIN zapp.profiles      pr ON pr.id          = qm.profile_id
    WHERE (p_queue_id IS NULL OR qu.id = p_queue_id)
    GROUP BY qu.id, qu.name, qu.color
  ) q;

  RETURN jsonb_build_object(
    'agents',   jsonb_build_object(
                  'online', v_online_agents,
                  'total',  v_total_agents
                ),
    'contacts', v_contacts,
    'queues',   v_queues,
    'filters',  jsonb_build_object(
                  'date_from', p_date_from::text,
                  'date_to',   p_date_to::text,
                  'agent_id',  p_agent_id,
                  'queue_id',  p_queue_id
                ),
    'fetched_at', now()::text
  );
END;
$$;


