--
-- Name: rpc_email_cleanup_old_events(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_email_cleanup_old_events(p_retention_days integer DEFAULT 90) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
BEGIN
  -- GUARDA 1: NULL gera cutoff NULL -> no-op silencioso com ok=true (falso positivo)
  IF p_retention_days IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'retention_days_null',
      'hint', 'NULL gera cutoff NULL e a funcao alvo retornaria ok=true sem apagar nada.');
  END IF;

  -- GUARDA 2: valores < 1 geram cutoff no FUTURO -> DELETE WHERE created_at < futuro
  -- apagaria a TABELA INTEIRA. Confirmado por teste 2026-07-26: p=-1 gerou cutoff=amanha.
  IF p_retention_days < 1 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'retention_days_invalido',
      'valor_recebido', p_retention_days, 'minimo_permitido', 1,
      'hint', 'Valores <1 colocam o cutoff no futuro e apagariam todos os registros.');
  END IF;

  -- GUARDA 3: valores muito grandes causam timestamp out of range no PostgreSQL.
  -- Limite conservador: 36.500 dias = 100 anos. Confirmado por teste: 2147483647 -> crash.
  IF p_retention_days > 36500 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'retention_days_overflow',
      'valor_recebido', p_retention_days, 'maximo_permitido', 36500,
      'hint', 'Valores > 36500 (100 anos) causam timestamp out of range no PostgreSQL.');
  END IF;

  RETURN zapp.rpc_email_cleanup_old_events(p_retention_days);
END;
$$;


--
-- Name: FUNCTION rpc_email_cleanup_old_events(p_retention_days integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rpc_email_cleanup_old_events(p_retention_days integer) IS 'v3 2026-07-26. Backcompat wrapper -> zapp.rpc_email_cleanup_old_events. Destravar cron job 15 (owner=supabase_admin). Guardas: (1) NULL -> erro explicito; (2) <1 -> erro (cutoff no futuro = DELETE total); (3) >36500 -> erro (timestamp overflow confirmado por teste com 2147483647). Alcancavel por service_role.';


--
-- Name: rpc_get_contact(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_get_contact(p_contact_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;
  SELECT jsonb_build_object(
    'contact', to_jsonb(c.*),
    'deals', COALESCE((SELECT jsonb_agg(to_jsonb(d.*)) FROM evo.evolution_deals d WHERE d.contact_id=c.id),'[]'),
    'recent_messages', COALESCE((SELECT jsonb_agg(to_jsonb(m.*)) FROM (SELECT * FROM evo.evolution_messages WHERE contact_id=c.id ORDER BY created_at DESC LIMIT 20) m),'[]'),
    'tasks', COALESCE((SELECT jsonb_agg(to_jsonb(t.*)) FROM evo.evolution_tasks t WHERE t.contact_id=c.id AND t.status IN ('pending','in_progress')),'[]')
  ) INTO v_result
  FROM evo.evolution_contacts c WHERE c.id=p_contact_id;
  RETURN v_result;
END;
$$;


