CREATE TABLE evo.evolution_contacts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    remote_jid character varying(50) NOT NULL,
    phone_number text,
    push_name character varying(255),
    profile_picture_url text,
    full_name character varying(255),
    email character varying(255),
    company character varying(255),
    role_title character varying(100),
    lead_status character varying(50) DEFAULT 'novo'::character varying,
    lead_source character varying(50),
    lead_score integer DEFAULT 0,
    whatsapp_labels text[],
    tags text[],
    assigned_to character varying(100),
    first_contact_at timestamp with time zone,
    last_message_at timestamp with time zone,
    total_messages integer DEFAULT 0,
    total_purchases numeric(12,2) DEFAULT 0,
    notes text,
    instance_name character varying(100) DEFAULT 'wpp2'::character varying,
    raw_data jsonb,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    deleted_at timestamp with time zone,
    message_count integer DEFAULT 0 NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    pii_masked_at timestamp with time zone,
    merge_source_id uuid,
    dedup_hash text,
    lgpd_consent_at timestamp with time zone,
    lgpd_deletion_requested_at timestamp with time zone,
    lgpd_opt_out_at timestamp with time zone,
    lgpd_marketing_consent boolean DEFAULT false NOT NULL,
    lgpd_data_sharing boolean DEFAULT false NOT NULL,
    lgpd_profiling boolean DEFAULT false NOT NULL,
    lgpd_consent_channel text,
