    deleted_reason text,
    search_vector tsvector,
    first_name character varying(255),
    last_name character varying(255),
    nickname character varying(255),
    queue_id uuid
)
WITH (autovacuum_enabled='true', autovacuum_vacuum_cost_limit='4000', autovacuum_vacuum_cost_delay='1', autovacuum_freeze_max_age='50000000', autovacuum_vacuum_scale_factor='0.05', autovacuum_vacuum_threshold='1000', autovacuum_analyze_scale_factor='0.05', autovacuum_analyze_threshold='500');

ALTER TABLE ONLY evo.evolution_contacts REPLICA IDENTITY FULL;


