--

CREATE FUNCTION public.rpc_get_contact(p_remote_jid text, p_instance text DEFAULT NULL::text) RETURNS SETOF evo.evolution_contacts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;
  RETURN QUERY
    SELECT * FROM evo.evolution_contacts
    WHERE remote_jid = p_remote_jid
      AND (p_instance IS NULL OR instance_name = p_instance)
      AND deleted_at IS NULL
    ORDER BY updated_at DESC
    LIMIT 1;
END;
$$;


