--
-- Name: fn_atualizar_compra(text, text, numeric, numeric, numeric); Type: FUNCTION; Schema: vendas; Owner: -
--

CREATE FUNCTION vendas.fn_atualizar_compra(p_pedido text, p_fornecedor text DEFAULT NULL::text, p_qtd_compra numeric DEFAULT NULL::numeric, p_valor_compra_unid numeric DEFAULT NULL::numeric, p_valor_compra_total numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count INT;
  v_resultado JSONB;
  v_calc_total NUMERIC;
BEGIN
  -- Verificar quantas linhas têm esse pedido
  SELECT COUNT(*) INTO v_count
  FROM vendas.ordens_compra
  WHERE pedido = p_pedido AND excluido_em IS NULL;

  IF v_count = 0 THEN
    RETURN jsonb_build_object('status','not_found','pedido',p_pedido);
  END IF;

  IF v_count > 1 THEN
    RETURN jsonb_build_object(
      'status','duplicate',
      'pedido',p_pedido,
      'qtd_linhas',v_count,
      'ids',(SELECT jsonb_agg(id) FROM vendas.ordens_compra
             WHERE pedido = p_pedido AND excluido_em IS NULL)
    );
  END IF;

  -- Se total não veio mas qtd e unid vieram, calcula
  IF p_valor_compra_total IS NULL
     AND p_qtd_compra IS NOT NULL
     AND p_valor_compra_unid IS NOT NULL THEN
    v_calc_total := p_qtd_compra * p_valor_compra_unid;
  ELSE
    v_calc_total := p_valor_compra_total;
  END IF;

  -- UPDATE só dos campos enviados (COALESCE preserva o atual)
  UPDATE vendas.ordens_compra SET
    fornecedor = COALESCE(p_fornecedor, fornecedor),
    qtd_compra = COALESCE(p_qtd_compra, qtd_compra),
    valor_compra_unid = COALESCE(p_valor_compra_unid, valor_compra_unid),
    valor_compra_total = COALESCE(v_calc_total, valor_compra_total)
  WHERE pedido = p_pedido AND excluido_em IS NULL
  RETURNING jsonb_build_object(
    'status','ok',
    'pedido',pedido,
    'id',id,
    'fornecedor',fornecedor,
    'qtd_compra',qtd_compra,
    'valor_compra_unid',valor_compra_unid,
    'valor_compra_total',valor_compra_total,
    'atualizado_em',atualizado_em
  ) INTO v_resultado;

  RETURN v_resultado;
END $$;


--
-- Name: fn_carga_inicial(jsonb); Type: FUNCTION; Schema: vendas; Owner: -
--

CREATE FUNCTION vendas.fn_carga_inicial(p_dados jsonb) RETURNS TABLE(inseridas integer, atualizadas integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_inseridas INT := 0;
  v_atualizadas INT := 0;
BEGIN
  WITH ups AS (
    INSERT INTO vendas.ordens_compra (
      ano, mes, aba_origem, linha_planilha,
      prioridade, tipo_pedido, data_entrega, data_venda,
      pedido, empresa, cnpj, cliente, produto, fornecedor,
      cod_produto, cor,
      qtd_pedido, qtd_faltante, qtd_compra,
      valor_compra_unid, valor_compra_total, valor_vendido_unid,
      link_produto, layout, obs_vendedor, tipo_gravacao,
      cidade_estado, vendedor, status, status_pagamento,
      comprovante, recibo_enviado, observacoes,
      favorecido, chave_pix, pagamento, restante,
      numero_fornecedor, solicitante, data_solicitacao,
      gravacao_fornecedor, gravacao_valor_unid,
      payload_raw, hash_linha
    )
    SELECT
      (e->>'ano')::INT, (e->>'mes')::INT, e->>'aba_origem', (e->>'linha_planilha')::INT,
      e->>'prioridade', e->>'tipo_pedido',
      (e->>'data_entrega')::DATE, (e->>'data_venda')::TIMESTAMPTZ,
      e->>'pedido', e->>'empresa', e->>'cnpj', e->>'cliente',
      e->>'produto', e->>'fornecedor', e->>'cod_produto', e->>'cor',
      NULLIF(e->>'qtd_pedido','')::NUMERIC,
      NULLIF(e->>'qtd_faltante','')::NUMERIC,
      NULLIF(e->>'qtd_compra','')::NUMERIC,
      NULLIF(e->>'valor_compra_unid','')::NUMERIC,
      NULLIF(e->>'valor_compra_total','')::NUMERIC,
      NULLIF(e->>'valor_vendido_unid','')::NUMERIC,
      e->>'link_produto', e->>'layout', e->>'obs_vendedor', e->>'tipo_gravacao',
      e->>'cidade_estado', e->>'vendedor', e->>'status', e->>'status_pagamento',
      e->>'comprovante', e->>'recibo_enviado', e->>'observacoes',
      e->>'favorecido', e->>'chave_pix', e->>'pagamento',
      NULLIF(e->>'restante','')::NUMERIC,
      e->>'numero_fornecedor', e->>'solicitante',
      (e->>'data_solicitacao')::TIMESTAMPTZ,
      e->>'gravacao_fornecedor',
      NULLIF(e->>'gravacao_valor_unid','')::NUMERIC,
      e, md5(e::TEXT)
    FROM jsonb_array_elements(p_dados) AS e
    ON CONFLICT (ano, mes, aba_origem, linha_planilha) DO UPDATE
    SET
      prioridade=EXCLUDED.prioridade, tipo_pedido=EXCLUDED.tipo_pedido,
      data_entrega=EXCLUDED.data_entrega, data_venda=EXCLUDED.data_venda,
      pedido=EXCLUDED.pedido, empresa=EXCLUDED.empresa, cnpj=EXCLUDED.cnpj,
      cliente=EXCLUDED.cliente, produto=EXCLUDED.produto, fornecedor=EXCLUDED.fornecedor,
      cod_produto=EXCLUDED.cod_produto, cor=EXCLUDED.cor,
      qtd_pedido=EXCLUDED.qtd_pedido, qtd_faltante=EXCLUDED.qtd_faltante,
      qtd_compra=EXCLUDED.qtd_compra,
      valor_compra_unid=EXCLUDED.valor_compra_unid,
      valor_compra_total=EXCLUDED.valor_compra_total,
      valor_vendido_unid=EXCLUDED.valor_vendido_unid,
      link_produto=EXCLUDED.link_produto, layout=EXCLUDED.layout,
      obs_vendedor=EXCLUDED.obs_vendedor, tipo_gravacao=EXCLUDED.tipo_gravacao,
      cidade_estado=EXCLUDED.cidade_estado, vendedor=EXCLUDED.vendedor,
      status=EXCLUDED.status, status_pagamento=EXCLUDED.status_pagamento,
      comprovante=EXCLUDED.comprovante, recibo_enviado=EXCLUDED.recibo_enviado,
      observacoes=EXCLUDED.observacoes, favorecido=EXCLUDED.favorecido,
      chave_pix=EXCLUDED.chave_pix, pagamento=EXCLUDED.pagamento,
      restante=EXCLUDED.restante, numero_fornecedor=EXCLUDED.numero_fornecedor,
      solicitante=EXCLUDED.solicitante, data_solicitacao=EXCLUDED.data_solicitacao,
      gravacao_fornecedor=EXCLUDED.gravacao_fornecedor,
      gravacao_valor_unid=EXCLUDED.gravacao_valor_unid,
      payload_raw=EXCLUDED.payload_raw, hash_linha=EXCLUDED.hash_linha,
      sincronizado_em=now(), excluido_em=NULL
    WHERE vendas.ordens_compra.hash_linha IS DISTINCT FROM EXCLUDED.hash_linha
    RETURNING (xmax = 0) AS inserida
  )
  SELECT 
    COUNT(*) FILTER (WHERE inserida)::INT,
    COUNT(*) FILTER (WHERE NOT inserida)::INT
  INTO v_inseridas, v_atualizadas FROM ups;
  
  RETURN QUERY SELECT v_inseridas, v_atualizadas;
END $$;


--
-- Name: fn_carga_lote(jsonb); Type: FUNCTION; Schema: vendas; Owner: -
--

CREATE FUNCTION vendas.fn_carga_lote(p_linhas jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_inseridas INT := 0;
  v_puladas_pedido_dup INT := 0;
  v_puladas_natural INT := 0;
  v_pedidos_dup TEXT[] := ARRAY[]::TEXT[];
  v_linhas_natural TEXT[] := ARRAY[]::TEXT[];
  v_linha jsonb;
  v_pedido TEXT;
  v_ja_existe BOOLEAN;
BEGIN
  FOR v_linha IN SELECT * FROM jsonb_array_elements(p_linhas) LOOP
    v_pedido := v_linha->>'pedido';

    IF v_pedido IS NOT NULL AND v_pedido <> '' 
       AND NOT ((v_linha->>'ano')::INT = 2026 AND (v_linha->>'mes')::INT = 1) THEN
      SELECT EXISTS(
        SELECT 1 FROM vendas.ordens_compra
        WHERE pedido = v_pedido
          AND excluido_em IS NULL
          AND NOT (ano = 2026 AND mes = 1)
      ) INTO v_ja_existe;

      IF v_ja_existe THEN
        v_puladas_pedido_dup := v_puladas_pedido_dup + 1;
        v_pedidos_dup := array_append(v_pedidos_dup,
          v_pedido || ' (aba=' || (v_linha->>'aba_origem') ||
          ' linha=' || (v_linha->>'linha_planilha') || ')'
        );
        CONTINUE;
      END IF;
    END IF;

    BEGIN
      INSERT INTO vendas.ordens_compra (
        ano, mes, aba_origem, linha_planilha,
        prioridade, tipo_pedido, data_entrega, data_venda, pedido, empresa, cnpj, cliente, produto,
        fornecedor, cod_produto, cor, qtd_pedido, qtd_faltante, qtd_compra,
        valor_compra_unid, valor_compra_total, valor_vendido_unid,
        link_produto, layout, obs_vendedor, tipo_gravacao, cidade_estado, vendedor,
        status, status_pagamento, comprovante, recibo_enviado, observacoes,
        favorecido, chave_pix, pagamento, restante, numero_fornecedor,
        solicitante, data_solicitacao, gravacao_fornecedor, gravacao_valor_unid,
        hash_linha, hash_compras, hash_update
      )
      VALUES (
        (v_linha->>'ano')::INT, (v_linha->>'mes')::INT, v_linha->>'aba_origem', (v_linha->>'linha_planilha')::INT,
        v_linha->>'prioridade', v_linha->>'tipo_pedido',
        NULLIF(v_linha->>'data_entrega','')::DATE, NULLIF(v_linha->>'data_venda','')::TIMESTAMPTZ,
        v_linha->>'pedido', v_linha->>'empresa', v_linha->>'cnpj', v_linha->>'cliente', v_linha->>'produto',
        v_linha->>'fornecedor', v_linha->>'cod_produto', v_linha->>'cor',
        NULLIF(v_linha->>'qtd_pedido','')::NUMERIC, NULLIF(v_linha->>'qtd_faltante','')::NUMERIC, NULLIF(v_linha->>'qtd_compra','')::NUMERIC,
        NULLIF(v_linha->>'valor_compra_unid','')::NUMERIC, NULLIF(v_linha->>'valor_compra_total','')::NUMERIC, NULLIF(v_linha->>'valor_vendido_unid','')::NUMERIC,
        v_linha->>'link_produto', v_linha->>'layout', v_linha->>'obs_vendedor', v_linha->>'tipo_gravacao', v_linha->>'cidade_estado', v_linha->>'vendedor',
        v_linha->>'status', v_linha->>'status_pagamento', v_linha->>'comprovante', v_linha->>'recibo_enviado', v_linha->>'observacoes',
        v_linha->>'favorecido', v_linha->>'chave_pix', v_linha->>'pagamento', NULLIF(v_linha->>'restante','')::NUMERIC, v_linha->>'numero_fornecedor',
        v_linha->>'solicitante', NULLIF(v_linha->>'data_solicitacao','')::TIMESTAMPTZ,
        v_linha->>'gravacao_fornecedor', NULLIF(v_linha->>'gravacao_valor_unid','')::NUMERIC,
        v_linha->>'hash_linha', v_linha->>'hash_compras', v_linha->>'hash_update'
      )
      ON CONFLICT (ano, mes, aba_origem, linha_planilha) DO NOTHING;

      IF FOUND THEN
        v_inseridas := v_inseridas + 1;
      ELSE
        v_puladas_natural := v_puladas_natural + 1;
        v_linhas_natural := array_append(v_linhas_natural,
          (v_linha->>'aba_origem')||':'||(v_linha->>'linha_planilha')
        );
      END IF;
    EXCEPTION WHEN unique_violation THEN
      v_puladas_pedido_dup := v_puladas_pedido_dup + 1;
      v_pedidos_dup := array_append(v_pedidos_dup,
        COALESCE(v_pedido,'?')||' (aba='||(v_linha->>'aba_origem')||' linha='||(v_linha->>'linha_planilha')||') [exception]'
      );
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'inseridas', v_inseridas,
    'puladas_pedido_duplicado', v_puladas_pedido_dup,
    'puladas_chave_natural', v_puladas_natural,
    'pedidos_duplicados', v_pedidos_dup,
    'linhas_chave_natural', v_linhas_natural
  );
END $$;


