--
-- Name: fn_listar_produtos_para_ia_ncm(integer); Type: FUNCTION; Schema: vendas; Owner: -
--

CREATE FUNCTION vendas.fn_listar_produtos_para_ia_ncm(p_limit integer DEFAULT 30) RETURNS TABLE(cod_produto text, nome_produto text, fornecedor text, qtd_ocorrencias bigint, prioridade_score numeric)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'vendas'
    AS $$ SELECT v.cod_produto, v.exemplo_nome_produto, v.fornecedor_principal, v.qtd_ocorrencias, ROUND(v.qtd_ocorrencias::numeric * COALESCE(LOG(NULLIF(v.valor_compra_total_acumulado, 0) + 1), 1), 2) FROM vendas.vw_produtos_sem_ncm v WHERE v.cod_produto IS NOT NULL AND v.exemplo_nome_produto IS NOT NULL AND LENGTH(TRIM(v.exemplo_nome_produto)) > 3 ORDER BY v.qtd_ocorrencias * COALESCE(LOG(NULLIF(v.valor_compra_total_acumulado, 0) + 1), 1) DESC NULLS LAST LIMIT p_limit $$;


--
-- Name: FUNCTION fn_listar_produtos_para_ia_ncm(p_limit integer); Type: COMMENT; Schema: vendas; Owner: -
--

COMMENT ON FUNCTION vendas.fn_listar_produtos_para_ia_ncm(p_limit integer) IS '[Onda NF] Lista produtos sem NCM para classificação via IA Gemini. Difere de fn_listar_skus_para_descobrir_ncm porque inclui SKUs genéricos (que falhariam no Bling) - a IA usa o NOME do produto.';


--
-- Name: fn_oc_hash_por_pedido(integer, integer); Type: FUNCTION; Schema: vendas; Owner: -
--

CREATE FUNCTION vendas.fn_oc_hash_por_pedido(p_ano integer, p_mes integer) RETURNS TABLE(pedido text, hash_compras text)
    LANGUAGE sql STABLE
    AS $$
  SELECT pedido, hash_compras
  FROM vendas.ordens_compra
  WHERE ano = p_ano AND mes = p_mes AND excluido_em IS NULL;
$$;


--
-- Name: fn_propagar_ncm_para_ordens_compra(); Type: FUNCTION; Schema: vendas; Owner: -
--

CREATE FUNCTION vendas.fn_propagar_ncm_para_ordens_compra() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'vendas'
    AS $$
DECLARE
  v_rows INT;
  v_fonte text;
BEGIN
  IF NEW.ncm IS NULL OR NEW.cod_produto IS NULL THEN
    RETURN NEW;
  END IF;

  -- fonte canônica para ordens_compra:
  -- 'manual' se foi o humano, 'mapa_cache' para qualquer origem automática
  v_fonte := CASE NEW.origem WHEN 'manual' THEN 'manual' ELSE 'mapa_cache' END;

  UPDATE vendas.ordens_compra
  SET
    ncm               = NEW.ncm,
    ncm_fonte         = v_fonte,
    ncm_atualizado_em = NOW(),
    atualizado_em     = NOW()
  WHERE
    cod_produto   = NEW.cod_produto
    AND excluido_em IS NULL
    AND (ncm IS NULL OR (ncm != NEW.ncm AND COALESCE(ncm_fonte, '') != 'manual'));

  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RAISE NOTICE '[fn_propagar_ncm] cod_produto=% ncm=% origem=% → % OC atualizadas',
    NEW.cod_produto, NEW.ncm, NEW.origem, v_rows;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION fn_propagar_ncm_para_ordens_compra(); Type: COMMENT; Schema: vendas; Owner: -
--

COMMENT ON FUNCTION vendas.fn_propagar_ncm_para_ordens_compra() IS '[Onda NF] Trigger que propaga NCM do mapa (produtos_ncm_mapa) para todas as linhas correspondentes em ordens_compra com mesmo cod_produto. Mantém o cadastro central e dispensa atualização manual linha-a-linha.';


--
-- Name: fn_registrar_ncm_descoberto(text, text, text, text, text, text); Type: FUNCTION; Schema: vendas; Owner: -
--

CREATE FUNCTION vendas.fn_registrar_ncm_descoberto(p_cod_produto text, p_ncm text, p_nome_produto text DEFAULT NULL::text, p_bling_produto_id text DEFAULT NULL::text, p_fornecedor text DEFAULT NULL::text, p_origem text DEFAULT 'bling_api'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'vendas'
    AS $_$ DECLARE v_rows_propagadas INT; v_id UUID; BEGIN IF p_cod_produto IS NULL OR p_ncm IS NULL OR p_ncm !~ '^[0-9]{8}$' THEN RETURN jsonb_build_object('ok', false, 'erro', 'cod_produto ou ncm inválido', 'cod_produto', p_cod_produto, 'ncm', p_ncm); END IF; INSERT INTO vendas.produtos_ncm_mapa (cod_produto, ncm, nome_produto, bling_produto_id, fornecedor, origem) VALUES (p_cod_produto, p_ncm, p_nome_produto, p_bling_produto_id, p_fornecedor, p_origem) ON CONFLICT (cod_produto) DO UPDATE SET ncm = EXCLUDED.ncm, nome_produto = COALESCE(EXCLUDED.nome_produto, vendas.produtos_ncm_mapa.nome_produto), bling_produto_id = COALESCE(EXCLUDED.bling_produto_id, vendas.produtos_ncm_mapa.bling_produto_id), fornecedor = COALESCE(EXCLUDED.fornecedor, vendas.produtos_ncm_mapa.fornecedor), origem = EXCLUDED.origem, atualizado_em = now() RETURNING id INTO v_id; SELECT COUNT(*) INTO v_rows_propagadas FROM vendas.ordens_compra WHERE cod_produto = p_cod_produto AND ncm = p_ncm; RETURN jsonb_build_object('ok', true, 'mapa_id', v_id, 'cod_produto', p_cod_produto, 'ncm', p_ncm, 'ordens_compra_atualizadas', v_rows_propagadas); END; $_$;


--
-- Name: FUNCTION fn_registrar_ncm_descoberto(p_cod_produto text, p_ncm text, p_nome_produto text, p_bling_produto_id text, p_fornecedor text, p_origem text); Type: COMMENT; Schema: vendas; Owner: -
--

COMMENT ON FUNCTION vendas.fn_registrar_ncm_descoberto(p_cod_produto text, p_ncm text, p_nome_produto text, p_bling_produto_id text, p_fornecedor text, p_origem text) IS '[Onda NF] RPC chamado pelo n8n quando descobre NCM no Bling. Faz UPSERT em produtos_ncm_mapa e o trigger propaga para ordens_compra. Retorna JSON com contagem propagada.';


--
-- Name: fn_set_atualizado_em(); Type: FUNCTION; Schema: vendas; Owner: -
--

CREATE FUNCTION vendas.fn_set_atualizado_em() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.atualizado_em = now();
  RETURN NEW;
END $$;


--
-- Name: fn_trg_ncm_auto(); Type: FUNCTION; Schema: vendas; Owner: -
--

CREATE FUNCTION vendas.fn_trg_ncm_auto() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'vendas'
    AS $$
DECLARE
  v_ncm   text;
  v_fonte text;
BEGIN
  -- Já tem NCM → nada a fazer
  IF NEW.ncm IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- ── Caminho A: tem cod_produto ──────────────────
  IF NEW.cod_produto IS NOT NULL THEN
    SELECT m.ncm,
           CASE m.origem WHEN 'manual' THEN 'manual' ELSE 'mapa_cache' END
    INTO v_ncm, v_fonte
    FROM vendas.produtos_ncm_mapa m
    WHERE m.cod_produto = NEW.cod_produto
    LIMIT 1;

    IF v_ncm IS NOT NULL THEN
      NEW.ncm               := v_ncm;
      NEW.ncm_fonte         := v_fonte;
      NEW.ncm_atualizado_em := NOW();
    END IF;
    -- Se não achou → sai com ncm=NULL; AFTER trigger chama o n8n

  -- ── Caminho B: sem cod_produto → match por nome ──
  ELSE
    SELECT oc.ncm, 'nome_match'
    INTO v_ncm, v_fonte
    FROM vendas.ordens_compra oc
    WHERE oc.produto      = NEW.produto
      AND oc.ncm          IS NOT NULL
      AND oc.excluido_em  IS NULL
    LIMIT 1;

    IF v_ncm IS NOT NULL THEN
      NEW.ncm               := v_ncm;
      NEW.ncm_fonte         := 'nome_match';
      NEW.ncm_atualizado_em := NOW();
    END IF;
    -- Se não achou: NCM fica NULL (sem cod_produto não dá pra acionar n8n com chave)
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_trg_ncm_enqueue_n8n(); Type: FUNCTION; Schema: vendas; Owner: -
--

CREATE FUNCTION vendas.fn_trg_ncm_enqueue_n8n() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'vendas', 'net'
    AS $$
DECLARE
  v_url text;
BEGIN
  IF NEW.ncm IS NOT NULL OR NEW.cod_produto IS NULL THEN
    RETURN NEW;
  END IF;

  IF EXISTS (SELECT 1 FROM vendas.ncm_skus_blacklist WHERE cod_produto = NEW.cod_produto) THEN
    RETURN NEW;
  END IF;

  SELECT valor INTO v_url
  FROM vendas._config
  WHERE chave = 'n8n_ncm_webhook_url'
  LIMIT 1;

  IF v_url IS NULL OR TRIM(v_url) = '' THEN
    RAISE WARNING '[ncm_enqueue] _config.n8n_ncm_webhook_url ausente. cod_produto=% ignorado.', NEW.cod_produto;
    RETURN NEW;
  END IF;

  BEGIN
    PERFORM net.http_post(
      url                  := v_url,
      body                 := jsonb_build_object(
        'cod_produto',  NEW.cod_produto,
        'nome_produto', NEW.produto,
        'fornecedor',   NEW.fornecedor,
        'oc_id',        NEW.id
      ),
      headers              := '{"Content-Type": "application/json"}'::jsonb,
      timeout_milliseconds := 5000
    );
    RAISE NOTICE '[ncm_enqueue] n8n acionado → cod_produto=%', NEW.cod_produto;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING '[ncm_enqueue] Falha webhook: %', SQLERRM;
  END;

  RETURN NEW;
END;
$$;


--
-- Name: fn_trg_oc_sync_unificada(); Type: FUNCTION; Schema: vendas; Owner: -
--

CREATE FUNCTION vendas.fn_trg_oc_sync_unificada() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
  v_pedido text;
  v_ano int;
  v_mes int;
BEGIN
  v_pedido := COALESCE(NEW.pedido, OLD.pedido);
  v_ano := COALESCE(NEW.ano, OLD.ano);
  v_mes := COALESCE(NEW.mes, OLD.mes);

  IF v_pedido IS NOT NULL AND ((v_ano > 2026) OR (v_ano = 2026 AND v_mes >= 5)) THEN
    PERFORM financeiro.sync_vendas_unificadas_from_oc(regexp_replace(v_pedido, '-(\d+)$', ''), v_ano, v_mes);
  END IF;

  -- Se um UPDATE mudou pedido/ano/mes, ressincroniza tambem o anterior
  IF TG_OP = 'UPDATE' AND OLD.pedido IS NOT NULL
     AND (regexp_replace(OLD.pedido,'-(\d+)$',''), OLD.ano, OLD.mes)
         IS DISTINCT FROM (regexp_replace(NEW.pedido,'-(\d+)$',''), NEW.ano, NEW.mes)
     AND ((OLD.ano > 2026) OR (OLD.ano = 2026 AND OLD.mes >= 5)) THEN
    PERFORM financeiro.sync_vendas_unificadas_from_oc(regexp_replace(OLD.pedido,'-(\d+)$',''), OLD.ano, OLD.mes);
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$_$;


--
-- Name: fn_update_compras(jsonb); Type: FUNCTION; Schema: vendas; Owner: -
--

CREATE FUNCTION vendas.fn_update_compras(p_updates jsonb) RETURNS TABLE(pedido text, atualizado boolean, motivo text)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  WITH input AS (
    SELECT
      u->>'pedido' AS pedido,
      u->>'produto' AS produto,
      u->>'fornecedor' AS fornecedor,
      NULLIF(u->>'qtd_compra','')::NUMERIC AS qtd_compra,
      NULLIF(u->>'valor_compra_unid','')::NUMERIC AS valor_compra_unid,
      NULLIF(u->>'valor_compra_total','')::NUMERIC AS valor_compra_total,
      u->>'hash_compras' AS hash_compras_novo
    FROM jsonb_array_elements(p_updates) u
  ),
  contagem AS (
    SELECT 
      i.pedido,
      i.produto, i.fornecedor, i.qtd_compra, i.valor_compra_unid, i.valor_compra_total, i.hash_compras_novo,
      (SELECT COUNT(*) FROM vendas.ordens_compra oc WHERE oc.pedido = i.pedido AND oc.excluido_em IS NULL) AS qtd_match
    FROM input i
  ),
  updates AS (
    UPDATE vendas.ordens_compra oc
    SET
      produto            = c.produto,
      fornecedor         = c.fornecedor,
      qtd_compra         = c.qtd_compra,
      valor_compra_unid  = c.valor_compra_unid,
      valor_compra_total = c.valor_compra_total,
      hash_compras       = c.hash_compras_novo
    FROM contagem c
    WHERE oc.pedido = c.pedido
      AND oc.excluido_em IS NULL
      AND c.qtd_match = 1
      AND (oc.hash_compras IS DISTINCT FROM c.hash_compras_novo)
    RETURNING oc.pedido
  )
  SELECT
    c.pedido,
    (c.qtd_match = 1 AND EXISTS(SELECT 1 FROM updates u WHERE u.pedido = c.pedido)) AS atualizado,
    CASE
      WHEN c.qtd_match = 0 THEN 'pedido_nao_encontrado'
      WHEN c.qtd_match > 1 THEN 'pedido_duplicado_'||c.qtd_match::TEXT||'_linhas'
      WHEN EXISTS(SELECT 1 FROM updates u WHERE u.pedido = c.pedido) THEN 'atualizado_ok'
      ELSE 'sem_mudancas'
    END AS motivo
  FROM contagem c;
END $$;


--
-- Name: fn_update_oc_v2(jsonb); Type: FUNCTION; Schema: vendas; Owner: -
--

CREATE FUNCTION vendas.fn_update_oc_v2(p_updates jsonb) RETURNS TABLE(pedido text, atualizado boolean, motivo text)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  WITH input AS (
    SELECT
      u->>'pedido'                                   AS pedido,
      (u->>'ano')::int                               AS ano,
      (u->>'mes')::int                               AS mes,
      u->>'aba_origem'                               AS aba_origem,
      u->>'prioridade'                               AS prioridade,
      u->>'tipo_pedido'                              AS tipo_pedido,
      NULLIF(u->>'data_entrega','')::date            AS data_entrega,
      NULLIF(u->>'data_venda','')::timestamptz       AS data_venda,
      u->>'empresa'                                  AS empresa,
      u->>'cnpj'                                     AS cnpj,
      u->>'cliente'                                  AS cliente,
      u->>'produto'                                  AS produto,
      u->>'fornecedor'                               AS fornecedor,
      u->>'cod_produto'                              AS cod_produto,
      u->>'cor'                                      AS cor,
      NULLIF(u->>'qtd_pedido','')::numeric           AS qtd_pedido,
      NULLIF(u->>'qtd_faltante','')::numeric         AS qtd_faltante,
      NULLIF(u->>'qtd_compra','')::numeric           AS qtd_compra,
      NULLIF(u->>'valor_compra_unid','')::numeric    AS valor_compra_unid,
      NULLIF(u->>'valor_compra_total','')::numeric   AS valor_compra_total,
      NULLIF(u->>'valor_vendido_unid','')::numeric   AS valor_vendido_unid,
      u->>'link_produto'                             AS link_produto,
      u->>'layout'                                   AS layout,
      u->>'obs_vendedor'                             AS obs_vendedor,
      u->>'tipo_gravacao'                            AS tipo_gravacao,
      u->>'cidade_estado'                            AS cidade_estado,
      u->>'vendedor'                                 AS vendedor,
      u->>'status'                                   AS status,
      u->>'status_pagamento'                         AS status_pagamento,
      u->>'comprovante'                              AS comprovante,
      u->>'recibo_enviado'                           AS recibo_enviado,
      u->>'observacoes'                              AS observacoes,
      u->>'favorecido'                               AS favorecido,
      u->>'chave_pix'                                AS chave_pix,
      u->>'pagamento'                                AS pagamento,
      NULLIF(u->>'restante','')::numeric             AS restante,
      u->>'numero_fornecedor'                        AS numero_fornecedor,
      u->>'solicitante'                              AS solicitante,
      NULLIF(u->>'data_solicitacao','')::timestamptz AS data_solicitacao,
      u->>'gravacao_fornecedor'                      AS gravacao_fornecedor,
      NULLIF(u->>'gravacao_valor_unid','')::numeric  AS gravacao_valor_unid,
      u->>'hash_linha'                               AS hash_linha,
      u->>'hash_compras'                             AS hash_compras,
      u->>'hash_update'                              AS hash_update_novo
    FROM jsonb_array_elements(p_updates) u
    WHERE u->>'pedido' IS NOT NULL AND u->>'pedido' <> ''
  ),
  contagem AS (
    SELECT i.*,
      (SELECT COUNT(*) FROM vendas.ordens_compra oc
        WHERE oc.pedido = i.pedido AND oc.excluido_em IS NULL) AS qtd_match
    FROM input i
  ),
  updates AS (
    UPDATE vendas.ordens_compra oc
    SET
      produto             = c.produto,
      fornecedor          = c.fornecedor,
      qtd_pedido          = c.qtd_pedido,
      qtd_compra          = c.qtd_compra,
      valor_compra_unid   = c.valor_compra_unid,
      valor_compra_total  = c.valor_compra_total,
      valor_vendido_unid  = c.valor_vendido_unid,
      tipo_gravacao       = c.tipo_gravacao,
      status              = c.status,
      status_pagamento    = c.status_pagamento,
      comprovante         = c.comprovante,
      favorecido          = c.favorecido,
      chave_pix           = c.chave_pix,
      pagamento           = c.pagamento,
      restante            = c.restante,
      numero_fornecedor   = c.numero_fornecedor,
      solicitante         = c.solicitante,
      data_solicitacao    = c.data_solicitacao,
      gravacao_fornecedor = c.gravacao_fornecedor,
      gravacao_valor_unid = c.gravacao_valor_unid,
      hash_update         = c.hash_update_novo,
      atualizado_em       = NOW()
    FROM contagem c
    WHERE oc.pedido = c.pedido
      AND oc.excluido_em IS NULL
      AND c.qtd_match = 1
      AND (oc.hash_update IS DISTINCT FROM c.hash_update_novo)
    RETURNING oc.pedido
  ),
  novos AS (
    SELECT DISTINCT ON (c.pedido) c.*,
      (SELECT COALESCE(MAX(oc2.linha_planilha),0)
         FROM vendas.ordens_compra oc2
        WHERE oc2.ano = c.ano AND oc2.mes = c.mes)
      + row_number() OVER (PARTITION BY c.ano, c.mes ORDER BY c.pedido) AS linha_nova
    FROM contagem c
    WHERE c.qtd_match = 0
    ORDER BY c.pedido
  ),
  inserts AS (
    INSERT INTO vendas.ordens_compra AS oc_new (
      ano, mes, aba_origem, linha_planilha,
      prioridade, tipo_pedido, data_entrega, data_venda, pedido, empresa, cnpj, cliente, produto,
      fornecedor, cod_produto, cor, qtd_pedido, qtd_faltante, qtd_compra,
      valor_compra_unid, valor_compra_total, valor_vendido_unid,
      link_produto, layout, obs_vendedor, tipo_gravacao, cidade_estado, vendedor,
      status, status_pagamento, comprovante, recibo_enviado, observacoes,
      favorecido, chave_pix, pagamento, restante, numero_fornecedor,
      solicitante, data_solicitacao, gravacao_fornecedor, gravacao_valor_unid,
      hash_linha, hash_compras, hash_update
    )
    SELECT
      n.ano, n.mes, n.aba_origem, n.linha_nova,
      n.prioridade, n.tipo_pedido, n.data_entrega, n.data_venda, n.pedido, n.empresa, n.cnpj, n.cliente, n.produto,
      n.fornecedor, n.cod_produto, n.cor, n.qtd_pedido, n.qtd_faltante, n.qtd_compra,
      n.valor_compra_unid, n.valor_compra_total, n.valor_vendido_unid,
      n.link_produto, n.layout, n.obs_vendedor, n.tipo_gravacao, n.cidade_estado, n.vendedor,
      n.status, n.status_pagamento, n.comprovante, n.recibo_enviado, n.observacoes,
      n.favorecido, n.chave_pix, n.pagamento, n.restante, n.numero_fornecedor,
      n.solicitante, n.data_solicitacao, n.gravacao_fornecedor, n.gravacao_valor_unid,
      n.hash_linha, n.hash_compras, n.hash_update_novo
    FROM novos n
    ON CONFLICT (ano, mes, aba_origem, linha_planilha) DO NOTHING
    RETURNING oc_new.pedido
  )
  SELECT
    c.pedido,
    (
      (c.qtd_match = 1 AND EXISTS(SELECT 1 FROM updates u WHERE u.pedido = c.pedido))
      OR EXISTS(SELECT 1 FROM inserts i WHERE i.pedido = c.pedido)
    ) AS atualizado,
    CASE
      WHEN EXISTS(SELECT 1 FROM inserts i WHERE i.pedido = c.pedido) THEN 'inserido_ok'
      WHEN c.qtd_match = 0 THEN 'pedido_nao_encontrado'
      WHEN c.qtd_match > 1 THEN 'pedido_duplicado_'||c.qtd_match::text||'_linhas'
      WHEN EXISTS(SELECT 1 FROM updates u WHERE u.pedido = c.pedido) THEN 'atualizado_ok'
      ELSE 'sem_mudancas'
    END AS motivo
  FROM contagem c;
END $$;


--
-- Name: handle_new_auth_user(); Type: FUNCTION; Schema: vendas; Owner: -
--

CREATE FUNCTION vendas.handle_new_auth_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'vendas', 'pg_catalog'
    AS $$
declare
  _nome text;
begin
  _nome := coalesce(
    new.raw_user_meta_data->>'full_name',
    new.raw_user_meta_data->>'name',
    split_part(new.email, '@', 1)
  );
  insert into vendas.usuarios (id, email, nome, perfil)
  values (new.id, new.email, _nome, 'visualizador')
  on conflict (id) do nothing;
  return new;
end;
$$;


