$$;


--
-- Name: resetar_envios_pedido(text); Type: FUNCTION; Schema: vendas; Owner: -
--

CREATE FUNCTION vendas.resetar_envios_pedido(p_pedido_pai text) RETURNS TABLE(acao text, detalhe text, qtd_afetada integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'vendas'
    AS $_$
DECLARE
  v_envios_removidos  integer;
  v_itens_resetados   integer;
  v_pedido_pai_norm   text;
BEGIN
  v_pedido_pai_norm := upper(trim(p_pedido_pai));

  -- 1) Apaga histórico de envios (vendas.envios_cotacao) dos itens deste pedido
  WITH del AS (
    DELETE FROM vendas.envios_cotacao ec
    USING vendas.ordens_compra oc
    WHERE ec.ordem_compra_id = oc.id
      AND (CASE 
             WHEN oc.pedido ~ '^.+-[0-9]+$' THEN regexp_replace(oc.pedido, '-[0-9]+$', '')
             ELSE oc.pedido
           END) = v_pedido_pai_norm
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_envios_removidos FROM del;

  acao := 'historico_envios_removidos';
  detalhe := format('Apagados de vendas.envios_cotacao para pedido %s', v_pedido_pai_norm);
  qtd_afetada := v_envios_removidos;
  RETURN NEXT;

  -- 2) Reset das colunas de envio na ordens_compra (NÃO mexe em "status" da planilha)
  WITH upd AS (
    UPDATE vendas.ordens_compra
    SET 
      qtd_enviada       = 0,
      status_envio      = 'pendente',
      ultimo_envio_em   = NULL,
      ultima_cotacao_id = NULL,
      atualizado_em     = now()
    WHERE (CASE 
             WHEN pedido ~ '^.+-[0-9]+$' THEN regexp_replace(pedido, '-[0-9]+$', '')
             ELSE pedido
           END) = v_pedido_pai_norm
      AND excluido_em IS NULL
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_itens_resetados FROM upd;

  acao := 'itens_resetados';
  detalhe := format('qtd_enviada=0, status_envio=pendente em vendas.ordens_compra para pedido %s', v_pedido_pai_norm);
  qtd_afetada := v_itens_resetados;
  RETURN NEXT;

  -- 3) Aviso sobre cotações vinculadas (não deleta, apenas informa)
  acao := 'cotacoes_vinculadas_nao_apagadas';
  detalhe := 'public.cotacoes mantidas (apague manualmente pelo painel se quiser limpar histórico)';
  SELECT COUNT(*) INTO qtd_afetada FROM public.cotacoes WHERE pedido_pai_origem = v_pedido_pai_norm;
  RETURN NEXT;

  RETURN;
END;
$_$;


--
-- Name: FUNCTION resetar_envios_pedido(p_pedido_pai text); Type: COMMENT; Schema: vendas; Owner: -
--

COMMENT ON FUNCTION vendas.resetar_envios_pedido(p_pedido_pai text) IS '[LOGISTICA] Utility de QA: zera qtd_enviada/status_envio/ultimo_envio_em de todos os itens de um pedido_pai e DELETA os registros correspondentes em envios_cotacao. NÃO apaga cotacoes em public.cotacoes (use DELETE FROM public.cotacoes WHERE pedido_pai_origem para isso). Onda 5, 2026-05-21.';


