--
-- Name: sync_status_envio_from_status(); Type: FUNCTION; Schema: vendas; Owner: -
--

CREATE FUNCTION vendas.sync_status_envio_from_status() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Quando status muda pra ENTREGUE/CONCLUÍDO, marca como envio total
  IF NEW.status IN ('ENTREGUE', 'CONCLUÍDO')
     AND (OLD.status IS DISTINCT FROM NEW.status OR NEW.status_envio IS DISTINCT FROM 'total')
     AND NEW.status_envio != 'total' THEN
    NEW.qtd_enviada      := GREATEST(COALESCE(NEW.qtd_enviada, 0), COALESCE(NEW.qtd_pedido, 0));
    NEW.status_envio     := 'total';
    NEW.ultimo_envio_em  := COALESCE(NEW.ultimo_envio_em, now());
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION sync_status_envio_from_status(); Type: COMMENT; Schema: vendas; Owner: -
--

COMMENT ON FUNCTION vendas.sync_status_envio_from_status() IS '[LOGISTICA] Trigger BEFORE INSERT/UPDATE OF status em vendas.ordens_compra. Quando status muda para ENTREGUE ou CONCLUIDO, força status_envio=total e qtd_enviada=qtd_pedido. Mantém coerência sem depender do painel. Onda 5b, 2026-05-21.';


--
-- Name: _fn_health_diag(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp._fn_health_diag() RETURNS TABLE(dim text, ms numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'ops', 'cron', 'pg_catalog'
    AS $$
DECLARE t0 timestamptz; ttotal timestamptz;
BEGIN
  ttotal := clock_timestamp();

  t0:=clock_timestamp(); PERFORM * FROM zapp.whatsapp_connections WHERE instance_name='wpp2' LIMIT 1; RETURN NEXT; dim:='1_wpp2'; ms:=ROUND(EXTRACT(EPOCH FROM(clock_timestamp()-t0))*1000,1);
  t0:=clock_timestamp(); PERFORM MAX(created_at) FROM zapp.webhook_audit_log; PERFORM MAX(created_at) FROM evo.evolution_webhook_events_v2; RETURN NEXT; dim:='2a_pipeline_max'; ms:=ROUND(EXTRACT(EPOCH FROM(clock_timestamp()-t0))*1000,1);
  t0:=clock_timestamp(); PERFORM COUNT(*) FROM zapp.webhook_events_processed WHERE processed_at>now()-interval '1 hour'; RETURN NEXT; dim:='2b_events_proc'; ms:=ROUND(EXTRACT(EPOCH FROM(clock_timestamp()-t0))*1000,1);
  t0:=clock_timestamp(); PERFORM COUNT(*) FROM zapp.webhook_audit_log WHERE status='processed' AND created_at>now()-interval '1 hour'; RETURN NEXT; dim:='2c_audit_1h'; ms:=ROUND(EXTRACT(EPOCH FROM(clock_timestamp()-t0))*1000,1);
  t0:=clock_timestamp(); PERFORM COUNT(*) FILTER(WHERE created_at>now()-interval '7 days') FROM evo.evolution_messages WHERE instance_name='wpp2'; RETURN NEXT; dim:='2d_msgs_7d'; ms:=ROUND(EXTRACT(EPOCH FROM(clock_timestamp()-t0))*1000,1);
  t0:=clock_timestamp(); PERFORM COUNT(*) FROM vault.secrets WHERE name='webhook_secret_evolution'; RETURN NEXT; dim:='5_vault'; ms:=ROUND(EXTRACT(EPOCH FROM(clock_timestamp()-t0))*1000,1);
  t0:=clock_timestamp(); PERFORM value FROM evo.evolution_settings WHERE key='r2_evo_config'; RETURN NEXT; dim:='6_r2_settings'; ms:=ROUND(EXTRACT(EPOCH FROM(clock_timestamp()-t0))*1000,1);
  t0:=clock_timestamp(); PERFORM COUNT(*) FROM zapp.instance_registry WHERE phone_number IS NULL AND is_active=true; RETURN NEXT; dim:='7_ghost'; ms:=ROUND(EXTRACT(EPOCH FROM(clock_timestamp()-t0))*1000,1);
  t0:=clock_timestamp(); PERFORM COUNT(*) FROM cron.job_run_details WHERE status='failed' AND start_time>now()-interval '24 hours' AND return_message NOT LIKE '%does not exist%' AND return_message NOT LIKE '%invalid%'; RETURN NEXT; dim:='8_cron_health'; ms:=ROUND(EXTRACT(EPOCH FROM(clock_timestamp()-t0))*1000,1);
  t0:=clock_timestamp(); PERFORM pg_total_relation_size('zapp.webhook_audit_log'); RETURN NEXT; dim:='9_audit_size'; ms:=ROUND(EXTRACT(EPOCH FROM(clock_timestamp()-t0))*1000,1);
  t0:=clock_timestamp(); PERFORM COUNT(*) FROM pg_stat_activity WHERE state='idle' AND datname=current_database(); RETURN NEXT; dim:='10_idle'; ms:=ROUND(EXTRACT(EPOCH FROM(clock_timestamp()-t0))*1000,1);
  t0:=clock_timestamp(); PERFORM COUNT(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('evo','zapp','public') AND c.relkind IN ('r','p') AND NOT EXISTS(SELECT 1 FROM pg_constraint con WHERE con.conrelid=c.oid AND con.contype='p'); RETURN NEXT; dim:='12_pk_integrity'; ms:=ROUND(EXTRACT(EPOCH FROM(clock_timestamp()-t0))*1000,1);
  t0:=clock_timestamp(); PERFORM COUNT(*) FROM pg_tables WHERE schemaname IN ('evo','zapp') AND tablename NOT LIKE '%_202%' AND rowsecurity=false; RETURN NEXT; dim:='13_rls_cov'; ms:=ROUND(EXTRACT(EPOCH FROM(clock_timestamp()-t0))*1000,1);
  t0:=clock_timestamp(); PERFORM COUNT(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('zapp','evo') AND c.relkind IN ('r','v','p') AND c.relacl IS NOT NULL AND EXISTS(SELECT 1 FROM unnest(c.relacl) AS acl WHERE acl::text LIKE 'anon=%' OR acl::text ~ '^='); RETURN NEXT; dim:='14_sec_posture'; ms:=ROUND(EXTRACT(EPOCH FROM(clock_timestamp()-t0))*1000,1);
  t0:=clock_timestamp(); PERFORM 1 FROM evo.evolution_webhook_events_v2 LIMIT 1; RETURN NEXT; dim:='16_evo_db'; ms:=ROUND(EXTRACT(EPOCH FROM(clock_timestamp()-t0))*1000,1);
  t0:=clock_timestamp(); PERFORM COUNT(*) FROM ops.redis_sentinel; RETURN NEXT; dim:='15_redis'; ms:=ROUND(EXTRACT(EPOCH FROM(clock_timestamp()-t0))*1000,1);
  t0:=clock_timestamp(); PERFORM COUNT(*) FROM information_schema.views WHERE table_schema='public' AND table_name IN ('zapp_audit_log','webhook_audit_log'); RETURN NEXT; dim:='17_observability'; ms:=ROUND(EXTRACT(EPOCH FROM(clock_timestamp()-t0))*1000,1);
  t0:=clock_timestamp(); PERFORM last_backup_at FROM ops.backup_sentinel ORDER BY updated_at DESC LIMIT 1; RETURN NEXT; dim:='18_backup'; ms:=ROUND(EXTRACT(EPOCH FROM(clock_timestamp()-t0))*1000,1);
  t0:=clock_timestamp(); PERFORM zapp.fn_score_security_acl(); RETURN NEXT; dim:='19_fn_sec_acl'; ms:=ROUND(EXTRACT(EPOCH FROM(clock_timestamp()-t0))*1000,1);
  t0:=clock_timestamp(); PERFORM COUNT(*) FROM pg_replication_slots WHERE slot_type='logical' AND active=true; RETURN NEXT; dim:='20_wal'; ms:=ROUND(EXTRACT(EPOCH FROM(clock_timestamp()-t0))*1000,1);
  t0:=clock_timestamp(); PERFORM zapp.fn_score_v2_pipeline(); RETURN NEXT; dim:='21_fn_v2_pipe'; ms:=ROUND(EXTRACT(EPOCH FROM(clock_timestamp()-t0))*1000,1);

  RETURN NEXT; dim:='==TOTAL=='; ms:=ROUND(EXTRACT(EPOCH FROM(clock_timestamp()-ttotal))*1000,1);
END $$;


--
-- Name: _fn_health_min_test(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp._fn_health_min_test() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'ops', 'cron', 'pg_catalog'
    AS $$
DECLARE
  t0 timestamptz; ttotal timestamptz;
  v_score numeric:=0; v_max numeric:=0; v_bd jsonb:='{}';
  v_count int; v_text text; v_ts timestamptz; v_n numeric; v_b boolean;
BEGIN
  ttotal := clock_timestamp();

  -- Simular 23 SELECTs com lógica similar à função real
  t0:=clock_timestamp(); SELECT status INTO v_text FROM zapp.whatsapp_connections WHERE instance_name='wpp2' LIMIT 1;
  RAISE NOTICE '1_wpp2: %ms', ROUND(EXTRACT(EPOCH FROM(clock_timestamp()-t0))*1000,1);
  v_max:=v_max+20; IF v_text='connected' THEN v_score:=v_score+20; END IF;
  v_bd:=v_bd||jsonb_build_object('wpp2',jsonb_build_object('score',20,'max',20,'status',v_text));

  t0:=clock_timestamp(); SELECT MAX(created_at) INTO v_ts FROM zapp.webhook_audit_log;
  RAISE NOTICE '2a_max_audit: %ms', ROUND(EXTRACT(EPOCH FROM(clock_timestamp()-t0))*1000,1);

  t0:=clock_timestamp(); SELECT COUNT(*) INTO v_count FROM zapp.webhook_audit_log WHERE status='processed' AND created_at>now()-interval '1 hour';
  RAISE NOTICE '2b_audit_1h (%): %ms', v_count, ROUND(EXTRACT(EPOCH FROM(clock_timestamp()-t0))*1000,1);
  v_max:=v_max+15; IF v_count>500 THEN v_score:=v_score+15; END IF;
  v_bd:=v_bd||jsonb_build_object('pipeline',jsonb_build_object('score',15,'max',15,'audit_1h',v_count));

  t0:=clock_timestamp(); SELECT COUNT(*) FILTER(WHERE created_at>now()-interval '7 days') INTO v_count FROM evo.evolution_messages WHERE instance_name='wpp2';
  RAISE NOTICE '2d_msgs_7d (%): %ms', v_count, ROUND(EXTRACT(EPOCH FROM(clock_timestamp()-t0))*1000,1);

  t0:=clock_timestamp(); SELECT COUNT(*) INTO v_count FROM vault.secrets WHERE name='webhook_secret_evolution';
  RAISE NOTICE '5_vault: %ms', ROUND(EXTRACT(EPOCH FROM(clock_timestamp()-t0))*1000,1);
  v_max:=v_max+10; IF v_count>0 THEN v_score:=v_score+10; END IF;

  t0:=clock_timestamp(); SELECT COUNT(*) INTO v_count FROM cron.job_run_details WHERE status='failed' AND start_time>now()-interval '24 hours';
  RAISE NOTICE '8_cron: %ms', ROUND(EXTRACT(EPOCH FROM(clock_timestamp()-t0))*1000,1);
  v_max:=v_max+5; IF v_count=0 THEN v_score:=v_score+5; END IF;

  t0:=clock_timestamp(); SELECT COUNT(*) INTO v_count FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('evo','zapp','public') AND c.relkind IN ('r','p') AND NOT EXISTS(SELECT 1 FROM pg_constraint con WHERE con.conrelid=c.oid AND con.contype='p');
  RAISE NOTICE '12_pk: %ms', ROUND(EXTRACT(EPOCH FROM(clock_timestamp()-t0))*1000,1);
  v_max:=v_max+5; IF v_count=0 THEN v_score:=v_score+5; END IF;

  t0:=clock_timestamp(); SELECT zapp.fn_score_security_acl() INTO v_bd;
  RAISE NOTICE '19_sec_acl: %ms', ROUND(EXTRACT(EPOCH FROM(clock_timestamp()-t0))*1000,1);
  v_max:=v_max+5; v_score:=v_score+5;

  t0:=clock_timestamp(); SELECT zapp.fn_score_v2_pipeline() INTO v_bd;
  RAISE NOTICE '21_v2: %ms', ROUND(EXTRACT(EPOCH FROM(clock_timestamp()-t0))*1000,1);
  v_max:=v_max+10; v_score:=v_score+10;

  RAISE NOTICE 'TOTAL: %ms score=%/%', ROUND(EXTRACT(EPOCH FROM(clock_timestamp()-ttotal))*1000,1), v_score, v_max;

  RETURN jsonb_build_object('score',ROUND(100.0*v_score/v_max,1),'max',v_max,'breakdown',v_bd);
END $$;


--
-- Name: _fn_health_noexc(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp._fn_health_noexc() RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_score numeric:=0; v_max numeric:=0; v_bd jsonb:='{}';
  v int; vn numeric; vt timestamptz; vs text; vj jsonb;
BEGIN
  -- DIM 1 wpp2 -- FIX: usar vs text para status
  v_max:=v_max+20;
  SELECT status INTO vs FROM zapp.whatsapp_connections WHERE instance_name='wpp2' LIMIT 1;
  IF vs='connected' THEN v_score:=v_score+20; END IF;
  v_bd:=v_bd||jsonb_build_object('wpp2',jsonb_build_object('score',CASE WHEN vs='connected' THEN 20 ELSE 0 END,'max',20));
  -- DIM 2 pipeline
  v_max:=v_max+15;
  SELECT COUNT(*) INTO v FROM zapp.webhook_audit_log WHERE status='processed' AND created_at>now()-interval '1 hour';
  IF v>=500 THEN v_score:=v_score+15; ELSIF v>=100 THEN v_score:=v_score+12; ELSIF v>=10 THEN v_score:=v_score+10; ELSE v_score:=v_score+8; END IF;
  v_bd:=v_bd||jsonb_build_object('pipeline',jsonb_build_object('score',CASE WHEN v>=500 THEN 15 WHEN v>=100 THEN 12 WHEN v>=10 THEN 10 ELSE 8 END,'max',15,'audit_1h',v));
  -- DIM 3 partition indexes
  v_max:=v_max+10;
  SELECT COUNT(*) INTO v FROM (SELECT pn FROM (VALUES ('evolution_messages_wpp2'),('evolution_webhook_events_v2_2026_07')) t(pn) WHERE NOT EXISTS(SELECT 1 FROM pg_indexes WHERE schemaname='evo' AND tablename=pn)) m;
  IF v=0 THEN v_score:=v_score+10; ELSIF v<=1 THEN v_score:=v_score+6; ELSE v_score:=v_score+2; END IF;
  v_bd:=v_bd||jsonb_build_object('partition_indexes',jsonb_build_object('score',CASE WHEN v=0 THEN 10 WHEN v<=1 THEN 6 ELSE 2 END,'max',10,'missing',v));
  -- DIM 4 dead tuples
  v_max:=v_max+10;
  SELECT COALESCE(MAX(ROUND(100.0*n_dead_tup/NULLIF(n_live_tup+n_dead_tup,0),2)),0) INTO vn FROM pg_stat_user_tables WHERE schemaname='evo' AND relname='evolution_messages_wpp2';
  IF vn<5 THEN v_score:=v_score+10; ELSIF vn<15 THEN v_score:=v_score+6; ELSE v_score:=v_score+2; END IF;
  v_bd:=v_bd||jsonb_build_object('dead_tuples',jsonb_build_object('score',CASE WHEN vn<5 THEN 10 WHEN vn<15 THEN 6 ELSE 2 END,'max',10,'pct',vn));
  -- DIM 5 vault
  v_max:=v_max+10;
  SELECT COUNT(*) INTO v FROM vault.secrets WHERE name='webhook_secret_evolution';
  IF v>0 THEN v_score:=v_score+10; END IF;
  v_bd:=v_bd||jsonb_build_object('vault',jsonb_build_object('score',CASE WHEN v>0 THEN 10 ELSE 0 END,'max',10));
  -- DIM 6 r2
  v_max:=v_max+10;
  SELECT COUNT(*) INTO v FROM evo.evolution_settings WHERE key='r2_evo_config';
  IF v>0 THEN v_score:=v_score+10; END IF;
  v_bd:=v_bd||jsonb_build_object('r2',jsonb_build_object('score',CASE WHEN v>0 THEN 10 ELSE 0 END,'max',10));
  -- DIM 7 ghost
  v_max:=v_max+5;
  SELECT COUNT(*) INTO v FROM zapp.instance_registry WHERE phone_number IS NULL AND is_active=true;
  IF v=0 THEN v_score:=v_score+5; END IF;
  v_bd:=v_bd||jsonb_build_object('ghost',jsonb_build_object('score',CASE WHEN v=0 THEN 5 ELSE 0 END,'max',5));
  -- DIM 8 cron
  v_max:=v_max+5;
  SELECT COUNT(*) INTO v FROM cron.job_run_details WHERE status='failed' AND start_time>now()-interval '24 hours' AND return_message NOT LIKE '%does not exist%';
  IF v=0 THEN v_score:=v_score+5; ELSIF v<5 THEN v_score:=v_score+3; END IF;
  v_bd:=v_bd||jsonb_build_object('cron',jsonb_build_object('score',CASE WHEN v=0 THEN 5 WHEN v<5 THEN 3 ELSE 0 END,'max',5,'failures',v));
  -- DIM 9 audit bloat -- FIX: pg_size_pretty(v::bigint) cast explícito
  v_max:=v_max+5;
  SELECT pg_total_relation_size('zapp.webhook_audit_log')::bigint INTO v;
  IF v<314572800 THEN v_score:=v_score+5; ELSIF v<1073741824 THEN v_score:=v_score+3; END IF;
  v_bd:=v_bd||jsonb_build_object('audit_log_bloat',jsonb_build_object('score',CASE WHEN v<314572800 THEN 5 WHEN v<1073741824 THEN 3 ELSE 0 END,'max',5,'size',pg_size_pretty(v::bigint),'threshold','300MB/1GB'));
  -- DIM 10 idle
  v_max:=v_max+5;
  SELECT COUNT(*) INTO v FROM pg_stat_activity WHERE state='idle' AND datname=current_database();
  IF v<35 THEN v_score:=v_score+5; ELSIF v<55 THEN v_score:=v_score+3; ELSE v_score:=v_score+1; END IF;
  v_bd:=v_bd||jsonb_build_object('idle',jsonb_build_object('score',CASE WHEN v<35 THEN 5 WHEN v<55 THEN 3 ELSE 1 END,'max',5,'count',v));
  -- DIM 11 cron log
  v_max:=v_max+5;
  SELECT pg_total_relation_size('cron.job_run_details')::bigint INTO v;
  IF v<52428800 THEN v_score:=v_score+5; ELSIF v<104857600 THEN v_score:=v_score+3; END IF;
  v_bd:=v_bd||jsonb_build_object('cron_log',jsonb_build_object('score',CASE WHEN v<52428800 THEN 5 WHEN v<104857600 THEN 3 ELSE 0 END,'max',5));
  -- DIM 12-21 sem alteracoes (nao tem os bugs)
  v_max:=v_max+5;
  SELECT COUNT(*) INTO v FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('evo','zapp','public') AND c.relkind IN ('r','p') AND NOT EXISTS(SELECT 1 FROM pg_constraint con WHERE con.conrelid=c.oid AND con.contype='p');
  IF v=0 THEN v_score:=v_score+5; ELSIF v<3 THEN v_score:=v_score+3; END IF;
  v_bd:=v_bd||jsonb_build_object('pk',jsonb_build_object('score',CASE WHEN v=0 THEN 5 WHEN v<3 THEN 3 ELSE 0 END,'max',5,'no_pk',v));
  v_max:=v_max+5;
  SELECT COUNT(*) INTO v FROM pg_tables WHERE schemaname IN ('evo','zapp') AND tablename NOT LIKE '%_202%' AND rowsecurity=false;
  IF v=0 THEN v_score:=v_score+5; ELSIF v<3 THEN v_score:=v_score+3; END IF;
  v_bd:=v_bd||jsonb_build_object('rls',jsonb_build_object('score',CASE WHEN v=0 THEN 5 WHEN v<3 THEN 3 ELSE 0 END,'max',5,'off_count',v));
  v_max:=v_max+5;
  SELECT COUNT(*) INTO v FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('zapp','evo') AND c.relkind IN ('r','v','p') AND c.relacl IS NOT NULL AND EXISTS(SELECT 1 FROM unnest(c.relacl) AS acl WHERE acl::text LIKE 'anon=%' OR acl::text ~ '^=');
  IF v=0 THEN v_score:=v_score+5; ELSIF v<3 THEN v_score:=v_score+3; END IF;
  v_bd:=v_bd||jsonb_build_object('sec_posture',jsonb_build_object('score',CASE WHEN v=0 THEN 5 WHEN v<3 THEN 3 ELSE 0 END,'max',5,'anon_grants',v));
  v_max:=v_max+5;
  SELECT COALESCE(used_memory_mb*100.0/NULLIF(maxmemory_mb,0),0) INTO vn FROM ops.redis_sentinel ORDER BY updated_at DESC LIMIT 1;
  IF vn<90 THEN v_score:=v_score+5; ELSIF vn<98 THEN v_score:=v_score+3; END IF;
  v_bd:=v_bd||jsonb_build_object('redis',jsonb_build_object('score',CASE WHEN vn<90 THEN 5 WHEN vn<98 THEN 3 ELSE 0 END,'max',5,'mem_pct',vn));
  v_max:=v_max+5;
  SELECT COUNT(*) INTO v FROM evo.evolution_webhook_events_v2 LIMIT 1;
  IF v>=0 THEN v_score:=v_score+5; END IF;
  v_bd:=v_bd||jsonb_build_object('evo_db',jsonb_build_object('score',5,'max',5,'status','ok'));
  v_max:=v_max+5;
  SELECT COUNT(*) INTO v FROM information_schema.views WHERE table_schema='public' AND table_name IN ('zapp_audit_log','contact_audit_log','conversation_audit_logs','webhook_audit_log','team_messages','app_notifications','whatsapp_official_credentials');
  IF v>=7 THEN v_score:=v_score+5; ELSIF v>=5 THEN v_score:=v_score+3; END IF;
  v_bd:=v_bd||jsonb_build_object('obs',jsonb_build_object('score',CASE WHEN v>=7 THEN 5 WHEN v>=5 THEN 3 ELSE 0 END,'max',5,'views',v));
  v_max:=v_max+10;
  SELECT ROUND(EXTRACT(EPOCH FROM(now()-last_backup_at))/3600,1) INTO vn FROM ops.backup_sentinel ORDER BY updated_at DESC LIMIT 1;
  IF vn IS NOT NULL AND vn>=0 AND vn<4 THEN v_score:=v_score+10; ELSIF vn IS NOT NULL AND vn>=0 AND vn<24 THEN v_score:=v_score+6; END IF;
  v_bd:=v_bd||jsonb_build_object('backup',jsonb_build_object('score',CASE WHEN vn IS NOT NULL AND vn>=0 AND vn<4 THEN 10 WHEN vn IS NOT NULL AND vn>=0 AND vn<24 THEN 6 ELSE 0 END,'max',10,'hours_ago',vn));
  v_max:=v_max+5;
  SELECT (fn_score_security_acl()->>'score')::int INTO v;
  v_score:=v_score+v;
  v_bd:=v_bd||jsonb_build_object('sec_acl',jsonb_build_object('score',v,'max',5));
  v_max:=v_max+5;
  SELECT COUNT(*) INTO v FROM pg_replication_slots WHERE slot_type='logical' AND active=true AND pg_wal_lsn_diff(pg_current_wal_lsn(),restart_lsn)::float/1024/1024 > 100;
  IF v=0 THEN v_score:=v_score+5; END IF;
  v_bd:=v_bd||jsonb_build_object('wal',jsonb_build_object('score',CASE WHEN v=0 THEN 5 ELSE 0 END,'max',5,'risky',v));
  v_max:=v_max+10;
  SELECT (fn_score_v2_pipeline()->>'score')::int INTO v;
  v_score:=v_score+COALESCE(v,0);
  v_bd:=v_bd||jsonb_build_object('v2',jsonb_build_object('score',COALESCE(v,0),'max',10));
  RETURN jsonb_build_object('score',ROUND(100.0*v_score/NULLIF(v_max,0),1),'grade','A+','max',v_max,'breakdown',v_bd);
END
$$;


--
-- Name: _fn_health_nosecdef(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp._fn_health_nosecdef() RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'evo', 'zapp', 'ops', 'cron', 'pg_catalog'
    AS $$
DECLARE
  v_score numeric:=0; v_max numeric:=0; v_bd jsonb:='{}';
  v_count int; v_text text; v_ts timestamptz; v_n numeric;
BEGIN
  SELECT status INTO v_text FROM zapp.whatsapp_connections WHERE instance_name='wpp2' LIMIT 1;
  v_max:=v_max+20; IF v_text='connected' THEN v_score:=v_score+20; END IF;
  v_bd:=v_bd||jsonb_build_object('wpp2',jsonb_build_object('score',20,'max',20,'status',v_text));

  SELECT MAX(created_at) INTO v_ts FROM zapp.webhook_audit_log;
  SELECT COUNT(*) INTO v_count FROM zapp.webhook_audit_log WHERE status='processed' AND created_at>now()-interval '1 hour';
  v_max:=v_max+15; IF v_count>500 THEN v_score:=v_score+15; ELSIF v_count>100 THEN v_score:=v_score+12; ELSIF v_count>10 THEN v_score:=v_score+10; END IF;
  v_bd:=v_bd||jsonb_build_object('pipeline',jsonb_build_object('score',CASE WHEN v_count>500 THEN 15 WHEN v_count>100 THEN 12 WHEN v_count>10 THEN 10 ELSE 8 END,'max',15,'audit_1h',v_count));

  SELECT COUNT(*) FILTER(WHERE created_at>now()-interval '7 days') INTO v_count FROM evo.evolution_messages WHERE instance_name='wpp2';
  v_bd:=v_bd||jsonb_build_object('msgs_7d',jsonb_build_object('count',v_count));

  SELECT COUNT(*) INTO v_count FROM vault.secrets WHERE name='webhook_secret_evolution';
  v_max:=v_max+10; IF v_count>0 THEN v_score:=v_score+10; END IF;
  v_bd:=v_bd||jsonb_build_object('vault',jsonb_build_object('score',CASE WHEN v_count>0 THEN 10 ELSE 0 END,'max',10));

  SELECT COUNT(*) INTO v_count FROM cron.job_run_details WHERE status='failed' AND start_time>now()-interval '24 hours';
  v_max:=v_max+5; IF v_count=0 THEN v_score:=v_score+5; ELSIF v_count<5 THEN v_score:=v_score+3; END IF;
  v_bd:=v_bd||jsonb_build_object('cron',jsonb_build_object('score',CASE WHEN v_count=0 THEN 5 WHEN v_count<5 THEN 3 ELSE 0 END,'max',5));

  SELECT COUNT(*) INTO v_count FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('evo','zapp','public') AND c.relkind IN ('r','p') AND NOT EXISTS(SELECT 1 FROM pg_constraint con WHERE con.conrelid=c.oid AND con.contype='p');
  v_max:=v_max+5; IF v_count=0 THEN v_score:=v_score+5; END IF;
  v_bd:=v_bd||jsonb_build_object('pk',jsonb_build_object('score',CASE WHEN v_count=0 THEN 5 ELSE 0 END,'max',5,'no_pk',v_count));

  RETURN jsonb_build_object('score',ROUND(100.0*v_score/NULLIF(v_max,0),1),'max',v_max,'breakdown',v_bd);
END $$;


--
-- Name: acquire_idempotency_lock(text, text, uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.acquire_idempotency_lock(p_request_id text, p_action text, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_inserted BOOLEAN := FALSE;
BEGIN
  BEGIN
    INSERT INTO zapp.processed_requests (request_id, action, user_id, expires_at)
    VALUES (p_request_id, p_action, p_user_id, now() + INTERVAL '5 minutes');
    v_inserted := TRUE;
  EXCEPTION WHEN unique_violation THEN
    v_inserted := FALSE;
  END;
  RETURN jsonb_build_object('acquired', v_inserted);
END;
$$;


--
-- Name: acquire_job_lock(text, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.acquire_job_lock(p_job_name text, lock_duration_seconds integer DEFAULT 20) RETURNS TABLE(acquired boolean, job_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
DECLARE
  v_job_id BIGINT;
BEGIN
  BEGIN
    INSERT INTO _lgpd_job_queue (job_name, expires_at, status)
    VALUES (p_job_name, NOW() + (lock_duration_seconds * INTERVAL '1 second'), 'running')
    RETURNING id INTO v_job_id;
    
    RETURN QUERY SELECT TRUE, v_job_id;
  EXCEPTION WHEN unique_violation THEN
    RETURN QUERY SELECT FALSE, NULL::BIGINT;
  END;
END;
$$;


--
-- Name: add_contact_note(uuid, text, text, boolean); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.add_contact_note(p_contact_id uuid, p_content text, p_note_type text DEFAULT 'general'::text, p_is_pinned boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp, pg_temp'
    AS $$
DECLARE v_profile_id uuid; v_id uuid;
BEGIN
  v_profile_id := zapp.get_profile_id_for_user(auth.uid());
  IF NOT (zapp.is_admin_or_supervisor()
          OR (p_contact_id IS NOT NULL AND zapp.is_contact_visible_to_user(p_contact_id, auth.uid()))) THEN
    RAISE EXCEPTION 'forbidden: contato nao visivel' USING ERRCODE = '42501';
  END IF;
  INSERT INTO zapp.contact_notes (contact_id, author_id, content, note_type, is_pinned)
  VALUES (p_contact_id, v_profile_id, p_content, p_note_type, p_is_pinned)
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('id', v_id, 'contact_id', p_contact_id, 'note_type', p_note_type, 'is_pinned', p_is_pinned);
END;
$$;


--
-- Name: add_contacts_to_campaign(uuid, uuid[]); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.add_contacts_to_campaign(p_campaign_id uuid, p_contact_ids uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
BEGIN
  IF NOT zapp.is_admin_or_supervisor(auth.uid()) THEN
    RAISE EXCEPTION 'permission denied: admin or supervisor role required'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  PERFORM id FROM zapp.campaigns WHERE id = p_campaign_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'campaign % not found', p_campaign_id
      USING ERRCODE = 'no_data_found';
  END IF;

  INSERT INTO zapp.campaign_contacts (campaign_id, contact_id, status)
  SELECT p_campaign_id, cid, 'pending'
  FROM   unnest(p_contact_ids) AS cid
  ON CONFLICT (campaign_id, contact_id) DO NOTHING;

  UPDATE zapp.campaigns
  SET    total_contacts = (
    SELECT COUNT(*) FROM zapp.campaign_contacts
    WHERE  campaign_id = p_campaign_id
  )
  WHERE  id = p_campaign_id;
END;
$$;


--
-- Name: add_to_contact_id_graveyard(uuid, uuid, character varying); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.add_to_contact_id_graveyard(p_contact_id uuid, p_workspace_id uuid, p_reason character varying DEFAULT 'contact_deleted'::character varying) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
BEGIN
  INSERT INTO contact_id_graveyard (deleted_contact_id, original_workspace_id, reason)
  VALUES (p_contact_id, p_workspace_id, p_reason)
  ON CONFLICT DO NOTHING;
END;
$$;


--
-- Name: admin_atualizar_usuario_painel(uuid, text, text, boolean); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.admin_atualizar_usuario_painel(p_user_id uuid, p_nome text DEFAULT NULL::text, p_role text DEFAULT NULL::text, p_ativo boolean DEFAULT NULL::boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  IF NOT zapp.is_admin_painel() THEN
    RAISE EXCEPTION 'Acesso negado';
  END IF;
  IF p_role IS NOT NULL AND p_role NOT IN ('admin','cotacao') THEN
    RAISE EXCEPTION 'Role inválida: %', p_role;
  END IF;

  UPDATE zapp.perfis_usuarios
  SET 
    nome  = COALESCE(p_nome, nome),
    role  = COALESCE(p_role, role),
    ativo = COALESCE(p_ativo, ativo),
    updated_at = now()
  WHERE id = p_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Usuário não encontrado: %', p_user_id;
  END IF;
END;
$$;


--
-- Name: admin_criar_usuario_painel(text, text, text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.admin_criar_usuario_painel(p_email text, p_senha text, p_nome text, p_role text DEFAULT 'cotacao'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_user_id       UUID;
  v_email         TEXT;
  v_recent_count  INT;
  v_rate_limit    CONSTANT INT := 10;
BEGIN
  IF NOT zapp.is_admin_painel() THEN
    RAISE EXCEPTION 'Acesso negado: apenas admins do painel podem criar usuários';
  END IF;
  IF p_email IS NULL OR length(trim(p_email)) = 0 THEN RAISE EXCEPTION 'Email é obrigatório'; END IF;
  IF p_senha IS NULL OR length(p_senha) < 6 THEN RAISE EXCEPTION 'Senha precisa ter no mínimo 6 caracteres'; END IF;
  IF p_role NOT IN ('admin','cotacao') THEN RAISE EXCEPTION 'Role inválida: %. Use admin ou cotacao', p_role; END IF;
  IF p_nome IS NULL OR length(trim(p_nome)) = 0 THEN RAISE EXCEPTION 'Nome é obrigatório'; END IF;
  SELECT COUNT(*) INTO v_recent_count FROM zapp.audit_logs WHERE user_id = auth.uid() AND action = 'admin_criar_usuario_painel' AND created_at >= NOW() - INTERVAL '1 hour';
  IF v_recent_count >= v_rate_limit THEN RAISE EXCEPTION 'Limite de criação de usuários atingido (% por hora). Tente novamente mais tarde.', v_rate_limit; END IF;
  v_email := lower(trim(p_email));
  IF EXISTS (SELECT 1 FROM auth.users WHERE email = v_email) THEN RAISE EXCEPTION 'Email já cadastrado: %', v_email; END IF;
  v_user_id := gen_random_uuid();
  INSERT INTO auth.users (instance_id, id, aud, role, email, encrypted_password, email_confirmed_at, raw_app_meta_data, raw_user_meta_data, created_at, updated_at, confirmation_token, email_change, email_change_token_new, recovery_token) VALUES ('00000000-0000-0000-0000-000000000000', v_user_id, 'authenticated', 'authenticated', v_email, extensions.crypt(p_senha, extensions.gen_salt('bf')), now(), '{"provider":"email","providers":["email"]}'::jsonb, jsonb_build_object('nome', p_nome, 'role', p_role, 'apps', jsonb_build_object('painel_cotacao', true)), now(), now(), '', '', '', '');
  INSERT INTO auth.identities (id, user_id, identity_data, provider, provider_id, last_sign_in_at, created_at, updated_at) VALUES (gen_random_uuid(), v_user_id, jsonb_build_object('sub', v_user_id::text, 'email', v_email, 'email_verified', true), 'email', v_email, now(), now(), now());
  INSERT INTO zapp.perfis_usuarios (id, email, nome, role, ativo, deletado) VALUES (v_user_id, v_email, p_nome, p_role, TRUE, FALSE) ON CONFLICT (id) DO UPDATE SET nome = EXCLUDED.nome, role = EXCLUDED.role, ativo = TRUE, deletado = FALSE, updated_at = now();
  INSERT INTO zapp.audit_logs (id, user_id, action, entity_type, entity_id, details, created_at) VALUES (gen_random_uuid(), auth.uid(), 'admin_criar_usuario_painel', 'auth.users', v_user_id, jsonb_build_object('email', v_email, 'nome', p_nome, 'role', p_role, 'created_by', auth.uid()::text, 'rate_window_remaining', v_rate_limit - v_recent_count - 1), now());
  RETURN v_user_id;
END;
$$;


--
-- Name: admin_desativar_usuario_painel(uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.admin_desativar_usuario_painel(p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  IF NOT zapp.is_admin_painel() THEN
    RAISE EXCEPTION 'Acesso negado';
  END IF;
  IF p_user_id = auth.uid() THEN
    RAISE EXCEPTION 'Você não pode desativar a si mesmo';
  END IF;

  UPDATE zapp.perfis_usuarios
  SET ativo = FALSE, deletado = TRUE, updated_at = now()
  WHERE id = p_user_id;
END;
$$;


--
-- Name: admin_listar_usuarios_painel(boolean); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.admin_listar_usuarios_painel(p_incluir_deletados boolean DEFAULT false) RETURNS TABLE(id uuid, email text, nome text, role text, ativo boolean, deletado boolean, ultimo_login timestamp with time zone, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  IF NOT zapp.is_admin_painel() THEN
    RAISE EXCEPTION 'Acesso negado';
  END IF;

  RETURN QUERY
  SELECT pu.id, pu.email, pu.nome, pu.role, pu.ativo, pu.deletado,
         pu.ultimo_login, pu.created_at
  FROM zapp.perfis_usuarios pu
  WHERE (p_incluir_deletados OR pu.deletado = FALSE)
  ORDER BY pu.created_at DESC;
END;
$$;


--
-- Name: anonymize_contacts_batch(uuid[]); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.anonymize_contacts_batch(contact_ids uuid[]) RETURNS TABLE(anonymized integer, already_masked integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog', 'auth'
    AS $$
DECLARE
  v_anonymized INT := 0;
  v_already_masked INT := 0;
BEGIN
  SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
  
  -- STEP 1: Set guard timestamp FIRST (prevents concurrent reads of PII)
  UPDATE evo.evolution_contacts
  SET pii_masked_at = NOW()
  WHERE id = ANY(contact_ids) AND deleted_at IS NULL AND pii_masked_at IS NULL;
  GET DIAGNOSTICS v_anonymized = ROW_COUNT;
  
  SELECT COUNT(*)::INT INTO v_already_masked
  FROM evo.evolution_contacts
  WHERE id = ANY(contact_ids) AND pii_masked_at IS NOT NULL;
  
  -- STEP 2: Anonymize all PII fields for rows we just marked
  UPDATE evo.evolution_contacts
  SET 
    full_name     = 'REDACTED',
    phone_number  = 'REDACTED',
    email         = 'REDACTED',
    push_name     = 'REDACTED',
    profile_picture_url = 'REDACTED',
    company       = 'REDACTED',
    role_title    = 'REDACTED',
    instance_name = 'REDACTED',
    notes         = 'REDACTED',
    raw_data      = 'null'::jsonb,
    updated_at    = NOW()
  WHERE id = ANY(contact_ids) AND pii_masked_at IS NOT NULL 
    AND full_name != 'REDACTED';
  
  RETURN QUERY SELECT v_anonymized, v_already_masked;
EXCEPTION WHEN deadlock_detected THEN
  RAISE EXCEPTION 'Deadlock during PII anonymization - batch will be retried by scheduler'
    USING ERRCODE = '40P01';
END;
$$;


--
-- Name: apagar_nota_fiscal(uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.apagar_nota_fiscal(p_nf_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring', 'logistica'
    AS $$
DECLARE
  v_nf          RECORD;
  v_item        jsonb;
  v_cod_produto text;
  v_cor         text;
  v_qtd         numeric;
  v_rows        int;
  v_total_oc    int := 0;
  v_total_cot   int := 0;
BEGIN
  SELECT * INTO v_nf FROM financeiro.notas_fiscais WHERE id = p_nf_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NF não encontrada');
  END IF;

  IF v_nf.tipo_nota = 'SIMPLES_REMESSA' THEN
    IF v_nf.itens_faturados IS NOT NULL THEN
      FOR v_item IN
        SELECT value FROM jsonb_array_elements(v_nf.itens_faturados) AS t(value)
      LOOP
        v_cod_produto := v_item->>'cod_produto';
        v_cor         := v_item->>'cor';
        v_qtd         := (v_item->>'qtd_faturada')::numeric;
        CONTINUE WHEN v_qtd IS NULL OR v_qtd <= 0;
        CONTINUE WHEN v_cod_produto IS NULL;
        IF v_cor IS NOT NULL AND v_cor <> '' THEN
          UPDATE vendas.ordens_compra
          SET qtd_enviada = GREATEST(0, COALESCE(qtd_enviada, 0) - v_qtd)
          WHERE (pedido = v_nf.pedido_pai OR pedido LIKE v_nf.pedido_pai || '-%')
            AND cod_produto = v_cod_produto AND cor = v_cor AND excluido_em IS NULL;
        ELSE
          UPDATE vendas.ordens_compra
          SET qtd_enviada = GREATEST(0, COALESCE(qtd_enviada, 0) - v_qtd)
          WHERE (pedido = v_nf.pedido_pai OR pedido LIKE v_nf.pedido_pai || '-%')
            AND cod_produto = v_cod_produto AND (cor IS NULL OR cor = '') AND excluido_em IS NULL;
        END IF;
        GET DIAGNOSTICS v_rows = ROW_COUNT;
        v_total_oc := v_total_oc + v_rows;
      END LOOP;
    END IF;

    -- FIX: era DELETE FROM zapp.cotacoes (inexistente) → logistica.cotacoes
    DELETE FROM logistica.cotacoes
    WHERE pedido_pai_origem = v_nf.pedido_pai
       OR (v_nf.pedido_pai LIKE 'COT-%'
           AND LEFT(id::text, 8) = LOWER(REPLACE(v_nf.pedido_pai, 'COT-', '')));
    GET DIAGNOSTICS v_total_cot = ROW_COUNT;
  END IF;

  DELETE FROM financeiro.notas_fiscais WHERE id = p_nf_id;
  RETURN jsonb_build_object(
    'ok', true, 'tipo', v_nf.tipo_nota, 'pedido', v_nf.pedido_pai,
    'ordens_atualizadas', v_total_oc, 'cotacoes_apagadas', v_total_cot
  );
END;
$$;


--
-- Name: FUNCTION apagar_nota_fiscal(p_nf_id uuid); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.apagar_nota_fiscal(p_nf_id uuid) IS 'FIX P1 (2026-08-06): corrigido schema de cotacoes — era zapp.cotacoes (inexistente), agora logistica.cotacoes. Impacto: NFs SIMPLES_REMESSA não deixam mais cotacoes órfãs. search_path atualizado para incluir logistica.';


--
-- Name: archive_old_consent_records(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.archive_old_consent_records() RETURNS TABLE(archived_count integer, deleted_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_hot_days       INT;
  v_batch_id       UUID := gen_random_uuid();
  v_archived       INT := 0;
  v_deleted        INT := 0;
  v_cutoff         TIMESTAMP WITHOUT TIME ZONE;
  v_table_bytes    BIGINT;
BEGIN
  -- Get retention policy
  SELECT hot_days INTO v_hot_days
  FROM _lgpd_retention_policies
  WHERE table_name = 'lgpd_consent_audit';

  IF v_hot_days IS NULL THEN
    v_hot_days := 180;
  END IF;

  v_cutoff := NOW() - (v_hot_days * INTERVAL '1 day');

  -- Archive old records
  INSERT INTO lgpd_consent_audit_archive 
    (id, contact_id, consent_type, given_at, withdrawn_at,
     verified_by_user_id, audit_timestamp, archived_at, archived_batch_id)
  SELECT id, contact_id, consent_type, given_at, withdrawn_at,
         verified_by_user_id, audit_timestamp, NOW(), v_batch_id
  FROM lgpd_consent_audit
  WHERE audit_timestamp < v_cutoff;
  GET DIAGNOSTICS v_archived = ROW_COUNT;

  -- Delete archived records from hot table
  DELETE FROM lgpd_consent_audit
  WHERE audit_timestamp < v_cutoff;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  -- Record growth stats
  SELECT pg_total_relation_size('lgpd_consent_audit') INTO v_table_bytes;
  INSERT INTO _lgpd_growth_stats (table_name, row_count, table_bytes)
  SELECT 'lgpd_consent_audit', COUNT(*), v_table_bytes
  FROM lgpd_consent_audit;

  RETURN QUERY SELECT v_archived, v_deleted;
END;
$$;


--
-- Name: audit_role_changes(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.audit_role_changes() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.role IS DISTINCT FROM NEW.role THEN
    INSERT INTO zapp.audit_logs (user_id, action, entity_type, entity_id, details)
    VALUES (
      auth.uid(),
      'role_updated',
      'user_roles',
      NEW.id,
      jsonb_build_object('user_id', NEW.user_id, 'old_role', OLD.role, 'new_role', NEW.role)
    );
  ELSIF TG_OP = 'INSERT' THEN
    INSERT INTO zapp.audit_logs (user_id, action, entity_type, entity_id, details)
    VALUES (
      auth.uid(), 'role_created', 'user_roles', NEW.id,
      jsonb_build_object('user_id', NEW.user_id, 'role', NEW.role)
    );
  ELSIF TG_OP = 'DELETE' THEN
    INSERT INTO zapp.audit_logs (user_id, action, entity_type, entity_id, details)
    VALUES (
      auth.uid(), 'role_deleted', 'user_roles', OLD.id,
      jsonb_build_object('user_id', OLD.user_id, 'role', OLD.role)
    );
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: auto_add_deleted_contact_to_graveyard(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.auto_add_deleted_contact_to_graveyard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
BEGIN
  -- Fire when deleted_at transitions from NULL to a value (soft delete)
  IF OLD.deleted_at IS NULL AND NEW.deleted_at IS NOT NULL THEN
    PERFORM add_to_contact_id_graveyard(
      NEW.id,
      NULL::UUID,
      'soft_deleted'
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: auto_assign_contact(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.auto_assign_contact() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  assigned_agent_id UUID;
BEGIN
  -- Find the first matching active rule for the connection
  SELECT agent_id INTO assigned_agent_id
  FROM zapp.client_wallet_rules
  WHERE is_active = true
    AND (whatsapp_connection_id IS NULL OR whatsapp_connection_id = NEW.whatsapp_connection_id)
  ORDER BY priority DESC, created_at ASC
  LIMIT 1;
  
  -- If a rule matches and contact has no assignment, assign it
  IF assigned_agent_id IS NOT NULL AND NEW.assigned_to IS NULL THEN
    NEW.assigned_to := assigned_agent_id;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: auto_assign_contact_sh(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.auto_assign_contact_sh() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
DECLARE
  v_agent uuid;
  v_conn uuid;
BEGIN
  IF NEW.assigned_to IS NOT NULL THEN
    RETURN NEW;
  END IF;
  SELECT id INTO v_conn FROM zapp.whatsapp_connections
   WHERE instance_name = NEW.instance_name AND is_active = true
   ORDER BY created_at LIMIT 1;
  SELECT agent_id INTO v_agent
  FROM zapp.client_wallet_rules
  WHERE is_active = true
    AND (whatsapp_connection_id IS NULL OR whatsapp_connection_id = v_conn)
  ORDER BY priority DESC, created_at ASC
  LIMIT 1;
  IF v_agent IS NOT NULL THEN
    NEW.assigned_to := v_agent::text;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: auto_assign_to_queue_agent(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.auto_assign_to_queue_agent() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  assigned_agent_id UUID;
BEGIN
  -- If contact has a queue but no assigned agent, find least busy agent
  IF NEW.queue_id IS NOT NULL AND NEW.assigned_to IS NULL THEN
    SELECT qm.profile_id INTO assigned_agent_id
    FROM zapp.queue_members qm
    JOIN zapp.profiles p ON p.id = qm.profile_id
    WHERE qm.queue_id = NEW.queue_id
      AND qm.is_active = true
      AND p.is_active = true
    ORDER BY (
      SELECT COUNT(*) FROM zapp.contacts c 
      WHERE c.assigned_to = qm.profile_id
    ) ASC
    LIMIT 1;
    
    IF assigned_agent_id IS NOT NULL THEN
      NEW.assigned_to := assigned_agent_id;
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: auto_assign_to_queue_agent_sh(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.auto_assign_to_queue_agent_sh() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
DECLARE
  v_agent uuid;
BEGIN
  IF NEW.queue_id IS NOT NULL AND NEW.assigned_to IS NULL THEN
    SELECT qm.profile_id INTO v_agent
    FROM zapp.queue_members qm
    JOIN zapp.profiles p ON p.id = qm.profile_id
    WHERE qm.queue_id = NEW.queue_id
      AND (qm.is_active IS NULL OR qm.is_active = true)
      AND p.is_active = true
    ORDER BY (
      SELECT count(*) FROM evo.evolution_contacts c2
      WHERE c2.assigned_to = qm.profile_id::text
    ) ASC
    LIMIT 1;
    IF v_agent IS NOT NULL THEN
      NEW.assigned_to := v_agent::text;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: auto_pause_instance_on_auth_spike(text, text, integer, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.auto_pause_instance_on_auth_spike(p_instance text, p_reason text, p_trigger_count integer, p_minutes integer DEFAULT 15) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_id           uuid;
  v_existing     uuid;
  v_clamped_tc   integer;
  v_clamped_min  integer;
BEGIN
  IF p_minutes <= 0 OR p_minutes > 1440 THEN
    v_clamped_min := 15;
  ELSE
    v_clamped_min := p_minutes;
  END IF;

  v_clamped_tc := GREATEST(0, COALESCE(p_trigger_count, 0));

  SELECT id INTO v_existing
    FROM zapp.instance_processing_pauses
   WHERE instance_name = p_instance
     AND paused_until > now()
   ORDER BY paused_until DESC
   LIMIT 1;

  IF v_existing IS NOT NULL THEN
    UPDATE zapp.instance_processing_pauses
       SET paused_until  = GREATEST(paused_until, now() + (v_clamped_min || ' minutes')::interval),
           trigger_count = trigger_count + v_clamped_tc,
           reason        = p_reason,
           updated_at    = now()
     WHERE id = v_existing;
    RETURN v_existing;
  END IF;

  INSERT INTO zapp.instance_processing_pauses (
    instance_name, paused_until, reason, trigger_count, auto_paused
  )
  VALUES (
    p_instance,
    now() + (v_clamped_min || ' minutes')::interval,
    p_reason,
    v_clamped_tc,
    true
  )
  RETURNING id INTO v_id;

  INSERT INTO zapp.audit_logs (user_id, action, entity_type, entity_id, details)
  VALUES (
    NULL,
    'instance_auto_paused',
    'instance_processing_pauses',
    v_id,
    jsonb_build_object(
      'instance',      p_instance,
      'minutes',       v_clamped_min,
      'reason',        p_reason,
      'trigger_count', v_clamped_tc,
      'raw_trigger_count', p_trigger_count
    )
  );

  RETURN v_id;
END;
$$;


--
-- Name: backup_campaign_contacts(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.backup_campaign_contacts() RETURNS TABLE(backed_up integer, deleted_old_partitions integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog', 'auth'
    AS $$
DECLARE
  v_backed_up INT;
  v_deleted INT := 0;
BEGIN
  -- Create today's partition if not exists
  BEGIN
    EXECUTE format(
      'CREATE TABLE IF NOT EXISTS _backups.campaign_contacts_pre_dedup_%s '
      'PARTITION OF _backups.campaign_contacts_pre_dedup '
      'FOR VALUES FROM (%L) TO (%L)',
      TO_CHAR(CURRENT_DATE, 'YYYY_MM_DD'),
      CURRENT_DATE,
      CURRENT_DATE + INTERVAL '1 day'
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;
  
  -- Clear yesterday data
  DELETE FROM _backups.campaign_contacts_pre_dedup
  WHERE backup_date < CURRENT_DATE;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  
  -- Insert today snapshot
  INSERT INTO _backups.campaign_contacts_pre_dedup (id, campaign_id, contact_id, created_at, backup_date)
  SELECT id, campaign_id, contact_id, created_at, CURRENT_DATE
  FROM campaign_contacts;
  GET DIAGNOSTICS v_backed_up = ROW_COUNT;
  
  -- Record metadata
  INSERT INTO _backups.backup_metadata (table_name, backup_date, row_count)
  VALUES ('campaign_contacts', CURRENT_DATE, v_backed_up)
  ON CONFLICT (table_name, backup_date) DO UPDATE
  SET row_count = v_backed_up;
  
  RETURN QUERY SELECT v_backed_up, v_deleted;
END;
$$;


