--
-- Name: bpm_process_recurrences(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.bpm_process_recurrences() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_rec RECORD; v_count int:=0;
BEGIN
  FOR v_rec IN SELECT r.*,c.flow_id,c.workspace_id,c.title,c.assignee_id,c.priority FROM bpm_card_recurrences r JOIN bpm_cards c ON r.card_id=c.id WHERE r.is_active AND r.next_execution_at<=NOW() AND (r.end_date IS NULL OR r.end_date>NOW()) AND (r.max_occurrences IS NULL OR r.current_occurrences<r.max_occurrences) LOOP
    IF v_rec.behavior='create_new' THEN
      INSERT INTO bpm_cards (flow_id,current_step_id,workspace_id,title,assignee_id,priority,origin,created_by) SELECT v_rec.flow_id,(SELECT id FROM bpm_flow_steps WHERE flow_id=v_rec.flow_id AND is_initial LIMIT 1),v_rec.workspace_id,v_rec.title||' (rec #'||(v_rec.current_occurrences+1)||')',v_rec.assignee_id,v_rec.priority,'recurrence',v_rec.created_by;
    ELSE
      UPDATE bpm_cards SET current_step_id=(SELECT id FROM bpm_flow_steps WHERE flow_id=v_rec.flow_id AND is_initial LIMIT 1),status='active',completed_at=NULL,updated_at=NOW() WHERE id=v_rec.card_id;
    END IF;
    UPDATE bpm_card_recurrences SET current_occurrences=current_occurrences+1,last_executed_at=NOW(),next_execution_at=CASE v_rec.frequency WHEN 'daily' THEN next_execution_at+(v_rec.interval_value||' days')::interval WHEN 'weekly' THEN next_execution_at+(v_rec.interval_value*7||' days')::interval WHEN 'monthly' THEN next_execution_at+(v_rec.interval_value||' months')::interval ELSE next_execution_at+'1 day'::interval END WHERE id=v_rec.id;
    v_count:=v_count+1;
  END LOOP;
  RETURN v_count;
END; $$;


--
-- Name: bpm_refresh_dashboards(); Type: FUNCTION; Schema: zapp; Owner: -
