BEGIN RETURN (SELECT COALESCE(jsonb_agg(jsonb_build_object('id',c.id,'title',c.title,'card_number',c.card_number,'status',c.status,'flow_name',f.name,'step_name',s.name)),'[]'::jsonb) FROM bpm_cards c JOIN bpm_flows f ON c.flow_id=f.id JOIN bpm_flow_steps s ON c.current_step_id=s.id WHERE c.workspace_id=p_workspace_id AND c.deleted_at IS NULL AND (c.title ILIKE '%'||p_query||'%' OR c.card_number::text=p_query) ORDER BY c.updated_at DESC LIMIT p_limit);
END; $$;


