--
-- Name: bulk_add_tag(uuid[], text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.bulk_add_tag(p_contact_ids uuid[], p_tag text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp, pg_temp'
    AS $$
DECLARE v_tag_id uuid; v_added integer := 0;
BEGIN
  IF NOT zapp.is_admin_or_supervisor() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  SELECT id INTO v_tag_id FROM zapp.tags WHERE name = p_tag LIMIT 1;
  IF v_tag_id IS NULL THEN
    INSERT INTO zapp.tags (name) VALUES (p_tag) RETURNING id INTO v_tag_id;
  END IF;
  INSERT INTO zapp.contact_tags (contact_id, tag_id)
  SELECT cid, v_tag_id FROM unnest(p_contact_ids) AS cid
  WHERE NOT EXISTS (SELECT 1 FROM zapp.contact_tags ct WHERE ct.contact_id = cid AND ct.tag_id = v_tag_id);
  GET DIAGNOSTICS v_added = ROW_COUNT;
  RETURN jsonb_build_object('added', v_added, 'tag_id', v_tag_id);
END;
$$;


--
-- Name: bulk_auto_merge_duplicates(text, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.bulk_auto_merge_duplicates(p_instance_name text, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_grp    record;
  v_primary uuid;
  v_sec    uuid;
  v_groups int := 0;
  v_merged int := 0;
  v_res    jsonb;
BEGIN
  -- [SEC 2026-08-01] Guard de autorização:
  -- Authenticated deve ser admin ou supervisor no workspace.
  -- service_role (auth.uid() IS NULL) passa — operação de backend legítima.
  IF auth.uid() IS NOT NULL AND NOT zapp.is_admin_or_supervisor() THEN
    RAISE EXCEPTION 'forbidden: admin or supervisor role required for bulk merge'
      USING ERRCODE = '42501';
  END IF;

  FOR v_grp IN
    SELECT
      regexp_replace(coalesce(ct.phone_number, ''), '\D', '', 'g') AS pn,
      array_agg(ct.id ORDER BY coalesce(ct.total_messages, 0) DESC, ct.created_at ASC) AS ids
    FROM evo.evolution_contacts ct
    WHERE ct.deleted_at IS NULL
      AND ct.instance_name = p_instance_name
      AND length(regexp_replace(coalesce(ct.phone_number, ''), '\D', '', 'g')) >= 10
    GROUP BY 1
    HAVING count(*) > 1
    ORDER BY count(*) DESC
    LIMIT greatest(p_limit, 1)
  LOOP
    v_groups  := v_groups + 1;
    v_primary := v_grp.ids[1];
    FOREACH v_sec IN ARRAY v_grp.ids[2:array_length(v_grp.ids, 1)] LOOP
      v_res := zapp.merge_contacts(v_primary, v_sec, '{}'::jsonb);
      IF coalesce((v_res ->> 'success')::boolean, false) THEN
        v_merged := v_merged + 1;
      END IF;
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object(
    'success',          true,
    'instance',         p_instance_name,
    'groups_processed', v_groups,
    'contacts_merged',  v_merged
  );
END;
$$;


--
-- Name: FUNCTION bulk_auto_merge_duplicates(p_instance_name text, p_limit integer); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.bulk_auto_merge_duplicates(p_instance_name text, p_limit integer) IS 'FATOR X v6.1.0: auto-merge em lote por instancia; primario = mais mensagens/mais antigo.';


--
-- Name: bulk_lgpd_optout(uuid[], text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.bulk_lgpd_optout(p_contact_ids uuid[], p_reason text DEFAULT 'user_request'::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_count integer;
BEGIN
  UPDATE zapp.contacts
  SET
    lgpd_opt_out_at        = now(),
    lgpd_marketing_consent = false,
    lgpd_data_sharing      = false,
    lgpd_profiling         = false,
    lgpd_last_updated_at   = now(),
    updated_at             = now()
  WHERE id = ANY(p_contact_ids)
    AND workspace_id = (
      SELECT workspace_id FROM zapp.profiles WHERE id = auth.uid()
    )
    AND lgpd_opt_out_at IS NULL;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


--
-- Name: bulk_soft_delete_contacts(uuid[], text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.bulk_soft_delete_contacts(p_contact_ids uuid[], p_reason text DEFAULT 'bulk_deletion'::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_count integer;
BEGIN
  IF NOT zapp.is_admin_or_supervisor(auth.uid()) THEN
    RAISE EXCEPTION 'permission denied: admin or supervisor required';
  END IF;
  IF array_length(p_contact_ids, 1) > 500 THEN
    RAISE EXCEPTION 'Maximum 500 contacts per bulk operation. Got: %', array_length(p_contact_ids, 1);
  END IF;
  UPDATE evo.evolution_contacts
  SET
    deleted_at     = now(),
    deleted_reason = p_reason,
    updated_at     = now()
  WHERE id = ANY(p_contact_ids)
    AND deleted_at IS NULL;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


