    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$ SELECT zapp.is_manager_or_above(_user_id) OR ( zapp.has_role(_user_id, 'supervisor') AND zapp.get_user_department(_user_id) IS NOT NULL AND EXISTS ( SELECT 1 FROM zapp.contacts c JOIN zapp.profiles p ON p.id::text = c.assigned_to WHERE c.id = _contact_id AND p.department_id = zapp.get_user_department(_user_id) ) ) OR EXISTS ( SELECT 1 FROM zapp.contacts c JOIN zapp.profiles p ON p.id::text = c.assigned_to WHERE c.id = _contact_id AND p.user_id = _user_id ); $$;


