--
-- Name: check_duplicate_request(text, text, uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.check_duplicate_request(p_request_id text, p_action text, p_user_id uuid) RETURNS TABLE(is_duplicate boolean, status_code integer, cached_result jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_rec zapp.processed_requests%ROWTYPE;
BEGIN
  SELECT * INTO v_rec
  FROM   zapp.processed_requests
  WHERE  request_id = p_request_id
    AND  action     = p_action
    AND  user_id    = p_user_id
    AND  expires_at > now()
  LIMIT 1;
  IF FOUND THEN
    RETURN QUERY SELECT TRUE, v_rec.result_status, v_rec.result_payload;
  ELSE
    RETURN QUERY SELECT FALSE, NULL::INTEGER, NULL::JSONB;
  END IF;
END;
$$;


--
-- Name: check_user_permission(text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.check_user_permission(p_permission_name text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
    v_has_permission BOOLEAN;
BEGIN
    SELECT EXISTS (
        SELECT 1 FROM zapp.role_permissions rp
        JOIN zapp.user_roles ur ON ur.role = rp.role
        JOIN zapp.permissions p ON p.id = rp.permission_id
        WHERE ur.user_id = auth.uid() AND p.name = p_permission_name
    ) INTO v_has_permission;
    IF NOT v_has_permission THEN
        PERFORM zapp.log_security_event('unauthorized_access', 'permission:' || p_permission_name, 'EXECUTE', 'denied');
    END IF;
    RETURN v_has_permission;
END;
$$;


