--

CREATE FUNCTION zapp.contacts_count_by_type() RETURNS TABLE(contact_type text, count bigint)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
  -- v2 2026-07-02: coluna renomeada lead_status→contact_type + alinhado com view contacts.
  -- Antes: UI lia coluna lead_status do RPC e comparava com contact_type da view
  -- (hardcoded 'cliente') → contagens nunca casavam com filtros → tabs mostravam wrong counts.
  SELECT COALESCE(lead_status, 'open')::text AS contact_type, count(*)::bigint
  FROM evo.evolution_contacts
  WHERE deleted_at IS NULL
  GROUP BY lead_status
  ORDER BY 2 DESC;
$$;


