--
-- Name: create_pagination_cursor(character varying, uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.create_pagination_cursor(p_table_name character varying, p_last_record_id uuid) RETURNS character varying
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_cursor_id VARCHAR(64);
BEGIN
  v_cursor_id := encode(
    digest(
      p_table_name || '::' || COALESCE(p_last_record_id::TEXT, 'NULL') || '::' || NOW()::TEXT,
      'sha256'
    ),
    'hex'
  );

  INSERT INTO _pagination_state (cursor_id, table_name, last_record_id, created_by)
  VALUES (v_cursor_id, p_table_name, p_last_record_id, auth.uid())
  ON CONFLICT (cursor_id) DO UPDATE SET
    last_seen_at = NOW(),
    expires_at   = NOW() + INTERVAL '1 hour';

  RETURN v_cursor_id;
END;
$$;


--
-- Name: current_user_is_privileged(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.current_user_is_privileged() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER LEAKPROOF
