--
-- Name: decode_html_entities(text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.decode_html_entities(p_input text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_result TEXT;
BEGIN
  v_result := p_input;
  v_result := REPLACE(v_result, '&lt;',   '<');
  v_result := REPLACE(v_result, '&gt;',   '>');
  v_result := REPLACE(v_result, '&amp;',  '&');
  v_result := REPLACE(v_result, '&quot;', '"');
  v_result := REPLACE(v_result, '&apos;', '''');
  v_result := REPLACE(v_result, '&nbsp;', ' ');
  RETURN v_result;
END;
$$;


