END;
$$;


--
-- Name: deduplicate_campaign_contacts_atomically(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.deduplicate_campaign_contacts_atomically() RETURNS TABLE(duplicates_removed integer, rows_locked integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog', 'auth'
    AS $$
DECLARE
  v_duplicates_removed INT := 0;
  v_rows_locked INT := 0;
  v_duplicate_ids UUID[];
BEGIN
  SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
  LOCK TABLE campaign_contacts IN SHARE ROW EXCLUSIVE MODE;
  
  SELECT ARRAY_AGG(id)
  INTO v_duplicate_ids
  FROM (
    SELECT id, campaign_id, contact_id,
           ROW_NUMBER() OVER (
             PARTITION BY campaign_id, contact_id 
             ORDER BY created_at DESC
           ) AS rn
    FROM campaign_contacts
  ) t
  WHERE rn > 1;

  IF v_duplicate_ids IS NOT NULL THEN
    SELECT COUNT(*)::INT INTO v_rows_locked
    FROM campaign_contacts
    WHERE id = ANY(v_duplicate_ids);

    IF v_rows_locked = 0 THEN
      RAISE EXCEPTION 'Snapshot inconsistency detected - retry duplicate removal' 
        USING ERRCODE = '40001';
    END IF;
  END IF;
  
  IF v_duplicate_ids IS NOT NULL THEN
    DELETE FROM campaign_contacts
    WHERE id = ANY(v_duplicate_ids);
    GET DIAGNOSTICS v_duplicates_removed = ROW_COUNT;
  END IF;
  
  RETURN QUERY SELECT v_duplicates_removed, v_rows_locked;
EXCEPTION WHEN serialization_failure THEN
  RAISE NOTICE 'Serialization failure during deduplication - client should retry';
  RETURN QUERY SELECT 0, 0;
END;
$$;


--
-- Name: delete_contact_completely(uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.delete_contact_completely(p_contact_id uuid) RETURNS TABLE(deleted_rows integer, audit_rows integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog', 'auth'
    AS $$
DECLARE
  v_workspace_id UUID;
  v_deleted_rows INT := 0;
  v_audit_rows INT := 0;
  v_batch INT := 0;
BEGIN
  -- Get workspace before deletion
  SELECT workspace_id INTO v_workspace_id
  FROM evo.evolution_contacts
  WHERE id = p_contact_id AND deleted_at IS NULL;

  -- Add to graveyard FIRST (prevents ID reuse for 7 years)
  PERFORM add_to_contact_id_graveyard(p_contact_id, v_workspace_id, 'lgpd_right_to_be_forgotten');

  -- Preserve audit trail
  INSERT INTO message_audit_log (message_id, contact_id, deleted_reason, deleted_at)
  SELECT id, contact_id, 'LGPD right-to-be-forgotten', NOW()
  FROM realtime.messages 
  WHERE contact_id = p_contact_id;
  GET DIAGNOSTICS v_audit_rows = ROW_COUNT;

  INSERT INTO lgpd_consent_audit (contact_id, consent_type, given_at, withdrawn_at)
  SELECT DISTINCT p_contact_id, consent_type, given_at, NOW()
  FROM lgpd_consent_audit
  WHERE contact_id = p_contact_id AND withdrawn_at IS NULL;

  -- Cascade deletes
  DELETE FROM zapp.conversation_snoozes WHERE contact_id = p_contact_id;
  GET DIAGNOSTICS v_batch = ROW_COUNT; v_deleted_rows := v_deleted_rows + v_batch;

  DELETE FROM zapp.campaign_contacts WHERE contact_id = p_contact_id;
  GET DIAGNOSTICS v_batch = ROW_COUNT; v_deleted_rows := v_deleted_rows + v_batch;

  -- Soft-delete (triggers auto_graveyard if not already added)
  UPDATE evo.evolution_contacts SET deleted_at = NOW() WHERE id = p_contact_id;
  GET DIAGNOSTICS v_batch = ROW_COUNT; v_deleted_rows := v_deleted_rows + v_batch;

  -- Record in evolution audit log
  INSERT INTO evo.evolution_audit_log (id, action, entity_type, entity_id, performed_by, new_values, created_at)
  VALUES (
    gen_random_uuid(), 'lgpd_deleted', 'contact', p_contact_id,
    COALESCE(auth.uid()::text, 'system'),
    '{"status":"lgpd_deleted","reason":"right-to-be-forgotten"}'::jsonb, NOW()
  );

  RETURN QUERY SELECT v_deleted_rows, v_audit_rows;
END;
$$;


