--
-- Name: ensure_single_default_ai_provider(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.ensure_single_default_ai_provider() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  -- Só atualiza outras rows quando NOVO is_default=true E
  -- (é INSERT OU mudou de false→true em UPDATE)
  IF NEW.is_default = true
     AND (TG_OP = 'INSERT' OR OLD.is_default IS DISTINCT FROM NEW.is_default)
  THEN
    UPDATE zapp.ai_providers
    SET is_default = false
    WHERE id != NEW.id
      AND name != NEW.name  -- evita conflito com ON CONFLICT DO UPDATE
      AND is_default = true
      AND use_for && NEW.use_for;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: ensure_single_default_filter(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.ensure_single_default_filter() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
BEGIN
  IF NEW.is_default = true THEN
    UPDATE zapp.saved_filters
    SET is_default = false
    WHERE user_id = NEW.user_id
      AND entity_type = NEW.entity_type
      AND id != NEW.id
      AND is_default = true;
  END IF;
  RETURN NEW;
END;
$$;


