--
-- Name: fn_add_label_to_contact(uuid, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_add_label_to_contact(p_contact_id uuid, p_label_name text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  UPDATE evolution_contacts SET whatsapp_labels = CASE WHEN whatsapp_labels IS NULL THEN ARRAY[p_label_name] WHEN NOT (p_label_name = ANY(whatsapp_labels)) THEN array_append(whatsapp_labels, p_label_name) ELSE whatsapp_labels END, updated_at = NOW() WHERE id = p_contact_id;
END;
$$;


--
-- Name: fn_add_sticker(text, text, text, boolean, text[], text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_add_sticker(p_name text, p_image_url text, p_category text DEFAULT 'outros'::text, p_is_animated boolean DEFAULT false, p_tags text[] DEFAULT '{}'::text[], p_uploaded_by text DEFAULT NULL::text, p_file_hash text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
DECLARE
  v_id uuid;
  v_existing uuid;
BEGIN
  -- Dedup por hash se fornecido
  IF p_file_hash IS NOT NULL THEN
    SELECT id INTO v_existing FROM stickers WHERE file_hash = p_file_hash;
    IF v_existing IS NOT NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'Figurinha duplicada (hash)', 'existing_id', v_existing);
    END IF;
  END IF;
  
  -- Dedup por URL
  SELECT id INTO v_existing FROM stickers WHERE image_url = p_image_url;
  IF v_existing IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Figurinha duplicada (URL)', 'existing_id', v_existing);
  END IF;
  
  INSERT INTO stickers (name, image_url, category, is_animated, tags, uploaded_by, file_hash, use_count, is_favorite, is_active, mime_type)
  VALUES (p_name, p_image_url, p_category, p_is_animated, p_tags, p_uploaded_by, p_file_hash, 0, false, true, 'image/webp')
  RETURNING id INTO v_id;
  
  RETURN jsonb_build_object(
    'ok', true,
    'id', v_id,
    'name', p_name,
    'category', p_category,
    'image_url', p_image_url,
    'is_animated', p_is_animated
  );
END;
$$;


--
-- Name: FUNCTION fn_add_sticker(p_name text, p_image_url text, p_category text, p_is_animated boolean, p_tags text[], p_uploaded_by text, p_file_hash text); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_add_sticker(p_name text, p_image_url text, p_category text, p_is_animated boolean, p_tags text[], p_uploaded_by text, p_file_hash text) IS 'Adiciona figurinha ao catalogo com dedup por hash e URL.';


--
-- Name: fn_add_sticker_to_catalog(text, text, text, boolean, text[], text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_add_sticker_to_catalog(p_name text, p_image_url text, p_category text DEFAULT 'outros'::text, p_is_animated boolean DEFAULT false, p_tags text[] DEFAULT '{}'::text[], p_uploaded_by text DEFAULT NULL::text, p_file_hash text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
DECLARE
  v_id uuid;
  v_dup uuid;
BEGIN
  -- Checar duplicata por hash
  IF p_file_hash IS NOT NULL THEN
    SELECT id INTO v_dup FROM stickers WHERE file_hash = p_file_hash;
    IF v_dup IS NOT NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'duplicata', 'existing_id', v_dup);
    END IF;
  END IF;
  -- Checar duplicata por URL
  SELECT id INTO v_dup FROM stickers WHERE image_url = p_image_url;
  IF v_dup IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'url_duplicada', 'existing_id', v_dup);
  END IF;

  INSERT INTO stickers (name, image_url, category, is_animated, tags, uploaded_by, file_hash, use_count, is_favorite, is_active, mime_type)
  VALUES (p_name, p_image_url, p_category, p_is_animated, p_tags, p_uploaded_by, p_file_hash, 0, false, true, 'image/webp')
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('ok', true, 'id', v_id, 'name', p_name, 'category', p_category);
END;
$$;


