--

CREATE FUNCTION zapp.fn_add_to_dlq(p_event_type text, p_instance_name text, p_remote_jid text, p_payload jsonb, p_error_message text, p_error_stack text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$ DECLARE v_dlq_id UUID; BEGIN INSERT INTO evolution_webhook_dlq(event_type,instance_name,remote_jid,payload,error_message,error_stack,next_retry_at) VALUES(p_event_type,p_instance_name,p_remote_jid,p_payload,p_error_message,p_error_stack,NOW()+INTERVAL '5 minutes') RETURNING id INTO v_dlq_id; RETURN v_dlq_id; END; $$;


--
-- Name: fn_add_to_dlq(text, text, text, jsonb, text, text, text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_add_to_dlq(p_event_type text, p_instance_name text, p_remote_jid text DEFAULT NULL::text, p_payload jsonb DEFAULT NULL::jsonb, p_error_message text DEFAULT ''::text, p_error_stack text DEFAULT NULL::text, p_raw_payload text DEFAULT NULL::text, p_queue_name text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
DECLARE
  v_dlq_id UUID;
  v_resolved_payload JSONB;
BEGIN
  -- Tentar parsear raw_payload como JSONB se payload não foi fornecido
  IF p_payload IS NULL AND p_raw_payload IS NOT NULL THEN
    BEGIN
      v_resolved_payload := p_raw_payload::jsonb;
    EXCEPTION WHEN OTHERS THEN
      v_resolved_payload := NULL; -- BAD JSON: guarda no raw_payload
    END;
  ELSE
    v_resolved_payload := p_payload;
  END IF;

  INSERT INTO evo.evolution_webhook_dlq (
    event_type, instance_name, remote_jid,
    payload, raw_payload, queue_name,
    error_message, error_stack,
    next_retry_at, status, created_at
  )
  VALUES (
    p_event_type, p_instance_name, p_remote_jid,
    v_resolved_payload, p_raw_payload, p_queue_name,
    p_error_message, p_error_stack,
    now() + INTERVAL '5 minutes', 'pending', now()
  )
  RETURNING id INTO v_dlq_id;

  RETURN v_dlq_id;
END;
$$;


--
-- Name: fn_agent_metrics(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_agent_metrics() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE result jsonb;
BEGIN
    SELECT jsonb_build_object(
        'agentes', (SELECT jsonb_agg(jsonb_build_object('id',a.id,'nome',a.name,'status',a.status,'modelo',a.model,'skills',(SELECT COUNT(*) FROM agent_installed_skills WHERE agent_id=a.id))) FROM agents a WHERE a.status='production'),
        'totais', jsonb_build_object('agentes_producao',(SELECT COUNT(*) FROM agents WHERE status='production'),'agentes_teste',(SELECT COUNT(*) FROM agents WHERE status IN ('testing','staging')),'skills_disponiveis',(SELECT COUNT(*) FROM skill_registry),'knowledge_bases',(SELECT COUNT(*) FROM knowledge_bases)),
        'gerado_em', NOW()
    ) INTO result;
    RETURN result;
END;
$$;


--
-- Name: fn_agent_presence_status(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_agent_presence_status() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.updated_at = now();
  NEW.last_activity_at = now();
  IF NEW.status = 'online' AND (OLD.status IS NULL OR OLD.status != 'online') THEN
    NEW.went_online_at = now();
  END IF;
  IF NEW.status = 'offline' AND OLD.status = 'online' THEN
    NEW.went_offline_at = now();
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_alert_connection_drift(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_alert_connection_drift() RETURNS TABLE(alerted_users integer, problematic_count integer, classifications text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog', 'evo', 'monitoring', 'auth'
    AS $$
DECLARE
  v_summary record; v_user_count int := 0; v_dedup_window interval := interval '15 minutes';
BEGIN
  SELECT * INTO v_summary FROM zapp.fn_connection_drift_summary();
  problematic_count := v_summary.degraded + v_summary.unhealthy + v_summary.stale + v_summary.never_checked;
  IF problematic_count = 0 THEN classifications := ARRAY[]::text[]; alerted_users := 0; RETURN NEXT; RETURN; END IF;
  IF EXISTS (SELECT 1 FROM zapp.app_notifications n WHERE n.entity_type='whatsapp_connection_drift' AND n.created_at > now()-v_dedup_window AND (n.metadata->>'problematic_count')::int = problematic_count) THEN
    classifications := ARRAY['skipped_dedup']; alerted_users := 0; RETURN NEXT; RETURN;
  END IF;
  classifications := ARRAY[]::text[];
  IF v_summary.degraded     > 0 THEN classifications := array_append(classifications, 'degraded'); END IF;
  IF v_summary.unhealthy    > 0 THEN classifications := array_append(classifications, 'unhealthy'); END IF;
  IF v_summary.stale        > 0 THEN classifications := array_append(classifications, 'stale'); END IF;
  IF v_summary.never_checked> 0 THEN classifications := array_append(classifications, 'never_checked'); END IF;
  WITH inserted AS (
    INSERT INTO zapp.app_notifications (user_id, title, body, type, entity_type, action_url, metadata)
    SELECT u.id, format('Conexao WhatsApp instavel (%s/%s)',problematic_count,v_summary.total_connections),
      format('Drift: %s. Ultima reconciliacao ha %ss.',array_to_string(classifications,', '),v_summary.reconcile_age_seconds),
      'warning','whatsapp_connection_drift','/#connections',
      jsonb_build_object('problematic_count',problematic_count,'total_connections',v_summary.total_connections,'classifications',classifications,'reconcile_age_seconds',v_summary.reconcile_age_seconds,'detected_at',now())
    FROM auth.users u WHERE u.email_confirmed_at IS NOT NULL RETURNING 1
  ) SELECT count(*) INTO v_user_count FROM inserted;
  alerted_users := v_user_count; RETURN NEXT;
END;
$$;


--
-- Name: FUNCTION fn_alert_connection_drift(); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_alert_connection_drift() IS 'Detecta drift de conexões WhatsApp e cria notificações em app_notifications. Tem dedup de 15min para evitar spam. Disparado pelo cron whatsapp_connection_drift_alert (a cada 5min).';


--
-- Name: fn_alert_connection_lost(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_alert_connection_lost() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.event_type = 'CONNECTION_UPDATE' THEN
        IF (NEW.payload->>'state') IN ('close','connecting') OR (NEW.payload->'data'->>'state') IN ('close','connecting') THEN
            INSERT INTO evolution_alerts (alert_type,severity,message,payload) VALUES ('connection_lost','critical','WhatsApp desconectado! Estado: '||COALESCE(NEW.payload->>'state',NEW.payload->'data'->>'state','unknown'),NEW.payload);
        ELSIF (NEW.payload->>'state') = 'open' OR (NEW.payload->'data'->>'state') = 'open' THEN
            INSERT INTO evolution_alerts (alert_type,severity,message,payload) VALUES ('connection_restored','info','WhatsApp reconectado com sucesso!',NEW.payload);
        END IF;
    END IF;
    IF NEW.event_type = 'LOGOUT_INSTANCE' THEN
        INSERT INTO evolution_alerts (alert_type,severity,message,payload) VALUES ('logout_detected','critical','ALERTA: Logout detectado na instancia!',NEW.payload);
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: fn_alert_dispatch(text, text, text, text, text, jsonb); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_alert_dispatch(p_type text, p_title text, p_message text, p_severity text DEFAULT 'medium'::text, p_source text DEFAULT 'system'::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_id uuid;
BEGIN
  INSERT INTO evolution_alerts (alert_type, title, message, description, severity, payload)
  VALUES (p_type, p_title, p_message, p_message, p_severity, jsonb_build_object('source', p_source, 'metadata', p_metadata))
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


--
-- Name: fn_alert_ghost_message_events(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_alert_ghost_message_events() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$ DECLARE v_ghosts jsonb; v_n int; BEGIN SELECT jsonb_agg(jsonb_build_object('instance', g.instance, 'eventos', g.n, 'ultimo', g.ultimo)), count(*) INTO v_ghosts, v_n FROM ( SELECT w.instance, count(*) AS n, max(w.created_at) AS ultimo FROM zapp.webhook_audit_log w WHERE w.error_message = 'unknown_instance' AND w.event_type IN ('messages.upsert','MESSAGES_UPSERT') AND w.created_at > now() - interval '15 minutes' AND NOT EXISTS (SELECT 1 FROM zapp.instance_registry ir WHERE ir.instance_name = w.instance AND ir.status = 'test') AND NOT EXISTS (SELECT 1 FROM zapp.whatsapp_connections wc WHERE wc.instance_name = w.instance OR wc.evo_instance_id = w.instance) GROUP BY w.instance ) g; IF v_n IS NULL OR v_n = 0 THEN RETURN 0; END IF; IF EXISTS (SELECT 1 FROM evo.evolution_alerts WHERE alert_type = 'ghost_message_events' AND created_at > now() - interval '60 minutes') THEN RETURN 0; END IF; INSERT INTO evo.evolution_alerts (alert_type, severity, title, message, payload) VALUES ('ghost_message_events', 'critical', 'Mensagens de instancia DESCONHECIDA rejeitadas (possivel instancia fantasma)', 'messages.upsert rejeitados como unknown_instance nos ultimos 15 min. Verificar instancias na Evolution.', v_ghosts); RETURN v_n; END; $$;


--
-- Name: FUNCTION fn_alert_ghost_message_events(); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_alert_ghost_message_events() IS 'Detecta mensagens de instancias VERDADEIRAMENTE desconhecidas rejeitadas pela Edge Function. FIX 2026-07-04: usa evo_instance_id para excluir instancias conhecidas (UUID Evolution API). Anti-flap: 1 alerta/hora maxima.';


--
-- Name: fn_alert_health_score_degraded(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_alert_health_score_degraded(p_threshold integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_hs JSONB; v_score NUMERIC; v_grade TEXT; v_already BOOLEAN;
BEGIN
  v_hs    := zapp.fn_system_health_score_cached(30, FALSE);
  v_score := (v_hs->>'score')::NUMERIC;
  v_grade := v_hs->>'grade';

  IF v_score >= p_threshold THEN
    RETURN jsonb_build_object('status','ok','score',v_score,'grade',v_grade,'_cached',(v_hs->>'_cached')::BOOL);
  END IF;

  SELECT EXISTS(
    SELECT 1 FROM evo.evolution_alerts
    WHERE alert_type='health_score_degraded'
      AND created_at > NOW()-INTERVAL '2 hours'
      AND resolved_at IS NULL
  ) INTO v_already;

  IF v_already THEN
    RETURN jsonb_build_object('status','already_alerted','score',v_score,'_cached',(v_hs->>'_cached')::BOOL);
  END IF;

  INSERT INTO evo.evolution_alerts(alert_type, severity, title, message, payload)
  VALUES(
    'health_score_degraded',
    CASE WHEN v_score<50 THEN 'critical' WHEN v_score<65 THEN 'high' ELSE 'medium' END,
    'Health Score DEGRADADO: '||ROUND(v_score,1)||'% (Grade '||v_grade||')',
    'Score '||ROUND(v_score,1)||'% abaixo do threshold '||p_threshold||'%. Grade: '||v_grade||'. Verifique o breakdown.',
    jsonb_build_object('score',v_score,'grade',v_grade,'threshold',p_threshold,'breakdown',v_hs->'breakdown')
  );

  RETURN jsonb_build_object(
    'status','alert_created','score',v_score,'grade',v_grade,
    'severity',CASE WHEN v_score<50 THEN 'critical' WHEN v_score<65 THEN 'high' ELSE 'medium' END
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('error',SQLERRM);
END;
$$;


--
-- Name: fn_alert_health_score_degraded(numeric); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_alert_health_score_degraded(p_threshold numeric DEFAULT 70) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
DECLARE
  v_hs JSONB; v_score NUMERIC; v_grade TEXT; v_already BOOLEAN;
BEGIN
  -- CACHE: usa fn_system_health_score_cached (TTL=5min) em vez de fn_system_health_score()
  -- Reducao: ~1256ms -> <5ms em cache hit (220x mais rapido)
  v_hs    := zapp.fn_system_health_score_cached(5, FALSE);
  v_score := (v_hs->>'score')::NUMERIC;
  v_grade := v_hs->>'grade';

  IF v_score >= p_threshold THEN
    RETURN jsonb_build_object('status','ok','score',v_score,'grade',v_grade,'_cached',(v_hs->>'_cached')::BOOL);
  END IF;

  SELECT EXISTS(
    SELECT 1 FROM evo.evolution_alerts
    WHERE alert_type='health_score_degraded'
      AND created_at > NOW()-INTERVAL '2 hours'
      AND resolved_at IS NULL
  ) INTO v_already;

  IF v_already THEN
    RETURN jsonb_build_object('status','already_alerted','score',v_score,'_cached',(v_hs->>'_cached')::BOOL);
  END IF;

  INSERT INTO evo.evolution_alerts(alert_type, severity, title, message, payload)
  VALUES(
    'health_score_degraded',
    CASE WHEN v_score<50 THEN 'critical' WHEN v_score<65 THEN 'high' ELSE 'medium' END,
    'Health Score DEGRADADO: '||ROUND(v_score,1)||'% (Grade '||v_grade||')',
    'Score '||ROUND(v_score,1)||'% abaixo do threshold '||p_threshold||'%. Grade: '||v_grade||'. Verifique o breakdown.',
    jsonb_build_object('score',v_score,'grade',v_grade,'threshold',p_threshold,'breakdown',v_hs->'breakdown')
  );

  RETURN jsonb_build_object(
    'status','alert_created','score',v_score,'grade',v_grade,
    'severity',CASE WHEN v_score<50 THEN 'critical' WHEN v_score<65 THEN 'high' ELSE 'medium' END
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('error',SQLERRM);
END;
$$;


--
-- Name: FUNCTION fn_alert_health_score_degraded(p_threshold numeric); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_alert_health_score_degraded(p_threshold numeric) IS 'Verifica health score e cria alerta se abaixo do threshold. v2: usa fn_system_health_score_cached(5,FALSE) em vez de fn_system_health_score() direto. Reducao: ~1256ms -> <5ms em cache hit. Retorna _cached flag para diagnostico.';


--
-- Name: fn_alert_message_pipeline_stalled(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_alert_message_pipeline_stalled() RETURNS TABLE(alerted_users integer, pipeline_health text, msgs_5min integer, age_seconds integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog', 'evo', 'monitoring', 'auth'
    AS $$
DECLARE
  v_rate record; v_user_count int := 0; v_dedup_window interval := interval '15 minutes';
BEGIN
  SELECT * INTO v_rate FROM zapp.fn_message_rate_5min();
  pipeline_health := v_rate.pipeline_health; msgs_5min := v_rate.msgs_5min; age_seconds := v_rate.age_seconds;
  IF v_rate.pipeline_health <> 'critical_business_hours' THEN alerted_users := 0; RETURN NEXT; RETURN; END IF;
  -- FIX 2026-07-04: zapp.app_notifications
  IF EXISTS (SELECT 1 FROM zapp.app_notifications n WHERE n.entity_type='message_pipeline_stalled' AND n.created_at > now()-v_dedup_window) THEN
    alerted_users := 0; RETURN NEXT; RETURN;
  END IF;
  WITH inserted AS (
    INSERT INTO zapp.app_notifications (user_id, title, body, type, entity_type, action_url, metadata)
    SELECT u.id, 'Pipeline de mensagens parado',
      format('0 mensagens recebidas em 5min durante horario comercial. Ultima ha %ss.',v_rate.age_seconds),
      'error','message_pipeline_stalled','/#dashboard',
      jsonb_build_object('msgs_5min',v_rate.msgs_5min,'age_seconds',v_rate.age_seconds,'last_msg_at',v_rate.last_msg_at,'detected_at',now())
    FROM auth.users u WHERE u.email_confirmed_at IS NOT NULL RETURNING 1
  ) SELECT count(*) INTO v_user_count FROM inserted;
  alerted_users := v_user_count; RETURN NEXT;
END;
$$;


--
-- Name: FUNCTION fn_alert_message_pipeline_stalled(); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_alert_message_pipeline_stalled() IS 'Detecta pipeline de mensagens parado durante horário comercial (Bateria #8 pós-incidente 2026-05-04). Alerta com type=error e dedup 15min.';


--
-- Name: fn_alert_table_bloat(numeric); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_alert_table_bloat(p_threshold_pct numeric DEFAULT 15) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
DECLARE
  v_bloated jsonb := '[]'::jsonb;
  v_count int := 0;
  v_row record;
BEGIN
  FOR v_row IN
    SELECT schemaname, relname,
      n_dead_tup, n_live_tup,
      round(100.0*n_dead_tup/NULLIF(n_live_tup+n_dead_tup,0),2) as dead_pct,
      pg_size_pretty(pg_total_relation_size(schemaname||'.'||relname)) as total_size
    FROM pg_stat_user_tables
    WHERE schemaname IN ('public','zapp','evo')
      AND (n_live_tup + n_dead_tup) >= 500
      AND round(100.0*n_dead_tup/NULLIF(n_live_tup+n_dead_tup,0),2) > p_threshold_pct
    ORDER BY dead_pct DESC LIMIT 10
  LOOP
    v_bloated := v_bloated || jsonb_build_array(
      jsonb_build_object(
        'schema', v_row.schemaname,
        'table', v_row.relname,
        'dead_pct', v_row.dead_pct,
        'dead_tuples', v_row.n_dead_tup,
        'size', v_row.total_size
      )
    );
    v_count := v_count + 1;
  END LOOP;

  IF v_count > 0 THEN
    -- Alertar admins via app_notifications
    INSERT INTO zapp.app_notifications(user_id, title, body, type, metadata)
    SELECT u.id,
      'Table Bloat Alert ('||v_count||' tabelas)',
      'Tabelas com dead_pct > '||p_threshold_pct||'%% detectadas. VACUUM necessario.',
      'warning',
      jsonb_build_object('bloated_tables', v_bloated, 'threshold_pct', p_threshold_pct, 'count', v_count)
    FROM auth.users u
    JOIN zapp.profiles p ON p.id = u.id
    WHERE p.role = 'admin'
    LIMIT 1
    ON CONFLICT DO NOTHING;
  END IF;

  RETURN jsonb_build_object(
    'checked_at', now(),
    'threshold_pct', p_threshold_pct,
    'bloated_count', v_count,
    'tables', v_bloated,
    'action', CASE WHEN v_count > 0 THEN 'alert_sent' ELSE 'ok' END
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('error', SQLERRM, 'checked_at', now());
END;
$$;


--
-- Name: FUNCTION fn_alert_table_bloat(p_threshold_pct numeric); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_alert_table_bloat(p_threshold_pct numeric) IS 'Alerta quando dead_pct > threshold (default 15%) em tabelas public/zapp/evo. Insere notificacao para admins. Criado auditoria 2026-07-04.';


--
-- Name: fn_alert_wpp2_disconnection(text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_alert_wpp2_disconnection(p_instance_name text DEFAULT 'wpp2'::text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_conn record;
  v_min_disconnected numeric;
  v_already_alerted boolean;
  v_alert_type text;
BEGIN
  SELECT status, phone_number, last_connected_at, disconnected_at, instance_name, is_active
  INTO v_conn
  FROM zapp.whatsapp_connections
  WHERE instance_name = p_instance_name
  LIMIT 1;

  IF v_conn IS NULL OR v_conn.status = 'connected' THEN
    RETURN jsonb_build_object('status','ok','instance_name',p_instance_name,'instance_status', COALESCE(v_conn.status,'not_found'));
  END IF;

  v_min_disconnected := COALESCE(
    EXTRACT(EPOCH FROM (now() - GREATEST(v_conn.last_connected_at, v_conn.disconnected_at))) / 60,
    9999
  );

  IF v_min_disconnected < 30 THEN
    RETURN jsonb_build_object('status','grace_period','disconnected_min',round(v_min_disconnected::numeric,1));
  END IF;

  v_alert_type := p_instance_name || '_disconnection';

  SELECT EXISTS(
    SELECT 1 FROM evo.evolution_alerts
    WHERE alert_type = v_alert_type
      AND created_at > now() - INTERVAL '60 minutes'
      AND resolved_at IS NULL
  ) INTO v_already_alerted;

  IF v_already_alerted THEN
    RETURN jsonb_build_object('status','already_alerted','disconnected_min',round(v_min_disconnected::numeric,1));
  END IF;

  INSERT INTO evo.evolution_alerts(alert_type, severity, title, message, payload)
  VALUES (
    v_alert_type,
    CASE WHEN v_min_disconnected > 120 THEN 'critical' ELSE 'high' END,
    format('%s DESCONECTADO — Rescan QR necessario', p_instance_name),
    format('Instancia %s (%s) desconectada ha %s minutos. Acesse o manager para reconectar.',
           p_instance_name, v_conn.phone_number, round(v_min_disconnected)::text),
    jsonb_build_object('instance',p_instance_name,'phone',v_conn.phone_number,
                       'disconnected_min',round(v_min_disconnected::numeric,1),
                       'action_required','QR_SCAN','url','https://evolution.atomicabr.com.br/manager')
  );

  RETURN jsonb_build_object('status','alert_created',
    'severity',CASE WHEN v_min_disconnected>120 THEN 'critical' ELSE 'high' END,
    'disconnected_min',round(v_min_disconnected::numeric,1));
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('error',SQLERRM,'ts',now());
END;
$$;


--
-- Name: fn_analyze_sentiment(text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_analyze_sentiment(p_text text) RETURNS TABLE(sentiment text, score numeric, intent text, urgency text, keywords text[])
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE v_lower TEXT; v_score DECIMAL := 0; v_sentiment TEXT := 'neutral'; v_intent TEXT := 'geral'; v_urgency TEXT := 'low'; v_keywords TEXT[] := ARRAY[]::TEXT[];
BEGIN
  v_lower := LOWER(COALESCE(p_text, ''));

  IF v_lower ~ '(n[aã]o|nunca|nem)\s+(recomendo|gostei|gosto|indico|aprovei|aprovo|satisfeit)' THEN
    v_score := v_score - 0.5; v_keywords := array_append(v_keywords, 'negacao');
  ELSIF v_lower ~ '(obrigad|excelente|perfeito|[oó]timo|maravilhos|adorei|amei|parab[eé]ns|satisfeit|recomendo|top|show|incr[ií]vel)' THEN
    v_score := v_score + 0.4; v_keywords := array_append(v_keywords, 'positivo');
  END IF;

  IF v_lower ~ '(p[eé]ssimo|horr[ií]vel|ruim|atraso|problema|reclama[cç][aã]|insatisfeit|decepcion|absurdo|vergonha|nunca mais|dem[oó]r|raiva|lixo|porcaria)' THEN
    v_score := v_score - 0.5; v_keywords := array_append(v_keywords, 'negativo');
  END IF;

  IF v_lower ~ '(advogado|procon|processo|justi[cç]a|tribunal|indeniza)' THEN
    v_urgency := 'critical'; v_score := -1; v_keywords := array_append(v_keywords, 'juridico');
  END IF;

  IF v_lower ~ '(urgente|urg[eê]ncia|imediato|agora|socorro|emerg[eê]ncia)' THEN
    v_urgency := CASE WHEN v_urgency='critical' THEN 'critical' ELSE 'high' END;
    v_keywords := array_append(v_keywords, 'urgente');
  END IF;

  IF v_lower LIKE '%?' OR v_lower ~ '(como|quando|onde|qual|quanto)' THEN v_intent := 'pergunta';
  ELSIF v_lower ~ '(reclam|problem)' THEN v_intent := 'reclamacao'; v_urgency := CASE WHEN v_urgency='low' THEN 'medium' ELSE v_urgency END;
  ELSIF v_lower ~ '(or[cç]amento|pre[cç]o|valor)' THEN v_intent := 'pedido_orcamento';
  ELSIF v_lower ~ '(parab[eé]ns|obrigad|adorei)' THEN v_intent := 'elogio';
  END IF;

  v_score := GREATEST(-1, LEAST(1, v_score));
  IF v_score > 0.2 THEN v_sentiment := 'positive';
  ELSIF v_score < -0.2 THEN v_sentiment := 'negative';
  ELSE v_sentiment := 'neutral'; END IF;

  RETURN QUERY SELECT v_sentiment, v_score, v_intent, v_urgency, v_keywords;
END;
$$;


--
-- Name: fn_app_notifications_delete(); Type: FUNCTION; Schema: zapp; Owner: -
