--
-- Name: fn_apply_connection_update(jsonb); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_apply_connection_update(p_event jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
DECLARE
  v_instance_name text;
  v_evo_status    text;
  v_evo_upper     text;
  v_mapped_status text;
  v_owner         text;
  v_phone         text;
  v_profile       text;
  v_evo_id        text;
  v_db_status     text;
  v_disconnected_at timestamptz;
  v_action        text;
  v_debounced     boolean := false;
BEGIN
  v_instance_name := COALESCE(p_event->>'instance', p_event->>'name', p_event->'data'->>'instance');
  v_evo_status    := COALESCE(p_event->'data'->>'state', p_event->>'state', p_event->>'connectionStatus');
  v_owner         := COALESCE(p_event->'data'->>'wuid', p_event->>'ownerJid', p_event->'data'->>'ownerJid');
  v_profile       := COALESCE(p_event->'data'->>'profileName', p_event->>'profileName');
  v_evo_id        := COALESCE(p_event->>'instanceId', p_event->>'id', p_event->'data'->>'id');
  v_phone         := split_part(COALESCE(v_owner, ''), '@', 1);
  v_evo_upper     := UPPER(COALESCE(v_evo_status, ''));

  IF v_instance_name IS NULL THEN
    RETURN jsonb_build_object('action', 'rejected', 'reason', 'missing_instance_name');
  END IF;

  v_mapped_status := CASE
    WHEN v_evo_upper LIKE 'OPEN%' OR v_evo_upper = 'CONNECTED'
      THEN 'connected'
    WHEN v_evo_upper LIKE 'CONNECTING%' OR v_evo_upper LIKE 'RECONNECTING%'
      THEN 'connecting'
    WHEN v_evo_upper IN ('CLOSE', 'DISCONNECTED')
      THEN 'disconnected'
    WHEN v_evo_upper IN ('QR_PENDING', 'QRCODE', 'QR_CODE')
      THEN 'qr_pending'
    WHEN v_evo_upper = 'BANNED'
      THEN 'banned'
    WHEN v_evo_upper IN ('TIMEOUT', 'CONFLICT', 'REPLACED', 'DEVICE_REMOVED', 'MULTIDEVICE_MISMATCH', 'STREAM_ERROR')
      THEN 'disconnected'
    ELSE 'disconnected'
  END;

  PERFORM set_config('app.reconcile_source', 'webhook_push', true);

  SELECT wc.status, wc.disconnected_at INTO v_db_status, v_disconnected_at
    FROM zapp.whatsapp_connections wc WHERE wc.instance_name = v_instance_name;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('action','skip_not_in_db','instance', v_instance_name, 'evo_status', v_evo_status);
  END IF;

  IF v_mapped_status = 'connected'
     AND v_disconnected_at IS NOT NULL
     AND v_disconnected_at > now() - interval '10 minutes' THEN
    v_mapped_status := 'connecting';
    v_debounced := true;
  END IF;

  IF v_db_status IS DISTINCT FROM v_mapped_status THEN
    UPDATE zapp.whatsapp_connections wc
      SET status        = v_mapped_status,
          instance_id   = COALESCE(NULLIF(v_evo_id,''), wc.instance_id),
          phone_number  = COALESCE(NULLIF(v_phone, ''), wc.phone_number),
          owner_jid     = COALESCE(v_owner, wc.owner_jid),
          health_status = CASE v_mapped_status
                            WHEN 'connected'    THEN 'ok'
                            WHEN 'connecting'   THEN 'degraded'
                            WHEN 'disconnected' THEN 'down'
                            WHEN 'qr_pending'   THEN 'degraded'
                            WHEN 'banned'       THEN 'down'
                            ELSE 'unknown' END,
          health_reason = CASE
                            WHEN v_debounced THEN format('webhook push: evo_state=%s debounced (disconnected_at=%s < 10min ago)', v_evo_status, v_disconnected_at)
                            WHEN v_mapped_status = 'connected' THEN NULL
                            ELSE format('webhook push: evo_state=%s mapped=%s', v_evo_status, v_mapped_status) END,
          last_health_check = now(),
          last_connected_at = CASE WHEN v_mapped_status = 'connected' THEN now() ELSE wc.last_connected_at END,
          disconnected_at   = CASE WHEN v_mapped_status = 'disconnected' THEN now() ELSE wc.disconnected_at END,
          updated_at        = now()
    WHERE wc.instance_name = v_instance_name;
    v_action := 'updated';
  ELSE
    UPDATE zapp.whatsapp_connections wc
      SET last_health_check = now(),
          instance_id = COALESCE(NULLIF(v_evo_id,''), wc.instance_id),
          health_status = CASE WHEN v_mapped_status='connected' AND NOT v_debounced AND wc.health_status IS DISTINCT FROM 'ok' THEN 'ok' ELSE wc.health_status END,
          health_reason = CASE WHEN v_mapped_status='connected' AND NOT v_debounced AND wc.health_status IS DISTINCT FROM 'ok' THEN NULL ELSE wc.health_reason END,
          last_connected_at = CASE WHEN v_mapped_status = 'connected' AND NOT v_debounced THEN now() ELSE wc.last_connected_at END
    WHERE wc.instance_name = v_instance_name;
    v_action := 'no_change';
  END IF;

  RETURN jsonb_build_object(
    'action', v_action,
    'instance', v_instance_name,
    'old_status', v_db_status,
    'new_status', v_mapped_status,
    'evo_state', v_evo_status,
    'debounced', v_debounced,
    'profile', v_profile
  );
END;
$$;


--
-- Name: FUNCTION fn_apply_connection_update(p_event jsonb); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_apply_connection_update(p_event jsonb) IS 'Recebe payload do evento connection.update da Evolution API (via webhook ou consumer push) e atualiza whatsapp_connections em tempo real. Latência push <1s vs cron-pull 60s. Source = webhook_push.';


--
-- Name: fn_archive_expired_media(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_archive_expired_media(p_batch_size integer DEFAULT 5000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_archived integer := 0; v_remaining_before integer; v_started timestamptz := clock_timestamp();
BEGIN
  SELECT COUNT(*) INTO v_remaining_before FROM evolution_mirror_media_queue WHERE status = 'failed_expired';
  WITH del AS (DELETE FROM evolution_mirror_media_queue WHERE id IN (SELECT id FROM evolution_mirror_media_queue WHERE status='failed_expired' AND created_at < NOW()-INTERVAL '7 days' ORDER BY id LIMIT p_batch_size) RETURNING 1)
  SELECT count(*) INTO v_archived FROM del;
  INSERT INTO evolution_audit_log (action,entity_type,performed_by,performed_by_type,metadata,created_at)
  VALUES ('data_cleanup','evolution_mirror_media_queue','fn_archive_expired_media','system',jsonb_build_object('rows_deleted',v_archived,'remaining_before',v_remaining_before),NOW());
  RETURN jsonb_build_object('archived',v_archived,'remaining_before',v_remaining_before,'duration_ms',round((extract(epoch from (clock_timestamp()-v_started))*1000)::numeric,1));
END;
$$;


--
-- Name: fn_archive_old_wpp2_messages(integer, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_archive_old_wpp2_messages(p_months_old integer DEFAULT 12, p_batch_size integer DEFAULT 1000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
DECLARE
  v_safe_months    INT := GREATEST(p_months_old, 12);
  v_cutoff         TIMESTAMPTZ := date_trunc('month', now()) - (v_safe_months || ' months')::interval;
  v_already_in_arc INT; v_newly_archived INT; v_deleted INT;
BEGIN
  SELECT count(*) INTO v_already_in_arc
  FROM (SELECT id,instance_name FROM evo.evolution_messages_wpp2 WHERE created_at < v_cutoff ORDER BY created_at ASC LIMIT p_batch_size) b
  WHERE EXISTS(SELECT 1 FROM evo.evolution_messages_wpp2_archive a WHERE a.id=b.id AND a.instance_name=b.instance_name);
  WITH batch AS (SELECT * FROM evo.evolution_messages_wpp2 WHERE created_at < v_cutoff ORDER BY created_at ASC LIMIT p_batch_size)
  INSERT INTO evo.evolution_messages_wpp2_archive
    (id, message_id, remote_jid, from_me, message_type, content, media_url,
     media_mimetype, quoted_message_id, is_starred, is_important, category,
     sentiment, tags, notes, follow_up_at, follow_up_done, payload, created_at,
     contact_id, conversation_id, direction, status, status_at, caption,
     media_filename, media_size, sent_by_bot, template_name, instance_name,
     push_name, media_type, raw_data, deleted_at, edited_at, updated_at,
     media_meta, audio_meme_id, sticker_id, link_preview, is_read, reply_to_id,
     media_bucket, media_path, media_sha256, media_status, transcription_status,
     transcription)
  SELECT id, message_id, remote_jid, from_me, message_type, content, media_url,
     media_mimetype, quoted_message_id, is_starred, is_important, category,
     sentiment, tags, notes, follow_up_at, follow_up_done, payload, created_at,
     contact_id, conversation_id, direction, status, status_at, caption,
     media_filename, media_size, sent_by_bot, template_name, instance_name,
     push_name, media_type, raw_data, deleted_at, edited_at, updated_at,
     media_meta, audio_meme_id, sticker_id, link_preview, is_read, reply_to_id,
     media_bucket, media_path, media_sha256, media_status, transcription_status,
     transcription
  FROM batch
  ON CONFLICT (id,instance_name) DO NOTHING;
  GET DIAGNOSTICS v_newly_archived = ROW_COUNT;
  WITH td AS (SELECT m.id,m.instance_name FROM evo.evolution_messages_wpp2 m WHERE m.created_at < v_cutoff ORDER BY m.created_at ASC LIMIT p_batch_size)
  DELETE FROM evo.evolution_messages_wpp2 WHERE (id,instance_name) IN (
    SELECT t.id,t.instance_name FROM td t WHERE EXISTS(SELECT 1 FROM evo.evolution_messages_wpp2_archive a WHERE a.id=t.id AND a.instance_name=t.instance_name)
  );
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN jsonb_build_object(
    'newly_archived',v_newly_archived,'already_in_archive',v_already_in_arc,
    'total_moved',v_newly_archived+v_already_in_arc,'deleted_from_source',v_deleted,
    'cutoff_date',v_cutoff,'months_old_requested',p_months_old,
    'months_old_applied',v_safe_months,'batch_size',p_batch_size,'ts',now()
  );
END; $$;


--
-- Name: fn_attendance_report(date, date); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_attendance_report(p_start_date date DEFAULT (CURRENT_DATE - 7), p_end_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE result jsonb;
BEGIN
    SELECT jsonb_build_object(
        'periodo', jsonb_build_object('inicio',p_start_date,'fim',p_end_date),
        'mensagens', (SELECT jsonb_build_object('total',COUNT(*),'enviadas',COUNT(*) FILTER(WHERE from_me=true),'recebidas',COUNT(*) FILTER(WHERE from_me=false),'por_dia',ROUND(COUNT(*)::numeric/GREATEST(p_end_date-p_start_date,1),2)) FROM evolution_messages WHERE created_at::date BETWEEN p_start_date AND p_end_date),
        'conversas', (SELECT jsonb_build_object('total',COUNT(*),'abertas',COUNT(*) FILTER(WHERE status IN ('aberta','open','active')),'resolvidas',COUNT(*) FILTER(WHERE status IN ('resolvida','resolved','closed'))) FROM evolution_conversations WHERE created_at::date BETWEEN p_start_date AND p_end_date),
        'contatos', (SELECT jsonb_build_object('total',COUNT(*),'novos',COUNT(*) FILTER(WHERE created_at::date BETWEEN p_start_date AND p_end_date)) FROM evolution_contacts),
        'gerado_em', NOW()
    ) INTO result;
    RETURN result;
END;
$$;


