--
-- Name: fn_audit_checksum_head_tail(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_audit_checksum_head_tail() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET statement_timeout TO '250s'
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$ DECLARE v_started timestamptz := clock_timestamp(); v_head_md5 text; v_tail_md5 text; v_head_count int; v_tail_count int; BEGIN WITH head_rows AS (SELECT raw_data->>'baileys_msg_id' as bid, created_at FROM zapp.evolution_messages WHERE raw_data ? 'baileys_msg_id' ORDER BY created_at ASC LIMIT 10000) SELECT md5(string_agg(bid, '|' ORDER BY created_at ASC)), count(*) INTO v_head_md5, v_head_count FROM head_rows; WITH tail_rows AS (SELECT raw_data->>'baileys_msg_id' as bid, created_at FROM zapp.evolution_messages WHERE raw_data ? 'baileys_msg_id' ORDER BY created_at DESC LIMIT 10000) SELECT md5(string_agg(bid, '|' ORDER BY created_at DESC)), count(*) INTO v_tail_md5, v_tail_count FROM tail_rows; INSERT INTO zapp.audit_results (audit_name, result) VALUES ('checksum_head_tail_v2', jsonb_build_object('head_md5_self', v_head_md5, 'head_count', v_head_count, 'tail_md5_self', v_tail_md5, 'tail_count', v_tail_count, 'duration_ms', EXTRACT(MILLISECONDS FROM clock_timestamp() - v_started)::int, 'executed_at', now())); END $$;


--
-- Name: fn_audit_checksum_messagetimestamp(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_audit_checksum_messagetimestamp() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET statement_timeout TO '250s'
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$ DECLARE v_started timestamptz := clock_timestamp(); v_head_md5 text; v_tail_md5 text; v_head_count int; v_tail_count int; v_head_min_ts bigint; v_head_max_ts bigint; v_tail_min_ts bigint; v_tail_max_ts bigint; BEGIN WITH head_rows AS (SELECT raw_data->>'baileys_msg_id' as bid, (raw_data->>'message_timestamp')::bigint as ts FROM zapp.evolution_messages WHERE raw_data ? 'baileys_msg_id' AND raw_data ? 'message_timestamp' ORDER BY (raw_data->>'message_timestamp')::bigint ASC LIMIT 10000) SELECT md5(string_agg(bid, '|' ORDER BY ts ASC)), count(*), min(ts), max(ts) INTO v_head_md5, v_head_count, v_head_min_ts, v_head_max_ts FROM head_rows; WITH tail_rows AS (SELECT raw_data->>'baileys_msg_id' as bid, (raw_data->>'message_timestamp')::bigint as ts FROM zapp.evolution_messages WHERE raw_data ? 'baileys_msg_id' AND raw_data ? 'message_timestamp' ORDER BY (raw_data->>'message_timestamp')::bigint DESC LIMIT 10000) SELECT md5(string_agg(bid, '|' ORDER BY ts DESC)), count(*), min(ts), max(ts) INTO v_tail_md5, v_tail_count, v_tail_min_ts, v_tail_max_ts FROM tail_rows; INSERT INTO zapp.audit_results (audit_name, result) VALUES ('checksum_messagetimestamp', jsonb_build_object('head_md5_self', v_head_md5, 'head_count', v_head_count, 'head_min_ts', v_head_min_ts, 'head_max_ts', v_head_max_ts, 'tail_md5_self', v_tail_md5, 'tail_count', v_tail_count, 'tail_min_ts', v_tail_min_ts, 'tail_max_ts', v_tail_max_ts, 'duration_ms', EXTRACT(MILLISECONDS FROM clock_timestamp() - v_started)::int, 'executed_at', now())); END $$;


--
-- Name: fn_audit_deal_changes(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_audit_deal_changes() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN PERFORM fn_audit_log('create','deal',NEW.id,'system',NULL,to_jsonb(NEW));
    ELSIF TG_OP = 'UPDATE' THEN PERFORM fn_audit_log('update','deal',NEW.id,'system',to_jsonb(OLD),to_jsonb(NEW));
    ELSIF TG_OP = 'DELETE' THEN PERFORM fn_audit_log('delete','deal',OLD.id,'system',to_jsonb(OLD),NULL);
    END IF;
    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: fn_audit_log(character varying, character varying, uuid, character varying, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_audit_log(p_action character varying, p_entity_type character varying, p_entity_id uuid, p_performed_by character varying DEFAULT 'system'::character varying, p_old_values jsonb DEFAULT NULL::jsonb, p_new_values jsonb DEFAULT NULL::jsonb, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE v_audit_id UUID; v_changes JSONB;
BEGIN
    IF p_old_values IS NOT NULL AND p_new_values IS NOT NULL THEN
        SELECT jsonb_object_agg(key, value) INTO v_changes FROM jsonb_each(p_new_values) WHERE p_old_values->key IS DISTINCT FROM value;
    END IF;
    INSERT INTO evolution_audit_log (action,entity_type,entity_id,performed_by,old_values,new_values,changes,metadata)
    VALUES (p_action,p_entity_type,p_entity_id,p_performed_by,p_old_values,p_new_values,v_changes,p_metadata)
    RETURNING id INTO v_audit_id;
    RETURN v_audit_id;
END;
$$;


--
-- Name: fn_audit_sample_match(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_audit_sample_match() RETURNS jsonb
    LANGUAGE plpgsql
    SET statement_timeout TO '180s'
    AS $$
DECLARE v_total int; v_found int;
BEGIN
  SELECT count(*) INTO v_total FROM audit_source_sample;
  SELECT count(*) INTO v_found FROM audit_source_sample s WHERE EXISTS (SELECT 1 FROM evolution_messages m WHERE m.raw_data->>'baileys_msg_id' = s.source_id);
  RETURN jsonb_build_object('total',v_total,'found',v_found,'missing',v_total-v_found,'coverage_pct',ROUND(100.0*v_found/NULLIF(v_total,0),2));
END; $$;


--
-- Name: fn_audit_security_invoker(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_audit_security_invoker() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
  SELECT jsonb_build_object(
    'risky_views',
    (
      SELECT COUNT(*)
      FROM zapp.v_security_invoker_audit
      WHERE risk_status != 'OK'
    ),
    'total_anon_views',
    (
      SELECT COUNT(*)
      FROM zapp.v_security_invoker_audit
      WHERE anon_can_select
    ),
    'all_secured',
    (
      SELECT COUNT(*) FILTER (WHERE risk_status != 'OK') = 0
      FROM zapp.v_security_invoker_audit
      WHERE anon_can_select
    ),
    'risky_list',
    (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'schema', schema, 'view', view_name, 'risk', risk_status
      )), '[]'::jsonb)
      FROM zapp.v_security_invoker_audit
      WHERE risk_status != 'OK'
    ),
    'checked_at', NOW()
  )
$$;


--
-- Name: FUNCTION fn_audit_security_invoker(); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_audit_security_invoker() IS 'Retorna snapshot de auditoria de SECURITY INVOKER: risky_views (count), all_secured (bool), risky_list (array). Use em alertas e health checks. Zero risky_views = seguro.';


--
-- Name: fn_audit_sticker_delete(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_audit_sticker_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO zapp.zapp_audit_log (user_id, action, entity_type, entity_id, old_data)
  VALUES (auth.uid(), 'delete', 'sticker', OLD.id, row_to_json(OLD)::jsonb);
  RETURN OLD;
END;
$$;


--
-- Name: fn_audit_trigger(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_audit_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$ BEGIN IF TG_OP = 'DELETE' THEN INSERT INTO evolution_audit_log (action, entity_type, entity_id, old_values, performed_by) VALUES ('delete', TG_TABLE_NAME, OLD.id, to_jsonb(OLD), 'system'); RETURN OLD; ELSIF TG_OP = 'UPDATE' THEN INSERT INTO evolution_audit_log (action, entity_type, entity_id, old_values, new_values, performed_by) VALUES ('update', TG_TABLE_NAME, NEW.id, to_jsonb(OLD), to_jsonb(NEW), 'system'); RETURN NEW; ELSIF TG_OP = 'INSERT' THEN INSERT INTO evolution_audit_log (action, entity_type, entity_id, new_values, performed_by) VALUES ('create', TG_TABLE_NAME, NEW.id, to_jsonb(NEW), 'system'); RETURN NEW; END IF; RETURN NULL; END; $$;


--
-- Name: fn_audit_trigger_v2(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_audit_trigger_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_row_id TEXT; v_changed JSONB;
BEGIN
  IF TG_OP = 'DELETE' THEN
    BEGIN v_row_id := OLD.id::text; EXCEPTION WHEN OTHERS THEN v_row_id := NULL; END;
    INSERT INTO audit_log_tables(tbl_name,operation,row_id,old_values,changed_by) VALUES(TG_TABLE_NAME,'DELETE',v_row_id,to_jsonb(OLD),current_user); RETURN OLD;
  ELSIF TG_OP = 'UPDATE' THEN
    BEGIN v_row_id := NEW.id::text; EXCEPTION WHEN OTHERS THEN v_row_id := NULL; END;
    SELECT jsonb_object_agg(key,value) INTO v_changed FROM jsonb_each(to_jsonb(NEW)) WHERE to_jsonb(OLD)->key IS DISTINCT FROM value;
    IF v_changed IS NOT NULL AND v_changed != '{}'::jsonb THEN
      INSERT INTO audit_log_tables(tbl_name,operation,row_id,changed_fields,old_values,new_values,changed_by) VALUES(TG_TABLE_NAME,'UPDATE',v_row_id,v_changed,to_jsonb(OLD),to_jsonb(NEW),current_user);
    END IF; RETURN NEW;
  ELSIF TG_OP = 'INSERT' THEN
    BEGIN v_row_id := NEW.id::text; EXCEPTION WHEN OTHERS THEN v_row_id := NULL; END;
    INSERT INTO audit_log_tables(tbl_name,operation,row_id,new_values,changed_by) VALUES(TG_TABLE_NAME,'INSERT',v_row_id,to_jsonb(NEW),current_user); RETURN NEW;
  END IF; RETURN NULL;
END; $$;


--
-- Name: fn_audit_unscanned_media(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_audit_unscanned_media() RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_total INT;
  v_pending INT;
  v_clean INT;
  v_blocked INT;
BEGIN
  SELECT count(*) INTO v_total FROM media_download_queue;
  SELECT count(*) INTO v_pending FROM media_download_queue WHERE scan_status = 'pending_scan';
  SELECT count(*) INTO v_clean FROM media_download_queue WHERE scan_status = 'clean';
  SELECT count(*) INTO v_blocked FROM media_download_queue WHERE scan_status = 'blocked';

  RETURN jsonb_build_object(
    'total_in_queue', v_total,
    'pending_scan', v_pending,
    'clean', v_clean,
    'blocked', v_blocked,
    'scan_coverage_pct', CASE WHEN v_total > 0 THEN round((v_clean + v_blocked)::numeric / v_total * 100, 2) ELSE 0 END,
    'audited_at', now()
  );
END;
$$;


--
-- Name: fn_audit_vocabulary_check_alert(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_audit_vocabulary_check_alert() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE 
  v_divergencias INT;
  v_amostra jsonb;
BEGIN
  SELECT COUNT(*) INTO v_divergencias
  FROM fn_validate_audit_vocabulary()
  WHERE permitida = false;
  
  IF v_divergencias > 0 THEN
    SELECT jsonb_agg(jsonb_build_object('rpc', rpc_name, 'action', action_literal))
    INTO v_amostra
    FROM fn_validate_audit_vocabulary() WHERE permitida = false LIMIT 10;
    
    INSERT INTO webhook_health_alerts (alert_type, severity, title, details)
    SELECT 'audit_vocabulary_drift', 'WARNING',
      format('🟡 %s RPCs usam actions fora do vocabulário', v_divergencias),
      jsonb_build_object('divergencias_encontradas', v_divergencias, 'amostra', v_amostra,
        'acao_recomendada', 'Adicionar actions ao constraint evolution_audit_log_action_check OU renomear action no RPC')
    WHERE NOT EXISTS (
      SELECT 1 FROM webhook_health_alerts 
      WHERE alert_type = 'audit_vocabulary_drift' AND resolved_at IS NULL
    );
  ELSE
    UPDATE webhook_health_alerts 
    SET resolved_at = now(),
        details = details || jsonb_build_object('auto_resolved', true, 'reason', 'Divergências eliminadas')
    WHERE alert_type = 'audit_vocabulary_drift' AND resolved_at IS NULL;
  END IF;
END;
$$;


--
-- Name: fn_auto_archive_inactive_conversations(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_auto_archive_inactive_conversations() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_count integer;
BEGIN
  WITH archived AS (UPDATE evolution_conversations SET status='arquivada',updated_at=NOW() WHERE status IN ('aberta','open','active') AND updated_at < NOW()-INTERVAL '30 days' AND id NOT IN (SELECT DISTINCT conversation_id FROM evolution_messages WHERE created_at > NOW()-INTERVAL '30 days' AND conversation_id IS NOT NULL) RETURNING 1)
  SELECT COUNT(*) INTO v_count FROM archived;
  IF v_count > 0 THEN INSERT INTO evolution_realtime_events (event_type,entity_type,title,body,priority) VALUES ('conversations_archived','conversation','Conversas Arquivadas',v_count||' conversas inativas foram arquivadas','low'); END IF;
  RETURN v_count;
END; $$;


--
-- Name: fn_auto_categorize_group(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_auto_categorize_group() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.name ILIKE '%venda%' OR NEW.name ILIKE '%comercial%' THEN NEW.category := 'vendas';
  ELSIF NEW.name ILIKE '%suporte%' OR NEW.name ILIKE '%atendimento%' THEN NEW.category := 'suporte';
  ELSIF NEW.name ILIKE '%interno%' OR NEW.name ILIKE '%equipe%' OR NEW.name ILIKE '%time%' THEN NEW.category := 'interno';
  ELSIF NEW.name ILIKE '%fornecedor%' THEN NEW.category := 'fornecedores';
  ELSIF NEW.name ILIKE '%cliente%' THEN NEW.category := 'clientes';
  ELSE NEW.category := COALESCE(NEW.category, 'outros'); END IF;
  RETURN NEW;
END; $$;


--
-- Name: fn_auto_cleanup_stale_alerts(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_auto_cleanup_stale_alerts() RETURNS TABLE(acknowledged_count integer, resolved_dup_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_ack_count int := 0; v_dup_count int := 0;
BEGIN
  UPDATE evolution_alerts SET acknowledged=true, acknowledged_at=NOW(), acknowledged_by='fn_auto_cleanup_stale_alerts'
  WHERE acknowledged=false AND created_at < NOW()-INTERVAL '24 hours' AND alert_type LIKE ANY (ARRAY['cron_failing%','audit:%','test:%','high_value_deal','logout_detected']);
  GET DIAGNOSTICS v_ack_count = ROW_COUNT;
  WITH dups AS (SELECT id, ROW_NUMBER() OVER (PARTITION BY alert_type, COALESCE(remote_jid,'__null__') ORDER BY created_at DESC) AS rn
    FROM evolution_alerts WHERE acknowledged=false AND resolved_at IS NULL)
  UPDATE evolution_alerts e SET resolved_at=NOW(), resolved_by='fn_auto_cleanup_stale_alerts (dedup)'
  FROM dups d WHERE e.id=d.id AND d.rn > 1;
  GET DIAGNOSTICS v_dup_count = ROW_COUNT;
  RETURN QUERY SELECT v_ack_count, v_dup_count;
END $$;


--
-- Name: fn_auto_enqueue_media(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_auto_enqueue_media() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.media_url IS NOT NULL AND NEW.media_type IS NOT NULL THEN
    INSERT INTO evolution_mirror_media_queue (message_id,media_url,media_type,status) VALUES (NEW.id,NEW.media_url,NEW.media_type,'pending') ON CONFLICT DO NOTHING;
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: fn_auto_enqueue_media_download(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_auto_enqueue_media_download() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_media_key   text;
  v_direct_path text;
  v_mimetype    text;
  v_msg_subkey  text;
  v_needs_download boolean;
BEGIN
  -- Identificar tipo de mensagem
  v_msg_subkey := CASE
    WHEN NEW.message_type IN ('image','imageMessage')       THEN 'imageMessage'
    WHEN NEW.message_type IN ('video','videoMessage')       THEN 'videoMessage'
    WHEN NEW.message_type IN ('ptvMessage')                 THEN 'ptvMessage'
    WHEN NEW.message_type IN ('audio','ptt','audioMessage') THEN 'audioMessage'
    WHEN NEW.message_type IN ('document','documentMessage') THEN 'documentMessage'
    WHEN NEW.message_type IN ('sticker','stickerMessage')   THEN 'stickerMessage'
    ELSE NULL
  END;

  IF v_msg_subkey IS NULL THEN RETURN NEW; END IF;

  -- Determinar se essa mensagem precisa ser baixada
  -- FIX C2: enfileira mesmo quando media_url está com kong/WA CDN (problemáticas)
  v_needs_download := (
    NEW.media_url IS NULL
    OR NEW.media_url = ''
    OR NEW.media_url LIKE '%kong%'
    OR NEW.media_url LIKE '%mmg.whatsapp.net%'
    OR NEW.media_url LIKE '%.enc%'
  );

  IF NOT v_needs_download THEN RETURN NEW; END IF;

  -- Extrair media_key e direct_path do payload
  IF NEW.media_meta IS NOT NULL AND NEW.media_meta->>'mediaKey' IS NOT NULL THEN
    v_media_key   := NEW.media_meta->>'mediaKey';
    v_direct_path := NEW.media_meta->>'directPath';
    v_mimetype    := NEW.media_meta->>'mimetype';
  ELSIF NEW.raw_data IS NOT NULL AND NEW.raw_data::text LIKE '%mediaKey%' THEN
    v_media_key   := NEW.raw_data->'message'->v_msg_subkey->>'mediaKey';
    v_direct_path := NEW.raw_data->'message'->v_msg_subkey->>'directPath';
    v_mimetype    := NEW.raw_data->'message'->v_msg_subkey->>'mimetype';
  END IF;

  -- Só enfileira se temos os dados necessários para o download
  IF v_media_key IS NOT NULL
     AND v_direct_path IS NOT NULL
     AND v_direct_path != ''
     AND NEW.message_id IS NOT NULL
  THEN
    INSERT INTO zapp.media_download_queue (
      message_id, message_uuid, remote_jid, instance_name,
      media_type, media_key, direct_path, mimetype, priority, status
    ) VALUES (
      NEW.message_id, NEW.id, NEW.remote_jid, NEW.instance_name,
      NEW.message_type, v_media_key, v_direct_path, v_mimetype, 10, 'pending'
    )
    ON CONFLICT (message_id) DO NOTHING;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION fn_auto_enqueue_media_download(); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_auto_enqueue_media_download() IS 'Enfileira automaticamente mensagens de midia sem URL para download posterior';


--
-- Name: fn_auto_offline_agents(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_auto_offline_agents() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  updated_count integer;
BEGIN
  UPDATE zapp.agent_presence 
  SET status = 'away'
  WHERE status = 'online' AND last_activity_at < now() - interval '30 minutes';
  GET DIAGNOSTICS updated_count = ROW_COUNT;
  RETURN updated_count;
END;
$$;


--
-- Name: fn_auto_populate_media(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_auto_populate_media() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Só processa se tem media_url e é tipo mídia
  IF NEW.media_url IS NOT NULL AND NEW.media_url != '' 
     AND NEW.message_type IN ('image','video','audio','ptt','document','sticker') THEN
    
    INSERT INTO zapp.evolution_media (
      message_id,
      remote_jid,
      media_type,
      mime_type,
      file_name,
      file_size,
      storage_url,
      caption,
      is_animated,
      created_at
    ) VALUES (
      NEW.message_id,
      NEW.remote_jid,
      NEW.message_type,
      NEW.media_mimetype,
      NEW.media_filename,
      NEW.media_size,
      NEW.media_url,
      NEW.caption,
      CASE WHEN NEW.message_type = 'sticker' AND NEW.media_mimetype LIKE '%webp%' THEN true ELSE false END,
      COALESCE(NEW.created_at, now())
    )
    ON CONFLICT DO NOTHING;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION fn_auto_populate_media(); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_auto_populate_media() IS 'Auto-popula evolution_media quando mensagem com mídia chega no evolution_messages';


--
-- Name: fn_auto_replica_identity_metabase(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_auto_replica_identity_metabase() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  obj record;
BEGIN
  FOR obj IN SELECT * FROM pg_event_trigger_ddl_commands() WHERE command_tag='CREATE TABLE' LOOP
    BEGIN
      EXECUTE format('ALTER TABLE %s REPLICA IDENTITY FULL', obj.object_identity);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END LOOP;
END;
$$;


--
-- Name: fn_auto_reset_failed_messages(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_auto_reset_failed_messages() RETURNS TABLE(reset_count integer, current_health text, severity integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v integer;
BEGIN
  UPDATE evolution_message_queue SET status='pending',attempts=0 WHERE status='failed' AND created_at>=now()-interval '6 hours'; GET DIAGNOSTICS v=ROW_COUNT;
  RETURN QUERY SELECT v, 'auto_reset'::text, 0;
END; $$;


--
-- Name: fn_auto_resolve_alerts(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_auto_resolve_alerts(p_hours integer DEFAULT 24) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_count integer;
BEGIN UPDATE evolution_alerts SET acknowledged=true,acknowledged_at=now() WHERE acknowledged=false AND created_at<now()-make_interval(hours:=p_hours) AND severity NOT IN ('critical'); GET DIAGNOSTICS v_count=ROW_COUNT; RETURN v_count; END; $$;


--
-- Name: fn_auto_resolve_baileys_alerts(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_auto_resolve_baileys_alerts() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v integer;
BEGIN
  -- FIX 2026-07-05 (sessao 6): esta funcao acknowledgeava alertas 'baileys' apos 6h
  -- independente da severidade, diferente da politica da funcao irma
  -- fn_auto_resolve_alerts (que exclui severity='critical'). Um alerta critico de
  -- conexao (ex.: tipo contem 'baileys_disconnected') podia ser silenciado sem
  -- confirmacao — mesma classe de risco do S6-4 (alertas criticos fechados sem
  -- verificar o estado real). Agora tambem exclui 'critical'.
  UPDATE evolution_alerts SET acknowledged=true, acknowledged_at=now()
  WHERE acknowledged=false AND alert_type ILIKE '%baileys%' AND created_at < now()-interval '6 hours'
    AND severity NOT IN ('critical');
  GET DIAGNOSTICS v = ROW_COUNT;
  RETURN v;
END;
$$;


--
-- Name: fn_auto_resolve_media_alerts(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_auto_resolve_media_alerts() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_fixed integer := 0;
BEGIN
  UPDATE media_download_queue SET status='pending', retry_count = retry_count + 1
  WHERE status='processing' AND processed_at < now() - interval '30 minutes';
  GET DIAGNOSTICS v_fixed = ROW_COUNT;

  UPDATE media_download_queue SET status='abandoned'
  WHERE status='failed' AND retry_count >= 5;

  RETURN v_fixed;
END;
$$;


--
-- Name: FUNCTION fn_auto_resolve_media_alerts(); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_auto_resolve_media_alerts() IS 'Auto-resolve: retry stuck items, abandon items com 5+ falhas';


--
-- Name: fn_auto_save_received_audio_meme(text, text, text, text, numeric); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_auto_save_received_audio_meme(p_audio_url text, p_name text DEFAULT NULL::text, p_mime_type text DEFAULT 'audio/mpeg'::text, p_file_hash text DEFAULT NULL::text, p_duration_seconds numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
DECLARE
  v_id uuid;
  v_dup jsonb;
  v_final_name text;
BEGIN
  -- Checar duplicata
  v_dup := rpc_check_audio_meme_duplicate(p_audio_url, p_file_hash);
  IF (v_dup->>'is_duplicate')::boolean THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'duplicate', 'existing_id', v_dup->>'existing_id');
  END IF;

  v_final_name := COALESCE(p_name, 'Recebido ' || to_char(now(), 'DD/MM/YYYY'));

  INSERT INTO audio_memes (name, audio_url, category, mime_type, file_hash, duration_seconds, uploaded_by, use_count, is_favorite, is_active)
  VALUES (v_final_name, p_audio_url, 'recebidos', p_mime_type, p_file_hash, p_duration_seconds, 'auto_save', 0, false, true)
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('ok', true, 'id', v_id, 'name', v_final_name, 'category', 'recebidos');
END;
$$;


--
-- Name: FUNCTION fn_auto_save_received_audio_meme(p_audio_url text, p_name text, p_mime_type text, p_file_hash text, p_duration_seconds numeric); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_auto_save_received_audio_meme(p_audio_url text, p_name text, p_mime_type text, p_file_hash text, p_duration_seconds numeric) IS 'Salva automaticamente audio-meme recebido de cliente na categoria recebidos. Dedup integrado.';


--
-- Name: fn_auto_save_received_sticker(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_auto_save_received_sticker() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.message_type = 'sticker' 
     AND NEW.media_url IS NOT NULL AND NEW.media_url != ''
     AND (NEW.from_me IS NULL OR NEW.from_me = false) THEN
    
    INSERT INTO zapp.stickers (name, image_url, category, is_animated, use_count)
    VALUES (
      'Recebida ' || to_char(COALESCE(NEW.created_at, now()), 'DD/MM/YYYY'),
      NEW.media_url,
      'recebidas',
      false,
      0
    )
    ON CONFLICT DO NOTHING;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_auto_sync_group_from_webhook(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_auto_sync_group_from_webhook() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE v_group_jid TEXT; v_subject TEXT; v_desc TEXT; v_owner TEXT; v_size INT;
BEGIN
  IF NEW.event_type = 'GROUPS_UPSERT' THEN
    v_group_jid := COALESCE(NEW.payload->>'id', NEW.remote_jid); v_subject := NEW.payload->>'subject';
    INSERT INTO evolution_groups (group_jid,name,description,owner_jid,participant_count,last_activity_at,category)
    VALUES (v_group_jid,COALESCE(v_subject,v_group_jid),NEW.payload->>'desc',NEW.payload->>'owner',COALESCE((NEW.payload->>'size')::INT,0),NOW(),'outros')
    ON CONFLICT (group_jid) DO UPDATE SET name=COALESCE(EXCLUDED.name,evolution_groups.name),description=COALESCE(EXCLUDED.description,evolution_groups.description),participant_count=COALESCE(EXCLUDED.participant_count,evolution_groups.participant_count),last_activity_at=NOW(),updated_at=NOW();
  ELSIF NEW.event_type IN ('GROUP-PARTICIPANTS_UPDATE','GROUP_PARTICIPANTS_UPDATE') THEN
    v_group_jid := COALESCE(NEW.payload->>'id', NEW.remote_jid);
    UPDATE evolution_groups SET last_activity_at=NOW(),updated_at=NOW() WHERE group_jid=v_group_jid;
    IF NOT FOUND THEN INSERT INTO evolution_groups (group_jid,name,category,last_activity_at) VALUES (v_group_jid,v_group_jid,'outros',NOW()) ON CONFLICT DO NOTHING; END IF;
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: fn_auto_task_on_deal(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_auto_task_on_deal() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
BEGIN
  -- Stage: orcamento_enviado → task de follow-up em 2 dias
  IF NEW.stage = 'orcamento_enviado' AND OLD.stage != 'orcamento_enviado' THEN
    INSERT INTO evo.evolution_tasks (
      title, deal_id, contact_id, task_type, due_date, priority, created_at
    ) VALUES (
      'Follow-up do orçamento: ' || NEW.title,
      NEW.id, NEW.contact_id, 'follow_up',
      CURRENT_DATE + 2, 'alta', now()
    );
  END IF;

  -- Stage: pagamento_pendente → task de confirmação de pagamento em 1 dia
  IF NEW.stage = 'pagamento_pendente' AND OLD.stage != 'pagamento_pendente' THEN
    INSERT INTO evo.evolution_tasks (
      title, deal_id, contact_id, task_type, due_date, priority, created_at
    ) VALUES (
      'Confirmar pagamento: ' || NEW.title,
      NEW.id, NEW.contact_id, 'task',
      CURRENT_DATE + 1, 'alta', now()
    );
  END IF;

  -- Stage: perdido → task de análise de perda (prazo 3 dias)
  IF NEW.stage = 'perdido' AND OLD.stage != 'perdido' THEN
    INSERT INTO evo.evolution_tasks (
      title, deal_id, contact_id, task_type, due_date, priority, created_at
    ) VALUES (
      'Analisar motivo da perda: ' || NEW.title,
      NEW.id, NEW.contact_id, 'task',
      CURRENT_DATE + 3, 'media', now()
    );
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_auto_update_connection_status(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_auto_update_connection_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
DECLARE
  v_instance TEXT;
  v_key      TEXT;
BEGIN
  IF NEW.event_type = 'connection.update' THEN
    v_instance := COALESCE(NEW.instance_name, 'wpp2');
    v_key      := 'connection_status_' || v_instance;

    INSERT INTO evo.evolution_settings (id, key, value, description, category, is_secret, created_at, updated_at)
    VALUES (
      gen_random_uuid(),
      v_key,
      jsonb_build_object(
        'event',      NEW.event_type,
        'state',      NEW.payload->>'state',
        'instance',   v_instance,
        'updated_at', now()::text
      ),
      'Status de conexão da instância ' || v_instance || ' — atualizado automaticamente',
      'general',
      false,
      now(),
      now()
    )
    ON CONFLICT (key) DO UPDATE
      SET value      = EXCLUDED.value,
          updated_at = now();
  END IF;
  RETURN NEW;
END;
$$;


