--
-- Name: fn_calculate_daily_kpis(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_calculate_daily_kpis() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'pg_temp'
    AS $$
DECLARE
  v_day_start timestamptz := date_trunc('day', now());
  v_new_contacts int;
  v_active_contacts int;
  v_total_contacts int;
  v_msgs_received int;
  v_msgs_sent int;
  v_avg_response int;
  v_convs_opened int;
  v_convs_resolved int;
  v_avg_resolution int;
  v_deals_created int;
  v_deals_won int;
  v_deals_lost int;
  v_revenue numeric;
  v_pipeline numeric;
  v_automations int;
  v_followups int;
  v_lead_to_deal numeric;
  v_deal_win numeric;
  v_avg_msgs_per_contact numeric;
BEGIN
  SELECT count(*) INTO v_new_contacts
    FROM evo.evolution_contacts
    WHERE created_at >= v_day_start AND deleted_at IS NULL;

  SELECT count(*) INTO v_active_contacts
    FROM evo.evolution_contacts
    WHERE deleted_at IS NULL AND last_message_at >= v_day_start;

  SELECT count(*) INTO v_total_contacts
    FROM evo.evolution_contacts
    WHERE deleted_at IS NULL;

  SELECT count(*) INTO v_msgs_received
    FROM evo.evolution_messages
    WHERE direction = 'inbound' AND created_at >= v_day_start AND deleted_at IS NULL;

  SELECT count(*) INTO v_msgs_sent
    FROM evo.evolution_messages
    WHERE direction = 'outbound' AND created_at >= v_day_start AND deleted_at IS NULL;

  SELECT COALESCE(avg(first_response_seconds), 0)::int INTO v_avg_response
    FROM evo.evolution_conversations
    WHERE first_response_at >= v_day_start AND first_response_seconds IS NOT NULL;

  SELECT count(*) INTO v_convs_opened
    FROM evo.evolution_conversations
    WHERE created_at >= v_day_start;

  SELECT count(*) INTO v_convs_resolved
    FROM evo.evolution_conversations
    WHERE resolution_at >= v_day_start;

  SELECT COALESCE(avg(resolution_seconds), 0)::int INTO v_avg_resolution
    FROM evo.evolution_conversations
    WHERE resolution_at >= v_day_start AND resolution_seconds IS NOT NULL;

  SELECT count(*) INTO v_deals_created
    FROM evo.evolution_deals
    WHERE created_at >= v_day_start AND deleted_at IS NULL;

  SELECT count(*) INTO v_deals_won
    FROM evo.evolution_deals
    WHERE won = true AND closed_at >= v_day_start AND deleted_at IS NULL;

  SELECT count(*) INTO v_deals_lost
    FROM evo.evolution_deals
    WHERE lost = true AND closed_at >= v_day_start AND deleted_at IS NULL;

  SELECT COALESCE(sum(value), 0) INTO v_revenue
    FROM evo.evolution_deals
    WHERE won = true AND closed_at >= v_day_start AND deleted_at IS NULL;

  SELECT COALESCE(sum(weighted_value), 0) INTO v_pipeline
    FROM evo.evolution_deals
    WHERE won = false AND lost = false AND deleted_at IS NULL;

  SELECT count(*) INTO v_automations
    FROM evo.evolution_automation_logs
    WHERE executed_at >= v_day_start;

  SELECT count(*) INTO v_followups
    FROM evo.evolution_followups
    WHERE sent_at >= v_day_start;

  v_lead_to_deal := CASE WHEN v_new_contacts > 0 THEN v_deals_created::numeric / v_new_contacts ELSE 0 END;
  v_deal_win := CASE WHEN (v_deals_won + v_deals_lost) > 0 THEN v_deals_won::numeric / (v_deals_won + v_deals_lost) ELSE 0 END;
  v_avg_msgs_per_contact := CASE WHEN v_total_contacts > 0 THEN (v_msgs_received + v_msgs_sent)::numeric / v_total_contacts ELSE 0 END;

  RETURN jsonb_build_object(
    'metric_date', current_date,
    'new_contacts', v_new_contacts,
    'active_contacts', v_active_contacts,
    'total_contacts', v_total_contacts,
    'messages_received', v_msgs_received,
    'messages_sent', v_msgs_sent,
    'avg_response_time_seconds', v_avg_response,
    'conversations_opened', v_convs_opened,
    'conversations_resolved', v_convs_resolved,
    'avg_resolution_time_seconds', v_avg_resolution,
    'deals_created', v_deals_created,
    'deals_won', v_deals_won,
    'deals_lost', v_deals_lost,
    'revenue', v_revenue,
    'pipeline_value', v_pipeline,
    'lead_to_deal_rate', v_lead_to_deal,
    'deal_win_rate', v_deal_win,
    'avg_messages_per_contact', v_avg_msgs_per_contact,
    'automations_triggered', v_automations,
    'followups_sent', v_followups
  );
END;
$$;


--
-- Name: fn_calculate_daily_metrics(date); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_calculate_daily_metrics(p_date date DEFAULT (CURRENT_DATE - 1)) RETURNS void
    LANGUAGE plpgsql
    AS $$ BEGIN INSERT INTO evolution_daily_metrics (metric_date, new_contacts, active_contacts, total_contacts, messages_received, messages_sent, conversations_opened, conversations_resolved, deals_created, deals_won, deals_lost, revenue, pipeline_value) SELECT p_date, (SELECT COUNT(*) FROM evolution_contacts WHERE DATE(created_at) = p_date), (SELECT COUNT(*) FROM evolution_contacts WHERE DATE(last_message_at) = p_date), (SELECT COUNT(*) FROM evolution_contacts WHERE DATE(created_at) <= p_date), (SELECT COUNT(*) FROM evolution_webhook_events WHERE event_type = 'MESSAGES_UPSERT' AND DATE(created_at) = p_date), (SELECT COUNT(*) FROM evolution_webhook_events WHERE event_type = 'SEND_MESSAGE' AND DATE(created_at) = p_date), (SELECT COUNT(*) FROM evolution_conversations WHERE DATE(created_at) = p_date), (SELECT COUNT(*) FROM evolution_conversations WHERE DATE(resolution_at) = p_date), (SELECT COUNT(*) FROM evolution_deals WHERE DATE(created_at) = p_date), (SELECT COUNT(*) FROM evolution_deals WHERE stage = 'pago' AND DATE(actual_close_date) = p_date), (SELECT COUNT(*) FROM evolution_deals WHERE stage = 'perdido' AND DATE(actual_close_date) = p_date), (SELECT COALESCE(SUM(value), 0) FROM evolution_deals WHERE stage = 'pago' AND DATE(actual_close_date) = p_date), (SELECT COALESCE(SUM(value), 0) FROM evolution_deals WHERE stage NOT IN ('perdido','pedido_finalizado')) ON CONFLICT (metric_date) DO UPDATE SET new_contacts = EXCLUDED.new_contacts, messages_received = EXCLUDED.messages_received, messages_sent = EXCLUDED.messages_sent, calculated_at = NOW(); END; $$;


--
-- Name: fn_calculate_first_response(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_calculate_first_response() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.first_response_at IS NULL AND NEW.last_outbound_at IS NOT NULL AND NEW.first_message_at IS NOT NULL THEN
    NEW.first_response_at = NEW.last_outbound_at;
    NEW.first_response_seconds = EXTRACT(EPOCH FROM (NEW.last_outbound_at - NEW.first_message_at))::integer;
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: fn_calculate_resolution_time(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_calculate_resolution_time() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.status NOT IN ('resolvida','resolved','closed') AND NEW.status IN ('resolvida','resolved','closed') THEN
    NEW.resolution_at = NOW();
    IF NEW.first_message_at IS NOT NULL THEN
      NEW.resolution_seconds = EXTRACT(EPOCH FROM (NOW() - NEW.first_message_at))::integer;
    END IF;
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: fn_call_stats(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_call_stats(p_days integer DEFAULT 7) RETURNS TABLE(total_calls bigint, missed_calls bigint, answered_calls bigint, callback_pending bigint, avg_duration_seconds numeric, busiest_hour integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$ BEGIN RETURN QUERY SELECT COUNT(*), COUNT(*) FILTER (WHERE call_status = 'missed'), COUNT(*) FILTER (WHERE call_status IN ('accepted','ended')), COUNT(*) FILTER (WHERE call_status = 'missed' AND missed_callback_sent = false), AVG(duration_seconds) FILTER (WHERE duration_seconds IS NOT NULL), (SELECT EXTRACT(HOUR FROM created_at)::INTEGER FROM evolution_calls WHERE created_at > NOW() - (p_days || ' days')::INTERVAL GROUP BY EXTRACT(HOUR FROM created_at) ORDER BY COUNT(*) DESC LIMIT 1) FROM evolution_calls WHERE created_at > NOW() - (p_days || ' days')::INTERVAL; END; $$;


--
-- Name: fn_categorize_sticker(uuid, text, text, text[]); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_categorize_sticker(p_sticker_id uuid, p_new_category text, p_new_name text DEFAULT NULL::text, p_tags text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
DECLARE
  v_old_cat text;
  v_exists boolean;
BEGIN
  -- Verificar se categoria existe
  SELECT EXISTS(SELECT 1 FROM sticker_categories WHERE slug = p_new_category AND is_active) INTO v_exists;
  IF NOT v_exists THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Categoria ' || p_new_category || ' nao encontrada');
  END IF;
  
  SELECT category INTO v_old_cat FROM stickers WHERE id = p_sticker_id;
  IF v_old_cat IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sticker nao encontrado');
  END IF;
  
  UPDATE stickers SET
    category = p_new_category,
    name = COALESCE(p_new_name, name),
    tags = COALESCE(p_tags, tags)
  WHERE id = p_sticker_id;
  
  -- trigger trg_sticker_category_count ja atualiza automaticamente
  
  RETURN jsonb_build_object(
    'ok', true,
    'sticker_id', p_sticker_id,
    'old_category', v_old_cat,
    'new_category', p_new_category,
    'name', COALESCE(p_new_name, (SELECT name FROM stickers WHERE id = p_sticker_id))
  );
END;
$$;


