--
-- Name: fn_check_all_cards_sla(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_check_all_cards_sla() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$ DECLARE v_count integer := 0; BEGIN INSERT INTO evolution_alerts (alert_type, severity, message, payload) SELECT 'sla_exceeded', CASE WHEN NOW() - c.updated_at > s.sla_hours * INTERVAL '2 hours' THEN 'critical' ELSE 'high' END, 'SLA Excedido: ' || c.title || ' — Card no step "' || s.name || '" ha ' || EXTRACT(HOURS FROM NOW() - c.updated_at)::int || 'h (SLA: ' || s.sla_hours || 'h)', jsonb_build_object('entity_type','bpm_card','entity_id',c.id,'card_title',c.title,'step_name',s.name,'sla_hours',s.sla_hours) FROM bpm_cards c JOIN bpm_flow_steps s ON c.current_step_id = s.id WHERE c.deleted_at IS NULL AND c.status != 'completed' AND s.sla_hours IS NOT NULL AND NOW() - c.updated_at > s.sla_hours * INTERVAL '1 hour' AND NOT EXISTS (SELECT 1 FROM evolution_alerts a WHERE a.alert_type = 'sla_exceeded' AND a.payload->>'entity_id' = c.id::text AND a.created_at > NOW() - INTERVAL '4 hours'); GET DIAGNOSTICS v_count = ROW_COUNT; RETURN v_count; END; $$;


--
-- Name: fn_check_baileys_zombie(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_check_baileys_zombie() RETURNS TABLE(health_status text, severity_score integer, alert_created boolean, alert_id uuid, message text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_last_inbound timestamptz; v_gap numeric; v_sev integer; v_msg text; v_alert uuid;
BEGIN
  SELECT max(created_at) INTO v_last_inbound FROM evolution_messages WHERE direction='inbound' AND created_at>=now()-interval '24 hours';
  v_gap:=COALESCE(EXTRACT(EPOCH FROM now()-v_last_inbound)/60,9999);
  v_sev:=CASE WHEN v_gap>120 THEN 5 WHEN v_gap>60 THEN 4 WHEN v_gap>30 THEN 3 WHEN v_gap>15 THEN 2 ELSE 1 END;
  IF v_sev>=3 THEN
    v_msg:=format('Baileys zombie detectado: gap_inbound=%s min, severity=%s',round(v_gap::numeric,1),v_sev);
    IF NOT EXISTS(SELECT 1 FROM evolution_alerts WHERE alert_type='baileys_zombie' AND acknowledged=false AND created_at>=now()-interval '30 minutes') THEN
      INSERT INTO evolution_alerts (alert_type,severity,message,payload) VALUES ('baileys_zombie',CASE WHEN v_sev>=4 THEN 'critical' ELSE 'high' END,v_msg,jsonb_build_object('gap_min',v_gap,'severity',v_sev)) RETURNING id INTO v_alert;
    END IF;
  END IF;
  RETURN QUERY SELECT CASE WHEN v_sev<=1 THEN 'healthy' WHEN v_sev=2 THEN 'warning' WHEN v_sev=3 THEN 'suspect' WHEN v_sev=4 THEN 'confirmed_zombie' ELSE 'critical_zombie' END, v_sev, v_alert IS NOT NULL, v_alert, COALESCE(v_msg,'OK - gap='||round(v_gap::numeric,1)||'min');
END; $$;


