--
-- Name: fn_check_email_rpc_acl(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_check_email_rpc_acl() RETURNS TABLE(funcao text, anon_execute boolean, alert_raised boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_temp'
    AS $$
DECLARE
  rec RECORD;
  v_alert_count int := 0;
  v_total_checked int := 0;
BEGIN
  FOR rec IN
    SELECT DISTINCT
      p.proname AS funcao,
      has_function_privilege('anon', p.oid, 'EXECUTE') AS anon_tem_execute
    FROM pg_proc p
    JOIN pg_namespace n ON p.pronamespace = n.oid
    WHERE n.nspname = 'zapp'
      AND (
        p.proname LIKE 'rpc_%'
        OR p.proname IN (
          'search_contacts',
          'fn_accept_transfer', 'fn_complete_transfer',
          'fn_create_transfer', 'fn_return_transfer',
          'fn_transfer_comment', 'manage_department_member',
          'fn_check_email_views_acl', 'fn_check_email_rpc_acl',
          'fn_system_health_score', 'fn_score_security_acl',
          'fn_security_acl_master_check', 'fn_check_all_restricted_fns_acl'
        )
      )
      AND NOT p.prorettype = (SELECT oid FROM pg_type WHERE typname = 'trigger')
    ORDER BY p.proname
  LOOP
    funcao       := rec.funcao;
    anon_execute := rec.anon_tem_execute;
    alert_raised := false;
    v_total_checked := v_total_checked + 1;

    IF rec.anon_tem_execute THEN
      IF NOT EXISTS (
        SELECT 1 FROM zapp.security_acl_alerts
        WHERE object_name = rec.funcao
          AND alert_type  = 'ANON_EXECUTE_GRANTED'
          AND resolved_at IS NULL
          AND detected_at > now() - interval '1 hour'
      ) THEN
        INSERT INTO zapp.security_acl_alerts
          (alert_type, object_name, role_name, privilege, severity, details)
        VALUES
          ('ANON_EXECUTE_GRANTED', rec.funcao, 'anon', 'EXECUTE', 'CRITICAL',
           jsonb_build_object(
             'function',   rec.funcao,
             'namespace',  'zapp',
             'detected_by','fn_check_email_rpc_acl v2',
             'action_needed', 'REVOKE EXECUTE ON FUNCTION zapp.' || rec.funcao || ' FROM PUBLIC;',
             'risk', 'anon pode chamar SECURITY DEFINER sem autenticacao'
           ));
        alert_raised := true;
        v_alert_count := v_alert_count + 1;
      END IF;
    END IF;
    RETURN NEXT;
  END LOOP;

  INSERT INTO zapp.security_acl_alerts
    (alert_type, object_name, role_name, privilege, severity, details)
  VALUES
    ('CHECK_COMPLETED', 'rpc_*+sensitive', 'system', 'N/A', 'INFO',
     jsonb_build_object(
       'version',          2,
       'new_violations',   v_alert_count,
       'functions_checked', v_total_checked,
       'scope',            'ALL rpc_* + sensitive non-rpc fns in zapp',
       'timestamp',        now()
     ));
END;
$$;


--
-- Name: fn_check_email_views_acl(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_check_email_views_acl() RETURNS TABLE(view_name text, anon_select boolean, has_security_invoker boolean, alert_raised boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_temp'
    AS $$
DECLARE
  rec RECORD;
BEGIN
  FOR rec IN
    SELECT
      c.relname AS vname,
      has_table_privilege('anon', c.oid, 'SELECT') AS anon_sel,
      EXISTS (
        SELECT 1 FROM pg_options_to_table(COALESCE(c.reloptions, ARRAY[]::text[]))
        WHERE option_name = 'security_invoker' AND option_value = 'on'
      ) AS has_si
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'zapp'
      AND c.relkind = 'v'
      AND c.relname LIKE 'email%'
    ORDER BY c.relname
  LOOP
    view_name            := rec.vname;
    anon_select          := rec.anon_sel;
    has_security_invoker := rec.has_si;
    alert_raised         := false;

    IF rec.anon_sel THEN
      IF NOT EXISTS (
        SELECT 1 FROM zapp.security_acl_alerts
        WHERE object_name = rec.vname AND alert_type = 'ANON_SELECT_VIEW'
          AND resolved_at IS NULL AND detected_at > now() - interval '1 hour'
      ) THEN
        INSERT INTO zapp.security_acl_alerts
          (alert_type, object_name, role_name, privilege, severity, details)
        VALUES
          ('ANON_SELECT_VIEW', rec.vname, 'anon', 'SELECT', 'HIGH',
           jsonb_build_object('action_needed', 'REVOKE SELECT ON zapp.' || rec.vname || ' FROM anon;'));
        alert_raised := true;
      END IF;
    END IF;

    IF NOT rec.has_si THEN
      IF NOT EXISTS (
        SELECT 1 FROM zapp.security_acl_alerts
        WHERE object_name = rec.vname AND alert_type = 'VIEW_MISSING_SECURITY_INVOKER'
          AND resolved_at IS NULL AND detected_at > now() - interval '1 day'
      ) THEN
        INSERT INTO zapp.security_acl_alerts
          (alert_type, object_name, role_name, privilege, severity, details)
        VALUES
          ('VIEW_MISSING_SECURITY_INVOKER', rec.vname, 'postgres', 'N/A', 'HIGH',
           jsonb_build_object('action_needed', 'ALTER VIEW zapp.' || rec.vname || ' SET (security_invoker=on);'));
        alert_raised := true;
      END IF;
    END IF;
    RETURN NEXT;
  END LOOP;
END;
$$;


--
-- Name: fn_check_evolution_db_health(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_check_evolution_db_health() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
DECLARE
  v_result jsonb;
  v_msg_count int;
  v_conn_str text;
BEGIN
  -- Tentar acesso via schema evo (espelho do Evolution DB no Supabase)
  -- O schema evo e atualizado por triggers/sync do PG14
  SELECT COUNT(*) INTO v_msg_count
  FROM evo.evolution_alerts
  WHERE created_at > NOW() - INTERVAL '24 hours';

  -- Checar ultima atividade no evo (proxy de conectividade)
  RETURN jsonb_build_object(
    'status', 'ok',
    'alerts_24h', v_msg_count,
    'evo_schema_accessible', true,
    'checked_at', now()
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'status', 'error',
    'error', SQLERRM,
    'evo_schema_accessible', false,
    'checked_at', now()
  );
END;
$$;


