--
-- Name: fn_check_logout_pattern(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_check_logout_pattern() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_1h integer; v_24h integer; v_401 integer;
BEGIN
  SELECT count(*) INTO v_1h FROM evolution_webhook_events WHERE event_type IN ('CONNECTION_UPDATE','connection.update') AND (payload->>'state'='close' OR payload->'data'->>'state'='close') AND created_at>=now()-interval '1 hour';
  SELECT count(*) INTO v_24h FROM evolution_webhook_events WHERE event_type IN ('CONNECTION_UPDATE','connection.update') AND (payload->>'state'='close' OR payload->'data'->>'state'='close') AND created_at>=now()-interval '24 hours';
  SELECT count(*) INTO v_401 FROM evolution_webhook_events WHERE event_type IN ('CONNECTION_UPDATE','connection.update') AND payload->>'statusReason'='401' AND created_at>=now()-interval '24 hours';
  IF v_401>=3 THEN INSERT INTO evolution_alerts (alert_type,severity,message) VALUES ('logout_401_repeated','critical',format('CRITICO: %s logouts 401 em 24h',v_401)) ON CONFLICT DO NOTHING; END IF;
  RETURN jsonb_build_object('logouts_1h',v_1h,'logouts_24h',v_24h,'logouts_401_24h',v_401,'pattern_detected',v_401>=3 OR v_1h>=2);
END; $$;


--
-- Name: fn_check_media_pipeline_health(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_check_media_pipeline_health() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_failed_1h integer;
  v_pending integer;
  v_stuck integer;
  v_alerts jsonb := '[]'::jsonb;
BEGIN
  -- 1. Falhas na última hora
  SELECT count(*) INTO v_failed_1h FROM media_download_queue 
  WHERE status='failed' AND processed_at > now() - interval '1 hour';
  
  IF v_failed_1h > 10 THEN
    v_alerts := v_alerts || jsonb_build_object('level', 'critical', 'msg', 'Mais de 10 falhas de download na ultima hora: ' || v_failed_1h);
  END IF;
  
  -- 2. Fila pendente muito grande
  SELECT count(*) INTO v_pending FROM media_download_queue WHERE status='pending';
  
  IF v_pending > 50000 THEN
    v_alerts := v_alerts || jsonb_build_object('level', 'warning', 'msg', 'Fila de download com mais de 50K itens: ' || v_pending);
  END IF;
  
  -- 3. Itens stuck em processing por mais de 30 min
  SELECT count(*) INTO v_stuck FROM media_download_queue 
  WHERE status='processing' AND processed_at < now() - interval '30 minutes';
  
  IF v_stuck > 0 THEN
    v_alerts := v_alerts || jsonb_build_object('level', 'warning', 'msg', 'Itens stuck em processing ha mais de 30min: ' || v_stuck);
    -- Auto-fix: resetar stuck items
    UPDATE media_download_queue SET status='pending', retry_count = retry_count + 1
    WHERE status='processing' AND processed_at < now() - interval '30 minutes';
  END IF;
  
  RETURN jsonb_build_object(
    'healthy', jsonb_array_length(v_alerts) = 0,
    'alerts', v_alerts,
    'metrics', jsonb_build_object(
      'failed_1h', v_failed_1h,
      'pending', v_pending,
      'stuck', v_stuck
    ),
    'checked_at', now()
  );
END;
$$;


--
-- Name: FUNCTION fn_check_media_pipeline_health(); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_check_media_pipeline_health() IS 'Health check do pipeline de midia: falhas, fila stuck, alertas automaticos';


--
-- Name: fn_check_media_processing(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_check_media_processing() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_total integer; v_with_url integer; v_pct numeric;
BEGIN
  SELECT count(*),count(*) FILTER(WHERE media_url IS NOT NULL AND media_url!='') INTO v_total,v_with_url FROM evolution_messages WHERE created_at>=now()-interval '1 hour' AND message_type IN ('image','video','audio','document','sticker');
  v_pct:=CASE WHEN v_total=0 THEN 100 ELSE 100.0*v_with_url/v_total END;
  RETURN jsonb_build_object('status',CASE WHEN v_pct>=95 THEN 'healthy' WHEN v_pct>=85 THEN 'warning' ELSE 'degraded' END,'pct_with_url',round(v_pct,2),'total_media_1h',v_total);
END; $$;


--
-- Name: fn_check_media_processing_failures(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_check_media_processing_failures() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_total integer; v_no_url integer; v_pct numeric;
BEGIN
  SELECT count(*),count(*) FILTER(WHERE media_url IS NULL OR media_url='') INTO v_total,v_no_url FROM evolution_messages WHERE created_at>=now()-interval '24 hours' AND message_type IN ('image','video','audio','document','sticker');
  v_pct:=CASE WHEN v_total>0 THEN round(100.0*v_no_url/v_total,1) ELSE 0 END;
  RETURN jsonb_build_object('media_24h',v_total,'no_url',v_no_url,'pct_no_url',v_pct,'status',CASE WHEN v_pct>20 THEN 'degraded' WHEN v_pct>5 THEN 'warning' ELSE 'healthy' END);
END; $$;


--
-- Name: fn_check_minio_decomission(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_check_minio_decomission() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_minio_urls bigint;
  v_s3_urls bigint;
  v_r2_urls bigint;
  v_can_decomission boolean;
BEGIN
  SELECT count(*) INTO v_minio_urls FROM evolution_messages WHERE media_url LIKE 'http://minio%';
  SELECT count(*) INTO v_s3_urls FROM evolution_messages WHERE media_url LIKE 'https://s3.atomicabr%';
  SELECT count(*) INTO v_r2_urls FROM evolution_messages WHERE media_url LIKE 'https://zapp-media-proxy%';
  
  v_can_decomission := (v_minio_urls = 0 AND v_s3_urls = 0);
  
  RETURN jsonb_build_object(
    'can_decomission', v_can_decomission,
    'minio_internal_urls', v_minio_urls,
    's3_atomicabr_urls', v_s3_urls,
    'r2_worker_urls', v_r2_urls,
    'recommendation', CASE 
      WHEN v_can_decomission THEN 'SEGURO descomissionar MinIO para midias. Manter para backups.'
      ELSE 'NAO SEGURO. Ainda existem ' || (v_minio_urls + v_s3_urls) || ' URLs apontando para MinIO.'
    END,
    'checked_at', now()
  );
END;
$$;


--
-- Name: FUNCTION fn_check_minio_decomission(); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_check_minio_decomission() IS 'Verifica se e seguro descomissionar o MinIO como storage de midia';


