--

CREATE FUNCTION zapp.fn_check_stuck_pending_messages() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_stuck integer; v_processing integer;
BEGIN
  SELECT count(*) INTO v_stuck FROM evolution_message_queue WHERE status='pending' AND created_at<now()-interval '10 minutes';
  SELECT count(*) INTO v_processing FROM evolution_message_queue WHERE status='processing' AND created_at<now()-interval '5 minutes';
  IF v_processing>0 THEN UPDATE evolution_message_queue SET status='pending' WHERE status='processing' AND created_at<now()-interval '5 minutes'; END IF;
  IF v_stuck>5 THEN INSERT INTO evolution_alerts (alert_type,severity,message) VALUES ('queue_stuck','high',format('Queue stuck: %s pending >10min, %s processing resetados',v_stuck,v_processing)); END IF;
  RETURN jsonb_build_object('stuck_pending',v_stuck,'stuck_processing_reset',v_processing,'alert_created',v_stuck>5);
END; $$;


