--
-- Name: fn_circuit_allow(text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_circuit_allow(p_service text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v RECORD;
BEGIN
  SELECT * INTO v FROM zapp.api_circuit_breaker WHERE service = p_service;
  IF NOT FOUND THEN RETURN TRUE; END IF;  -- serviço desconhecido: libera

  IF v.state = 'closed' THEN
    RETURN TRUE;

  ELSIF v.state = 'open' THEN
    -- cooldown expirou? transiciona para half_open e libera o teste
    IF clock_timestamp() >= v.next_attempt_at THEN
      UPDATE zapp.api_circuit_breaker
        SET state = 'half_open', success_count_half_open = 0, updated_at = now()
      WHERE service = p_service;
      RETURN TRUE;
    END IF;
    RETURN FALSE;  -- ainda no cooldown: bloquear

  ELSIF v.state = 'half_open' THEN
    RETURN TRUE;  -- permite o call de teste

  END IF;
  RETURN TRUE;  -- fallback seguro
END;
$$;


--
-- Name: FUNCTION fn_circuit_allow(p_service text); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_circuit_allow(p_service text) IS 'Retorna TRUE se a call ao serviço deve prosseguir. Chamar ANTES de qualquer request à API externa. Se retornar FALSE: não fazer a call, retornar erro imediato ao caller.';


--
-- Name: fn_circuit_record(text, boolean); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_circuit_record(p_service text, p_success boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v RECORD;
BEGIN
  SELECT * INTO v FROM zapp.api_circuit_breaker WHERE service = p_service;
  IF NOT FOUND THEN RETURN; END IF;

  IF p_success THEN
    IF v.state = 'closed' THEN
      -- sucesso normal: zerar falhas acumuladas
      UPDATE zapp.api_circuit_breaker
        SET failure_count = 0, last_success_at = now(), updated_at = now()
      WHERE service = p_service;

    ELSIF v.state = 'half_open' THEN
      -- sucesso no teste: incrementar contador de recuperação
      IF (v.success_count_half_open + 1) >= v.required_successes_to_close THEN
        -- atingiu threshold: fechar circuito (recuperado)
        UPDATE zapp.api_circuit_breaker
          SET state = 'closed', failure_count = 0,
              success_count_half_open = 0, last_success_at = now(),
              opened_at = NULL, next_attempt_at = NULL, updated_at = now()
        WHERE service = p_service;
      ELSE
        UPDATE zapp.api_circuit_breaker
          SET success_count_half_open = success_count_half_open + 1,
              last_success_at = now(), updated_at = now()
        WHERE service = p_service;
      END IF;
    END IF;

  ELSE
    -- falha
    IF v.state = 'closed' THEN
      IF (v.failure_count + 1) >= v.threshold_failures THEN
        -- atingiu threshold: ABRIR circuito
        UPDATE zapp.api_circuit_breaker
          SET state = 'open', failure_count = v.failure_count + 1,
              last_failure_at = now(), opened_at = now(),
              next_attempt_at = now() + (v.cooldown_seconds || ' seconds')::interval,
              updated_at = now()
        WHERE service = p_service;
      ELSE
        UPDATE zapp.api_circuit_breaker
          SET failure_count = failure_count + 1,
              last_failure_at = now(), updated_at = now()
        WHERE service = p_service;
      END IF;

    ELSIF v.state = 'half_open' THEN
      -- falhou no teste: voltar para open com cooldown reset
      UPDATE zapp.api_circuit_breaker
        SET state = 'open', failure_count = failure_count + 1,
            success_count_half_open = 0, last_failure_at = now(),
            opened_at = now(),
            next_attempt_at = now() + (v.cooldown_seconds || ' seconds')::interval,
            updated_at = now()
      WHERE service = p_service;
    END IF;
  END IF;
END;
$$;


--
-- Name: FUNCTION fn_circuit_record(p_service text, p_success boolean); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_circuit_record(p_service text, p_success boolean) IS 'Registrar resultado de uma call. Chamar DEPOIS de qualquer request à API externa. TRUE = sucesso, FALSE = falha. Transiciona estado da máquina de estados.';


--
-- Name: fn_circuit_reset(text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_circuit_reset(p_service text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
  UPDATE zapp.api_circuit_breaker
    SET state = 'closed', failure_count = 0, success_count_half_open = 0,
        opened_at = NULL, next_attempt_at = NULL, updated_at = now()
  WHERE service = p_service;
$$;


--
-- Name: FUNCTION fn_circuit_reset(p_service text); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_circuit_reset(p_service text) IS 'Reset manual: usar somente após confirmar que o cookie/API está de volta. Ex: SELECT zapp.fn_circuit_reset(''lusha'');';


--
-- Name: fn_circuit_status(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_circuit_status() RETURNS TABLE(service text, state text, failure_count integer, success_count_half_open integer, opened_at timestamp with time zone, next_attempt_at timestamp with time zone, last_failure_at timestamp with time zone, last_success_at timestamp with time zone, mins_until_retry numeric)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
  SELECT
    service, state, failure_count, success_count_half_open,
    opened_at, next_attempt_at, last_failure_at, last_success_at,
    CASE WHEN state = 'open' AND next_attempt_at > now()
         THEN round(extract(epoch from next_attempt_at - now()) / 60, 1)
         ELSE 0 END AS mins_until_retry
  FROM zapp.api_circuit_breaker
  ORDER BY service;
$$;


--
-- Name: fn_claim_media_batch(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_claim_media_batch(p_batch_size integer DEFAULT 10) RETURNS TABLE(id uuid, message_id uuid, media_url text, media_type text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN RETURN QUERY UPDATE evolution_mirror_media_queue SET status='processing',updated_at=now() WHERE id IN (SELECT mmq.id FROM evolution_mirror_media_queue mmq WHERE mmq.status='pending' ORDER BY mmq.created_at LIMIT p_batch_size FOR UPDATE SKIP LOCKED) RETURNING evolution_mirror_media_queue.id,evolution_mirror_media_queue.message_id,evolution_mirror_media_queue.media_url,evolution_mirror_media_queue.media_type; END; $$;


--
-- Name: fn_clamav_scan_media(bigint, text, boolean, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_clamav_scan_media(p_queue_id bigint, p_scan_result text, p_is_clean boolean, p_details text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE v_queue RECORD;
BEGIN
  SELECT * INTO v_queue FROM media_download_queue WHERE id = p_queue_id;
  IF v_queue IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not found'); END IF;
  UPDATE media_download_queue SET scan_status = CASE WHEN p_is_clean THEN 'clean' ELSE 'blocked' END, scan_result = p_scan_result, scanned_at = now() WHERE id = p_queue_id;
  INSERT INTO media_scan_log (message_id, instance_name, scan_type, scan_result, details) VALUES (v_queue.message_id, v_queue.instance_name, 'clamav_scan', CASE WHEN p_is_clean THEN 'clean' ELSE 'blocked' END, COALESCE(p_details, p_scan_result));
  IF NOT p_is_clean THEN
    INSERT INTO media_quarantine (message_id, instance_name, remote_jid, original_mimetype, media_meta, block_reason, severity) VALUES (v_queue.message_id, v_queue.instance_name, v_queue.remote_jid, v_queue.mimetype, jsonb_build_object('media_key', v_queue.media_key), 'CLAMAV: ' || p_scan_result, 'block');
    UPDATE media_download_queue SET status = 'blocked', error_message = 'CLAMAV: ' || p_scan_result WHERE id = p_queue_id;
  END IF;
  RETURN jsonb_build_object('ok', true, 'is_clean', p_is_clean, 'scan_result', p_scan_result);
END;
$$;


