--
-- Name: fn_cleanup_old_notifications(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_cleanup_old_notifications() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_read_deleted   integer := 0;
  v_system_deleted integer := 0;
  v_unread_deleted integer := 0;
BEGIN
  -- FIX 2026-07-04: zapp.app_notifications
  DELETE FROM zapp.app_notifications WHERE is_read = true AND created_at < NOW() - INTERVAL '30 days';
  GET DIAGNOSTICS v_read_deleted = ROW_COUNT;
  DELETE FROM zapp.app_notifications WHERE type IN ('warning','error','system','info') AND is_read = false AND created_at < NOW() - INTERVAL '7 days';
  GET DIAGNOSTICS v_system_deleted = ROW_COUNT;
  DELETE FROM zapp.app_notifications WHERE is_read = false AND created_at < NOW() - INTERVAL '60 days';
  GET DIAGNOSTICS v_unread_deleted = ROW_COUNT;
  RETURN jsonb_build_object('read_deleted',v_read_deleted,'system_deleted',v_system_deleted,'unread_old',v_unread_deleted,'total_deleted',v_read_deleted+v_system_deleted+v_unread_deleted,'ran_at',NOW());
END;
$$;


