--
-- Name: fn_cleanup_webhook_events_v2(boolean, integer, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_cleanup_webhook_events_v2(p_dry_run boolean DEFAULT true, p_processed_days integer DEFAULT 14, p_total_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_proc integer:=0; v_total integer:=0; v_size_before text;
BEGIN
  v_size_before:=pg_size_pretty(pg_total_relation_size('evolution_webhook_events'::regclass));
  IF NOT p_dry_run THEN
    DELETE FROM evolution_webhook_events WHERE processed=true AND error_message IS NULL AND created_at<now()-(p_processed_days||' days')::interval; GET DIAGNOSTICS v_proc=ROW_COUNT;
    DELETE FROM evolution_webhook_events WHERE created_at<now()-(p_total_days||' days')::interval; GET DIAGNOSTICS v_total=ROW_COUNT;
  END IF;
  RETURN jsonb_build_object('dry_run',p_dry_run,'processed_deleted',v_proc,'total_deleted',v_total,'size_before',v_size_before);
END; $$;


--
-- Name: fn_clear_qr_on_connect(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_clear_qr_on_connect() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.status = 'connected' AND OLD.status != 'connected' THEN
    NEW.qr_code = NULL;
    NEW.qr_code_base64 = NULL;
    NEW.connected_at = now();
    NEW.last_connected_at = now();
  END IF;
  IF NEW.status = 'disconnected' AND OLD.status = 'connected' THEN
    NEW.disconnected_at = now();
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_collect_restore_logs(text, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_collect_restore_logs(p_container_name text DEFAULT 'restore-validate-validator-1'::text, p_endpoint_id integer DEFAULT 1) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_api_key text;
  v_portainer_url text := 'https://portainer.atomicabr.com.br';
  v_containers_req_id bigint;
  v_containers_response jsonb;
  v_container_id text;
  v_logs_req_id bigint;
  v_logs_response text;
  v_ingest jsonb;
BEGIN
  SELECT decrypted_secret INTO v_api_key
  FROM vault.decrypted_secrets
  WHERE name = 'portainer_api_key' LIMIT 1;

  IF v_api_key IS NULL THEN
    RETURN jsonb_build_object('status','standby','reason','portainer_api_key_not_in_vault');
  END IF;

  SELECT net.http_get(
    url := v_portainer_url || '/api/endpoints/' || p_endpoint_id || '/docker/containers/json?all=true&filters=' ||
           replace(replace(jsonb_build_object('name', jsonb_build_array(p_container_name))::text, '"', '%22'), ' ', ''),
    headers := jsonb_build_object('X-API-Key', v_api_key),
    timeout_milliseconds := 10000
  ) INTO v_containers_req_id;

  FOR i IN 1..16 LOOP
    PERFORM pg_sleep(0.5);
    SELECT (content::jsonb) INTO v_containers_response
    FROM net._http_response
    WHERE id = v_containers_req_id AND status_code IS NOT NULL LIMIT 1;
    EXIT WHEN v_containers_response IS NOT NULL;
  END LOOP;

  IF v_containers_response IS NULL OR jsonb_array_length(v_containers_response) = 0 THEN
    RETURN jsonb_build_object('status','no_container_found','container_name', p_container_name);
  END IF;

  v_container_id := v_containers_response->0->>'Id';

  SELECT net.http_get(
    url := v_portainer_url || '/api/endpoints/' || p_endpoint_id || '/docker/containers/' || v_container_id ||
           '/logs?stdout=true&stderr=true&tail=500',
    headers := jsonb_build_object('X-API-Key', v_api_key),
    timeout_milliseconds := 15000
  ) INTO v_logs_req_id;

  FOR i IN 1..30 LOOP
    PERFORM pg_sleep(0.5);
    SELECT content INTO v_logs_response
    FROM net._http_response
    WHERE id = v_logs_req_id AND status_code IS NOT NULL LIMIT 1;
    EXIT WHEN v_logs_response IS NOT NULL;
  END LOOP;

  IF v_logs_response IS NULL THEN
    RETURN jsonb_build_object('status','timeout_reading_logs');
  END IF;

  v_logs_response := regexp_replace(v_logs_response, E'[\\x00-\\x08\\x0B-\\x1F]', '', 'g');
  v_ingest := zapp.fn_ingest_restore_logs_from_text(v_logs_response);

  RETURN jsonb_build_object('status','ok','container_id', v_container_id,'logs_bytes', length(v_logs_response),'ingest', v_ingest);
END;
$$;


--
-- Name: fn_complete_transfer(uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_complete_transfer(p_transfer_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
BEGIN
    UPDATE zapp.conversation_transfers
    SET 
        status = 'completed',
        completed_at = NOW()
    WHERE 
        id = p_transfer_id AND status = 'accepted';
    
    RETURN FOUND;
END;
$$;


