    UPDATE zapp.conversation_transfers SET status = 'completed', resolution_notes = p_notes, resolution_type = p_type, completed_at = NOW()
    WHERE id = p_transfer_id AND status IN ('accepted', 'in_progress');
    RETURN FOUND;
END;
$$;


--
-- Name: fn_compute_contact_dedup_hash(text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_compute_contact_dedup_hash(p_phone_number text, p_email text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT md5(
    COALESCE(
      CASE
        WHEN REGEXP_REPLACE(COALESCE(p_phone_number,''), '[^0-9]', '', 'g') = '' THEN NULL
        ELSE
          CASE
            WHEN LENGTH(REGEXP_REPLACE(REGEXP_REPLACE(COALESCE(p_phone_number,''), '[^0-9]', '', 'g'), '^55', '')) = 10
              AND SUBSTR(REGEXP_REPLACE(REGEXP_REPLACE(COALESCE(p_phone_number,''), '[^0-9]', '', 'g'), '^55', ''), 3, 1) IN ('7','8','9')
            THEN
              SUBSTR(REGEXP_REPLACE(REGEXP_REPLACE(COALESCE(p_phone_number,''), '[^0-9]', '', 'g'), '^55', ''), 1, 2)
              || '9'
              || SUBSTR(REGEXP_REPLACE(REGEXP_REPLACE(COALESCE(p_phone_number,''), '[^0-9]', '', 'g'), '^55', ''), 3)
            ELSE
              REGEXP_REPLACE(REGEXP_REPLACE(COALESCE(p_phone_number,''), '[^0-9]', '', 'g'), '^55', '')
          END
      END,
      ''
    )
    || '|' ||
    COALESCE(LOWER(TRIM(p_email)), '')
  );
$$;


--
-- Name: fn_compute_contact_dedup_hash(text, text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_compute_contact_dedup_hash(p_phone text, p_email text, p_name text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT md5(
    lower(coalesce(regexp_replace(p_phone, '\D', '', 'g'), '')) || '|' ||
    lower(coalesce(p_email, '')) || '|' ||
    lower(coalesce(p_name, ''))
  );
$$;


--
-- Name: fn_connection_drift_summary(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_connection_drift_summary() RETURNS TABLE(total_connections integer, healthy integer, degraded integer, unhealthy integer, stale integer, never_checked integer, worst_age_seconds integer, last_reconcile_at timestamp with time zone, reconcile_age_seconds integer, generated_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
  SELECT
    count(*)::int AS total_connections,
    count(*) FILTER (WHERE drift_classification = 'healthy')::int AS healthy,
    count(*) FILTER (WHERE drift_classification = 'degraded')::int AS degraded,
    count(*) FILTER (WHERE drift_classification = 'unhealthy')::int AS unhealthy,
    count(*) FILTER (WHERE drift_classification = 'stale')::int AS stale,
    count(*) FILTER (WHERE drift_classification = 'never_checked')::int AS never_checked,
    COALESCE(max(health_check_age_seconds), 0)::int AS worst_age_seconds,
    max(last_reconcile_at) AS last_reconcile_at,
    COALESCE(min(reconcile_age_seconds), 0)::int AS reconcile_age_seconds,
    now() AS generated_at
  FROM zapp.v_connection_drift_score;
$$;


