CREATE FUNCTION zapp.fn_contacts_view_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
BEGIN
  UPDATE evo.evolution_contacts          -- schema explícito: BASE TABLE
