--
-- Name: FUNCTION fn_contacts_view_delete(); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_contacts_view_delete() IS 'v1 2026-07-02: DELETE via view vira soft delete (antes apagava fisicamente a base).';


--
-- Name: fn_contacts_view_delete_handler(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_contacts_view_delete_handler() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
BEGIN
  -- Soft delete: marca deleted_at em vez de remover fisicamente
  -- Requisito LGPD: 30 dias de undo antes da exclusao permanente
  -- PITFALL: em trigger INSTEAD OF DELETE, NEW e NULL — nunca acessar NEW.*
  UPDATE evo.evolution_contacts
  SET deleted_at = NOW(),
      deleted_reason = CASE
        WHEN array_length(TG_ARGV, 1) > 0 THEN TG_ARGV[0]
        ELSE 'user_request'
      END
  WHERE id = OLD.id;
  RETURN OLD;
END;
$$;


