    NEW.source,
    COALESCE(NEW.instance_name, 'wpp2'),  -- R13: default corrigido p/ instância ativa (pink_test removida 2026-07-09)
    COALESCE(NEW.external_id, NEW.remote_jid, NEW.phone || '@s.whatsapp.net'),
    NEW.push_name, NEW.tags,
