--
-- Name: fn_cookie_probe_collect(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_cookie_probe_collect(p_grace_seconds integer DEFAULT 45) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'net'
    AS $$
DECLARE
  r RECORD; v_status INT; v_content TEXT; v_timed_out BOOLEAN;
  v_created TIMESTAMPTZ; v_healthy BOOLEAN; v_new_status TEXT;
  v_processed INT := 0; v_pending INT := 0; v_found BOOLEAN;
BEGIN
  FOR r IN
    SELECT servico, request_id, dispatched_at,
           coalesce(probe_version,'v2') AS probe_version,
           coalesce(probe_auth,'cookie') AS probe_auth
    FROM zapp.cookie_probe_pending
  LOOP
    v_status:=NULL; v_content:=NULL; v_timed_out:=false; v_created:=NULL;
    SELECT resp.status_code, left(resp.content::text,300),
           coalesce(resp.timed_out,false), resp.created
      INTO v_status, v_content, v_timed_out, v_created
      FROM net._http_response resp WHERE resp.id=r.request_id;
    v_found := FOUND;
    IF NOT v_found AND (now()-r.dispatched_at) < make_interval(secs=>p_grace_seconds) THEN
      v_pending:=v_pending+1; CONTINUE;
    END IF;
    IF r.servico='lusha' THEN
      v_healthy := coalesce(v_status,0)=200;
      v_new_status := CASE coalesce(v_status,0)
        WHEN 200 THEN 'healthy' WHEN 401 THEN 'expired'
        WHEN 403 THEN 'challenged' WHEN 429 THEN 'rate_limited' ELSE 'error' END;
    ELSIF r.servico='leadcontact' THEN
      BEGIN
        v_healthy:=coalesce(v_status,0)=200
          AND (v_content::jsonb->'data'->>'login')='true';
      EXCEPTION WHEN OTHERS THEN v_healthy:=coalesce(v_status,0)=200; END;
      v_new_status := CASE
        WHEN v_healthy THEN 'healthy'
        WHEN coalesce(v_status,0)=0 THEN 'error'
        WHEN coalesce(v_status,0)=401 THEN 'expired'
        WHEN coalesce(v_status,0)=429 THEN 'rate_limited'
        ELSE 'expired' END;
    ELSE
      v_healthy := coalesce(v_status,0)=200;
      v_new_status := CASE coalesce(v_status,0)
        WHEN 200 THEN 'healthy' WHEN 302 THEN 'expired'
        WHEN 401 THEN 'expired' WHEN 403 THEN 'challenged'
        WHEN 429 THEN 'rate_limited' ELSE 'error' END;
    END IF;
    UPDATE zapp.cookies_config
      SET is_healthy=v_healthy, health_status=v_new_status,
          health_error=format('probe2ph/%s/%s http=%s at %s | head=%s',
            r.probe_version, r.probe_auth,
            coalesce(v_status::text,
              CASE WHEN v_timed_out THEN 'timeout' ELSE 'no_response' END),
            now(), left(coalesce(v_content,''),60)),
          last_health_check_at=now()
      WHERE servico=r.servico;
    INSERT INTO zapp.cookie_probe_log(
        servico,http_status,response_preview,is_healthy,probe_ms,probe_error,
        probe_version,probe_auth)
    VALUES(
        r.servico,v_status,left(coalesce(v_content,''),200),v_healthy,
        CASE WHEN v_created IS NOT NULL
             THEN (extract(epoch from (v_created-r.dispatched_at))*1000)::int
             ELSE NULL END,
        CASE WHEN v_status IS NULL THEN 'no_response_within_grace' ELSE NULL END,
        r.probe_version, r.probe_auth);
    PERFORM zapp.fn_circuit_record(r.servico, v_healthy);
    DELETE FROM zapp.cookie_probe_pending WHERE servico=r.servico;
    v_processed:=v_processed+1;
  END LOOP;
  RETURN jsonb_build_object('phase','collect','processed',v_processed,'still_pending',v_pending);
END;
$$;


--
-- Name: fn_cookie_probe_cycle(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_cookie_probe_cycle() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'net'
    AS $$
DECLARE
  v_collect  jsonb;
  v_dispatch jsonb;
  v_alerts   jsonb;
BEGIN
  v_collect  := zapp.fn_cookie_probe_collect();
  v_dispatch := zapp.fn_cookie_probe_dispatch();
  v_alerts   := zapp.fn_lux_alert_check();
  RETURN jsonb_build_object(
    'collect',  v_collect,
    'dispatch', v_dispatch,
    'alerts',   v_alerts
  );
END;
$$;


--
-- Name: fn_cookie_probe_dispatch(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_cookie_probe_dispatch() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'net'
    AS $$
DECLARE
  v_lusha_cookie  TEXT;
  v_lusha_token   TEXT;
  v_lc_cookie     TEXT;
  v_lc_token      TEXT;
  v_li_cookie     TEXT;
  v_li_csrf       TEXT;
  v_req_lusha     BIGINT;
  v_req_lc        BIGINT;
  v_req_li        BIGINT;
  v_fired         INT  := 0;
  v_lusha_mode    TEXT := 'v2_cookie';
  v_lc_auth       TEXT := 'none';
BEGIN
  SELECT cookie, token INTO v_lusha_cookie, v_lusha_token FROM zapp.cookies_config WHERE servico='lusha';
  SELECT cookie, token INTO v_lc_cookie, v_lc_token FROM zapp.cookies_config WHERE servico='leadcontact';
  SELECT cookie, csrf_token INTO v_li_cookie, v_li_csrf FROM zapp.cookies_config WHERE servico='linkedin';

  -- █ LUSHA probe — DUAL MODE: V3 (api_key) se token>=32 chars, else V2 (JWT cookie)
  IF length(coalesce(v_lusha_token,'')) >= 32 THEN
    -- V3: GET api.lusha.com/v3 com api_key header (sem cookie JWT)
    v_lusha_mode := 'v3_apikey';
    SELECT net.http_get(
      url := 'https://api.lusha.com/v3/contacts/prospecting/filters/departments',
      headers := jsonb_build_object(
        'api_key', v_lusha_token,
        'Accept', 'application/json',
        'User-Agent', 'Mozilla/5.0'),
      timeout_milliseconds := 6000
    ) INTO v_req_lusha;
    INSERT INTO zapp.cookie_probe_pending(servico,request_id,dispatched_at,probe_version,probe_auth)
    VALUES('lusha',v_req_lusha,now(),'v3','apikey')
    ON CONFLICT (servico) DO UPDATE SET request_id=EXCLUDED.request_id,dispatched_at=EXCLUDED.dispatched_at,probe_version='v3',probe_auth='apikey';
    v_fired := v_fired+1;
  ELSIF length(coalesce(v_lusha_cookie,'')) > 20 THEN
    -- V2: GET dashboard-services.lusha.com/v2 com Cookie JWT (modo atual)
    v_lusha_mode := 'v2_cookie';
    SELECT net.http_get(
      url := 'https://dashboard-services.lusha.com/v2/filters/companyName?text=PROBE',
      headers := jsonb_build_object(
        'Cookie',v_lusha_cookie,'Origin','https://dashboard.lusha.com',
        'Referer','https://dashboard.lusha.com/','Accept','application/json',
        'User-Agent','Mozilla/5.0 (Windows NT 10.0; Win64; x64)'),
      timeout_milliseconds := 6000
    ) INTO v_req_lusha;
    INSERT INTO zapp.cookie_probe_pending(servico,request_id,dispatched_at,probe_version,probe_auth)
    VALUES('lusha',v_req_lusha,now(),'v2','cookie')
    ON CONFLICT (servico) DO UPDATE SET request_id=EXCLUDED.request_id,dispatched_at=EXCLUDED.dispatched_at,probe_version='v2',probe_auth='cookie';
    v_fired := v_fired+1;
  END IF;

  -- █ LEADCONTACT probe — Bearer primary, SESSION fallback
  IF length(coalesce(v_lc_token,'')) > 10 OR length(coalesce(v_lc_cookie,'')) > 10 THEN
    v_lc_auth := CASE WHEN length(coalesce(v_lc_token,'')) > 10 THEN 'bearer' ELSE 'cookie' END;
    SELECT net.http_post(
      url := 'https://api.leadcontact.ai/api/auth/check_login',
      body := '{}'::jsonb,
      headers := CASE
        WHEN length(coalesce(v_lc_token,'')) > 10
        THEN jsonb_build_object(
          'Authorization','Bearer '||v_lc_token,'Content-Type','application/json',
          'Origin','chrome-extension://imhlnhlbiencamnbpigopiibddajimep','User-Agent','Mozilla/5.0')
        ELSE jsonb_build_object(
          'Cookie',v_lc_cookie,'Content-Type','application/json',
          'Origin','chrome-extension://imhlnhlbiencamnbpigopiibddajimep','User-Agent','Mozilla/5.0')
      END,
      timeout_milliseconds := 6000
    ) INTO v_req_lc;
    INSERT INTO zapp.cookie_probe_pending(servico,request_id,dispatched_at,probe_version,probe_auth)
    VALUES('leadcontact',v_req_lc,now(),'v1',v_lc_auth)
    ON CONFLICT (servico) DO UPDATE SET request_id=EXCLUDED.request_id,dispatched_at=EXCLUDED.dispatched_at,probe_auth=EXCLUDED.probe_auth;
    v_fired := v_fired+1;
  END IF;

  -- █ LINKEDIN probe — inalterado (cookie morto, circuit aberto, monitor)
  IF length(coalesce(v_li_cookie,'')) > 20 THEN
    SELECT net.http_get(
      url := 'https://www.linkedin.com/voyager/api/me',
      headers := jsonb_build_object(
        'Cookie',v_li_cookie,'csrf-token',coalesce(v_li_csrf,''),
        'Accept','application/vnd.linkedin.normalized+json+2.1',
        'x-restli-protocol-version','2.0.0','User-Agent','Mozilla/5.0 (Windows NT 10.0; Win64; x64)'),
      timeout_milliseconds := 6000
    ) INTO v_req_li;
    INSERT INTO zapp.cookie_probe_pending(servico,request_id,dispatched_at,probe_version,probe_auth)
    VALUES('linkedin',v_req_li,now(),'v1','cookie')
    ON CONFLICT (servico) DO UPDATE SET request_id=EXCLUDED.request_id,dispatched_at=EXCLUDED.dispatched_at;
    v_fired := v_fired+1;
  END IF;

  RETURN jsonb_build_object(
    'phase','dispatch','fired',v_fired,
    'lusha_mode',v_lusha_mode,'lc_auth',v_lc_auth,
    'req_ids',jsonb_build_object('lusha',v_req_lusha,'leadcontact',v_req_lc,'linkedin',v_req_li),
    'dispatched_at',now());
END;
$$;


--
-- Name: fn_cookie_real_probe(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_cookie_real_probe() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'net'
    AS $$
DECLARE
  v_lusha_cookie TEXT;
  v_lc_cookie    TEXT;
  v_li_cookie    TEXT;
  v_li_csrf      TEXT;
  v_req_lusha    BIGINT;
  v_req_lc       BIGINT;
  v_req_li       BIGINT;
  v_total_reqs   INT := 0;
  v_done         INT;
  v_i            INT;
  v_status       INT;
  v_content      TEXT;
  v_healthy      BOOLEAN;
  v_started      TIMESTAMPTZ := clock_timestamp();
BEGIN
  -- ── 1. LER COOKIES ────────────────────────────────────────────────────
  SELECT cookie INTO v_lusha_cookie FROM zapp.cookies_config WHERE servico='lusha';
  SELECT cookie INTO v_lc_cookie    FROM zapp.cookies_config WHERE servico='leadcontact';
  SELECT cookie, csrf_token INTO v_li_cookie, v_li_csrf
    FROM zapp.cookies_config WHERE servico='linkedin';

  -- ── 2. DISPARAR TODOS OS REQUESTS EM PARALELO ─────────────────────────
  -- Todas as 3 calls são assíncronas (pg_net background worker)
  -- Elas correm em PARALELO — não sequencialmente

  IF length(coalesce(v_lusha_cookie,'')) > 20 THEN
    SELECT net.http_get(
      url     := 'https://dashboard-services.lusha.com/v2/filters/companyName?text=PROBE',
      headers := jsonb_build_object(
        'Cookie',     v_lusha_cookie,
        'Origin',     'https://dashboard.lusha.com',
        'Referer',    'https://dashboard.lusha.com/',
        'Accept',     'application/json',
        'User-Agent', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)'
      ),
      timeout_milliseconds := 6000
    ) INTO v_req_lusha;
    v_total_reqs := v_total_reqs + 1;
  END IF;

  IF length(coalesce(v_lc_cookie,'')) > 10 THEN
    SELECT net.http_post(
      url     := 'https://api.leadcontact.ai/api/auth/check_login',
      body    := '{}'::jsonb,
      headers := jsonb_build_object(
        'Cookie',       v_lc_cookie,
        'Content-Type', 'application/json',
        'Origin',       'chrome-extension://imhlnhlbiencamnbpigopiibddajimep',
        'User-Agent',   'Mozilla/5.0'
      ),
      timeout_milliseconds := 6000
    ) INTO v_req_lc;
    v_total_reqs := v_total_reqs + 1;
  END IF;

  IF length(coalesce(v_li_cookie,'')) > 20 THEN
    SELECT net.http_get(
      url     := 'https://www.linkedin.com/voyager/api/me',
      headers := jsonb_build_object(
        'Cookie',                    v_li_cookie,
        'csrf-token',                coalesce(v_li_csrf,''),
        'Accept',                    'application/vnd.linkedin.normalized+json+2.1',
        'x-restli-protocol-version', '2.0.0',
        'User-Agent',                'Mozilla/5.0 (Windows NT 10.0; Win64; x64)'
      ),
      timeout_milliseconds := 6000
    ) INTO v_req_li;
    v_total_reqs := v_total_reqs + 1;
  END IF;

  -- ── 3. LOOP UNIFICADO: aguardar TODOS responderem (max 9s) ────────────
  -- 18 × 500ms = 9s > HTTP timeout de 6s — garante que todas chegam
  v_i := 0;
  LOOP
    EXIT WHEN v_i >= 18;
    PERFORM pg_sleep(0.5);
    v_i := v_i + 1;

    SELECT count(*) INTO v_done
    FROM net._http_response
    WHERE id IN (v_req_lusha, v_req_lc, v_req_li)
      AND status_code IS NOT NULL;

    EXIT WHEN v_done >= v_total_reqs;
  END LOOP;

  -- ── 4. PROCESSAR LUSHA ────────────────────────────────────────────────
  IF v_req_lusha IS NOT NULL THEN
    SELECT r.status_code, left(r.content::text, 300)
      INTO v_status, v_content
    FROM net._http_response r WHERE r.id = v_req_lusha;

    v_healthy := coalesce(v_status,0) = 200;
    UPDATE zapp.cookies_config SET
      is_healthy           = v_healthy,
      health_status        = CASE coalesce(v_status,0)
                               WHEN 200 THEN 'healthy'
                               WHEN 401 THEN 'expired'
                               WHEN 403 THEN 'challenged'
                               WHEN 429 THEN 'rate_limited'
                               ELSE       'error' END,
      health_error         = format('real_probe v2 http=%s at %s | head=%s',
                               coalesce(v_status::text,'timeout'), now(),
                               left(coalesce(v_content,''),80)),
      last_health_check_at = now()
    WHERE servico = 'lusha';

    INSERT INTO zapp.cookie_probe_log (servico, http_status, response_preview, is_healthy, probe_ms)
    VALUES ('lusha', v_status, left(coalesce(v_content,''),200), v_healthy,
            (extract(epoch from clock_timestamp()-v_started)*1000)::int);

    -- sincronizar com circuit breaker
    PERFORM zapp.fn_circuit_record('lusha', v_healthy);
  END IF;

  -- ── 5. PROCESSAR LEADCONTACT ──────────────────────────────────────────
  IF v_req_lc IS NOT NULL THEN
    SELECT r.status_code, left(r.content::text, 300)
      INTO v_status, v_content
    FROM net._http_response r WHERE r.id = v_req_lc;

    BEGIN
      v_healthy := coalesce(v_status,0)=200
                   AND (v_content::jsonb->'data'->>'login')='true';
    EXCEPTION WHEN OTHERS THEN
      v_healthy := false;
    END;

    UPDATE zapp.cookies_config SET
      is_healthy           = v_healthy,
      health_status        = CASE
                               WHEN v_healthy               THEN 'healthy'
                               WHEN coalesce(v_status,0)=0  THEN 'error'
                               ELSE 'expired' END,
      health_error         = format('real_probe v2 http=%s login=%s at %s',
                               coalesce(v_status::text,'timeout'),
                               CASE WHEN v_healthy THEN 'true' ELSE 'false' END,
                               now()),
      last_health_check_at = now()
    WHERE servico = 'leadcontact';

    INSERT INTO zapp.cookie_probe_log (servico, http_status, response_preview, is_healthy, probe_ms)
    VALUES ('leadcontact', v_status, left(coalesce(v_content,''),200), v_healthy,
            (extract(epoch from clock_timestamp()-v_started)*1000)::int);

    PERFORM zapp.fn_circuit_record('leadcontact', v_healthy);
  END IF;

  -- ── 6. PROCESSAR LINKEDIN ─────────────────────────────────────────────
  IF v_req_li IS NOT NULL THEN
    SELECT r.status_code, left(r.content::text, 200)
      INTO v_status, v_content
    FROM net._http_response r WHERE r.id = v_req_li;

    v_healthy := coalesce(v_status,0) = 200;
    UPDATE zapp.cookies_config SET
      is_healthy           = v_healthy,
      health_status        = CASE coalesce(v_status,0)
                               WHEN 200 THEN 'healthy'
                               WHEN 302 THEN 'expired'
                               WHEN 400 THEN 'expired'
                               WHEN 403 THEN 'challenged'
                               WHEN 429 THEN 'rate_limited'
                               ELSE       'error' END,
      health_error         = format('real_probe v2 http=%s at %s',
                               coalesce(v_status::text,'timeout'), now()),
      last_health_check_at = now()
    WHERE servico = 'linkedin';

    INSERT INTO zapp.cookie_probe_log (servico, http_status, response_preview, is_healthy, probe_ms)
    VALUES ('linkedin', v_status, left(coalesce(v_content,''),200), v_healthy,
            (extract(epoch from clock_timestamp()-v_started)*1000)::int);

    PERFORM zapp.fn_circuit_record('linkedin', v_healthy);
  END IF;

  RETURN jsonb_build_object(
    'probed_at',   v_started,
    'duration_ms', (extract(epoch from clock_timestamp()-v_started)*1000)::int,
    'requests_fired', v_total_reqs,
    'iterations_used', v_i,
    'req_ids', jsonb_build_object(
      'lusha', v_req_lusha, 'leadcontact', v_req_lc, 'linkedin', v_req_li
    )
  );
END;
$$;


--
-- Name: fn_count_total_rows(text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_count_total_rows(p_schema text, p_table text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_count bigint;
BEGIN
  EXECUTE format('SELECT COUNT(*) FROM %I.%I', p_schema, p_table)
    INTO v_count;
  RETURN COALESCE(v_count, 0);
END $$;


--
-- Name: fn_create_notification(text, text, text, uuid, uuid, text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_create_notification(p_type text, p_title text, p_message text, p_contact_id uuid DEFAULT NULL::uuid, p_deal_id uuid DEFAULT NULL::uuid, p_instance text DEFAULT 'wpp2'::text, p_priority text DEFAULT 'normal'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_id uuid;
BEGIN
  INSERT INTO evolution_notifications (notification_type, title, message, contact_id, deal_id, priority)
  VALUES (p_type, p_title, p_message, p_contact_id, p_deal_id, p_priority)
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


--
-- Name: fn_create_realtime_event(text, jsonb, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_create_realtime_event(p_type text, p_payload jsonb, p_instance text DEFAULT 'wpp2'::text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_id bigint;
BEGIN INSERT INTO evolution_realtime_events (event_type,payload,instance_name) VALUES (p_type,p_payload,p_instance) RETURNING id INTO v_id; RETURN v_id; EXCEPTION WHEN OTHERS THEN RETURN -1; END; $$;


--
-- Name: fn_create_transfer(uuid, uuid, uuid, uuid, text, text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_create_transfer(p_conversation_id uuid, p_from_agent_id uuid, p_to_agent_id uuid DEFAULT NULL::uuid, p_to_queue_id uuid DEFAULT NULL::uuid, p_transfer_type text DEFAULT 'direct'::text, p_priority text DEFAULT 'P3'::text, p_context_summary text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
    v_transfer_id UUID;
BEGIN
    INSERT INTO zapp.conversation_transfers (
        conversation_id,
        from_agent_id,
        to_agent_id,
        to_queue_id,
        transfer_type,
        priority,
        context_summary,
        sla_deadline
    ) VALUES (
        p_conversation_id,
        p_from_agent_id,
        p_to_agent_id,
        p_to_queue_id,
        p_transfer_type,
        p_priority,
        p_context_summary,
        CASE 
            WHEN p_priority = 'P1' THEN NOW() + INTERVAL '15 minutes'
            WHEN p_priority = 'P2' THEN NOW() + INTERVAL '1 hour'
            WHEN p_priority = 'P3' THEN NOW() + INTERVAL '4 hours'
            ELSE NOW() + INTERVAL '24 hours'
        END
    ) RETURNING id INTO v_transfer_id;
    
    RETURN v_transfer_id;
END;
$$;


--
-- Name: fn_create_transfer(text, text, text, text, text, integer, text, text, text, text[]); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_create_transfer(p_source_instance text, p_target_instance text, p_remote_jid text, p_reason text, p_category text DEFAULT 'outro'::text, p_priority integer DEFAULT 2, p_transfer_type text DEFAULT 'internal'::text, p_source_operator text DEFAULT NULL::text, p_context_summary text DEFAULT NULL::text, p_tags text[] DEFAULT '{}'::text[]) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$ DECLARE v_cid uuid; v_cname text; v_convid uuid; v_msgs jsonb; v_tid uuid; v_tk int; BEGIN SELECT id, push_name INTO v_cid, v_cname FROM evolution_contacts WHERE remote_jid=p_remote_jid LIMIT 1; SELECT id INTO v_convid FROM evolution_conversations WHERE remote_jid=p_remote_jid AND instance_name=p_source_instance LIMIT 1; SELECT COALESCE(jsonb_agg(row_to_json(m)),'[]'::jsonb) INTO v_msgs FROM (SELECT message_id, from_me, left(content,200) AS content, message_type, created_at::timestamp(0) AS ts FROM evolution_messages WHERE remote_jid=p_remote_jid AND instance_name=p_source_instance ORDER BY created_at DESC LIMIT 5) m; INSERT INTO conversation_transfers(source_instance,source_conversation_id,source_operator,target_instance,contact_id,remote_jid,contact_name,transfer_type,category,reason,context_summary,context_messages,tags,priority) VALUES(p_source_instance,v_convid,p_source_operator,p_target_instance,v_cid,p_remote_jid,v_cname,p_transfer_type,p_category,p_reason,p_context_summary,v_msgs,p_tags,p_priority) RETURNING id,ticket_number INTO v_tid,v_tk; RETURN jsonb_build_object('ok',true,'transfer_id',v_tid,'ticket_number',v_tk,'contact_name',v_cname,'context_messages_count',jsonb_array_length(v_msgs),'expires_at',(SELECT expires_at FROM conversation_transfers WHERE id=v_tid)); END $$;


--
-- Name: fn_cron_guardian(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_cron_guardian() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'cron', 'pg_catalog'
    AS $_$
DECLARE
  v_recreated text[] := '{}';
  v_fixed     text[] := '{}';
  v_count int;
  v_src text;
  v_new text;
  v_before text;   -- snapshot antes de cada patch
BEGIN
  -- === GUARDIAN DE CRONS ===
  SELECT COUNT(*) INTO v_count FROM cron.job WHERE jobname='v2-pipeline-heartbeat' AND active;
  IF v_count = 0 THEN
    PERFORM cron.schedule('v2-pipeline-heartbeat','*/30 * * * *','SELECT evo.fn_v2_pipeline_heartbeat()');
    v_recreated := array_append(v_recreated, 'v2-pipeline-heartbeat');
  END IF;

  SELECT COUNT(*) INTO v_count FROM cron.job WHERE jobname='vacuum-messages-2h' AND active;
  IF v_count = 0 THEN
    PERFORM cron.schedule('vacuum-messages-2h','25 */2 * * *','VACUUM ANALYZE evo.evolution_messages');
    v_recreated := array_append(v_recreated, 'vacuum-messages-2h');
  END IF;

  SELECT COUNT(*) INTO v_count FROM cron.job WHERE jobname='vacuum-contacts-2h' AND active;
  IF v_count = 0 THEN
    PERFORM cron.schedule('vacuum-contacts-2h','35 */2 * * *','VACUUM ANALYZE evo.evolution_contacts');
    v_recreated := array_append(v_recreated, 'vacuum-contacts-2h');
  END IF;

  -- === GUARDIAN DE fn_system_health_score ===
  SELECT prosrc INTO v_src FROM pg_proc WHERE proname='fn_system_health_score';
  IF v_src IS NULL THEN
    RETURN jsonb_build_object('error','fn_system_health_score nao encontrada');
  END IF;
  v_new := v_src;

  -- PROTEÇÃO 1: cron_health sem filtro "does not exist"
  IF v_new NOT ILIKE '%does not exist%' THEN
    v_before := v_new;
    v_new := replace(v_new,
      $O$SELECT COUNT(*) INTO v FROM cron.job_run_details WHERE status='failed' AND start_time IS NOT NULL AND start_time>NOW()-INTERVAL '24 hours';$O$,
      $N$SELECT COUNT(*) INTO v FROM cron.job_run_details WHERE status='failed' AND start_time IS NOT NULL AND start_time>NOW()-INTERVAL '24 hours' AND return_message NOT LIKE '%does not exist%' AND return_message NOT LIKE '%invalid input value for enum webhook_event_status%';$N$
    );
    IF v_new = v_before THEN  -- tentativa 24h falhou, tentar 1h
      v_new := replace(v_new,
        $O$SELECT COUNT(*) INTO v FROM cron.job_run_details WHERE status='failed' AND start_time IS NOT NULL AND start_time>NOW()-INTERVAL '1 hour';$O$,
        $N$SELECT COUNT(*) INTO v FROM cron.job_run_details WHERE status='failed' AND start_time IS NOT NULL AND start_time>NOW()-INTERVAL '1 hour' AND return_message NOT LIKE '%does not exist%' AND return_message NOT LIKE '%invalid input value for enum webhook_event_status%';$N$
      );
    END IF;
    -- FIX: comparar v_new vs v_before (não vs v_src original)
    IF v_new <> v_before THEN
      v_fixed := array_append(v_fixed, 'fn_health:cron_filter');
    ELSE
      v_fixed := array_append(v_fixed, 'fn_health:cron_filter:PATTERN_NOT_FOUND');
    END IF;
  END IF;

  -- PROTEÇÃO 2: partition_indexes com tabela errada
  -- Detectar EXATAMENTE: 'evolution_messages','message_id' (sem _wpp2)
  -- Usar posição para verificar que NÃO é wpp2
  IF position($P$('evolution_messages','message_id_instance_name_key'$P$ IN v_new) > 0
     AND position($P$('evolution_messages_wpp2','message_id_instance_name_key'$P$ IN v_new) = 0
  THEN
    v_before := v_new;
    v_new := replace(v_new,
      $O$('evolution_messages','message_id_instance_name_key','evo'),('evolution_messages','id_idx','evo')$O$,
      $N$('evolution_messages_wpp2','message_id_instance_name_key','evo'),('evolution_messages_wpp2','id_idx','evo')$N$
    );
    -- FIX: comparar v_new vs v_before desta etapa
    IF v_new <> v_before THEN
      v_fixed := array_append(v_fixed, 'fn_health:partition_idx_table');
    ELSE
      v_fixed := array_append(v_fixed, 'fn_health:partition_idx_table:PATTERN_NOT_FOUND');
    END IF;
  END IF;

  -- Aplicar se houve mudanças reais
  IF v_new <> v_src THEN
    EXECUTE format(
      'CREATE OR REPLACE FUNCTION zapp.fn_system_health_score() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,evo,zapp,ops,extensions,pg_catalog AS %L',
      v_new
    );
  END IF;

  RETURN jsonb_build_object(
    'checked', 3,
    'recreated', to_jsonb(v_recreated),
    'fixed', to_jsonb(v_fixed),
    'ts', now()
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('error', SQLERRM, 'ts', now());
END;
$_$;


--
-- Name: fn_d30_execute_full_pipeline(boolean); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_d30_execute_full_pipeline(p_dry_run boolean DEFAULT true) RETURNS TABLE(fase text, etapa text, detalhe text, status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_backup_schema TEXT;
  v_snapshot_atualizado BOOLEAN := false;
  v_tabelas_drop INT;
BEGIN
  IF NOT p_dry_run AND EXISTS(SELECT 1 FROM pg_namespace WHERE nspname = 'legacy_staging') THEN
    INSERT INTO migration_snapshot_d30 (entidade, qtd_legacy, qtd_evolution, qtd_migrados, qtd_novos_pos_migracao, taxa_migracao_pct, notes)
    VALUES (
      'contatos_final_d30',
      (SELECT COUNT(*)::int FROM legacy_staging.contacts),
      (SELECT COUNT(*)::int FROM evolution_contacts),
      (SELECT COUNT(*)::int FROM evolution_contacts WHERE raw_data ->> 'legacy_id' IS NOT NULL),
      (SELECT COUNT(*)::int FROM evolution_contacts WHERE raw_data ->> 'legacy_id' IS NULL),
      ROUND(100.0 * (SELECT COUNT(*) FROM evolution_contacts WHERE raw_data ->> 'legacy_id' IS NOT NULL) 
            / NULLIF((SELECT COUNT(*) FROM legacy_staging.contacts), 0), 2),
      'Snapshot FINAL no momento do D+30 execution'
    );
    v_snapshot_atualizado := true;
  END IF;
  
  RETURN QUERY SELECT 
    '1_snapshot'::text, 'refresh_numeros_finais'::text,
    CASE WHEN v_snapshot_atualizado THEN 'Snapshot final inserido' ELSE 'Modo dry-run ou schema não existe' END::text,
    CASE WHEN v_snapshot_atualizado THEN 'OK' ELSE 'SKIP' END::text;
  
  IF NOT p_dry_run THEN
    FOR fase, etapa IN SELECT 'backup' as a, b.etapa FROM fn_d30_backup_legacy_staging() b LOOP
      detalhe := etapa; status := 'OK';
      RETURN NEXT;
    END LOOP;
  ELSE
    RETURN QUERY SELECT '2_backup'::text, 'dry_run'::text, 
      'Criaria schema backup_legacy_<timestamp>'::text, 'DRY_RUN'::text;
  END IF;
  
  RETURN QUERY 
    SELECT '3_validation'::text, c.action::text, c.detail::text, 
      CASE WHEN c.action = 'blocked' THEN 'BLOCKED' 
           WHEN c.action = 'dry_run' THEN 'DRY_RUN' 
           ELSE 'OK' END::text
    FROM fn_legacy_staging_cleanup(true) c;
  
  IF NOT p_dry_run THEN
    SELECT COUNT(*)::int INTO v_tabelas_drop 
    FROM information_schema.tables WHERE table_schema = 'legacy_staging';
    RETURN QUERY 
      SELECT '4_drop'::text, c.action::text, c.detail::text,
        CASE WHEN c.action = 'executed' THEN '🏆 DONE' 
             WHEN c.action = 'blocked' THEN 'BLOCKED'
             ELSE 'INFO' END::text
      FROM fn_legacy_staging_cleanup(false) c;
  ELSE
    RETURN QUERY SELECT '4_drop'::text, 'dry_run'::text,
      'DROP SCHEMA legacy_staging CASCADE (aguardando 15/05)'::text, 'DRY_RUN'::text;
  END IF;
  
  RETURN QUERY SELECT '5_done'::text, 'pipeline_finished'::text,
    'Pipeline D+30 finalizado. Checar v_migration_reconciliation.'::text, '🏆'::text;
END;
$$;


--
-- Name: fn_d30_reminder_check(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_d30_reminder_check() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_first_migration TIMESTAMPTZ;
  v_days_since NUMERIC;
  v_legacy_exists BOOLEAN;
  v_existing_alert_id UUID;
BEGIN
  SELECT EXISTS(SELECT 1 FROM pg_namespace WHERE nspname = 'legacy_staging') 
    INTO v_legacy_exists;
  
  IF NOT v_legacy_exists THEN
    UPDATE webhook_health_alerts
    SET resolved_at = now(),
        details = details || jsonb_build_object('auto_resolved', true, 'reason', 'legacy_staging foi dropado')
    WHERE alert_type IN ('d30_approaching', 'd30_ready', 'd30_overdue')
      AND resolved_at IS NULL;
    RETURN;
  END IF;
  
  SELECT MIN(executed_at) INTO v_first_migration FROM zapp.migration_audit;
  v_days_since := EXTRACT(EPOCH FROM (now() - v_first_migration)) / 86400;
  
  IF v_days_since >= 27 AND v_days_since < 30 THEN
    SELECT id INTO v_existing_alert_id FROM webhook_health_alerts 
    WHERE alert_type = 'd30_approaching' AND resolved_at IS NULL LIMIT 1;
    IF v_existing_alert_id IS NULL THEN
      INSERT INTO webhook_health_alerts (alert_type, severity, title, details)
      VALUES ('d30_approaching','WARNING','🟡 D+30 se aproximando - preparar DROP legacy_staging',
        jsonb_build_object('dias_desde_migracao', ROUND(v_days_since, 1),
          'dias_para_d30', ROUND(30 - v_days_since, 1),
          'acao_recomendada', 'Revisar checklist + rodar fn_d30_execute_full_pipeline(true) em dry-run',
          'comando_execucao', 'SELECT * FROM fn_d30_execute_full_pipeline(false);'));
    END IF;
  ELSIF v_days_since >= 30 THEN
    SELECT id INTO v_existing_alert_id FROM webhook_health_alerts 
    WHERE alert_type = 'd30_ready' AND resolved_at IS NULL LIMIT 1;
    IF v_existing_alert_id IS NULL THEN
      INSERT INTO webhook_health_alerts (alert_type, severity, title, details)
      VALUES ('d30_ready','CRITICAL','🔴 D+30 atingido - EXECUTAR DROP legacy_staging',
        jsonb_build_object('dias_desde_migracao', ROUND(v_days_since, 1),
          'dias_apos_d30', ROUND(v_days_since - 30, 1),
          'tabelas_staging', (SELECT COUNT(*)::int FROM information_schema.tables WHERE table_schema = 'legacy_staging'),
          'comando_execucao', 'SELECT * FROM fn_d30_execute_full_pipeline(false);',
          'acao_recomendada', 'Executar pipeline D+30 agora. Backup automático incluído.'));
    END IF;
  ELSIF v_days_since >= 60 THEN
    SELECT id INTO v_existing_alert_id FROM webhook_health_alerts 
    WHERE alert_type = 'd30_overdue' AND resolved_at IS NULL LIMIT 1;
    IF v_existing_alert_id IS NULL THEN
      INSERT INTO webhook_health_alerts (alert_type, severity, title, details)
      VALUES ('d30_overdue','CRITICAL','🚨 D+30 ATRASADO - legacy_staging deveria ter sido dropado',
        jsonb_build_object('dias_desde_migracao', ROUND(v_days_since, 1),
          'dias_de_atraso', ROUND(v_days_since - 30, 1),
          'urgencia', 'ALTA - acumulando dívida técnica + LGPD',
          'comando_execucao', 'SELECT * FROM fn_d30_execute_full_pipeline(false);'));
    END IF;
  END IF;
END;
$$;


