--

CREATE FUNCTION zapp.fn_dedup_connection_alert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.alert_type IN ('connection_lost','connection_restored') THEN
    IF EXISTS (SELECT 1 FROM evolution_alerts WHERE alert_type=NEW.alert_type AND acknowledged=false AND created_at > NOW()-INTERVAL '5 minutes') THEN
      RETURN NULL;
    END IF;
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: fn_detect_schema_drift(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_detect_schema_drift() RETURNS TABLE(function_name text, suspected_column text, suspected_table text, severity text, hint text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_fn RECORD; v_tbl RECORD; v_match RECORD;
BEGIN
  FOR v_fn IN SELECT p.proname, pg_get_functiondef(p.oid) AS src FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prolang=(SELECT oid FROM pg_language WHERE lanname='plpgsql') AND p.proname NOT LIKE 'fn_detect_schema_drift%' LOOP
    FOR v_tbl IN SELECT t.table_name, array_agg(c.column_name::text) AS real_cols FROM information_schema.tables t JOIN information_schema.columns c ON c.table_name=t.table_name AND c.table_schema=t.table_schema WHERE t.table_schema='public' GROUP BY t.table_name LOOP
      FOR v_match IN SELECT DISTINCT (regexp_matches(v_fn.src,'(?:"'||v_tbl.table_name||'"|\m'||v_tbl.table_name||'\M)\s*\.\s*"?([a-zA-Z_][a-zA-Z0-9_]*)"?','g'))[1] AS col LOOP
        IF v_match.col IS NOT NULL AND v_match.col NOT IN ('*','oid','tableoid') AND NOT (v_match.col=ANY(v_tbl.real_cols)) THEN
          function_name:=v_fn.proname; suspected_column:=v_match.col; suspected_table:=v_tbl.table_name; severity:='high'; hint:='Column not found'; RETURN NEXT;
        END IF;
      END LOOP;
    END LOOP;
  END LOOP;
END; $$;


--
-- Name: fn_dlq_compute_next_retry(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_dlq_compute_next_retry(p_attempt integer) RETURNS timestamp with time zone
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN RETURN now() + make_interval(secs:=LEAST(POWER(2,p_attempt)*60,86400)); END; $$;


--
-- Name: fn_dlq_process_retries(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_dlq_process_retries(p_batch integer DEFAULT 10) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v integer;
BEGIN
  UPDATE evolution_webhook_dlq SET status='retrying'
  WHERE id IN (SELECT id FROM evolution_webhook_dlq WHERE status='pending' AND next_retry_at<=now() AND retry_count<5 ORDER BY next_retry_at LIMIT p_batch FOR UPDATE SKIP LOCKED);
  GET DIAGNOSTICS v=ROW_COUNT;
  RETURN v;
END;
$$;


