--
-- Name: fn_drop_logflare_slot(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_drop_logflare_slot() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp, pg_temp'
    AS $$
DECLARE
  v_pid int;
  v_lag_mb numeric;
  v_slot_active boolean;
  v_attempts int := 0;
BEGIN
  -- Verificar lag
  SELECT pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn)/1048576, active
  INTO v_lag_mb, v_slot_active
  FROM pg_replication_slots 
  WHERE slot_name = 'cainophile_nwl2ry0m';
  
  IF v_lag_mb IS NULL THEN
    RETURN 'Slot já foi dropado';
  END IF;
  
  -- Encontrar PID
  SELECT pa.pid INTO v_pid
  FROM pg_stat_activity pa
  WHERE pa.query LIKE '%cainophile%' AND pa.pid != pg_backend_pid()
  LIMIT 1;
  
  -- Terminar backend (SECURITY DEFINER como postgres)
  IF v_pid IS NOT NULL THEN
    PERFORM pg_terminate_backend(v_pid);
    -- Polling: esperar slot ficar inativo
    LOOP
      PERFORM pg_sleep(0.5);
      v_attempts := v_attempts + 1;
      SELECT active INTO v_slot_active FROM pg_replication_slots WHERE slot_name = 'cainophile_nwl2ry0m';
      EXIT WHEN v_slot_active = false OR v_attempts > 10;
    END LOOP;
  END IF;
  
  -- Tentar dropar
  SELECT active INTO v_slot_active FROM pg_replication_slots WHERE slot_name = 'cainophile_nwl2ry0m';
  IF v_slot_active THEN
    RETURN format('FALHA: slot ainda ativo após %s tentativas (lag: %s MB)', v_attempts, round(v_lag_mb,1));
  END IF;
  
  PERFORM pg_drop_replication_slot('cainophile_nwl2ry0m');
  RETURN format('SUCESSO: Slot dropado. WAL liberado: %s MB', round(v_lag_mb, 1));
EXCEPTION
  WHEN OTHERS THEN
    RETURN format('ERRO: %s', SQLERRM);
END;
$$;


--
-- Name: fn_edge_delete_evolution_credentials(uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_edge_delete_evolution_credentials(p_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'permission denied' USING ERRCODE = '42501';
  END IF;

  DELETE FROM evo.evolution_instance_credentials WHERE id = p_id;
  RETURN FOUND;
END;
$$;


--
-- Name: fn_edge_get_evolution_credentials(text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_edge_get_evolution_credentials(p_instance text DEFAULT 'wpp2'::text) RETURNS TABLE(instance_name text, api_url text, api_key text, health_status text, last_health_check timestamp with time zone, is_active boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_claims_role text := coalesce((NULLIF(current_setting('request.jwt.claims', true), ''))::jsonb->>'role', '');
BEGIN
  IF v_claims_role <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'forbidden: service_role required' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT c.instance_name::text,
         c.api_url::text,
         v.decrypted_secret::text AS api_key,
         c.health_status::text,
         c.last_health_check,
         c.is_active
  FROM evo.evolution_instance_credentials c
  CROSS JOIN LATERAL (
    SELECT ds.decrypted_secret FROM vault.decrypted_secrets ds WHERE ds.name = 'evolution_api_key' LIMIT 1
  ) v
  WHERE c.instance_name = p_instance;
END;
$$;


--
-- Name: FUNCTION fn_edge_get_evolution_credentials(p_instance text); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_edge_get_evolution_credentials(p_instance text) IS 'Edge fn evolution-credentials: entrega api_key (vault) + api_url (evo) sem expor vault/evo no PGRST_DB_SCHEMAS. Guarda: claims service_role. Criada 2026-07-06 (integração full).';


--
-- Name: fn_edge_upsert_evolution_credentials(text, text, text, text, text, boolean); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_edge_upsert_evolution_credentials(p_instance_name text, p_api_url text, p_api_key text, p_display_name text, p_department text, p_is_active boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_id uuid;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'permission denied' USING ERRCODE = '42501';
  END IF;

  INSERT INTO evo.evolution_instance_credentials (
    instance_name, api_url, api_key, display_name, department, is_active, updated_at
  )
  VALUES (
    p_instance_name, p_api_url, p_api_key, p_display_name, p_department,
    COALESCE(p_is_active, true), now()
  )
  ON CONFLICT (instance_name) DO UPDATE SET
    api_url      = EXCLUDED.api_url,
    api_key      = EXCLUDED.api_key,
    display_name = EXCLUDED.display_name,
    department   = EXCLUDED.department,
    is_active    = EXCLUDED.is_active,
    updated_at   = now()
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('id', v_id::text);
END;
$$;


