--
-- Name: fn_evolution_audit_score(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_evolution_audit_score() RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE v jsonb; v_total int; v_with_contact int; v_pct numeric;
BEGIN
  SELECT count(*), count(*) FILTER(WHERE contact_id IS NOT NULL) INTO v_total, v_with_contact FROM evolution_messages WHERE created_at>=now()-interval '7 days';
  v_pct := CASE WHEN v_total>0 THEN round(100.0*v_with_contact/v_total,2) ELSE 100 END;
  SELECT jsonb_build_object('score',CASE WHEN v_pct>=99 THEN 'A+' WHEN v_pct>=95 THEN 'A' WHEN v_pct>=90 THEN 'B' WHEN v_pct>=80 THEN 'C' ELSE 'D' END,'pct_with_contact',v_pct,'msgs_7d',v_total,'with_contact',v_with_contact) INTO v;
  RETURN v;
END;
$$;


