--
-- Name: fn_expire_old_media_queue(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_expire_old_media_queue() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  expired_count integer;
BEGIN
  UPDATE media_download_queue
  SET status = 'expired', error_message = 'WhatsApp media expired (>30 days)'
  WHERE status = 'pending'
    AND created_at < now() - interval '32 days';
  GET DIAGNOSTICS expired_count = ROW_COUNT;
  RETURN expired_count;
END;
$$;


--
-- Name: fn_expire_whatsapp_media_urls(integer, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_expire_whatsapp_media_urls(p_days_old integer DEFAULT 7, p_batch_limit integer DEFAULT 500) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo', 'zapp', 'pg_catalog'
    AS $$
DECLARE
  v_updated integer;
  v_still_pending integer;
BEGIN
  -- Marca como 'expired' os URLs do WhatsApp CDN mais antigos que p_days_old dias
  WITH to_expire AS (
    SELECT id
    FROM evo.evolution_messages
    WHERE (
      media_url LIKE '%mmg.whatsapp.net%'
      OR media_url LIKE '%cdn.whatsapp.net%'
      OR media_url LIKE '%mmg.whatsapp.com%'
      OR media_url LIKE '%media.whatsapp.net%'
    )
    AND (media_status IS NULL OR media_status NOT IN ('expired', 'ready'))
    AND created_at < NOW() - (p_days_old || ' days')::interval
    LIMIT p_batch_limit
  )
  UPDATE evo.evolution_messages em
  SET media_status = 'expired',
      updated_at = NOW()
  FROM to_expire t
  WHERE em.id = t.id;

  GET DIAGNOSTICS v_updated = ROW_COUNT;

  -- Conta quantos ainda precisam ser processados (próxima execução)
  SELECT COUNT(*) INTO v_still_pending
  FROM evo.evolution_messages
  WHERE (
    media_url LIKE '%mmg.whatsapp.net%'
    OR media_url LIKE '%cdn.whatsapp.net%'
    OR media_url LIKE '%mmg.whatsapp.com%'
  )
  AND (media_status IS NULL OR media_status NOT IN ('expired', 'ready'))
  AND created_at < NOW() - (p_days_old || ' days')::interval;

  RETURN jsonb_build_object(
    'updated', v_updated,
    'still_pending', v_still_pending,
    'days_threshold', p_days_old,
    'executed_at', NOW()
  );
END;
$$;


--
-- Name: fn_export_messages(text, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_export_messages(p_jid text, p_instance text DEFAULT 'wpp2'::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(data timestamp with time zone, remetente text, tipo text, conteudo text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
  SELECT created_at, CASE WHEN from_me THEN 'Eu' ELSE COALESCE(push_name,'Cliente') END, message_type, COALESCE(content,'[midia]') FROM evolution_messages WHERE remote_jid=p_jid AND instance_name=p_instance AND (p_from IS NULL OR created_at>=p_from) AND (p_to IS NULL OR created_at<=p_to) ORDER BY created_at;
$$;


--
-- Name: fn_extract_phone_from_jid(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_extract_phone_from_jid() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- 🔧 Grupos/broadcasts/newsletters NÃO têm phone_number — força NULL
  IF NEW.remote_jid IS NOT NULL AND (
    NEW.remote_jid LIKE '%@g.us' OR
    NEW.remote_jid LIKE '%@broadcast' OR
    NEW.remote_jid LIKE '%@newsletter'
  ) THEN
    NEW.phone_number := NULL;
  -- Contatos pessoais: extrair phone do JID se ainda não preenchido
  ELSIF NEW.remote_jid IS NOT NULL AND NEW.phone_number IS NULL THEN
    NEW.phone_number := LEFT(split_part(NEW.remote_jid, '@', 1), 20);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_force_autovacuum(text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_force_autovacuum(p_schema text, p_table text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_relid oid; v_dead int; v_live int; v_relkind char;
BEGIN
  IF p_schema NOT IN ('public','zapp','evo') THEN
    RETURN jsonb_build_object('error','schema_not_allowed','schema',p_schema);
  END IF;
  SELECT c.oid, c.relkind INTO v_relid, v_relkind
  FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE n.nspname=p_schema AND c.relname=p_table;
  IF v_relid IS NULL THEN
    RETURN jsonb_build_object('error','table_not_found','table',p_schema||'.'||p_table);
  END IF;
  IF v_relkind != 'r' THEN
    RETURN jsonb_build_object('error','not_a_table','relkind',v_relkind,'table',p_schema||'.'||p_table);
  END IF;
  SELECT n_dead_tup, n_live_tup INTO v_dead, v_live FROM pg_stat_user_tables WHERE relid=v_relid;
  EXECUTE 'ANALYZE '||p_schema||'.'||quote_ident(p_table);
  IF v_dead > 0 THEN
    EXECUTE format('ALTER TABLE %I.%I SET (autovacuum_vacuum_scale_factor=0.0001, autovacuum_vacuum_threshold=0, autovacuum_vacuum_cost_delay=2)', p_schema, p_table);
    PERFORM cron.schedule(
      'restore_av_'||p_schema||'_'||p_table,
      to_char(now()+INTERVAL '2 minutes','MI HH24')||' * * *',
      format('ALTER TABLE %I.%I RESET (autovacuum_vacuum_scale_factor, autovacuum_vacuum_threshold, autovacuum_vacuum_cost_delay); SELECT cron.unschedule(''restore_av_%s_%s'');', p_schema, p_table, p_schema, p_table)
    );
  END IF;
  RETURN jsonb_build_object(
    'analyzed',true,'table',p_schema||'.'||p_table,
    'dead_tuples_before',v_dead,'live_tuples',v_live,
    'autovacuum_triggered',v_dead>0,'restore_scheduled',v_dead>0,
    'note',CASE WHEN v_dead>0 THEN 'ANALYZE + scale_factor=0.0001 + threshold=0. Restaurado em 2min.' ELSE 'ANALYZE feito. Sem dead tuples.' END
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('error',SQLERRM,'table',p_schema||'.'||p_table);
END;
$$;


