--
-- Name: fn_gc_deleted_messages(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_gc_deleted_messages(p_days integer DEFAULT 90) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v              integer := 0;
  v_batch        integer;
  v_cutoff       timestamptz := now() - (p_days || ' days')::interval;
  v_created_floor timestamptz := now() - INTERVAL '7 days';
BEGIN
  SET LOCAL statement_timeout = '30min';
  LOOP
    WITH victims AS (
      SELECT id
      FROM evolution_messages
      WHERE deleted_at IS NOT NULL
        AND deleted_at < v_cutoff
        AND created_at < v_created_floor
      LIMIT 5000
    )
    DELETE FROM evolution_messages m
    USING victims vv
    WHERE m.id = vv.id;
    GET DIAGNOSTICS v_batch = ROW_COUNT;
    v := v + v_batch;
    EXIT WHEN v_batch = 0;
    PERFORM pg_sleep(0.1);
  END LOOP;
  RETURN v;
END;
$$;


