END;
$$;


--
-- Name: fn_get_active_alerts(text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_get_active_alerts(p_severity text DEFAULT NULL::text) RETURNS TABLE(id uuid, tipo text, title text, description text, severity text, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
  SELECT a.id, a.alert_type, a.title, a.description, a.severity, a.created_at
  FROM evolution_alerts a
  WHERE a.acknowledged = false
    AND (p_severity IS NULL OR a.severity = p_severity)
  ORDER BY
    CASE a.severity WHEN 'critical' THEN 1 WHEN 'high' THEN 2 WHEN 'medium' THEN 3 ELSE 4 END,
    a.created_at DESC;
$$;


