-- Name: fn_get_deleted_messages(text, text, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_get_deleted_messages(p_instance text, p_jid text DEFAULT NULL::text, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$ SELECT jsonb_build_object('ok', true, 'total', count(*), 'messages', COALESCE(jsonb_agg(jsonb_build_object('message_id', message_id, 'remote_jid', remote_jid, 'content', content, 'from_me', from_me, 'deleted_at', deleted_at, 'created_at', created_at) ORDER BY deleted_at DESC), '[]'::jsonb)) FROM (SELECT message_id, remote_jid, content, from_me, deleted_at, created_at FROM evolution_messages WHERE instance_name = p_instance AND deleted_at IS NOT NULL AND (p_jid IS NULL OR remote_jid = p_jid) ORDER BY deleted_at DESC LIMIT p_limit) sub; $$;


--
-- Name: fn_get_evolution_health_summary(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_get_evolution_health_summary() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
DECLARE v jsonb;
BEGIN
  SELECT jsonb_build_object(
    'instances', (SELECT count(*) FROM zapp.instance_registry WHERE is_active),
    'events_1h', (SELECT count(*) FROM evo.evolution_webhook_events WHERE created_at >= now() - interval '1 hour'),
    'pipeline_ok', (SELECT count(*) > 0 FROM evo.evolution_webhook_events WHERE processed = true AND created_at >= now() - interval '24 hours'),
    'reconcile_ok_15min', (SELECT count(*) > 0 FROM cron.job_run_details d JOIN cron.job j ON j.jobid=d.jobid WHERE j.jobname='whatsapp_reconcile_dispatch' AND d.status='succeeded' AND d.start_time > now() - interval '15 min'),
    'msgs_sem_conversa', (SELECT count(*) FROM evo.evolution_messages WHERE conversation_id IS NULL),
    'backcompat_views', (SELECT count(*) FILTER (WHERE relkind='v') FROM pg_class c JOIN pg_namespace ns ON ns.oid=c.relnamespace WHERE ns.nspname='public' AND c.relname LIKE 'evolution_%'),
    'last_event', (SELECT max(created_at) FROM evo.evolution_webhook_events),
    'db_size', pg_size_pretty(pg_database_size(current_database()))
  ) INTO v;
  RETURN v;
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('error', SQLERRM);
END;
$$;


--
-- Name: fn_get_live_metrics(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_get_live_metrics() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v jsonb;
BEGIN SELECT jsonb_build_object('msgs_last_hour',(SELECT count(*) FROM evolution_messages WHERE created_at>=now()-interval '1 hour'),'events_last_hour',(SELECT count(*) FROM evolution_webhook_events WHERE created_at>=now()-interval '1 hour'),'active_instances',(SELECT count(*) FROM instance_registry WHERE is_active),'open_convs',(SELECT count(*) FROM evolution_conversations WHERE status IN ('aberta','open','active'))) INTO v; RETURN v; END; $$;


--
-- Name: fn_get_message_reactions(text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_get_message_reactions(p_msg_id text, p_inst text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$SELECT jsonb_build_object('ok', true, 'message_id', p_msg_id, 'total', (SELECT count(*) FROM evolution_reactions WHERE message_id = p_msg_id AND (p_inst IS NULL OR instance_name = p_inst)), 'reactions', COALESCE((SELECT jsonb_agg(jsonb_build_object('emoji', emoji, 'remote_jid', remote_jid, 'push_name', push_name, 'from_me', from_me, 'reacted_at', reacted_at)) FROM evolution_reactions WHERE message_id = p_msg_id AND (p_inst IS NULL OR instance_name = p_inst)), '[]'::jsonb));$$;


--
-- Name: fn_get_or_create_conversation(uuid, text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_get_or_create_conversation(p_contact_id uuid, p_jid text, p_instance text DEFAULT 'wpp2'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_id uuid;
BEGIN
  SELECT id INTO v_id FROM evolution_conversations WHERE remote_jid=p_jid AND instance_name=p_instance LIMIT 1;
  IF v_id IS NULL THEN
    INSERT INTO evolution_conversations (remote_jid,contact_id,status,instance_name,first_message_at) VALUES (p_jid,p_contact_id,'aberta',p_instance,now())
    ON CONFLICT (remote_jid,instance_name) DO UPDATE SET contact_id=COALESCE(evolution_conversations.contact_id,EXCLUDED.contact_id), updated_at=now()
    RETURNING id INTO v_id;
  END IF;
  RETURN v_id;
END; $$;


