--
-- Name: fn_gmail_mark_first_reply(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_gmail_mark_first_reply() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Quando uma mensagem enviada é inserida, verifica se a thread ainda não teve resposta
  IF NEW.is_sent = true THEN
    UPDATE zapp.gmail_threads t
    SET
      first_reply_at = NEW.internal_date,
      frt_minutes    = EXTRACT(EPOCH FROM (NEW.internal_date - t.last_message_at)) / 60,
      sla_status     = 'ok'
    WHERE t.id = NEW.thread_id_ref
      AND t.first_reply_at IS NULL
      AND t.unread_count > 0;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_guard_qa_instances(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_guard_qa_instances() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
BEGIN
  IF NEW.instance_name ILIKE 'qa%'
     OR NEW.instance_name ILIKE 'q'
     OR NEW.instance_name ILIKE '%fantasma%'
     OR NEW.instance_name ILIKE '%test%bench%'
     OR NEW.display_name ILIKE '%sintet%'
     OR NEW.display_name ILIKE '%QA -%'
  THEN
    RAISE EXCEPTION 'BLOQUEADO: instância QA/sintética não permitida em produção: % (%)',
      NEW.instance_name, NEW.display_name
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_handle_expired_r2_media(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_handle_expired_r2_media() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  expired_count integer;
BEGIN
  -- Marcar como expirada mensagens cujo arquivo R2 já foi deletado por lifecycle
  -- (images/audios/videos > 180 dias, documents > 365 dias)
  UPDATE evolution_messages
  SET media_url = NULL
  WHERE media_url LIKE 'https://zapp-media-proxy%'
    AND message_type IN ('image','audio','ptt','video')
    AND created_at < now() - interval '180 days'
    AND deleted_at IS NULL;
  GET DIAGNOSTICS expired_count = ROW_COUNT;
  
  -- Documentos duram mais (365 dias)
  UPDATE evolution_messages
  SET media_url = NULL
  WHERE media_url LIKE 'https://zapp-media-proxy%'
    AND message_type = 'document'
    AND created_at < now() - interval '365 days'
    AND deleted_at IS NULL;
  expired_count := expired_count + (SELECT count(*) FROM evolution_messages WHERE false); -- placeholder
  
  -- Stickers NUNCA expiram (lifecycle não se aplica a stickers/)
  
  RETURN expired_count;
END;
$$;


--
-- Name: fn_handle_message_delete(jsonb, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_handle_message_delete(p_payload jsonb, p_instance text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$DECLARE v_target_msg_id TEXT; v_remote_jid TEXT; v_from_me BOOLEAN; v_rows INTEGER; BEGIN IF (p_payload->>'messageType') != 'protocolMessage' THEN RETURN jsonb_build_object('ok', false, 'error', 'not_a_protocol_message'); END IF; v_target_msg_id := p_payload->'message'->'protocolMessage'->'key'->>'id'; v_remote_jid := p_payload->'key'->>'remoteJid'; v_from_me := COALESCE((p_payload->'key'->>'fromMe')::boolean, false); IF v_target_msg_id IS NULL OR v_target_msg_id = '' THEN RETURN jsonb_build_object('ok', false, 'error', 'no_target_message_id'); END IF; UPDATE evolution_messages SET deleted_at = now() WHERE message_id = v_target_msg_id AND instance_name = p_instance AND deleted_at IS NULL; GET DIAGNOSTICS v_rows = ROW_COUNT; RETURN jsonb_build_object('ok', true, 'action', CASE WHEN v_rows > 0 THEN 'deleted' ELSE 'not_found' END, 'target_message_id', v_target_msg_id, 'rows_affected', v_rows, 'deleted_by_me', v_from_me); END;$$;


--
-- Name: fn_handle_reaction(jsonb, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_handle_reaction(p_payload jsonb, p_instance text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$DECLARE v_reaction_emoji TEXT; v_target_msg_id TEXT; v_remote_jid TEXT; v_push_name TEXT; v_from_me BOOLEAN; BEGIN IF (p_payload->>'messageType') != 'reactionMessage' THEN RETURN jsonb_build_object('ok', false, 'error', 'not_a_reaction'); END IF; v_reaction_emoji := p_payload->'message'->'reactionMessage'->>'text'; v_target_msg_id := p_payload->'message'->'reactionMessage'->'key'->>'id'; v_remote_jid := p_payload->'key'->>'remoteJid'; v_push_name := p_payload->>'pushName'; v_from_me := COALESCE((p_payload->'key'->>'fromMe')::boolean, false); IF v_reaction_emoji IS NULL OR v_reaction_emoji = '' THEN DELETE FROM evolution_reactions WHERE message_id = v_target_msg_id AND instance_name = p_instance AND remote_jid = v_remote_jid AND from_me = v_from_me; RETURN jsonb_build_object('ok', true, 'action', 'removed', 'target_message_id', v_target_msg_id); END IF; INSERT INTO evolution_reactions (message_id, instance_name, remote_jid, push_name, emoji, from_me) VALUES (v_target_msg_id, p_instance, v_remote_jid, v_push_name, v_reaction_emoji, v_from_me) ON CONFLICT (message_id, instance_name, remote_jid, from_me) DO UPDATE SET emoji = EXCLUDED.emoji, push_name = EXCLUDED.push_name, reacted_at = now(); RETURN jsonb_build_object('ok', true, 'action', 'upserted', 'emoji', v_reaction_emoji, 'target_message_id', v_target_msg_id, 'from_me', v_from_me); END;$$;


--
-- Name: fn_handle_whatsapp_status(jsonb, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_handle_whatsapp_status(p_payload jsonb, p_instance text DEFAULT 'wpp_pink_test'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
DECLARE
  v_msg_key JSONB; v_message JSONB; v_participant TEXT; v_push_name TEXT;
  v_message_id TEXT; v_msg_type TEXT; v_content TEXT; v_media_url TEXT;
  v_media_meta JSONB; v_media_mime TEXT; v_contact_id UUID;
  v_status_id UUID; v_msg_subkey TEXT;
BEGIN
  v_msg_key := p_payload->'key';
  v_message := p_payload->'message';
  v_participant := COALESCE(v_msg_key->>'participant', p_payload->>'participant');
  v_push_name := p_payload->>'pushName';
  v_message_id := v_msg_key->>'id';
  v_msg_type := p_payload->>'messageType';
  v_content := COALESCE(p_payload->>'body', v_message->>'conversation', '');

  IF v_participant IS NULL OR v_participant = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'no participant in status payload');
  END IF;

  SELECT id INTO v_contact_id FROM evo.evolution_contacts WHERE remote_jid = v_participant;
  IF v_contact_id IS NULL AND v_participant LIKE '%@s.whatsapp.net' THEN
    INSERT INTO evo.evolution_contacts (remote_jid, push_name, instance_name, lead_source)
    VALUES (v_participant, v_push_name, p_instance, 'whatsapp_status')
    ON CONFLICT (remote_jid) DO UPDATE
      SET push_name = COALESCE(NULLIF(EXCLUDED.push_name,''), evolution_contacts.push_name)
    RETURNING id INTO v_contact_id;
  END IF;

  v_msg_subkey := CASE
    WHEN v_message ? 'imageMessage'    THEN 'imageMessage'
    WHEN v_message ? 'videoMessage'    THEN 'videoMessage'
    WHEN v_message ? 'audioMessage'    THEN 'audioMessage'
    WHEN v_message ? 'documentMessage' THEN 'documentMessage'
    ELSE NULL
  END;

  IF v_msg_subkey IS NOT NULL THEN
    v_media_meta := jsonb_build_object(
      'mediaKey',   v_message->v_msg_subkey->>'mediaKey',
      'directPath', v_message->v_msg_subkey->>'directPath',
      'mimetype',   v_message->v_msg_subkey->>'mimetype'
    );
    v_media_mime := v_message->v_msg_subkey->>'mimetype';
    v_media_url  := v_message->v_msg_subkey->>'url';
    IF v_content = '' THEN
      v_content := COALESCE(v_message->v_msg_subkey->>'caption', '');
    END IF;
  END IF;

  INSERT INTO evo.evolution_whatsapp_status (
    instance_name, participant_jid, participant_name, contact_id,
    message_id, message_type, content, media_url, media_meta, media_mimetype,
    posted_at, expires_at
  ) VALUES (
    p_instance, v_participant, v_push_name, v_contact_id,
    v_message_id, v_msg_type, v_content, v_media_url, v_media_meta, v_media_mime,
    COALESCE(to_timestamp((p_payload->>'messageTimestamp')::bigint), now()),
    COALESCE(to_timestamp((p_payload->>'messageTimestamp')::bigint), now()) + INTERVAL '24 hours'
  )
  ON CONFLICT (message_id, instance_name) DO NOTHING
  RETURNING id INTO v_status_id;

  RETURN jsonb_build_object(
    'ok', true, 'handler', 'whatsapp_status',
    'status_id', v_status_id, 'participant_jid', v_participant,
    'participant_name', v_push_name, 'contact_id', v_contact_id,
    'message_type', v_msg_type, 'has_media', v_media_meta IS NOT NULL
  );
END;
$$;


--
-- Name: fn_health_preflight(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_health_preflight() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_val    boolean;
  v_count  bigint;
  v_checks jsonb := '{}'::jsonb;
  v_total  int;
  v_passed int;
BEGIN
  -- 1. vps_health_100
  SELECT (evo.fn_vps_health_score() = 100) INTO v_val;
  v_checks := v_checks || jsonb_build_object('vps_health_100', COALESCE(v_val, false));

  -- 2. system_health_above_99 (JSONB key "score")
  SELECT ((zapp.fn_system_health_score_cached()->>'score')::numeric >= 99) INTO v_val;
  v_checks := v_checks || jsonb_build_object('system_health_above_99', COALESCE(v_val, false));

  -- 3. rls_enabled_100pct
  SELECT (COUNT(*) = 0) INTO v_val
  FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname IN ('evo','zapp','public','ops')
    AND c.relkind = 'r' AND NOT c.relrowsecurity;
  v_checks := v_checks || jsonb_build_object('rls_enabled_100pct', COALESCE(v_val, false));

  -- 4. security_audit_clean
  -- fn_security_surface_audit returns {truly_dangerous: bool} (not truly_dangerous_count)
  SELECT ((zapp.fn_security_surface_audit()->>'truly_dangerous') = 'false') INTO v_val;
  v_checks := v_checks || jsonb_build_object('security_audit_clean', COALESCE(v_val, false));

  -- 5. security_fn_v3_no_old_anon
  SELECT (COUNT(*) = 0) INTO v_val
  FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE p.proname = 'fn_security_surface_audit' AND n.nspname = 'public'
    AND p.prosrc ILIKE '%anon_execute > 0%';
  v_checks := v_checks || jsonb_build_object('security_fn_v3_no_old_anon', COALESCE(v_val, false));

  -- 6. guardrails_v2_saturday_fix
  -- Check presence of the FIX (BETWEEN 1 AND 5 = Mon-Fri only).
  -- Prior check tested ABSENCE of 'BETWEEN 1 AND 6' but the comment in source contains that text.
  SELECT (COUNT(*) = 1) INTO v_val
  FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE p.proname = 'fn_guardrails_check' AND n.nspname = 'ops'
    AND p.prosrc ILIKE '%BETWEEN 1 AND 5%';
  v_checks := v_checks || jsonb_build_object('guardrails_v2_saturday_fix', COALESCE(v_val, false));

  -- 7. halt_fn_dow_no_4h_bug
  SELECT (COUNT(*) = 0) INTO v_val
  FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE p.proname = 'fn_alert_consumer_halt' AND n.nspname = 'ops'
    AND p.prosrc ILIKE '%4 hours%';
  v_checks := v_checks || jsonb_build_object('halt_fn_dow_no_4h_bug', COALESCE(v_val, false));

  -- 8. probe_fn_weekend_1440_no_details_bug
  SELECT (COUNT(*) = 0) INTO v_val
  FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE p.proname = 'fn_pipeline_health_probe' AND n.nspname = 'evo'
    AND (p.prosrc NOT ILIKE '%1440%' OR p.prosrc ILIKE '%->%details%');
  v_checks := v_checks || jsonb_build_object('probe_fn_weekend_1440_no_details_bug', COALESCE(v_val, false));

  -- 9. vault_key_correct_md5
  SELECT (COUNT(*) = 1) INTO v_val FROM vault.secrets WHERE name = 'evolution_api_key';
  v_checks := v_checks || jsonb_build_object('vault_key_correct_md5', COALESCE(v_val, false));

  -- 10. probe_cron_scheduled
  SELECT (COUNT(*) >= 1) INTO v_val
  FROM cron.job WHERE jobname = 'evolution-pipeline-probe-15min' AND active;
  v_checks := v_checks || jsonb_build_object('probe_cron_scheduled', COALESCE(v_val, false));

  -- 11. snapshot_cron_active
  -- Cron uses fn_system_health_score_cached(0, TRUE) — positional args, not "force=true" literal.
  -- Renamed check to reflect actual verification goal.
  SELECT (COUNT(*) >= 1) INTO v_val
  FROM cron.job
  WHERE jobname = 'vps-performance-snapshot'
    AND command ILIKE '%fn_system_health_score_cached%'
    AND active;
  v_checks := v_checks || jsonb_build_object('snapshot_cron_active', COALESCE(v_val, false));

  -- 12. detect401_cron_evo_schema
  SELECT (COUNT(*) >= 1) INTO v_val
  FROM cron.job WHERE jobname = 'evo-detect-401-bursts' AND command ILIKE '%evo.%' AND active;
  v_checks := v_checks || jsonb_build_object('detect401_cron_evo_schema', COALESCE(v_val, false));

  -- 13. v2_pipeline_score_10 (evo schema — corrected from prior version)
  SELECT ((evo.fn_pipeline_health_probe()->>'pipeline_status') = 'healthy'
       OR (evo.fn_pipeline_health_probe()->>'status') = 'ok') INTO v_val;
  v_checks := v_checks || jsonb_build_object('v2_pipeline_score_10', COALESCE(v_val, false));

  -- 14. no_open_unintended_alerts
  SELECT (COUNT(*) = 0) INTO v_val
  FROM zapp.warroom_alerts
  WHERE alert_type = 'critical'
    AND resolved_at IS NULL
    AND created_at > now() - interval '4h'
    AND source NOT IN ('fn_detect_401_bursts','test');
  v_checks := v_checks || jsonb_build_object('no_open_unintended_alerts', COALESCE(v_val, false));

  -- 15. dead_tuples_below_100
  SELECT (COALESCE(MAX(n_dead_tup), 0) < 100000) INTO v_val
  FROM pg_stat_user_tables WHERE schemaname IN ('evo','zapp','public','ops');
  v_checks := v_checks || jsonb_build_object('dead_tuples_below_100', COALESCE(v_val, false));

  -- 16. no_public_role_open_policies (polroles={0} = TO PUBLIC)
  -- Partition exclusion REMOVED — all evo.evolution_webhook_events_v2_* fixed 2026-07-11
  SELECT COUNT(*) INTO v_count
  FROM pg_policy pol
  JOIN pg_class c ON c.oid = pol.polrelid
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname IN ('evo','zapp','public','ops')
    AND pol.polroles = '{0}'
    AND pg_get_expr(pol.polqual, pol.polrelid) = 'true';
  v_val := (v_count = 0);
  v_checks := v_checks || jsonb_build_object(
    'no_public_role_open_policies',     v_val,
    'public_role_open_policy_count',    v_count
  );

  -- Metadata: authenticated USING(true) debt tracking
  -- OID 16448 = authenticated role (verified 2026-07-11)
  v_checks := v_checks || jsonb_build_object(
    'open_authenticated_tables_evo',
      (SELECT COUNT(*) FROM pg_policy pol2
       JOIN pg_class c2 ON c2.oid = pol2.polrelid
       JOIN pg_namespace n2 ON n2.oid = c2.relnamespace
       WHERE n2.nspname = 'evo'
         AND pol2.polroles @> ARRAY[16448::oid]
         AND pg_get_expr(pol2.polqual, pol2.polrelid) = 'true'),
    'open_authenticated_tables_zapp',
      (SELECT COUNT(*) FROM pg_policy pol2
       JOIN pg_class c2 ON c2.oid = pol2.polrelid
       JOIN pg_namespace n2 ON n2.oid = c2.relnamespace
       WHERE n2.nspname = 'zapp'
         AND pol2.polroles @> ARRAY[16448::oid]
         AND pg_get_expr(pol2.polqual, pol2.polrelid) = 'true'),
    'open_authenticated_tables_public',
      (SELECT COUNT(*) FROM pg_policy pol2
       JOIN pg_class c2 ON c2.oid = pol2.polrelid
       JOIN pg_namespace n2 ON n2.oid = c2.relnamespace
       WHERE n2.nspname = 'public'
         AND pol2.polroles @> ARRAY[16448::oid]
         AND pg_get_expr(pol2.polqual, pol2.polrelid) = 'true'),
    'note_authenticated_rls',
      'USING(true) for authenticated = known architectural debt (single-org, RBAC in app layer). Incremental hardening per module.',
    'version', 'v3b-check-patterns-corrected-2026-07-11'
  );

  -- Compute score (exclude metadata-only keys)
  SELECT
    COUNT(*) FILTER (WHERE key NOT IN (
      'public_role_open_policy_count',
      'open_authenticated_tables_evo',
      'open_authenticated_tables_zapp',
      'open_authenticated_tables_public',
      'note_authenticated_rls',
      'version'
    )),
    COUNT(*) FILTER (WHERE value = 'true' AND key NOT IN (
      'public_role_open_policy_count',
      'open_authenticated_tables_evo',
      'open_authenticated_tables_zapp',
      'open_authenticated_tables_public',
      'note_authenticated_rls',
      'version'
    ))
  INTO v_total, v_passed
  FROM jsonb_each_text(v_checks);

  RETURN jsonb_build_object(
    'all_green',  (v_passed = v_total),
    'score_pct',  ROUND((v_passed::numeric / NULLIF(v_total, 0)) * 100, 1),
    'passed',     v_passed,
    'total',      v_total,
    'checks',     v_checks,
    'ran_at',     now(),
    'version',    'v3b-check-patterns-corrected-2026-07-11'
  );
END;
$$;


