--
-- Name: fn_is_business_hours(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_is_business_hours() RETURNS TABLE(is_open boolean, current_status character varying, message text, next_open_at timestamp with time zone)
    LANGUAGE plpgsql
    AS $$
DECLARE v_now TIMESTAMPTZ := NOW() AT TIME ZONE 'America/Sao_Paulo'; v_day INTEGER := EXTRACT(DOW FROM v_now); v_time TIME := v_now::TIME;
BEGIN
  IF v_day IN (0,6) THEN RETURN QUERY SELECT false,'closed_day'::varchar,'Atendimento de segunda a sexta.'::text,NULL::timestamptz; RETURN; END IF;
  IF v_time >= '08:00'::time AND v_time <= '18:00'::time THEN
    RETURN QUERY SELECT true,'open'::varchar,('Aberto ate 18:00')::text,NULL::timestamptz;
  ELSIF v_time < '08:00'::time THEN
    RETURN QUERY SELECT false,'before_hours'::varchar,'Abrimos as 08:00'::text,NULL::timestamptz;
  ELSE
    RETURN QUERY SELECT false,'after_hours'::varchar,'Horario encerrado. Retornamos amanha!'::text,NULL::timestamptz;
  END IF;
END; $$;


--
-- Name: fn_lgpd_anonymize_deleted_contacts(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_lgpd_anonymize_deleted_contacts(p_days_threshold integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'pg_temp'
    AS $$
DECLARE v_count bigint := 0;
BEGIN
  UPDATE evo.evolution_contacts
  SET full_name = '[anonimizado]',
      push_name = NULL,
      phone_number = NULL,
      email = NULL,
      company = NULL,
      notes = NULL,
      pii_masked_at = now()
  WHERE deleted_at IS NOT NULL
    AND deleted_at < now() - make_interval(days => p_days_threshold)
    AND pii_masked_at IS NULL;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN jsonb_build_object('anonymized_contacts', v_count, 'days_threshold', p_days_threshold);
END;
$$;


--
-- Name: fn_lgpd_purge_contact_activity(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_lgpd_purge_contact_activity(p_days_threshold integer DEFAULT 90) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_temp'
    AS $_$
DECLARE v_count bigint := 0;
BEGIN
  -- Purge conservador: so tabelas conhecidas de atividade de contato, com coluna created_at
  IF to_regclass('zapp.contact_audit_log') IS NOT NULL THEN
    EXECUTE 'DELETE FROM zapp.contact_audit_log WHERE created_at < now() - make_interval(days => $1)'
      USING p_days_threshold;
    GET DIAGNOSTICS v_count = ROW_COUNT;
  END IF;
  RETURN jsonb_build_object('purged_contact_activity', v_count, 'days_threshold', p_days_threshold);
END;
$_$;


--
-- Name: fn_lgpd_purge_message_metadata(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_lgpd_purge_message_metadata(p_days_threshold integer DEFAULT 365) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'pg_temp'
    AS $$
DECLARE v_count bigint := 0;
BEGIN
  UPDATE evo.evolution_messages
  SET payload = NULL,
      raw_data = NULL,
      transcription = NULL,
      media_meta = NULL
  WHERE created_at < now() - make_interval(days => p_days_threshold)
    AND (payload IS NOT NULL OR raw_data IS NOT NULL OR transcription IS NOT NULL OR media_meta IS NOT NULL);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN jsonb_build_object('purged_message_metadata', v_count, 'days_threshold', p_days_threshold);
END;
$$;


