--
-- Name: fn_list_audio_memes(text, boolean, text, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_list_audio_memes(p_category text DEFAULT NULL::text, p_favorites_only boolean DEFAULT false, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'ok', true,
    'total', count(*),
    'categories', jsonb_agg(DISTINCT category),
    'memes', jsonb_agg(
      jsonb_build_object(
        'id', id,
        'name', name,
        'audio_url', audio_url,
        'category', category,
        'duration_seconds', duration_seconds,
        'is_favorite', is_favorite,
        'use_count', use_count
      ) ORDER BY use_count DESC, name
    )
  ) INTO v_result
  FROM (
    SELECT * FROM audio_memes
    WHERE (p_category IS NULL OR category = p_category)
      AND (NOT p_favorites_only OR is_favorite = true)
      AND (p_search IS NULL OR name ILIKE '%' || p_search || '%')
    ORDER BY use_count DESC, name
    LIMIT p_limit
  ) sub;
  
  RETURN COALESCE(v_result, '{"ok":true,"total":0,"categories":[],"memes":[]}');
END;
$$;


--
-- Name: FUNCTION fn_list_audio_memes(p_category text, p_favorites_only boolean, p_search text, p_limit integer); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_list_audio_memes(p_category text, p_favorites_only boolean, p_search text, p_limit integer) IS 'Lista memes do catalogo filtrados por categoria, favoritos e busca textual';


--
-- Name: fn_list_audio_memes_for_user(text, boolean, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_list_audio_memes_for_user(p_category text DEFAULT NULL::text, p_only_favorites boolean DEFAULT false, p_search text DEFAULT NULL::text) RETURNS TABLE(id uuid, name text, audio_url text, category text, duration_seconds numeric, use_count integer, is_favorite boolean, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
  SELECT m.id, m.name, m.audio_url, m.category, m.duration_seconds, m.use_count,
         EXISTS (
           SELECT 1 FROM zapp.audio_meme_favorites f
           WHERE f.meme_id = m.id AND f.user_id = auth.uid()
         ) AS is_favorite,
         m.created_at
  FROM zapp.audio_memes m
  WHERE (p_category IS NULL OR m.category = p_category)
    AND (p_search IS NULL OR m.name ILIKE '%'||p_search||'%')
    AND (
      NOT p_only_favorites
      OR EXISTS (
        SELECT 1 FROM zapp.audio_meme_favorites f
        WHERE f.meme_id = m.id AND f.user_id = auth.uid()
      )
    )
  ORDER BY is_favorite DESC, m.use_count DESC, m.name ASC;
$$;


--
-- Name: fn_list_audio_memes_for_user(uuid, text, boolean, text, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_list_audio_memes_for_user(p_user_id uuid, p_category text DEFAULT NULL::text, p_favorites_only boolean DEFAULT false, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'ok', true,
    'user_id', p_user_id,
    'total', count(*),
    'memes', COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', sub.id,
        'name', sub.name,
        'audio_url', sub.audio_url,
        'category', sub.category,
        'duration_seconds', sub.duration_seconds,
        'is_favorite', sub.is_user_fav,
        'use_count', sub.use_count
      ) ORDER BY sub.is_user_fav DESC, sub.use_count DESC, sub.name
    ), '[]'::jsonb)
  ) INTO v_result
  FROM (
    SELECT 
      am.*,
      (amf.id IS NOT NULL) AS is_user_fav
    FROM audio_memes am
    LEFT JOIN audio_meme_favorites amf ON amf.meme_id = am.id AND amf.user_id = p_user_id
    WHERE (p_category IS NULL OR am.category = p_category)
      AND (NOT p_favorites_only OR amf.id IS NOT NULL)
      AND (p_search IS NULL OR am.name ILIKE '%' || p_search || '%')
    ORDER BY (amf.id IS NOT NULL) DESC, am.use_count DESC, am.name
    LIMIT p_limit
  ) sub;
  
  RETURN COALESCE(v_result, jsonb_build_object('ok', true, 'user_id', p_user_id, 'total', 0, 'memes', '[]'::jsonb));
END;
$$;


--
-- Name: FUNCTION fn_list_audio_memes_for_user(p_user_id uuid, p_category text, p_favorites_only boolean, p_search text, p_limit integer); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_list_audio_memes_for_user(p_user_id uuid, p_category text, p_favorites_only boolean, p_search text, p_limit integer) IS 'Lista memes com is_favorite personalizado POR USUARIO. Favoritos aparecem primeiro.';


--
-- Name: fn_list_message_reactions(text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_list_message_reactions(p_message_id text, p_instance text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
DECLARE
  v_reactions JSONB;
  v_count INT;
BEGIN
  SELECT jsonb_agg(jsonb_build_object('emoji', r.emoji, 'remote_jid', r.remote_jid, 'push_name', r.push_name, 'from_me', r.from_me, 'reacted_at', r.reacted_at) ORDER BY r.reacted_at), COUNT(*)
  INTO v_reactions, v_count
  FROM evolution_reactions r
  WHERE r.message_id = p_message_id AND (p_instance IS NULL OR r.instance_name = p_instance);
  RETURN jsonb_build_object('ok', true, 'message_id', p_message_id, 'total', COALESCE(v_count, 0), 'reactions', COALESCE(v_reactions, '[]'::jsonb));
END;
$$;


--
-- Name: fn_list_shared_links(text, boolean, text, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_list_shared_links(p_instance text DEFAULT NULL::text, p_from_me boolean DEFAULT NULL::boolean, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
BEGIN
  RETURN (
    SELECT jsonb_build_object(
      'ok', true,
      'total', count(*),
      'links', COALESCE(jsonb_agg(
        jsonb_build_object(
          'message_id', message_id,
          'content', left(content, 200),
          'url', link_preview->>'url',
          'title', link_preview->>'title',
          'description', link_preview->>'description',
          'preview_type', link_preview->>'previewType',
          'has_thumbnail', (link_preview->>'hasThumbnail')::boolean,
          'instance', instance_name,
          'from_me', from_me,
          'created_at', created_at
        ) ORDER BY created_at DESC
      ), '[]'::jsonb)
    )
    FROM (
      SELECT * FROM evolution_messages
      WHERE link_preview IS NOT NULL
        AND (p_instance IS NULL OR instance_name = p_instance)
        AND (p_from_me IS NULL OR from_me = p_from_me)
        AND (p_search IS NULL OR content ILIKE '%' || p_search || '%' OR link_preview->>'title' ILIKE '%' || p_search || '%')
      ORDER BY created_at DESC
      LIMIT p_limit
    ) sub
  );
END;
$$;


