-- Name: FUNCTION fn_list_shared_links(p_instance text, p_from_me boolean, p_search text, p_limit integer); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_list_shared_links(p_instance text, p_from_me boolean, p_search text, p_limit integer) IS 'Lista links compartilhados com metadados de preview. Filtros: instancia, direcao, busca textual.';


--
-- Name: fn_list_sticker_categories(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_list_sticker_categories() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
BEGIN
  RETURN (
    SELECT jsonb_build_object(
      'ok', true,
      'total_categories', count(*),
      'total_stickers', COALESCE(sum(real_count), 0),
      'categories', jsonb_agg(
        jsonb_build_object(
          'id', sc.id,
          'slug', sc.slug,
          'label', sc.label_pt,
          'emoji', sc.emoji,
          'sticker_count', COALESCE(real_count, 0),
          'total_uses', COALESCE(real_uses, 0),
          'is_active', sc.is_active,
          'sort_order', sc.sort_order
        ) ORDER BY sc.sort_order
      )
    )
    FROM sticker_categories sc
    LEFT JOIN (
      SELECT category, count(*) AS real_count, COALESCE(sum(use_count), 0) AS real_uses
      FROM stickers WHERE is_active = true
      GROUP BY category
    ) s ON s.category = sc.slug
    WHERE sc.is_active = true
  );
END;
$$;


