    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
  SELECT id, response_text, keyword
  FROM evolution_keyword_automations
  WHERE is_active = true
    AND LOWER(p_content) LIKE '%' || LOWER(keyword) || '%'
