--
-- Name: fn_media_pipeline_health_report(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_media_pipeline_health_report() RETURNS TABLE(metric text, value bigint, status text, alert boolean, description text)
    LANGUAGE sql STABLE
    AS $$
  SELECT 'kong_urls_messages'::text, COUNT(*)::bigint,
    CASE WHEN COUNT(*) = 0 THEN 'ok' ELSE 'CRITICAL' END, COUNT(*) > 0,
    'URLs kong:8000 em evolution_messages_wpp2 (ADR-001)'::text
  FROM evo.evolution_messages_wpp2 WHERE media_url LIKE '%kong%'
  UNION ALL SELECT 'kong_urls_media', COUNT(*),
    CASE WHEN COUNT(*) = 0 THEN 'ok' ELSE 'CRITICAL' END, COUNT(*) > 0,
    'URLs kong:8000 em evolution_media'
  FROM evo.evolution_media WHERE storage_url LIKE '%kong%'
  UNION ALL SELECT 'kong_urls_contacts', COUNT(*),
    CASE WHEN COUNT(*) = 0 THEN 'ok' ELSE 'CRITICAL' END, COUNT(*) > 0,
    'URLs kong:8000 em evolution_contacts'
  FROM evo.evolution_contacts WHERE profile_picture_url LIKE '%kong%'
  UNION ALL SELECT 'media_queue_stuck_pending', COUNT(*),
    CASE WHEN COUNT(*) = 0 THEN 'ok' WHEN COUNT(*) < 50 THEN 'warning' ELSE 'CRITICAL' END,
    COUNT(*) > 50, 'Jobs pending há mais de 2h'
  FROM zapp.media_download_queue WHERE status='pending' AND created_at < now()-interval '2h'
  UNION ALL SELECT 'media_queue_total_pending', COUNT(*),
    CASE WHEN COUNT(*) = 0 THEN 'ok' WHEN COUNT(*) < 500 THEN 'warning' ELSE 'CRITICAL' END,
    COUNT(*) > 500, 'Total jobs pending'
  FROM zapp.media_download_queue WHERE status='pending'
  UNION ALL SELECT 'media_queue_done_24h', COUNT(*),
    CASE WHEN COUNT(*) = 0 THEN 'warning' ELSE 'ok' END,
    false, 'Jobs done nas últimas 24h'
  FROM zapp.media_download_queue WHERE status='done' AND processed_at > now()-interval '24h'
  UNION ALL SELECT 'messages_media_unknown_status', COUNT(*),
    CASE WHEN COUNT(*) = 0 THEN 'ok' WHEN COUNT(*) < 50 THEN 'warning' ELSE 'CRITICAL' END,
    COUNT(*) > 1000, 'Mensagens media_url com status=unknown'
  FROM evo.evolution_messages_wpp2 WHERE media_url IS NOT NULL AND (media_status IS NULL OR media_status='unknown')
  UNION ALL SELECT 'messages_media_ready', COUNT(*), 'info', false, 'Mídias ready'
  FROM evo.evolution_messages_wpp2 WHERE media_status='ready'
  UNION ALL SELECT 'messages_media_expired', COUNT(*), 'info', false, 'Mídias expiradas'
  FROM evo.evolution_messages_wpp2 WHERE media_status='expired'
  UNION ALL SELECT 'bucket_whatsapp_media_public',
    CASE WHEN public THEN 1 ELSE 0 END,
    CASE WHEN public THEN 'ok' ELSE 'CRITICAL' END, NOT public,
    'Bucket whatsapp-media deve ser público (ADR-002)'
  FROM storage.buckets WHERE name='whatsapp-media'
  UNION ALL SELECT 'realtime_contacts_in_publication',
    CASE WHEN EXISTS(SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='evo' AND tablename='evolution_contacts') THEN 1 ELSE 0 END,
    CASE WHEN EXISTS(SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='evo' AND tablename='evolution_contacts') THEN 'ok' ELSE 'CRITICAL' END,
    NOT EXISTS(SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='evo' AND tablename='evolution_contacts'),
    'evolution_contacts na publication realtime'
  UNION ALL SELECT 'contacts_replica_identity_full',
    CASE WHEN c.relreplident='f' THEN 1 ELSE 0 END,
    CASE WHEN c.relreplident='f' THEN 'ok' ELSE 'warning' END,
    c.relreplident != 'f', 'evolution_contacts REPLICA IDENTITY=FULL'
  FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE n.nspname='evo' AND c.relname='evolution_contacts'
  UNION ALL SELECT
    'wal_logflare_lag_mb',
    (pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn) / 1048576)::bigint,
    CASE
      WHEN pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn)/1048576 < 100 THEN 'ok'
      WHEN pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn)/1048576 < 500 THEN 'warning'
      ELSE 'CRITICAL'
    END,
    pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn)/1048576 > 500,
    'WAL lag slot Logflare (cainophile) em MB — DROP se não usar Logflare'
  FROM pg_replication_slots WHERE slot_name LIKE 'cainophile%'
  UNION ALL SELECT 'db_dead_tuples_messages', n_dead_tup,
    CASE WHEN n_dead_tup < 5000 THEN 'ok' WHEN n_dead_tup < 20000 THEN 'warning' ELSE 'CRITICAL' END,
    n_dead_tup > 50000, 'Dead tuples em evolution_messages_wpp2'
  FROM pg_stat_user_tables WHERE schemaname='evo' AND relname='evolution_messages_wpp2'
$$;


--
-- Name: fn_media_public_url(text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_media_public_url(raw_url text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  r2_base text := 'https://zapp-media-proxy.adm01.workers.dev';
BEGIN
  IF raw_url IS NULL OR raw_url = '' THEN
    RETURN raw_url;
  END IF;

  -- 1. MinIO interno -> R2 worker (URLs legadas)
  IF raw_url LIKE 'http://minio:9000/%' THEN
    RETURN r2_base || '/' || split_part(substring(raw_url FROM 'http://minio:9000/(.*)'), '?', 1);
  END IF;

  IF raw_url LIKE 'http://minio/%' THEN
    RETURN r2_base || '/' || split_part(substring(raw_url FROM 'http://minio/(.*)'), '?', 1);
  END IF;

  -- 2. MinIO público antigo (s3.atomicabr) -> R2 worker
  IF raw_url LIKE 'https://s3.atomicabr.com.br/evolution/%' THEN
    RETURN r2_base || '/' || substring(raw_url FROM 'https://s3.atomicabr.com.br/evolution/(.*)');
  END IF;

  -- 3. R2 endpoint interno -> R2 worker público
  IF raw_url LIKE '%r2.cloudflarestorage.com/zapp-whatsapp-media/%' THEN
    RETURN r2_base || '/' || substring(raw_url FROM '.*/zapp-whatsapp-media/(.*)');
  END IF;

  -- 4. Já é URL do R2 worker, retornar como está
  IF raw_url LIKE 'https://zapp-media-proxy%' THEN
    RETURN raw_url;
  END IF;

  -- 5. Qualquer outra URL pública (inclui self-hosted e legadas), manter
  RETURN raw_url;
END;
$$;


