CREATE FUNCTION zapp.fn_media_queue_stats() RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE v jsonb;
BEGIN SELECT jsonb_build_object('total',(SELECT count(*) FROM evolution_mirror_media_queue),'pending',(SELECT count(*) FROM evolution_mirror_media_queue WHERE status='pending'),'processing',(SELECT count(*) FROM evolution_mirror_media_queue WHERE status='processing'),'completed',(SELECT count(*) FROM evolution_mirror_media_queue WHERE status='completed'),'failed',(SELECT count(*) FROM evolution_mirror_media_queue WHERE status='failed')) INTO v; RETURN v; END; $$;


--
-- Name: fn_message_rate_5min(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_message_rate_5min() RETURNS TABLE(msgs_5min integer, msgs_per_min numeric, last_msg_at timestamp with time zone, age_seconds integer, pipeline_health text, hour_brt integer, is_business_hours boolean, generated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
DECLARE
  v_count int; v_last timestamptz; v_age int; v_hour int; v_business boolean; v_health text;
BEGIN
  SELECT count(*), max(created_at) INTO v_count, v_last
    FROM evo.evolution_messages
    WHERE created_at > now() - interval '5 minutes';
  v_age := COALESCE(EXTRACT(EPOCH FROM (now() - v_last))::int, 999999);
  v_hour := EXTRACT(HOUR FROM (now() AT TIME ZONE 'America/Sao_Paulo'))::int;
  v_business := v_hour BETWEEN 8 AND 20;
  v_health := CASE
    WHEN v_count >= 5                                    THEN 'healthy'
    WHEN v_count BETWEEN 1 AND 4                         THEN 'low_volume'
    WHEN v_count = 0 AND v_age > 600 AND v_business      THEN 'critical_business_hours'
    WHEN v_count = 0 AND v_age > 600 AND NOT v_business  THEN 'expected_silence_offhours'
    WHEN v_count = 0 AND v_age <= 600                    THEN 'recent_quiet'
    ELSE 'unknown'
  END;
  RETURN QUERY SELECT v_count, ROUND(v_count::numeric/5,2), v_last, v_age, v_health, v_hour, v_business, now();
END;
$$;


--
-- Name: FUNCTION fn_message_rate_5min(); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_message_rate_5min() IS 'KPI de throughput do pipeline de mensagens (Bateria #8 anti-regressão pós-incidente 2026-05-04). Classifica como critical_business_hours quando 0 msgs em 5min durante 08-20 BRT.';


--
-- Name: fn_messages_instead_of_insert(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_messages_instead_of_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$ DECLARE v_instance_name text; v_remote_jid text; v_new_id uuid; v_status text; BEGIN SELECT wc.instance_name INTO v_instance_name FROM zapp.whatsapp_connections wc WHERE wc.id = COALESCE(NEW.whatsapp_connection_id, NEW.connection_id) LIMIT 1; IF v_instance_name IS NULL THEN v_instance_name := NULLIF(COALESCE(NEW.instance_name, ''), ''); END IF; v_instance_name := COALESCE(v_instance_name, 'wpp2'); SELECT COALESCE(NULLIF(ec.remote_jid, ''), NULLIF(ec.phone_number, '') || '@s.whatsapp.net') INTO v_remote_jid FROM evo.evolution_contacts ec WHERE ec.id = NEW.contact_id LIMIT 1; IF v_remote_jid IS NULL OR v_remote_jid = '' THEN v_remote_jid := NULLIF(COALESCE(NEW.remote_jid, ''), ''); END IF; v_remote_jid := COALESCE(v_remote_jid, 'unknown@s.whatsapp.net'); v_status := CASE WHEN NEW.status IN ('sending', 'retrying', 'queued', 'processing', 'scheduled') THEN 'pending' WHEN NEW.status IN ('failed_auth', 'failed_retries', 'error') THEN 'failed' WHEN NEW.status IS NULL OR NEW.status = '' THEN 'delivered' WHEN NEW.status NOT IN ('received','sent','delivered','read','deleted','pending','played','failed') THEN 'pending' ELSE NEW.status END; NEW.status := v_status; INSERT INTO evo.evolution_messages (id, message_id, remote_jid, from_me, message_type, content, media_url, contact_id, conversation_id, direction, status, status_at, instance_name, push_name, created_at, updated_at, payload) VALUES (COALESCE(NEW.id, gen_random_uuid()), COALESCE(NEW.external_id, NEW.whatsapp_message_id), v_remote_jid, COALESCE(NEW.is_from_me, NEW.sender = 'agent', false), COALESCE(NEW.message_type, 'text'), NEW.content, NEW.media_url, NEW.contact_id, NEW.conversation_id, CASE WHEN COALESCE(NEW.sender, 'contact') = 'agent' THEN 'outbound' ELSE 'inbound' END, v_status, COALESCE(NEW.status_updated_at, now()), v_instance_name, NEW.push_name, COALESCE(NEW.created_at, now()), now(), COALESCE(NEW.metadata, '{}'::jsonb)) ON CONFLICT (message_id, instance_name) DO NOTHING RETURNING id INTO v_new_id; IF v_new_id IS NULL THEN SELECT id INTO v_new_id FROM evo.evolution_messages WHERE message_id = COALESCE(NEW.external_id, NEW.whatsapp_message_id) AND instance_name = v_instance_name LIMIT 1; END IF; NEW.id := v_new_id; RETURN NEW; END; $$;


--
-- Name: FUNCTION fn_messages_instead_of_insert(); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_messages_instead_of_insert() IS 'INSTEAD OF INSERT trigger em zapp.messages (ordem=1). Cria a row canônica em evo.evolution_messages.
FIX 2026-07-26 v2:
  A. Status normalization: remapeia valores inválidos (sending→pending, failed_auth→failed).
     CRÍTICO: NEW.status := v_status propagado para trigger 2 (ordem=2).
  B. instance_name fallback: connection_id > NEW.instance_name > wpp2.
  C. remote_jid fallback: contact_lookup > NEW.remote_jid > phone > unknown.';


--
-- Name: fn_messages_view_insert_handler(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_messages_view_insert_handler() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo', 'zapp', 'monitoring', 'pg_catalog'
    AS $$
DECLARE
  v_db_direction text;
  v_remote_jid   text;
  v_push_name    text;
  v_instance     text;
  v_from_me      boolean;
  v_phone        text;
  v_contact_name text;
BEGIN
  -- Assign id FIRST so RETURN NEW carries the generated UUID back to PostgREST.
  -- Without this, callers that omit id in the INSERT get NULL in the RETURNING clause
  -- when ON CONFLICT DO NOTHING fires (FOUND=false, fallback SELECT returns NULL if
  -- message_id is NULL).
  NEW.id := COALESCE(NEW.id, gen_random_uuid());

  v_db_direction := CASE NEW.direction
    WHEN 'incoming' THEN 'inbound'
    WHEN 'outgoing' THEN 'outbound'
    ELSE COALESCE(NEW.direction, 'inbound')
  END;

  v_from_me := COALESCE(
    NEW.is_from_me,
    CASE WHEN v_db_direction = 'outbound' THEN true ELSE false END
  );

  v_instance := NULLIF(NEW.instance_name, '');
  IF v_instance IS NULL THEN
    SELECT wc.instance_name INTO v_instance
    FROM zapp.whatsapp_connections wc
    WHERE wc.id = NEW.whatsapp_connection_id
    LIMIT 1;
  END IF;
  v_instance := COALESCE(v_instance, 'wpp2');

  v_remote_jid := NULLIF(NEW.remote_jid, '');
  v_push_name  := NEW.push_name;
  IF v_remote_jid IS NULL OR v_push_name IS NULL THEN
    SELECT c.remote_jid, c.phone, c.name
    INTO v_remote_jid, v_phone, v_contact_name
    FROM zapp.contacts c
    WHERE c.id = NEW.contact_id
    LIMIT 1;
    IF (v_remote_jid IS NULL OR v_remote_jid = '') AND v_phone IS NOT NULL AND v_phone <> '' THEN
      v_remote_jid := v_phone || '@s.whatsapp.net';
    END IF;
    v_push_name := COALESCE(NEW.push_name, v_contact_name);
  END IF;

  INSERT INTO zapp.evolution_messages (
    id, message_id, remote_jid, from_me,
    message_type, content, media_url, media_mimetype, media_filename, media_size,
    quoted_message_id, payload,
    contact_id, conversation_id, direction, status, status_at,
    caption, instance_name, push_name,
    deleted_at, edited_at, created_at, updated_at
  ) VALUES (
    NEW.id,
    COALESCE(NEW.whatsapp_message_id, NEW.external_id),
    COALESCE(v_remote_jid, ''),
    v_from_me,
    NEW.message_type,
    NEW.content,
    NEW.media_url,
    NEW.media_mime_type,
    NEW.media_filename,
    NEW.media_size,
    NEW.quoted_message->>'id',
    COALESCE(NEW.metadata, '{}'::jsonb),
    NEW.contact_id,
    NEW.conversation_id,
    v_db_direction,
    COALESCE(NEW.status, 'delivered'),
    NEW.status_updated_at,
    NEW.caption,
    v_instance,
    v_push_name,
    CASE WHEN NEW.is_deleted THEN COALESCE(NEW.created_at, now()) ELSE NULL END,
    CASE WHEN NEW.is_edited  THEN COALESCE(NEW.created_at, now()) ELSE NULL END,
    COALESCE(NEW.created_at, now()),
    COALESCE(NEW.updated_at, now())
  )
  ON CONFLICT (message_id, instance_name) DO NOTHING;

  -- When insert was skipped due to conflict, FOUND is false.
  -- Re-fetch the existing row's id so RETURN NEW carries the correct UUID.
  IF NOT FOUND THEN
    SELECT em.id INTO NEW.id
    FROM zapp.evolution_messages em
    WHERE em.message_id = COALESCE(NEW.whatsapp_message_id, NEW.external_id)
      AND em.instance_name = v_instance
    LIMIT 1;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_mirror_kill_zombie_runs(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_mirror_kill_zombie_runs() RETURNS TABLE(killed_count integer, run_ids uuid[], oldest_age_minutes numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_cutoff         timestamptz := NOW() - INTERVAL '30 minutes';
  v_killed_ids     uuid[];
  v_killed_count   int := 0;
  v_oldest_minutes numeric;
  v_should_alert   boolean := false;
BEGIN
  SELECT
    array_agg(id),
    COUNT(*)::int,
    MAX(EXTRACT(EPOCH FROM (NOW() - started_at)) / 60)
  INTO v_killed_ids, v_killed_count, v_oldest_minutes
  FROM evolution_mirror_runs
  WHERE status = 'running'
    AND started_at < v_cutoff;

  IF v_killed_count > 0 THEN
    UPDATE evolution_mirror_runs
    SET
      status = 'failed',
      completed_at = NOW(),
      duration_seconds = EXTRACT(EPOCH FROM (NOW() - started_at))::int,
      error_message = 'watchdog: killed zombie run (>30min running, no progress)',
      metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
        'killed_by', 'fn_mirror_kill_zombie_runs',
        'killed_at', NOW(),
        'was_running_minutes', EXTRACT(EPOCH FROM (NOW() - started_at)) / 60
      )
    WHERE id = ANY(v_killed_ids);
    v_should_alert := true;
  END IF;

  INSERT INTO migration_audit (phase, entity, action, rows_affected, status, notes)
  VALUES (
    'monitoring','evolution_mirror_runs','zombie_cleanup',v_killed_count,
    CASE WHEN v_killed_count > 0 THEN 'killed_zombies' ELSE 'no_zombies' END,
    CASE WHEN v_killed_count > 0
      THEN 'Killed ' || v_killed_count || ' zombie runs, oldest ' || ROUND(v_oldest_minutes, 1) || ' min'
      ELSE 'No zombies detected'
    END
  );

  IF v_should_alert THEN
    BEGIN
      PERFORM fn_alert_dispatch(
        p_alert_key := 'mirror_zombies_killed',
        p_severity  := 'warning',
        p_title     := 'Mirror runs zumbis eliminados',
        p_message   := 'Watchdog matou ' || v_killed_count || ' run(s) travados. Mais antigo: ' || ROUND(v_oldest_minutes, 1) || ' minutos.',
        p_details   := jsonb_build_object(
          'killed_count', v_killed_count,
          'run_ids', v_killed_ids,
          'oldest_minutes', v_oldest_minutes
        )
      );
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'alert dispatch failed: %', SQLERRM;
    END;
  END IF;

  killed_count := v_killed_count;
  run_ids := COALESCE(v_killed_ids, ARRAY[]::uuid[]);
  oldest_age_minutes := v_oldest_minutes;
  RETURN NEXT;
END;
$$;


--
-- Name: fn_mirror_to_webhook_events_v2(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_mirror_to_webhook_events_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
BEGIN
  INSERT INTO evo.evolution_webhook_events_v2 (
    id, event_type, instance_name, remote_jid,
    from_me, message_type, push_name, payload,
    processed, processed_at, error_message,
    status, retry_count, created_at
  )
  VALUES (
    NEW.id, NEW.event_type, NEW.instance_name, NEW.remote_jid,
    NEW.from_me, NEW.message_type, NEW.push_name, NEW.payload,
    COALESCE(NEW.processed, false),
    NEW.processed_at, NEW.error_message,
    NEW.status::text,  -- cast de enum para text
    0, -- retry_count (coluna nova no v2)
    NEW.created_at
  )
  ON CONFLICT (id, created_at) DO NOTHING;  -- idempotente
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Mirror nunca deve bloquear o write principal
  RAISE WARNING 'fn_mirror_to_webhook_events_v2 falhou para id %: %', NEW.id, SQLERRM;
  RETURN NEW;
END;
$$;


