--
-- Name: fn_monitor_dlq_health(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_monitor_dlq_health(p_threshold integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
DECLARE
  v_pending   INT;
  v_oldest    TIMESTAMPTZ;
  v_alert_id  UUID;
BEGIN
  -- Contar entradas pendentes
  SELECT count(*), min(created_at)
  INTO v_pending, v_oldest
  FROM evo.evolution_webhook_dlq
  WHERE status = 'pending';

  -- Se abaixo do threshold, resolver alertas existentes de DLQ
  IF v_pending < p_threshold THEN
    UPDATE evo.evolution_alerts
    SET resolved_at = now(), acknowledged_at = now()
    WHERE alert_type = 'dlq_accumulation'
      AND acknowledged = false AND resolved = false;

    RETURN jsonb_build_object(
      'status', 'healthy',
      'pending_count', v_pending,
      'threshold', p_threshold,
      'action', 'none'
    );
  END IF;

  -- Acima do threshold: criar/atualizar alerta
  -- Verificar se já existe alerta aberto (evitar flood)
  IF NOT EXISTS (
    SELECT 1 FROM evo.evolution_alerts
    WHERE alert_type = 'dlq_accumulation'
      AND acknowledged = false AND resolved = false
  ) THEN
    INSERT INTO evo.evolution_alerts (
      alert_type, severity, message, acknowledged, created_at
    ) VALUES (
      'dlq_accumulation',
      CASE WHEN v_pending > 100 THEN 'critical'
           WHEN v_pending > 50  THEN 'high'
           ELSE 'medium' END,
      format('DLQ acumulou %s mensagens pendentes. Mais antiga: %s',
             v_pending, v_oldest::timestamptz(0)),
      false, now()
    )
    RETURNING id INTO v_alert_id;

    RETURN jsonb_build_object(
      'status', 'alert_created',
      'pending_count', v_pending,
      'threshold', p_threshold,
      'alert_id', v_alert_id,
      'oldest_entry', v_oldest
    );
  END IF;

  RETURN jsonb_build_object(
    'status', 'alert_already_open',
    'pending_count', v_pending,
    'threshold', p_threshold
  );
END;
$$;


--
-- Name: fn_monitor_slow_queries(numeric, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_monitor_slow_queries(p_min_ms numeric DEFAULT 500, p_min_calls integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'extensions'
    AS $$
DECLARE v_top jsonb; v_count int := 0; v_alert_threshold numeric := 2000;
BEGIN
  SELECT jsonb_agg(row_to_json(q)) INTO v_top FROM (
    SELECT round(mean_exec_time::numeric,0) as mean_ms, calls,
      round((total_exec_time/1000)::numeric,1) as total_sec, LEFT(query,120) as query_preview
    FROM extensions.pg_stat_statements
    WHERE mean_exec_time > p_min_ms AND calls > p_min_calls
    ORDER BY total_exec_time DESC LIMIT 10
  ) q;
  -- FIX: usar array_length nao ROW_COUNT
  v_count := jsonb_array_length(COALESCE(v_top, '[]'::jsonb));
  IF v_count > 0 AND EXISTS(SELECT 1 FROM extensions.pg_stat_statements WHERE mean_exec_time > v_alert_threshold AND calls > 10) THEN
    INSERT INTO zapp.app_notifications(user_id,title,body,type,metadata)
    SELECT u.id,'Slow Query Alert','Queries com mean_ms > '||v_alert_threshold||'ms detectadas','warning',
      jsonb_build_object('top_queries',v_top,'threshold_ms',v_alert_threshold)
    FROM auth.users u JOIN zapp.profiles p ON p.id=u.id WHERE p.role='admin'
    ON CONFLICT DO NOTHING;
  END IF;
  RETURN jsonb_build_object('checked_at',now(),'queries_above_threshold',v_count,'threshold_ms',p_min_ms,'top_slow',COALESCE(v_top,'[]'::jsonb));
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('error',SQLERRM,'checked_at',now());
END;
$$;


--
-- Name: FUNCTION fn_monitor_slow_queries(p_min_ms numeric, p_min_calls integer); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_monitor_slow_queries(p_min_ms numeric, p_min_calls integer) IS 'Monitora queries lentas via pg_stat_statements. Alerta via app_notifications se mean > 2000ms. Cron horario. Criado em auditoria 2026-07-04.';


