--
-- Name: fn_move_sticker_category(uuid, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_move_sticker_category(p_sticker_id uuid, p_new_category text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
DECLARE
  v_old_category text;
BEGIN
  -- Validar categoria
  IF NOT EXISTS (SELECT 1 FROM sticker_categories WHERE slug = p_new_category AND is_active = true) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Categoria nao encontrada: ' || p_new_category);
  END IF;
  
  SELECT category INTO v_old_category FROM stickers WHERE id = p_sticker_id;
  IF v_old_category IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sticker nao encontrado');
  END IF;
  
  UPDATE stickers SET category = p_new_category WHERE id = p_sticker_id;
  
  RETURN jsonb_build_object(
    'ok', true,
    'sticker_id', p_sticker_id,
    'old_category', v_old_category,
    'new_category', p_new_category
  );
END;
$$;


