--
-- Name: fn_normalize_br_phone(text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_normalize_br_phone(raw_phone text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  cleaned text;
  len integer;
BEGIN
  -- Remove tudo que não é dígito
  cleaned := regexp_replace(raw_phone, '[^0-9]', '', 'g');
  len := length(cleaned);
  
  -- Remove prefixo 55 se presente
  IF len >= 12 AND left(cleaned, 2) = '55' THEN
    cleaned := substring(cleaned FROM 3);
    len := length(cleaned);
  END IF;
  
  -- Se tem 10 dígitos (sem 9o dígito), adiciona o 9 para celulares
  IF len = 10 THEN
    -- Celulares começam com 9,8,7,6 após DDD
    IF substring(cleaned FROM 3 FOR 1) IN ('9','8','7','6') THEN
      cleaned := left(cleaned, 2) || '9' || substring(cleaned FROM 3);
    END IF;
  END IF;
  
  RETURN cleaned;
END;
$$;


--
-- Name: fn_normalize_message_types(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_normalize_message_types(p_batch_size integer DEFAULT 5000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET statement_timeout TO '240s'
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_started timestamptz:=clock_timestamp(); v_updated int:=0; v_batch int; v_from text; v_to text; v_froms text[]:=ARRAY['imageMessage','audioMessage','videoMessage','documentMessage','stickerMessage']; v_tos text[]:=ARRAY['image','audio','video','document','sticker']; i int;
BEGIN
  FOR i IN 1..array_length(v_froms,1) LOOP v_from:=v_froms[i]; v_to:=v_tos[i];
    LOOP WITH batch AS (SELECT id FROM evolution_messages WHERE message_type=v_from LIMIT p_batch_size) UPDATE evolution_messages em SET message_type=v_to FROM batch WHERE em.id=batch.id; GET DIAGNOSTICS v_batch=ROW_COUNT; v_updated:=v_updated+v_batch; EXIT WHEN v_batch=0; END LOOP;
  END LOOP;
  RETURN jsonb_build_object('status','ok','total_updated',v_updated);
END; $$;


--
-- Name: fn_normalize_phone(text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_normalize_phone(p_phone text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  v_digits text;
  v_len    int;
BEGIN
  -- Extrair apenas digitos
  v_digits := regexp_replace(COALESCE(p_phone, ''), '[^0-9]', '', 'g');

  IF v_digits = '' THEN
    RETURN NULL;
  END IF;

  -- Remover zero lider: DDD pode ser escrito como '021', '011', etc.
  -- Ex: '02199998888' (11d) -> remove '0' -> '2199998888' (10d)
  IF left(v_digits, 1) = '0' THEN
    v_digits := substring(v_digits, 2);
  END IF;

  v_len := length(v_digits);

  -- 10-11 digitos: numero sem DDI -> adicionar '55' (Brasil)
  IF v_len BETWEEN 10 AND 11 THEN
    RETURN '55' || v_digits;
  END IF;

  -- 12-13 digitos: deve comecar com '55' (DDI Brasil) para ser valido
  IF v_len BETWEEN 12 AND 13 THEN
    IF left(v_digits, 2) = '55' THEN
      RETURN v_digits;
    END IF;
    -- DDI diferente de 55: nao e numero brasileiro -> NULL
    RETURN NULL;
  END IF;

  -- Fora de range (< 10 ou > 13 digitos): invalido
  RETURN NULL;
END;
$$;


--
-- Name: fn_normalize_send_jid(text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_normalize_send_jid(p_jid text, p_instance text DEFAULT 'wpp2'::text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $_$
DECLARE v_jid text; v_phone text;
BEGIN
  -- [2026-07-05 lid-guard] Evolution 2.3.7: sendText a JID @lid quebra (onWhatsApp
  -- valida errado; corrigido apenas na 2.4.0-rc2). Normaliza para o JID numerico.
  -- Regex ASCII-anchored (aprendizado CNPJ: \d casa digitos unicode).
  v_jid := btrim(coalesce(p_jid,''));
  IF v_jid = '' THEN
    RAISE EXCEPTION 'fn_normalize_send_jid: jid vazio/nulo' USING ERRCODE='22023';
  END IF;
  IF lower(v_jid) ~ '^[0-9]+@lid$' THEN
    SELECT ec.phone_number INTO v_phone
    FROM evo.evolution_contacts ec
    WHERE lower(ec.remote_jid) = lower(v_jid)
      AND ec.instance_name = p_instance
      AND ec.phone_number ~ '^[0-9]+$'
    ORDER BY ec.updated_at DESC LIMIT 1;
    IF v_phone IS NULL THEN
      RAISE EXCEPTION 'fn_normalize_send_jid: JID @lid % sem phone_number mapeado em evolution_contacts (instancia %) — envio bloqueado (bug 2.3.7)', v_jid, p_instance USING ERRCODE='22023';
    END IF;
    RETURN v_phone || '@s.whatsapp.net';
  END IF;
  IF v_jid ~ '^[0-9]+@(s\.whatsapp\.net|g\.us|c\.us)$' OR v_jid = 'status@broadcast' THEN
    RETURN v_jid;
  END IF;
  RAISE EXCEPTION 'fn_normalize_send_jid: JID malformado: %', v_jid USING ERRCODE='22023';
END $_$;


--
-- Name: FUNCTION fn_normalize_send_jid(p_jid text, p_instance text); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_normalize_send_jid(p_jid text, p_instance text) IS 'Guard @lid p/ Evolution 2.3.7 (bug envio @lid, fix so em 2.4.0-rc2). Validada em 100 cenarios adversariais 2026-07-05. Usar em todo caminho de envio SQL/RPC.';


