--

CREATE FUNCTION zapp.fn_optimization_recommendations() RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE v jsonb:='[]';
BEGIN
  IF (SELECT count(*) FROM evolution_webhook_events WHERE processed=false AND created_at<now()-interval '1 hour')>0 THEN v:=v||'"Eventos nao processados ha mais de 1 hora"'::jsonb; END IF;
  IF (SELECT count(*) FROM evolution_conversations WHERE status IN ('aberta','open') AND last_message_at<now()-interval '24 hours')>10 THEN v:=v||'"Mais de 10 conversas abertas sem resposta ha 24h"'::jsonb; END IF;
  IF (SELECT count(*) FROM evolution_alerts WHERE acknowledged=false AND severity='critical')>0 THEN v:=v||'"Alertas criticos nao reconhecidos"'::jsonb; END IF;
  RETURN jsonb_build_object('recommendations',v,'generated_at',now());
END; $$;


--
-- Name: fn_outbound_dispatch(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_outbound_dispatch(p_batch_size integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'net'
    AS $$
DECLARE
  v_api_url   text;
  v_api_key   text;
  v_row       record;
  v_conn      record;
  v_endpoint  text;
  v_body      jsonb;
  v_req_id    bigint;
  v_sent      int := 0;
  v_skipped   int := 0;
  v_failed    int := 0;
BEGIN
  SELECT decrypted_secret INTO v_api_url FROM vault.decrypted_secrets WHERE name = 'evolution_api_url';
  SELECT decrypted_secret INTO v_api_key FROM vault.decrypted_secrets WHERE name = 'evolution_api_key';
  IF v_api_url IS NULL OR v_api_key IS NULL THEN
    RAISE EXCEPTION '[fn_outbound_dispatch] vault secrets faltando';
  END IF;
  v_api_url := rtrim(v_api_url, '/');

  FOR v_row IN
    SELECT q.*
    FROM zapp.outbound_message_queue q
    WHERE q.status = 'pending'
      -- FIX v6.2.9: COALESCE para proteger contra max_retries IS NULL
      AND coalesce(q.retry_count, 0) < coalesce(q.max_retries, 3)
    ORDER BY q.created_at ASC
    LIMIT p_batch_size
    FOR UPDATE SKIP LOCKED
  LOOP
    SELECT status INTO v_conn
    FROM zapp.whatsapp_connections
    WHERE instance_name = v_row.instance_name LIMIT 1;

    IF v_conn IS NULL OR v_conn.status <> 'connected' THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    BEGIN
      IF (v_row.message_type = 'text' OR v_row.message_type IS NULL) AND v_row.content IS NULL THEN
        RAISE EXCEPTION 'content nulo para mensagem de texto (id=%)', v_row.id;
      END IF;
      IF v_row.message_type NOT IN ('text') AND v_row.message_type IS NOT NULL AND v_row.media_url IS NULL THEN
        RAISE EXCEPTION 'media_url nulo para tipo % (id=%)', v_row.message_type, v_row.id;
      END IF;

      IF v_row.message_type = 'text' OR v_row.message_type IS NULL THEN
        v_endpoint := v_api_url || '/message/sendText/' || v_row.instance_name;
        v_body := jsonb_build_object('number', split_part(v_row.remote_jid,'@',1), 'text', v_row.content);
      ELSIF v_row.message_type = 'audio' THEN
        v_endpoint := v_api_url || '/message/sendMedia/' || v_row.instance_name;
        v_body := jsonb_build_object(
          'number', split_part(v_row.remote_jid,'@',1),
          'mediatype','audio',
          'mimetype', coalesce(v_row.media_mime_type,'audio/ogg; codecs=opus'),
          'media', v_row.media_url, 'ptt', coalesce(v_row.ptt, true));
      ELSE
        v_endpoint := v_api_url || '/message/sendMedia/' || v_row.instance_name;
        v_body := jsonb_build_object(
          'number', split_part(v_row.remote_jid,'@',1),
          'mediatype', v_row.message_type,
          'mimetype', coalesce(v_row.media_mime_type,'application/octet-stream'),
          'media', v_row.media_url, 'caption', v_row.caption,
          'fileName', coalesce((v_row.metadata->>'fileName')::text,'file'));
      END IF;

      v_req_id := net.http_post(
        url     := v_endpoint, body := v_body,
        headers := jsonb_build_object('apikey', v_api_key, 'Content-Type','application/json'),
        timeout_milliseconds := 10000);

      UPDATE zapp.outbound_message_queue
      SET status='sending', external_id=v_req_id::text, sent_at=now(), updated_at=now()
      WHERE id = v_row.id;
      v_sent := v_sent + 1;

    EXCEPTION WHEN OTHERS THEN
      UPDATE zapp.outbound_message_queue
      SET
        retry_count   = coalesce(retry_count,0) + 1,
        error_message = left(SQLERRM, 500),
        failed_at     = CASE WHEN coalesce(retry_count,0)+1 > coalesce(max_retries,3) THEN now() ELSE NULL END,
        status        = CASE WHEN coalesce(retry_count,0)+1 > coalesce(max_retries,3) THEN 'failed' ELSE 'pending' END,
        updated_at    = now()
      WHERE id = v_row.id;
      v_failed := v_failed + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object('dispatched_at',now(),'sent',v_sent,'skipped',v_skipped,'failed',v_failed);
END;
$$;


--
-- Name: fn_outbound_dispatch_apply(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_outbound_dispatch_apply(p_batch_size integer DEFAULT 50) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'net'
    AS $$
DECLARE
  v_row    record;
  v_resp   record;
  v_applied int := 0;
BEGIN
  -- BUG FIX v6.2.8a: coluna e 'content', nao 'body'; adicionar FOR UPDATE SKIP LOCKED
  -- para evitar race condition com crons concorrentes
  FOR v_row IN
    SELECT q.id, q.external_id::bigint AS req_id
    FROM zapp.outbound_message_queue q
    WHERE q.status = 'sending'
      AND q.sent_at < now() - interval '3 seconds'
      AND q.external_id IS NOT NULL
    LIMIT p_batch_size
    FOR UPDATE SKIP LOCKED
  LOOP
    BEGIN
      -- FIX: coluna chama-se 'content', nao 'body'
      SELECT status_code, content AS body, timed_out, error_msg
      INTO v_resp
      FROM net._http_response
      WHERE id = v_row.req_id;

      IF FOUND THEN
        -- Timeout de rede: tratar como falha
        IF v_resp.timed_out IS TRUE THEN
          UPDATE zapp.outbound_message_queue
          SET
            status        = CASE WHEN retry_count + 1 > max_retries THEN 'failed' ELSE 'pending' END,
            retry_count   = retry_count + 1,
            error_message = 'pg_net timeout: ' || coalesce(v_resp.error_msg, 'request timed out'),
            failed_at     = CASE WHEN retry_count + 1 > max_retries THEN now() ELSE NULL END,
            updated_at    = now()
          WHERE id = v_row.id;
        ELSIF v_resp.status_code BETWEEN 200 AND 299 THEN
          UPDATE zapp.outbound_message_queue
          SET status='sent', updated_at=now()
          WHERE id=v_row.id;
        ELSE
          -- BUG FIX v6.2.8b: usar > em vez de >= para corrigir off-by-one no retry
          UPDATE zapp.outbound_message_queue
          SET
            status        = CASE WHEN retry_count + 1 > max_retries THEN 'failed' ELSE 'pending' END,
            retry_count   = retry_count + 1,
            error_message = left(coalesce(v_resp.body::text, v_resp.error_msg, 'http_'||v_resp.status_code::text), 500),
            failed_at     = CASE WHEN retry_count + 1 > max_retries THEN now() ELSE NULL END,
            updated_at    = now()
          WHERE id=v_row.id;
        END IF;
        v_applied := v_applied + 1;
      END IF;
      -- Se nao FOUND: request ainda em flight (< 3s), ignorar e tentar no proximo ciclo
    EXCEPTION WHEN OTHERS THEN
      -- Erro inesperado: logar no error_message sem travar o loop
      UPDATE zapp.outbound_message_queue
      SET error_message = left('apply_exception: '||SQLERRM, 500), updated_at=now()
      WHERE id=v_row.id;
    END;
  END LOOP;
  RETURN v_applied;
END;
$$;


--
-- Name: fn_outbound_sending_reaper(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_outbound_sending_reaper() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE v_reaped int;
BEGIN
  UPDATE zapp.outbound_message_queue
  SET
    status        = CASE WHEN retry_count + 1 > max_retries THEN 'failed' ELSE 'pending' END,
    retry_count   = retry_count + 1,
    error_message = 'reaper: sending stuck > 15min sem resposta pg_net',
    failed_at     = CASE WHEN retry_count + 1 > max_retries THEN now() ELSE NULL END,
    external_id   = NULL,
    sent_at       = NULL,
    updated_at    = now()
  WHERE status = 'sending'
    AND sent_at < now() - interval '15 minutes';
  GET DIAGNOSTICS v_reaped = ROW_COUNT;
  RETURN v_reaped;
END;
$$;


--
-- Name: fn_outbound_updated_at(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_outbound_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.updated_at = now();
  IF NEW.status = 'sent' AND OLD.status != 'sent' THEN NEW.sent_at = now(); END IF;
  IF NEW.status = 'failed' AND OLD.status != 'failed' THEN NEW.failed_at = now(); END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_parse_baileys_long(jsonb); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_parse_baileys_long(p_val jsonb) RETURNS bigint
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
  IF p_val IS NULL THEN RETURN NULL; END IF;
  IF jsonb_typeof(p_val) = 'number' THEN RETURN p_val::text::bigint; END IF;
  IF jsonb_typeof(p_val) = 'object' AND p_val ? 'low' THEN RETURN ((p_val->>'high')::bigint * 4294967296 + (p_val->>'low')::bigint); END IF;
  IF jsonb_typeof(p_val) = 'string' THEN RETURN NULLIF(p_val#>>'{}','')::bigint; END IF;
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN RETURN NULL;
END; $$;


--
-- Name: fn_parse_timestamp_flexible(text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_parse_timestamp_flexible(p_val text) RETURNS timestamp with time zone
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
DECLARE v_num bigint;
BEGIN
  IF p_val IS NULL OR p_val='' THEN RETURN NULL; END IF;
  IF p_val ~ '^[0-9]{10,13}$' THEN v_num:=p_val::bigint; IF length(p_val)>=13 THEN RETURN to_timestamp(v_num/1000.0); ELSE RETURN to_timestamp(v_num); END IF; END IF;
  BEGIN RETURN p_val::timestamptz; EXCEPTION WHEN OTHERS THEN RETURN NULL; END;
END; $_$;


--
-- Name: fn_peak_hours_analysis(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_peak_hours_analysis(p_days integer DEFAULT 7) RETURNS TABLE(hora integer, msgs_total bigint, msgs_inbound bigint, msgs_outbound bigint)
    LANGUAGE sql STABLE
    AS $$
  SELECT EXTRACT(HOUR FROM created_at)::integer, count(*), count(*) FILTER(WHERE direction='inbound'), count(*) FILTER(WHERE direction='outbound') FROM evolution_messages WHERE created_at>=now()-make_interval(days:=p_days) GROUP BY 1 ORDER BY 1;
$$;


--
-- Name: fn_pipeline_analytics(text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_pipeline_analytics(p_instance text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v jsonb;
BEGIN
  SELECT jsonb_build_object(
    'total_deals',(SELECT count(*) FROM evolution_deals WHERE (p_instance IS NULL OR instance_name=p_instance)),
    'total_value',(SELECT COALESCE(sum(value),0) FROM evolution_deals WHERE stage NOT IN ('perdido','pedido_finalizado') AND (p_instance IS NULL OR instance_name=p_instance)),
    'by_stage',(SELECT jsonb_object_agg(stage,cnt) FROM (SELECT stage,count(*) cnt FROM evolution_deals WHERE (p_instance IS NULL OR instance_name=p_instance) GROUP BY stage) t),
    'avg_value',(SELECT COALESCE(avg(value),0) FROM evolution_deals WHERE value>0 AND (p_instance IS NULL OR instance_name=p_instance)),
    'conversion_rate',(SELECT round(100.0*count(*) FILTER(WHERE stage='pedido_finalizado')/NULLIF(count(*),0),1) FROM evolution_deals WHERE (p_instance IS NULL OR instance_name=p_instance))
  ) INTO v;
  RETURN v;
END; $$;


