    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v integer;
BEGIN DELETE FROM evolution_pipeline_health_log WHERE checked_at<now()-interval '30 days'; GET DIAGNOSTICS v=ROW_COUNT; RETURN v; EXCEPTION WHEN OTHERS THEN RETURN 0; END; $$;


--
-- Name: fn_pipeline_watchdog(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_pipeline_watchdog() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$ DECLARE v_last_event timestamptz; v_hours_silent numeric; v_pending_wh int; v_result jsonb; v_alerts jsonb := '[]'::jsonb; v_recent_alert bigint; BEGIN SELECT MAX(created_at) INTO v_last_event FROM zapp.webhook_audit_log WHERE status='processed'; v_hours_silent := round( EXTRACT(EPOCH FROM (now() - COALESCE(v_last_event, now() - interval '9999 hours'))) / 3600, 1 ); SELECT count(*) INTO v_pending_wh FROM zapp.webhook_audit_log WHERE status='pending'; IF v_hours_silent > 4 THEN v_alerts := v_alerts || jsonb_build_object( 'level', 'CRITICAL', 'code', 'PIPELINE_SILENT', 'msg', 'Sem webhooks processados ha ' || v_hours_silent || 'h -- ultimo em ' || COALESCE(v_last_event::text,'nunca') ); SELECT COUNT(*) INTO v_recent_alert FROM evo.evolution_alerts WHERE alert_type = 'pipeline_silent' AND resolved_at IS NULL AND created_at > now() - INTERVAL '4 hours'; IF v_recent_alert = 0 THEN INSERT INTO evo.evolution_alerts (id, alert_type, severity, title, message, payload, acknowledged, created_at) VALUES (gen_random_uuid(), 'pipeline_silent', 'critical', 'Pipeline silencioso ha ' || v_hours_silent || 'h', 'Pipeline sem webhooks processados ha ' || v_hours_silent || ' horas', jsonb_build_object('last_event', v_last_event, 'hours_silent', v_hours_silent, 'source_table', 'zapp.webhook_audit_log'), false, now()); END IF; ELSE UPDATE evo.evolution_alerts SET resolved_at = now(), resolved_by = 'fn_pipeline_watchdog:auto' WHERE alert_type = 'pipeline_silent' AND resolved_at IS NULL; END IF; IF v_pending_wh > 100 THEN v_alerts := v_alerts || jsonb_build_object('level', 'WARNING', 'code', 'WEBHOOK_BACKLOG', 'msg', v_pending_wh::text || ' webhooks pendentes'); END IF; RETURN jsonb_build_object('checked_at', now(), 'last_event', v_last_event, 'hours_silent', v_hours_silent, 'pending_wh', v_pending_wh, 'alerts', v_alerts, 'alert_count', jsonb_array_length(v_alerts), 'status', CASE WHEN jsonb_array_length(v_alerts) = 0 THEN 'ok' ELSE 'degraded' END, 'source_table', 'zapp.webhook_audit_log'); END; $$;


--
-- Name: fn_pml_protect_immutable(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_pml_protect_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  IF (OLD.idempotency_key IS DISTINCT FROM NEW.idempotency_key)
     OR (OLD.payload IS DISTINCT FROM NEW.payload)
     OR (OLD.payload_hash IS DISTINCT FROM NEW.payload_hash)
     OR (OLD.provider IS DISTINCT FROM NEW.provider)
     OR (OLD.external_message_id IS DISTINCT FROM NEW.external_message_id)
     OR (OLD.received_at IS DISTINCT FROM NEW.received_at) THEN
    RAISE EXCEPTION 'provider_message_log: immutable columns cannot be modified';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_populate_tail_missing(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_populate_tail_missing() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET statement_timeout TO '180s'
    SET search_path TO 'archive', 'zapp', 'pg_temp'
    AS $$ DECLARE v_count int; BEGIN TRUNCATE archive.audit_tail_missing; INSERT INTO archive.audit_tail_missing (source_id) SELECT s.source_id FROM archive.audit_source_tail_10k s LEFT JOIN archive.audit_mv_baileys_ids mv ON mv.baileys_id = s.source_id WHERE mv.baileys_id IS NULL; SELECT count(*) INTO v_count FROM archive.audit_tail_missing; RETURN v_count; END $$;


--
-- Name: fn_process_chat_update(jsonb, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_process_chat_update(p_payload jsonb, p_instance text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_chat_count int := 0;
BEGIN
  IF jsonb_typeof(p_payload) = 'array' THEN
    v_chat_count := jsonb_array_length(p_payload);
  END IF;

  -- Eventos chats.update sem dados úteis (só remoteJid+instanceId): skip
  RETURN jsonb_build_object(
    'ok', true,
    'action', 'chats_acknowledged',
    'chat_count', v_chat_count
  );
END;
$$;


--
-- Name: fn_process_contacts_batch(jsonb, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_process_contacts_batch(p_contacts jsonb, p_instance text DEFAULT 'wpp2'::text) RETURNS TABLE(processed integer, skipped integer, error_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $_$
DECLARE
  v_processed integer := 0;
  v_skipped integer := 0;
  v_errors integer := 0;
  v_arr_size integer := 0;
  v_use_batch_mode boolean := false;
BEGIN
  IF p_contacts IS NULL OR jsonb_typeof(p_contacts) NOT IN ('array','object') THEN
    RETURN QUERY SELECT 0, 0, 0;
    RETURN;
  END IF;

  IF jsonb_typeof(p_contacts) = 'object' THEN
    p_contacts := jsonb_build_array(p_contacts);
  END IF;

  v_arr_size := jsonb_array_length(p_contacts);
  v_use_batch_mode := v_arr_size > 50;

  IF v_use_batch_mode THEN
    PERFORM set_config('app.batch_mode', 'on', true);
  END IF;

  SELECT COUNT(*) INTO v_skipped
  FROM jsonb_array_elements(p_contacts) AS c
  WHERE COALESCE(c->>'id', c->>'remoteJid') IS NULL;

  WITH input_rows AS (
    SELECT 
      COALESCE(c->>'id', c->>'remoteJid') AS remote_jid,
      COALESCE(c->>'pushName', c->>'name', c->>'notify') AS push_name,
      -- 🔧 FIX: grupos/broadcasts/newsletters NÃO têm phone_number (NULL).
      -- Contatos pessoais (@s.whatsapp.net) extraem o número antes do '@'.
      -- substring(...FOR 20) é defesa extra (caso algo escape, não estoura).
      CASE 
        WHEN COALESCE(c->>'id', c->>'remoteJid') LIKE '%@g.us' THEN NULL
        WHEN COALESCE(c->>'id', c->>'remoteJid') LIKE '%@broadcast' THEN NULL
        WHEN COALESCE(c->>'id', c->>'remoteJid') LIKE '%@newsletter' THEN NULL
        ELSE substring(regexp_replace(COALESCE(c->>'id', c->>'remoteJid'), '@.+$', '') FROM 1 FOR 20)
      END AS phone_number,
      COALESCE(c->>'profilePictureUrl', c->>'imgUrl') AS profile_picture_url
    FROM jsonb_array_elements(p_contacts) AS c
    WHERE COALESCE(c->>'id', c->>'remoteJid') IS NOT NULL
  ),
  upsert_result AS (
    INSERT INTO zapp.evolution_contacts (
      remote_jid, push_name, phone_number, profile_picture_url, instance_name
    )
    SELECT remote_jid, push_name, phone_number, profile_picture_url, p_instance
    FROM input_rows
    ON CONFLICT (remote_jid) DO UPDATE SET
      push_name = COALESCE(EXCLUDED.push_name, evolution_contacts.push_name),
      -- 🔧 FIX: também atualiza phone_number (com a regra correta - NULL pra grupos)
      phone_number = EXCLUDED.phone_number,
      profile_picture_url = COALESCE(EXCLUDED.profile_picture_url, evolution_contacts.profile_picture_url),
      updated_at = NOW()
    RETURNING id
  )
  SELECT COUNT(*) INTO v_processed FROM upsert_result;

  IF v_use_batch_mode THEN
    PERFORM set_config('app.batch_mode', 'off', true);
  END IF;

  RETURN QUERY SELECT v_processed, v_skipped, v_errors;

EXCEPTION WHEN OTHERS THEN
  v_errors := 1;
  PERFORM set_config('app.batch_mode', 'off', true);
  RAISE WARNING 'fn_process_contacts_batch failed: % %', SQLSTATE, SQLERRM;
  RETURN QUERY SELECT v_processed, v_skipped, v_errors;
END;
$_$;


