--
-- Name: fn_process_message_edited(jsonb, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_process_message_edited(p_payload jsonb, p_instance text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_type text; v_message_id text; v_remote_jid text;
  v_new_content text; v_action text; v_rows_affected int;
BEGIN
  v_type := COALESCE(p_payload->>'type', 'UNKNOWN');
  v_message_id := COALESCE(p_payload->'key'->>'id', p_payload->>'messageId');
  v_remote_jid := COALESCE(p_payload->'key'->>'remoteJid', p_payload->>'remoteJid');

  CASE v_type
    WHEN 'MESSAGE_EDIT' THEN
      v_new_content := COALESCE(
        p_payload->'editedMessage'->'message'->>'conversation',
        p_payload->'editedMessage'->'message'->'extendedTextMessage'->>'text',
        p_payload->>'editedText'
      );
      IF v_message_id IS NOT NULL AND v_new_content IS NOT NULL THEN
        UPDATE zapp.evolution_messages
        SET content = v_new_content, edited_at = COALESCE(edited_at, NOW()), updated_at = NOW()
        WHERE message_id = v_message_id AND instance_name = p_instance;
        GET DIAGNOSTICS v_rows_affected = ROW_COUNT;
        v_action := CASE WHEN v_rows_affected > 0 THEN 'message_edited' ELSE 'message_not_found' END;
      ELSE v_action := 'skipped_no_data';
      END IF;

    WHEN 'REVOKE' THEN
      IF v_message_id IS NOT NULL THEN
        UPDATE zapp.evolution_messages
        SET deleted_at = NOW(), updated_at = NOW()
        WHERE message_id = v_message_id AND instance_name = p_instance;
        GET DIAGNOSTICS v_rows_affected = ROW_COUNT;
        v_action := CASE WHEN v_rows_affected > 0 THEN 'message_revoked' ELSE 'message_not_found' END;
      ELSE v_action := 'skipped_no_id';
      END IF;

    ELSE
      v_action := 'skipped_' || lower(v_type);
  END CASE;

  RETURN jsonb_build_object('ok', true, 'type', v_type, 'action', v_action, 'message_id', v_message_id);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('ok', false, 'error', SQLERRM, 'sqlstate', SQLSTATE);
END;
$$;


--
-- Name: fn_process_message_queue(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_process_message_queue(p_batch integer DEFAULT 10) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v integer;
BEGIN UPDATE evolution_message_queue SET status='processing' WHERE id IN (SELECT id FROM evolution_message_queue WHERE status='pending' ORDER BY created_at LIMIT p_batch FOR UPDATE SKIP LOCKED); GET DIAGNOSTICS v=ROW_COUNT; RETURN v; END; $$;


