-- Name: FUNCTION fn_r2_media_path(p_instance text, p_media_type text, p_message_id text, p_created_at timestamp with time zone); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_r2_media_path(p_instance text, p_media_type text, p_message_id text, p_created_at timestamp with time zone) IS 'Gera path organizado para armazenamento no R2: instance/tipo/ano/mes/message_id.ext';


--
-- Name: fn_rate_limit_check(text, text, integer, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_rate_limit_check(p_identifier text, p_rpc_name text, p_max_calls integer DEFAULT 60, p_window_minutes integer DEFAULT 1) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $_$
DECLARE
  v_count int;
  v_ws    timestamptz;
  v_id    text;
  v_rpc   text;
BEGIN
  -- Normalise: strip ALL whitespace (space, tab, newline, carriage-return)
  v_id  := regexp_replace(p_identifier, '^[\s]+|[\s]+$', '', 'g');
  v_rpc := regexp_replace(p_rpc_name,   '^[\s]+|[\s]+$', '', 'g');

  -- Fail-closed: NULL, empty-after-trim, zero/negative numeric args
  IF p_identifier IS NULL OR v_id = ''
    OR p_rpc_name IS NULL OR v_rpc = ''
    OR p_window_minutes IS NULL OR p_window_minutes <= 0
    OR p_max_calls IS NULL OR p_max_calls <= 0
  THEN
    RETURN FALSE;
  END IF;

  v_ws := to_timestamp(
    floor(EXTRACT(epoch FROM now()) / (p_window_minutes * 60))
    * (p_window_minutes * 60)
  );

  INSERT INTO rpc_rate_limits (identifier, rpc_name, window_start, call_count)
  VALUES (v_id, v_rpc, v_ws, 1)
  ON CONFLICT (identifier, rpc_name, window_start)
    DO UPDATE SET call_count = rpc_rate_limits.call_count + 1
  RETURNING call_count INTO v_count;

  RETURN v_count <= p_max_calls;
END;
$_$;


--
-- Name: FUNCTION fn_rate_limit_check(p_identifier text, p_rpc_name text, p_max_calls integer, p_window_minutes integer); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_rate_limit_check(p_identifier text, p_rpc_name text, p_max_calls integer, p_window_minutes integer) IS 'Rate limiter canonico por (identifier, rpc_name, janela de p_window_minutes minutos). Grava em zapp.rpc_rate_limits. Retorna TRUE se dentro do limite, FALSE se estourou. Janela alinhada: floor(epoch/(N*60))*N*60 - garante que multiplas chamadas dentro do mesmo periodo caem na mesma janela. Para N=1 (default): backward-compatible com comportamento anterior. CORRIGIDO 2026-07-17: p_window_minutes agora e USADO (era ignorado antes, janela fixa de 1 min). Callers devem ser fail-CLOSED: negar quando error IS NOT NULL.';


--
-- Name: fn_realtime_events_retention(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_realtime_events_retention() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v integer;
BEGIN DELETE FROM evolution_realtime_events WHERE created_at<now()-interval '48 hours'; GET DIAGNOSTICS v=ROW_COUNT; RETURN v; EXCEPTION WHEN OTHERS THEN RETURN 0; END; $$;


--
-- Name: fn_reconcile_apply(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_reconcile_apply() RETURNS TABLE(request_id bigint, instance_name text, action text, old_status text, new_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp, evo, extensions, pg_catalog'
    AS $$
DECLARE
  v_job record; v_content text; v_body jsonb; v_http int; v_inst jsonb;
  v_db_status text; v_evo_raw text; v_evo_status text; v_phone text; v_owner text;
  v_evo_id text; v_action text; v_results jsonb := '[]'::jsonb;
  v_matched_name text;
  v_db_disconnected_at timestamptz;
  v_debounced boolean;
  v_best_status_per_phone JSONB := '{}'::jsonb;
  v_priority int; v_best_priority int;
BEGIN
  PERFORM set_config('app.reconcile_source','cron_reconcile', true);
  FOR v_job IN
    SELECT j.id, j.request_id FROM evo.evolution_reconcile_jobs j
    WHERE j.applied_at IS NULL AND j.dispatched_at < now()-interval '2 seconds'
    ORDER BY j.dispatched_at LIMIT 50
  LOOP
    SELECT r.status_code, r.content INTO v_http, v_content FROM net._http_response r WHERE r.id=v_job.request_id;
    IF v_http IS NULL THEN CONTINUE; END IF;
    IF v_http<>200 OR v_content IS NULL OR left(ltrim(v_content),1)<>'[' THEN
      UPDATE evo.evolution_reconcile_jobs SET applied_at=now(), http_status=v_http,
        result=jsonb_build_object('error','http_or_body_invalid','http',v_http,'body_sample',left(coalesce(v_content,'<null>'),120))
      WHERE id=v_job.id; CONTINUE;
    END IF;
    BEGIN v_body:=v_content::jsonb;
    EXCEPTION WHEN others THEN
      UPDATE evo.evolution_reconcile_jobs SET applied_at=now(), http_status=v_http,
        result=jsonb_build_object('error','json_parse_failed','http',v_http,'body_sample',left(v_content,120))
      WHERE id=v_job.id; CONTINUE;
    END;
    IF jsonb_typeof(v_body)<>'array' THEN
      UPDATE evo.evolution_reconcile_jobs SET applied_at=now(), http_status=v_http,
        result=jsonb_build_object('error','body_not_array','http',v_http)
      WHERE id=v_job.id; CONTINUE;
    END IF;

    v_best_status_per_phone := '{}'::jsonb;

    FOR v_inst IN SELECT * FROM jsonb_array_elements(v_body) LOOP
      v_evo_raw   := v_inst->>'connectionStatus';
      v_owner     := v_inst->>'ownerJid';
      v_phone     := split_part(COALESCE(v_owner,''),'@',1);
      v_evo_status := CASE v_evo_raw WHEN 'open' THEN 'connected' WHEN 'connecting' THEN 'connecting' WHEN 'close' THEN 'disconnected' ELSE 'disconnected' END;
      v_priority   := CASE v_evo_status WHEN 'connected' THEN 4 WHEN 'connecting' THEN 3 WHEN 'disconnected' THEN 2 ELSE 1 END;

      IF v_phone IS NOT NULL AND v_phone!='' THEN
        v_best_priority := COALESCE((v_best_status_per_phone->>v_phone)::int, 0);
        IF v_priority > v_best_priority THEN
          v_best_status_per_phone := jsonb_set(v_best_status_per_phone, ARRAY[v_phone], to_jsonb(v_priority));
        END IF;
      END IF;
    END LOOP;

    FOR v_inst IN SELECT * FROM jsonb_array_elements(v_body) LOOP
      v_evo_raw    := v_inst->>'connectionStatus';
      v_owner      := v_inst->>'ownerJid';
      v_evo_id     := v_inst->>'id';
      v_phone      := split_part(COALESCE(v_owner,''),'@',1);
      v_evo_status := CASE v_evo_raw WHEN 'open' THEN 'connected' WHEN 'connecting' THEN 'connecting' WHEN 'close' THEN 'disconnected' ELSE 'disconnected' END;
      v_priority   := CASE v_evo_status WHEN 'connected' THEN 4 WHEN 'connecting' THEN 3 WHEN 'disconnected' THEN 2 ELSE 1 END;

      SELECT wc.instance_name, wc.status, wc.disconnected_at INTO v_matched_name, v_db_status, v_db_disconnected_at
      FROM zapp.whatsapp_connections wc WHERE wc.instance_name=(v_inst->>'name');

      IF NOT FOUND AND v_phone IS NOT NULL AND v_phone!='' THEN
        SELECT wc.instance_name, wc.status, wc.disconnected_at INTO v_matched_name, v_db_status, v_db_disconnected_at
        FROM zapp.whatsapp_connections wc
        WHERE wc.phone_number=v_phone AND wc.is_active=true LIMIT 1;
      END IF;

      -- FIX 2026-07-05 (sessao 6): mesmo debounce de fn_apply_connection_update. Reduz a
      -- prioridade tambem (3, igual 'connecting' genuino) para que o guard de prioridade
      -- abaixo continue funcionando sem caso especial: um 'open' debounced perde
      -- corretamente para outra entrada do mesmo telefone que reportou 'connected' de
      -- verdade no mesmo lote.
      v_debounced := false;
      IF v_matched_name IS NOT NULL AND v_evo_status = 'connected'
         AND v_db_disconnected_at IS NOT NULL
         AND v_db_disconnected_at > now() - interval '10 minutes' THEN
        v_evo_status := 'connecting';
        v_priority := 3;
        v_debounced := true;
      END IF;

      IF v_matched_name IS NULL THEN
        v_action := 'skip_not_in_db';
      ELSE
        v_best_priority := COALESCE((v_best_status_per_phone->>v_phone)::int, 0);
        IF v_priority < v_best_priority THEN
          v_action := 'skip_lower_priority';
        ELSIF v_db_status IS DISTINCT FROM v_evo_status THEN
          UPDATE zapp.whatsapp_connections wc SET
            status=v_evo_status,
            instance_id=v_evo_id,
            phone_number=COALESCE(NULLIF(v_phone,''), wc.phone_number),
            owner_jid=COALESCE(v_owner, wc.owner_jid),
            health_status=CASE v_evo_status WHEN 'connected' THEN 'ok' WHEN 'connecting' THEN 'degraded' WHEN 'disconnected' THEN 'error' ELSE 'unknown' END,
            health_reason=CASE
                            WHEN v_debounced THEN format('reconcile: evo_state=%s debounced (disconnected_at=%s < 10min ago)', v_evo_raw, v_db_disconnected_at)
                            WHEN v_evo_status='connected' THEN NULL
                            ELSE format('reconcile: evo_state=%s (evo_name=%s)', v_evo_raw, v_inst->>'name') END,
            last_health_check=now(),
            last_connected_at=CASE WHEN v_evo_status='connected' THEN now() ELSE wc.last_connected_at END,
            updated_at=now()
          WHERE wc.instance_name=v_matched_name;
          v_action := CASE WHEN v_matched_name!=(v_inst->>'name') THEN 'updated_via_phone_match' ELSE 'updated' END;
        ELSE
          -- R14 (2026-07-11): self-heal de health no ramo no_change (mesma correcao de fn_apply_connection_update)
          UPDATE zapp.whatsapp_connections wc SET last_health_check=now(), instance_id=v_evo_id,
            health_status=CASE WHEN v_evo_status='connected' AND NOT v_debounced AND wc.health_status IS DISTINCT FROM 'ok' THEN 'ok' ELSE wc.health_status END,
            health_reason=CASE WHEN v_evo_status='connected' AND NOT v_debounced AND wc.health_status IS DISTINCT FROM 'ok' THEN NULL ELSE wc.health_reason END
          WHERE wc.instance_name=v_matched_name;
          v_action := 'no_change';
        END IF;
      END IF;

      v_results := v_results || jsonb_build_object('instance',COALESCE(v_matched_name,v_inst->>'name'),'evo_name',v_inst->>'name','action',v_action,'old',v_db_status,'new',v_evo_status,'debounced',v_debounced);
      request_id := v_job.request_id; instance_name := COALESCE(v_matched_name,v_inst->>'name'); action := v_action; old_status := v_db_status; new_status := v_evo_status;
      RETURN NEXT;
      v_matched_name := NULL; v_db_status := NULL; v_db_disconnected_at := NULL;
    END LOOP;

    UPDATE evo.evolution_reconcile_jobs SET applied_at=now(), http_status=v_http, result=v_results WHERE id=v_job.id;
    v_results := '[]'::jsonb;
  END LOOP;
  RETURN;
END;
$$;


--
-- Name: FUNCTION fn_reconcile_apply(); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_reconcile_apply() IS 'Processa respostas pendentes (>2s) de evolution_reconcile_jobs e atualiza public.whatsapp_connections com connectionStatus, ownerJid, instance_id, phone_number. Mapeia connectionStatus: open→connected, connecting→connecting, close→disconnected. Disparado pelo cron whatsapp_reconcile_apply (1-59/5 * * * *, defasado 1min do dispatch).';


--
-- Name: fn_reconcile_dispatch(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_reconcile_dispatch() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'net'
    AS $$
DECLARE
  v_api_url text;
  v_api_key text;
  v_req_id  bigint;
BEGIN
  SELECT decrypted_secret INTO v_api_url FROM vault.decrypted_secrets WHERE name = 'evolution_api_url';
  SELECT decrypted_secret INTO v_api_key FROM vault.decrypted_secrets WHERE name = 'evolution_api_key';

  IF v_api_url IS NULL OR v_api_key IS NULL THEN
    RAISE EXCEPTION '[fn_reconcile_dispatch] vault.evolution_api_url ou evolution_api_key faltando';
  END IF;

  v_req_id := net.http_get(
    url := v_api_url || '/instance/fetchInstances',
    headers := jsonb_build_object('apikey', v_api_key, 'Accept', 'application/json'),
    timeout_milliseconds := 8000
  );

  INSERT INTO evo.evolution_reconcile_jobs (request_id) VALUES (v_req_id)
  ON CONFLICT (request_id) DO UPDATE
    SET dispatched_at = now();

  RETURN v_req_id;
END;
$$;


--
-- Name: FUNCTION fn_reconcile_dispatch(); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_reconcile_dispatch() IS 'Dispara um GET assíncrono em /instance/fetchInstances da Evolution via pg_net e registra o request_id em evolution_reconcile_jobs. Lê credenciais de vault.evolution_api_url e vault.evolution_api_key. Roda como SECURITY DEFINER. EXECUTE restrito a postgres+service_role. Disparado pelo cron whatsapp_reconcile_dispatch (*/5 * * * *).';


