--
-- Name: fn_register_instance(character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_register_instance(p_instance_name character varying, p_display_name character varying, p_phone character varying, p_department character varying, p_responsible character varying DEFAULT NULL::character varying) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
DECLARE
  v_id UUID; v_part_msgs TEXT; v_part_conv TEXT;
BEGIN
  -- Registrar instância na tabela canônica zapp.instance_registry.
  -- DB-03: o corpo antigo apontava para evo.instance_registry (inexistente),
  -- o que fazia a chamada falhar com "relation evo.instance_registry does not exist".
  INSERT INTO zapp.instance_registry (instance_name, display_name, phone_number, department, responsible_name)
  VALUES (p_instance_name, p_display_name, p_phone, p_department, p_responsible)
  RETURNING id INTO v_id;

  -- Criar partições automaticamente (somente parents LIST por instance_name)
  v_part_msgs := 'evolution_messages_'       || replace(p_instance_name, '-', '_');
  v_part_conv := 'evolution_conversations_'  || replace(p_instance_name, '-', '_');

  EXECUTE format(
    'CREATE TABLE IF NOT EXISTS evo.%I PARTITION OF evo.evolution_messages FOR VALUES IN (%L)',
    v_part_msgs, p_instance_name
  );
  EXECUTE format(
    'CREATE TABLE IF NOT EXISTS evo.%I PARTITION OF evo.evolution_conversations FOR VALUES IN (%L)',
    v_part_conv, p_instance_name
  );

  -- Webhook events: NÃO criar partição aqui (DB-03).
  -- O step antigo apontava para evo.evolution_webhook_events (tabela inexistente).
  -- A tabela real é evo.evolution_webhook_events_v2, particionada por
  -- RANGE (created_at) — PARTITION OF ... FOR VALUES IN (...) é inválido para
  -- parent RANGE. As partições mensais de _v2 são gerenciadas pelo cron
  -- "auto-create-monthly-partitions" (cron.job jobid=64 ->
  -- evo.fn_auto_create_next_partitions()), que cria as partições do mês
  -- seguinte e do mês subsequente. Nada a fazer aqui.

  -- Índices nas novas partições de mensagens
  EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_rjid     ON evo.%I(remote_jid)',        replace(p_instance_name,'-','_'), v_part_msgs);
  EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_created  ON evo.%I(created_at DESC)',   replace(p_instance_name,'-','_'), v_part_msgs);
  EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_jid_act  ON evo.%I(remote_jid, created_at DESC) WHERE deleted_at IS NULL', replace(p_instance_name,'-','_'), v_part_msgs);

  -- RLS nas 2 partições filhas criadas
  EXECUTE format('ALTER TABLE evo.%I ENABLE ROW LEVEL SECURITY', v_part_msgs);
  EXECUTE format('ALTER TABLE evo.%I ENABLE ROW LEVEL SECURITY', v_part_conv);

  -- Policy: service_role apenas (não TO PUBLIC!)
  EXECUTE format('CREATE POLICY service_role_full_access ON evo.%I FOR ALL TO service_role USING (true) WITH CHECK (true)', v_part_msgs);
  EXECUTE format('CREATE POLICY service_role_full_access ON evo.%I FOR ALL TO service_role USING (true) WITH CHECK (true)', v_part_conv);

  -- Policy: authenticated com acesso operacional
  EXECUTE format('CREATE POLICY auth_full_access ON evo.%I FOR ALL TO authenticated USING (true) WITH CHECK (true)', v_part_msgs);
  EXECUTE format('CREATE POLICY auth_full_access ON evo.%I FOR ALL TO authenticated USING (true) WITH CHECK (true)', v_part_conv);

  RETURN v_id;
END;
$$;


--
-- Name: fn_register_sticky_assignment(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_register_sticky_assignment(p_contact_id uuid, p_agent_profile_id uuid, p_channel_connection_id uuid DEFAULT NULL::uuid, p_queue_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_id uuid;
BEGIN
  INSERT INTO zapp.sticky_assignments
    (contact_id, channel_connection_id, agent_profile_id, queue_id, last_assigned_at, expires_at)
  VALUES
    (p_contact_id, p_channel_connection_id, p_agent_profile_id, p_queue_id, now(), now() + interval '24 hours')
  ON CONFLICT (contact_id, channel_connection_id) DO UPDATE
    SET agent_profile_id = EXCLUDED.agent_profile_id,
        queue_id = EXCLUDED.queue_id,
        last_assigned_at = now(),
        expires_at = now() + interval '24 hours'
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: fn_reject_oversized_media(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_reject_oversized_media() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- 64 MB = 67,108,864 bytes — WhatsApp hard limit
  IF NEW.file_length IS NOT NULL AND NEW.file_length > 67108864 THEN
    NEW.status := 'oversized';
    NEW.error_message := format(
      'E2-12: file_length %s bytes exceeds WhatsApp 64 MB limit — skipped R2 upload',
      NEW.file_length
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_release_quarantine(uuid, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_release_quarantine(p_quarantine_id uuid, p_reviewed_by text DEFAULT 'admin'::text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_q RECORD;
BEGIN
  SELECT * INTO v_q FROM media_quarantine WHERE id = p_quarantine_id;
  IF v_q IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'quarantine record not found');
  END IF;
  UPDATE media_quarantine SET reviewed = true, reviewed_by = p_reviewed_by, reviewed_at = now(), released = true, released_at = now() WHERE id = p_quarantine_id;
  INSERT INTO media_scan_log (message_id, instance_name, scan_type, scan_result, details) VALUES (v_q.message_id, v_q.instance_name, 'manual_review', 'clean', 'Released by ' || p_reviewed_by || '. Original reason: ' || v_q.block_reason);
  RETURN jsonb_build_object('ok', true, 'released', true, 'message_id', v_q.message_id, 'block_reason', v_q.block_reason);
END;
$$;


--
-- Name: fn_replay_failed_webhooks(interval); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_replay_failed_webhooks(p_since interval DEFAULT '24:00:00'::interval) RETURNS TABLE(event_id uuid, event_type text, remote_jid text)
    LANGUAGE plpgsql
    AS $$ BEGIN RETURN QUERY UPDATE zapp.evolution_webhook_events SET processed = false, processed_at = NULL, error_message = NULL WHERE error_message IS NOT NULL AND created_at >= now() - p_since RETURNING id, evolution_webhook_events.event_type, evolution_webhook_events.remote_jid; END $$;


--
-- Name: fn_replay_webhook_event(uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_replay_webhook_event(p_event_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$ DECLARE v_event record; v_result jsonb; BEGIN SELECT * INTO v_event FROM zapp.evolution_webhook_events WHERE id = p_event_id; IF v_event IS NULL THEN RETURN jsonb_build_object('status', 'error', 'message', 'event_id not found'); END IF; UPDATE zapp.evolution_webhook_events SET processed = false, processed_at = NULL, error_message = NULL WHERE id = p_event_id; v_result := jsonb_build_object('status', 'queued_for_replay', 'event_id', p_event_id, 'event_type', v_event.event_type, 'remote_jid', v_event.remote_jid, 'original_error', v_event.error_message, 'original_created', v_event.created_at); INSERT INTO zapp.migration_audit (phase, entity, action, rows_affected, status, notes) VALUES ('operacional', 'webhook_events', 'replay', 1, 'success', format('Event %s re-queued. Original error: %s', p_event_id, COALESCE(v_event.error_message, 'none'))); RETURN v_result; END $$;


--
-- Name: fn_reprocess_instance_webhook_events(text, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_reprocess_instance_webhook_events(p_instance_name text DEFAULT 'wpp2'::text, p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'pg_temp'
    AS $_$
DECLARE
  v_table  text;
  v_sql    text;
  v_rec    RECORD;
  v_ok     int := 0;
  v_fail   int := 0;
  v_skip   int := 0;
  v_stats  jsonb := '{}'::jsonb;
BEGIN
  v_table := 'evolution_webhook_events_' || lower(regexp_replace(p_instance_name, '[^a-z0-9_]', '_', 'g'));

  IF NOT EXISTS (
    SELECT 1 FROM information_schema.tables 
    WHERE table_schema='evo' AND table_name=v_table
  ) THEN
    RETURN jsonb_build_object('error', 'Tabela nao encontrada: ' || v_table, 'instance', p_instance_name);
  END IF;

  v_sql := format(
    'SELECT id, event_type, instance_name, payload FROM evo.%I
     WHERE status = ''pending''::zapp.webhook_event_status
       AND created_at < NOW() - interval ''30 seconds''
     ORDER BY created_at
     LIMIT %s',
    v_table, p_limit
  );

  FOR v_rec IN EXECUTE v_sql LOOP
    BEGIN
      IF v_rec.event_type IN ('contacts.upsert','contacts.update','CONTACTS_UPSERT','CONTACTS_UPDATE') THEN
        PERFORM zapp.fn_process_contacts_batch(v_rec.payload, COALESCE(v_rec.instance_name, p_instance_name));
        v_stats := v_stats || jsonb_build_object('contacts', COALESCE((v_stats->>'contacts')::int,0)+1);

      ELSIF v_rec.event_type IN ('messages.upsert','MESSAGES_UPSERT') THEN
        PERFORM zapp.fn_process_whatsapp_message(v_rec.payload, COALESCE(v_rec.instance_name, p_instance_name));
        v_stats := v_stats || jsonb_build_object('messages_upsert', COALESCE((v_stats->>'messages_upsert')::int,0)+1);

      ELSIF v_rec.event_type IN ('messages.edited','MESSAGES_EDITED') THEN
        PERFORM zapp.fn_process_message_edited(v_rec.payload, COALESCE(v_rec.instance_name, p_instance_name));
        v_stats := v_stats || jsonb_build_object('messages_edited', COALESCE((v_stats->>'messages_edited')::int,0)+1);

      ELSIF v_rec.event_type IN ('chats.update','CHATS_UPDATE') THEN
        PERFORM zapp.fn_process_chat_update(v_rec.payload, COALESCE(v_rec.instance_name, p_instance_name));
        v_stats := v_stats || jsonb_build_object('chats_update', COALESCE((v_stats->>'chats_update')::int,0)+1);

      ELSE
        EXECUTE format(
          'UPDATE evo.%I SET status=''skipped'', processed_at=NOW(),
           error_message=''sem handler para event_type: '' || $1 WHERE id=$2',
          v_table
        ) USING v_rec.event_type, v_rec.id;
        v_skip := v_skip + 1;
        CONTINUE;
      END IF;

      EXECUTE format(
        'UPDATE evo.%I SET status=''success'', processed_at=NOW(), error_message=NULL WHERE id=$1',
        v_table
      ) USING v_rec.id;
      v_ok := v_ok + 1;

    EXCEPTION WHEN OTHERS THEN
      EXECUTE format(
        'UPDATE evo.%I SET status=''failed'', error_message=$1 WHERE id=$2',
        v_table
      ) USING SQLERRM, v_rec.id;
      v_fail := v_fail + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'instance',    p_instance_name,
    'table',       v_table,
    'ok',          v_ok,
    'failed',      v_fail,
    'skipped',     v_skip,
    'distribution',v_stats,
    'processed_at',now()
  );
END;
$_$;


--
-- Name: fn_reprocess_pending_webhook_events(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_reprocess_pending_webhook_events(p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
DECLARE
  e RECORD;
  v_ok int := 0;
  v_fail int := 0;
  v_stats jsonb := '{}'::jsonb;
  v_action_count int;
BEGIN
  FOR e IN
    SELECT id, event_type, instance_name, payload, retry_count
    FROM evo.evolution_webhook_events_v2   -- FIX: usar tabela v2
    WHERE status IN ('pending', 'failed')
      AND created_at < NOW() - INTERVAL '30 seconds'  -- deixa o consumer processar primeiro
      AND retry_count < 5                             -- não reprocessar infinitamente
    ORDER BY created_at
    LIMIT p_limit
  LOOP
    BEGIN
      IF e.event_type IN ('contacts.upsert','contacts.update','CONTACTS_UPSERT','CONTACTS_UPDATE') THEN
        PERFORM zapp.fn_process_contacts_batch(e.payload, COALESCE(e.instance_name, 'wpp2'));
        v_action_count := COALESCE((v_stats->>'contacts')::int, 0) + 1;
        v_stats := v_stats || jsonb_build_object('contacts', v_action_count);

      ELSIF e.event_type IN ('messages.edited','MESSAGES_EDITED') THEN
        PERFORM zapp.fn_process_message_edited(e.payload, COALESCE(e.instance_name, 'wpp2'));
        v_action_count := COALESCE((v_stats->>'messages_edited')::int, 0) + 1;
        v_stats := v_stats || jsonb_build_object('messages_edited', v_action_count);

      ELSIF e.event_type IN ('chats.update','CHATS_UPDATE') THEN
        PERFORM zapp.fn_process_chat_update(e.payload, COALESCE(e.instance_name, 'wpp2'));
        v_action_count := COALESCE((v_stats->>'chats_update')::int, 0) + 1;
        v_stats := v_stats || jsonb_build_object('chats_update', v_action_count);

      ELSIF e.event_type IN ('messages.upsert','MESSAGES_UPSERT') THEN
        PERFORM zapp.fn_process_whatsapp_message(e.payload, COALESCE(e.instance_name, 'wpp2'));
        v_action_count := COALESCE((v_stats->>'messages_upsert')::int, 0) + 1;
        v_stats := v_stats || jsonb_build_object('messages_upsert', v_action_count);

      ELSE
        v_action_count := COALESCE((v_stats->>'skipped_no_handler')::int, 0) + 1;
        v_stats := v_stats || jsonb_build_object('skipped_no_handler', v_action_count);
      END IF;

      -- FIX: atualizar status (text) + processed (boolean) na v2
      UPDATE evo.evolution_webhook_events_v2
      SET processed = true, processed_at = NOW(), error_message = NULL, status = 'processed'
      WHERE id = e.id;
      v_ok := v_ok + 1;

    EXCEPTION WHEN OTHERS THEN
      -- Incrementar retry_count; mover para dead_letter se >= 5 tentativas
      UPDATE evo.evolution_webhook_events_v2
      SET
        error_message = SQLERRM,
        retry_count = COALESCE(retry_count, 0) + 1,
        status = CASE WHEN COALESCE(retry_count, 0) + 1 >= 5 THEN 'dead_letter' ELSE 'failed' END
      WHERE id = e.id;
      v_fail := v_fail + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', v_ok,
    'failed', v_fail,
    'distribution', v_stats,
    'source_table', 'evolution_webhook_events_v2',
    'timestamp', NOW()
  );
END;
$$;


--
-- Name: fn_require_app_user(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_require_app_user() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM zapp.profiles WHERE user_id = auth.uid())
       OR NOT EXISTS (SELECT 1 FROM zapp.user_roles WHERE user_id = auth.uid())
       AND NOT EXISTS (SELECT 1 FROM zapp.workspace_members WHERE user_id = auth.uid()) THEN
      RAISE EXCEPTION 'forbidden: app member required' USING ERRCODE = '42501';
    END IF;
  END IF;
END;
$$;


--
-- Name: fn_resolve_agent_for_routing(uuid, uuid, uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_resolve_agent_for_routing(p_contact_id uuid, p_channel_connection_id uuid DEFAULT NULL::uuid, p_queue_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_agent_id uuid;
  v_resolved_queue uuid;
  v_strategy text;
  v_required_skills text[];
BEGIN
  -- 1) Sticky: último agente do contato neste canal, ainda válido e ativo
  SELECT s.agent_profile_id, s.queue_id
    INTO v_agent_id, v_resolved_queue
  FROM zapp.sticky_assignments s
  JOIN zapp.profiles p ON p.id = s.agent_profile_id
  WHERE s.contact_id = p_contact_id
    AND (p_channel_connection_id IS NULL OR s.channel_connection_id = p_channel_connection_id)
    AND s.expires_at > now()
    AND p.is_active = true
  ORDER BY s.last_assigned_at DESC
  LIMIT 1;

  IF v_agent_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'agent_profile_id', v_agent_id,
      'queue_id', v_resolved_queue,
      'strategy', 'sticky'
    );
  END IF;

  -- 2) Resolver fila: parâmetro > regra de roteamento do canal
  v_resolved_queue := p_queue_id;

  IF v_resolved_queue IS NULL AND p_channel_connection_id IS NOT NULL THEN
    SELECT queue_id INTO v_resolved_queue
    FROM zapp.channel_routing_rules
    WHERE channel_connection_id = p_channel_connection_id
      AND queue_id IS NOT NULL
    ORDER BY priority DESC
    LIMIT 1;
  END IF;

  IF v_resolved_queue IS NULL THEN
    RETURN jsonb_build_object(
      'agent_profile_id', NULL,
      'queue_id', NULL,
      'strategy', 'unassigned',
      'reason', 'no_queue_resolved'
    );
  END IF;

  -- 3) Skills exigidas pela fila
  SELECT COALESCE(array_agg(skill_name), ARRAY[]::text[])
    INTO v_required_skills
  FROM zapp.queue_skill_requirements
  WHERE queue_id = v_resolved_queue;

  -- 4) Round-robin: agente da fila com menos atribuições nas últimas 24h, com skills
  SELECT qm.profile_id INTO v_agent_id
  FROM zapp.queue_members qm
  JOIN zapp.profiles p ON p.id = qm.profile_id
  WHERE qm.queue_id = v_resolved_queue
    AND qm.is_active = true
    AND p.is_active = true
    AND (
      array_length(v_required_skills, 1) IS NULL
      OR NOT EXISTS (
        SELECT 1 FROM unnest(v_required_skills) rs(name)
        WHERE NOT EXISTS (
          SELECT 1 FROM zapp.agent_skills s
          WHERE s.profile_id = qm.profile_id AND s.skill_name = rs.name
        )
      )
    )
  ORDER BY (
    SELECT COUNT(*) FROM zapp.sticky_assignments sa
    WHERE sa.agent_profile_id = qm.profile_id
      AND sa.last_assigned_at > now() - interval '24 hours'
  ) ASC, random()
  LIMIT 1;

  IF v_agent_id IS NULL THEN
    RETURN jsonb_build_object(
      'agent_profile_id', NULL,
      'queue_id', v_resolved_queue,
      'strategy', 'unassigned',
      'reason', 'no_eligible_agent'
    );
  END IF;

  RETURN jsonb_build_object(
    'agent_profile_id', v_agent_id,
    'queue_id', v_resolved_queue,
    'strategy', 'round_robin'
  );
END;
$$;


--
-- Name: fn_resolve_alerts_by_type(text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_resolve_alerts_by_type(p_alert_type text, p_resolved_by text DEFAULT 'system'::text) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE v_count integer;
BEGIN
    UPDATE evolution_alerts SET acknowledged=true, acknowledged_at=NOW(), acknowledged_by=p_resolved_by, resolved_at=NOW(), resolved_by=p_resolved_by WHERE alert_type=p_alert_type AND acknowledged=false;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$;


--
-- Name: fn_response_time_analysis(text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_response_time_analysis(p_instance text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE v jsonb;
BEGIN SELECT jsonb_build_object('avg_response_minutes',(SELECT round(avg(EXTRACT(EPOCH FROM (last_outbound_at-last_inbound_at))/60)::numeric,1) FROM evolution_conversations WHERE last_inbound_at IS NOT NULL AND last_outbound_at IS NOT NULL AND last_outbound_at>last_inbound_at AND (p_instance IS NULL OR instance_name=p_instance)),'total_conversations',(SELECT count(*) FROM evolution_conversations WHERE (p_instance IS NULL OR instance_name=p_instance))) INTO v; RETURN v; END; $$;


--
-- Name: fn_restore_integrity_check(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_restore_integrity_check() RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_run_id      uuid        := gen_random_uuid();
  v_start       timestamptz := now();
  v_result      jsonb       := '{}';
  v_pass        int         := 0;
  v_fail        int         := 0;
  v_warn        int         := 0;
  v_overall     text;
  v_n           bigint;
  v_backup_age  numeric;
  v_backup_file text;
  v_detail      text;
  v_status      text;
  v_fn_name     text;
  v_fn_exists   boolean;
  v_row_exists  boolean;
  v_default_part text;
  v_default_rows bigint;

  v_critical_functions text[] := ARRAY[
    'fn_process_webhook_event',
    'fn_process_whatsapp_message',
    'fn_cache_warmup_after_vacuum',
    'fn_purge_api_key_from_logs',
    'fn_gc_deleted_messages',
    'fn_zapp_web_smoke_test_v2'
  ];
BEGIN

  BEGIN
    SELECT EXTRACT(EPOCH FROM (now() - last_backup_at)) / 3600, last_backup_file
    INTO v_backup_age, v_backup_file
    FROM ops.backup_sentinel ORDER BY last_backup_at DESC LIMIT 1;
    IF v_backup_age IS NULL THEN
      v_status := 'FAIL'; v_fail := v_fail + 1;
      v_detail := 'ops.backup_sentinel is empty — no backup record found';
    ELSIF v_backup_age > 26 THEN
      v_status := 'FAIL'; v_fail := v_fail + 1;
      v_detail := format('last backup %sh ago (file: %s) — exceeds 26h threshold', v_backup_age, v_backup_file);
    ELSE
      v_status := 'PASS'; v_pass := v_pass + 1;
      v_detail := format('last backup %sh ago — file: %s', v_backup_age, v_backup_file);
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_status := 'FAIL'; v_fail := v_fail + 1;
    v_detail := 'ops.backup_sentinel inaccessible: ' || SQLERRM;
  END;
  INSERT INTO zapp.restore_test_log (run_id, step, status, detail) VALUES (v_run_id, '1_backup_sentinel_freshness', v_status, v_detail);
  v_result := v_result || jsonb_build_object('1_backup_sentinel', jsonb_build_object('status', v_status, 'detail', v_detail));

  BEGIN
    SELECT EXISTS (SELECT 1 FROM evo.evolution_messages LIMIT 1) INTO v_row_exists;
    v_status := 'PASS'; v_pass := v_pass + 1;
    v_detail := 'evo.evolution_messages readable';
  EXCEPTION WHEN OTHERS THEN
    v_status := 'FAIL'; v_fail := v_fail + 1;
    v_detail := 'evo.evolution_messages inaccessible: ' || SQLERRM;
  END;
  INSERT INTO zapp.restore_test_log (run_id, step, status, detail) VALUES (v_run_id, '2_messages_wpp2_access', v_status, v_detail);
  v_result := v_result || jsonb_build_object('2_messages_wpp2', jsonb_build_object('status', v_status, 'detail', v_detail));

  BEGIN
    SELECT COUNT(*) INTO v_n FROM zapp.evolution_contacts WHERE deleted_at IS NULL;
    IF v_n < 1000 THEN
      v_status := 'WARN'; v_warn := v_warn + 1;
      v_detail := format('evolution_contacts has only %s active rows (expected ≥ 1000)', v_n);
    ELSE
      v_status := 'PASS'; v_pass := v_pass + 1;
      v_detail := format('evolution_contacts: %s active rows', v_n);
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_status := 'FAIL'; v_fail := v_fail + 1;
    v_detail := 'zapp.evolution_contacts inaccessible: ' || SQLERRM;
  END;
  INSERT INTO zapp.restore_test_log (run_id, step, status, detail) VALUES (v_run_id, '3_contacts_row_count', v_status, v_detail);
  v_result := v_result || jsonb_build_object('3_contacts', jsonb_build_object('status', v_status, 'detail', v_detail));

  BEGIN
    SELECT COUNT(*) INTO v_n FROM pg_class c
    WHERE c.relispartition = true
      AND c.relnamespace = 'evo'::regnamespace
      AND c.oid IN (
        SELECT inhrelid FROM pg_inherits
        WHERE inhparent = 'evo.evolution_webhook_events_v2'::regclass
      )
      AND c.relname NOT LIKE '%\_default';

    IF v_n < 7 THEN
      v_status := 'FAIL'; v_fail := v_fail + 1;
      v_detail := format('only %s non-default partitions found — expected ≥ 7 (mês atual + 6 futuros)', v_n);
    ELSE
      v_status := 'PASS'; v_pass := v_pass + 1;
      v_detail := format('%s non-default partitions present (default ignorada no baseline)', v_n);
    END IF;

    SELECT c.relname INTO v_default_part
    FROM pg_class c
    JOIN pg_inherits i ON i.inhrelid = c.oid
    WHERE i.inhparent = 'evo.evolution_webhook_events_v2'::regclass
      AND c.relname LIKE '%\_default'
    LIMIT 1;

    IF v_default_part IS NOT NULL THEN
      EXECUTE format('SELECT count(*) FROM evo.%I', v_default_part) INTO v_default_rows;
      IF v_default_rows > 0 THEN
        v_status := 'WARN'; v_warn := v_warn + 1;
        v_detail := format('default partition %s has %s rows (dados fora do range de partições!)', v_default_part, v_default_rows);
      END IF;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_status := 'FAIL'; v_fail := v_fail + 1;
    v_detail := 'partition count check failed: ' || SQLERRM;
  END;
  INSERT INTO zapp.restore_test_log (run_id, step, status, detail) VALUES (v_run_id, '4_partition_count', v_status, v_detail);
  v_result := v_result || jsonb_build_object('4_partitions', jsonb_build_object('status', v_status, 'detail', v_detail));

  BEGIN
    SELECT COUNT(*) INTO v_n
    FROM pg_index ix JOIN pg_class c ON c.oid = ix.indexrelid JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname IN ('public', 'evo', 'zapp') AND NOT ix.indisvalid;
    IF v_n > 0 THEN
      v_status := 'FAIL'; v_fail := v_fail + 1;
      v_detail := format('%s invalid index(es) found in public/evo/zapp — REINDEX required', v_n);
    ELSE
      v_status := 'PASS'; v_pass := v_pass + 1;
      v_detail := 'all indexes in public/evo/zapp are valid';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_status := 'FAIL'; v_fail := v_fail + 1;
    v_detail := 'invalid index check failed: ' || SQLERRM;
  END;
  INSERT INTO zapp.restore_test_log (run_id, step, status, detail) VALUES (v_run_id, '5_invalid_indexes', v_status, v_detail);
  v_result := v_result || jsonb_build_object('5_invalid_indexes', jsonb_build_object('status', v_status, 'detail', v_detail));

  BEGIN
    v_detail := ''; v_status := 'PASS';
    FOREACH v_fn_name IN ARRAY v_critical_functions LOOP
      SELECT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
                     WHERE n.nspname IN ('public', 'evo', 'zapp') AND p.proname = v_fn_name) INTO v_fn_exists;
      IF NOT v_fn_exists THEN v_status := 'FAIL'; v_detail := v_detail || v_fn_name || ' MISSING; '; END IF;
    END LOOP;
    IF v_status = 'PASS' THEN v_pass := v_pass + 1; v_detail := 'all 6 critical functions present: ' || array_to_string(v_critical_functions, ', ');
    ELSE v_fail := v_fail + 1; END IF;
  EXCEPTION WHEN OTHERS THEN v_status := 'FAIL'; v_fail := v_fail + 1; v_detail := 'critical function check failed: ' || SQLERRM; END;
  INSERT INTO zapp.restore_test_log (run_id, step, status, detail) VALUES (v_run_id, '6_critical_functions', v_status, v_detail);
  v_result := v_result || jsonb_build_object('6_critical_functions', jsonb_build_object('status', v_status, 'detail', v_detail));

  BEGIN
    SELECT COUNT(*) INTO v_n FROM information_schema.tables
    WHERE table_schema IN ('public', 'evo', 'zapp', 'archive', 'ops') AND table_type = 'BASE TABLE';
    IF v_n < 500 THEN
      v_status := 'FAIL'; v_fail := v_fail + 1;
      v_detail := format('only %s tables found — expected ≥ 500 (baseline: 681)', v_n);
    ELSE
      v_status := 'PASS'; v_pass := v_pass + 1;
      v_detail := format('%s tables present across public/evo/zapp/archive/ops', v_n);
    END IF;
  EXCEPTION WHEN OTHERS THEN v_status := 'FAIL'; v_fail := v_fail + 1; v_detail := 'table count check failed: ' || SQLERRM; END;
  INSERT INTO zapp.restore_test_log (run_id, step, status, detail) VALUES (v_run_id, '7_table_count_sanity', v_status, v_detail);
  v_result := v_result || jsonb_build_object('7_table_count', jsonb_build_object('status', v_status, 'detail', v_detail));

  v_overall := CASE WHEN v_fail > 0 THEN 'FAIL' WHEN v_warn > 0 THEN 'WARN' ELSE 'PASS' END;
  INSERT INTO zapp.restore_test_log (run_id, step, status, detail)
  VALUES (v_run_id, 'SUMMARY', v_overall,
    format('pass=%s warn=%s fail=%s duration_ms=%s', v_pass, v_warn, v_fail,
           ROUND(EXTRACT(EPOCH FROM (now() - v_start)) * 1000)));

  IF v_overall = 'FAIL' THEN
    BEGIN
      INSERT INTO zapp.webhook_health_alerts (alert_type, severity, title, details, created_at)
      VALUES ('restore_integrity_fail', 'critical',
        format('E9-05: fn_restore_integrity_check FAIL — %s check(s) failed. run_id=%s', v_fail, v_run_id),
        jsonb_build_object('run_id', v_run_id, 'pass', v_pass, 'warn', v_warn, 'fail', v_fail, 'detail', v_result),
        now());
    EXCEPTION WHEN OTHERS THEN NULL; END;
  END IF;

  RETURN jsonb_build_object(
    'run_id', v_run_id, 'checked_at', v_start,
    'duration_ms', ROUND(EXTRACT(EPOCH FROM (now() - v_start)) * 1000),
    'overall', v_overall, 'pass', v_pass, 'warn', v_warn, 'fail', v_fail, 'checks', v_result
  );
END;
$$;


--
-- Name: FUNCTION fn_restore_integrity_check(); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_restore_integrity_check() IS 'E9-05: Daily restore-integrity probe. Validates backup freshness, table accessibility, partition count, index validity, critical function presence, RLS enforcement, and table count sanity. Writes per-step results to public.restore_test_log and raises a webhook_health_alert on any FAIL. Scheduled daily at 11:00 UTC (after backup window).';


--
-- Name: fn_retention_audit_tables(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_retention_audit_tables() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'archive', 'zapp', 'evo', 'pg_temp'
    AS $$
DECLARE v_r jsonb := '{}'; v_c bigint;
BEGIN
  BEGIN DELETE FROM archive.audit_dump_chunks WHERE created_at < now() - interval '90 days'; GET DIAGNOSTICS v_c = ROW_COUNT; v_r := v_r || jsonb_build_object('audit_dump', v_c); EXCEPTION WHEN OTHERS THEN NULL; END;
  BEGIN DELETE FROM zapp.audit_log_tables WHERE created_at < now() - interval '90 days'; GET DIAGNOSTICS v_c = ROW_COUNT; v_r := v_r || jsonb_build_object('audit_log_tables', v_c); EXCEPTION WHEN OTHERS THEN NULL; END;
  RETURN v_r;
END;
$$;


--
-- Name: fn_retention_cleanup(integer, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_retention_cleanup(p_processed_days integer DEFAULT 7, p_unprocessed_days integer DEFAULT 30) RETURNS TABLE(deleted_processed bigint, deleted_unprocessed bigint, freed_bytes text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_del_proc bigint; v_del_unproc bigint; v_size_before bigint; v_size_after bigint;
BEGIN
  v_size_before := pg_total_relation_size('evolution_webhook_events');
  DELETE FROM evolution_webhook_events WHERE processed=true AND created_at < NOW()-make_interval(days=>p_processed_days);
  GET DIAGNOSTICS v_del_proc = ROW_COUNT;
  DELETE FROM evolution_webhook_events WHERE processed=false AND created_at < NOW()-make_interval(days=>p_unprocessed_days);
  GET DIAGNOSTICS v_del_unproc = ROW_COUNT;
  v_size_after := pg_total_relation_size('evolution_webhook_events');
  INSERT INTO evolution_retention_log (processed_days_kept,unprocessed_days_kept,deleted_processed,deleted_unprocessed,freed_bytes_pretty,freed_bytes_raw,duration_ms,triggered_by)
  VALUES (p_processed_days,p_unprocessed_days,v_del_proc,v_del_unproc,pg_size_pretty(v_size_before-v_size_after),v_size_before-v_size_after,0,'manual');
  RETURN QUERY SELECT v_del_proc, v_del_unproc, pg_size_pretty(v_size_before-v_size_after);
END $$;


--
-- Name: fn_retention_mirror_media(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_retention_mirror_media() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_c integer;
BEGIN
  DELETE FROM zapp.evolution_mirror_media_queue WHERE status = 'uploaded' AND created_at < now() - interval '30 days';
  GET DIAGNOSTICS v_c = ROW_COUNT;
  RETURN v_c;
END;
$$;


--
-- Name: fn_retention_old_alerts(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_retention_old_alerts() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_total integer := 0; v_tmp integer;
BEGIN
  DELETE FROM zapp.evolution_alerts 
  WHERE resolved_at IS NOT NULL AND resolved_at < now() - interval '60 days';
  GET DIAGNOSTICS v_tmp = ROW_COUNT;
  v_total := v_total + v_tmp;
  
  DELETE FROM zapp.evolution_alerts 
  WHERE acknowledged = true AND created_at < now() - interval '90 days';
  GET DIAGNOSTICS v_tmp = ROW_COUNT;
  v_total := v_total + v_tmp;
  
  RETURN v_total;
END;
$$;


--
-- Name: fn_retention_webhook_events(integer, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_retention_webhook_events(p_proc_days integer DEFAULT 30, p_unproc_days integer DEFAULT 90) RETURNS TABLE(deleted_processed bigint, deleted_unprocessed bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_proc bigint:=0; v_unproc bigint:=0;
BEGIN
  DELETE FROM evolution_webhook_events WHERE processed=true AND created_at<now()-(p_proc_days||' days')::interval; GET DIAGNOSTICS v_proc=ROW_COUNT;
  DELETE FROM evolution_webhook_events WHERE processed=false AND created_at<now()-(p_unproc_days||' days')::interval; GET DIAGNOSTICS v_unproc=ROW_COUNT;
  RETURN QUERY SELECT v_proc, v_unproc;
END; $$;


--
-- Name: fn_retention_webhook_events_aggressive(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_retention_webhook_events_aggressive() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_total bigint := 0; v_tmp bigint;
BEGIN
  DELETE FROM zapp.evolution_webhook_events 
  WHERE processed = true AND created_at < now() - interval '14 days';
  GET DIAGNOSTICS v_tmp = ROW_COUNT;
  v_total := v_total + v_tmp;
  
  DELETE FROM zapp.evolution_webhook_events 
  WHERE created_at < now() - interval '30 days';
  GET DIAGNOSTICS v_tmp = ROW_COUNT;
  v_total := v_total + v_tmp;
  
  RETURN v_total;
END;
$$;


--
-- Name: fn_retry_dlq_events(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_retry_dlq_events() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_count INTEGER := 0;
BEGIN
  UPDATE evolution_webhook_dlq
  SET status = 'retrying',
      retry_count = retry_count + 1,
      next_retry_at = CASE 
        WHEN retry_count >= max_retries - 1 THEN NULL
        ELSE NOW() + (INTERVAL '5 minutes' * (retry_count + 1))
      END
  WHERE status IN ('pending', 'retrying')
    AND next_retry_at <= NOW()
    AND retry_count < max_retries;
  
  GET DIAGNOSTICS v_count = ROW_COUNT;
  
  UPDATE evolution_webhook_dlq
  SET status = 'failed'
  WHERE status = 'retrying' AND retry_count >= max_retries;
  
  RETURN v_count;
END;
$$;


--
-- Name: fn_retry_stuck_media_queue(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_retry_stuck_media_queue() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  retried_count integer;
BEGIN
  -- 1) Requeue: processing com timeout e ainda com retries disponiveis -> pending
  UPDATE zapp.media_download_queue
  SET status = 'pending', retry_count = retry_count + 1,
      error_message = 'Timeout - stuck in processing'
  WHERE status = 'processing'
    AND processed_at < now() - interval '10 minutes'
    AND retry_count < max_retries;
  GET DIAGNOSTICS retried_count = ROW_COUNT;

  -- 2) Falha definitiva: processing que esgotou todas as retries
  UPDATE zapp.media_download_queue
  SET status = 'failed', error_message = 'Max retries exceeded after timeout'
  WHERE status = 'processing'
    AND processed_at < now() - interval '10 minutes'
    AND retry_count >= max_retries;

  -- 3) Safety net: pending orfaos com retry esgotado e antigos o suficiente
  --    (nao afeta itens recem-requeueados pela clausula 1)
  UPDATE zapp.media_download_queue
  SET status = 'failed', error_message = 'Max retries exceeded after timeout'
  WHERE status = 'pending'
    AND retry_count >= max_retries
    AND (processed_at IS NULL OR processed_at < now() - interval '20 minutes');

  RETURN retried_count;
END;
$$;


--
-- Name: fn_retry_stuck_messages(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_retry_stuck_messages() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp, evo, pg_temp'
    AS $$
DECLARE
  v_count         INTEGER := 0;
  v_failed_count  INTEGER := 0;
  r               RECORD;
  v_has_enq       BOOLEAN;
BEGIN
  -- ── Fase 1: Transicionar para 'failed' mensagens que esgotaram os retries ──
  UPDATE evo.evolution_messages
     SET status     = 'failed',
         updated_at = NOW()
   WHERE status        = 'pending'
     AND updated_at    < NOW() - INTERVAL '10 minutes'
     AND retry_attempt >= 3;

  GET DIAGNOSTICS v_failed_count = ROW_COUNT;

  IF v_failed_count > 0 THEN
    RAISE NOTICE '[fn_retry_stuck_messages] % mensagem(ns) transicionada(s) para failed (retry_attempt >= 3)',
      v_failed_count;
  END IF;

  -- ── Fase 2: Verificar existência de fn_enqueue_message_dispatch ───────────
  SELECT EXISTS (
    SELECT 1 FROM pg_catalog.pg_proc p
    JOIN pg_catalog.pg_namespace n ON n.oid = p.pronamespace
   WHERE n.nspname = 'zapp' AND p.proname = 'fn_enqueue_message_dispatch'
  ) INTO v_has_enq;

  -- ── Fase 3: Retry mensagens ainda elegíveis (retry_attempt < 3) ──────────
  FOR r IN
    SELECT id, instance_name, remote_jid,
           COALESCE(retry_attempt, 0) AS attempt
      FROM evo.evolution_messages
     WHERE status        = 'pending'
       AND updated_at    < NOW() - INTERVAL '10 minutes'
       AND (retry_attempt IS NULL OR retry_attempt < 3)
     ORDER BY updated_at
     LIMIT 100
     FOR UPDATE SKIP LOCKED
  LOOP
    BEGIN
      UPDATE evo.evolution_messages
         SET retry_attempt = r.attempt + 1,
             updated_at    = NOW(),
             status        = 'pending'
       WHERE id = r.id;

      IF v_has_enq THEN
        PERFORM zapp.fn_enqueue_message_dispatch(r.id, r.instance_name);
      END IF;

      v_count := v_count + 1;

    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING '[fn_retry_stuck_messages] falha ao retentar mensagem id=%: %',
        r.id, SQLERRM;
    END;
  END LOOP;

  RETURN v_count;
END;
$$;


--
-- Name: FUNCTION fn_retry_stuck_messages(); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_retry_stuck_messages() IS 'Cron a cada 10min. Fase 1: marca como failed mensagens pending com retry_attempt>=3 (estado terminal). Fase 2: verifica existência de zapp.fn_enqueue_message_dispatch via pg_proc. Fase 3: retenta mensagens ainda elegíveis (retry_attempt<3), chamando fn_enqueue_message_dispatch se disponível. FIX P2 (2026-08-06, GAP-OPERACIONAL): fase de auto-fail adicionada. FIX G1 (2026-08-06): search_path corrigido (sem aspas simples envolvendo schemas).';


--
-- Name: fn_return_transfer(uuid, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_return_transfer(p_transfer_id uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
BEGIN
    UPDATE zapp.conversation_transfers SET status = 'returned', resolution_notes = p_reason, resolution_type = 'returned', completed_at = NOW()
    WHERE id = p_transfer_id AND status IN ('accepted', 'in_progress');
    RETURN FOUND;
END;
$$;


--
-- Name: fn_rewrite_contact_url(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_rewrite_contact_url() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ DECLARE v_base text := 'https://supabase.atomicabr.com.br'; v_r2 text := 'https://zapp-media-proxy.adm01.workers.dev'; BEGIN IF NEW.profile_picture_url IS NOT NULL AND NEW.profile_picture_url != '' THEN IF NEW.profile_picture_url LIKE '%kong%' THEN NEW.profile_picture_url := replace(NEW.profile_picture_url, 'http://kong:8000', v_base); NEW.profile_picture_url := replace(NEW.profile_picture_url, 'https://kong:8000', v_base); NEW.profile_picture_url := replace(NEW.profile_picture_url, 'http://kong/', v_base || '/'); NEW.profile_picture_url := replace(NEW.profile_picture_url, 'https://kong/', v_base || '/'); ELSIF NEW.profile_picture_url LIKE 'http://minio%' THEN NEW.profile_picture_url := zapp.fn_media_public_url(NEW.profile_picture_url); END IF; END IF; RETURN NEW; END $$;


--
-- Name: fn_rewrite_media_storage_url(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_rewrite_media_storage_url() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ DECLARE v_base text := 'https://supabase.atomicabr.com.br'; v_r2 text := 'https://zapp-media-proxy.adm01.workers.dev'; BEGIN IF NEW.storage_url IS NOT NULL AND NEW.storage_url != '' THEN IF NEW.storage_url LIKE 'http://minio%' THEN NEW.storage_url := zapp.fn_media_public_url(NEW.storage_url); ELSIF NEW.storage_url LIKE '%r2.cloudflarestorage.com%' THEN NEW.storage_url := zapp.fn_media_public_url(NEW.storage_url); ELSIF NEW.storage_url LIKE '%kong%' THEN NEW.storage_url := replace(NEW.storage_url, 'http://kong:8000', v_base); NEW.storage_url := replace(NEW.storage_url, 'https://kong:8000', v_base); NEW.storage_url := replace(NEW.storage_url, 'http://kong/', v_base || '/'); NEW.storage_url := replace(NEW.storage_url, 'https://kong/', v_base || '/'); IF NEW.storage_url LIKE 'http://%' THEN NEW.storage_url := 'https://' || substring(NEW.storage_url FROM 8); END IF; END IF; END IF; RETURN NEW; END $$;


--
-- Name: fn_rewrite_media_url(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_rewrite_media_url() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ DECLARE v_base text := 'https://supabase.atomicabr.com.br'; v_r2 text := 'https://zapp-media-proxy.adm01.workers.dev'; BEGIN IF NEW.media_url IS NOT NULL AND NEW.media_url != '' THEN IF NEW.media_url LIKE 'http://minio%' THEN NEW.media_url := zapp.fn_media_public_url(NEW.media_url); ELSIF NEW.media_url LIKE '%r2.cloudflarestorage.com%' THEN NEW.media_url := zapp.fn_media_public_url(NEW.media_url); ELSIF NEW.media_url LIKE '%kong%' THEN NEW.media_url := replace(NEW.media_url, 'http://kong:8000', v_base); NEW.media_url := replace(NEW.media_url, 'https://kong:8000', v_base); NEW.media_url := replace(NEW.media_url, 'http://kong/', v_base || '/'); NEW.media_url := replace(NEW.media_url, 'https://kong/', v_base || '/'); IF NEW.media_url LIKE 'http://%' THEN NEW.media_url := 'https://' || substring(NEW.media_url FROM 8); END IF; END IF; END IF; RETURN NEW; END $$;


--
-- Name: FUNCTION fn_rewrite_media_url(); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_rewrite_media_url() IS 'Auto-reescreve URLs MinIO e R2 internas para URL publica do worker proxy';


--
-- Name: fn_rollback_to_minio(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_rollback_to_minio() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  -- Reverter URLs R2 para MinIO público
  UPDATE evolution_messages
  SET media_url = replace(media_url, 'https://zapp-media-proxy.adm01.workers.dev/', 'https://s3.atomicabr.com.br/evolution/')
  WHERE media_url LIKE 'https://zapp-media-proxy%';
  
  RETURN 'Rollback para MinIO executado. URLs revertidas para s3.atomicabr.com.br';
END;
$$;


--
-- Name: FUNCTION fn_rollback_to_minio(); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_rollback_to_minio() IS 'EMERGENCIA: Reverte todas as URLs do R2 worker de volta para MinIO publico. Usar apenas se R2 ficar offline.';


--
-- Name: fn_route_failed_webhooks_to_dlq(integer, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_route_failed_webhooks_to_dlq(p_max_age_minutes integer DEFAULT 30, p_batch_size integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
DECLARE
  v_routed    INT := 0;
  v_count     INT := 0;
  v_skipped   INT := 0;
  v_threshold TIMESTAMPTZ := now() - (p_max_age_minutes || ' minutes')::interval;
  v_tbl       TEXT;
  v_sql       TEXT;
  v_has_col   BOOLEAN;
BEGIN
  FOR v_tbl IN
    SELECT t.table_name
    FROM information_schema.tables t
    WHERE t.table_schema = 'evo'
      AND t.table_name LIKE 'evolution_webhook_events_%'
      AND t.table_name NOT IN ('evolution_webhook_events_v2','evolution_webhook_events_default')
      AND t.table_name NOT LIKE 'evolution_webhook_events_v2_%'
      AND t.table_type = 'BASE TABLE'
    ORDER BY t.table_name
  LOOP
    BEGIN
      SELECT EXISTS(
        SELECT 1 FROM information_schema.columns
        WHERE table_schema='evo' AND table_name=v_tbl AND column_name='processed'
      ) INTO v_has_col;
      IF NOT v_has_col THEN
        v_skipped := v_skipped + 1;
        CONTINUE;
      END IF;
      v_sql := format(
        'WITH failed AS ('
        '  SELECT id, event_type, instance_name, remote_jid, payload, error_message'
        '  FROM evo.%I'
        '  WHERE processed=false AND error_message IS NOT NULL AND created_at<%L'
        '  ORDER BY created_at ASC LIMIT %s'
        '), inserted AS ('
        '  INSERT INTO evo.evolution_webhook_dlq'
        '    (event_type, instance_name, remote_jid, payload, error_message,'
        '     status, next_retry_at, created_at, source_event_id)'
        '  SELECT f.event_type, f.instance_name, f.remote_jid, f.payload,'
        '    COALESCE(f.error_message,''processing_failed''),'
        '    ''pending'', now()+INTERVAL ''5 minutes'', now(), f.id'
        '  FROM failed f'
        '  ON CONFLICT (source_event_id) WHERE source_event_id IS NOT NULL DO NOTHING'
        '  RETURNING source_event_id'
        ') UPDATE evo.%I SET processed=true, processed_at=now()'
        ' WHERE id IN (SELECT source_event_id FROM inserted)',
        v_tbl, v_threshold, p_batch_size, v_tbl
      );
      EXECUTE v_sql;
      GET DIAGNOSTICS v_count = ROW_COUNT;
      v_routed := v_routed + v_count;
    EXCEPTION WHEN OTHERS THEN
      v_skipped := v_skipped + 1;
      RAISE WARNING 'dlq_router: tabela % inacessivel (SQLSTATE=%): %', v_tbl, SQLSTATE, SQLERRM;
    END;
  END LOOP;
  RETURN jsonb_build_object(
    'newly_routed_to_dlq', v_routed,
    'tables_skipped', v_skipped,
    'threshold', v_threshold,
    'batch_size', p_batch_size
  );
END;
$$;


--
-- Name: FUNCTION fn_route_failed_webhooks_to_dlq(p_max_age_minutes integer, p_batch_size integer); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_route_failed_webhooks_to_dlq(p_max_age_minutes integer, p_batch_size integer) IS 'Roteia eventos webhook com erro para evolution_webhook_dlq. Descobre tabelas dinamicamente via information_schema. v2: adicionado guard pg_tables + EXCEPTION WHEN undefined_table para tolerar tabelas deletadas (ex: wpp_pink_test cleanup). Retorna newly_routed_to_dlq + tables_skipped + skipped_details.';


--
-- Name: fn_run_media_health_alert(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_run_media_health_alert() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_report RECORD;
  v_alert_count int := 0;
  v_alert_msg text := '';
BEGIN
  FOR v_report IN 
    SELECT * FROM zapp.fn_media_pipeline_health_report() WHERE alert = true
  LOOP
    v_alert_count := v_alert_count + 1;
    v_alert_msg := v_alert_msg || E'\n[' || upper(v_report.status) || '] ' || 
                   v_report.metric || ': ' || v_report.value::text || ' — ' || v_report.description;
  END LOOP;
  
  IF v_alert_count > 0 THEN
    INSERT INTO zapp.warroom_alerts (
      alert_type, severity, title, message, source, created_at
    ) VALUES (
      'warning',  -- corrected: was 'media_pipeline' which violates chk_warroom_alert_type
      'high',
      '[ZAPP] ' || v_alert_count::text || ' alertas no pipeline de midia',
      v_alert_msg,
      'cron:media_pipeline_health_check',
      now()
    ) ON CONFLICT DO NOTHING;
  END IF;
END;
$$;


--
-- Name: fn_safe_audit_log(text, text, uuid, text, text, jsonb, jsonb, jsonb, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_safe_audit_log(p_action text, p_entity_type text, p_entity_id uuid DEFAULT NULL::uuid, p_performed_by text DEFAULT 'system'::text, p_performed_by_type text DEFAULT 'system'::text, p_old jsonb DEFAULT NULL::jsonb, p_new jsonb DEFAULT NULL::jsonb, p_metadata jsonb DEFAULT NULL::jsonb, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_temp'
    AS $$
DECLARE
  v_id   uuid;
  v_meta jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  IF p_performed_by IS NULL
     OR (p_performed_by IS DISTINCT FROM auth.uid()::text
         AND p_performed_by IS DISTINCT FROM COALESCE((SELECT email FROM auth.users WHERE id = auth.uid()), '')
         AND NOT zapp.is_admin_or_supervisor())
  THEN
    RAISE EXCEPTION 'permission denied';
  END IF;

  v_meta := COALESCE(p_metadata, '{}'::jsonb);
  IF p_notes IS NOT NULL THEN
    v_meta := v_meta || jsonb_build_object('notes', p_notes);
  END IF;

  BEGIN
    BEGIN
      INSERT INTO zapp.evolution_audit_log (
        action, entity_type, entity_id,
        performed_by, performed_by_type,
        old_values, new_values, metadata
      )
      VALUES (
        p_action, p_entity_type, p_entity_id,
        p_performed_by, p_performed_by_type,
        p_old, p_new, v_meta
      )
      RETURNING id INTO v_id;

      RETURN v_id;

    EXCEPTION WHEN check_violation THEN
      BEGIN
        INSERT INTO zapp.evolution_audit_log (
          action, entity_type, entity_id,
          performed_by, performed_by_type,
          old_values, new_values, metadata
        )
        VALUES (
          'action_not_in_vocabulary', p_entity_type, p_entity_id,
          p_performed_by, p_performed_by_type,
          p_old, p_new,
          v_meta || jsonb_build_object('original_action', p_action)
        )
        RETURNING id INTO v_id;

        RETURN v_id;
      EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'fn_safe_audit_log falhou: %', SQLERRM;
        RETURN NULL;
      END;
    END;
  END;
END;
$$;


--
-- Name: fn_sales_forecast(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_sales_forecast(p_months integer DEFAULT 3) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE v jsonb; v_avg numeric;
BEGIN
  SELECT COALESCE(avg(value),0) INTO v_avg FROM evolution_deals WHERE stage='pedido_finalizado' AND closed_at>=now()-interval '3 months';
  SELECT jsonb_build_object('avg_deal_value',round(v_avg,2),'forecast_monthly',round(v_avg*(SELECT count(*) FROM evolution_deals WHERE stage NOT IN ('perdido','pedido_finalizado'))/NULLIF(p_months,0),2),'open_deals',(SELECT count(*) FROM evolution_deals WHERE stage NOT IN ('perdido','pedido_finalizado')),'pipeline_value',(SELECT COALESCE(sum(value),0) FROM evolution_deals WHERE stage NOT IN ('perdido','pedido_finalizado'))) INTO v;
  RETURN v;
END; $$;


--
-- Name: fn_sales_report(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_sales_report(p_from timestamp with time zone DEFAULT (now() - '30 days'::interval), p_to timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE v jsonb;
BEGIN
  SELECT jsonb_build_object('period',jsonb_build_object('from',p_from,'to',p_to),'deals_created',(SELECT count(*) FROM evolution_deals WHERE created_at BETWEEN p_from AND p_to),'deals_closed',(SELECT count(*) FROM evolution_deals WHERE stage='pedido_finalizado' AND closed_at BETWEEN p_from AND p_to),'total_revenue',(SELECT COALESCE(sum(value),0) FROM evolution_deals WHERE stage='pedido_finalizado' AND closed_at BETWEEN p_from AND p_to),'deals_lost',(SELECT count(*) FROM evolution_deals WHERE stage='perdido' AND updated_at BETWEEN p_from AND p_to)) INTO v;
  RETURN v;
END; $$;


--
-- Name: fn_save_daily_kpis(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_save_daily_kpis() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'pg_temp'
    AS $$
DECLARE
  v jsonb;
BEGIN
  v := zapp.fn_calculate_daily_kpis();

  INSERT INTO evo.evolution_daily_metrics (
    id,
    metric_date,
    new_contacts,
    active_contacts,
    total_contacts,
    messages_received,
    messages_sent,
    avg_response_time_seconds,
    conversations_opened,
    conversations_resolved,
    avg_resolution_time_seconds,
    deals_created,
    deals_won,
    deals_lost,
    revenue,
    pipeline_value,
    lead_to_deal_rate,
    deal_win_rate,
    avg_messages_per_contact,
    automations_triggered,
    followups_sent,
    calculated_at
  ) VALUES (
    gen_random_uuid(),
    (v->>'metric_date')::date,
    (v->>'new_contacts')::int,
    (v->>'active_contacts')::int,
    (v->>'total_contacts')::int,
    (v->>'messages_received')::int,
    (v->>'messages_sent')::int,
    (v->>'avg_response_time_seconds')::int,
    (v->>'conversations_opened')::int,
    (v->>'conversations_resolved')::int,
    (v->>'avg_resolution_time_seconds')::int,
    (v->>'deals_created')::int,
    (v->>'deals_won')::int,
    (v->>'deals_lost')::int,
    (v->>'revenue')::numeric,
    (v->>'pipeline_value')::numeric,
    (v->>'lead_to_deal_rate')::numeric,
    (v->>'deal_win_rate')::numeric,
    (v->>'avg_messages_per_contact')::numeric,
    (v->>'automations_triggered')::int,
    (v->>'followups_sent')::int,
    now()
  )
  ON CONFLICT (metric_date) DO UPDATE SET
    new_contacts = EXCLUDED.new_contacts,
    active_contacts = EXCLUDED.active_contacts,
    total_contacts = EXCLUDED.total_contacts,
    messages_received = EXCLUDED.messages_received,
    messages_sent = EXCLUDED.messages_sent,
    avg_response_time_seconds = EXCLUDED.avg_response_time_seconds,
    conversations_opened = EXCLUDED.conversations_opened,
    conversations_resolved = EXCLUDED.conversations_resolved,
    avg_resolution_time_seconds = EXCLUDED.avg_resolution_time_seconds,
    deals_created = EXCLUDED.deals_created,
    deals_won = EXCLUDED.deals_won,
    deals_lost = EXCLUDED.deals_lost,
    revenue = EXCLUDED.revenue,
    pipeline_value = EXCLUDED.pipeline_value,
    lead_to_deal_rate = EXCLUDED.lead_to_deal_rate,
    deal_win_rate = EXCLUDED.deal_win_rate,
    avg_messages_per_contact = EXCLUDED.avg_messages_per_contact,
    automations_triggered = EXCLUDED.automations_triggered,
    followups_sent = EXCLUDED.followups_sent,
    calculated_at = now();
END;
$$;


--
-- Name: fn_scheduled_cleanup(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_scheduled_cleanup() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE v_e integer; v_m integer; v_a integer;
BEGIN
  DELETE FROM evolution_webhook_events WHERE created_at<now()-interval '30 days'; GET DIAGNOSTICS v_e=ROW_COUNT;
  DELETE FROM evolution_alerts WHERE acknowledged=true AND acknowledged_at<now()-interval '7 days'; GET DIAGNOSTICS v_a=ROW_COUNT;
END; $$;


--
-- Name: fn_schema_drift_daily_check(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_schema_drift_daily_check() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_count integer;
BEGIN SELECT count(*) INTO v_count FROM fn_detect_schema_drift(); RETURN jsonb_build_object('status','checked','drift_count',v_count,'checked_at',now()); END; $$;


--
-- Name: fn_score_security_acl(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_score_security_acl() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'vendas', 'financeiro', 'artes', 'archive', 'pg_catalog'
    AS $$
DECLARE
  v_anon_email_execute      int := 0;
  v_anon_email_view_select  int := 0;
  v_anon_rpc_all_execute    int := 0;
  v_anon_sensitive_execute  int := 0;
  v_views_no_si_anon        int := 0;
  v_open_critical           int := 0;
  v_open_high               int := 0;
  v_anon_any_execute        int := 0;
  v_public_grant_execute    int := 0;
  v_auth_purge_no_guard     int := 0;
  v_evo_views_no_si         int := 0;
  v_rls_zero_policy         int := 0;
  v_anon_exe_evo_zapp_breach int := 0;
  v_legacy_rls_off_anon     int := 0;
  v_auth_rls_fn_denied      int := 0;
  v_score                   int := 0;
BEGIN
  SELECT count(*) INTO v_anon_email_execute
  FROM pg_proc p JOIN pg_namespace n ON p.pronamespace=n.oid
  WHERE n.nspname='public' AND p.proname LIKE 'rpc_email_%'
    AND has_function_privilege('anon',p.oid,'EXECUTE');
  SELECT count(*) INTO v_anon_email_view_select
  FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE n.nspname='public' AND c.relkind='v' AND c.relname LIKE 'email%'
    AND has_table_privilege('anon',c.oid,'SELECT');
  SELECT count(*) INTO v_anon_rpc_all_execute
  FROM pg_proc p JOIN pg_namespace n ON p.pronamespace=n.oid
  WHERE n.nspname='public' AND p.proname LIKE 'rpc_%'
    AND NOT p.prorettype=(SELECT oid FROM pg_type WHERE typname='trigger')
    AND has_function_privilege('anon',p.oid,'EXECUTE');
  SELECT count(*) INTO v_anon_sensitive_execute
  FROM pg_proc p JOIN pg_namespace n ON p.pronamespace=n.oid
  WHERE n.nspname='public'
    AND p.proname IN (
      'search_contacts','fn_accept_transfer','fn_complete_transfer',
      'fn_create_transfer','fn_return_transfer','fn_transfer_comment',
      'manage_department_member','fn_check_email_views_acl',
      'fn_system_health_score','fn_score_security_acl',
      'fn_security_acl_master_check','fn_check_email_rpc_acl',
      'fn_purge_api_key_from_logs','fn_restore_integrity_check',
      'decrypt_gmail_token','auto_pause_instance_on_auth_spike',
      'fn_update_backup_sentinel'
    )
    AND has_function_privilege('anon',p.oid,'EXECUTE');
  SELECT count(*) INTO v_views_no_si_anon
  FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE n.nspname='public' AND c.relkind='v'
    AND has_table_privilege('anon',c.oid,'SELECT')
    AND NOT EXISTS(
      SELECT 1 FROM pg_options_to_table(COALESCE(c.reloptions,ARRAY[]::text[]))
      WHERE option_name='security_invoker' AND option_value IN ('on','true')
    );
  SELECT count(*) INTO v_open_critical
  FROM zapp.security_acl_alerts
  WHERE resolved_at IS NULL
    AND alert_type IN ('ANON_EXECUTE_GRANTED','ANON_SELECT_VIEW')
    AND severity='CRITICAL';
  SELECT count(*) INTO v_open_high
  FROM zapp.security_acl_alerts
  WHERE resolved_at IS NULL
    AND alert_type='VIEW_MISSING_SECURITY_INVOKER'
    AND severity='HIGH';
  SELECT count(*) INTO v_anon_any_execute
  FROM pg_proc p JOIN pg_namespace n ON p.pronamespace=n.oid
  WHERE n.nspname='public'
    AND has_function_privilege('anon',p.oid,'EXECUTE');
  SELECT count(*) INTO v_public_grant_execute
  FROM pg_proc p JOIN pg_namespace n ON p.pronamespace=n.oid
  WHERE n.nspname='public'
    AND EXISTS(
      SELECT 1 FROM aclexplode(COALESCE(p.proacl,'{}')) a
      WHERE a.grantee=0 AND a.privilege_type='EXECUTE'
    );
  SELECT count(*) INTO v_auth_purge_no_guard
  FROM pg_proc p JOIN pg_namespace n ON p.pronamespace=n.oid
  WHERE n.nspname='public'
    AND has_function_privilege('authenticated',p.oid,'EXECUTE')
    AND (
      p.proname ILIKE 'fn_purge%' OR p.proname ILIKE 'fn_gc%'
      OR p.proname ILIKE 'cleanup_%' OR p.proname ILIKE 'run_%_purge'
    );
  SELECT count(*) INTO v_evo_views_no_si
  FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE c.relkind='v' AND n.nspname='public'
    AND pg_get_viewdef(c.oid) ILIKE '%evo.%'
    AND NOT EXISTS(
      SELECT 1 FROM pg_options_to_table(COALESCE(c.reloptions,ARRAY[]::text[]))
      WHERE option_name='security_invoker' AND option_value IN ('on','true')
    );
  SELECT count(*) INTO v_rls_zero_policy
  FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE c.relkind='r' AND n.nspname IN ('evo','zapp')
    AND c.relrowsecurity=true
    AND c.relname NOT LIKE '%_202%'
    AND (SELECT count(*) FROM pg_policies pp
         WHERE pp.schemaname=n.nspname AND pp.tablename=c.relname)=0;
  SELECT count(*) INTO v_anon_exe_evo_zapp_breach
  FROM pg_proc p JOIN pg_namespace n ON p.pronamespace=n.oid
  WHERE n.nspname IN ('evo','zapp')
    AND has_function_privilege('anon', p.oid, 'EXECUTE')
    AND has_schema_privilege('anon', n.nspname, 'USAGE');
  SELECT count(*) INTO v_legacy_rls_off_anon
  FROM pg_tables t
  WHERE t.schemaname IN ('vendas','financeiro','artes','archive')
    AND t.rowsecurity = false
    AND has_table_privilege('anon', t.schemaname||'.'||t.tablename, 'SELECT');
  SELECT count(DISTINCT p.oid) INTO v_auth_rls_fn_denied
  FROM pg_depend d
  JOIN pg_proc p ON p.oid = d.refobjid
  JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE d.classid = 'pg_policy'::regclass
    AND d.refclassid = 'pg_proc'::regclass
    AND n.nspname IN ('public','zapp','evo')
    AND p.prokind = 'f'
    AND NOT has_function_privilege('authenticated', p.oid, 'EXECUTE');
  v_score := CASE
    WHEN v_anon_email_execute>0 OR v_anon_email_view_select>0
      OR v_anon_rpc_all_execute>0 OR v_anon_sensitive_execute>0
      OR v_views_no_si_anon>0 OR v_open_critical>0
      OR v_anon_any_execute>0 OR v_public_grant_execute>0
      OR v_auth_purge_no_guard>0 OR v_evo_views_no_si>0
      OR v_rls_zero_policy>0 OR v_anon_exe_evo_zapp_breach>0
      OR v_legacy_rls_off_anon>0 THEN 0
    WHEN v_open_high>0 OR v_auth_rls_fn_denied>0 THEN 3
    ELSE 5
  END;
  RETURN jsonb_build_object(
    'score',v_score,'max',5,
    'anon_email_execute',v_anon_email_execute,
    'anon_email_view_select',v_anon_email_view_select,
    'anon_rpc_all_execute',v_anon_rpc_all_execute,
    'anon_sensitive_execute',v_anon_sensitive_execute,
    'views_no_si_anon',v_views_no_si_anon,
    'open_critical',v_open_critical,'open_high',v_open_high,
    'anon_any_execute',v_anon_any_execute,
    'public_grant_execute',v_public_grant_execute,
    'auth_purge_no_guard',v_auth_purge_no_guard,
    'evo_views_no_si',v_evo_views_no_si,
    'rls_zero_policy',v_rls_zero_policy,
    'anon_exe_evo_zapp_breach',v_anon_exe_evo_zapp_breach,
    'legacy_rls_off_anon',v_legacy_rls_off_anon,
    'auth_rls_fn_denied',v_auth_rls_fn_denied,
    'monitoring','pg_cron 30min - R23-2026-07-16: si=true fix + R19+G8 + R25-2026-08-01: auth_rls_fn_denied(pg_depend)'
  );
END;
$$;


--
-- Name: fn_score_v2_pipeline(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_score_v2_pipeline() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'pg_catalog'
    AS $$
DECLARE
  v_h JSONB;
BEGIN
  SELECT evo.fn_v2_mirror_health() INTO v_h;
  RETURN jsonb_build_object(
    'score',          (v_h->>'v2_score')::INT,
    'max',            10,
    'status',         v_h->>'v2_status',
    'hours_dead',     (v_h->>'v2_hours_dead')::NUMERIC,
    'last_event',     v_h->>'v2_last_event',
    'divergence',     (v_h->>'divergence')::BOOL,
    'audit_healthy',  (v_h->>'audit_healthy')::BOOL,
    'infra_fix',      (v_h->>'infra_fix_needed')::BOOL,
    'fix_command',    v_h->>'fix_command'
  );
END;
$$;


--
-- Name: FUNCTION fn_score_v2_pipeline(); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_score_v2_pipeline() IS 'Dimensao v2_mirror_pipeline para fn_system_health_score(): avalia evolution_webhook_events_v2 INDEPENDENTEMENTE do webhook_audit_log. 10pts = dead < 1h, 8 = 1-2h, 5 = 2-6h, 2 = 6-24h, 0 = > 24h. Divergence=true quando v2 morto mas audit_log ativo — sinaliza problema de bindings RabbitMQ.';


--
-- Name: fn_search_contacts(text, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_search_contacts(p_query text, p_limit integer DEFAULT 50) RETURNS SETOF evo.evolution_contacts
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
  SELECT * FROM evolution_contacts WHERE deleted_at IS NULL AND (full_name ILIKE '%'||p_query||'%' OR push_name ILIKE '%'||p_query||'%' OR phone_number ILIKE '%'||p_query||'%' OR company ILIKE '%'||p_query||'%' OR remote_jid ILIKE '%'||p_query||'%') ORDER BY last_message_at DESC NULLS LAST LIMIT p_limit;
$$;


--
-- Name: fn_security_acl_master_check(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_security_acl_master_check() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_rpc_violations   int := 0;
  v_view_violations  int := 0;
  v_result           jsonb;
BEGIN
  -- Conta violações em RPCs
  SELECT count(*) INTO v_rpc_violations
  FROM zapp.fn_check_email_rpc_acl()
  WHERE anon_execute = true;

  -- Conta violações em views
  SELECT count(*) INTO v_view_violations
  FROM zapp.fn_check_email_views_acl()
  WHERE anon_select = true OR NOT has_security_invoker;

  v_result := jsonb_build_object(
    'checked_at',        now(),
    'rpc_violations',    v_rpc_violations,
    'view_violations',   v_view_violations,
    'total_violations',  v_rpc_violations + v_view_violations,
    'status',            CASE WHEN v_rpc_violations + v_view_violations = 0 THEN 'CLEAN' ELSE 'VIOLATIONS_DETECTED' END
  );

  RETURN v_result;
END;
$$;


--
-- Name: fn_security_self_audit_daily(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_security_self_audit_daily() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp, ops, evo, pg_catalog'
    AS $$ DECLARE v_surface jsonb; v_acl jsonb; v_secdef jsonb; v_invoker_alerts int := 0; v_severity text; v_details jsonb; BEGIN v_surface := zapp.fn_security_surface_audit(); v_acl := zapp.fn_security_acl_master_check(); v_secdef := ops.fn_secdef_search_path_guard(); PERFORM zapp.fn_autofix_security_invoker(); INSERT INTO zapp.security_acl_alerts (detected_at, alert_type, object_name, role_name, privilege, severity, details) SELECT NOW(), 'VIEW_MISSING_SECURITY_INVOKER', schema||'.'||view_name, 'anon', 'SELECT', 'HIGH', jsonb_build_object('view', view_name, 'schema', schema, 'anon_can_select', true) FROM zapp.v_security_invoker_audit WHERE risk_status != 'OK' AND NOT EXISTS (SELECT 1 FROM zapp.security_acl_alerts WHERE alert_type='VIEW_MISSING_SECURITY_INVOKER' AND object_name = schema||'.'||view_name AND resolved_at IS NULL AND detected_at > NOW() - INTERVAL '24 hours'); GET DIAGNOSTICS v_invoker_alerts = ROW_COUNT; v_details := jsonb_build_object('surface', v_surface, 'acl_master', v_acl, 'secdef_guard', v_secdef, 'invoker_alerts_new', v_invoker_alerts, 'checked_at', now()); v_severity := CASE WHEN coalesce((v_surface->>'truly_dangerous')::boolean, false) OR coalesce((v_acl->>'total_violations')::int, 0) > 0 THEN 'HIGH' ELSE 'INFO' END; INSERT INTO zapp.security_acl_alerts (detected_at, alert_type, object_name, role_name, privilege, severity, details) VALUES (now(), 'SECURITY_SELF_AUDIT_DAILY', 'database', 'postgres', 'SELF_AUDIT', v_severity, v_details); RETURN v_details; END; $$;


--
-- Name: fn_security_surface_audit(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_security_surface_audit() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'pg_catalog'
    AS $$
DECLARE
  v_anon_execute        int; v_public_grant int; v_views_no_si int; v_rls_off int;
  v_auth_purge          int; v_default_priv_auth int; v_auth_secdef_no_guard int;
  v_truly_dangerous     boolean;
BEGIN
  SELECT COUNT(*) INTO v_anon_execute FROM pg_proc p JOIN pg_namespace n ON p.pronamespace=n.oid
  WHERE n.nspname='public' AND has_function_privilege('anon',p.oid,'execute');

  SELECT COUNT(*) INTO v_public_grant FROM pg_proc p JOIN pg_namespace n ON p.pronamespace=n.oid
  WHERE n.nspname='public' AND EXISTS(SELECT 1 FROM aclexplode(COALESCE(p.proacl,'{}')) a
    WHERE a.grantee=0 AND a.privilege_type='EXECUTE');

  -- FIX v4 (2026-08-06): option_value do pg_options_to_table grava 'true' (nao 'on') —
  -- a comparacao com 'on' gerava falso REGRESSION permanente (122 views "sem SI" que tinham SI).
  SELECT COUNT(*) INTO v_views_no_si FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE c.relkind='v' AND n.nspname='public'
    AND NOT EXISTS(SELECT 1 FROM pg_options_to_table(c.reloptions) o
      WHERE o.option_name='security_invoker' AND o.option_value IN ('on','true'))
    AND pg_get_viewdef(c.oid) ILIKE '%evo.%';

  SELECT COUNT(*) INTO v_rls_off FROM pg_tables
  WHERE schemaname IN ('evo','zapp','public') AND rowsecurity=false;

  SELECT COUNT(*) INTO v_auth_purge FROM pg_proc p JOIN pg_namespace n ON p.pronamespace=n.oid
  WHERE n.nspname='public' AND has_function_privilege('authenticated',p.oid,'execute')
    AND (p.proname ILIKE 'fn_purge%' OR p.proname ILIKE 'fn_gc%'
      OR p.proname ILIKE 'cleanup_%' OR p.proname ILIKE 'run_%_purge');

  SELECT COUNT(*) INTO v_default_priv_auth
  FROM pg_default_acl d JOIN pg_namespace n ON n.oid=d.defaclnamespace
  WHERE n.nspname='evo' AND d.defaclobjtype='r'
    AND EXISTS(SELECT 1 FROM aclexplode(d.defaclacl) a
      JOIN pg_roles r ON r.oid=a.grantee WHERE r.rolname='authenticated'
      AND a.privilege_type='SELECT');

  SELECT COUNT(*) INTO v_auth_secdef_no_guard FROM pg_proc p JOIN pg_namespace n ON p.pronamespace=n.oid
  WHERE n.nspname='public' AND has_function_privilege('authenticated',p.oid,'execute')
    AND p.prosecdef=true
    AND (p.proname ILIKE 'fn_archive%' OR p.proname ILIKE 'fn_batch_%'
      OR p.proname ILIKE 'fn_auto_archive%' OR p.proname ILIKE 'fn_mirror_kill%'
      OR p.proname ILIKE 'fin_bulk_%' OR p.proname ILIKE 'fin_sync_%'
      OR p.proname ILIKE 'fn_claim_media%' OR p.proname ILIKE 'fn_backfill%'
      OR p.proname ILIKE 'fn_check_followup%');

  v_truly_dangerous := (v_views_no_si>0 OR v_rls_off>0 OR v_auth_purge>0
                         OR v_default_priv_auth>0 OR v_auth_secdef_no_guard>0);

  IF v_truly_dangerous AND NOT EXISTS(
    SELECT 1 FROM evo.evolution_alerts
    WHERE alert_type='security_acl_regression' AND resolved_at IS NULL
      AND created_at >= NOW()-INTERVAL '4 hours'
  ) THEN
    INSERT INTO evo.evolution_alerts (severity,alert_type,message,payload) VALUES (
      'critical','security_acl_regression',
      format('ACL REGRESSION: anon=%s pub_grant=%s no_si=%s rls_off=%s purge=%s defpriv_auth=%s secdef_noguard=%s',
        v_anon_execute,v_public_grant,v_views_no_si,v_rls_off,v_auth_purge,v_default_priv_auth,v_auth_secdef_no_guard),
      jsonb_build_object('anon_execute',v_anon_execute,'public_grant',v_public_grant,
        'views_no_si',v_views_no_si,'rls_off',v_rls_off,'auth_purge',v_auth_purge,
        'default_priv_auth_evo',v_default_priv_auth,'auth_secdef_no_guard',v_auth_secdef_no_guard,
        'checked_at',NOW(),'fix_version','v4'));
  END IF;

  RETURN jsonb_build_object(
    'status', CASE WHEN v_truly_dangerous THEN 'REGRESSION' ELSE 'CLEAN' END,
    'anon_execute',v_anon_execute,'public_grant',v_public_grant,'views_no_si',v_views_no_si,
    'rls_off',v_rls_off,'auth_purge',v_auth_purge,
    'default_priv_auth_evo',v_default_priv_auth,'auth_secdef_no_guard',v_auth_secdef_no_guard,
    'truly_dangerous',v_truly_dangerous,'fix_version','v4','checked_at',NOW());
END;
$$;


--
-- Name: fn_segment_contacts(text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_segment_contacts(p_segment text, p_instance text DEFAULT NULL::text) RETURNS TABLE(id uuid, nome text, phone text, segment text)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN RETURN QUERY SELECT c.id,COALESCE(c.full_name,c.push_name)::text,c.phone_number::text,p_segment::text FROM evolution_contacts c WHERE c.deleted_at IS NULL AND (p_instance IS NULL OR c.instance_name=p_instance) AND CASE p_segment
  WHEN 'vip' THEN c.lead_score>=80
  WHEN 'hot' THEN c.lead_score BETWEEN 50 AND 79
  WHEN 'warm' THEN c.lead_score BETWEEN 20 AND 49
  WHEN 'cold' THEN c.lead_score<20 OR c.lead_score IS NULL
  WHEN 'inactive' THEN c.last_message_at < now()-interval '30 days'
  ELSE true END ORDER BY c.lead_score DESC NULLS LAST; END; $$;


--
-- Name: fn_segments_updated_at(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_segments_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END; $$;


--
-- Name: fn_send_audio_meme(text, text, uuid, uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_send_audio_meme(p_remote_jid text, p_instance_name text, p_audio_meme_id uuid, p_created_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
DECLARE
  v_meme record;
  v_queue_id uuid;
BEGIN
  SELECT * INTO v_meme FROM audio_memes WHERE id = p_audio_meme_id;
  IF v_meme IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'audio_meme_id nao encontrado no catalogo');
  END IF;
  
  INSERT INTO outbound_message_queue (
    remote_jid, instance_name, message_type, content,
    media_url, media_mime_type, ptt, audio_meme_id,
    metadata, status, retry_count, max_retries, created_by
  ) VALUES (
    p_remote_jid, p_instance_name, 'audio', '',
    v_meme.audio_url, 'audio/ogg; codecs=opus', true, p_audio_meme_id,
    jsonb_build_object(
      'meme_name', v_meme.name,
      'meme_category', v_meme.category,
      'duration_seconds', v_meme.duration_seconds
    ),
    'pending', 0, 3, p_created_by
  ) RETURNING id INTO v_queue_id;
  
  UPDATE audio_memes SET use_count = use_count + 1 WHERE id = p_audio_meme_id;
  
  RETURN jsonb_build_object(
    'ok', true,
    'queue_id', v_queue_id,
    'meme_name', v_meme.name,
    'meme_category', v_meme.category,
    'ptt', true,
    'audio_url', v_meme.audio_url,
    'remote_jid', p_remote_jid,
    'instance_name', p_instance_name
  );
END;
$$;


--
-- Name: FUNCTION fn_send_audio_meme(p_remote_jid text, p_instance_name text, p_audio_meme_id uuid, p_created_by uuid); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_send_audio_meme(p_remote_jid text, p_instance_name text, p_audio_meme_id uuid, p_created_by uuid) IS 'Enfileira envio de audio-meme com ptt=true (aparece como voice note no WhatsApp). Incrementa use_count automaticamente.';


--
-- Name: fn_send_bitrix_alert(text, text, text, text, jsonb, boolean, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_send_bitrix_alert(p_alert_key text, p_severity text, p_title text, p_message text, p_payload jsonb DEFAULT '{}'::jsonb, p_force_send boolean DEFAULT false, p_cooldown_min integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_severity_rank   smallint;
  v_cooldown_row    zapp.evolution_alert_cooldown%ROWTYPE;
  v_webhook_url     text;
  v_recipient_id    text;
  v_dry_run         boolean := false;
  v_skip_reason     text := NULL;
  v_emoji           text;
  v_formatted_msg   text;
  v_request_id      bigint;
  v_alert_id        uuid;
  v_dispatch_status text;
  v_result          jsonb;
  v_now             timestamptz := now();
  v_now_brt         text;
BEGIN
  -- Input validation
  IF p_alert_key IS NULL OR p_alert_key = '' THEN
    RAISE EXCEPTION 'alert_key is required';
  END IF;
  IF p_severity IS NULL OR p_severity = '' THEN
    RAISE EXCEPTION 'severity is required';
  END IF;

  v_severity_rank := zapp.fn_severity_rank(p_severity);
  v_now_brt := to_char(v_now AT TIME ZONE 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI:SS') || ' BRT';

  -- Cooldown check (com escalation bypass)
  SELECT * INTO v_cooldown_row
  FROM zapp.evolution_alert_cooldown
  WHERE alert_key = p_alert_key;

  IF v_cooldown_row.alert_key IS NOT NULL AND NOT p_force_send THEN
    -- Mesma severidade ou downgrade, dentro da janela de cooldown → skip
    IF v_severity_rank <= v_cooldown_row.last_severity_rank
       AND v_now - v_cooldown_row.last_sent_at < make_interval(mins => p_cooldown_min) THEN
      v_skip_reason := format('cooldown_active: %s remaining',
        make_interval(mins => p_cooldown_min) - (v_now - v_cooldown_row.last_sent_at));
      RETURN jsonb_build_object(
        'dispatched', false,
        'skip_reason', v_skip_reason,
        'alert_key', p_alert_key,
        'severity', p_severity,
        'cooldown_until', v_cooldown_row.last_sent_at + make_interval(mins => p_cooldown_min)
      );
    END IF;
  END IF;

  -- Lookup vault secrets (graceful: se faltar, vai pra DRY-RUN)
  BEGIN
    v_webhook_url := zapp.fn_get_vault_secret('bitrix24_webhook_alerts_url');
  EXCEPTION WHEN OTHERS THEN
    v_webhook_url := NULL;
  END;
  BEGIN
    v_recipient_id := zapp.fn_get_vault_secret('bitrix24_alert_recipient_user_id');
  EXCEPTION WHEN OTHERS THEN
    v_recipient_id := NULL;
  END;

  IF v_webhook_url IS NULL OR v_webhook_url = '' OR v_recipient_id IS NULL OR v_recipient_id = '' THEN
    v_dry_run := true;
    v_dispatch_status := 'dry_run_no_secret';
  END IF;

  -- Format message (BB-code Bitrix24)
  v_emoji := CASE
    WHEN v_severity_rank >= 3 THEN '🚨'
    WHEN v_severity_rank = 2 THEN '🟠'
    WHEN v_severity_rank = 1 THEN '⚠️'
    ELSE 'ℹ️'
  END;

  v_formatted_msg := format(
    E'%s [B]%s[/B] · Pipeline ZAPP\n\n[B]📌 %s[/B]\n\n%s\n\n[I]🔑 alert_key:[/I] %s\n[I]🕐 %s[/I]\n[I]🌎 supabase.atomicabr.com.br[/I]',
    v_emoji,
    upper(p_severity),
    coalesce(p_title, '(sem título)'),
    coalesce(p_message, '(sem mensagem)'),
    p_alert_key,
    v_now_brt
  );

  -- Dispatch via pg_net se não for dry-run
  IF NOT v_dry_run THEN
    BEGIN
      v_request_id := net.http_post(
        url := rtrim(v_webhook_url, '/') || '/im.message.add.json',
        body := jsonb_build_object(
          'USER_ID', v_recipient_id,
          'MESSAGE', v_formatted_msg
        ),
        headers := '{"Content-Type": "application/json"}'::jsonb,
        timeout_milliseconds := 5000
      );
      v_dispatch_status := 'sent';
    EXCEPTION WHEN OTHERS THEN
      v_request_id := NULL;
      v_dispatch_status := 'send_failed: ' || SQLERRM;
    END;
  END IF;

  -- Always log in evolution_alerts
  INSERT INTO zapp.evolution_alerts (alert_type, severity, title, message, payload)
  VALUES (
    'bitrix_dispatch',
    p_severity,
    p_title,
    p_message,
    p_payload
      || jsonb_build_object(
        'alert_key', p_alert_key,
        'dispatch_status', v_dispatch_status,
        'dry_run', v_dry_run,
        'http_request_id', v_request_id,
        'severity_rank', v_severity_rank,
        'sent_at', v_now,
        'formatted_msg', v_formatted_msg
      )
  )
  RETURNING id INTO v_alert_id;

  -- Upsert cooldown
  INSERT INTO zapp.evolution_alert_cooldown
    (alert_key, last_severity, last_severity_rank, consecutive_count, last_sent_at,
     last_payload, cooldown_minutes, last_dispatch_status, updated_at)
  VALUES
    (p_alert_key, p_severity, v_severity_rank, 1, v_now,
     p_payload, p_cooldown_min, v_dispatch_status, v_now)
  ON CONFLICT (alert_key) DO UPDATE SET
    last_severity = EXCLUDED.last_severity,
    last_severity_rank = EXCLUDED.last_severity_rank,
    consecutive_count = CASE
      WHEN evolution_alert_cooldown.last_severity = EXCLUDED.last_severity
      THEN evolution_alert_cooldown.consecutive_count + 1
      ELSE 1
    END,
    last_sent_at = EXCLUDED.last_sent_at,
    last_payload = EXCLUDED.last_payload,
    last_dispatch_status = EXCLUDED.last_dispatch_status,
    updated_at = EXCLUDED.updated_at;

  v_result := jsonb_build_object(
    'dispatched', NOT v_dry_run AND v_request_id IS NOT NULL,
    'dry_run', v_dry_run,
    'alert_id', v_alert_id,
    'http_request_id', v_request_id,
    'dispatch_status', v_dispatch_status,
    'severity', p_severity,
    'severity_rank', v_severity_rank,
    'alert_key', p_alert_key,
    'sent_at', v_now,
    'formatted_msg_preview', left(v_formatted_msg, 200)
  );

  RETURN v_result;
END;
$$;


