--
-- Name: fn_send_sticker(text, text, uuid, uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_send_sticker(p_remote_jid text, p_instance_name text, p_sticker_id uuid, p_created_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
DECLARE
  v_sticker record;
  v_queue_id uuid;
BEGIN
  -- 1. Buscar figurinha no catalogo
  SELECT * INTO v_sticker FROM stickers WHERE id = p_sticker_id AND is_active = true;
  IF v_sticker IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'sticker_id nao encontrado ou inativo');
  END IF;
  
  -- 2. Inserir na fila de envio
  INSERT INTO outbound_message_queue (
    remote_jid, instance_name, message_type, content,
    media_url, media_mime_type, sticker_id,
    metadata, status, retry_count, max_retries, created_by
  ) VALUES (
    p_remote_jid, p_instance_name, 'sticker', '',
    v_sticker.image_url, COALESCE(v_sticker.mime_type, 'image/webp'), p_sticker_id,
    jsonb_build_object(
      'sticker_name', v_sticker.name,
      'sticker_category', v_sticker.category,
      'is_animated', v_sticker.is_animated
    ),
    'pending', 0, 3, p_created_by
  ) RETURNING id INTO v_queue_id;
  
  -- 3. Incrementar use_count
  UPDATE stickers SET use_count = COALESCE(use_count, 0) + 1 WHERE id = p_sticker_id;
  
  RETURN jsonb_build_object(
    'ok', true,
    'queue_id', v_queue_id,
    'sticker_name', v_sticker.name,
    'sticker_category', v_sticker.category,
    'is_animated', v_sticker.is_animated,
    'image_url', v_sticker.image_url,
    'remote_jid', p_remote_jid,
    'instance_name', p_instance_name
  );
END;
$$;


--
-- Name: FUNCTION fn_send_sticker(p_remote_jid text, p_instance_name text, p_sticker_id uuid, p_created_by uuid); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_send_sticker(p_remote_jid text, p_instance_name text, p_sticker_id uuid, p_created_by uuid) IS 'Enfileira envio de figurinha do catalogo. Incrementa use_count automaticamente.';


--
-- Name: fn_send_sticker_from_catalog(text, text, uuid, uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_send_sticker_from_catalog(p_remote_jid text, p_instance_name text, p_sticker_id uuid, p_created_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
DECLARE
  v_sticker record;
  v_queue_id uuid;
BEGIN
  SELECT * INTO v_sticker FROM stickers WHERE id = p_sticker_id AND is_active = true;
  IF v_sticker IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'sticker_id nao encontrado ou inativo');
  END IF;
  
  INSERT INTO outbound_message_queue (
    remote_jid, instance_name, message_type, content,
    media_url, media_mime_type, sticker_id,
    metadata, status, retry_count, max_retries, created_by
  ) VALUES (
    p_remote_jid, p_instance_name, 'sticker', '',
    v_sticker.image_url, COALESCE(v_sticker.mime_type, 'image/webp'), p_sticker_id,
    jsonb_build_object(
      'sticker_name', v_sticker.name,
      'sticker_category', v_sticker.category,
      'is_animated', v_sticker.is_animated
    ),
    'pending', 0, 3, p_created_by
  ) RETURNING id INTO v_queue_id;
  
  -- Incrementar use_count
  UPDATE stickers SET use_count = COALESCE(use_count, 0) + 1 WHERE id = p_sticker_id;
  
  RETURN jsonb_build_object(
    'ok', true,
    'queue_id', v_queue_id,
    'sticker_name', v_sticker.name,
    'sticker_category', v_sticker.category,
    'is_animated', v_sticker.is_animated,
    'image_url', v_sticker.image_url,
    'remote_jid', p_remote_jid,
    'instance_name', p_instance_name
  );
END;
$$;


--
-- Name: FUNCTION fn_send_sticker_from_catalog(p_remote_jid text, p_instance_name text, p_sticker_id uuid, p_created_by uuid); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_send_sticker_from_catalog(p_remote_jid text, p_instance_name text, p_sticker_id uuid, p_created_by uuid) IS 'Enfileira envio de figurinha do catalogo. Incrementa use_count automaticamente.';


