--
-- Name: fn_severity_rank(text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_severity_rank(p_severity text) RETURNS smallint
    LANGUAGE sql IMMUTABLE
    AS $$ SELECT CASE lower(coalesce(p_severity, '')) WHEN 'info' THEN 0::smallint WHEN 'low' THEN 0::smallint WHEN 'warning' THEN 1::smallint WHEN 'warn' THEN 1::smallint WHEN 'medium' THEN 1::smallint WHEN 'error' THEN 2::smallint WHEN 'high' THEN 2::smallint WHEN 'critical' THEN 3::smallint WHEN 'crit' THEN 3::smallint ELSE 1::smallint END $$;


--
-- Name: FUNCTION fn_severity_rank(p_severity text); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_severity_rank(p_severity text) IS 'Maps severity string to rank 0-3 for cooldown escalation logic. info/low=0, warning/medium=1, error/high=2, critical=3.';


--
-- Name: fn_should_apply_kill_switch(text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_should_apply_kill_switch(p_switch_name text, p_bucket_key text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
DECLARE
  v_row RECORD;
  v_bucket_hash int;
BEGIN
  SELECT enabled, rollout_percentage
  INTO v_row
  FROM zapp.system_kill_switches
  WHERE switch_name = p_switch_name;

  IF NOT FOUND OR v_row.enabled THEN
    RETURN false;
  END IF;

  IF v_row.rollout_percentage >= 100 THEN
    RETURN true;
  END IF;

  IF v_row.rollout_percentage <= 0 THEN
    RETURN false;
  END IF;

  v_bucket_hash := abs(hashtext(p_switch_name || ':' || p_bucket_key)) % 100;
  RETURN v_bucket_hash < v_row.rollout_percentage;
END;
$$;


--
-- Name: fn_snapshot_constraints_reference(text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_snapshot_constraints_reference(p_version text DEFAULT NULL::text, p_generated_by text DEFAULT 'system_cron'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_content text; v_hash text; v_prev record; v_drift jsonb;
  v_is_new_version boolean := false; v_new_id uuid;
  v_version text; v_lines int;
BEGIN
  v_content := fn_generate_constraints_reference();
  v_hash := encode(extensions.digest(v_content::bytea, 'sha256'), 'hex');
  v_lines := length(v_content) - length(replace(v_content, E'\n', '')) + 1;
  v_version := COALESCE(p_version, 'auto-' || to_char(now(), 'YYYYMMDD-HH24MI'));
  
  SELECT content_hash, version, generated_at INTO v_prev
  FROM zapp.system_docs
  WHERE doc_name = 'EVOLUTION_DB_CONSTRAINTS_REFERENCE'
  ORDER BY generated_at DESC LIMIT 1;
  
  IF v_prev.content_hash IS NULL THEN
    v_drift := jsonb_build_object('type', 'initial_snapshot', 'is_drift', false);
    v_is_new_version := true;
  ELSIF v_prev.content_hash = v_hash THEN
    v_drift := jsonb_build_object('type', 'identical', 'is_drift', false,
      'previous_version', v_prev.version, 'previous_generated_at', v_prev.generated_at);
  ELSE
    v_drift := jsonb_build_object('type', 'content_changed', 'is_drift', true,
      'previous_version', v_prev.version, 'previous_generated_at', v_prev.generated_at,
      'previous_hash', substring(v_prev.content_hash, 1, 12),
      'new_hash', substring(v_hash, 1, 12),
      'time_since_last', age(now(), v_prev.generated_at)::text);
    v_is_new_version := true;
  END IF;
  
  IF v_is_new_version THEN
    INSERT INTO zapp.system_docs (
      doc_name, version, content, content_hash,
      generated_by, total_lines, drift_from_previous
    ) VALUES (
      'EVOLUTION_DB_CONSTRAINTS_REFERENCE', v_version, v_content, v_hash,
      p_generated_by, v_lines, v_drift
    )
    ON CONFLICT (doc_name, content_hash) DO NOTHING
    RETURNING id INTO v_new_id;
  END IF;
  
  RETURN jsonb_build_object(
    'saved', v_new_id IS NOT NULL,
    'is_new_version', v_is_new_version,
    'new_version_id', v_new_id,
    'version', v_version,
    'hash', substring(v_hash, 1, 16),
    'content_size_bytes', length(v_content),
    'total_lines', v_lines,
    'drift', v_drift
  );
END;
$$;


--
-- Name: fn_sticker_stats(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_sticker_stats() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
BEGIN
  RETURN (
    SELECT jsonb_build_object(
      'ok', true,
      'total_stickers', (SELECT count(*) FROM stickers WHERE is_active),
      'total_categories', (SELECT count(*) FROM sticker_categories WHERE is_active),
      'categories_with_stickers', (SELECT count(DISTINCT category) FROM stickers WHERE is_active),
      'total_animated', (SELECT count(*) FROM stickers WHERE is_animated AND is_active),
      'total_favorites_global', (SELECT count(*) FROM sticker_favorites),
      'total_use_count', (SELECT COALESCE(sum(use_count),0) FROM stickers),
      'bucket_name', 'stickers',
      'storage_type', 'Supabase Cloud (legado) - migracao R2 pendente',
      'top_categories', (
        SELECT jsonb_agg(jsonb_build_object(
          'slug', sc.slug, 'label', sc.label_pt, 'emoji', sc.emoji, 'count', sc.sticker_count
        ) ORDER BY sc.sticker_count DESC)
        FROM sticker_categories sc WHERE sc.sticker_count > 0
      )
    )
  );
END;
$$;


