--
-- Name: fn_sticky_on_contact_assign(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_sticky_on_contact_assign() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_profile_id uuid;
BEGIN
  IF NEW.assigned_to IS NULL THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.assigned_to IS NOT DISTINCT FROM OLD.assigned_to THEN
    RETURN NEW;
  END IF;

  SELECT id INTO v_profile_id FROM zapp.profiles WHERE user_id = NEW.assigned_to LIMIT 1;
  IF v_profile_id IS NULL THEN RETURN NEW; END IF;

  PERFORM zapp.fn_sticky_upsert(NEW.id, v_profile_id, NULL, NULL, 'contact_assignment');
  RETURN NEW;
END;
$$;


--
-- Name: sticky_assignments; Type: TABLE; Schema: zapp; Owner: -
--

CREATE TABLE zapp.sticky_assignments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    contact_id uuid NOT NULL,
    channel_connection_id uuid,
    agent_profile_id uuid NOT NULL,
    queue_id uuid,
    last_assigned_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone DEFAULT (now() + '24:00:00'::interval) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: fn_sticky_upsert(uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_sticky_upsert(p_contact_id uuid, p_agent_profile_id uuid, p_channel_id uuid DEFAULT NULL::uuid, p_queue_id uuid DEFAULT NULL::uuid, p_source text DEFAULT 'manual'::text) RETURNS zapp.sticky_assignments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_ttl_hours int := 24;
  v_enabled boolean := true;
  v_row zapp.sticky_assignments;
BEGIN
  IF p_contact_id IS NULL OR p_agent_profile_id IS NULL THEN
    RETURN NULL;
  END IF;

  -- Lê TTL/enabled do canal (se informado)
  IF p_channel_id IS NOT NULL THEN
    SELECT sticky_enabled, COALESCE(sticky_ttl_hours, 24)
      INTO v_enabled, v_ttl_hours
      FROM zapp.service_channels
     WHERE id = p_channel_id;

    IF NOT COALESCE(v_enabled, true) THEN
      RETURN NULL;
    END IF;
  END IF;

  INSERT INTO zapp.sticky_assignments AS sa
    (contact_id, agent_profile_id, queue_id, last_assigned_at, expires_at)
  VALUES
    (p_contact_id, p_agent_profile_id, p_queue_id, now(),
     now() + make_interval(hours => v_ttl_hours))
  ON CONFLICT (contact_id) DO UPDATE
    SET agent_profile_id = EXCLUDED.agent_profile_id,
        queue_id         = COALESCE(EXCLUDED.queue_id, sa.queue_id),
        last_assigned_at = now(),
        expires_at       = now() + make_interval(hours => v_ttl_hours)
  RETURNING * INTO v_row;

  -- Audit best-effort
  BEGIN
    INSERT INTO zapp.audit_log(actor_user_id, action, entity_type, entity_id, payload)
    VALUES (auth.uid(), 'sticky.upsert', 'sticky_assignment', v_row.id,
            jsonb_build_object('source', p_source, 'agent', p_agent_profile_id,
                               'channel', p_channel_id, 'queue', p_queue_id,
                               'expires_at', v_row.expires_at));
  EXCEPTION WHEN undefined_table THEN NULL;
  END;

  RETURN v_row;
END;
$$;


--
-- Name: fn_storage_audit(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_storage_audit() RETURNS TABLE(risk text, bucket text, policy_name text, cmd text, roles text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'zapp', 'storage', 'pg_catalog'
    AS $$
  SELECT 
    CASE 
      WHEN p.roles::text ILIKE '%anon%' AND p.cmd IN ('INSERT','UPDATE','DELETE') THEN 'CRITICAL'
      WHEN p.roles::text ILIKE '%public%' AND p.cmd IN ('INSERT','UPDATE','DELETE') 
           AND p.qual NOT LIKE '%auth.uid()%' THEN 'HIGH'
      WHEN p.roles::text ILIKE '%anon%' AND p.cmd = 'SELECT' 
           AND b.public = false THEN 'MEDIUM'
      ELSE 'OK'
    END AS risk,
    b.name AS bucket,
    p.policyname AS policy_name,
    p.cmd,
    p.roles::text
  FROM pg_policies p
  JOIN storage.buckets b ON b.id = split_part(p.qual, '''', 2)
  WHERE p.schemaname = 'storage' AND p.tablename = 'objects'
    AND (
      (p.roles::text ILIKE '%anon%' AND b.public = false)
      OR (p.roles::text ILIKE '%public%' AND p.cmd IN ('INSERT','UPDATE','DELETE') AND p.qual NOT LIKE '%auth.uid()%')
    )
  ORDER BY 1, 2;
$$;


