--
-- Name: fn_trg_auto_security_invoker(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_trg_auto_security_invoker() RETURNS event_trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
DECLARE obj record; v_schema text; v_name text;
BEGIN
  FOR obj IN SELECT * FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE VIEW','ALTER VIEW','CREATE OR REPLACE VIEW')
      AND object_type = 'view'
  LOOP
    v_schema := split_part(obj.object_identity, '.', 1);
    v_name   := split_part(obj.object_identity, '.', 2);
    IF v_schema IN ('public','zapp','evo','artes','financeiro','monitoring','ops','vendas','email_app','ai','bpm','archive','logistica') THEN
      BEGIN
        IF NOT EXISTS (
          SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
          WHERE n.nspname = v_schema AND c.relname = v_name AND c.relkind = 'v'
            AND c.reloptions IS NOT NULL
            AND array_to_string(c.reloptions, ',') ILIKE '%security_invoker%'
        ) THEN
          EXECUTE format('ALTER VIEW %I.%I SET (security_invoker = true)', v_schema, v_name);
        END IF;
      EXCEPTION WHEN OTHERS THEN NULL;
      END;
    END IF;
  END LOOP;
END;
$$;


--
-- Name: fn_trg_gate_require_scan(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_trg_gate_require_scan() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Quando worker tenta marcar como done, verificar se scan foi feito
  IF NEW.status = 'done' AND OLD.status != 'done' THEN
    IF NEW.scan_status = 'pending_scan' OR NEW.scan_status IS NULL THEN
      -- Forçar scan antes de liberar
      NEW.scan_status := 'pending_scan';
      -- Registrar tentativa
      INSERT INTO media_scan_log (message_id, instance_name, scan_type, scan_result, details)
      VALUES (NEW.message_id, NEW.instance_name, 'mimetype_check', 'warning', 'Worker tentou done sem scan - pendente');
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION fn_trg_gate_require_scan(); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_trg_gate_require_scan() IS 'Gate: registra warning quando worker marca done sem scan ClamAV';


--
-- Name: fn_trg_quarantine_alert(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_trg_quarantine_alert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO media_security_alerts (alert_type, severity, title, details, message_id, instance_name)
  VALUES (
    CASE WHEN NEW.block_reason LIKE 'CLAMAV%' THEN 'virus_detected'
         WHEN NEW.block_reason LIKE 'FILE_TOO%' THEN 'size_exceeded'
         ELSE 'file_blocked' END,
    CASE WHEN NEW.block_reason LIKE 'CLAMAV%' THEN 'critical'
         WHEN NEW.block_reason LIKE 'MIMETYPE%' THEN 'high'
         ELSE 'medium' END,
    'Arquivo bloqueado: ' || COALESCE(NEW.original_mimetype, 'unknown') || ' ' || COALESCE(NEW.original_extension, ''),
    jsonb_build_object('block_reason', NEW.block_reason, 'mimetype', NEW.original_mimetype, 'extension', NEW.original_extension, 'file_size', NEW.file_size_bytes, 'remote_jid', NEW.remote_jid),
    NEW.message_id,
    NEW.instance_name
  );
  PERFORM pg_notify('media_security', json_build_object('type', 'file_blocked', 'message_id', NEW.message_id, 'reason', NEW.block_reason)::text);
  RETURN NEW;
END;
$$;


--
-- Name: fn_trg_security_check_media_queue(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_trg_security_check_media_queue() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $_$
DECLARE
  v_result JSONB;
  v_ext TEXT;
BEGIN
  -- Extract extension from direct_path
  v_ext := regexp_replace(COALESCE(NEW.direct_path, ''), '^.*\.([a-zA-Z0-9]+)(\?.*)?$', '.\1');
  IF v_ext = NEW.direct_path THEN v_ext := NULL; END IF;

  v_result := fn_validate_media_security(
    p_mimetype := NEW.mimetype,
    p_extension := v_ext,
    p_file_size := NEW.file_length,           -- FIX 11/06/2026: regra max_file_size estava morta na camada 1
    p_message_id := NEW.message_id,
    p_instance := NEW.instance_name,
    p_remote_jid := NEW.remote_jid,
    p_media_meta := jsonb_build_object('media_key', NEW.media_key, 'direct_path', NEW.direct_path)
  );

  IF NOT (v_result->>'allowed')::boolean THEN
    NEW.status := 'blocked';
    NEW.scan_status := 'blocked';             -- FIX 11/06/2026: ficava pending_scan para sempre
    NEW.scan_result := v_result->>'reasons';
    NEW.scanned_at := now();
    NEW.error_message := v_result->>'reasons';
  END IF;

  RETURN NEW;
END;
$_$;


