--
-- Name: fn_update_audio_meme_category_count(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_update_audio_meme_category_count() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE audio_meme_categories SET meme_count = meme_count + 1 WHERE slug = NEW.category;
  ELSIF TG_OP = 'DELETE' THEN
    UPDATE audio_meme_categories SET meme_count = GREATEST(meme_count - 1, 0) WHERE slug = OLD.category;
  ELSIF TG_OP = 'UPDATE' AND OLD.category IS DISTINCT FROM NEW.category THEN
    UPDATE audio_meme_categories SET meme_count = GREATEST(meme_count - 1, 0) WHERE slug = OLD.category;
    UPDATE audio_meme_categories SET meme_count = meme_count + 1 WHERE slug = NEW.category;
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;


