--
-- Name: fn_update_redis_sentinel(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_update_redis_sentinel() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'ops'
    AS $$
DECLARE v_result jsonb;
BEGIN
  -- Chamar o Redis health check via Evolution API info endpoint
  -- Como nao temos acesso direto ao Redis via SQL, usamos a tabela sentinel
  -- atualizada pelo watchdog externo. Esta funcao apenas valida se o sentinel esta fresco.
  SELECT jsonb_build_object(
    'sentinel_age_min', round(EXTRACT(EPOCH FROM (now()-last_ping_at))/60,1),
    'is_fresh', last_ping_at > NOW()-INTERVAL '10 minutes',
    'mem_pct', round(100.0*used_memory_mb/NULLIF(maxmemory_mb,0),1)
  ) INTO v_result FROM ops.redis_sentinel WHERE id=1;
  RETURN COALESCE(v_result, '{"error":"no_sentinel"}'::jsonb);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('error', SQLERRM);
END;
$$;


--
-- Name: fn_update_sticker_category_count(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_update_sticker_category_count() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE sticker_categories SET sticker_count = sticker_count + 1 WHERE slug = NEW.category;
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    UPDATE sticker_categories SET sticker_count = GREATEST(sticker_count - 1, 0) WHERE slug = OLD.category;
    RETURN OLD;
  ELSIF TG_OP = 'UPDATE' AND OLD.category != NEW.category THEN
    UPDATE sticker_categories SET sticker_count = GREATEST(sticker_count - 1, 0) WHERE slug = OLD.category;
    UPDATE sticker_categories SET sticker_count = sticker_count + 1 WHERE slug = NEW.category;
    RETURN NEW;
  END IF;
  RETURN NEW;
END;
$$;


