--
-- Name: fn_vacuum_critical_tables(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_vacuum_critical_tables() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
DECLARE
  v_tables text[] := ARRAY[
    'zapp.webhook_events_processed','zapp.webhook_audit_log','zapp.app_notifications',
    'zapp.webhook_rate_limits','zapp.instance_registry','zapp.profiles',
    'zapp.empresas','logistica.cotacoes','evo.evolution_alerts'
  ];
  v_tbl text;
  v_vacuumed int := 0;
  v_errors text[] := ARRAY[]::text[];
BEGIN
  FOREACH v_tbl IN ARRAY v_tables LOOP
    BEGIN
      PERFORM dblink_exec(
        'host=localhost port=5432 user=postgres dbname=postgres',
        'VACUUM ANALYZE '||v_tbl,
        true
      );
      v_vacuumed := v_vacuumed + 1;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors || (v_tbl||': '||SQLERRM);
    END;
  END LOOP;
  RETURN jsonb_build_object(
    'vacuumed', v_vacuumed,
    'total', array_length(v_tables,1),
    'errors', to_jsonb(v_errors),
    'executed_at', now()
  );
END;
$$;


--
-- Name: FUNCTION fn_vacuum_critical_tables(); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_vacuum_critical_tables() IS 'FIX P1 (2026-08-06): substituído zapp.cotacoes (inexistente) por logistica.cotacoes no array de tabelas a serem vacuadas. A função tem EXCEPTION handler, então a tabela errada causava falha silenciosa sem vacuum real.';


--
-- Name: fn_validate_audit_vocabulary(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_validate_audit_vocabulary() RETURNS TABLE(action_text text, fonte text, permitida boolean, qtd_inserts integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_actions_permitted TEXT[] := ARRAY[
    'create','read','update','delete','created','updated','deleted',
    'soft_delete','hard_delete','restore','merge','split',
    'archive','unarchive','archived','unarchived',
    'view','export','import','login','logout',
    'send_message','receive_message','template_sent',
    'stage_change','deal_created','deal_closed','deal_lost',
    'complete','reopen','assign','unassign',
    'label_applied','label_removed','label_mapped_to_stage',
    'associate_label','disassociate_label','label_sync',
    'webhook_cleanup','data_cleanup','gc',
    'webhook_received','webhook_processed','webhook_failed',
    'bitrix_sync','bitrix_push','bitrix_pull'
  ];
BEGIN
  RETURN QUERY
  SELECT action::text, 'audit_log_registros'::text,
    (action = ANY(v_actions_permitted)),
    COUNT(*)::int
  FROM zapp.evolution_audit_log
  GROUP BY action
  ORDER BY (action = ANY(v_actions_permitted)), COUNT(*) DESC;
END;
$$;


--
-- Name: fn_validate_media_security(text, text, bigint, text, text, text, uuid, jsonb); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_validate_media_security(p_mimetype text, p_extension text DEFAULT NULL::text, p_file_size bigint DEFAULT NULL::bigint, p_message_id text DEFAULT NULL::text, p_instance text DEFAULT 'wpp_pink_test'::text, p_remote_jid text DEFAULT NULL::text, p_contact_id uuid DEFAULT NULL::uuid, p_media_meta jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
DECLARE
  v_rule      RECORD;
  v_max_size  BIGINT;
  v_blocked   BOOLEAN := false;
  v_reasons   TEXT[]  := '{}';
  v_severity  TEXT    := 'clean';
  v_ext       TEXT;
  v_scan_result TEXT;
BEGIN
  v_ext := COALESCE(p_extension, '');
  IF v_ext != '' AND left(v_ext, 1) != '.' THEN v_ext := '.' || v_ext; END IF;
  v_ext := lower(v_ext);

  FOR v_rule IN
    SELECT * FROM zapp.media_security_config
    WHERE rule_type='blocked_mimetype' AND is_active
      AND lower(rule_value) = lower(COALESCE(p_mimetype,''))
  LOOP
    v_blocked := v_rule.severity = 'block';
    v_severity := v_rule.severity;
    v_scan_result := CASE WHEN v_rule.severity='block' THEN 'blocked'
                          WHEN v_rule.severity='warn' THEN 'warning' ELSE 'clean' END;
    v_reasons := array_append(v_reasons, 'MIMETYPE_BLOCKED: '||p_mimetype);
    INSERT INTO zapp.media_scan_log (message_id,instance_name,scan_type,scan_result,details)
    VALUES (p_message_id,p_instance,'mimetype_check',v_scan_result,p_mimetype||' -> '||v_rule.description);
    IF v_blocked THEN
      INSERT INTO zapp.media_quarantine (message_id,instance_name,remote_jid,contact_id,
        original_mimetype,original_extension,file_size_bytes,media_meta,block_reason,rule_id,severity)
      VALUES (p_message_id,p_instance,p_remote_jid,p_contact_id,p_mimetype,v_ext,
        p_file_size,p_media_meta,'MIMETYPE_BLOCKED: '||p_mimetype,v_rule.id,v_rule.severity);
    END IF;
  END LOOP;

  IF v_ext != '' AND NOT v_blocked THEN
    FOR v_rule IN
      SELECT * FROM zapp.media_security_config
      WHERE rule_type='blocked_extension' AND is_active AND lower(rule_value)=v_ext
    LOOP
      v_blocked := v_rule.severity = 'block';
      IF v_rule.severity='block' OR v_severity='clean' THEN v_severity := v_rule.severity; END IF;
      v_scan_result := CASE WHEN v_rule.severity='block' THEN 'blocked'
                            WHEN v_rule.severity='warn' THEN 'warning' ELSE 'clean' END;
      v_reasons := array_append(v_reasons, 'EXTENSION_BLOCKED: '||v_ext);
      INSERT INTO zapp.media_scan_log (message_id,instance_name,scan_type,scan_result,details)
      VALUES (p_message_id,p_instance,'extension_check',v_scan_result,v_ext||' -> '||v_rule.description);
      IF v_blocked THEN
        INSERT INTO zapp.media_quarantine (message_id,instance_name,remote_jid,contact_id,
          original_mimetype,original_extension,file_size_bytes,media_meta,block_reason,rule_id,severity)
        VALUES (p_message_id,p_instance,p_remote_jid,p_contact_id,p_mimetype,v_ext,
          p_file_size,p_media_meta,'EXTENSION_BLOCKED: '||v_ext,v_rule.id,v_rule.severity);
      END IF;
    END LOOP;
  END IF;

  IF p_file_size IS NOT NULL AND NOT v_blocked THEN
    SELECT rule_value::bigint INTO v_max_size
    FROM zapp.media_security_config
    WHERE rule_type='max_file_size' AND is_active LIMIT 1;
    IF v_max_size IS NOT NULL AND p_file_size > v_max_size THEN
      v_blocked := true; v_severity := 'block';
      v_reasons := array_append(v_reasons,'FILE_TOO_LARGE: '||p_file_size||' bytes');
      INSERT INTO zapp.media_scan_log (message_id,instance_name,scan_type,scan_result,details)
      VALUES (p_message_id,p_instance,'size_check','blocked',p_file_size||' > '||v_max_size);
      INSERT INTO zapp.media_quarantine (message_id,instance_name,remote_jid,contact_id,
        original_mimetype,original_extension,file_size_bytes,media_meta,block_reason,severity)
      VALUES (p_message_id,p_instance,p_remote_jid,p_contact_id,p_mimetype,v_ext,
        p_file_size,p_media_meta,'FILE_TOO_LARGE: '||p_file_size||' bytes','block');
    END IF;
  END IF;

  IF v_severity='clean' THEN
    INSERT INTO zapp.media_scan_log (message_id,instance_name,scan_type,scan_result,details)
    VALUES (p_message_id,p_instance,'mimetype_check','clean',COALESCE(p_mimetype,'unknown'));
  END IF;

  RETURN jsonb_build_object('allowed',NOT v_blocked,'severity',v_severity,
    'reasons',to_jsonb(v_reasons),'mimetype',p_mimetype,'extension',v_ext,'file_size',p_file_size);
END;
$$;


--
-- Name: fn_validate_whatsapp_connection_url(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_validate_whatsapp_connection_url() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog, zapp, vault'
    AS $$
DECLARE
  v_allowed_url TEXT;
BEGIN
  IF NEW.api_type = 'official' THEN
    RETURN NEW;
  END IF;
  BEGIN
    SELECT decrypted_secret
      INTO v_allowed_url
      FROM vault.decrypted_secrets
     WHERE name = 'evolution_api_url'
     LIMIT 1;
  EXCEPTION WHEN undefined_table OR invalid_schema_name THEN
    RAISE EXCEPTION 'fn_validate_whatsapp_connection_url: vault indisponível — INSERT rejeitado'
      USING ERRCODE = '42501';
  END;
  IF v_allowed_url IS NULL OR v_allowed_url = '' THEN
    RAISE EXCEPTION
      'fn_validate_whatsapp_connection_url: vault.evolution_api_url não configurado — '
      'INSERT rejeitado. Configure o secret antes de criar conexões.'
      USING ERRCODE = '42501';
  END IF;
  IF NEW.api_url IS DISTINCT FROM v_allowed_url THEN
    RAISE EXCEPTION 'api_url invalida — valor recebido não corresponde ao esperado (vault.evolution_api_url)'
      USING ERRCODE = '23514',
            DETAIL  = format('recebido: %s', NEW.api_url);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION fn_validate_whatsapp_connection_url(); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_validate_whatsapp_connection_url() IS 'BEFORE INSERT/UPDATE OF api_url trigger (M37/F6-12): validates api_url against vault.evolution_api_url. Fail-secure: RAISES when vault is empty or unavailable (no hardcoded fallback). Error message does not expose the expected URL. Exempts api_type=official (Meta Cloud API / Graph API endpoint).';


--
-- Name: fn_vault_healthcheck(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_vault_healthcheck() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  rec RECORD;
  v_decrypted text;
  v_ok int := 0;
  v_fail int := 0;
  v_defer int := 0;
  v_failed_names text[] := '{}';
BEGIN
  FOR rec IN SELECT name, description FROM vault.secrets ORDER BY name
  LOOP
    IF rec.description LIKE 'DEFER%' THEN
      v_defer := v_defer + 1;
    ELSE
      BEGIN
        SELECT decrypted_secret INTO v_decrypted FROM vault.decrypted_secrets WHERE name = rec.name;
        IF v_decrypted IS NOT NULL AND v_decrypted != '' THEN
          v_ok := v_ok + 1;
        ELSE
          v_fail := v_fail + 1;
          v_failed_names := v_failed_names || rec.name;
        END IF;
      EXCEPTION WHEN OTHERS THEN
        v_fail := v_fail + 1;
        v_failed_names := v_failed_names || rec.name;
      END;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'checked_at', now(),
    'ok', v_ok,
    'fail', v_fail,
    'defer', v_defer,
    'failed_names', to_jsonb(v_failed_names),
    'status', CASE WHEN v_fail = 0 THEN 'healthy' ELSE 'degraded' END
  );
END
$$;


--
-- Name: FUNCTION fn_vault_healthcheck(); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_vault_healthcheck() IS 'Onda 9.1 — retorna jsonb com ok/fail/defer/status. Read-only, safe pra polling.';


--
-- Name: fn_vault_healthcheck_cleanup(); Type: FUNCTION; Schema: zapp; Owner: -
--

