    LANGUAGE sql
    AS $$
  DELETE FROM zapp.vault_healthcheck_log WHERE checked_at < now() - interval '30 days';
$$;


--
-- Name: FUNCTION fn_vault_healthcheck_cleanup(); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_vault_healthcheck_cleanup() IS 'Onda 9.1 — retenção: deleta logs com mais de 30 dias.';


--
-- Name: fn_vault_healthcheck_run(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_vault_healthcheck_run() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  v_result := zapp.fn_vault_healthcheck();
  INSERT INTO zapp.vault_healthcheck_log (
    checked_at, status, ok_count, fail_count, defer_count, failed_names, full_result
  ) VALUES (
    (v_result->>'checked_at')::timestamptz,
    v_result->>'status',
    (v_result->>'ok')::int,
    (v_result->>'fail')::int,
    (v_result->>'defer')::int,
    ARRAY(SELECT jsonb_array_elements_text(v_result->'failed_names')),
    v_result
  );
END
$$;


--
-- Name: FUNCTION fn_vault_healthcheck_run(); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_vault_healthcheck_run() IS 'Onda 9.1 — wrapper invocado pelo cron. Executa o check e persiste em vault_healthcheck_log.';


--
-- Name: fn_wal_slot_lag_check(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.fn_wal_slot_lag_check(p_threshold_mb integer DEFAULT 200) RETURNS TABLE(slot_name text, lag_mb numeric, is_active boolean, exceeds_threshold boolean)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
  SELECT
    slot_name::TEXT,
    ROUND(pg_wal_lsn_diff(pg_current_wal_lsn(), confirmed_flush_lsn)
          / (1024.0 * 1024.0), 2) AS lag_mb,
    active AS is_active,
    ROUND(pg_wal_lsn_diff(pg_current_wal_lsn(), confirmed_flush_lsn)
          / (1024.0 * 1024.0), 2) > p_threshold_mb AS exceeds_threshold
  FROM pg_replication_slots
  WHERE slot_type = 'logical'
  ORDER BY lag_mb DESC NULLS LAST;
$$;


--
-- Name: FUNCTION fn_wal_slot_lag_check(p_threshold_mb integer); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.fn_wal_slot_lag_check(p_threshold_mb integer) IS 'Returns WAL lag in MB per logical replication slot. Slots exceeding p_threshold_mb flag exceeds_threshold=true. Monitor cainophile_kzabiv0d (Logflare) which was at 313 MB lag on 2026-07-24 with ~35 MB/day growth.';


