--
-- Name: get_channel_credentials(uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.get_channel_credentials(_connection_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  IF NOT is_admin_or_supervisor(auth.uid()) THEN
    RETURN NULL;
  END IF;
  RETURN (SELECT credentials FROM zapp.channel_connections WHERE id = _connection_id);
END;
$$;


--
-- Name: get_channel_credentials_safe(uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.get_channel_credentials_safe(p_channel_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  -- Only admins can access credentials
  IF NOT zapp.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Access denied: admin role required';
  END IF;
  
  RETURN (
    SELECT credentials 
    FROM zapp.channel_connections 
    WHERE id = p_channel_id
  );
END;
$$;


--
-- Name: get_companies_by_phones_batch(text[]); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.get_companies_by_phones_batch(p_phones text[]) RETURNS TABLE(phone text, company text, full_name text, lead_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  PERFORM zapp.fn_require_app_user();
  RETURN QUERY
SELECT ct.phone_number::text, ct.company::text, COALESCE(ct.full_name, ct.push_name)::text, ct.lead_status::text
FROM evo.evolution_contacts ct
WHERE ct.deleted_at IS NULL
  AND regexp_replace(COALESCE(ct.phone_number, ''), '\\D', '', 'g') = ANY (
    SELECT DISTINCT regexp_replace(COALESCE(p, ''), '\\D', '', 'g')
    FROM unnest(COALESCE(p_phones, '{}')) p
    WHERE length(regexp_replace(COALESCE(p, ''), '\\D', '', 'g')) >= 8
  )
LIMIT 1000;
END;
$$;


--
-- Name: FUNCTION get_companies_by_phones_batch(p_phones text[]); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.get_companies_by_phones_batch(p_phones text[]) IS 'Retorna dados de empresa/nome para um batch de phones normalizados. Usa idx_ec_phone_norm_batch via = ANY(subquery). LIMIT 1000. Fix 2026-08-05: CTE JOIN → = ANY para melhor uso de índice de expressão.';


--
-- Name: get_compliance_metrics(timestamp without time zone); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.get_compliance_metrics(snapshot_time timestamp without time zone DEFAULT now()) RETURNS TABLE(total_deleted integer, pending_deletion integer, already_anonymized integer, with_lgpd_consent integer, compliance_rate_pct numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog', 'auth'
    AS $$
BEGIN
  SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
  
  RETURN QUERY
  WITH deleted_contacts AS (
    SELECT id, pii_masked_at, lgpd_consent_at
    FROM evo.evolution_contacts
    WHERE deleted_at IS NOT NULL
  )
  SELECT 
    COUNT(*)::INT AS total_deleted,
    COUNT(*) FILTER (WHERE pii_masked_at IS NULL)::INT AS pending_deletion,
    COUNT(*) FILTER (WHERE pii_masked_at IS NOT NULL)::INT AS already_anonymized,
    COUNT(*) FILTER (WHERE lgpd_consent_at IS NOT NULL)::INT AS with_consent,
    ROUND(
      COUNT(*) FILTER (WHERE pii_masked_at IS NOT NULL)::NUMERIC / 
      NULLIF(COUNT(*), 0) * 100, 2
    )::NUMERIC AS compliance_rate_pct
  FROM deleted_contacts;
END;
$$;


--
-- Name: get_compliance_metrics_v2(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.get_compliance_metrics_v2() RETURNS TABLE(metric_name character varying, metric_value bigint, snapshot_fresh boolean, validated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    'total_contacts'::VARCHAR,
    COUNT(*)::BIGINT,
    validate_snapshot_freshness('contacts', get_snapshot_version('contacts')),
    now()
  FROM evo.evolution_contacts
  WHERE deleted_at IS NULL;
END;
$$;


