-- Name: get_connection_id_for_instance(text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.get_connection_id_for_instance(p_instance text) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
  SELECT id
  FROM zapp.whatsapp_connections
  WHERE instance_name = p_instance
    AND is_active = true
  ORDER BY last_connected_at DESC NULLS LAST, created_at DESC
  LIMIT 1;
$$;


--
-- Name: FUNCTION get_connection_id_for_instance(p_instance text); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.get_connection_id_for_instance(p_instance text) IS 'Retorna o connection_id ativo para uma instância. STABLE: planner avalia uma vez por instância distinta na query.';


