CREATE FUNCTION zapp.get_contact_stats(p_instance_name text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$ SELECT jsonb_build_object('instance', p_instance_name, 'total', count(*), 'ativos_30d', count(*) FILTER (WHERE last_message_at >= now()-interval '30 days'), 'novos_30d', count(*) FILTER (WHERE created_at >= now()-interval '30 days'), 'com_compra', count(*) FILTER (WHERE coalesce(total_purchases,0) > 0), 'atribuidos', count(*) FILTER (WHERE assigned_to IS NOT NULL), 'por_lead_status', coalesce((SELECT jsonb_object_agg(coalesce(lead_status,'sem_status'), qtd) FROM (SELECT lead_status, count(*) AS qtd FROM evo.evolution_contacts WHERE instance_name=p_instance_name AND deleted_at IS NULL GROUP BY 1) s), '{}'::jsonb)) FROM evo.evolution_contacts WHERE instance_name=p_instance_name AND deleted_at IS NULL $$;


