--
-- Name: get_lgpd_compliance_stats(text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.get_lgpd_compliance_stats(p_instance_name text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$ SELECT jsonb_build_object('instance', coalesce(p_instance_name,'todas'), 'total', count(*), 'com_consentimento', count(*) FILTER (WHERE lgpd_consent_at IS NOT NULL), 'opt_out', count(*) FILTER (WHERE lgpd_opt_out_at IS NOT NULL), 'exclusao_solicitada', count(*) FILTER (WHERE lgpd_deletion_requested_at IS NOT NULL), 'marketing_ok', count(*) FILTER (WHERE lgpd_marketing_consent IS TRUE), 'data_sharing_ok', count(*) FILTER (WHERE lgpd_data_sharing IS TRUE), 'profiling_ok', count(*) FILTER (WHERE lgpd_profiling IS TRUE), 'sem_registro_lgpd', count(*) FILTER (WHERE lgpd_consent_at IS NULL AND lgpd_opt_out_at IS NULL)) FROM evo.evolution_contacts WHERE deleted_at IS NULL AND (p_instance_name IS NULL OR instance_name=p_instance_name) $$;


--
