--
-- Name: get_page_via_cursor(character varying, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.get_page_via_cursor(p_cursor_id character varying, p_page_size integer DEFAULT 50) RETURNS TABLE(row_number integer, id uuid, name text, email text, phone text, deleted_at timestamp with time zone, next_cursor character varying)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_last_record_id UUID;
  v_user_id        UUID;
BEGIN
  v_user_id := auth.uid();

  SELECT last_record_id INTO v_last_record_id
  FROM _pagination_state
  WHERE cursor_id   = p_cursor_id
    AND created_by  = v_user_id
    AND expires_at  > NOW();

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invalid or expired cursor' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY WITH page_data AS (
    SELECT
      ROW_NUMBER() OVER (ORDER BY c.id)::INT AS row_num,
      c.id,
      c.name::TEXT,
      c.email::TEXT,
      c.phone::TEXT,
      c.deleted_at
    FROM zapp.contacts c
    WHERE c.deleted_at IS NULL
      AND (
        is_admin_or_supervisor(v_user_id)
        OR EXISTS (
          SELECT 1 FROM zapp.workspace_members wm WHERE wm.user_id = v_user_id
        )
      )
      AND CASE
        WHEN v_last_record_id IS NULL THEN TRUE
        ELSE c.id > v_last_record_id
      END
    ORDER BY c.id
    LIMIT p_page_size + 1
  )
  SELECT
    pd.row_num,
    pd.id,
    pd.name,
    pd.email,
    pd.phone,
    pd.deleted_at,
    CASE
      WHEN COUNT(*) OVER () > p_page_size
        THEN create_pagination_cursor('contacts', pd.id)
      ELSE NULL
    END::VARCHAR
  FROM page_data pd
  WHERE pd.row_num <= p_page_size;

  -- Cleanup expired cursors for this user
  DELETE FROM _pagination_state
  WHERE expires_at < NOW()
    AND created_by = v_user_id;
END;
$$;


--
-- Name: get_platform_health(text, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.get_platform_health(p_instance_name text DEFAULT NULL::text, p_days integer DEFAULT 1) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$ SELECT jsonb_build_object('contacts', jsonb_build_object('total_active', (SELECT count(*) FROM evo.evolution_contacts WHERE deleted_at IS NULL), 'new_today', (SELECT count(*) FROM evo.evolution_contacts WHERE created_at >= date_trunc('day', now()) AND deleted_at IS NULL), 'duplicates', (SELECT COALESCE(sum(n-1),0) FROM (SELECT count(*) n FROM evo.evolution_contacts WHERE deleted_at IS NULL AND phone_number IS NOT NULL GROUP BY phone_number HAVING count(*)>1) d), 'consent_rate_pct', 'n/a'), 'conversations', jsonb_build_object('open', (SELECT count(*) FROM evo.evolution_conversations WHERE status NOT IN ('closed','resolved') OR status IS NULL), 'closed_today', (SELECT count(*) FROM evo.evolution_conversations WHERE status IN ('closed','resolved') AND updated_at >= date_trunc('day', now())), 'unread', (SELECT COALESCE(sum(unread_count),0) FROM evo.evolution_conversations), 'bot_active', (SELECT count(*) FROM evo.evolution_conversations WHERE COALESCE(is_bot_active,false)), 'avg_response_s', NULL), 'messages', jsonb_build_object('total_today', (SELECT count(*) FROM evo.evolution_messages WHERE created_at >= date_trunc('day', now())), 'inbound_today', (SELECT count(*) FROM evo.evolution_messages WHERE created_at >= date_trunc('day', now()) AND COALESCE(from_me,false)=false), 'outbound_today', (SELECT count(*) FROM evo.evolution_messages WHERE created_at >= date_trunc('day', now()) AND COALESCE(from_me,false)=true), 'failed_today', (SELECT count(*) FROM zapp.failed_messages WHERE created_at >= date_trunc('day', now()))), 'webhooks', jsonb_build_object('total_events', (SELECT count(*) FROM evo.evolution_webhook_events WHERE created_at >= now() - make_interval(days => GREATEST(p_days,1))), 'processed_events', (SELECT count(*) FROM evo.evolution_webhook_events WHERE created_at >= now() - make_interval(days => GREATEST(p_days,1)) AND processed_at IS NOT NULL), 'pending_events', (SELECT count(*) FROM evo.evolution_webhook_events WHERE created_at >= now() - make_interval(days => GREATEST(p_days,1)) AND processed_at IS NULL), 'dlq_pending', (SELECT count(*) FROM zapp.failed_messages WHERE status IN ('pending','retrying'))), 'instance_name', COALESCE(p_instance_name,'all'), 'generated_at', now()::text) $$;


