CREATE FUNCTION zapp.grant_lgpd_consent(p_contact_id uuid, p_channel text, p_marketing_consent boolean DEFAULT true, p_data_sharing boolean DEFAULT false, p_profiling boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$ DECLARE v_ok int; BEGIN UPDATE evo.evolution_contacts SET lgpd_consent_at=now(), lgpd_consent_channel=p_channel, lgpd_marketing_consent=coalesce(p_marketing_consent,true), lgpd_data_sharing=coalesce(p_data_sharing,false), lgpd_profiling=coalesce(p_profiling,false), lgpd_opt_out_at=NULL, lgpd_last_updated_at=now(), version=coalesce(version,0)+1, updated_at=now() WHERE id=p_contact_id AND deleted_at IS NULL; GET DIAGNOSTICS v_ok = ROW_COUNT; IF v_ok=0 THEN RETURN jsonb_build_object('success',false,'message','contato nao encontrado'); END IF; INSERT INTO evo.evolution_audit_log (action, entity_type, entity_id, performed_by, performed_by_type, metadata, created_at) VALUES ('lgpd_consent_granted','contact',p_contact_id, coalesce(auth.uid()::text,'system'),'user', jsonb_build_object('channel',p_channel,'marketing',p_marketing_consent,'data_sharing',p_data_sharing,'profiling',p_profiling), now()); RETURN jsonb_build_object('success',true,'contact_id',p_contact_id); END $$;


