--
-- Name: is_admin_or_supervisor(uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.is_admin_or_supervisor(_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
BEGIN
  IF _user_id IS NULL THEN
    RETURN FALSE;
  END IF;

  RETURN EXISTS (
    SELECT 1 FROM zapp.user_roles
    WHERE user_id = _user_id
      AND role::TEXT IN ('dev', 'admin', 'manager', 'supervisor')
  ) OR EXISTS (
    SELECT 1 FROM zapp.workspace_members
    WHERE user_id = _user_id
      AND role IN ('admin', 'supervisor', 'owner')
  );
END;
$$;


