--
-- Name: is_feature_enabled(text, uuid, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.is_feature_enabled(p_flag_key text, p_user_id uuid DEFAULT NULL::uuid, p_user_role text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$ DECLARE v_flag zapp.feature_flags%ROWTYPE; v_hash bigint; BEGIN SELECT * INTO v_flag FROM zapp.feature_flags WHERE key = p_flag_key; IF NOT FOUND THEN RETURN false; END IF; IF NOT v_flag.enabled THEN RETURN false; END IF; IF v_flag.expires_at IS NOT NULL AND v_flag.expires_at < now() THEN RETURN false; END IF; IF p_user_id IS NOT NULL AND p_user_id = ANY(v_flag.blocked_user_ids) THEN RETURN false; END IF; IF p_user_id IS NOT NULL AND p_user_id = ANY(v_flag.allowed_user_ids) THEN RETURN true; END IF; IF p_user_role IS NOT NULL AND p_user_role = ANY(v_flag.allowed_roles) THEN RETURN true; END IF; IF v_flag.rollout_percentage > 0 AND v_flag.rollout_percentage < 100 AND p_user_id IS NOT NULL THEN v_hash := abs(hashtext(p_user_id::text)) % 100; IF v_hash < v_flag.rollout_percentage THEN RETURN true; END IF; RETURN false; END IF; IF v_flag.rollout_percentage = 100 THEN RETURN true; END IF; RETURN false; END; $$;


