--
-- Name: merge_contacts(uuid, uuid, jsonb); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.merge_contacts(p_primary_id uuid, p_secondary_id uuid, p_merged_fields jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp, evo, pg_temp'
    AS $$
DECLARE
  v_primary evo.evolution_contacts%ROWTYPE;
  v_secondary evo.evolution_contacts%ROWTYPE;
  v_notes_remapped integer := 0;
  v_tags_remapped integer := 0;
  v_assignments_remapped integer := 0;
BEGIN
  -- 1. Autorização
  IF NOT zapp.is_admin_or_supervisor() THEN
    RAISE EXCEPTION 'Apenas admin/supervisor pode mesclar contatos' USING ERRCODE = '42501';
  END IF;

  -- 2. Validar existência
  SELECT * INTO v_primary FROM evo.evolution_contacts WHERE id = p_primary_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Contato primário não encontrado: %', p_primary_id;
  END IF;

  SELECT * INTO v_secondary FROM evo.evolution_contacts WHERE id = p_secondary_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Contato secundário não encontrado: %', p_secondary_id;
  END IF;

  IF p_primary_id = p_secondary_id THEN
    RAISE EXCEPTION 'Não é possível mesclar um contato com ele mesmo';
  END IF;

  -- 3. Merge de campos: primário vence, secundário preenche vazios
  -- Campos de texto e enriquecimento
  UPDATE evo.evolution_contacts SET
    full_name     = COALESCE(NULLIF(v_primary.full_name, ''), NULLIF(v_secondary.full_name, '')),
    push_name     = COALESCE(NULLIF(v_primary.push_name, ''), NULLIF(v_secondary.push_name, '')),
    email         = COALESCE(v_primary.email, v_secondary.email),
    company       = COALESCE(NULLIF(v_primary.company, ''), NULLIF(v_secondary.company, '')),
    role_title    = COALESCE(NULLIF(v_primary.role_title, ''), NULLIF(v_secondary.role_title, '')),
    notes         = CASE
      WHEN v_primary.notes IS NOT NULL AND v_secondary.notes IS NOT NULL
      THEN v_primary.notes || E'\n\n--- Mesclado de ' || v_secondary.full_name || ' ---\n' || v_secondary.notes
      ELSE COALESCE(v_primary.notes, v_secondary.notes)
    END,
    whatsapp_labels = COALESCE(v_primary.whatsapp_labels, v_secondary.whatsapp_labels),
    tags           = COALESCE(v_primary.tags, v_secondary.tags),
    profile_picture_url = COALESCE(v_primary.profile_picture_url, v_secondary.profile_picture_url),
    -- Numéricos: soma ou mantém o maior
    lead_score     = COALESCE(v_primary.lead_score, 0) + COALESCE(v_secondary.lead_score, 0),
    total_messages = COALESCE(v_primary.total_messages, 0) + COALESCE(v_secondary.total_messages, 0),
    total_purchases = COALESCE(v_primary.total_purchases, 0) + COALESCE(v_secondary.total_purchases, 0),
    -- Lead: mantém o status mais avançado (primário)
    lead_status    = v_primary.lead_status,
    lead_source    = COALESCE(v_primary.lead_source, v_secondary.lead_source),
    -- Atribuição: mantém a do primário
    assigned_to    = v_primary.assigned_to,
    -- Datas: usa a mais antiga e a mais recente
    first_contact_at = LEAST(v_primary.first_contact_at, v_secondary.first_contact_at),
    last_message_at  = GREATEST(v_primary.last_message_at, v_secondary.last_message_at),
    -- LGPD: mantém consentimentos existentes
    lgpd_consent_at = COALESCE(v_primary.lgpd_consent_at, v_secondary.lgpd_consent_at),
    lgpd_marketing_consent = v_primary.lgpd_marketing_consent OR v_secondary.lgpd_marketing_consent,
    updated_at = NOW()
  WHERE id = p_primary_id;

  -- 4. Remapear dados relacionados (secundário → primário)
  -- Notas
  UPDATE zapp.contact_notes SET contact_id = p_primary_id WHERE contact_id = p_secondary_id;
  GET DIAGNOSTICS v_notes_remapped = ROW_COUNT;

  -- Tags
  UPDATE zapp.contact_tags SET contact_id = p_primary_id WHERE contact_id = p_secondary_id;
  GET DIAGNOSTICS v_tags_remapped = ROW_COUNT;

  -- Atribuições (só as não resolvidas)
  UPDATE zapp.contact_assignments SET contact_id = p_primary_id WHERE contact_id = p_secondary_id;
  GET DIAGNOSTICS v_assignments_remapped = ROW_COUNT;

  -- 5. Soft-delete do secundário com rastreabilidade
  UPDATE evo.evolution_contacts SET
    deleted_at = NOW(),
    deleted_reason = 'merged_into:' || p_primary_id::text,
    merge_source_id = p_primary_id,
    updated_at = NOW()
  WHERE id = p_secondary_id;

  -- 6. Registrar nota de auditoria no primário
  INSERT INTO zapp.contact_notes (contact_id, author_id, content, note_type)
  VALUES (
    p_primary_id,
    zapp.get_profile_id_for_user(auth.uid()),
    format('Contato mesclado: %s (ID: %s) → %s. Notas: %s, Tags: %s, Atribuições: %s.',
      COALESCE(v_secondary.full_name, v_secondary.push_name, 'sem nome'),
      p_secondary_id,
      COALESCE(v_primary.full_name, v_primary.push_name, 'sem nome'),
      v_notes_remapped, v_tags_remapped, v_assignments_remapped),
    'system'
  );

  RETURN jsonb_build_object(
    'merged', true,
    'primary_id', p_primary_id,
    'secondary_id', p_secondary_id,
    'notes_remapped', v_notes_remapped,
    'tags_remapped', v_tags_remapped,
    'assignments_remapped', v_assignments_remapped
  );
END;
$$;


--
-- Name: messages_instead_of_delete(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.messages_instead_of_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
BEGIN
  UPDATE evo.evolution_messages
  SET deleted_at = now(), updated_at = now()
  WHERE id = OLD.id
    AND instance_name = OLD.instance_name;  -- ← partition pruning
  RETURN OLD;
END;
$$;


--
-- Name: messages_update_trigger(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.messages_update_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
DECLARE
  v_status     text;
  v_deleted_at timestamptz;
BEGIN
  -- messages_update_trigger v3 — INFRA-01 (+ FIX #6-DB-A + GAP-1 + BUG-1 + GAP-2)

  -- PASSO 1: Normalização de status
  v_status := CASE
    WHEN NEW.status IS NOT DISTINCT FROM OLD.status                                        THEN OLD.status
    WHEN NEW.status IN ('sending', 'retrying', 'queued', 'processing', 'scheduled')        THEN 'pending'
    WHEN NEW.status IN ('failed_auth', 'failed_retries', 'error')                          THEN 'failed'
    WHEN NEW.status IS NULL OR NEW.status = ''                                             THEN OLD.status
    WHEN NEW.status NOT IN ('received','sent','delivered','read','deleted','pending','played','failed')
                                                                                            THEN 'pending'
    ELSE NEW.status
  END;

  -- PASSO 2: Progression guard
  IF v_status IS DISTINCT FROM OLD.status THEN
    IF    OLD.status = 'deleted' THEN
      v_status := OLD.status;
    ELSIF OLD.status = 'read'      AND v_status NOT IN ('deleted','failed') THEN
      v_status := OLD.status;
    ELSIF OLD.status = 'played'    AND v_status IN ('received','pending','sent','delivered') THEN
      v_status := OLD.status;
    ELSIF OLD.status = 'delivered' AND v_status IN ('received','pending','sent') THEN
      v_status := OLD.status;
    ELSIF OLD.status = 'sent'      AND v_status IN ('received','pending') THEN
      v_status := OLD.status;
    END IF;
  END IF;

  -- PASSO 3: deleted_at automático
  v_deleted_at := CASE
    WHEN v_status = 'deleted' AND (OLD.status IS NULL OR OLD.status <> 'deleted') THEN now()
    ELSE NULL
  END;

  -- PASSO 4: Persistência com partition pruning via instance_name
  UPDATE evo.evolution_messages SET
    is_read    = COALESCE(NEW.is_read, OLD.is_read),
    status     = v_status,
    status_at  = CASE
                   WHEN v_status IS DISTINCT FROM OLD.status THEN COALESCE(NEW.status_updated_at::timestamptz, now())
                   ELSE status_at
                 END,
    content    = CASE WHEN NEW.content IS DISTINCT FROM OLD.content THEN NEW.content ELSE content END,
    deleted_at = CASE
                   WHEN v_deleted_at IS NOT NULL                                                          THEN v_deleted_at
                   WHEN NEW.is_deleted = true AND (OLD.is_deleted IS NULL OR OLD.is_deleted = false)      THEN COALESCE(NEW.whatsapp_timestamp, now())
                   WHEN NEW.is_deleted = false                                                             THEN NULL
                   ELSE deleted_at
                 END,
    updated_at = now()
  WHERE id = OLD.id AND instance_name = OLD.instance_name;

  -- PASSO 5: Propagar v_status normalizado para RETURNING
  NEW.status := v_status;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION messages_update_trigger(); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.messages_update_trigger() IS 'INSTEAD OF UPDATE trigger em zapp.messages (ordem=1 — action_order alphabetically first).
FIX #6-DB-A 2026-07-26: Adiciona normalização de status (sending→pending, failed_auth→failed, etc.)
para proteger contra valores inválidos vindos do messageSender.ts via UPDATE.';


--
-- Name: normalize_contact_phone(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.normalize_contact_phone() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.phone IS NOT NULL THEN
    NEW.phone := regexp_replace(NEW.phone, '[^0-9]', '', 'g');
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: normalize_contact_phone_sh(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.normalize_contact_phone_sh() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $_$
BEGIN
  IF NEW.phone_number IS NOT NULL THEN
    NEW.phone_number := regexp_replace(
      regexp_replace(NEW.phone_number, '[^\d+]', '', 'g'),
      '^(\d{10,11})$', '+55\1'
    );
  END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;
END;
$_$;


--
-- Name: normalize_input_nfkc(text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.normalize_input_nfkc(p_input text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_normalized TEXT;
BEGIN
  IF p_input IS NULL OR p_input = '' THEN
    RETURN '';
  END IF;

  SELECT normalized_text INTO v_normalized
  FROM _input_normalization_cache
  WHERE original_text = p_input;

  IF FOUND THEN
    UPDATE _input_normalization_cache
    SET cache_hits  = cache_hits + 1,
        accessed_at = NOW()
    WHERE original_text = p_input;
    RETURN v_normalized;
  END IF;

  -- PostgreSQL doesn't have built-in NFKC; best approximation: lower+trim
  v_normalized := LOWER(TRIM(p_input));

  INSERT INTO _input_normalization_cache (original_text, normalized_text)
  VALUES (p_input, v_normalized)
  ON CONFLICT (original_text) DO UPDATE SET
    cache_hits  = _input_normalization_cache.cache_hits + 1,
    accessed_at = NOW();

  -- Evict LRU entries beyond 1000 rows
  DELETE FROM _input_normalization_cache
  WHERE original_text IN (
    SELECT original_text FROM _input_normalization_cache
    ORDER BY accessed_at DESC, cached_at DESC
    OFFSET 1000
  );

  RETURN v_normalized;
END;
$$;


--
-- Name: normalize_phone_for_unique(text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.normalize_phone_for_unique(phone text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $_$
  SELECT CASE
    WHEN phone IS NULL THEN NULL
    ELSE (
      -- Strip non-digits
      regexp_replace(
        -- Remove country code 55
        CASE
          WHEN regexp_replace(phone, '[^0-9]', '', 'g') ~ '^55\d{10,11}$'
          THEN right(regexp_replace(phone, '[^0-9]', '', 'g'), -2)
          ELSE regexp_replace(phone, '[^0-9]', '', 'g')
        END,
        '[^0-9]', '', 'g'
      )
    )
  END
$_$;


--
-- Name: notify_sicoob_on_reply(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.notify_sicoob_on_reply() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'net', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  v_contact_type text;
  v_supabase_url text;
  v_resp bigint;
BEGIN
  IF NEW.sender = 'agent' AND NEW.channel_type = 'internal_chat' THEN
    SELECT contact_type INTO v_contact_type
    FROM zapp.contacts
    WHERE id = NEW.contact_id;

    IF v_contact_type = 'sicoob_gifts' THEN
      v_supabase_url := COALESCE(
        NULLIF(current_setting('app.settings.supabase_url', true), ''),
        'https://supabase.atomicabr.com.br'
      );

      BEGIN
        SELECT net.http_post(
          url := v_supabase_url || '/functions/v1/sicoob-bridge-reply',
          body := jsonb_build_object(
            'contact_id', NEW.contact_id,
            'content', NEW.content,
            'message_id', NEW.id,
            'agent_id', NEW.agent_id,
            'created_at', NEW.created_at
          ),
          headers := jsonb_build_object(
            'Content-Type', 'application/json',
            'Authorization', 'Bearer ' || current_setting('app.settings.service_role_key', true)
          )
        ) INTO v_resp;
      EXCEPTION WHEN OTHERS THEN
        -- Log falha mas NUNCA aborta o INSERT da mensagem
        RAISE WARNING '[notify_sicoob_on_reply] http_post falhou: % / %', SQLSTATE, SQLERRM;
      END;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION notify_sicoob_on_reply(); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.notify_sicoob_on_reply() IS 'DEPRECATED 2026-07-16: Fluxo Sicoob desativado. Função corrigida (net.http_post + EXCEPTION) mas sem trigger ativo. Reativar apenas se integração Sicoob for necessária. Tabelas sicoob_reply_outbox e sicoob_contact_mapping estão vazias.';


