--
-- Name: pause_instance(text, text, integer, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.pause_instance(p_instance text, p_reason text, p_minutes integer DEFAULT 15, p_trigger_count integer DEFAULT 0) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_id uuid;
BEGIN
  IF NOT zapp.is_admin_or_supervisor(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied: admin or supervisor role required';
  END IF;

  IF p_minutes <= 0 OR p_minutes > 1440 THEN
    RAISE EXCEPTION 'p_minutes must be between 1 and 1440';
  END IF;

  INSERT INTO zapp.instance_processing_pauses (
    instance_name, paused_until, reason, trigger_count, paused_by, auto_paused
  )
  VALUES (
    p_instance,
    now() + (p_minutes || ' minutes')::interval,
    COALESCE(NULLIF(trim(p_reason), ''), 'manual_pause'),
    GREATEST(0, COALESCE(p_trigger_count, 0)),
    auth.uid(),
    false
  )
  RETURNING id INTO v_id;

  INSERT INTO zapp.audit_logs (user_id, action, entity_type, entity_id, details)
  VALUES (
    auth.uid(),
    'instance_paused',
    'instance_processing_pauses',
    v_id::text,
    jsonb_build_object(
      'instance', p_instance,
      'minutes', p_minutes,
      'reason', p_reason,
      'trigger_count', p_trigger_count
    )
  );

  RETURN v_id;
END;
$$;


--
-- Name: pg_stat_database_simple(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.pg_stat_database_simple() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp, pg_temp'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  PERFORM zapp.fn_require_app_user();
  SELECT jsonb_build_object(
           'datname', datname,
           'numbackends', numbackends,
           'xact_commit', xact_commit,
           'xact_rollback', xact_rollback,
           'blks_read', blks_read,
           'blks_hit', blks_hit,
           'tup_returned', tup_returned,
           'tup_fetched', tup_fetched,
           'tup_inserted', tup_inserted,
           'tup_updated', tup_updated,
           'tup_deleted', tup_deleted,
           'sampled_at', now()
         )
  INTO v_result
  FROM pg_catalog.pg_stat_database
  WHERE datname = current_database();
  RETURN coalesce(v_result, '{}'::jsonb);
END;
$$;


--
-- Name: populate_contact_intelligence_batch(integer, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.populate_contact_intelligence_batch(p_batch_size integer DEFAULT 500, p_offset integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
DECLARE
  v_contact_id uuid;
  v_count      int := 0;
BEGIN
  FOR v_contact_id IN
    SELECT ec.id
    FROM evo.evolution_contacts ec
    LEFT JOIN zapp.contact_intelligence ci ON ci.contact_id = ec.id
    WHERE ec.deleted_at IS NULL
      AND ci.contact_id IS NULL   -- ainda não tem registro de CI
    ORDER BY ec.last_message_at DESC NULLS LAST
    LIMIT p_batch_size
    OFFSET p_offset
  LOOP
    PERFORM zapp.upsert_contact_intelligence(v_contact_id);
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;
$$;


--
-- Name: prevent_audit_modification(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.prevent_audit_modification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP != 'INSERT' THEN
    RAISE EXCEPTION 'Audit table is immutable - no % allowed', TG_OP
      USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: prevent_contact_id_reuse(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.prevent_contact_id_reuse() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
BEGIN
  IF NOT is_contact_id_available(NEW.id) THEN
    RAISE EXCEPTION 'Contact ID % was previously deleted and cannot be reused for 7 years', NEW.id
      USING ERRCODE = '23505';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: prevent_profile_privilege_escalation(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.prevent_profile_privilege_escalation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  -- If role, permissions, or access_level are being changed
  IF (OLD.role IS DISTINCT FROM NEW.role) OR 
     (OLD.permissions IS DISTINCT FROM NEW.permissions) OR 
     (OLD.access_level IS DISTINCT FROM NEW.access_level) THEN
    -- Only allow if user is admin or supervisor
    IF NOT is_admin_or_supervisor(auth.uid()) THEN
      RAISE EXCEPTION 'Only administrators can modify role, permissions, or access_level';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: prevent_role_escalation(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.prevent_role_escalation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  v_uid        uuid;
  v_blocked    text[] := '{}';
BEGIN
  -- service_role always permitted
  IF current_setting('request.jwt.claim.role', true) = 'service_role' THEN
    RETURN NEW;
  END IF;

  -- Resolve caller identity safely (NULL if no JWT context)
  BEGIN
    v_uid := auth.uid();
  EXCEPTION WHEN OTHERS THEN
    v_uid := NULL;
  END;

  -- Check role escalation
  IF OLD.role IS DISTINCT FROM NEW.role
     AND NOT COALESCE(zapp.is_admin_or_supervisor(v_uid), false) THEN
    v_blocked := array_append(v_blocked,
      format('role: %s -> %s',
        COALESCE(OLD.role,'null'), COALESCE(NEW.role,'null')));
    NEW.role := OLD.role;
  END IF;

  -- Check access_level escalation
  IF OLD.access_level IS DISTINCT FROM NEW.access_level
     AND NOT COALESCE(zapp.is_admin_or_supervisor(v_uid), false) THEN
    v_blocked := array_append(v_blocked,
      format('access_level: %s -> %s',
        COALESCE(OLD.access_level::text,'null'),
        COALESCE(NEW.access_level::text,'null')));
    NEW.access_level := OLD.access_level;
  END IF;

  -- Check permissions escalation
  IF OLD.permissions IS DISTINCT FROM NEW.permissions
     AND NOT COALESCE(zapp.is_admin_or_supervisor(v_uid), false) THEN
    v_blocked := array_append(v_blocked, 'permissions');
    NEW.permissions := OLD.permissions;
  END IF;

  -- If any violation: server-log (survives rollback) + audit + raise
  IF array_length(v_blocked, 1) > 0 THEN

    RAISE LOG 'PRIVILEGE_ESCALATION_BLOCKED | user=% | profile=% | fields=[%]',
      v_uid, OLD.id, array_to_string(v_blocked, ', ');

    BEGIN
      INSERT INTO zapp.audit_logs
        (id, action, entity_id, entity_type, user_id, details, event_type, status)
      VALUES (
        gen_random_uuid(),
        'PRIVILEGE_ESCALATION_BLOCKED',
        OLD.id,
        'profile',
        v_uid,
        jsonb_build_object(
          'blocked_fields', v_blocked,
          'old_role', OLD.role,
          'new_role_attempted', NEW.role,
          'trigger', TG_NAME,
          'table', TG_TABLE_SCHEMA || '.' || TG_TABLE_NAME
        ),
        'security',
        'blocked'
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;

    RAISE EXCEPTION 'PRIVILEGE_ESCALATION_BLOCKED: Unauthorized attempt on field(s) [%] for profile %. Operation aborted (42501).',
      array_to_string(v_blocked, ', '), OLD.id
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: purge_old_deleted_contacts(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.purge_old_deleted_contacts() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_count integer;
BEGIN
  -- Only purge contacts merged or deleted > 30 days ago
  DELETE FROM zapp.contacts
  WHERE deleted_at IS NOT NULL
    AND deleted_at < now() - interval '30 days';

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


--
-- Name: purge_old_query_telemetry(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.purge_old_query_telemetry(p_days integer DEFAULT 30) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_deleted integer;
BEGIN
  DELETE FROM zapp.query_telemetry
   WHERE created_at < now() - (p_days || ' days')::interval;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END;
$$;


--
-- Name: purge_webhook_logs(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.purge_webhook_logs() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
DECLARE v_deleted bigint := 0; v_batch bigint;
BEGIN
  LOOP
    DELETE FROM zapp.webhook_audit_log WHERE id IN (SELECT id FROM zapp.webhook_audit_log WHERE created_at < now() - interval '90 days' LIMIT 50000);
    GET DIAGNOSTICS v_batch = ROW_COUNT; v_deleted := v_deleted + v_batch;
    EXIT WHEN v_batch < 50000;
  END LOOP;
  LOOP
    DELETE FROM zapp.webhook_events_processed WHERE id IN (SELECT id FROM zapp.webhook_events_processed WHERE processed_at < now() - interval '30 days' LIMIT 50000);
    GET DIAGNOSTICS v_batch = ROW_COUNT; v_deleted := v_deleted + v_batch;
    EXIT WHEN v_batch < 50000;
  END LOOP;
  INSERT INTO ops.maintenance_log (job, details, ran_at) VALUES ('purge_webhook_logs', jsonb_build_object('deleted_rows', v_deleted), now()) ON CONFLICT DO NOTHING;
END $$;


--
-- Name: rate_limit_reset_requests(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rate_limit_reset_requests() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_pending_count integer;
BEGIN
  SELECT COUNT(*) INTO v_pending_count
  FROM zapp.password_reset_requests
  WHERE user_id = NEW.user_id
    AND status = 'pending'
    AND created_at > now() - interval '1 hour';

  IF v_pending_count >= 3 THEN
    RAISE EXCEPTION 'Too many pending reset requests. Please wait before trying again.';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: reassign_absent_agents(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.reassign_absent_agents(inactive_minutes integer DEFAULT 30) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_absent RECORD;
  v_new_agent UUID;
  v_reassigned INTEGER := 0;
  v_contact RECORD;
BEGIN
  IF NOT zapp.is_admin_or_supervisor() THEN
    RAISE EXCEPTION 'Acesso negado: requer admin ou supervisor' USING ERRCODE = '42501';
  END IF;

  FOR v_absent IN
    SELECT p.id AS agent_id
    FROM profiles p
    WHERE p.is_active = true
      AND p.last_seen_at IS NOT NULL
      AND p.last_seen_at < now() - (inactive_minutes || ' minutes')::interval
      AND EXISTS (SELECT 1 FROM contacts c WHERE c.assigned_to = p.id)
  LOOP
    FOR v_contact IN
      SELECT c.id, c.queue_id
      FROM contacts c
      WHERE c.assigned_to = v_absent.agent_id
    LOOP
      SELECT qm.profile_id INTO v_new_agent
      FROM queue_members qm
      JOIN profiles p ON p.id = qm.profile_id
      WHERE (v_contact.queue_id IS NULL OR qm.queue_id = v_contact.queue_id)
        AND qm.is_active = true
        AND p.is_active = true
        AND p.id != v_absent.agent_id
        AND (p.last_seen_at IS NULL OR p.last_seen_at > now() - (inactive_minutes || ' minutes')::interval)
      ORDER BY (
        SELECT COUNT(*) FROM contacts cc WHERE cc.assigned_to = qm.profile_id
      ) ASC
      LIMIT 1;

      IF v_new_agent IS NOT NULL THEN
        UPDATE contacts SET assigned_to = v_new_agent WHERE id = v_contact.id;

        INSERT INTO conversation_events (contact_id, event_type, from_agent_id, to_agent_id, metadata)
        VALUES (v_contact.id, 'absence_reassign', v_absent.agent_id, v_new_agent,
                jsonb_build_object('reason', 'agent_inactive', 'inactive_minutes', inactive_minutes));

        v_reassigned := v_reassigned + 1;
      END IF;
    END LOOP;
  END LOOP;

  RETURN v_reassigned;
END;
$$;


--
-- Name: reassign_overloaded_agents(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.reassign_overloaded_agents() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_overloaded RECORD;
  v_new_agent UUID;
  v_reassigned INTEGER := 0;
  v_contact RECORD;
BEGIN
  IF NOT zapp.is_admin_or_supervisor() THEN
    RAISE EXCEPTION 'Acesso negado: requer admin ou supervisor' USING ERRCODE = '42501';
  END IF;

  FOR v_overloaded IN
    SELECT p.id AS agent_id, p.max_chats,
           COUNT(c.id) AS current_chats
    FROM profiles p
    JOIN contacts c ON c.assigned_to = p.id
    WHERE p.is_active = true
      AND p.max_chats IS NOT NULL
      AND p.max_chats > 0
    GROUP BY p.id, p.max_chats
    HAVING COUNT(c.id) > p.max_chats
  LOOP
    FOR v_contact IN
      SELECT c.id, c.queue_id
      FROM contacts c
      WHERE c.assigned_to = v_overloaded.agent_id
      ORDER BY c.updated_at ASC
      LIMIT (v_overloaded.current_chats - v_overloaded.max_chats)
    LOOP
      SELECT qm.profile_id INTO v_new_agent
      FROM queue_members qm
      JOIN profiles p ON p.id = qm.profile_id
      WHERE (v_contact.queue_id IS NULL OR qm.queue_id = v_contact.queue_id)
        AND qm.is_active = true
        AND p.is_active = true
        AND p.id != v_overloaded.agent_id
        AND (p.max_chats IS NULL OR (
          SELECT COUNT(*) FROM contacts cc WHERE cc.assigned_to = p.id
        ) < p.max_chats)
      ORDER BY (
        SELECT COUNT(*) FROM contacts cc WHERE cc.assigned_to = qm.profile_id
      ) ASC
      LIMIT 1;

      IF v_new_agent IS NOT NULL THEN
        UPDATE contacts SET assigned_to = v_new_agent WHERE id = v_contact.id;

        INSERT INTO conversation_events (contact_id, event_type, from_agent_id, to_agent_id, metadata)
        VALUES (v_contact.id, 'overload_reassign', v_overloaded.agent_id, v_new_agent,
                jsonb_build_object('reason', 'max_chats_exceeded', 'max_chats', v_overloaded.max_chats));

        v_reassigned := v_reassigned + 1;
      END IF;
    END LOOP;
  END LOOP;

  RETURN v_reassigned;
END;
$$;


--
-- Name: reassign_overloaded_agents(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.reassign_overloaded_agents(p_max_conversations integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN RETURN jsonb_build_object('reassigned', 0, 'message', 'No overloaded agents found'); END;
$$;


