--
-- Name: record_failed_login(text, text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.record_failed_login(p_email text, p_ip_address text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text) RETURNS TABLE(is_locked boolean, locked_until timestamp with time zone, attempts integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_attempt RECORD;
  v_new_count INTEGER;
  v_lock_duration INTERVAL;
  v_locked_until TIMESTAMP WITH TIME ZONE;
  v_max_attempts INTEGER := 5;
BEGIN
  -- Get existing attempts
  SELECT la.attempt_count, la.locked_until, la.last_attempt_at
  INTO v_attempt
  FROM zapp.login_attempts la
  WHERE la.email = LOWER(p_email);
  
  IF NOT FOUND THEN
    -- First failed attempt
    INSERT INTO zapp.login_attempts (email, ip_address, user_agent, attempt_count)
    VALUES (LOWER(p_email), p_ip_address, p_user_agent, 1);
    
    RETURN QUERY SELECT false, NULL::TIMESTAMP WITH TIME ZONE, 1;
    RETURN;
  END IF;
  
  -- If previous lock expired, reset count
  IF v_attempt.locked_until IS NOT NULL AND v_attempt.locked_until <= now() THEN
    v_new_count := 1;
  ELSE
    v_new_count := v_attempt.attempt_count + 1;
  END IF;
  
  -- Calculate lock duration with exponential backoff
  IF v_new_count >= v_max_attempts THEN
    -- Lock duration: 2^(attempts - max_attempts) minutes, starting at 1 minute
    -- 5 attempts = 1 min, 6 = 2 min, 7 = 4 min, 8 = 8 min, etc.
    v_lock_duration := (POWER(2, LEAST(v_new_count - v_max_attempts, 10)))::INTEGER * INTERVAL '1 minute';
    v_locked_until := now() + v_lock_duration;
  ELSE
    v_locked_until := NULL;
  END IF;
  
  -- Update attempt record
  UPDATE zapp.login_attempts
  SET 
    attempt_count = v_new_count,
    last_attempt_at = now(),
    locked_until = v_locked_until,
    ip_address = COALESCE(p_ip_address, login_attempts.ip_address),
    user_agent = COALESCE(p_user_agent, login_attempts.user_agent),
    updated_at = now()
  WHERE email = LOWER(p_email);
  
  RETURN QUERY SELECT 
    v_locked_until IS NOT NULL AND v_locked_until > now(),
    v_locked_until,
    v_new_count;
END;
$$;


--
-- Name: record_processed_request(text, text, uuid, integer, jsonb); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.record_processed_request(p_request_id text, p_action text, p_user_id uuid, p_status_code integer, p_result_payload jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
BEGIN
  INSERT INTO zapp.processed_requests (
    request_id, action, user_id, result_status, result_payload, expires_at
  ) VALUES (
    p_request_id, p_action, p_user_id,
    p_status_code, p_result_payload, now() + INTERVAL '5 minutes'
  )
  ON CONFLICT (request_id, action) DO NOTHING;
EXCEPTION WHEN OTHERS THEN
  NULL;
END;
$$;


--
-- Name: record_voice_telemetry(uuid, integer, text, text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.record_voice_telemetry(p_queue_id uuid, p_duration_ms integer, p_status text, p_error_type text DEFAULT NULL::text, p_error_detail text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
BEGIN
  UPDATE zapp.voice_conversion_queue
  SET status = p_status, duration_ms = p_duration_ms,
      error_message = COALESCE(p_error_detail, error_message),
      error_code = p_error_type,
      completed_at = CASE WHEN p_status IN ('completed','failed') THEN now() ELSE completed_at END,
      updated_at = now()
  WHERE id = p_queue_id;

  IF p_status = 'failed' AND p_error_type IS NOT NULL THEN
    INSERT INTO zapp.dev_diagnostic_logs (action, category, details)
    VALUES ('voice_conversion_failed','Voice',
      jsonb_build_object('queue_id',p_queue_id,'duration_ms',p_duration_ms,'error_type',p_error_type));
  END IF;
END;
$$;


--
-- Name: refresh_cookie_health_status(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.refresh_cookie_health_status() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
BEGIN
  UPDATE cookies_config SET
    health_status = CASE
      WHEN cookie = '' OR cookie LIKE 'REQUIRES_RENEWAL%' OR cookie LIKE 'PLACEHOLDER%' THEN 'error'
      WHEN expires_at IS NULL THEN 'unknown'
      WHEN expires_at < NOW()                                                          THEN 'expired'
      WHEN expires_at < NOW() + (alerta_dias_antes || ' days')::INTERVAL               THEN 'expiring_soon'
      ELSE 'healthy'
    END,
    is_healthy = CASE
      WHEN cookie = '' OR cookie LIKE 'REQUIRES_RENEWAL%' OR cookie LIKE 'PLACEHOLDER%' THEN false
      WHEN expires_at IS NULL THEN NULL
      WHEN expires_at < NOW() THEN false
      ELSE true
    END
  WHERE expires_at IS NOT NULL 
     OR cookie = '' 
     OR cookie LIKE 'REQUIRES_RENEWAL%'
     OR cookie LIKE 'PLACEHOLDER%';
END;
$$;


--
-- Name: FUNCTION refresh_cookie_health_status(); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.refresh_cookie_health_status() IS 'Atualiza health_status e is_healthy baseado em expires_at. Chamar via n8n cron diário.';


