--
-- Name: restore_contact(uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.restore_contact(p_contact_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  -- Only managers/admins can restore
  IF NOT EXISTS (
    SELECT 1 FROM zapp.profiles
    WHERE id = auth.uid()
      AND role IN ('admin', 'supervisor', 'manager')
  ) THEN
    RAISE EXCEPTION 'Permission denied: only managers can restore contacts';
  END IF;

  UPDATE zapp.contacts
  SET
    deleted_at     = NULL,
    deleted_by     = NULL,
    deleted_reason = NULL,
    updated_at     = now()
  WHERE id = p_contact_id
    AND deleted_at IS NOT NULL
    AND deleted_at >= now() - interval '30 days'
    AND workspace_id = (
      SELECT workspace_id FROM zapp.profiles WHERE id = auth.uid()
    );

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Contact % not found, not deleted, or outside 30-day recovery window', p_contact_id;
  END IF;
END;
$$;


--
-- Name: revoke_lgpd_consent(uuid, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.revoke_lgpd_consent(p_contact_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$ DECLARE v_ok int; BEGIN UPDATE evo.evolution_contacts SET lgpd_opt_out_at=now(), lgpd_marketing_consent=false, lgpd_data_sharing=false, lgpd_profiling=false, lgpd_last_updated_at=now(), version=coalesce(version,0)+1, updated_at=now() WHERE id=p_contact_id AND deleted_at IS NULL; GET DIAGNOSTICS v_ok = ROW_COUNT; IF v_ok=0 THEN RETURN jsonb_build_object('success',false,'message','contato nao encontrado'); END IF; INSERT INTO evo.evolution_audit_log (action, entity_type, entity_id, performed_by, performed_by_type, metadata, created_at) VALUES ('lgpd_consent_revoked','contact',p_contact_id, coalesce(auth.uid()::text,'system'),'user', jsonb_build_object('reason',p_reason), now()); RETURN jsonb_build_object('success',true,'contact_id',p_contact_id); END $$;


--
-- Name: FUNCTION revoke_lgpd_consent(p_contact_id uuid, p_reason text); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.revoke_lgpd_consent(p_contact_id uuid, p_reason text) IS 'FATOR X v6.1.0: opt-out LGPD com zeragem de consentimentos e auditoria.';


--
-- Name: rls_auto_enable(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rls_auto_enable() RETURNS event_trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
    IF cmd.schema_name IS NOT NULL
       AND cmd.schema_name IN ('public', 'evo', 'zapp', 'ops')
       AND cmd.schema_name NOT IN ('pg_catalog','information_schema')
       AND cmd.schema_name NOT LIKE 'pg_toast%'
       AND cmd.schema_name NOT LIKE 'pg_temp%'
    THEN
      BEGIN
        EXECUTE format('ALTER TABLE IF EXISTS %s ENABLE ROW LEVEL SECURITY',
                       cmd.object_identity);
        RAISE LOG 'rls_auto_enable: habilitou RLS em %', cmd.object_identity;
      EXCEPTION WHEN OTHERS THEN
        RAISE LOG 'rls_auto_enable: FALHOU em % : %', cmd.object_identity, SQLERRM;
      END;
    ELSE
      RAISE LOG 'rls_auto_enable: skip % (schema % nao monitorado)',
                cmd.object_identity, cmd.schema_name;
    END IF;
  END LOOP;
END;
$$;


