--
-- Name: rpc_associate_label(uuid, text, uuid, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_associate_label(p_label_id uuid, p_entity_type text, p_entity_id uuid, p_action text DEFAULT 'add'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$ DECLARE v_result jsonb; BEGIN IF p_action='add' THEN INSERT INTO evolution_label_associations(label_id,entity_type,entity_id) VALUES(p_label_id,p_entity_type,p_entity_id) ON CONFLICT(label_id,entity_type,entity_id) DO NOTHING; v_result := jsonb_build_object('success',true,'action','added'); ELSIF p_action='remove' THEN DELETE FROM evolution_label_associations WHERE label_id=p_label_id AND entity_type=p_entity_type AND entity_id=p_entity_id; v_result := jsonb_build_object('success',true,'action','removed'); ELSE v_result := jsonb_build_object('success',false,'error','Invalid action'); END IF; RETURN v_result; END; $$;


--
-- Name: rpc_auto_save_sticker(text, text, text, boolean); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_auto_save_sticker(p_image_url text, p_name text DEFAULT NULL::text, p_category text DEFAULT 'recebidas'::text, p_is_animated boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_existing_id uuid;
  v_new_id uuid;
BEGIN
  -- Verificar se já existe (deduplicação por URL)
  SELECT id INTO v_existing_id 
  FROM zapp.stickers 
  WHERE image_url = p_image_url AND is_active = true
  LIMIT 1;
  
  IF v_existing_id IS NOT NULL THEN
    -- Já existe, apenas incrementa uso
    UPDATE zapp.stickers SET use_count = use_count + 1 WHERE id = v_existing_id;
    RETURN v_existing_id;
  END IF;
  
  -- Inserir novo sticker
  INSERT INTO zapp.stickers (
    name, image_url, category, is_animated, owner_id, use_count
  ) VALUES (
    COALESCE(p_name, 'Recebida ' || to_char(now(), 'DD/MM/YYYY')),
    p_image_url,
    p_category,
    p_is_animated,
    auth.uid(),
    1
  ) RETURNING id INTO v_new_id;
  
  RETURN v_new_id;
END;
$$;


--
-- Name: rpc_backfill_messages_contact_id(text, integer, boolean); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_backfill_messages_contact_id(p_instance_name text DEFAULT 'wpp2'::text, p_batch_size integer DEFAULT 5000, p_dry_run boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
DECLARE
  v_start timestamptz := clock_timestamp();
  v_cap int := LEAST(p_batch_size, 20000);
  v_repaired bigint := 0;
  v_remaining bigint;
BEGIN
  PERFORM zapp.fn_require_app_user();

  IF NOT p_dry_run THEN
    WITH candidates AS (
      SELECT m.id FROM evo.evolution_messages m
      WHERE m.instance_name = p_instance_name
        AND m.contact_id IS NULL
        AND m.remote_jid NOT LIKE '%@g.us'
        AND m.remote_jid NOT LIKE '%@broadcast'
        AND m.remote_jid NOT IN ('unknown@s.whatsapp.net','unknown@deleted')
        AND split_part(m.remote_jid,'@',1) NOT LIKE 'smoke%'
      LIMIT v_cap
      FOR UPDATE SKIP LOCKED
    ),
    contact_match AS (
      -- Match by remote_jid (exact)
      SELECT DISTINCT ON (m.id) m.id AS msg_id, c.id AS contact_id
      FROM candidates cand
      JOIN evo.evolution_messages m ON m.id = cand.id
      JOIN evo.evolution_contacts c
        ON c.instance_name = m.instance_name
       AND c.remote_jid = m.remote_jid
       AND c.deleted_at IS NULL
      UNION ALL
      -- Match by phone_number (normalized)
      SELECT DISTINCT ON (m.id) m.id, c.id
      FROM candidates cand
      JOIN evo.evolution_messages m ON m.id = cand.id
      LEFT JOIN evo.evolution_contacts c
        ON c.instance_name = m.instance_name
       AND c.phone_number = regexp_replace(split_part(m.remote_jid,'@',1), '\D','','g')
       AND c.deleted_at IS NULL
      WHERE c.id IS NOT NULL
    ),
    best_match AS (
      SELECT DISTINCT ON (msg_id) msg_id, contact_id
      FROM contact_match
      WHERE contact_id IS NOT NULL
      ORDER BY msg_id
    ),
    updated AS (
      UPDATE evo.evolution_messages em
      SET contact_id = bm.contact_id
      FROM best_match bm
      WHERE em.id = bm.msg_id
        AND em.contact_id IS NULL
      RETURNING em.id
    )
    SELECT COUNT(*) INTO v_repaired FROM updated;
  ELSE
    SELECT COUNT(*) INTO v_repaired
    FROM (
      SELECT m.id FROM evo.evolution_messages m
      WHERE m.instance_name = p_instance_name
        AND m.contact_id IS NULL
        AND m.remote_jid NOT LIKE '%@g.us'
      LIMIT v_cap
    ) sub;
  END IF;

  SELECT COUNT(*) INTO v_remaining
  FROM evo.evolution_messages
  WHERE instance_name = p_instance_name
    AND contact_id IS NULL
    AND remote_jid NOT LIKE '%@g.us';

  RETURN jsonb_build_object(
    'repaired',          v_repaired,
    'remaining_estimate',v_remaining,
    'instance_name',     p_instance_name,
    'dry_run',           p_dry_run,
    'elapsed_ms',        EXTRACT(EPOCH FROM (clock_timestamp()-v_start))*1000
  );
END;
$$;


--
-- Name: rpc_bulk_repair_dedup_hashes(text, integer, boolean); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_bulk_repair_dedup_hashes(p_instance_name text DEFAULT 'wpp2'::text, p_batch_size integer DEFAULT 5000, p_dry_run boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'extensions'
    AS $$
DECLARE
  v_start timestamptz := clock_timestamp();
  v_cap int := LEAST(p_batch_size, 17000);
  v_updated bigint := 0;
  v_skipped bigint;
BEGIN
  PERFORM zapp.fn_require_app_user();

  SELECT COUNT(*) INTO v_skipped
  FROM evo.evolution_contacts
  WHERE instance_name = p_instance_name
    AND dedup_hash IS NOT NULL
    AND deleted_at IS NULL;

  IF NOT p_dry_run THEN
    WITH candidates AS (
      SELECT id FROM evo.evolution_contacts
      WHERE instance_name = p_instance_name
        AND dedup_hash IS NULL
        AND pii_masked_at IS NULL
        AND deleted_at IS NULL
      LIMIT v_cap
      FOR UPDATE SKIP LOCKED
    ),
    updated AS (
      UPDATE evo.evolution_contacts ec
      SET dedup_hash = encode(
            extensions.digest(
              regexp_replace(coalesce(ec.phone_number,''), '\D', '', 'g')
              || '|' || lower(coalesce(ec.email,''))
              || '|' || lower(coalesce(ec.full_name,'')),
              'sha256'
            ), 'hex'),
          updated_at = now()
      FROM candidates c
      WHERE ec.id = c.id AND ec.pii_masked_at IS NULL
      RETURNING ec.id
    )
    SELECT COUNT(*) INTO v_updated FROM updated;
  ELSE
    SELECT COUNT(*) INTO v_updated
    FROM evo.evolution_contacts
    WHERE instance_name = p_instance_name
      AND dedup_hash IS NULL AND pii_masked_at IS NULL AND deleted_at IS NULL
    LIMIT v_cap;
  END IF;

  RETURN jsonb_build_object(
    'updated', v_updated, 'skipped', v_skipped,
    'dry_run', p_dry_run, 'batch_size', v_cap,
    'instance_name', p_instance_name,
    'elapsed_ms', EXTRACT(EPOCH FROM (clock_timestamp()-v_start))*1000
  );
END;
$$;


