--
-- Name: rpc_change_deal_stage(uuid, text, text, text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_change_deal_stage(p_id uuid, p_new_stage text, p_performed_by text DEFAULT 'frontend'::text, p_lost_reason text DEFAULT NULL::text, p_lost_notes text DEFAULT NULL::text) RETURNS evo.evolution_deals
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$ DECLARE v_old_stage text; v_row evolution_deals; BEGIN
  PERFORM zapp.fn_require_app_user();
 SELECT stage INTO v_old_stage FROM evolution_deals WHERE id=p_id; UPDATE evolution_deals SET stage=p_new_stage, stage_changed_at=now(), lost_reason=CASE WHEN p_new_stage='lost' THEN p_lost_reason ELSE lost_reason END, actual_close_date=CASE WHEN p_new_stage IN ('won','lost') THEN CURRENT_DATE ELSE actual_close_date END, updated_at=now() WHERE id=p_id RETURNING * INTO v_row; RETURN v_row; END; $$;


--
-- Name: rpc_check_and_trigger_gmail_revalidation(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_check_and_trigger_gmail_revalidation() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
    v_last_val TIMESTAMP WITH TIME ZONE;
    v_status TEXT;
    v_job_id UUID;
BEGIN
    SELECT last_validation, status INTO v_last_val, v_status 
    FROM zapp.gmail_health_summary 
    WHERE id = 'current';

    -- Trigger if degraded/error OR if last validation was more than 30 minutes ago
    IF v_status IN ('degraded', 'error') OR v_last_val < now() - interval '30 minutes' OR v_last_val IS NULL THEN
        -- Check if there's already a pending job to avoid duplicates
        IF NOT EXISTS (SELECT 1 FROM zapp.gmail_revalidation_jobs WHERE status = 'pending' AND requested_at > now() - interval '5 minutes') THEN
            INSERT INTO zapp.gmail_revalidation_jobs (status, requested_at)
            VALUES ('pending', now())
            RETURNING id INTO v_job_id;
            
            RETURN jsonb_build_object('triggered', true, 'job_id', v_job_id, 'reason', 'Threshold met or stale data');
        END IF;
    END IF;

    RETURN jsonb_build_object('triggered', false, 'reason', 'System healthy and data fresh');
END;
$$;


--
-- Name: rpc_check_audio_meme_duplicate(text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_check_audio_meme_duplicate(p_audio_url text DEFAULT NULL::text, p_file_hash text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
DECLARE
  v_existing record;
BEGIN
  IF p_file_hash IS NOT NULL THEN
    SELECT id, name, category INTO v_existing FROM audio_memes WHERE file_hash = p_file_hash;
    IF v_existing IS NOT NULL THEN
      RETURN jsonb_build_object('is_duplicate', true, 'match_type', 'hash', 'existing_id', v_existing.id, 'existing_name', v_existing.name);
    END IF;
  END IF;
  IF p_audio_url IS NOT NULL THEN
    SELECT id, name, category INTO v_existing FROM audio_memes WHERE audio_url = p_audio_url;
    IF v_existing IS NOT NULL THEN
      RETURN jsonb_build_object('is_duplicate', true, 'match_type', 'url', 'existing_id', v_existing.id, 'existing_name', v_existing.name);
    END IF;
  END IF;
  RETURN jsonb_build_object('is_duplicate', false);
END;
$$;


--
-- Name: FUNCTION rpc_check_audio_meme_duplicate(p_audio_url text, p_file_hash text); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.rpc_check_audio_meme_duplicate(p_audio_url text, p_file_hash text) IS 'Verifica duplicata de audio-meme por hash SHA256 ou URL.';


--
-- Name: rpc_check_rls_compliance(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_check_rls_compliance() RETURNS TABLE(table_name text, schema_name text, reason text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
  SELECT
    c.relname::text AS table_name,
    n.nspname::text AS schema_name,
    'RLS desabilitado em tabela sensível'::text AS reason
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind = 'r'
    AND c.relrowsecurity = false
    AND c.relname NOT LIKE E'\\_%'
    AND c.relname NOT IN (
      'spatial_ref_sys',
      'schema_migrations'
    )
  ORDER BY c.relname;
$$;


