--
-- Name: rpc_claim_media_download_batch(integer, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_claim_media_download_batch(p_batch_size integer DEFAULT 10, p_instance_name text DEFAULT 'wpp_pink_test'::text) RETURNS TABLE(id bigint, message_id text, message_uuid uuid, remote_jid text, media_type text, media_key text, direct_path text, mimetype text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  RETURN QUERY
  UPDATE zapp.media_download_queue mdq
  SET status='processing', processed_at=now()
  FROM (
    SELECT mdq2.id FROM zapp.media_download_queue mdq2
    WHERE mdq2.status='pending' AND mdq2.instance_name=p_instance_name
      AND mdq2.retry_count < mdq2.max_retries
    ORDER BY mdq2.priority DESC, mdq2.created_at ASC
    LIMIT p_batch_size FOR UPDATE SKIP LOCKED
  ) sub
  WHERE mdq.id=sub.id
  RETURNING mdq.id, mdq.message_id, mdq.message_uuid, mdq.remote_jid,
            mdq.media_type, mdq.media_key, mdq.direct_path, mdq.mimetype;
END; $$;


--
-- Name: rpc_complete_media_download(bigint, text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_complete_media_download(p_queue_id bigint, p_download_url text DEFAULT NULL::text, p_storage_path text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_msg_uuid uuid;
  v_public_url text;
  v_r2_base text := 'https://zapp-media-proxy.adm01.workers.dev';
BEGIN
  PERFORM zapp.fn_require_app_user();

  -- Se recebeu URL, converter para pública
  IF p_download_url IS NOT NULL THEN
    v_public_url := fn_media_public_url(p_download_url);
  ELSIF p_storage_path IS NOT NULL THEN
    -- Se recebeu path do R2, montar URL
    v_public_url := v_r2_base || '/' || p_storage_path;
  END IF;
  
  -- Atualizar fila
  UPDATE media_download_queue 
  SET status = 'done', download_url = v_public_url, storage_path = p_storage_path, processed_at = now()
  WHERE id = p_queue_id
  RETURNING message_uuid INTO v_msg_uuid;
  
  -- Atualizar a mensagem original com a URL pública
  IF v_msg_uuid IS NOT NULL AND v_public_url IS NOT NULL THEN
    UPDATE evolution_messages SET media_url = v_public_url WHERE id = v_msg_uuid;
  END IF;
END;
$$;


--
-- Name: FUNCTION rpc_complete_media_download(p_queue_id bigint, p_download_url text, p_storage_path text); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.rpc_complete_media_download(p_queue_id bigint, p_download_url text, p_storage_path text) IS 'Marca download de midia como concluido e atualiza URL publica via R2 worker';


