--
-- Name: rpc_contact_media_stats(text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_contact_media_stats(p_remote_jid text) RETURNS TABLE(media_type text, total bigint, with_url bigint, without_url bigint, latest_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  PERFORM zapp.fn_require_app_user();

  RETURN QUERY
  SELECT em.message_type::text, count(*), count(*) FILTER (WHERE em.media_url IS NOT NULL AND em.media_url != ''),
    count(*) FILTER (WHERE em.media_url IS NULL OR em.media_url = ''), max(em.created_at)
  FROM evo.evolution_messages em  -- FIX
  WHERE em.remote_jid=p_remote_jid AND em.message_type IN ('image','video','audio','ptt','document','sticker')
    AND em.deleted_at IS NULL
  GROUP BY em.message_type ORDER BY count(*) DESC;
END; $$;


