);


--
-- Name: rpc_disable_service_channel(uuid, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_disable_service_channel(p_id uuid, p_reason text DEFAULT NULL::text) RETURNS zapp.service_channels
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_row zapp.service_channels;
BEGIN
  IF NOT zapp.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Access denied: admin role required';
  END IF;

  UPDATE zapp.service_channels SET
    status = 'disabled',
    disabled_at = now(),
    disabled_reason = NULLIF(trim(COALESCE(p_reason,'')), '')
  WHERE id = p_id
  RETURNING * INTO v_row;

  IF v_row.id IS NULL THEN RAISE EXCEPTION 'channel not found'; END IF;

  -- Marca conexão whatsapp como desconectada (se houver)
  IF v_row.whatsapp_connection_id IS NOT NULL THEN
    UPDATE zapp.whatsapp_connections
       SET status = 'disconnected', updated_at = now()
     WHERE id = v_row.whatsapp_connection_id;
  END IF;

  INSERT INTO zapp.audit_logs (user_id, action, entity_type, entity_id, details)
  VALUES (auth.uid(), 'service_channel_disabled', 'service_channels', p_id::text,
          jsonb_build_object('reason', p_reason, 'wpp_connection', v_row.whatsapp_connection_id));

  RETURN v_row;
END;
$$;


--
-- Name: rpc_dispatch_error_stats(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_dispatch_error_stats(p_hours integer DEFAULT 24) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_hours INTEGER;
  v_total BIGINT;
  v_by_agent JSONB;
  v_by_instance JSONB;
  v_by_code JSONB;
BEGIN
  IF NOT zapp.is_admin_or_supervisor(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied: admin or supervisor role required';
  END IF;

  v_hours := GREATEST(1, LEAST(COALESCE(p_hours, 24), 720));

  SELECT COUNT(*) INTO v_total
  FROM zapp.dispatch_error_logs
  WHERE occurred_at > now() - (v_hours || ' hours')::interval;

  SELECT COALESCE(jsonb_agg(t.*), '[]'::jsonb) INTO v_by_agent FROM (
    SELECT COALESCE(agent_email, 'sem-agente') AS agent, COUNT(*)::INT AS total
    FROM zapp.dispatch_error_logs
    WHERE occurred_at > now() - (v_hours || ' hours')::interval
    GROUP BY 1
    ORDER BY 2 DESC
    LIMIT 20
  ) t;

  SELECT COALESCE(jsonb_agg(t.*), '[]'::jsonb) INTO v_by_instance FROM (
    SELECT instance_name AS instance, COUNT(*)::INT AS total
    FROM zapp.dispatch_error_logs
    WHERE occurred_at > now() - (v_hours || ' hours')::interval
    GROUP BY 1
    ORDER BY 2 DESC
    LIMIT 20
  ) t;

  SELECT COALESCE(jsonb_agg(t.*), '[]'::jsonb) INTO v_by_code FROM (
    SELECT COALESCE(error_code, 'unknown') AS code, COUNT(*)::INT AS total
    FROM zapp.dispatch_error_logs
    WHERE occurred_at > now() - (v_hours || ' hours')::interval
    GROUP BY 1
    ORDER BY 2 DESC
    LIMIT 20
  ) t;

  RETURN jsonb_build_object(
    'window_hours', v_hours,
    'total', COALESCE(v_total, 0),
    'by_agent', v_by_agent,
    'by_instance', v_by_instance,
    'by_error_code', v_by_code
  );
END;
$$;


--
-- Name: rpc_dlq_abandon(uuid, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_dlq_abandon(p_id uuid, p_reason text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_updated int;
  v_reason  text;
BEGIN
  IF NOT (zapp.has_role(auth.uid(), 'admin') OR zapp.has_role(auth.uid(), 'supervisor')) THEN
    PERFORM zapp.log_rls_denied(
      'failed_messages', 'admin|supervisor',
      jsonb_build_object('rpc', 'rpc_dlq_abandon', 'p_id', p_id)
    );
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  v_reason := NULLIF(TRIM(COALESCE(p_reason, '')), '');
  UPDATE zapp.failed_messages
     SET status        = 'abandoned',
         error_message = COALESCE(error_message, '') ||
                         ' [ABANDONED: ' || COALESCE(v_reason, 'no reason given') || ']',
         updated_at    = now()
   WHERE id     = p_id
     AND status NOT IN ('abandoned', 'succeeded');
  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated > 0 THEN
    INSERT INTO zapp.audit_logs (user_id, action, entity_type, entity_id, details)
    VALUES (auth.uid(), 'dlq_abandon', 'failed_messages', p_id::text,
            jsonb_build_object('reason', v_reason));
  END IF;
  RETURN v_updated > 0;
END;
$$;


--
-- Name: rpc_dlq_bulk_abandon(uuid[], text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_dlq_bulk_abandon(p_ids uuid[], p_reason text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_updated int;
  v_reason  text;
BEGIN
  IF NOT (zapp.has_role(auth.uid(), 'admin') OR zapp.has_role(auth.uid(), 'supervisor')) THEN
    PERFORM zapp.log_rls_denied(
      'failed_messages', 'admin|supervisor',
      jsonb_build_object('rpc', 'rpc_dlq_bulk_abandon', 'ids_count', array_length(p_ids, 1))
    );
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_ids IS NULL OR array_length(p_ids, 1) IS NULL THEN RETURN 0; END IF;
  IF array_length(p_ids, 1) > 500 THEN
    RAISE EXCEPTION 'Bulk operation limited to 500 rows per call';
  END IF;
  v_reason := NULLIF(TRIM(COALESCE(p_reason, '')), '');
  UPDATE zapp.failed_messages
     SET status        = 'abandoned',
         error_message = COALESCE(error_message, '') ||
                         ' [ABANDONED: ' || COALESCE(v_reason, 'bulk') || ']',
         updated_at    = now()
   WHERE id = ANY(p_ids)
     AND status NOT IN ('abandoned', 'succeeded');
  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated > 0 THEN
    INSERT INTO zapp.audit_logs (user_id, action, entity_type, entity_id, details)
    VALUES (auth.uid(), 'dlq_bulk_abandon', 'failed_messages', NULL,
            jsonb_build_object('reason', v_reason, 'requested', array_length(p_ids, 1), 'updated', v_updated));
  END IF;
  RETURN v_updated;
END;
$$;


--
-- Name: rpc_dlq_bulk_retry_now(uuid[], text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_dlq_bulk_retry_now(p_ids uuid[], p_reason text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_count INTEGER;
BEGIN
  IF NOT (zapp.has_role(auth.uid(), 'admin') OR zapp.has_role(auth.uid(), 'supervisor')) THEN
    PERFORM zapp.log_rls_denied(
      'failed_messages', 'admin|supervisor',
      jsonb_build_object('rpc', 'rpc_dlq_bulk_retry_now', 'ids_count', array_length(p_ids, 1))
    );
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_ids IS NULL OR array_length(p_ids, 1) IS NULL THEN RETURN 0; END IF;
  IF array_length(p_ids, 1) > 500 THEN
    RAISE EXCEPTION 'Bulk operation limited to 500 rows per call';
  END IF;
  UPDATE zapp.failed_messages
     SET next_attempt_at = now(),
         status          = 'pending',
         updated_at      = now()
   WHERE id = ANY(p_ids)
     AND status NOT IN ('processing', 'succeeded');
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


--
-- Name: rpc_dlq_list_audit(integer, integer, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_dlq_list_audit(p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_action text DEFAULT NULL::text) RETURNS TABLE(id uuid, action text, entity_id text, details jsonb, created_at timestamp with time zone, user_id uuid, user_name text, user_email text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
BEGIN
  IF NOT (zapp.has_role(auth.uid(), 'admin') OR zapp.has_role(auth.uid(), 'supervisor')) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  SELECT
    a.id, a.action, a.entity_id, a.details, a.created_at, a.user_id,
    p.name  AS user_name,
    p.email AS user_email
  FROM zapp.audit_logs a
  LEFT JOIN zapp.profiles p ON p.user_id = a.user_id
  WHERE a.entity_type = 'failed_messages'
    AND a.action LIKE 'dlq_%'
    AND (
      p_action IS NULL
      OR a.action = p_action
      OR (p_action = 'all' AND a.action LIKE 'dlq_%')
    )
  ORDER BY a.created_at DESC
  LIMIT  GREATEST(COALESCE(p_limit,  50), 1)
  OFFSET GREATEST(COALESCE(p_offset,  0), 0);
END;
$$;


--
-- Name: rpc_dlq_list_audit_cursor(integer, text, uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_dlq_list_audit_cursor(p_limit integer DEFAULT 30, p_action text DEFAULT NULL::text, p_cursor_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, action text, entity_id text, details jsonb, created_at timestamp with time zone, user_id uuid, user_name text, user_email text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
BEGIN
  IF NOT zapp.is_admin_or_supervisor(auth.uid()) THEN
    PERFORM zapp.log_rls_denied('audit_logs', 'admin|supervisor',
      jsonb_build_object('rpc', 'rpc_dlq_list_audit_cursor', 'action', p_action));
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    al.id,
    al.action::text,
    al.entity_id::text,
    al.details,
    al.created_at,
    al.user_id,
    p.name  AS user_name,
    p.email AS user_email
  FROM zapp.audit_logs al
  LEFT JOIN zapp.profiles p ON p.user_id = al.user_id
  WHERE al.entity_type = 'failed_messages'
    AND (p_action IS NULL OR p_action = 'all' OR al.action = p_action)
    AND (p_cursor_id IS NULL OR
         (al.created_at, al.id) < (
           SELECT c.created_at, c.id
           FROM zapp.audit_logs c
           WHERE c.id = p_cursor_id
         ))
  ORDER BY al.created_at DESC, al.id DESC
  LIMIT COALESCE(p_limit, 30);
END;
$$;


--
-- Name: rpc_dlq_log_item_action(text, uuid[], text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_dlq_log_item_action(p_action text, p_ids uuid[], p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_action text;
BEGIN
  IF NOT (zapp.has_role(auth.uid(), 'admin') OR zapp.has_role(auth.uid(), 'supervisor')) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  v_action := CASE p_action
    WHEN 'retry'        THEN 'dlq_retry_now'
    WHEN 'abandon'      THEN 'dlq_abandon'
    WHEN 'bulk_retry'   THEN 'dlq_bulk_retry'
    WHEN 'bulk_abandon' THEN 'dlq_bulk_abandon'
    ELSE NULL
  END;
  IF v_action IS NULL THEN
    RAISE EXCEPTION 'Invalid action: %', p_action;
  END IF;
  IF p_ids IS NULL OR array_length(p_ids, 1) IS NULL THEN RETURN; END IF;
  INSERT INTO zapp.audit_logs (user_id, action, entity_type, entity_id, details)
  VALUES (
    auth.uid(), v_action, 'failed_messages',
    CASE WHEN array_length(p_ids, 1) = 1 THEN p_ids[1]::text ELSE NULL END,
    jsonb_build_object(
      'ids',          to_jsonb(p_ids),
      'count',        array_length(p_ids, 1),
      'reason',       p_reason,
      'performed_at', now()
    )
  );
END;
$$;


--
-- Name: rpc_dlq_log_reprocess_result(integer, integer, integer, integer, text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_dlq_log_reprocess_result(p_processed integer DEFAULT 0, p_succeeded integer DEFAULT 0, p_failed integer DEFAULT 0, p_abandoned integer DEFAULT 0, p_message text DEFAULT NULL::text, p_source text DEFAULT 'panel'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
