--
-- Name: rpc_dlq_retry_now(uuid, uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_dlq_retry_now(p_id uuid DEFAULT NULL::uuid, p_item_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_target  uuid;
  v_updated int;
BEGIN
  IF NOT (zapp.has_role(auth.uid(), 'admin') OR zapp.has_role(auth.uid(), 'supervisor')) THEN
    PERFORM zapp.log_rls_denied(
      'failed_messages', 'admin|supervisor',
      jsonb_build_object('rpc', 'rpc_dlq_retry_now', 'p_id', COALESCE(p_id, p_item_id))
    );
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  v_target := COALESCE(p_id, p_item_id);
  IF v_target IS NULL THEN RETURN FALSE; END IF;
  UPDATE zapp.failed_messages
     SET status          = 'pending',
         next_attempt_at = now(),
         updated_at      = now()
   WHERE id     = v_target
     AND status NOT IN ('processing', 'succeeded');
  GET DIAGNOSTICS v_updated = ROW_COUNT;
  RETURN v_updated > 0;
END;
$$;


--
-- Name: rpc_dlq_stats(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_dlq_stats() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_total          bigint;
  v_total_24h      bigint;
  v_oldest_pending timestamptz;
  v_by_status      jsonb;
  v_by_instance    jsonb;
BEGIN
  IF NOT (zapp.has_role(auth.uid(), 'admin') OR zapp.has_role(auth.uid(), 'supervisor')) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT COUNT(*) INTO v_total FROM zapp.failed_messages;

  SELECT COUNT(*) INTO v_total_24h
  FROM zapp.failed_messages
  WHERE created_at >= NOW() - INTERVAL '24 hours';

  SELECT MIN(created_at) INTO v_oldest_pending
  FROM zapp.failed_messages
  WHERE status = 'pending';

  SELECT jsonb_object_agg(status, cnt) INTO v_by_status
  FROM (
    SELECT status, COUNT(*) AS cnt
    FROM zapp.failed_messages
    GROUP BY status
  ) s;

  SELECT jsonb_agg(
    jsonb_build_object('instance', instance_name, 'count', cnt)
    ORDER BY cnt DESC
  ) INTO v_by_instance
  FROM (
    SELECT instance_name, COUNT(*) AS cnt
    FROM zapp.failed_messages
    GROUP BY instance_name
    ORDER BY cnt DESC
    LIMIT 10
  ) i;

  RETURN jsonb_build_object(
    'total',             COALESCE(v_total, 0),
    'total_24h',         COALESCE(v_total_24h, 0),
    'oldest_pending_at', v_oldest_pending,
    'by_status',         COALESCE(v_by_status, '{}'::jsonb),
    'by_instance',       COALESCE(v_by_instance, '[]'::jsonb)
  );
END;
$$;


--
-- Name: rpc_dr_health_check(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_dr_health_check() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'pg_temp'
    AS $$
DECLARE
  v_db_stats      record;
  v_wh_health     record;
  v_cron_failing  bigint;
  v_open_inc      bigint;
  v_evo_cred      record;
  v_result        jsonb;
BEGIN
  SELECT
  CASE WHEN count(*) FILTER (WHERE created_at >= now() - interval '1 hour') > 0 THEN 'healthy'
       WHEN count(*) FILTER (WHERE created_at >= now() - interval '24 hours') > 0 THEN 'degraded'
       ELSE 'critical' END AS health_status,
  max(created_at) AS last_event_at,
  count(*) FILTER (WHERE NOT processed) AS unresponded,
  count(*) FILTER (WHERE created_at >= now() - interval '1 hour') AS events_1h,
  count(*) FILTER (WHERE created_at >= now() - interval '24 hours') AS events_24h,
  count(*) FILTER (WHERE processed_at >= now() - interval '1 hour') AS processed_1h
INTO v_wh_health
FROM evo.evolution_webhook_events_v2;

  BEGIN
    SELECT count(*) INTO v_cron_failing FROM cron.job WHERE active = false;
  EXCEPTION WHEN OTHERS THEN
    v_cron_failing := 0;
  END;

  BEGIN
    SELECT count(*) INTO v_open_inc
    FROM zapp.system_health_incidents WHERE status IN ('open','investigating');
  EXCEPTION WHEN OTHERS THEN
    v_open_inc := 0;
  END;

  BEGIN
    SELECT * INTO v_evo_cred
    FROM zapp.evolution_instance_credentials WHERE instance_name='wpp2' LIMIT 1;
  EXCEPTION WHEN OTHERS THEN
    v_evo_cred := NULL;
  END;

  v_result := jsonb_build_object(
    'overall_status', CASE
      WHEN v_wh_health.health_status = 'critical' THEN 'critical'
      WHEN v_open_inc > 0 OR v_cron_failing > 0 THEN 'degraded'
      ELSE 'healthy'
    END,
    'checks', jsonb_build_object(
      'pipeline', jsonb_build_object(
        'status',       v_wh_health.health_status,
        'last_event_at', v_wh_health.last_event_at,
        'pending',      v_wh_health.unresponded
      ),
      'cron_jobs', jsonb_build_object(
        'disabled_count', COALESCE(v_cron_failing, 0),
        'status', CASE WHEN COALESCE(v_cron_failing,0)=0 THEN 'ok' ELSE 'warning' END
      ),
      'incidents', jsonb_build_object(
        'open_count', COALESCE(v_open_inc, 0),
        'status', CASE WHEN COALESCE(v_open_inc,0)=0 THEN 'ok' ELSE 'warning' END
      ),
      'evo_api', jsonb_build_object(
        'instance',       'wpp2',
        'health_status',  COALESCE(v_evo_cred.health_status, 'unknown'),
        'last_check',     v_evo_cred.last_health_check
      ),
      'database', jsonb_build_object('status','ok','checked_at',now())
    ),
    'runbook_steps', 8,
    'generated_at', now()
  );

  RETURN v_result;
END;
$$;


--
-- Name: rpc_e2e_cleanup(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_e2e_cleanup() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp, evo, pg_temp'
    AS $$ DECLARE v_contacts int := 0; v_conversations int := 0; v_messages int := 0; v_evo_messages int := 0; v_evo_contacts int := 0; v_result jsonb; BEGIN WITH e2e_contacts AS (SELECT id FROM zapp.contacts WHERE phone LIKE '55119999999%' OR email LIKE '%@zappweb.test' OR name LIKE 'E2E %') DELETE FROM zapp.messages WHERE contact_id IN (SELECT id FROM e2e_contacts) OR remote_jid LIKE '55119999999%@s.whatsapp.net'; GET DIAGNOSTICS v_messages = ROW_COUNT; WITH e2e_contacts AS (SELECT id FROM zapp.contacts WHERE phone LIKE '55119999999%' OR email LIKE '%@zappweb.test' OR name LIKE 'E2E %') DELETE FROM zapp.conversations WHERE contact_id IN (SELECT id FROM e2e_contacts) OR remote_jid LIKE '55119999999%@s.whatsapp.net'; GET DIAGNOSTICS v_conversations = ROW_COUNT; DELETE FROM evo.evolution_messages WHERE remote_jid LIKE '55119999999%@s.whatsapp.net' AND created_at >= now() - interval '90 days'; GET DIAGNOSTICS v_evo_messages = ROW_COUNT; DELETE FROM evo.evolution_contacts WHERE remote_jid LIKE '55119999999%@s.whatsapp.net' AND created_at >= now() - interval '90 days'; GET DIAGNOSTICS v_evo_contacts = ROW_COUNT; DELETE FROM zapp.contacts WHERE phone LIKE '55119999999%' OR email LIKE '%@zappweb.test' OR name LIKE 'E2E %'; GET DIAGNOSTICS v_contacts = ROW_COUNT; v_result := jsonb_build_object('contacts_deleted', v_contacts, 'conversations_deleted', v_conversations, 'messages_deleted', v_messages, 'evo_messages_deleted', v_evo_messages, 'evo_contacts_deleted', v_evo_contacts); RETURN v_result; END; $$;


--
-- Name: rpc_e2e_seed_contacts(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_e2e_seed_contacts() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp, pg_temp'
    AS $$ DECLARE v_seeds jsonb := jsonb_build_array(jsonb_build_object('phone','5511999999901','name','E2E Contact Alpha','email','e2e-alpha@zappweb.test'), jsonb_build_object('phone','5511999999902','name','E2E Contact Beta','email','e2e-beta@zappweb.test'), jsonb_build_object('phone','5511999999903','name','E2E Contact Gamma','email','e2e-gamma@zappweb.test'), jsonb_build_object('phone','5511999999904','name','E2E Contact Delta','email','e2e-delta@zappweb.test'), jsonb_build_object('phone','5511999999905','name','E2E Contact Epsilon','email','e2e-epsilon@zappweb.test')); v_row jsonb; v_phone text; v_name text; v_email text; v_jid text; v_has_email boolean; v_has_jid boolean; v_has_active boolean; v_has_tags boolean; v_cols text; v_vals text; v_updates text; v_inserted int := 0; v_updated int := 0; v_id uuid; BEGIN SELECT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='zapp' AND table_name='contacts' AND column_name='email') INTO v_has_email; SELECT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='zapp' AND table_name='contacts' AND column_name='remote_jid') INTO v_has_jid; SELECT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='zapp' AND table_name='contacts' AND column_name='is_active') INTO v_has_active; SELECT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='zapp' AND table_name='contacts' AND column_name='tags') INTO v_has_tags; FOR v_row IN SELECT * FROM jsonb_array_elements(v_seeds) LOOP v_phone := v_row->>'phone'; v_name := v_row->>'name'; v_email := v_row->>'email'; v_jid := v_phone || '@s.whatsapp.net'; SELECT id INTO v_id FROM zapp.contacts WHERE phone = v_phone LIMIT 1; IF v_id IS NULL THEN v_cols := 'phone, name'; v_vals := format('%L, %L', v_phone, v_name); IF v_has_email THEN v_cols := v_cols || ', email'; v_vals := v_vals || format(', %L', v_email); END IF; IF v_has_jid THEN v_cols := v_cols || ', remote_jid'; v_vals := v_vals || format(', %L', v_jid); END IF; IF v_has_active THEN v_cols := v_cols || ', is_active'; v_vals := v_vals || ', true'; END IF; IF v_has_tags THEN v_cols := v_cols || ', tags'; v_vals := v_vals || format(', %L::text[]', '{e2e,seed}'); END IF; EXECUTE format('INSERT INTO zapp.contacts (%s) VALUES (%s)', v_cols, v_vals); v_inserted := v_inserted + 1; ELSE v_updates := 'name = ' || quote_literal(v_name); IF v_has_email THEN v_updates := v_updates || ', email = ' || quote_literal(v_email); END IF; IF v_has_jid THEN v_updates := v_updates || ', remote_jid = ' || quote_literal(v_jid); END IF; IF v_has_active THEN v_updates := v_updates || ', is_active = true'; END IF; EXECUTE format('UPDATE zapp.contacts SET %s WHERE id = %L', v_updates, v_id); v_updated := v_updated + 1; END IF; END LOOP; RETURN jsonb_build_object('kind','contacts','table','zapp.contacts','inserted',v_inserted,'updated',v_updated,'total',v_inserted+v_updated); END; $$;


--
-- Name: rpc_e2e_seed_user(text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_e2e_seed_user(p_email text, p_password text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions', 'public'
    AS $$ DECLARE v_user_id uuid; v_encrypted text; v_user_action text := 'unchanged'; v_roles_before int := 0; v_roles_after int := 0; v_roles_added int := 0; v_roles_list text[]; v_workspace uuid := 'd188f2f8-1ca3-4176-bcbc-1a1c481e24ad'; BEGIN IF p_email IS NULL OR p_password IS NULL OR p_email = '' OR p_password = '' THEN RETURN jsonb_build_object('ok', false, 'error', 'email e password obrigatorios'); END IF; v_encrypted := extensions.crypt(p_password, extensions.gen_salt('bf', 10)); SELECT id INTO v_user_id FROM auth.users WHERE email = p_email; IF v_user_id IS NULL THEN v_user_id := extensions.gen_random_uuid(); INSERT INTO auth.users (id, instance_id, aud, role, email, encrypted_password, email_confirmed_at, created_at, updated_at, raw_app_meta_data, raw_user_meta_data, is_super_admin) VALUES (v_user_id, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', p_email, v_encrypted, now(), now(), now(), jsonb_build_object('provider','email','providers',jsonb_build_array('email')), jsonb_build_object('name','E2E Bot','seed','e2e'), false); v_user_action := 'inserted'; ELSE UPDATE auth.users SET encrypted_password = v_encrypted, email_confirmed_at = COALESCE(email_confirmed_at, now()), updated_at = now(), banned_until = NULL, deleted_at = NULL WHERE id = v_user_id; v_user_action := 'updated'; END IF; INSERT INTO zapp.profiles (user_id, name, email, role, is_active, access_level) VALUES (v_user_id, 'E2E Bot', p_email, 'agent', true, 'agent') ON CONFLICT (user_id) DO UPDATE SET is_active = true, role = COALESCE(zapp.profiles.role, 'agent'), access_level = COALESCE(zapp.profiles.access_level, 'agent'), email = EXCLUDED.email, updated_at = now(); SELECT COUNT(*) INTO v_roles_before FROM zapp.user_roles WHERE user_id = v_user_id; INSERT INTO zapp.user_roles (id, user_id, role_key, workspace_id, role, created_at) VALUES (extensions.gen_random_uuid(), v_user_id, 'agent', v_workspace, 'agent', now()) ON CONFLICT (user_id, workspace_id) DO UPDATE SET role = 'agent', role_key = 'agent'; SELECT COUNT(*), array_agg(role::text ORDER BY role::text) INTO v_roles_after, v_roles_list FROM zapp.user_roles WHERE user_id = v_user_id; v_roles_added := v_roles_after - v_roles_before; RETURN jsonb_build_object('ok', true, 'email', p_email, 'user_id', v_user_id, 'user_action', v_user_action, 'roles', to_jsonb(v_roles_list), 'roles_total', v_roles_after, 'roles_added', v_roles_added); END; $$;


--
-- Name: rpc_e2e_validate_user(text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_e2e_validate_user(p_email text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp, pg_temp'
    AS $$ DECLARE v_user_id uuid; v_confirmed timestamptz; v_banned_until timestamptz; v_is_active boolean; v_role_count integer; v_has_crm boolean; v_checks jsonb; BEGIN IF p_email IS NULL OR p_email = '' THEN RETURN jsonb_build_object('valid', false, 'error', 'email vazio'); END IF; SELECT id, email_confirmed_at, banned_until INTO v_user_id, v_confirmed, v_banned_until FROM auth.users WHERE email = p_email; v_checks := jsonb_build_object('user_exists', v_user_id IS NOT NULL, 'email_confirmed', v_confirmed IS NOT NULL, 'not_banned', v_banned_until IS NULL OR v_banned_until <= now()); IF v_user_id IS NOT NULL THEN SELECT is_active INTO v_is_active FROM zapp.profiles WHERE user_id = v_user_id; v_checks := v_checks || jsonb_build_object('profile_exists', v_is_active IS NOT NULL, 'profile_active', v_is_active IS TRUE); SELECT count(*), bool_or(role::text IN ('agent','supervisor','admin')) INTO v_role_count, v_has_crm FROM zapp.user_roles WHERE user_id = v_user_id; v_checks := v_checks || jsonb_build_object('has_roles', coalesce(v_role_count,0) > 0, 'has_crm_role', coalesce(v_has_crm, false)); ELSE v_checks := v_checks || jsonb_build_object('profile_exists', false, 'profile_active', false, 'has_roles', false, 'has_crm_role', false); END IF; RETURN jsonb_build_object('valid', (v_checks->>'user_exists')::boolean AND (v_checks->>'email_confirmed')::boolean AND (v_checks->>'not_banned')::boolean AND (v_checks->>'profile_exists')::boolean AND (v_checks->>'profile_active')::boolean AND (v_checks->>'has_roles')::boolean AND (v_checks->>'has_crm_role')::boolean, 'email', p_email, 'checks', v_checks); END; $$;


--
-- Name: rpc_email_archive_thread(uuid, boolean); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_email_archive_thread(p_thread_id uuid, p_archived boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  UPDATE email_app.email_threads
  SET status = CASE WHEN COALESCE(p_archived, true) THEN 'archived' ELSE 'open' END, updated_at = now()
  WHERE id = p_thread_id;

  RETURN jsonb_build_object('archived', COALESCE(p_archived, true), 'thread_id', p_thread_id, 'archived_at', now());
END;
$$;


--
-- Name: rpc_email_assign_thread(uuid, text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_email_assign_thread(p_thread_id uuid, p_assignee text DEFAULT NULL::text, p_agent_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_assignee text;
BEGIN
  v_assignee := COALESCE(p_agent_id, p_assignee);

  UPDATE email_app.email_threads SET assigned_to = v_assignee, updated_at = now() WHERE id = p_thread_id;

  RETURN jsonb_build_object('updated', true, 'thread_id', p_thread_id, 'assigned_to', v_assignee);
END;
$$;


--
-- Name: rpc_email_cleanup_old_events(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_email_cleanup_old_events(p_retention_days integer DEFAULT 90) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_deleted_events int;
  v_deleted_clicks int;
  v_cutoff timestamptz;
BEGIN
  v_cutoff := now() - (p_retention_days || ' days')::interval;

  -- Delete old tracking events (keep the aggregated counts in tracked_messages)
  DELETE FROM email_tracking_events WHERE created_at < v_cutoff;
  GET DIAGNOSTICS v_deleted_events = ROW_COUNT;

  -- Delete old click events
  DELETE FROM email_link_click_events WHERE created_at < v_cutoff;
  GET DIAGNOSTICS v_deleted_clicks = ROW_COUNT;

  RETURN jsonb_build_object(
    'ok', true,
    'deleted_events', v_deleted_events,
    'deleted_clicks', v_deleted_clicks,
    'cutoff_date', v_cutoff
  );
END;
$$;


--
-- Name: rpc_email_create_tracking(text, text, text, text, text, text, text, uuid, jsonb, jsonb); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_email_create_tracking(p_recipient_email text, p_recipient_name text DEFAULT NULL::text, p_sender_email text DEFAULT ''::text, p_subject text DEFAULT ''::text, p_thread_id text DEFAULT NULL::text, p_gmail_message_id text DEFAULT NULL::text, p_provider text DEFAULT 'gmail'::text, p_account_id uuid DEFAULT NULL::uuid, p_links jsonb DEFAULT '[]'::jsonb, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tracking_id uuid;
  v_link_count int := 0;
  v_link record;
  v_link_ids jsonb := '[]'::jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error', 'auth required');
  END IF;

  -- 1. Criar tracked message
  INSERT INTO email_tracked_messages (
    user_id, account_id, provider, recipient_email, recipient_name,
    sender_email, subject, thread_id, gmail_message_id,
    has_tracking_pixel, has_tracked_links,
    tracked_link_count, metadata
  ) VALUES (
    v_uid, p_account_id, p_provider, p_recipient_email, p_recipient_name,
    p_sender_email, p_subject, p_thread_id, p_gmail_message_id,
    true, (jsonb_array_length(p_links) > 0),
    jsonb_array_length(p_links), p_metadata
  )
  RETURNING tracking_id INTO v_tracking_id;

  -- 2. Criar links rastreados
  IF jsonb_array_length(p_links) > 0 THEN
    FOR v_link IN SELECT * FROM jsonb_array_elements(p_links) WITH ORDINALITY AS t(val, pos)
    LOOP
      INSERT INTO email_tracked_links (
        tracking_id, original_url, display_text, position
      ) VALUES (
        v_tracking_id,
        v_link.val->>'url',
        v_link.val->>'text',
        (v_link.pos - 1)::int
      );
      v_link_count := v_link_count + 1;
    END LOOP;
  END IF;

  -- 3. UPSERT contact score (total_sent)
  INSERT INTO email_contact_scores (
    user_id, email, display_name, total_sent
  ) VALUES (
    v_uid, p_recipient_email, p_recipient_name, 1
  )
  ON CONFLICT (user_id, email) DO UPDATE SET
    total_sent = email_contact_scores.total_sent + 1,
    display_name = COALESCE(EXCLUDED.display_name, email_contact_scores.display_name),
    updated_at = now();

  -- 4. Buscar link_ids criados
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object('link_id', link_id, 'original_url', original_url, 'position', position)
  ), '[]'::jsonb) INTO v_link_ids
  FROM email_tracked_links WHERE tracking_id = v_tracking_id;

  RETURN jsonb_build_object(
    'ok', true,
    'tracking_id', v_tracking_id,
    'link_count', v_link_count,
    'links', v_link_ids
  );
END;
$$;


--
-- Name: rpc_email_device_breakdown(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_email_device_breakdown(p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RETURN '{}'::jsonb; END IF;

  RETURN jsonb_build_object(
    'by_device', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('device', device_type, 'count', cnt)), '[]'::jsonb)
      FROM (
        SELECT e.device_type, COUNT(*) as cnt
        FROM email_tracking_events e
        JOIN email_tracked_messages m ON m.tracking_id = e.tracking_id
        WHERE m.user_id = v_uid AND e.created_at >= now() - (p_days || ' days')::interval
          AND e.is_bot = false
        GROUP BY e.device_type ORDER BY cnt DESC
      ) sub
    ),
    'by_browser', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('browser', browser, 'count', cnt)), '[]'::jsonb)
      FROM (
        SELECT e.browser, COUNT(*) as cnt
        FROM email_tracking_events e
        JOIN email_tracked_messages m ON m.tracking_id = e.tracking_id
        WHERE m.user_id = v_uid AND e.created_at >= now() - (p_days || ' days')::interval
          AND e.is_bot = false
        GROUP BY e.browser ORDER BY cnt DESC
      ) sub
    ),
    'by_country', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('country', country, 'count', cnt)), '[]'::jsonb)
      FROM (
        SELECT e.country, COUNT(*) as cnt
        FROM email_tracking_events e
        JOIN email_tracked_messages m ON m.tracking_id = e.tracking_id
        WHERE m.user_id = v_uid AND e.created_at >= now() - (p_days || ' days')::interval
          AND e.country IS NOT NULL AND e.is_bot = false
        GROUP BY e.country ORDER BY cnt DESC LIMIT 20
      ) sub
    ),
    'bot_percentage', (
      SELECT ROUND(
        (COUNT(*) FILTER (WHERE e.is_bot = true)::numeric /
         NULLIF(COUNT(*), 0)) * 100, 1
      )
      FROM email_tracking_events e
      JOIN email_tracked_messages m ON m.tracking_id = e.tracking_id
      WHERE m.user_id = v_uid AND e.created_at >= now() - (p_days || ' days')::interval
    )
  );
END;
$$;


--
-- Name: rpc_email_health_check(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_email_health_check() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_result jsonb := '{}'::jsonb;
  v_count bigint;
  v_ok boolean := true;
BEGIN
  -- Check tables
  SELECT COUNT(*) INTO v_count FROM pg_tables WHERE schemaname='public' 
    AND tablename IN ('email_tracked_messages','email_tracking_events','email_tracked_links','email_link_click_events','email_contact_scores');
  v_result := v_result || jsonb_build_object('tracking_tables', v_count, 'tables_ok', v_count = 5);
  IF v_count != 5 THEN v_ok := false; END IF;

  -- Check RPCs
  SELECT COUNT(*) INTO v_count FROM pg_proc WHERE proname LIKE 'rpc_email_%';
  v_result := v_result || jsonb_build_object('rpcs', v_count, 'rpcs_ok', v_count >= 10);

  -- Check RLS
  SELECT COUNT(*) INTO v_count FROM pg_tables WHERE schemaname='public' 
    AND tablename IN ('email_tracked_messages','email_tracking_events','email_tracked_links','email_link_click_events','email_contact_scores')
    AND rowsecurity = true;
  v_result := v_result || jsonb_build_object('rls_enabled', v_count, 'rls_ok', v_count = 5);
  IF v_count != 5 THEN v_ok := false; END IF;

  -- Check indexes
  SELECT COUNT(*) INTO v_count FROM pg_indexes WHERE schemaname='public' AND tablename LIKE 'email_track%' AND indexname LIKE 'idx_%';
  v_result := v_result || jsonb_build_object('indexes', v_count, 'indexes_ok', v_count >= 10);

  -- Check edge functions (via HTTP would need separate test)
  v_result := v_result || jsonb_build_object('edge_functions', jsonb_build_array('email-track-pixel', 'email-track-link'));

  -- Data stats
  SELECT COUNT(*) INTO v_count FROM email_tracked_messages;
  v_result := v_result || jsonb_build_object('total_tracked_messages', v_count);
  SELECT COUNT(*) INTO v_count FROM email_tracking_events;
  v_result := v_result || jsonb_build_object('total_events', v_count);
  SELECT COUNT(*) INTO v_count FROM email_contact_scores;
  v_result := v_result || jsonb_build_object('total_contacts_scored', v_count);

  -- Realtime
  SELECT COUNT(*) INTO v_count FROM pg_publication_tables WHERE pubname='supabase_realtime' AND tablename IN ('email_tracking_events','email_tracked_messages');
  v_result := v_result || jsonb_build_object('realtime_tables', v_count);

  -- FTS
  SELECT EXISTS(SELECT 1 FROM pg_indexes WHERE tablename='email_messages' AND indexdef LIKE '%gin%fts%') INTO v_ok;
  v_result := v_result || jsonb_build_object('fts_enabled', v_ok);

  v_result := v_result || jsonb_build_object('status', CASE WHEN v_ok THEN 'healthy' ELSE 'degraded' END, 'checked_at', now());

  RETURN v_result;
END;
$$;


--
-- Name: rpc_email_link_performance(uuid, integer, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_email_link_performance(p_tracking_id uuid DEFAULT NULL::uuid, p_days integer DEFAULT 30, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RETURN '[]'::jsonb; END IF;

  -- If tracking_id provided, show links for that specific email
  IF p_tracking_id IS NOT NULL THEN
    RETURN (
      SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
          'link_id', l.link_id,
          'original_url', l.original_url,
          'display_text', l.display_text,
          'position', l.position,
          'click_count', l.click_count,
          'first_clicked_at', l.first_clicked_at,
          'last_clicked_at', l.last_clicked_at
        ) ORDER BY l.click_count DESC
      ), '[]'::jsonb)
      FROM email_tracked_links l
      JOIN email_tracked_messages m ON m.tracking_id = l.tracking_id
      WHERE l.tracking_id = p_tracking_id AND m.user_id = v_uid
    );
  END IF;

  -- Otherwise, show top links across all emails
  RETURN (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'original_url', sub.original_url,
        'total_clicks', sub.total_clicks,
        'email_count', sub.email_count,
        'avg_clicks', sub.avg_clicks
      ) ORDER BY sub.total_clicks DESC
    ), '[]'::jsonb)
    FROM (
      SELECT
        l.original_url,
        SUM(l.click_count) as total_clicks,
        COUNT(DISTINCT l.tracking_id) as email_count,
        ROUND(AVG(l.click_count), 1) as avg_clicks
      FROM email_tracked_links l
      JOIN email_tracked_messages m ON m.tracking_id = l.tracking_id
      WHERE m.user_id = v_uid
        AND l.created_at >= now() - (p_days || ' days')::interval
        AND l.click_count > 0
      GROUP BY l.original_url
      ORDER BY total_clicks DESC
      LIMIT p_limit
    ) sub
  );
END;
$$;


--
-- Name: rpc_email_mark_thread_read(uuid, boolean, boolean, uuid[]); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_email_mark_thread_read(p_thread_id uuid, p_read boolean DEFAULT NULL::boolean, p_unread boolean DEFAULT NULL::boolean, p_message_ids uuid[] DEFAULT NULL::uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_unread boolean;
BEGIN
  v_unread := CASE WHEN p_unread IS NOT NULL THEN p_unread
                   WHEN p_read   IS NOT NULL THEN NOT p_read
                   ELSE false END;

  UPDATE email_app.email_threads SET is_unread = v_unread, updated_at = now() WHERE id = p_thread_id;

  UPDATE email_app.email_messages SET is_read = NOT v_unread
  WHERE thread_id = p_thread_id AND (p_message_ids IS NULL OR id = ANY(p_message_ids));

  RETURN jsonb_build_object('updated', true, 'thread_id', p_thread_id, 'is_unread', v_unread);
END;
$$;


--
-- Name: rpc_email_message_details(uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_email_message_details(p_tracking_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_msg jsonb;
  v_events jsonb;
  v_links jsonb;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('error', 'auth required'); END IF;

  -- Message details
  SELECT jsonb_build_object(
    'id', m.id, 'tracking_id', m.tracking_id, 'recipient_email', m.recipient_email,
    'recipient_name', m.recipient_name, 'sender_email', m.sender_email,
    'subject', m.subject, 'provider', m.provider, 'delivery_status', m.delivery_status,
    'bounce_type', m.bounce_type, 'open_count', m.open_count, 'click_count', m.click_count,
    'first_opened_at', m.first_opened_at, 'last_opened_at', m.last_opened_at,
    'created_at', m.created_at, 'metadata', m.metadata
  ) INTO v_msg
  FROM email_tracked_messages m
  WHERE m.tracking_id = p_tracking_id AND m.user_id = v_uid;

  IF v_msg IS NULL THEN RETURN jsonb_build_object('error', 'not found'); END IF;

  -- Open events (last 50)
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'event_type', e.event_type, 'device_type', e.device_type, 'browser', e.browser,
    'os', e.os, 'country', e.country, 'city', e.city, 'is_bot', e.is_bot,
    'created_at', e.created_at
  ) ORDER BY e.created_at DESC), '[]'::jsonb) INTO v_events
  FROM email_tracking_events e WHERE e.tracking_id = p_tracking_id LIMIT 50;

  -- Links with click details
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'link_id', l.link_id, 'original_url', l.original_url, 'display_text', l.display_text,
    'position', l.position, 'click_count', l.click_count,
    'first_clicked_at', l.first_clicked_at, 'last_clicked_at', l.last_clicked_at
  ) ORDER BY l.position), '[]'::jsonb) INTO v_links
  FROM email_tracked_links l WHERE l.tracking_id = p_tracking_id;

  RETURN jsonb_build_object(
    'message', v_msg,
    'events', v_events,
    'links', v_links
  );
END;
$$;


--
-- Name: rpc_email_register_bounce(uuid, text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_email_register_bounce(p_tracking_id uuid, p_bounce_type text DEFAULT 'soft'::text, p_error_message text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  UPDATE zapp.email_tracked_messages
  SET delivery_status='bounced', bounce_type=p_bounce_type,
      metadata=metadata||jsonb_build_object('bounce_error',p_error_message,'bounced_at',now()),
      updated_at=now()
  WHERE tracking_id=p_tracking_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error','tracking_id not found'); END IF;
  RETURN jsonb_build_object('ok',true,'bounce_type',p_bounce_type);
END; $$;


--
-- Name: rpc_email_register_click(uuid, text, text, text, text, text, text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_email_register_click(p_link_id uuid, p_ip text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text, p_country text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_device_type text DEFAULT 'unknown'::text, p_browser text DEFAULT 'unknown'::text, p_os text DEFAULT 'unknown'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_link record; v_msg record; v_now timestamptz := now();
BEGIN
  SELECT link_id, tracking_id, original_url INTO v_link FROM zapp.email_tracked_links WHERE link_id = p_link_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'link_id not found'); END IF;

  SELECT user_id, recipient_email INTO v_msg FROM zapp.email_tracked_messages WHERE tracking_id = v_link.tracking_id;

  INSERT INTO zapp.email_link_click_events (
    link_id, tracking_id, ip_address, user_agent, country, city, device_type, browser, os
  ) VALUES (p_link_id, v_link.tracking_id, p_ip::inet, p_user_agent, p_country, p_city, p_device_type, p_browser, p_os);

  UPDATE zapp.email_tracked_links SET click_count = click_count + 1,
    first_clicked_at = COALESCE(first_clicked_at, v_now), last_clicked_at = v_now
  WHERE link_id = p_link_id;

  UPDATE zapp.email_tracked_messages SET click_count = click_count + 1, updated_at = v_now
  WHERE tracking_id = v_link.tracking_id;

  IF v_msg IS NOT NULL THEN
    INSERT INTO zapp.email_contact_scores (user_id, email, total_clicks, engagement_score, last_interaction)
    VALUES (v_msg.user_id, v_msg.recipient_email, 1, 2, v_now)
    ON CONFLICT (user_id, email) DO UPDATE SET
      total_clicks = email_contact_scores.total_clicks + 1,
      engagement_score = email_contact_scores.engagement_score + 2,
      last_interaction = v_now, updated_at = v_now;
  END IF;

  RETURN jsonb_build_object('ok', true, 'original_url', v_link.original_url);
END;
$$;


--
-- Name: rpc_email_register_failure(uuid, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_email_register_failure(p_tracking_id uuid, p_error text DEFAULT 'unknown'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  UPDATE zapp.email_tracked_messages
  SET delivery_status='failed',
      metadata=metadata||jsonb_build_object('failure_error',p_error,'failed_at',now()),
      updated_at=now()
  WHERE tracking_id=p_tracking_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error','tracking_id not found'); END IF;
  RETURN jsonb_build_object('ok',true);
END; $$;


--
-- Name: rpc_email_register_open(uuid, text, text, text, text, text, text, text, boolean); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_email_register_open(p_tracking_id uuid, p_ip text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text, p_country text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_device_type text DEFAULT 'unknown'::text, p_browser text DEFAULT 'unknown'::text, p_os text DEFAULT 'unknown'::text, p_is_self_open boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_msg record;
  v_is_bot boolean := false;
  v_now timestamptz := now();
BEGIN
  SELECT id, user_id, recipient_email, open_count
    INTO v_msg FROM zapp.email_tracked_messages
   WHERE tracking_id = p_tracking_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'tracking_id not found'); END IF;

  v_is_bot := (p_device_type = 'bot');

  INSERT INTO zapp.email_tracking_events (
    tracking_id, event_type, ip_address, user_agent,
    country, city, device_type, browser, os, is_self_open, is_bot
  ) VALUES (
    p_tracking_id, 'open', p_ip::inet, p_user_agent,
    p_country, p_city, p_device_type, p_browser, p_os,
    p_is_self_open, v_is_bot
  );

  UPDATE zapp.email_tracked_messages
     SET open_count = open_count + 1,
         first_opened_at = COALESCE(first_opened_at, v_now),
         last_opened_at = v_now,
         delivery_status = CASE WHEN delivery_status = 'sent' THEN 'delivered' ELSE delivery_status END,
         updated_at = v_now
   WHERE tracking_id = p_tracking_id;

  INSERT INTO zapp.email_contact_scores (user_id, email, total_opens, engagement_score, last_interaction)
  VALUES (v_msg.user_id, v_msg.recipient_email, 1, 1, v_now)
  ON CONFLICT (user_id, email) DO UPDATE SET
    total_opens = email_contact_scores.total_opens + 1,
    engagement_score = email_contact_scores.engagement_score + 1,
    last_interaction = v_now,
    updated_at = v_now;

  RETURN jsonb_build_object('ok', true, 'open_count', v_msg.open_count + 1);
END;
$$;


--
-- Name: rpc_email_search(text, uuid, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_email_search(p_query text, p_account_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tsquery tsquery;
BEGIN
  IF v_uid IS NULL THEN RETURN '[]'::jsonb; END IF;
  
  -- Converter query para tsquery com tratamento de erros
  BEGIN
    v_tsquery := plainto_tsquery('portuguese', p_query);
  EXCEPTION WHEN OTHERS THEN
    v_tsquery := to_tsquery('portuguese', regexp_replace(p_query, '[^a-zA-Z0-9à-ú\s]', '', 'g'));
  END;

  RETURN (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', m.id,
        'thread_id', m.thread_id,
        'subject', m.subject,
        'snippet', m.snippet,
        'from_name', m.from_name,
        'from_address', m.from_address,
        'internal_date', m.internal_date,
        'is_read', m.is_read,
        'has_attachments', m.has_attachments,
        'rank', ts_rank(m.fts_vector, v_tsquery)
      ) ORDER BY ts_rank(m.fts_vector, v_tsquery) DESC
    ), '[]'::jsonb)
    FROM email_messages m
    WHERE m.fts_vector @@ v_tsquery
      AND (p_account_id IS NULL OR m.gmail_account_id = p_account_id)
    LIMIT p_limit
  );
END;
$$;


--
-- Name: rpc_email_search_threads(text, uuid, text, text, integer, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_email_search_threads(p_query text DEFAULT NULL::text, p_account_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text, p_label_id text DEFAULT NULL::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v jsonb;
  v_limit  integer := LEAST(GREATEST(COALESCE(p_limit, 20), 0), 200);
  v_offset integer := GREATEST(COALESCE(p_offset, 0), 0);
  v_label  text    := NULLIF(btrim(COALESCE(p_label_id, '')), '');
BEGIN
  -- Guard: apenas usuarios autenticados podem buscar threads
  IF auth.uid() IS NULL THEN
    RETURN '[]'::jsonb;
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(t)), '[]'::jsonb) INTO v FROM (
    SELECT id, id AS thread_id, gmail_thread_id::text AS email_thread_id,
           gmail_account_id AS account_id, subject, snippet, status,
           is_starred, is_unread, is_important,
           CASE WHEN is_unread THEN GREATEST(COALESCE(message_count,1),1) ELSE 0 END AS unread_count,
           last_message_at, message_count, assigned_to, sla_status, first_reply_at, created_at
    FROM email_app.email_threads
    WHERE (p_account_id IS NULL OR gmail_account_id = p_account_id)
      AND (p_status IS NULL OR status = p_status)
      AND (
        p_status IS NOT NULL
        OR v_label IS NULL
        OR upper(v_label) = 'INBOX'
        OR (upper(v_label) = 'ARCHIVE'   AND status = 'archived')
        OR (upper(v_label) = 'STARRED'   AND is_starred IS TRUE)
        OR (upper(v_label) = 'IMPORTANT' AND is_important IS TRUE)
        OR (upper(v_label) NOT IN ('INBOX','ARCHIVE','STARRED','IMPORTANT') AND label_ids ILIKE '%' || v_label || '%')
      )
      AND (p_status IS NOT NULL OR v_label IS NULL OR upper(v_label) <> 'INBOX' OR status IS DISTINCT FROM 'archived')
      AND (p_query IS NULL OR subject ILIKE '%' || p_query || '%' OR snippet ILIKE '%' || p_query || '%')
    ORDER BY last_message_at DESC NULLS LAST
    LIMIT v_limit OFFSET v_offset
  ) t;
  RETURN v;
END;
$$;


--
-- Name: rpc_email_star_thread(uuid, boolean); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_email_star_thread(p_thread_id uuid, p_starred boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  UPDATE zapp.email_threads
  SET is_starred = p_starred
  WHERE id = p_thread_id;

  RETURN jsonb_build_object('updated', true, 'thread_id', p_thread_id, 'starred', p_starred);
END;
$$;


--
-- Name: rpc_email_token_status(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_email_token_status() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_total    integer;
  v_expired  integer;
  v_expiring integer;
BEGIN
  SELECT
    count(*),
    count(*) FILTER (WHERE token_expires_at < now()),
    count(*) FILTER (WHERE token_expires_at BETWEEN now() AND now() + interval '24 hours')
  INTO v_total, v_expired, v_expiring
  FROM zapp.email_accounts
  WHERE user_id = auth.uid() AND is_active = true;

  RETURN jsonb_build_object(
    'total_accounts',    COALESCE(v_total, 0),
    'expired_tokens',    COALESCE(v_expired, 0),
    'expiring_soon',     COALESCE(v_expiring, 0),
    'all_valid',         COALESCE(v_expired, 0) = 0,
    'checked_at',        now()
  );
END;
$$;


--
-- Name: rpc_email_top_contacts(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_email_top_contacts(p_limit integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RETURN '[]'::jsonb;
  END IF;

  RETURN (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'email',            c.email,
        'display_name',     c.display_name,
        'engagement_score', c.engagement_score,
        'total_opens',      c.total_opens,
        'total_clicks',     c.total_clicks,
        'last_interaction', c.last_interaction
      )
    ), '[]'::jsonb)
    FROM (
      SELECT email, display_name, engagement_score, total_opens, total_clicks, last_interaction
        FROM zapp.email_contact_scores
       WHERE user_id = v_uid
         AND engagement_score > 0
       ORDER BY engagement_score DESC
       LIMIT p_limit
    ) c
  );
END;
$$;


--
-- Name: rpc_email_tracking_daily_series(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_email_tracking_daily_series(p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RETURN '[]'::jsonb; END IF;

  RETURN (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'date', d.day::date,
        'opens', COALESCE((
          SELECT COUNT(*) FROM email_tracking_events e
          JOIN email_tracked_messages m ON m.tracking_id = e.tracking_id
          WHERE m.user_id = v_uid
            AND e.created_at::date = d.day::date
            AND e.event_type = 'open'
            AND e.is_bot = false
        ), 0),
        'clicks', COALESCE((
          SELECT COUNT(*) FROM email_link_click_events c
          JOIN email_tracked_messages m ON m.tracking_id = c.tracking_id
          WHERE m.user_id = v_uid
            AND c.created_at::date = d.day::date
        ), 0),
        'sent', COALESCE((
          SELECT COUNT(*) FROM email_tracked_messages
          WHERE user_id = v_uid AND created_at::date = d.day::date
        ), 0)
      ) ORDER BY d.day
    ), '[]'::jsonb)
    FROM generate_series(
      (now() - (p_days || ' days')::interval)::date,
      now()::date,
      '1 day'::interval
    ) AS d(day)
  );
END;
$$;


--
-- Name: rpc_email_tracking_stats(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_email_tracking_stats(p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_uid           uuid := auth.uid();
  v_total         int;
  v_total_opens   bigint;
  v_total_clicks  bigint;
  v_unique_opens  int;
  v_bounces       int;
  v_open_rate     numeric;
  v_click_rate    numeric;
  v_avg_opens     numeric;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error', 'auth required');
  END IF;

  -- Total de emails rastreados no período
  SELECT COUNT(*)
    INTO v_total
    FROM zapp.email_tracked_messages
   WHERE user_id = v_uid
     AND created_at >= (now() - (p_days || ' days')::interval);

  IF v_total = 0 THEN
    RETURN jsonb_build_object(
      'total_tracked', 0, 'total_opens', 0, 'total_clicks', 0,
      'unique_opens', 0, 'open_rate', 0, 'click_rate', 0,
      'bounce_count', 0, 'avg_opens_per_email', NULL, 'period_days', p_days
    );
  END IF;

  -- Total opens e clicks
  SELECT COALESCE(SUM(open_count), 0), COALESCE(SUM(click_count), 0)
    INTO v_total_opens, v_total_clicks
    FROM zapp.email_tracked_messages
   WHERE user_id = v_uid
     AND created_at >= (now() - (p_days || ' days')::interval);

  -- Unique opens (emails que foram abertos pelo menos 1x)
  SELECT COUNT(*)
    INTO v_unique_opens
    FROM zapp.email_tracked_messages
   WHERE user_id = v_uid
     AND created_at >= (now() - (p_days || ' days')::interval)
     AND open_count > 0;

  -- Bounces
  SELECT COUNT(*)
    INTO v_bounces
    FROM zapp.email_tracked_messages
   WHERE user_id = v_uid
     AND created_at >= (now() - (p_days || ' days')::interval)
     AND delivery_status = 'bounced';

  -- Taxas
  v_open_rate  := ROUND((v_unique_opens::numeric / v_total) * 100, 1);
  v_click_rate := ROUND((CASE WHEN v_unique_opens > 0 THEN v_total_clicks::numeric / v_unique_opens ELSE 0 END) * 100, 1);
  v_avg_opens  := CASE WHEN v_unique_opens > 0 THEN ROUND(v_total_opens::numeric / v_unique_opens, 1) ELSE NULL END;

  RETURN jsonb_build_object(
    'total_tracked',       v_total,
    'total_opens',         v_total_opens,
    'total_clicks',        v_total_clicks,
    'unique_opens',        v_unique_opens,
    'open_rate',           v_open_rate,
    'click_rate',          v_click_rate,
    'bounce_count',        v_bounces,
    'avg_opens_per_email', v_avg_opens,
    'period_days',         p_days
  );
END;
$$;


--
-- Name: rpc_email_unopened_followup(integer, integer, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_email_unopened_followup(p_min_hours integer DEFAULT 24, p_max_days integer DEFAULT 7, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RETURN '[]'::jsonb; END IF;
  RETURN (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'tracking_id', m.tracking_id,
        'recipient_email', m.recipient_email,
        'recipient_name', m.recipient_name,
        'subject', m.subject,
        'sent_at', m.created_at,
        'hours_ago', EXTRACT(EPOCH FROM now()-m.created_at)/3600
      ) ORDER BY m.created_at
    ), '[]'::jsonb)
    FROM email_tracked_messages m
    WHERE m.user_id = v_uid
      AND m.open_count = 0
      AND m.delivery_status IN ('sent','delivered')
      AND m.created_at < now() - (p_min_hours || ' hours')::interval
      AND m.created_at > now() - (p_max_days || ' days')::interval
    LIMIT p_limit
  );
END; $$;


--
-- Name: rpc_email_unopened_list(integer, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_email_unopened_list(p_days integer DEFAULT 7, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RETURN '[]'::jsonb; END IF;

  RETURN (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'tracking_id', m.tracking_id,
        'recipient_email', m.recipient_email,
        'recipient_name', m.recipient_name,
        'subject', m.subject,
        'sent_at', m.created_at,
        'hours_ago', ROUND(EXTRACT(EPOCH FROM now() - m.created_at) / 3600, 1)
      ) ORDER BY m.created_at DESC
    ), '[]'::jsonb)
    FROM email_tracked_messages m
    WHERE m.user_id = v_uid
      AND m.open_count = 0
      AND m.delivery_status IN ('sent', 'delivered')
      AND m.created_at >= now() - (p_days || ' days')::interval
    LIMIT p_limit
  );
END;
$$;


--
-- Name: rpc_email_update_delivery(uuid, text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_email_update_delivery(p_tracking_id uuid, p_status text, p_bounce_type text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error', 'auth required');
  END IF;

  IF p_status NOT IN ('sent','delivered','bounced','deferred','failed') THEN
    RETURN jsonb_build_object('error', 'invalid status');
  END IF;

  UPDATE email_tracked_messages
  SET delivery_status = p_status,
      bounce_type = CASE WHEN p_status = 'bounced' THEN COALESCE(p_bounce_type, 'soft') ELSE bounce_type END,
      updated_at = now()
  WHERE tracking_id = p_tracking_id AND user_id = v_uid;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'tracking_id not found or unauthorized');
  END IF;

  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: rpc_enqueue_reprocess(text, uuid, text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_enqueue_reprocess(p_target_kind text, p_target_id uuid, p_action text, p_reason text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_key TEXT;
  v_id UUID;
BEGIN
  IF NOT zapp.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Access denied: admin role required';
  END IF;

  v_key := encode(digest(
    p_target_kind || ':' || p_target_id::text || ':' || p_action || ':' ||
    COALESCE(auth.uid()::text, 'system') || ':' ||
    to_char(date_trunc('hour', now()), 'YYYY-MM-DD HH24'),
    'sha256'
  ), 'hex');

  INSERT INTO zapp.reprocess_jobs (
    idempotency_key, target_kind, target_id, action, requested_by, reason
  )
  VALUES (v_key, p_target_kind, p_target_id, p_action, auth.uid(), p_reason)
  ON CONFLICT (idempotency_key) DO UPDATE
    SET reason = COALESCE(EXCLUDED.reason, reprocess_jobs.reason),
        updated_at = now()
  RETURNING id INTO v_id;

  INSERT INTO zapp.audit_logs (user_id, action, entity_type, entity_id, details)
  VALUES (
    auth.uid(),
    'reprocess_enqueued',
    'reprocess_jobs',
    v_id::text,
    jsonb_build_object(
      'target_kind', p_target_kind,
      'target_id', p_target_id,
      'action', p_action,
      'reason', p_reason
    )
  );

  RETURN v_id;
END;
$$;


--
-- Name: rpc_evolution_fallback_stats(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_evolution_fallback_stats(p_hours integer DEFAULT 24) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_hours integer;
  v_total bigint;
  v_total_7d bigint;
  v_total_1h bigint;
  v_last_event timestamptz;
  v_first_event timestamptz;
  v_by_action jsonb;
  v_by_reason jsonb;
  v_by_instance jsonb;
  v_recent jsonb;
BEGIN
  IF NOT zapp.is_admin_or_supervisor(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied: admin or supervisor role required';
  END IF;

  v_hours := GREATEST(1, LEAST(COALESCE(p_hours, 24), 720));

  SELECT COUNT(*), MIN(ts), MAX(ts)
    INTO v_total, v_first_event, v_last_event
    FROM zapp.evolution_fallback_events
   WHERE ts > now() - (v_hours || ' hours')::interval;

  SELECT COUNT(*) INTO v_total_7d
    FROM zapp.evolution_fallback_events
   WHERE ts > now() - interval '7 days';

  SELECT COUNT(*) INTO v_total_1h
    FROM zapp.evolution_fallback_events
   WHERE ts > now() - interval '1 hour';

  SELECT COALESCE(jsonb_agg(t.*), '[]'::jsonb) INTO v_by_action FROM (
    SELECT action, COUNT(*)::int AS count
      FROM zapp.evolution_fallback_events
     WHERE ts > now() - (v_hours || ' hours')::interval
     GROUP BY action
     ORDER BY COUNT(*) DESC
  ) t;

  SELECT COALESCE(jsonb_agg(t.*), '[]'::jsonb) INTO v_by_reason FROM (
    SELECT reason, COUNT(*)::int AS count
      FROM zapp.evolution_fallback_events
     WHERE ts > now() - (v_hours || ' hours')::interval
     GROUP BY reason
     ORDER BY COUNT(*) DESC
  ) t;

  SELECT COALESCE(jsonb_agg(t.*), '[]'::jsonb) INTO v_by_instance FROM (
    SELECT COALESCE(instance, '(sem instância)') AS instance, COUNT(*)::int AS count
      FROM zapp.evolution_fallback_events
     WHERE ts > now() - (v_hours || ' hours')::interval
     GROUP BY instance
     ORDER BY COUNT(*) DESC
     LIMIT 10
  ) t;

  SELECT COALESCE(jsonb_agg(t.* ORDER BY t.ts DESC), '[]'::jsonb) INTO v_recent FROM (
    SELECT ts, action, instance, status, reason, mode, fallback_target, primary_ms
      FROM zapp.evolution_fallback_events
     WHERE ts > now() - (v_hours || ' hours')::interval
     ORDER BY ts DESC
     LIMIT 25
  ) t;

  RETURN jsonb_build_object(
    'window_hours', v_hours,
    'total', COALESCE(v_total, 0),
    'total_last_hour', COALESCE(v_total_1h, 0),
    'total_last_7d', COALESCE(v_total_7d, 0),
    'first_event_at', v_first_event,
    'last_event_at', v_last_event,
    'by_action', v_by_action,
    'by_reason', v_by_reason,
    'by_instance', v_by_instance,
    'recent', v_recent
  );
END;
$$;


--
-- Name: rpc_fail_media_download(bigint, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_fail_media_download(p_queue_id bigint, p_error text DEFAULT 'Unknown error'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  UPDATE media_download_queue 
  SET 
    status = CASE WHEN retry_count + 1 >= max_retries THEN 'failed' ELSE 'pending' END,
    retry_count = retry_count + 1,
    error_message = p_error,
    processed_at = now()
  WHERE id = p_queue_id;
END;
$$;


--
-- Name: rpc_find_contact_by_phone(text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_find_contact_by_phone(p_phone text) RETURNS TABLE(id uuid, name text, phone text, remote_jid text, instance_name character varying)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  cleaned text;
BEGIN
  PERFORM zapp.fn_require_app_user();

  cleaned := zapp.fn_normalize_br_phone(p_phone);
  RETURN QUERY
  SELECT ec.id, COALESCE(ec.full_name, ec.push_name)::text, ec.phone_number::text, ec.remote_jid::text, ec.instance_name
  FROM evolution_contacts ec
  WHERE ec.deleted_at IS NULL
    AND (
      ec.phone_number = cleaned
      OR ec.phone_number = p_phone
      OR split_part(ec.remote_jid, '@', 1) = cleaned
      OR split_part(ec.remote_jid, '@', 1) = p_phone
    )
  LIMIT 5;
END;
$$;


