--
-- Name: rpc_get_contact(uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_get_contact(p_contact_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
DECLARE v_result jsonb;
BEGIN
  PERFORM zapp.fn_require_app_user();

  SELECT jsonb_build_object(
    'contact',         to_jsonb(c.*),
    'deals',           COALESCE((
                         SELECT jsonb_agg(to_jsonb(d.*))
                         FROM evo.evolution_deals d
                         WHERE d.contact_id = c.id
                       ), '[]'),
    'recent_messages', COALESCE((
                         SELECT jsonb_agg(to_jsonb(m.*))
                         FROM (
                           SELECT * FROM evo.evolution_messages
                           WHERE contact_id = c.id
                           ORDER BY created_at DESC
                           LIMIT 20
                         ) m
                       ), '[]'),
    'tasks',           COALESCE((
                         SELECT jsonb_agg(to_jsonb(t.*))
                         FROM evo.evolution_tasks t
                         WHERE t.contact_id = c.id
                           AND t.status IN ('pending', 'in_progress')
                       ), '[]')
  )
  INTO v_result
  FROM evo.evolution_contacts c
  WHERE c.id = p_contact_id;
  RETURN v_result;
END;
$$;


