--

CREATE FUNCTION zapp.rpc_get_conversation_media(p_remote_jid text, p_types text[] DEFAULT ARRAY['image'::text, 'video'::text, 'audio'::text, 'ptt'::text, 'document'::text, 'sticker'::text], p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, message_id text, media_type text, media_url text, media_mime_type text, media_filename text, media_size integer, caption text, from_me boolean, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  PERFORM zapp.fn_require_app_user();

  RETURN QUERY
  SELECT
    em.id,
    em.message_id::text,
    em.message_type::text,                    -- FIX: varchar→text
    zapp.fn_media_public_url(em.media_url),
    em.media_mimetype::text,
    em.media_filename::text,                  -- FIX: varchar→text
    em.media_size::integer,
    em.caption::text,
    em.from_me,
    em.created_at
  FROM evo.evolution_messages em              -- FIX: schema explícito
  WHERE em.remote_jid = p_remote_jid
    AND em.message_type = ANY(p_types)
    AND em.media_url IS NOT NULL AND em.media_url != ''
    AND em.deleted_at IS NULL
  ORDER BY em.created_at DESC
  LIMIT p_limit OFFSET p_offset;
END;
$$;


