--
-- Name: rpc_get_gmail_health_summary(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_get_gmail_health_summary(p_window_minutes integer DEFAULT 60) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
    v_total_calls INTEGER;
    v_failure_count INTEGER;
    v_current_status TEXT;
    v_last_validation TIMESTAMP WITH TIME ZONE;
BEGIN
    -- Get count of failures in the window
    SELECT COUNT(*) INTO v_failure_count
    FROM zapp.gmail_health_logs
    WHERE is_failure = true
      AND timestamp > now() - (p_window_minutes || ' minutes')::interval;

    -- Get last validation timestamp
    SELECT MAX(timestamp) INTO v_last_validation
    FROM zapp.gmail_health_logs
    WHERE operation = 'validation';

    -- Simple threshold logic
    IF v_failure_count > 10 THEN
        v_current_status := 'error';
    ELSIF v_failure_count > 0 THEN
        v_current_status := 'degraded';
    ELSE
        v_current_status := 'healthy';
    END IF;

    RETURN jsonb_build_object(
        'status', v_current_status,
        'failure_count_window', v_failure_count,
        'last_validation', v_last_validation,
        'window_minutes', p_window_minutes
    );
END;
$$;


--
-- Name: rpc_get_media_public_url(uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_get_media_public_url(p_message_uuid uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_url text; v_type text; v_mime text; v_filename text; v_size integer;
BEGIN
  PERFORM zapp.fn_require_app_user();

  SELECT zapp.fn_media_public_url(em.media_url), em.message_type::text, em.media_mimetype::text,
    em.media_filename::text, em.media_size
  INTO v_url, v_type, v_mime, v_filename, v_size
  FROM evo.evolution_messages em  -- FIX
  WHERE em.id=p_message_uuid AND em.media_url IS NOT NULL AND em.media_url != ''
  LIMIT 1;
  IF v_url IS NULL THEN
    DECLARE v_qs text;
    BEGIN
      SELECT status::text INTO v_qs FROM zapp.media_download_queue WHERE message_uuid=p_message_uuid LIMIT 1;
      IF v_qs IS NOT NULL THEN RETURN jsonb_build_object('status','downloading','queue_status',v_qs,'message','Mídia está sendo baixada');
      ELSE RETURN jsonb_build_object('status','unavailable','message','Mídia não disponível'); END IF;
    EXCEPTION WHEN undefined_table THEN RETURN jsonb_build_object('status','unavailable','message','Mídia não disponível');
    END;
  END IF;
  RETURN jsonb_build_object('status','available','url',v_url,'media_type',v_type,'mime_type',v_mime,'filename',v_filename,'file_size',v_size);
END; $$;


--
-- Name: rpc_get_media_url(text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_get_media_url(p_message_id text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_url text;
BEGIN
  PERFORM zapp.fn_require_app_user();

  SELECT zapp.fn_media_public_url(media_url) INTO v_url
  FROM evo.evolution_messages  -- FIX
  WHERE message_id=p_message_id AND media_url IS NOT NULL AND media_url != '' LIMIT 1;
  IF v_url IS NULL THEN
    SELECT zapp.fn_media_public_url(storage_url) INTO v_url
    FROM evo.evolution_media WHERE message_id=p_message_id AND storage_url IS NOT NULL AND storage_url != '' LIMIT 1;
  END IF;
  RETURN v_url;
END; $$;


