    quoted_message_id text,
    is_starred boolean DEFAULT false,
    is_important boolean DEFAULT false,
    category text,
    sentiment text,
    tags text[],
    notes text,
    follow_up_at timestamp with time zone,
    follow_up_done boolean DEFAULT false,
    payload jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    contact_id uuid,
    conversation_id uuid,
    direction character varying(10) DEFAULT 'inbound'::character varying,
    status character varying(20) DEFAULT 'delivered'::character varying,
    status_at timestamp with time zone DEFAULT now(),
    caption text,
    media_filename character varying(255),
    media_size integer,
    sent_by_bot boolean DEFAULT false,
    template_name character varying(100),
    instance_name character varying(100) NOT NULL,
    push_name text,
    media_type text,
    raw_data jsonb,
    deleted_at timestamp with time zone,
    edited_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now(),
    media_meta jsonb,
    audio_meme_id uuid,
    sticker_id uuid,
    link_preview jsonb,
    is_read boolean DEFAULT false NOT NULL,
    reply_to_id uuid,
    media_bucket text,
    media_path text,
    media_sha256 text,
    media_status text DEFAULT 'unknown'::text,
    transcription_status text,
    transcription text,
    error_code text,
    error_reason text,
    retry_attempt integer,
    retry_total integer,
    CONSTRAINT evolution_messages_direction_check CHECK (((direction IS NULL) OR ((direction)::text = ANY ((ARRAY['inbound'::character varying, 'outbound'::character varying])::text[])))),
    CONSTRAINT evolution_messages_status_check CHECK (((status IS NULL) OR ((status)::text = ANY ((ARRAY['received'::character varying, 'sent'::character varying, 'delivered'::character varying, 'read'::character varying, 'deleted'::character varying, 'pending'::character varying, 'played'::character varying, 'failed'::character varying])::text[]))))
)
PARTITION BY LIST (instance_name);

ALTER TABLE ONLY evo.evolution_messages REPLICA IDENTITY FULL;


