-- Name: rpc_get_whatsapp_mode(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_get_whatsapp_mode() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
