--
-- Name: rpc_gmail_update_sla_status(uuid, integer, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_gmail_update_sla_status(p_account_id uuid DEFAULT NULL::uuid, p_threshold_min integer DEFAULT 480, p_warning_pct integer DEFAULT 80) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_updated_breached INT; v_updated_warning INT; v_updated_ok INT;
BEGIN
  UPDATE zapp.gmail_threads SET sla_status = 'breached', updated_at = NOW()
  WHERE first_reply_at IS NULL
    AND (p_account_id IS NULL OR account_id = p_account_id)
    AND EXTRACT(EPOCH FROM (NOW() - last_message_at)) / 60 >= p_threshold_min
    AND (label_ids && ARRAY['INBOX']::text[]);
  GET DIAGNOSTICS v_updated_breached = ROW_COUNT;

  UPDATE zapp.gmail_threads SET sla_status = 'warning', updated_at = NOW()
  WHERE first_reply_at IS NULL
    AND (p_account_id IS NULL OR account_id = p_account_id)
    AND EXTRACT(EPOCH FROM (NOW() - last_message_at)) / 60 >= (p_threshold_min * p_warning_pct / 100.0)
    AND EXTRACT(EPOCH FROM (NOW() - last_message_at)) / 60 < p_threshold_min
    AND (label_ids && ARRAY['INBOX']::text[]);
  GET DIAGNOSTICS v_updated_warning = ROW_COUNT;

  UPDATE zapp.gmail_threads SET sla_status = 'ok', updated_at = NOW()
  WHERE first_reply_at IS NULL
    AND (p_account_id IS NULL OR account_id = p_account_id)
    AND EXTRACT(EPOCH FROM (NOW() - last_message_at)) / 60 < (p_threshold_min * p_warning_pct / 100.0)
    AND (label_ids && ARRAY['INBOX']::text[]);
  GET DIAGNOSTICS v_updated_ok = ROW_COUNT;

  UPDATE zapp.gmail_threads SET sla_status = 'met', updated_at = NOW()
  WHERE first_reply_at IS NOT NULL
    AND (p_account_id IS NULL OR account_id = p_account_id)
    AND EXTRACT(EPOCH FROM (first_reply_at - last_message_at)) / 60 < p_threshold_min;

  RETURN jsonb_build_object('success', true, 'breached_updated', v_updated_breached, 'warning_updated', v_updated_warning, 'ok_updated', v_updated_ok);
END;
$$;


--
-- Name: rpc_inbox_preview_batch(text[], text, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_inbox_preview_batch(p_remote_jids text[], p_instance text DEFAULT NULL::text, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$ 
BEGIN
  PERFORM zapp.fn_require_app_user();
RETURN (SELECT jsonb_build_object('previews', COALESCE(jsonb_agg(preview), '[]'::jsonb)) FROM ( SELECT DISTINCT ON (remote_jid) jsonb_build_object('remote_jid', remote_jid, 'latest', row_to_json(msg.*)) AS preview FROM ( SELECT DISTINCT ON (remote_jid) * FROM evo.evolution_messages WHERE remote_jid = ANY(p_remote_jids) AND (p_instance IS NULL OR instance_name = p_instance) AND deleted_at IS NULL ORDER BY remote_jid, created_at DESC ) msg LIMIT p_limit ) sub);
END;$$;


