--
-- Name: rpc_insert_message(text, text, text, text, boolean, text, text, text, jsonb); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_insert_message(p_remote_jid text, p_content text, p_instance text, p_message_id text DEFAULT NULL::text, p_from_me boolean DEFAULT true, p_direction text DEFAULT NULL::text, p_message_type text DEFAULT 'text'::text, p_media_url text DEFAULT NULL::text, p_metadata jsonb DEFAULT NULL::jsonb) RETURNS evo.evolution_messages
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'pg_catalog'
    AS $$ DECLARE v_contact_id uuid; v_row evo.evolution_messages; v_dir text; BEGIN IF p_instance IS NULL OR btrim(p_instance) = '' THEN RAISE EXCEPTION 'p_instance is required' USING ERRCODE = '22004'; END IF; SELECT id INTO v_contact_id FROM evo.evolution_contacts WHERE remote_jid = p_remote_jid AND instance_name = p_instance LIMIT 1; IF auth.role() <> 'service_role' THEN IF NOT (zapp.is_admin_or_supervisor() OR (v_contact_id IS NOT NULL AND zapp.is_contact_visible_to_user(v_contact_id, auth.uid()))) THEN RAISE EXCEPTION 'forbidden: contato nao visivel' USING ERRCODE = '42501'; END IF; END IF; v_dir := COALESCE(p_direction, CASE WHEN p_from_me THEN 'outbound' ELSE 'inbound' END); INSERT INTO evo.evolution_messages(message_id, remote_jid, from_me, direction, message_type, content, instance_name, contact_id, status, created_at, media_url, payload) VALUES (p_message_id, p_remote_jid, p_from_me, v_dir, p_message_type, p_content, p_instance, v_contact_id, CASE WHEN p_from_me THEN 'sent' ELSE 'received' END, now(), p_media_url, p_metadata) RETURNING * INTO v_row; UPDATE evo.evolution_contacts SET last_message_at = now(), total_messages = COALESCE(total_messages, 0) + 1 WHERE id = v_contact_id; RETURN v_row; END; $$;


--
-- Name: rpc_instance_auth_event_summary(text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_instance_auth_event_summary(p_instance text) RETURNS TABLE(event_type text, total bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT instance_auth_events.event_type, count(*) as total
    FROM zapp.instance_auth_events
    WHERE (p_instance IS NULL OR instance_name = p_instance)
    GROUP BY 1;
END;
$$;


--
-- Name: rpc_instance_auth_event_summary(integer, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_instance_auth_event_summary(p_hours integer DEFAULT 24, p_instance text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_hours integer;
  v_total bigint;
  v_invalid bigint;
  v_401 bigint;
  v_403 bigint;
  v_top jsonb;
  v_first timestamptz;
  v_last timestamptz;
BEGIN
  IF NOT zapp.is_admin_or_supervisor(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied: admin or supervisor role required';
  END IF;

  v_hours := GREATEST(1, LEAST(COALESCE(p_hours, 24), 168));

  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE reason = 'invalid_signature'),
    COUNT(*) FILTER (WHERE reason = 'auth_401'),
    COUNT(*) FILTER (WHERE reason = 'auth_403'),
    MIN(created_at),
    MAX(created_at)
  INTO v_total, v_invalid, v_401, v_403, v_first, v_last
  FROM zapp.instance_auth_events
  WHERE created_at > now() - (v_hours || ' hours')::interval
    AND (p_instance IS NULL OR instance_name = p_instance);

  SELECT COALESCE(jsonb_agg(t.*), '[]'::jsonb) INTO v_top FROM (
    SELECT
      instance_name,
      COUNT(*)::int AS total,
      COUNT(*) FILTER (WHERE reason = 'invalid_signature')::int AS invalid_signature,
      COUNT(*) FILTER (WHERE reason = 'auth_401')::int AS auth_401,
      COUNT(*) FILTER (WHERE reason = 'auth_403')::int AS auth_403
    FROM zapp.instance_auth_events
    WHERE created_at > now() - (v_hours || ' hours')::interval
      AND (p_instance IS NULL OR instance_name = p_instance)
    GROUP BY instance_name
    ORDER BY COUNT(*) DESC
    LIMIT 10
  ) t;

  RETURN jsonb_build_object(
    'window_hours', v_hours,
    'total', COALESCE(v_total, 0),
    'invalid_signature', COALESCE(v_invalid, 0),
    'auth_401', COALESCE(v_401, 0),
    'auth_403', COALESCE(v_403, 0),
    'first_event_at', v_first,
    'last_event_at', v_last,
    'top_instances', v_top
  );
END;
$$;


--
-- Name: rpc_instance_auth_event_trend(integer, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_instance_auth_event_trend(p_hours integer DEFAULT 24, p_instance text DEFAULT NULL::text) RETURNS TABLE(bucket timestamp with time zone, instance_name text, invalid_signature integer, auth_401 integer, auth_403 integer, total integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_hours integer;
  v_bucket_minutes integer;
BEGIN
  IF NOT zapp.is_admin_or_supervisor(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied: admin or supervisor role required';
  END IF;

  v_hours := GREATEST(1, LEAST(COALESCE(p_hours, 24), 168));
  v_bucket_minutes := CASE
    WHEN v_hours <= 24 THEN 10
    WHEN v_hours <= 72 THEN 30
    ELSE 60
  END;

  RETURN QUERY
  SELECT
    date_bin((v_bucket_minutes || ' minutes')::interval, e.created_at, TIMESTAMPTZ '2000-01-01') AS bucket,
    e.instance_name,
    COUNT(*) FILTER (WHERE e.reason = 'invalid_signature')::integer AS invalid_signature,
    COUNT(*) FILTER (WHERE e.reason = 'auth_401')::integer AS auth_401,
    COUNT(*) FILTER (WHERE e.reason = 'auth_403')::integer AS auth_403,
    COUNT(*)::integer AS total
  FROM zapp.instance_auth_events e
  WHERE e.created_at > now() - (v_hours || ' hours')::interval
    AND (p_instance IS NULL OR e.instance_name = p_instance)
  GROUP BY 1, 2
  ORDER BY 1 ASC, 2 ASC;
END;
$$;


--
-- Name: rpc_instance_stats(text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_instance_stats(p_instance text DEFAULT NULL::text) RETURNS TABLE(instance_name text, msgs_hoje bigint, msgs_7d bigint, convs_abertas bigint, contatos bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  PERFORM zapp.fn_require_app_user();

  RETURN QUERY
  SELECT 
    ir.instance_name::text,
    (SELECT count(*) FROM evolution_messages m WHERE m.instance_name=ir.instance_name AND m.created_at >= date_trunc('day',now()))::bigint,
    (SELECT count(*) FROM evolution_messages m WHERE m.instance_name=ir.instance_name AND m.created_at >= now()-interval '7 days')::bigint,
    (SELECT count(*) FROM evolution_conversations c WHERE c.instance_name=ir.instance_name AND c.status IN ('aberta','open','active'))::bigint,
    (SELECT count(*) FROM evolution_contacts ct WHERE ct.instance_name=ir.instance_name AND ct.deleted_at IS NULL)::bigint
  FROM instance_registry ir
  WHERE ir.is_active=true AND (p_instance IS NULL OR ir.instance_name=p_instance)
  ORDER BY ir.department;
END;
$$;


