--
-- Name: channel_queues; Type: TABLE; Schema: zapp; Owner: -
--

CREATE TABLE zapp.channel_queues (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    channel_id uuid NOT NULL,
    queue_id uuid NOT NULL,
    is_default boolean DEFAULT false,
    created_at timestamp with time zone DEFAULT now(),
    created_by uuid,
    is_active boolean DEFAULT true NOT NULL,
    priority integer DEFAULT 0 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: rpc_link_channel_queue(uuid, uuid, integer, boolean); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_link_channel_queue(p_channel_id uuid, p_queue_id uuid, p_priority integer DEFAULT 0, p_is_active boolean DEFAULT true) RETURNS zapp.channel_queues
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_row zapp.channel_queues;
BEGIN
  IF NOT is_admin_or_supervisor(auth.uid()) THEN RAISE EXCEPTION 'forbidden'; END IF;
  INSERT INTO zapp.channel_queues(channel_id, queue_id, priority, is_active, created_by)
  VALUES (p_channel_id, p_queue_id, COALESCE(p_priority,0), COALESCE(p_is_active,true), auth.uid())
  ON CONFLICT (channel_id, queue_id) DO UPDATE
    SET priority=EXCLUDED.priority, is_active=EXCLUDED.is_active, updated_at=now()
  RETURNING * INTO v_row;
  RETURN v_row;
END $$;


--
-- Name: evolution_audit_log; Type: TABLE; Schema: evo; Owner: -
--

CREATE TABLE evo.evolution_audit_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    action character varying(30) NOT NULL,
    entity_type character varying(50) NOT NULL,
    entity_id uuid,
    performed_by character varying(100) DEFAULT 'system'::character varying NOT NULL,
    performed_by_type character varying(20) DEFAULT 'system'::character varying,
    old_values jsonb,
    new_values jsonb,
    changes jsonb,
    ip_address character varying(45),
    user_agent text,
    session_id character varying(100),
    metadata jsonb,
    created_at timestamp with time zone DEFAULT now()
);


--
-- Name: rpc_list_audit_log(text, uuid, text, text, integer, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_list_audit_log(p_entity_type text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid, p_action text DEFAULT NULL::text, p_performed_by text DEFAULT NULL::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS SETOF evo.evolution_audit_log
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$ 
BEGIN
  PERFORM zapp.fn_require_app_user();
RETURN QUERY SELECT * FROM evolution_audit_log WHERE (p_entity_type IS NULL OR entity_type=p_entity_type) AND (p_entity_id IS NULL OR entity_id=p_entity_id) AND (p_action IS NULL OR action=p_action) AND (p_performed_by IS NULL OR performed_by=p_performed_by) ORDER BY created_at DESC LIMIT p_limit OFFSET p_offset; 
END;$$;


--
-- Name: evolution_broadcasts; Type: TABLE; Schema: evo; Owner: -
--

CREATE TABLE evo.evolution_broadcasts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name character varying(100) NOT NULL,
    description text,
    template_id uuid,
    content text,
    media_url text,
    segment_type character varying(30) DEFAULT 'all'::character varying,
    segment_config jsonb DEFAULT '{}'::jsonb,
    scheduled_at timestamp with time zone,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    status character varying(20) DEFAULT 'draft'::character varying,
    total_recipients integer DEFAULT 0,
    sent_count integer DEFAULT 0,
    delivered_count integer DEFAULT 0,
    read_count integer DEFAULT 0,
    failed_count integer DEFAULT 0,
    response_count integer DEFAULT 0,
    messages_per_minute integer DEFAULT 10,
    created_by character varying(100),
    instance_name character varying(100) DEFAULT 'wpp2'::character varying,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT evolution_broadcasts_status_check CHECK (((status IS NULL) OR ((status)::text = ANY (ARRAY['draft'::text, 'scheduled'::text, 'active'::text, 'paused'::text, 'completed'::text, 'cancelled'::text, 'failed'::text]))))
);


--
-- Name: rpc_list_broadcasts(text, text, integer, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_list_broadcasts(p_instance text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS SETOF evo.evolution_broadcasts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  RETURN QUERY SELECT * FROM evo.evolution_broadcasts
  WHERE (p_instance IS NULL OR instance_name = p_instance)
    AND (p_status IS NULL OR status = p_status)
  ORDER BY created_at DESC LIMIT p_limit OFFSET p_offset;
END; $$;


--
-- Name: evolution_calls; Type: TABLE; Schema: evo; Owner: -
--

CREATE TABLE evo.evolution_calls (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    call_id text NOT NULL,
    remote_jid text NOT NULL,
    contact_id uuid,
    call_type text NOT NULL,
    call_status text NOT NULL,
    direction text NOT NULL,
    duration_seconds integer,
    started_at timestamp with time zone,
    ended_at timestamp with time zone,
    missed_callback_sent boolean DEFAULT false,
    instance_name text DEFAULT 'wpp2'::text,
    raw_data jsonb,
    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT evolution_calls_call_status_check CHECK ((call_status = ANY (ARRAY['ended'::text, 'ringing'::text, 'missed'::text, 'rejected'::text, 'failed'::text, 'accepted'::text]))),
    CONSTRAINT evolution_calls_call_type_check CHECK ((call_type = ANY (ARRAY['voice'::text, 'video'::text]))),
    CONSTRAINT evolution_calls_direction_check CHECK ((direction = ANY (ARRAY['incoming'::text, 'outgoing'::text])))
)
WITH (autovacuum_vacuum_scale_factor='0.05', autovacuum_analyze_scale_factor='0.02');


--
-- Name: rpc_list_calls(text, text, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_list_calls(p_remote_jid text DEFAULT NULL::text, p_instance text DEFAULT NULL::text, p_limit integer DEFAULT 50) RETURNS SETOF evo.evolution_calls
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$

BEGIN
  PERFORM zapp.fn_require_app_user();
RETURN QUERY  SELECT * FROM evo.evolution_calls
  WHERE (p_instance IS NULL OR instance_name = p_instance)
    AND (p_remote_jid IS NULL OR remote_jid = p_remote_jid)
  ORDER BY started_at DESC NULLS LAST LIMIT p_limit;

END;$$;


--
-- Name: rpc_list_channel_queues(uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_list_channel_queues(p_channel_id uuid) RETURNS TABLE(queue_id uuid, name text, status text, priority integer, is_default boolean, is_active boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$ SELECT q.id, q.name, q.status, COALESCE(cq.priority, 0), (sc.default_queue_id = q.id), COALESCE(cq.is_active, true) FROM zapp.service_channels sc LEFT JOIN zapp.channel_queues cq ON cq.channel_id = sc.id LEFT JOIN zapp.queues q ON q.id = cq.queue_id OR q.id = sc.default_queue_id WHERE sc.id = p_channel_id AND q.id IS NOT NULL ORDER BY (sc.default_queue_id = q.id) DESC, COALESCE(cq.priority,0) DESC, q.name; $$;


--
-- Name: rpc_list_contact_links(uuid, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_list_contact_links(p_contact_id uuid, p_limit integer DEFAULT 50) RETURNS TABLE(id uuid, content text, from_me boolean, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  PERFORM zapp.fn_require_app_user();

  RETURN QUERY
  SELECT em.id, em.content::text, COALESCE(em.from_me, false), em.created_at
  FROM evo.evolution_messages em  -- FIX
  WHERE em.contact_id=p_contact_id AND em.content ~ 'https?://[^\s]+'
    AND em.deleted_at IS NULL
  ORDER BY em.created_at DESC LIMIT p_limit;
END; $$;


--
-- Name: rpc_list_contact_media(uuid, text, integer, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_list_contact_media(p_contact_id uuid, p_media_type text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, message_id text, media_type text, media_url text, media_mime_type text, media_filename text, media_size integer, caption text, from_me boolean, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  PERFORM zapp.fn_require_app_user();

  RETURN QUERY
  SELECT
    em.id,
    em.message_id::text,
    em.message_type::text,                    -- FIX: varchar→text
    zapp.fn_media_public_url(em.media_url),
    em.media_mimetype::text,
    em.media_filename::text,                  -- FIX: varchar→text
    em.media_size::integer,
    em.caption::text,
    COALESCE(em.from_me, false),
    em.created_at
  FROM evo.evolution_messages em              -- FIX: schema explícito
  WHERE em.contact_id = p_contact_id
    AND em.message_type IN ('image','video','audio','ptt','document','sticker')
    AND em.media_url IS NOT NULL AND em.media_url != ''
    AND em.deleted_at IS NULL
    AND (p_media_type IS NULL OR em.message_type::text = p_media_type)
  ORDER BY em.created_at DESC
  LIMIT p_limit OFFSET p_offset;
END;
$$;


--
-- Name: rpc_list_contacts(text, text, text, text, integer, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_list_contacts(p_instance text DEFAULT NULL::text, p_lead_status text DEFAULT NULL::text, p_assigned_to text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS SETOF evo.evolution_contacts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$

BEGIN
  PERFORM zapp.fn_require_app_user();
RETURN QUERY  SELECT *
  FROM evo.evolution_contacts
  WHERE
    deleted_at IS NULL
    AND (p_instance IS NULL OR instance_name = p_instance)
    AND (p_lead_status IS NULL OR lead_status = p_lead_status)
    AND (p_assigned_to IS NULL OR assigned_to = p_assigned_to)
    AND (
      p_search IS NULL
      OR full_name  ILIKE '%' || p_search || '%'
      OR push_name  ILIKE '%' || p_search || '%'
      OR phone_number ILIKE '%' || p_search || '%'
      OR remote_jid ILIKE '%' || p_search || '%'
    )
  ORDER BY last_message_at DESC NULLS LAST
  LIMIT  GREATEST(COALESCE(p_limit, 50), 0)   -- FIX
  OFFSET GREATEST(COALESCE(p_offset, 0), 0);

END;$$;


--
-- Name: rpc_list_conversations(text, text, text, integer, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_list_conversations(p_instance text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_assigned_to text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS SETOF evo.evolution_conversations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$

BEGIN
  PERFORM zapp.fn_require_app_user();
RETURN QUERY  SELECT *
  FROM evo.evolution_conversations
  WHERE
    (p_instance IS NULL OR instance_name = p_instance)
    AND (p_status IS NULL OR status = p_status)
    AND (p_assigned_to IS NULL OR assigned_to = p_assigned_to)
  ORDER BY last_message_at DESC NULLS LAST
  LIMIT  GREATEST(COALESCE(p_limit, 50), 0)   -- FIX: sanitizar negativo
  OFFSET GREATEST(COALESCE(p_offset, 0), 0);

END;$$;


