--

COMMENT ON FUNCTION zapp.rpc_list_cron_jobs() IS 'Admin RPC — lista todos os jobs pg_cron (somente admins/supervisores). SECURITY DEFINER.';


--
-- Name: rpc_list_deals(text, text, uuid, text, integer, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_list_deals(p_stage text DEFAULT NULL::text, p_assigned_to text DEFAULT NULL::text, p_contact_id uuid DEFAULT NULL::uuid, p_instance text DEFAULT NULL::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS SETOF evo.evolution_deals
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$

BEGIN
