--
-- Name: rpc_list_messages_lite(text, text, integer, integer, timestamp with time zone); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_list_messages_lite(p_remote_jid text, p_instance text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_before_date timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS SETOF evo.evolution_messages
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'pg_temp'
    AS $_$
DECLARE
  v_limit   int := GREATEST(COALESCE(p_limit,  50), 0);
  v_offset  int := GREATEST(COALESCE(p_offset,  0), 0);
BEGIN
  PERFORM zapp.fn_require_app_user();
  IF p_instance IS NOT NULL THEN
    RETURN QUERY EXECUTE
      'SELECT * FROM evo.evolution_messages
       WHERE remote_jid   = $1
         AND instance_name = $2
         AND deleted_at   IS NULL
         AND ($3 IS NULL OR created_at < $3)
       ORDER BY created_at DESC
       LIMIT $4 OFFSET $5'
    USING p_remote_jid, p_instance, p_before_date, v_limit, v_offset;
  ELSE
    RETURN QUERY EXECUTE
      'SELECT * FROM evo.evolution_messages
       WHERE remote_jid = $1
         AND deleted_at IS NULL
         AND ($2 IS NULL OR created_at < $2)
       ORDER BY created_at DESC
       LIMIT $3 OFFSET $4'
    USING p_remote_jid, p_before_date, v_limit, v_offset;
  END IF;
END;
$_$;


--
-- Name: FUNCTION rpc_list_messages_lite(p_remote_jid text, p_instance text, p_limit integer, p_offset integer, p_before_date timestamp with time zone); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.rpc_list_messages_lite(p_remote_jid text, p_instance text, p_limit integer, p_offset integer, p_before_date timestamp with time zone) IS 'FATOR X v6.1.0: assinatura estendida com p_offset (compat rpcCatalog front). Substitui a versao 4-args; chamadas legadas continuam casando por defaults.';


