CREATE FUNCTION zapp.rpc_list_tasks(p_assigned_to text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_contact_id uuid DEFAULT NULL::uuid, p_deal_id uuid DEFAULT NULL::uuid, p_due_from date DEFAULT NULL::date, p_due_to date DEFAULT NULL::date, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS SETOF evo.evolution_tasks
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$ SELECT * FROM evolution_tasks WHERE (p_assigned_to IS NULL OR assigned_to=p_assigned_to) AND (p_status IS NULL OR status=p_status) AND (p_contact_id IS NULL OR contact_id=p_contact_id) AND (p_deal_id IS NULL OR deal_id=p_deal_id) AND (p_due_from IS NULL OR due_date>=p_due_from) AND (p_due_to IS NULL OR due_date<=p_due_to) ORDER BY CASE priority WHEN 'urgent' THEN 1 WHEN 'high' THEN 2 WHEN 'medium' THEN 3 ELSE 4 END, due_date NULLS LAST LIMIT p_limit OFFSET p_offset; $$;


--
-- Name: rpc_list_transfers_paginated(text, integer, timestamp with time zone, timestamp with time zone, integer, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_list_transfers_paginated(p_status text DEFAULT NULL::text, p_priority integer DEFAULT NULL::integer, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, source_instance text, target_instance text, remote_jid text, contact_name text, status text, priority integer, transfer_type text, category text, reason text, from_agent_id uuid, to_agent_id uuid, sla_deadline timestamp with time zone, created_at timestamp with time zone, accepted_at timestamp with time zone, completed_at timestamp with time zone, total_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT t.id, t.source_instance, t.target_instance, t.remote_jid, t.contact_name,
         t.status, t.priority, t.transfer_type, t.category, t.reason,
         t.from_agent_id, t.to_agent_id, t.sla_deadline,
         t.created_at, t.accepted_at, t.completed_at,
         COUNT(*) OVER()::bigint AS total_count
  FROM zapp.conversation_transfers t
  WHERE (p_status IS NULL OR t.status = p_status)
    AND (p_priority IS NULL OR t.priority = p_priority)
    AND (p_from IS NULL OR t.created_at >= p_from)
    AND (p_to IS NULL OR t.created_at <= p_to)
  ORDER BY t.created_at DESC
  LIMIT COALESCE(p_limit, 50)
  OFFSET COALESCE(p_offset, 0);
$$;


