     jsonb_build_object('source', 'zapp.rpc_log_assignment_change'));
END;
$$;


--
-- Name: rpc_log_email_health(text, text, text, text, text, jsonb, boolean, uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_log_email_health(p_status text, p_operation text DEFAULT NULL::text, p_resource text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text, p_error_message text DEFAULT NULL::text, p_metadata jsonb DEFAULT NULL::jsonb, p_is_failure boolean DEFAULT NULL::boolean, p_account_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_failure_count integer := 0;
  v_is_failure boolean := COALESCE(p_is_failure, p_status IN ('error','degraded'));
  -- status para a coluna do summary respeita a CHECK; valores fora do dominio viram 'unknown'
  v_summary_status text := CASE WHEN p_status IN ('healthy','degraded','error','unknown') THEN p_status
                                WHEN p_status = 'ok' THEN 'healthy'
                                ELSE 'unknown' END;
BEGIN
  -- log bruto preserva o p_status original (a tabela de logs nao tem CHECK)
  INSERT INTO zapp.email_health_logs (account_id, status, operation, resource, request_id, error_message, metadata, is_failure)
  VALUES (p_account_id, p_status, p_operation, p_resource, p_request_id, p_error_message, p_metadata, v_is_failure);

  SELECT failure_count INTO v_failure_count FROM zapp.email_health_summary WHERE id = 'current';
  IF v_is_failure THEN
    v_failure_count := COALESCE(v_failure_count, 0) + 1;
  ELSE
    v_failure_count := 0;
  END IF;

  UPDATE zapp.email_health_summary
  SET status = v_summary_status, failure_count = v_failure_count, last_checked_at = now(), updated_at = now()
  WHERE id = 'current';

  RETURN jsonb_build_object('logged', true, 'status', p_status, 'summary_status', v_summary_status, 'failure_count', v_failure_count);
END;
$$;


--
-- Name: rpc_log_gmail_health(text, text, text, text, text, jsonb, boolean); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_log_gmail_health(p_status text, p_operation text DEFAULT NULL::text, p_resource text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text, p_error_message text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_is_failure boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
    v_id UUID;
BEGIN
    INSERT INTO zapp.gmail_health_logs (
        status, operation, resource, request_id, error_message, metadata, is_failure
    ) VALUES (
        p_status, p_operation, p_resource, p_request_id, p_error_message, p_metadata, p_is_failure
    ) RETURNING id INTO v_id;
    
    RETURN v_id;
END;
$$;


--
-- Name: rpc_log_outbound_event(uuid, uuid, text, text, text, jsonb, text, text, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_log_outbound_event(p_conversation_id uuid DEFAULT NULL::uuid, p_message_id uuid DEFAULT NULL::uuid, p_event_type text DEFAULT 'send'::text, p_status text DEFAULT 'sent'::text, p_error text DEFAULT NULL::text, p_metadata jsonb DEFAULT NULL::jsonb, p_instance_name text DEFAULT NULL::text, p_remote_jid text DEFAULT NULL::text, p_latency_ms integer DEFAULT NULL::integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$ DECLARE v_id uuid; BEGIN INSERT INTO zapp.outbound_delivery_audit (conversation_id, message_id, event_type, status, error_message, metadata, instance_name, remote_jid, latency_ms) VALUES (p_conversation_id, p_message_id, p_event_type, p_status, p_error, p_metadata, p_instance_name, p_remote_jid, p_latency_ms) RETURNING id INTO v_id; RETURN v_id; END; $$;


--
-- Name: rpc_log_provider_message(text, text, text, text, text, text, uuid, jsonb, text, uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_log_provider_message(p_idempotency_key text, p_provider text, p_instance_name text, p_external_message_id text, p_direction text, p_remote_jid text, p_external_contact_id uuid, p_payload jsonb, p_trace_id text DEFAULT NULL::text, p_thread_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_id UUID;
  v_hash TEXT;
BEGIN
  IF p_idempotency_key IS NULL OR length(p_idempotency_key) = 0 THEN
    RAISE EXCEPTION 'idempotency_key required';
  END IF;

  v_hash := encode(digest(p_payload::text, 'sha256'), 'hex');

  INSERT INTO zapp.provider_message_log (
    idempotency_key, provider, instance_name, external_message_id,
    direction, remote_jid, external_contact_id, payload, payload_hash,
    trace_id, thread_id
  )
  VALUES (
    p_idempotency_key, p_provider, p_instance_name, p_external_message_id,
    p_direction, p_remote_jid, p_external_contact_id, p_payload, v_hash,
    p_trace_id, p_thread_id
  )
  ON CONFLICT (idempotency_key) DO UPDATE
    SET metadata = provider_message_log.metadata || jsonb_build_object(
      'duplicate_attempts',
      COALESCE((provider_message_log.metadata->>'duplicate_attempts')::int, 0) + 1,
      'last_duplicate_at', now()
    )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: rpc_log_search_event(text, jsonb); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_log_search_event(p_query text, p_entities jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
BEGIN
  INSERT INTO zapp.query_telemetry
    (query_text, query_hash, source, user_id, duration_ms)
  VALUES (
    p_query,
    md5(lower(trim(p_query))),
    'global_search',
    auth.uid(),
    0
  )
  ON CONFLICT DO NOTHING;

  -- Registrar entidades pesquisadas no log de diagnóstico se fornecido
  IF p_entities IS NOT NULL AND jsonb_array_length(p_entities) > 0 THEN
    INSERT INTO zapp.dev_diagnostic_logs (action, category, details, user_id)
    VALUES (
      'search_event',
      'Search',
      jsonb_build_object(
        'query',    p_query,
        'entities', p_entities,
        'ts',       extract(epoch FROM now())
      ),
      auth.uid()
    );
  END IF;
END;
$$;


