CREATE FUNCTION zapp.rpc_log_service_event(p_instance text, p_event_type text, p_message text, p_level text DEFAULT 'info'::text, p_remote_jid text DEFAULT NULL::text, p_payload jsonb DEFAULT NULL::jsonb, p_metadata jsonb DEFAULT NULL::jsonb, p_performed_by text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$ DECLARE v_id uuid; BEGIN INSERT INTO evo.evolution_audit_log (action, entity_type, performed_by, performed_by_type, metadata, created_at) VALUES (p_event_type, 'service_event', coalesce(p_performed_by, auth.uid()::text, 'system'), 'service', jsonb_build_object('instance',p_instance,'level',coalesce(p_level,'info'),'message',p_message,'remote_jid',p_remote_jid,'payload',p_payload) || coalesce(p_metadata,'{}'::jsonb), now()) RETURNING id INTO v_id; RETURN jsonb_build_object('success',true,'audit_id',v_id); END $$;


