--
-- Name: rpc_mark_message_failed(uuid, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_mark_message_failed(p_queue_id uuid, p_error text DEFAULT 'Unknown error'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  UPDATE zapp.outbound_message_queue 
  SET 
    status = CASE WHEN retry_count < max_retries THEN 'pending' ELSE 'failed' END,
    retry_count = retry_count + 1,
    error_message = p_error
  WHERE id = p_queue_id;
END;
$$;


--
-- Name: rpc_mark_messages_as_read(uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_mark_messages_as_read(p_contact_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
BEGIN
  PERFORM zapp.fn_require_app_user();

  IF p_contact_id IS NULL THEN
    RAISE EXCEPTION 'rpc_mark_messages_as_read: p_contact_id cannot be null';
  END IF;

  UPDATE evo.evolution_messages
  SET
    is_read    = true,
    updated_at = now()
  WHERE contact_id = p_contact_id
    AND from_me    = false
    AND is_read    = false
    AND deleted_at IS NULL;
END;
$$;


--
-- Name: FUNCTION rpc_mark_messages_as_read(p_contact_id uuid); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.rpc_mark_messages_as_read(p_contact_id uuid) IS 'Marks all inbound (from_me=false) messages for a contact as read in evo.evolution_messages. SECURITY DEFINER bypasses the missing UPDATE RLS policy on the evo schema.';


--
-- Name: rpc_media_dashboard(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_media_dashboard() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $_$
DECLARE
  v_result jsonb;
BEGIN
  PERFORM zapp.fn_require_app_user();

  SELECT jsonb_build_object(
    'r2', jsonb_build_object(
      'bucket', 'zapp-whatsapp-media',
      'worker_url', 'https://zapp-media-proxy.adm01.workers.dev',
      'urls_ativas', (SELECT count(*) FROM evolution_messages WHERE media_url LIKE 'https://zapp-media-proxy%'),
      'status', 'ativo'
    ),
    'storage_legado', jsonb_build_object(
      'supabase_cloud', (SELECT count(*) FROM evolution_messages WHERE media_url LIKE 'https://allrjhk%'),
      'minio_interno', (SELECT count(*) FROM evolution_messages WHERE media_url LIKE 'http://minio%'),
      's3_atomicabr', (SELECT count(*) FROM evolution_messages WHERE media_url LIKE 'https://s3.atomicabr%')
    ),
    'pipeline', jsonb_build_object(
      'sem_url', (SELECT count(*) FROM evolution_messages WHERE (media_url IS NULL OR media_url='') AND message_type IN ('image','video','audio','ptt','document','sticker') AND deleted_at IS NULL),
      'queue_pending', (SELECT count(*) FROM media_download_queue WHERE status='pending'),
      'queue_done', (SELECT count(*) FROM media_download_queue WHERE status='done'),
      'queue_failed', (SELECT count(*) FROM media_download_queue WHERE status='failed'),
      'queue_processing', (SELECT count(*) FROM media_download_queue WHERE status='processing')
    ),
    'por_tipo', (
      SELECT jsonb_object_agg(message_type, total) FROM (
        SELECT message_type, count(*) as total
        FROM evolution_messages 
        WHERE message_type IN ('image','video','audio','ptt','document','sticker') AND deleted_at IS NULL
        GROUP BY message_type
      ) t
    ),
    'stickers', jsonb_build_object(
      'total', (SELECT count(*) FROM stickers WHERE is_active=true),
      'favoritos', (SELECT count(*) FROM stickers WHERE is_favorite=true),
      'categorias', (SELECT count(DISTINCT category) FROM stickers WHERE category IS NOT NULL)
    ),
    'custo_estimado_r2', jsonb_build_object(
      'descricao', 'US$ 0.015 por GB/mes, egress gratis',
      'nota', 'Volume atual < 10 GB = dentro do free tier'
    ),
    'timestamp', now()
  ) INTO v_result;
  
  RETURN v_result;
END;
$_$;


