--
-- Name: rpc_media_download_stats(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_media_download_stats() RETURNS TABLE(status text, media_type text, total bigint, avg_retries numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  RETURN QUERY
  SELECT mdq.status, mdq.media_type, count(*), round(avg(mdq.retry_count), 1)
  FROM media_download_queue mdq
  GROUP BY mdq.status, mdq.media_type
  ORDER BY mdq.status, count(*) DESC;
END;
$$;


--
-- Name: rpc_message_stats(text, integer, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_message_stats(p_instance text DEFAULT 'wpp_pink_test'::text, p_days_back integer DEFAULT 7, p_assigned_to text DEFAULT NULL::text) RETURNS TABLE(dia date, total bigint, inbound bigint, outbound bigint, bot bigint, unique_contacts bigint, msgs_per_contact numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$

BEGIN
  PERFORM zapp.fn_require_app_user();
RETURN QUERY  SELECT
    date_trunc('day', m.created_at)::date AS dia,
    COUNT(*), COUNT(*) FILTER (WHERE m.direction='inbound'),
    COUNT(*) FILTER (WHERE m.direction='outbound'),
    COUNT(*) FILTER (WHERE m.sent_by_bot=true),
    COUNT(DISTINCT m.remote_jid),
    ROUND(COUNT(*)::numeric / NULLIF(COUNT(DISTINCT m.remote_jid),0), 2)
  FROM evo.evolution_messages m
  WHERE (p_instance IS NULL OR m.instance_name=p_instance)
    AND m.created_at >= (now() - (p_days_back||' days')::INTERVAL)
    AND m.deleted_at IS NULL
  GROUP BY date_trunc('day', m.created_at)
  ORDER BY dia DESC;

END;$$;


--
-- Name: rpc_migrate_whatsapp_integration(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_migrate_whatsapp_integration() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_evo_count INT := 0;
  v_evo_open  INT := 0;
  v_evo_default RECORD;
  v_cloud_phone TEXT;
  v_cloud_waba  TEXT;
  v_current_mode TEXT;
  v_chosen_provider TEXT;
  v_status TEXT;
  v_notes TEXT;
  v_signals JSONB;
  v_profile_id UUID;
  v_default_instance TEXT;
BEGIN
  IF NOT zapp.is_admin_or_supervisor() THEN
    RAISE EXCEPTION 'forbidden: admin required' USING ERRCODE = '42501';
  END IF;
  -- Sinais Evolution: instâncias registradas localmente
  SELECT COUNT(*) INTO v_evo_count FROM zapp.whatsapp_connections;
  SELECT COUNT(*) INTO v_evo_open
    FROM zapp.whatsapp_connections
    WHERE COALESCE(status,'') IN ('open','connected');
  SELECT instance_id, name, phone_number, status
    INTO v_evo_default
    FROM zapp.whatsapp_connections
    WHERE is_default = true
    ORDER BY updated_at DESC NULLS LAST
    LIMIT 1;

  -- Sinais Cloud: settings já preenchidos
  SELECT value INTO v_cloud_phone FROM zapp.global_settings WHERE key = 'whatsapp_cloud_display_phone';
  SELECT value INTO v_cloud_waba  FROM zapp.global_settings WHERE key = 'whatsapp_cloud_waba_name';

  SELECT value INTO v_current_mode FROM zapp.global_settings WHERE key = 'whatsapp_mode';

  v_signals := jsonb_build_object(
    'evolution_instances_total', v_evo_count,
    'evolution_instances_open',  v_evo_open,
    'evolution_default_instance', COALESCE(v_evo_default.instance_id, NULL),
    'cloud_display_phone_set',   COALESCE(NULLIF(v_cloud_phone,''), NULL) IS NOT NULL,
    'cloud_waba_name_set',       COALESCE(NULLIF(v_cloud_waba,''),  NULL) IS NOT NULL,
    'previous_mode',             COALESCE(v_current_mode, 'unset')
  );

  IF v_evo_open > 0 OR v_evo_count > 0 THEN
    v_chosen_provider := 'evolution';
  ELSIF COALESCE(NULLIF(v_cloud_phone,''),'') <> '' THEN
    v_chosen_provider := 'cloud';
  ELSE
    v_chosen_provider := CASE WHEN v_current_mode = 'official' THEN 'cloud' ELSE 'evolution' END;
  END IF;

  v_default_instance := COALESCE(v_evo_default.instance_id, 'wpp2');

  INSERT INTO zapp.global_settings(key, value)
  VALUES ('whatsapp_mode', CASE WHEN v_chosen_provider = 'cloud' THEN 'official' ELSE 'unofficial' END)
  ON CONFLICT (key) DO UPDATE
    SET value = EXCLUDED.value,
        updated_at = now()
    WHERE zapp.global_settings.value IS DISTINCT FROM EXCLUDED.value;

  IF v_chosen_provider = 'cloud' AND COALESCE(NULLIF(v_cloud_phone,''),'') = '' THEN
    v_status := 'pending_credentials';
    v_notes  := 'Modo oficial selecionado, mas faltam credenciais Meta (phone/WABA).';
  ELSIF v_chosen_provider = 'evolution' AND v_evo_count = 0 THEN
    v_status := 'pending_credentials';
    v_notes  := 'Modo Evolution selecionado, mas nenhuma instância registrada.';
  ELSE
    v_status := 'migrated';
    v_notes  := format('Provider %s ativado a partir dos sinais existentes.', v_chosen_provider);
  END IF;

  UPDATE zapp.integration_profiles SET is_active = false WHERE is_active = true;

  SELECT id INTO v_profile_id
    FROM zapp.integration_profiles
    WHERE provider = v_chosen_provider
    ORDER BY updated_at DESC LIMIT 1;

  IF v_profile_id IS NULL THEN
    INSERT INTO zapp.integration_profiles
      (provider, is_active, default_instance, display_phone, waba_name,
       detected_signals, migration_status, migration_notes, migrated_at)
    VALUES
      (v_chosen_provider, true,
       CASE WHEN v_chosen_provider='evolution' THEN v_default_instance ELSE NULL END,
       NULLIF(v_cloud_phone,''), NULLIF(v_cloud_waba,''),
       v_signals, v_status, v_notes,
       CASE WHEN v_status = 'migrated' THEN now() ELSE NULL END)
    RETURNING id INTO v_profile_id;
  ELSE
    UPDATE zapp.integration_profiles
       SET is_active = true,
           default_instance = CASE WHEN v_chosen_provider='evolution' THEN v_default_instance ELSE default_instance END,
           display_phone = COALESCE(NULLIF(v_cloud_phone,''), display_phone),
           waba_name     = COALESCE(NULLIF(v_cloud_waba,''),  waba_name),
           detected_signals = v_signals,
           migration_status = v_status,
           migration_notes  = v_notes,
           migrated_at = CASE WHEN v_status = 'migrated' THEN now() ELSE migrated_at END
     WHERE id = v_profile_id;
  END IF;

  RETURN jsonb_build_object(
    'profile_id', v_profile_id,
    'provider',   v_chosen_provider,
    'mode',       CASE WHEN v_chosen_provider='cloud' THEN 'official' ELSE 'unofficial' END,
    'status',     v_status,
    'notes',      v_notes,
    'signals',    v_signals
  );
END;
$$;


--
-- Name: rpc_move_deal(uuid, character varying, character varying); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_move_deal(p_deal_id uuid, p_new_stage character varying, p_user character varying DEFAULT 'system'::character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$ DECLARE v_old_stage VARCHAR; v_result JSONB; BEGIN
  PERFORM zapp.fn_require_app_user();
 SELECT stage INTO v_old_stage FROM evolution_deals WHERE id=p_deal_id; UPDATE evolution_deals SET stage=p_new_stage, stage_changed_at=NOW(), actual_close_date=CASE WHEN p_new_stage IN ('pago','pedido_finalizado','perdido') THEN CURRENT_DATE ELSE actual_close_date END WHERE id=p_deal_id; SELECT jsonb_build_object('success',TRUE,'deal_id',p_deal_id,'old_stage',v_old_stage,'new_stage',p_new_stage,'moved_at',NOW()) INTO v_result; RETURN v_result; END; $$;


--
-- Name: rpc_ops_metrics(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_ops_metrics(p_window_hours integer DEFAULT 24) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_since timestamptz := now() - make_interval(hours => GREATEST(p_window_hours, 1));
  v_result jsonb;
BEGIN
  -- Bloqueia agentes
  IF NOT (zapp.is_admin_or_supervisor(auth.uid())) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  WITH
  pml AS (
    SELECT * FROM zapp.provider_message_log WHERE received_at >= v_since
  ),
  by_channel AS (
    SELECT
      sc.id AS channel_id,
      sc.name AS channel_name,
      sc.channel_type,
      sc.status,
      COUNT(*) FILTER (WHERE p.direction = 'inbound') AS msgs_in,
      COUNT(*) FILTER (WHERE p.direction = 'outbound') AS msgs_out,
      COUNT(*) FILTER (WHERE p.delivery_status IN ('failed','error')) AS msgs_failed
    FROM zapp.service_channels sc
    LEFT JOIN pml p ON p.instance_name = sc.instance_name
    GROUP BY sc.id, sc.name, sc.channel_type, sc.status
  ),
  by_queue AS (
    SELECT
      q.id AS queue_id,
      q.name AS queue_name,
      q.status AS queue_status,
      COUNT(c.id) FILTER (WHERE c.assigned_to IS NULL) AS waiting,
      COUNT(c.id) FILTER (WHERE c.assigned_to IS NOT NULL) AS in_service,
      AVG(EXTRACT(EPOCH FROM (now() - c.created_at)))
        FILTER (WHERE c.assigned_to IS NULL) AS avg_wait_seconds,
      PERCENTILE_DISC(0.99) WITHIN GROUP (ORDER BY EXTRACT(EPOCH FROM (now() - c.created_at)))
        FILTER (WHERE c.assigned_to IS NULL) AS p99_wait_seconds
    FROM zapp.queues q
    LEFT JOIN zapp.contacts c ON c.queue_id = q.id
    GROUP BY q.id, q.name, q.status
  ),
  totals AS (
    SELECT
      (SELECT COUNT(*) FROM pml WHERE direction='inbound') AS total_in,
      (SELECT COUNT(*) FROM pml WHERE direction='outbound') AS total_out,
      (SELECT COUNT(*) FROM pml WHERE delivery_status IN ('failed','error')) AS total_failed,
      (SELECT COUNT(*) FROM zapp.service_channels WHERE status='active') AS active_channels,
      (SELECT COUNT(*) FROM zapp.queues WHERE status='active') AS active_queues,
      (SELECT COUNT(DISTINCT user_id) FROM zapp.profiles WHERE status='online') AS online_agents
  )
  SELECT jsonb_build_object(
    'window_hours', p_window_hours,
    'generated_at', now(),
    'totals', (SELECT to_jsonb(t) FROM totals t),
    'by_channel', COALESCE((SELECT jsonb_agg(to_jsonb(c) ORDER BY c.msgs_in DESC) FROM by_channel c), '[]'::jsonb),
    'by_queue', COALESCE((SELECT jsonb_agg(to_jsonb(q) ORDER BY q.waiting DESC) FROM by_queue q), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: queues; Type: TABLE; Schema: zapp; Owner: -
--

CREATE TABLE zapp.queues (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    description text,
    color text DEFAULT '#3B82F6'::text,
    icon text DEFAULT 'inbox'::text,
    is_active boolean DEFAULT true,
    max_capacity integer,
    auto_assign boolean DEFAULT true,
    round_robin boolean DEFAULT true,
    priority integer DEFAULT 0,
    sla_policy_id uuid,
    business_hours jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    auto_rebalance_enabled boolean DEFAULT true NOT NULL,
    department_id uuid,
    distribution_algorithm text DEFAULT 'least_busy'::text NOT NULL,
    last_assigned_at timestamp with time zone,
    last_assigned_user_id uuid,
    max_concurrent_per_agent integer,
    max_per_queue_per_agent integer,
    max_queue_size integer,
    max_wait_seconds integer,
    max_wait_time_minutes integer DEFAULT 30,
    overflow_queue_id uuid,
    paused_at timestamp with time zone,
    paused_by uuid,
    paused_reason text,
    routing_weight integer DEFAULT 1 NOT NULL,
    sla_priority text DEFAULT 'medium'::text NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    CONSTRAINT queues_status_check CHECK ((status = ANY (ARRAY['active'::text, 'paused'::text, 'archived'::text, 'inactive'::text])))
);


--
-- Name: TABLE queues; Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON TABLE zapp.queues IS 'Tabela de filas de atendimento. RLS ativo.
Policies após FIX GAP-RLS (2026-08-06):
  authenticated_read_queues — SELECT authenticated, USING true [mantida]
  q_select, queues_select   — REMOVIDAS (duplicatas idênticas)
  queues_admin_write        — ALL authenticated, USING is_admin_or_supervisor()
  q_service                 — ALL service_role, USING true';


--
-- Name: rpc_pause_queue(uuid, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_pause_queue(p_queue_id uuid, p_reason text DEFAULT NULL::text) RETURNS zapp.queues
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_row zapp.queues;
BEGIN
  IF NOT is_admin_or_supervisor(auth.uid()) THEN RAISE EXCEPTION 'forbidden'; END IF;
  UPDATE zapp.queues
     SET status='paused', paused_at=now(), paused_by=auth.uid(), paused_reason=p_reason, is_active=false
   WHERE id=p_queue_id RETURNING * INTO v_row;
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'queue not found'; END IF;
  RETURN v_row;
END $$;


--
-- Name: rpc_pause_service_channel(uuid, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_pause_service_channel(p_id uuid, p_reason text DEFAULT NULL::text) RETURNS zapp.service_channels
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_row zapp.service_channels;
BEGIN
  IF NOT zapp.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Access denied: admin role required';
  END IF;

  UPDATE zapp.service_channels SET
    status = 'paused',
    paused_at = now(),
    paused_reason = NULLIF(trim(COALESCE(p_reason,'')), '')
  WHERE id = p_id
  RETURNING * INTO v_row;

  IF v_row.id IS NULL THEN RAISE EXCEPTION 'channel not found'; END IF;

  INSERT INTO zapp.audit_logs (user_id, action, entity_type, entity_id, details)
  VALUES (auth.uid(), 'service_channel_paused', 'service_channels', p_id::text,
          jsonb_build_object('reason', p_reason));

  RETURN v_row;
END;
$$;


--
-- Name: rpc_pick_next_agent(uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_pick_next_agent(p_queue_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_algo text;
  v_last uuid;
  v_pick uuid;
BEGIN
  SELECT distribution_algorithm, last_assigned_user_id
    INTO v_algo, v_last
    FROM zapp.queues
   WHERE id = p_queue_id AND status = 'active';

  IF v_algo IS NULL OR v_algo = 'manual_pull' THEN
    RETURN NULL;
  END IF;

  IF v_algo = 'round_robin' THEN
    -- Próximo elegível depois do último atribuído (ordem determinística por user_id),
    -- com fallback para o primeiro elegível se já passou do fim da lista.
    WITH cand AS (
      SELECT user_id, active_chats, max_chats
        FROM zapp.rpc_list_eligible_agents(p_queue_id)
       WHERE active_chats < max_chats
       ORDER BY user_id
    )
    SELECT user_id INTO v_pick FROM cand
     WHERE v_last IS NULL OR user_id > v_last
     ORDER BY user_id
     LIMIT 1;

    IF v_pick IS NULL THEN
      SELECT user_id INTO v_pick FROM (
        SELECT user_id, active_chats, max_chats
          FROM zapp.rpc_list_eligible_agents(p_queue_id)
         WHERE active_chats < max_chats
         ORDER BY user_id
         LIMIT 1
      ) s;
    END IF;
  ELSIF v_algo = 'longest_idle' THEN
    SELECT a.user_id INTO v_pick
      FROM zapp.rpc_list_eligible_agents(p_queue_id) a
      LEFT JOIN zapp.profiles p ON p.user_id = a.user_id
     WHERE a.active_chats < a.max_chats
     ORDER BY p.last_active_at NULLS FIRST, a.active_chats ASC, random()
     LIMIT 1;
  ELSE
    -- least_busy (default)
    SELECT user_id INTO v_pick
      FROM zapp.rpc_list_eligible_agents(p_queue_id)
     WHERE active_chats < max_chats
     ORDER BY active_chats ASC, random()
     LIMIT 1;
  END IF;

  IF v_pick IS NOT NULL THEN
    UPDATE zapp.queues
       SET last_assigned_user_id = v_pick,
           last_assigned_at = now()
     WHERE id = p_queue_id;
  END IF;

  RETURN v_pick;
END
$$;


--
-- Name: rpc_pipeline_dashboard(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_pipeline_dashboard() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'pg_temp'
    AS $$
DECLARE
  v_wh_health       record;
  v_pending_count   bigint;
  v_failed_count    bigint;
  v_hours_silent    numeric;
  v_health_status   text;
  v_result          jsonb;
BEGIN
  SELECT
  CASE WHEN count(*) FILTER (WHERE created_at >= now() - interval '1 hour') > 0 THEN 'healthy'
       WHEN count(*) FILTER (WHERE created_at >= now() - interval '24 hours') > 0 THEN 'degraded'
       ELSE 'critical' END AS health_status,
  max(created_at) AS last_event_at,
  count(*) FILTER (WHERE NOT processed) AS unresponded,
  count(*) FILTER (WHERE created_at >= now() - interval '1 hour') AS events_1h,
  count(*) FILTER (WHERE created_at >= now() - interval '24 hours') AS events_24h,
  count(*) FILTER (WHERE processed_at >= now() - interval '1 hour') AS processed_1h
INTO v_wh_health
FROM evo.evolution_webhook_events_v2;

  SELECT count(*) INTO v_pending_count
  FROM evo.evolution_webhook_events_v2 WHERE status = 'pending';

  SELECT count(*) INTO v_failed_count
  FROM evo.evolution_webhook_events_v2 WHERE status = 'failed';

  v_hours_silent := CASE
    WHEN v_wh_health.last_event_at IS NOT NULL
    THEN ROUND(EXTRACT(EPOCH FROM (now() - v_wh_health.last_event_at))/3600, 1)
    ELSE 9999
  END;

  v_health_status := CASE
    WHEN v_wh_health.events_1h > 0 THEN 'healthy'
    WHEN v_wh_health.events_24h > 0 THEN 'degraded'
    WHEN v_hours_silent > 24        THEN 'critical'
    ELSE 'unknown'
  END;

  v_result := jsonb_build_object(
    'health_status',       v_health_status,
    'last_event_at',       v_wh_health.last_event_at,
    'events_last_hour',    COALESCE(v_wh_health.events_1h, 0),
    'events_last_24h',     COALESCE(v_wh_health.events_24h, 0),
    'processed_last_hour', COALESCE(v_wh_health.processed_1h, 0),
    'pending_webhooks',    COALESCE(v_pending_count, 0),
    'failed_webhooks',     COALESCE(v_failed_count, 0),
    'hours_silent',        v_hours_silent,
    'source_table',        'evolution_webhook_events_v2',
    'snapshot_at',         now()
  );

  RETURN v_result;
END;
$$;


--
-- Name: rpc_platform_maintenance(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_platform_maintenance() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
DECLARE
  v_alerts_cleaned INT := 0; v_dlq_cleaned INT := 0; v_logs_cleaned INT := 0;
BEGIN
  UPDATE zapp.evolution_alerts
  SET acknowledged = true, acknowledged_at = NOW(), acknowledged_by = 'auto_maintenance'
  WHERE acknowledged = false
    AND created_at < NOW() - INTERVAL '48 hours'
    AND (severity != 'critical' OR alert_type IN ('connection_lost','connection_restored','daily_briefing'));
  GET DIAGNOSTICS v_alerts_cleaned = ROW_COUNT;

  DELETE FROM zapp.evolution_webhook_dlq
  WHERE status IN ('processed', 'discarded') AND created_at < NOW() - INTERVAL '7 days';
  GET DIAGNOSTICS v_dlq_cleaned = ROW_COUNT;

  DELETE FROM zapp.evolution_webhook_events
  WHERE created_at < NOW() - INTERVAL '30 days';
  GET DIAGNOSTICS v_logs_cleaned = ROW_COUNT;

  REFRESH MATERIALIZED VIEW CONCURRENTLY zapp.mv_conversations_summary;
  REFRESH MATERIALIZED VIEW CONCURRENTLY evo.mv_daily_kpis;
  REFRESH MATERIALIZED VIEW CONCURRENTLY zapp.mv_system_status;
  REFRESH MATERIALIZED VIEW CONCURRENTLY zapp.mv_executive_dashboard;

  RETURN jsonb_build_object(
    'success', true,
    'alerts_cleaned', v_alerts_cleaned,
    'dlq_cleaned', v_dlq_cleaned,
    'logs_cleaned', v_logs_cleaned,
    'mat_views_refreshed', 4,
    'timestamp', NOW()
  );
END;
$$;


--
-- Name: rpc_provider_panel(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_provider_panel() RETURNS TABLE(provider_id uuid, name text, provider_type zapp.provider_type, base_url text, is_active boolean, priority integer, status text, last_ping_at timestamp with time zone, last_ping_latency_ms integer, last_error text, open_sessions bigint, events_24h bigint, errors_24h bigint, routes_primary bigint, routes_fallback bigint, routes_active bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  IF NOT zapp.is_admin_or_supervisor(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied: admin or supervisor role required';
  END IF;

  RETURN QUERY
  SELECT
    p.id, p.name, p.provider_type, p.base_url, p.is_active, p.priority,
    p.status, p.last_ping_at, p.last_ping_latency_ms, p.last_error,
    COALESCE((SELECT COUNT(*) FROM provider_sessions s
              WHERE s.provider_id = p.id AND s.ended_at IS NULL), 0),
    COALESCE((SELECT COUNT(*) FROM provider_session_logs l
              WHERE l.provider_id = p.id AND l.created_at > now() - interval '24 hours'), 0),
    COALESCE((SELECT COUNT(*) FROM provider_session_logs l
              WHERE l.provider_id = p.id AND l.level = 'error'
                AND l.created_at > now() - interval '24 hours'), 0),
    COALESCE((SELECT COUNT(*) FROM channel_provider_routes r WHERE r.primary_provider_id = p.id), 0),
    COALESCE((SELECT COUNT(*) FROM channel_provider_routes r WHERE r.fallback_provider_id = p.id), 0),
    COALESCE((SELECT COUNT(*) FROM channel_provider_routes r WHERE r.current_provider_id = p.id), 0)
  FROM provider_configs p
  ORDER BY p.priority ASC, p.name ASC;
END;
$$;


--
-- Name: rpc_provider_session_timeline(uuid, uuid, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_provider_session_timeline(p_provider_id uuid DEFAULT NULL::uuid, p_session_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100) RETURNS TABLE(log_id uuid, session_id uuid, provider_id uuid, provider_name text, level text, event text, message text, latency_ms integer, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  IF NOT zapp.is_admin_or_supervisor(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied: admin or supervisor role required';
  END IF;

  RETURN QUERY
  SELECT l.id, l.session_id, l.provider_id, p.name,
         l.level, l.event, l.message, l.latency_ms, l.created_at
  FROM provider_session_logs l
  JOIN provider_configs p ON p.id = l.provider_id
  WHERE (p_provider_id IS NULL OR l.provider_id = p_provider_id)
    AND (p_session_id IS NULL OR l.session_id = p_session_id)
  ORDER BY l.created_at DESC
  LIMIT GREATEST(1, LEAST(p_limit, 500));
END;
$$;


--
-- Name: rpc_publish_outbox(text, uuid, text, jsonb, text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_publish_outbox(p_aggregate_type text, p_aggregate_id uuid, p_event_type text, p_payload jsonb, p_idempotency_key text DEFAULT NULL::text, p_trace_id text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_key TEXT;
  v_id UUID;
BEGIN
  v_key := COALESCE(
    p_idempotency_key,
    encode(digest(
      p_aggregate_type || ':' || p_aggregate_id::text || ':' || p_event_type || ':' ||
      encode(digest(p_payload::text, 'sha256'), 'hex'),
      'sha256'
    ), 'hex')
  );

  INSERT INTO zapp.outbox_events (
    aggregate_type, aggregate_id, event_type, payload, idempotency_key, trace_id
  )
  VALUES (p_aggregate_type, p_aggregate_id, p_event_type, p_payload, v_key, p_trace_id)
  ON CONFLICT (idempotency_key) DO NOTHING
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: rpc_purge_channel_sticky(uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_purge_channel_sticky(p_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_wpp_id UUID;
  v_count INTEGER := 0;
BEGIN
  IF NOT zapp.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Access denied: admin role required';
  END IF;

  SELECT whatsapp_connection_id INTO v_wpp_id
    FROM zapp.service_channels WHERE id = p_id;

  IF v_wpp_id IS NULL THEN
    RETURN 0;
  END IF;

  DELETE FROM zapp.sticky_assignments
   WHERE channel_connection_id = v_wpp_id;

  GET DIAGNOSTICS v_count = ROW_COUNT;

  INSERT INTO zapp.audit_logs (user_id, action, entity_type, entity_id, details)
  VALUES (auth.uid(), 'service_channel_sticky_purged', 'service_channels', p_id::text,
          jsonb_build_object('purged_count', v_count));

  RETURN v_count;
END;
$$;


