--
-- Name: rpc_queue_rebalance_candidates(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_queue_rebalance_candidates(p_limit integer DEFAULT 50) RETURNS TABLE(contact_id uuid, queue_id uuid, reason text, waiting_minutes numeric, sla_priority text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  IF NOT zapp.is_admin_or_supervisor(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied: admin or supervisor role required';
  END IF;

  RETURN QUERY
  SELECT
    c.id,
    c.queue_id,
    CASE
      WHEN c.assigned_to IS NULL THEN 'unassigned'
      ELSE 'sla_breached'
    END AS reason,
    EXTRACT(EPOCH FROM (now() - c.created_at))/60::numeric AS waiting_minutes,
    q.sla_priority
  FROM zapp.contacts c
  JOIN zapp.queues q ON q.id = c.queue_id
  WHERE q.is_active = true
    AND q.auto_rebalance_enabled = true
    AND (
      c.assigned_to IS NULL
      OR EXTRACT(EPOCH FROM (now() - c.created_at))/60 > q.max_wait_time_minutes
    )
  ORDER BY
    CASE q.sla_priority WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END,
    q.routing_weight DESC,
    c.created_at ASC
  LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 50), 200));
END;
$$;


--
-- Name: rpc_queue_sla_panel(text, text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_queue_sla_panel(p_skill_name text DEFAULT NULL::text, p_channel_type text DEFAULT NULL::text, p_sla_status text DEFAULT NULL::text) RETURNS TABLE(queue_id uuid, queue_name text, color text, sla_priority text, routing_weight integer, auto_rebalance_enabled boolean, max_wait_time_minutes integer, active_agents bigint, waiting_count bigint, in_progress_count bigint, breached_count bigint, at_risk_count bigint, oldest_wait_minutes numeric, last_routed_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  IF NOT zapp.is_admin_or_supervisor(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied: admin or supervisor role required' USING ERRCODE = '42501';
  END IF;

  -- v2 (2026-07-02): CTEs de espera/SLA repontadas de zapp.contacts.queue_id
  -- (que é NULL::uuid hardcoded na view => métricas eternamente 0, bug provado)
  -- para as fontes reais: zapp.queue_positions (fila de espera: entered_at) e
  -- zapp.sticky_assignments ativos (proxy de em-atendimento por fila).
  RETURN QUERY
  WITH q AS (
    SELECT q.* FROM zapp.queues q
    WHERE q.is_active = true
      AND (p_skill_name IS NULL OR EXISTS (
        SELECT 1 FROM zapp.queue_skill_requirements qsr
        WHERE qsr.queue_id = q.id AND qsr.skill_name = p_skill_name))
      AND (p_channel_type IS NULL OR EXISTS (
        SELECT 1 FROM zapp.whatsapp_connection_queues wcq
        JOIN zapp.channel_connections cc ON cc.whatsapp_connection_id = wcq.whatsapp_connection_id
        WHERE wcq.queue_id = q.id AND cc.channel_type = p_channel_type))
  ),
  agents AS (
    SELECT qm.queue_id, COUNT(*) FILTER (WHERE qm.is_active AND p.is_active) AS active_agents
    FROM zapp.queue_members qm
    JOIN zapp.profiles p ON p.id = qm.profile_id
    GROUP BY qm.queue_id
  ),
  positions_agg AS (
    SELECT qp.queue_id,
           COUNT(*) AS waiting_count,
           MAX(EXTRACT(EPOCH FROM (now() - qp.entered_at))/60) AS oldest_wait_minutes
    FROM zapp.queue_positions qp
    GROUP BY qp.queue_id
  ),
  in_prog AS (
    SELECT sa.queue_id, COUNT(*) AS in_progress_count
    FROM zapp.sticky_assignments sa
    WHERE sa.expires_at IS NULL OR sa.expires_at > now()
    GROUP BY sa.queue_id
  ),
  sla_agg AS (
    SELECT qp.queue_id,
           COUNT(*) FILTER (WHERE EXTRACT(EPOCH FROM (now() - qp.entered_at))/60 > qq.max_wait_time_minutes) AS breached_count,
           COUNT(*) FILTER (WHERE EXTRACT(EPOCH FROM (now() - qp.entered_at))/60 BETWEEN qq.max_wait_time_minutes * 0.75 AND qq.max_wait_time_minutes) AS at_risk_count
    FROM zapp.queue_positions qp
    JOIN zapp.queues qq ON qq.id = qp.queue_id
    GROUP BY qp.queue_id
  ),
  routing AS (
    SELECT sa.queue_id, MAX(sa.last_assigned_at) AS last_routed_at
    FROM zapp.sticky_assignments sa GROUP BY sa.queue_id
  )
  SELECT q.id, q.name, q.color, q.sla_priority, q.routing_weight, q.auto_rebalance_enabled, q.max_wait_time_minutes,
    COALESCE(a.active_agents, 0), COALESCE(pa.waiting_count, 0), COALESCE(ip.in_progress_count, 0),
    COALESCE(s.breached_count, 0), COALESCE(s.at_risk_count, 0), COALESCE(pa.oldest_wait_minutes, 0)::numeric, r.last_routed_at
  FROM q
  LEFT JOIN agents a ON a.queue_id = q.id
  LEFT JOIN positions_agg pa ON pa.queue_id = q.id
  LEFT JOIN in_prog ip ON ip.queue_id = q.id
  LEFT JOIN sla_agg s ON s.queue_id = q.id
  LEFT JOIN routing r ON r.queue_id = q.id
  WHERE p_sla_status IS NULL
    OR (p_sla_status = 'on_track' AND COALESCE(s.breached_count,0) = 0 AND COALESCE(s.at_risk_count,0) = 0)
    OR (p_sla_status = 'at_risk'  AND COALESCE(s.at_risk_count,0) > 0)
    OR (p_sla_status = 'breached' AND COALESCE(s.breached_count,0) > 0)
  ORDER BY CASE q.sla_priority WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END,
    q.routing_weight DESC, COALESCE(s.breached_count,0) DESC;
END;
$$;


--
-- Name: FUNCTION rpc_queue_sla_panel(p_skill_name text, p_channel_type text, p_sla_status text); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.rpc_queue_sla_panel(p_skill_name text, p_channel_type text, p_sla_status text) IS 'v2 2026-07-02: espera/SLA lidos de zapp.queue_positions (entered_at) e in_progress de zapp.sticky_assignments ativos. Antes agregava public.contacts.queue_id, que é NULL::uuid hardcoded na view (painel eternamente zerado). Validado com teste funcional matematico + matriz 6 roles.';


--
-- Name: rpc_reactivate_service_channel(uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_reactivate_service_channel(p_id uuid) RETURNS zapp.service_channels
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_row zapp.service_channels;
BEGIN
  IF NOT zapp.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Access denied: admin role required';
  END IF;

  UPDATE zapp.service_channels SET
    status = 'active',
    paused_at = NULL,
    paused_reason = NULL,
    disabled_at = NULL,
    disabled_reason = NULL
  WHERE id = p_id
  RETURNING * INTO v_row;

  IF v_row.id IS NULL THEN RAISE EXCEPTION 'channel not found'; END IF;

  INSERT INTO zapp.audit_logs (user_id, action, entity_type, entity_id, details)
  VALUES (auth.uid(), 'service_channel_reactivated', 'service_channels', p_id::text, '{}'::jsonb);

  RETURN v_row;
END;
$$;


