--
-- Name: rpc_register_automation_execution(uuid, text, text, uuid, jsonb); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_register_automation_execution(p_rule_id uuid, p_remote_jid text, p_instance_name text, p_assigned_to uuid, p_trigger_payload jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_cooldown INTEGER;
  v_recent_count INTEGER;
  v_id UUID;
BEGIN
  SELECT cooldown_seconds INTO v_cooldown
  FROM zapp.automation_rules WHERE id = p_rule_id AND is_active = true;
  IF v_cooldown IS NULL THEN RETURN NULL; END IF;

  SELECT COUNT(*) INTO v_recent_count
  FROM zapp.automation_executions
  WHERE rule_id = p_rule_id
    AND remote_jid = p_remote_jid
    AND created_at > now() - make_interval(secs => v_cooldown);

  IF v_recent_count > 0 THEN RETURN NULL; END IF;

  INSERT INTO zapp.automation_executions (
    rule_id, remote_jid, instance_name, assigned_to, trigger_payload, status
  ) VALUES (
    p_rule_id, p_remote_jid, p_instance_name, p_assigned_to, p_trigger_payload, 'pending'
  ) RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: rpc_register_automation_execution(uuid, text, text, text, jsonb, uuid, uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_register_automation_execution(p_rule_id uuid, p_remote_jid text, p_instance_name text, p_assigned_to text DEFAULT NULL::text, p_trigger_payload jsonb DEFAULT '{}'::jsonb, p_channel_id uuid DEFAULT NULL::uuid, p_department_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_cooldown INT;
  v_last TIMESTAMPTZ;
  v_id UUID;
  v_channel UUID;
  v_department UUID;
  v_snapshot JSONB;
BEGIN
  SELECT cooldown_seconds, channel_id, department_id,
         jsonb_build_object(
           'name', name,
           'description', description,
           'trigger_type', trigger_type,
           'trigger_config', trigger_config,
           'actions', actions,
           'priority', priority,
           'cooldown_seconds', cooldown_seconds,
           'channel_id', channel_id,
           'department_id', department_id,
           'captured_at', now()
         )
    INTO v_cooldown, v_channel, v_department, v_snapshot
  FROM zapp.automation_rules WHERE id = p_rule_id AND is_active = true;

  IF v_cooldown IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT MAX(created_at) INTO v_last
  FROM zapp.automation_executions
  WHERE rule_id = p_rule_id AND remote_jid = p_remote_jid;

  IF v_last IS NOT NULL AND v_last > now() - make_interval(secs => v_cooldown) THEN
    RETURN NULL;
  END IF;

  INSERT INTO zapp.automation_executions (
    rule_id, remote_jid, instance_name, assigned_to, trigger_payload,
    channel_id, department_id, rule_snapshot, status
  ) VALUES (
    p_rule_id, p_remote_jid, p_instance_name, p_assigned_to, p_trigger_payload,
    COALESCE(p_channel_id, v_channel),
    COALESCE(p_department_id, v_department),
    v_snapshot,
    'pending'
  ) RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: rpc_register_webhook_event(text, text, text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_register_webhook_event(p_event_key text, p_instance_name text, p_event_type text, p_payload_hash text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_inserted BOOLEAN;
BEGIN
  IF p_event_key IS NULL OR length(p_event_key) = 0 THEN
    RAISE EXCEPTION 'event_key required';
  END IF;

  INSERT INTO zapp.webhook_event_dedup (event_key, instance_name, event_type, payload_hash)
  VALUES (p_event_key, p_instance_name, p_event_type, p_payload_hash)
  ON CONFLICT (event_key) DO NOTHING;

  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  RETURN v_inserted > 0;
END;
$$;


--
-- Name: rpc_resolve_instance_by_phone(text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_resolve_instance_by_phone(p_phone text) RETURNS TABLE(instance_name text, api_url text, api_key text, connection_id uuid, contact_phone text, remote_jid text, contact_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  cleaned text;
BEGIN
  PERFORM zapp.fn_require_app_user();

  cleaned := zapp.fn_normalize_br_phone(p_phone);
  RETURN QUERY
  SELECT 
    ec.instance_name::text,
    wc.api_url,
    CASE WHEN wc.api_key IS NULL THEN NULL ELSE '********' END AS api_key,
    wc.id AS connection_id,
    COALESCE(ec.phone_number, split_part(ec.remote_jid, '@', 1))::text,
    ec.remote_jid::text,
    ec.id AS contact_id
  FROM evolution_contacts ec
  JOIN zapp.whatsapp_connections wc ON wc.instance_name = ec.instance_name AND wc.is_active = true
  WHERE ec.deleted_at IS NULL
    AND (
      ec.phone_number = cleaned
      OR split_part(ec.remote_jid, '@', 1) = cleaned
      OR ec.phone_number = p_phone
      OR split_part(ec.remote_jid, '@', 1) = p_phone
    )
  ORDER BY ec.last_message_at DESC NULLS LAST
  LIMIT 1;
END;
$$;


--
-- Name: rpc_resolve_whatsapp_instance(uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_resolve_whatsapp_instance(p_contact_id uuid) RETURNS TABLE(instance_name text, api_url text, api_key text, connection_id uuid, contact_phone text, remote_jid text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  PERFORM zapp.fn_require_app_user();

  RETURN QUERY
  SELECT 
    ec.instance_name::text,
    wc.api_url,
    CASE WHEN wc.api_key IS NULL THEN NULL ELSE '********' END AS api_key,
    wc.id AS connection_id,
    COALESCE(ec.phone_number, split_part(ec.remote_jid, '@', 1))::text AS contact_phone,
    ec.remote_jid::text
  FROM evolution_contacts ec
  JOIN zapp.whatsapp_connections wc ON wc.instance_name = ec.instance_name AND wc.is_active = true
  WHERE ec.id = p_contact_id AND ec.deleted_at IS NULL
  LIMIT 1;
END;
$$;


--
-- Name: rpc_resume_queue(uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_resume_queue(p_queue_id uuid) RETURNS zapp.queues
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_row zapp.queues;
BEGIN
  IF NOT is_admin_or_supervisor(auth.uid()) THEN RAISE EXCEPTION 'forbidden'; END IF;
  UPDATE zapp.queues
     SET status='active', paused_at=NULL, paused_by=NULL, paused_reason=NULL, is_active=true
   WHERE id=p_queue_id RETURNING * INTO v_row;
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'queue not found'; END IF;
  RETURN v_row;
END $$;


--
-- Name: rpc_route_inbound_message(uuid, uuid, uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_route_inbound_message(p_contact_id uuid, p_channel_id uuid DEFAULT NULL::uuid, p_queue_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_sticky zapp.sticky_assignments;
  v_agent_user_id uuid;
  v_agent_profile_id uuid;
  v_dept_id uuid;
  v_max int;
  v_active int;
  v_online boolean;
  v_picked uuid;
  v_source text := 'algorithm';
BEGIN
  IF p_contact_id IS NULL THEN
    RAISE EXCEPTION 'contact_id required';
  END IF;

  -- 1) Tenta sticky
  SELECT * INTO v_sticky
    FROM zapp.sticky_assignments
   WHERE contact_id = p_contact_id
     AND expires_at > now();

  IF FOUND THEN
    SELECT p.user_id,
           COALESCE(p.max_concurrent_chats, 5),
           COALESCE(p.is_online, false),
           p.department_id
      INTO v_agent_user_id, v_max, v_online, v_dept_id
      FROM zapp.profiles p
     WHERE p.id = v_sticky.agent_profile_id;

    SELECT count(*) INTO v_active
      FROM zapp.contacts
     WHERE assigned_to = v_agent_user_id
       AND COALESCE(status, 'open') NOT IN ('resolved','closed');

    -- valida: online, com folga, e (sem fila exigida OU mesmo depto da fila)
    IF v_agent_user_id IS NOT NULL
       AND v_online
       AND v_active < v_max
       AND (
         p_queue_id IS NULL
         OR EXISTS (
              SELECT 1 FROM zapp.queues q
               WHERE q.id = p_queue_id
                 AND (q.department_id IS NULL OR q.department_id = v_dept_id)
                 AND COALESCE(q.status, 'active') = 'active'
            )
       )
    THEN
      v_picked := v_agent_user_id;
      v_source := 'sticky';
    END IF;
  END IF;

  -- 2) Fallback: algoritmo da fila
  IF v_picked IS NULL AND p_queue_id IS NOT NULL THEN
    BEGIN
      SELECT zapp.rpc_pick_next_agent(p_queue_id) INTO v_picked;
    EXCEPTION WHEN undefined_function THEN
      v_picked := NULL;
    END;
    v_source := 'algorithm';
  END IF;

  IF v_picked IS NULL THEN
    BEGIN
      INSERT INTO zapp.audit_log(actor_user_id, action, entity_type, entity_id, payload)
      VALUES (NULL, 'route.no_agent', 'contact', p_contact_id,
              jsonb_build_object('channel', p_channel_id, 'queue', p_queue_id));
    EXCEPTION WHEN undefined_table THEN NULL;
    END;
    RETURN jsonb_build_object('assigned', false, 'source', null);
  END IF;

  -- 3) Atribui (dispara trigger de sticky upsert)
  UPDATE zapp.contacts
     SET assigned_to = v_picked,
         updated_at = now()
   WHERE id = p_contact_id
     AND (assigned_to IS DISTINCT FROM v_picked);

  -- 4) Garante sticky atualizado mesmo se já era o assigned_to
  SELECT id INTO v_agent_profile_id FROM zapp.profiles WHERE user_id = v_picked LIMIT 1;
  IF v_agent_profile_id IS NOT NULL THEN
    PERFORM zapp.fn_sticky_upsert(p_contact_id, v_agent_profile_id, p_channel_id, p_queue_id, v_source);
  END IF;

  RETURN jsonb_build_object(
    'assigned', true,
    'agent_user_id', v_picked,
    'source', v_source,
    'channel_id', p_channel_id,
    'queue_id', p_queue_id
  );
END;
$$;


--
-- Name: rpc_route_incoming_message(uuid, uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_route_incoming_message(p_contact_id uuid, p_connection_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_mode TEXT;
  v_current_assigned UUID;
  v_target_agent UUID;
  v_reason TEXT;
  v_business_open BOOLEAN := TRUE;
BEGIN
  -- Lê estado atual
  SELECT assigned_to INTO v_current_assigned
    FROM zapp.contacts
   WHERE id = p_contact_id
   LIMIT 1;

  -- Se contato já tem dono, não mexe (princípio "nunca tirar atendimento")
  IF v_current_assigned IS NOT NULL THEN
    RETURN jsonb_build_object(
      'action', 'skipped',
      'reason', 'already_assigned',
      'agent_id', v_current_assigned
    );
  END IF;

  -- Lê modo da conexão
  SELECT routing_mode INTO v_mode
    FROM zapp.whatsapp_connections
   WHERE id = p_connection_id
   LIMIT 1;

  v_mode := COALESCE(v_mode, 'manual');

  -- Horário comercial (se a função existir e a conexão configurar)
  BEGIN
    v_business_open := zapp.is_within_business_hours(p_connection_id);
  EXCEPTION WHEN OTHERS THEN
    v_business_open := TRUE;
  END;

  IF NOT v_business_open THEN
    RETURN jsonb_build_object(
      'action', 'unassigned',
      'reason', 'outside_business_hours',
      'mode', v_mode
    );
  END IF;

  -- Modo: manual → não faz nada (Sem dono)
  IF v_mode = 'manual' THEN
    RETURN jsonb_build_object('action', 'unassigned', 'reason', 'manual_mode');
  END IF;

  -- Modo: sticky → último agente conhecido
  IF v_mode = 'sticky' THEN
    SELECT sa.agent_profile_id INTO v_target_agent
      FROM zapp.sticky_assignments sa
     WHERE sa.contact_id = p_contact_id
       AND (sa.channel_connection_id IS NULL OR sa.channel_connection_id = p_connection_id)
       AND sa.expires_at > now()
     ORDER BY sa.last_assigned_at DESC
     LIMIT 1;

    IF v_target_agent IS NOT NULL THEN
      v_reason := 'sticky_match';
    END IF;
  END IF;

  -- Modo: rules → engine de client_wallet_rules
  IF v_mode = 'rules' AND v_target_agent IS NULL THEN
    SELECT cwr.agent_id INTO v_target_agent
      FROM zapp.client_wallet_rules cwr
     WHERE cwr.is_active = TRUE
       AND (cwr.whatsapp_connection_id IS NULL OR cwr.whatsapp_connection_id = p_connection_id)
     ORDER BY cwr.priority DESC, cwr.created_at ASC
     LIMIT 1;

    IF v_target_agent IS NOT NULL THEN
      v_reason := 'rule_match';
    END IF;
  END IF;

  -- Modo: round_robin → menor carga no depto da conexão
  IF v_mode = 'round_robin' AND v_target_agent IS NULL THEN
    SELECT p.id INTO v_target_agent
      FROM zapp.profiles p
     WHERE p.is_active = TRUE
       AND p.role IN ('agent', 'supervisor')
     ORDER BY (
       SELECT COUNT(*) FROM zapp.contacts c2
        WHERE c2.assigned_to = p.id
     ) ASC, p.created_at ASC
     LIMIT 1;

    IF v_target_agent IS NOT NULL THEN
      v_reason := 'round_robin';
    END IF;
  END IF;

  -- Aplica atribuição (se encontrou candidato)
  IF v_target_agent IS NOT NULL THEN
    UPDATE zapp.contacts
       SET assigned_to = v_target_agent,
           updated_at = now()
     WHERE id = p_contact_id
       AND assigned_to IS NULL;  -- guard contra race

    -- Registra sticky para próxima
    BEGIN
      PERFORM zapp.fn_register_sticky_assignment(
        p_contact_id, v_target_agent, p_connection_id, NULL
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;  -- sticky é best-effort
    END;

    RETURN jsonb_build_object(
      'action', 'assigned',
      'agent_id', v_target_agent,
      'reason', v_reason,
      'mode', v_mode
    );
  END IF;

  -- Fallback: nenhum candidato encontrado em modo automático → Sem dono
  RETURN jsonb_build_object(
    'action', 'unassigned',
    'reason', 'no_candidate_fallback',
    'mode', v_mode
  );
END;
$$;


--
-- Name: rpc_run_full_test_suite(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_run_full_test_suite() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'auth', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_run_id  text := 'suite_' || to_char(now(), 'YYYYMMDD_HH24MISS');
  v_passed  integer := 0;
  v_failed  integer := 0;
  v_ok      boolean;
  v_msg     text;
BEGIN
  IF NOT zapp.is_admin_or_supervisor(auth.uid()) THEN
    RAISE EXCEPTION 'permission denied: admin or supervisor required';
  END IF;
  -- T1: Webhook pipeline health
  v_ok := EXISTS (SELECT 1 FROM evo.evolution_webhook_events_v2 WHERE created_at >= now() - interval '1 hour');
  v_msg := CASE WHEN v_ok THEN 'Pipeline respondendo' ELSE 'Pipeline não responde' END;
  INSERT INTO zapp.sts_troubleshooting_report (test_name, status, description, started_at, completed_at)
    VALUES ('webhook_pipeline_health', CASE WHEN v_ok THEN 'passed' ELSE 'failed' END, v_msg, now(), now());
  INSERT INTO zapp.stress_test_metrics (run_id, task_type, latency_ms, status)
    VALUES (v_run_id, 'webhook_pipeline_health', 1, CASE WHEN v_ok THEN 'success' ELSE 'failed' END);
  IF v_ok THEN v_passed := v_passed + 1; ELSE v_failed := v_failed + 1; END IF;
  -- T2: Alert channels ativos
  v_ok := EXISTS (SELECT 1 FROM zapp.alert_channels WHERE is_active = true);
  v_msg := CASE WHEN v_ok THEN 'Pelo menos 1 canal ativo' ELSE 'Nenhum canal ativo' END;
  INSERT INTO zapp.sts_troubleshooting_report (test_name, status, description, started_at, completed_at)
    VALUES ('alert_channels_reachable', CASE WHEN v_ok THEN 'passed' ELSE 'failed' END, v_msg, now(), now());
  INSERT INTO zapp.stress_test_metrics (run_id, task_type, latency_ms, status)
    VALUES (v_run_id, 'alert_channels_reachable', 1, CASE WHEN v_ok THEN 'success' ELSE 'failed' END);
  IF v_ok THEN v_passed := v_passed + 1; ELSE v_failed := v_failed + 1; END IF;
  -- T3: Evolution credentials
  v_ok := EXISTS (SELECT 1 FROM zapp.evolution_instance_credentials WHERE is_active = true);
  v_msg := CASE WHEN v_ok THEN 'Credenciais Evo configuradas' ELSE 'Sem credenciais Evo' END;
  INSERT INTO zapp.sts_troubleshooting_report (test_name, status, description, started_at, completed_at)
    VALUES ('evolution_credentials_present', CASE WHEN v_ok THEN 'passed' ELSE 'failed' END, v_msg, now(), now());
  INSERT INTO zapp.stress_test_metrics (run_id, task_type, latency_ms, status)
    VALUES (v_run_id, 'evolution_credentials_present', 1, CASE WHEN v_ok THEN 'success' ELSE 'failed' END);
  IF v_ok THEN v_passed := v_passed + 1; ELSE v_failed := v_failed + 1; END IF;
  -- T4: RLS em tabelas críticas
  v_ok := (SELECT bool_and(relrowsecurity) FROM pg_class
           WHERE relname IN ('messages','contacts','profiles','conversations','user_roles') AND relkind='r');
  v_msg := CASE WHEN v_ok THEN 'RLS OK em todas tabelas críticas' ELSE 'Tabela crítica sem RLS!' END;
  INSERT INTO zapp.sts_troubleshooting_report (test_name, status, description, started_at, completed_at)
    VALUES ('rls_critical_tables', CASE WHEN v_ok THEN 'passed' ELSE 'failed' END, v_msg, now(), now());
  INSERT INTO zapp.stress_test_metrics (run_id, task_type, latency_ms, status)
    VALUES (v_run_id, 'rls_critical_tables', 1, CASE WHEN v_ok THEN 'success' ELSE 'failed' END);
  IF v_ok THEN v_passed := v_passed + 1; ELSE v_failed := v_failed + 1; END IF;
  -- T5: Cron jobs ativos
  v_ok := (SELECT count(*) FROM cron.job WHERE active = true) >= 3;
  v_msg := format('%s cron jobs ativos', (SELECT count(*) FROM cron.job WHERE active = true));
  INSERT INTO zapp.sts_troubleshooting_report (test_name, status, description, started_at, completed_at)
    VALUES ('cron_jobs_active', CASE WHEN v_ok THEN 'passed' ELSE 'failed' END, v_msg, now(), now());
  INSERT INTO zapp.stress_test_metrics (run_id, task_type, latency_ms, status)
    VALUES (v_run_id, 'cron_jobs_active', 1, CASE WHEN v_ok THEN 'success' ELSE 'failed' END);
  IF v_ok THEN v_passed := v_passed + 1; ELSE v_failed := v_failed + 1; END IF;
  RETURN jsonb_build_object(
    'run_id',       v_run_id,
    'total_tests',  v_passed + v_failed,
    'passed',       v_passed,
    'failed',       v_failed,
    'success_rate', ROUND(100.0 * v_passed / NULLIF(v_passed + v_failed, 0), 1),
    'completed_at', now()
  );
END;
$$;


--
-- Name: rpc_schedule_follow_up(uuid, timestamp with time zone, boolean); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_schedule_follow_up(p_message_id uuid, p_follow_up_at timestamp with time zone, p_follow_up_done boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$

BEGIN
  PERFORM zapp.fn_require_app_user();
  UPDATE evo.evolution_messages
  SET follow_up_at   = p_follow_up_at,
      follow_up_done = p_follow_up_done,
      updated_at     = now()
  WHERE id = p_message_id;

END;$$;


--
-- Name: rpc_schema_columns(text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_schema_columns(p_schema text DEFAULT 'zapp'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp, pg_temp'
    AS $$
BEGIN
  IF p_schema NOT IN ('zapp', 'evo', 'public') THEN
    RAISE EXCEPTION 'permission denied: schema not allowed: %', p_schema
      USING ERRCODE = '42501';
  END IF;

  RETURN COALESCE(
    (
      SELECT jsonb_agg(
               jsonb_build_object(
                 'table_name',   t.table_name::text,
                 'column_name',  c.column_name::text,
                 'data_type',    c.data_type::text,
                 'is_nullable',  c.is_nullable::text
               )
               ORDER BY t.table_name, c.ordinal_position
             )
      FROM information_schema.columns c
      JOIN information_schema.tables t
        ON t.table_schema = c.table_schema AND t.table_name = c.table_name
      WHERE c.table_schema = p_schema
    ),
    '[]'::jsonb
  );
END;
$$;


--
-- Name: rpc_schema_tables(text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_schema_tables(p_schema text DEFAULT 'zapp'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp, pg_temp'
    AS $$
BEGIN
  IF p_schema NOT IN ('zapp', 'evo', 'public') THEN
    RAISE EXCEPTION 'permission denied: schema not allowed: %', p_schema
      USING ERRCODE = '42501';
  END IF;

  RETURN COALESCE(
    (
      SELECT jsonb_agg(
               jsonb_build_object(
                 'table_name', table_name::text,
                 'table_type', table_type::text
               )
               ORDER BY table_name
             )
      FROM information_schema.tables
      WHERE table_schema = p_schema
    ),
    '[]'::jsonb
  );
END;
$$;


--
-- Name: rpc_search_audio_memes(text, text, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_search_audio_memes(p_search text, p_category text DEFAULT NULL::text, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
BEGIN
  RETURN (
    SELECT jsonb_build_object(
      'ok', true,
      'query', p_search,
      'total', count(*),
      'results', COALESCE(jsonb_agg(
        jsonb_build_object(
          'id', id, 'name', name, 'category', category,
          'audio_url', audio_url, 'use_count', use_count,
          'tags', tags, 'similarity', round(similarity(name, p_search)::numeric, 3)
        ) ORDER BY similarity(name, p_search) DESC, use_count DESC
      ), '[]'::jsonb)
    )
    FROM (
      SELECT * FROM audio_memes
      WHERE is_active = true
        AND (
          name % p_search
          OR name ILIKE '%' || p_search || '%'
          OR EXISTS (SELECT 1 FROM unnest(tags) t WHERE t ILIKE '%' || p_search || '%')
        )
        AND (p_category IS NULL OR category = p_category)
      ORDER BY similarity(name, p_search) DESC, use_count DESC
      LIMIT p_limit
    ) sub
  );
END;
$$;


--
-- Name: FUNCTION rpc_search_audio_memes(p_search text, p_category text, p_limit integer); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.rpc_search_audio_memes(p_search text, p_category text, p_limit integer) IS 'Busca fuzzy por nome (trigram) e tags. Retorna com score de similaridade.';


--
-- Name: rpc_search_insights(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_search_insights(p_days integer DEFAULT 7) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
DECLARE
  v_result         jsonb;
  v_total_searches bigint;
  v_zero_results   bigint;
  v_avg_results    numeric;
  v_top_queries    jsonb;
BEGIN
  SELECT count(*) INTO v_total_searches
  FROM zapp.query_telemetry
  WHERE created_at >= now() - (p_days || ' days')::interval
    AND source = 'global_search';

  SELECT COALESCE(jsonb_agg(q ORDER BY cnt DESC), '[]'::jsonb)
  INTO v_top_queries
  FROM (
    SELECT query_text AS query, count(*) AS cnt
    FROM zapp.query_telemetry
    WHERE created_at >= now() - (p_days || ' days')::interval
      AND source = 'global_search'
      AND query_text IS NOT NULL
    GROUP BY query_text
    ORDER BY cnt DESC
    LIMIT 10
  ) q;

  SELECT count(*) INTO v_zero_results
  FROM zapp.dev_diagnostic_logs
  WHERE action = 'search_click'
    AND created_at >= now() - (p_days || ' days')::interval;

  v_result := jsonb_build_object(
    'total_searches',       COALESCE(v_total_searches, 0),
    'zero_result_queries',  0,
    'avg_result_count',     0,
    'click_through_rate',   CASE
                              WHEN v_total_searches > 0
                              THEN ROUND(v_zero_results::numeric / v_total_searches * 100, 2)
                              ELSE 0
                            END,
    'top_queries',          COALESCE(v_top_queries, '[]'::jsonb),
    'window_days',          p_days,
    'generated_at',         now()
  );

  RETURN v_result;
END;
$$;


--
-- Name: rpc_search_media(uuid, text, text, boolean, timestamp with time zone, timestamp with time zone, integer, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_search_media(p_contact_id uuid DEFAULT NULL::uuid, p_remote_jid text DEFAULT NULL::text, p_media_type text DEFAULT NULL::text, p_has_url boolean DEFAULT NULL::boolean, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, message_id text, remote_jid text, media_type text, media_url text, media_mimetype text, media_filename text, media_size integer, caption text, from_me boolean, push_name text, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  PERFORM zapp.fn_require_app_user();

  RETURN QUERY
  SELECT
    em.id,
    em.message_id,
    em.remote_jid,
    em.message_type::text,
    zapp.fn_media_public_url(em.media_url),
    em.media_mimetype::text,
    em.media_filename::text,     -- FIX: varchar→text cast explícito
    em.media_size::integer,
    em.caption::text,
    em.from_me,
    em.push_name::text,
    em.created_at
  FROM evo.evolution_messages em  -- FIX: schema explícito
  WHERE em.message_type IN ('image','video','audio','ptt','document','sticker')
    AND em.deleted_at IS NULL
    AND (p_contact_id IS NULL OR em.contact_id = p_contact_id)
    AND (p_remote_jid IS NULL OR em.remote_jid = p_remote_jid)
    AND (p_media_type IS NULL OR em.message_type::text = p_media_type)
    AND (p_has_url IS NULL OR
      (p_has_url = true  AND em.media_url IS NOT NULL AND em.media_url != '') OR
      (p_has_url = false AND (em.media_url IS NULL OR em.media_url = ''))
    )
    AND (p_date_from IS NULL OR em.created_at >= p_date_from)
    AND (p_date_to   IS NULL OR em.created_at <= p_date_to)
  ORDER BY em.created_at DESC
  LIMIT p_limit OFFSET p_offset;
END;
$$;


--
-- Name: rpc_search_messages(text, text, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_search_messages(p_query text, p_instance text DEFAULT 'wpp2'::text, p_limit integer DEFAULT 20) RETURNS TABLE(id uuid, message_id text, remote_jid text, from_me boolean, content text, message_type text, created_at timestamp with time zone, push_name text, rank real)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$

BEGIN
  PERFORM zapp.fn_require_app_user();
RETURN QUERY  SELECT m.id, m.message_id, m.remote_jid, m.from_me,
    m.content, m.message_type, m.created_at, m.push_name,
    ts_rank(
      to_tsvector('portuguese', COALESCE(m.content,'')),
      plainto_tsquery('portuguese', p_query)
    ) AS rank
  FROM evo.evolution_messages m
  WHERE (p_instance IS NULL OR m.instance_name = p_instance)
    AND m.content IS NOT NULL AND m.deleted_at IS NULL
    AND to_tsvector('portuguese', COALESCE(m.content,''))
        @@ plainto_tsquery('portuguese', p_query)
  ORDER BY rank DESC, m.created_at DESC
  LIMIT p_limit;

END;$$;


--
-- Name: stickers; Type: TABLE; Schema: zapp; Owner: -
--

CREATE TABLE zapp.stickers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text DEFAULT 'Sem nome'::text NOT NULL,
    image_url text NOT NULL,
    category text DEFAULT 'outros'::text,
    use_count integer DEFAULT 0,
    owner_id uuid,
    is_favorite boolean DEFAULT false,
    is_animated boolean DEFAULT false,
    is_active boolean DEFAULT true,
    tags text[] DEFAULT '{}'::text[],
    file_hash text,
    width integer,
    height integer,
    file_size integer,
    mime_type text DEFAULT 'image/webp'::text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    uploaded_by text
);


--
-- Name: rpc_search_stickers(text, text, boolean, integer, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_search_stickers(p_query text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_favorites_only boolean DEFAULT false, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS SETOF zapp.stickers
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  RETURN QUERY
  SELECT s.*
  FROM zapp.stickers s
  WHERE s.is_active = true
    AND (p_query IS NULL OR s.name ILIKE '%' || p_query || '%' OR s.category ILIKE '%' || p_query || '%')
    AND (p_category IS NULL OR s.category = p_category)
    AND (NOT p_favorites_only OR s.is_favorite = true)
  ORDER BY 
    CASE WHEN p_favorites_only THEN s.use_count END DESC,
    s.use_count DESC,
    s.created_at DESC
  LIMIT p_limit
  OFFSET p_offset;
END;
$$;


--
-- Name: rpc_send_sticker(uuid, text, text, uuid, uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_send_sticker(p_contact_id uuid, p_sticker_url text DEFAULT NULL::text, p_instance_name text DEFAULT 'wpp_pink_test'::text, p_sticker_id uuid DEFAULT NULL::uuid, p_created_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'auth'
    AS $$
DECLARE
  v_remote_jid text; v_queue_id uuid; v_sticker record; v_url text;
BEGIN
  PERFORM zapp.fn_require_app_user();

  SELECT remote_jid INTO v_remote_jid FROM evo.evolution_contacts WHERE id=p_contact_id;
  IF v_remote_jid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'contact_id nao encontrado');
  END IF;
  v_url := p_sticker_url;
  IF p_sticker_id IS NOT NULL THEN
    SELECT * INTO v_sticker FROM zapp.stickers WHERE id=p_sticker_id;
    IF v_sticker IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'sticker_id nao encontrado no catalogo');
    END IF;
    v_url := v_sticker.image_url;
    UPDATE zapp.stickers SET use_count=COALESCE(use_count,0)+1 WHERE id=p_sticker_id;
  END IF;
  IF v_url IS NULL OR v_url = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'sticker_url obrigatoria (ou fornecer sticker_id)');
  END IF;
  INSERT INTO zapp.outbound_message_queue(
    contact_id, remote_jid, instance_name, message_type, content,
    media_url, media_mime_type, sticker_id, metadata, status, retry_count, max_retries, created_by
  ) VALUES(
    p_contact_id, v_remote_jid, p_instance_name, 'sticker', '',
    v_url, 'image/webp', p_sticker_id,
    CASE WHEN v_sticker IS NOT NULL THEN
      jsonb_build_object('sticker_name', v_sticker.name, 'sticker_category', v_sticker.category)
    ELSE NULL END,
    'pending', 0, 3, p_created_by
  ) RETURNING id INTO v_queue_id;
  RETURN jsonb_build_object(
    'ok', true, 'queue_id', v_queue_id, 'remote_jid', v_remote_jid,
    'sticker_url', v_url, 'sticker_id', p_sticker_id, 'instance_name', p_instance_name
  );
END; $$;


--
-- Name: rpc_set_whatsapp_mode(text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_set_whatsapp_mode(p_mode text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
BEGIN
  IF NOT zapp.is_admin_or_supervisor(v_uid) THEN
    RAISE EXCEPTION 'forbidden: only admin/supervisor can change whatsapp_mode';
  END IF;

  -- NULL NOT IN (...) = NULL -> IF NULL = FALSE: guarda explícita contra NULL
  -- (achado A3 da auditoria de confirmação 2026-08-05)
  IF p_mode IS NULL OR p_mode NOT IN ('official', 'unofficial') THEN
    RAISE EXCEPTION 'invalid mode: % (allowed: official, unofficial)', p_mode;
  END IF;

  INSERT INTO zapp.global_settings (key, value, updated_by)
  VALUES ('whatsapp_mode', p_mode, v_uid)
  ON CONFLICT (key) DO UPDATE
    SET value = EXCLUDED.value,
        updated_by = EXCLUDED.updated_by,
        updated_at = now();

  RETURN p_mode;
END;
$$;


--
-- Name: rpc_system_health(text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_system_health(p_dummy text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$

BEGIN
  PERFORM zapp.fn_require_app_user();
RETURN (  SELECT jsonb_build_object(
    'timestamp', now(),
    'database_size', pg_size_pretty(pg_database_size(current_database())),
    'messages_total', (SELECT count(*) FROM evolution_messages),
    'messages_24h', (SELECT count(*) FROM evolution_messages WHERE created_at > now() - interval '24 hours'),
    'contacts_total', (SELECT count(*) FROM evolution_contacts),
    'conversations_total', (SELECT count(*) FROM evolution_conversations),
    'groups_total', (SELECT count(*) FROM evolution_groups),
    'webhook_events_24h', (SELECT count(*) FROM evolution_webhook_events WHERE created_at > now() - interval '24 hours'),
    'webhook_processed_24h', (SELECT count(*) FROM evolution_webhook_events WHERE processed = true AND created_at > now() - interval '24 hours'),
    'webhook_unprocessed', (SELECT count(*) FROM evolution_webhook_events WHERE processed = false AND created_at > now() - interval '1 hour'),
    'webhook_errors_24h', (SELECT count(*) FROM evolution_webhook_events WHERE error_message IS NOT NULL AND created_at > now() - interval '24 hours'),
    'dlq_pending', (SELECT count(*) FROM evolution_dlq WHERE processed_at IS NULL),
    'orphan_messages', (SELECT count(*) FROM evolution_messages WHERE contact_id IS NULL AND created_at > now() - interval '24 hours')
  ));
END;$$;


--
-- Name: rpc_system_health_check(); Type: FUNCTION; Schema: zapp; Owner: -
