CREATE FUNCTION zapp.rpc_unlink_channel_queue(p_channel_id uuid, p_queue_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  IF NOT is_admin_or_supervisor(auth.uid()) THEN RAISE EXCEPTION 'forbidden'; END IF;
  DELETE FROM zapp.channel_queues WHERE channel_id=p_channel_id AND queue_id=p_queue_id;
  RETURN FOUND;
END $$;


