CREATE FUNCTION zapp.rpc_upsert_contact(p_remote_jid text, p_instance text, p_push_name text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
    v_id UUID;
BEGIN
  PERFORM zapp.fn_require_app_user();

    INSERT INTO zapp.contacts (remote_jid, push_name, instance, updated_at)
    VALUES (p_remote_jid, p_push_name, p_instance, now())
    ON CONFLICT (remote_jid) DO UPDATE 
    SET push_name = EXCLUDED.push_name,
        instance = EXCLUDED.instance,
        updated_at = now()
    RETURNING id INTO v_id;
    
    RETURN v_id;
END;
$$;


--
-- Name: rpc_upsert_contact(text, text, text, text, text, text, text, text, text, text, integer, text, text[], text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_upsert_contact(p_remote_jid text, p_instance text DEFAULT 'wpp_pink_test'::text, p_push_name text DEFAULT NULL::text, p_full_name text DEFAULT NULL::text, p_phone_number text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_company text DEFAULT NULL::text, p_role_title text DEFAULT NULL::text, p_lead_status text DEFAULT NULL::text, p_lead_source text DEFAULT NULL::text, p_lead_score integer DEFAULT NULL::integer, p_assigned_to text DEFAULT NULL::text, p_tags text[] DEFAULT NULL::text[], p_notes text DEFAULT NULL::text) RETURNS evo.evolution_contacts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_row evo.evolution_contacts;
BEGIN
  PERFORM zapp.fn_require_app_user();

  INSERT INTO evo.evolution_contacts(
    remote_jid, instance_name, push_name, full_name, phone_number, email,
    company, role_title, lead_status, lead_source, lead_score, assigned_to,
    tags, notes, created_at, updated_at
  ) VALUES (
    p_remote_jid, p_instance, p_push_name, p_full_name, p_phone_number,
    p_email, p_company, p_role_title, COALESCE(p_lead_status,'new'),
    p_lead_source, COALESCE(p_lead_score,0), p_assigned_to, p_tags,
    p_notes, now(), now()
  )
  ON CONFLICT(remote_jid) DO UPDATE SET
    push_name     = COALESCE(EXCLUDED.push_name, evolution_contacts.push_name),
    full_name     = COALESCE(EXCLUDED.full_name, evolution_contacts.full_name),
    phone_number  = COALESCE(EXCLUDED.phone_number, evolution_contacts.phone_number),
    email         = COALESCE(EXCLUDED.email, evolution_contacts.email),
    company       = COALESCE(EXCLUDED.company, evolution_contacts.company),
    lead_status   = COALESCE(EXCLUDED.lead_status, evolution_contacts.lead_status),
    lead_score    = COALESCE(EXCLUDED.lead_score, evolution_contacts.lead_score),
    assigned_to   = COALESCE(EXCLUDED.assigned_to, evolution_contacts.assigned_to),
    tags          = COALESCE(EXCLUDED.tags, evolution_contacts.tags),
    notes         = COALESCE(EXCLUDED.notes, evolution_contacts.notes),
    deleted_at    = NULL,
    updated_at    = now()
  RETURNING * INTO v_row;
  RETURN v_row;
END;
$$;


--
-- Name: rpc_upsert_deal(text, uuid, uuid, uuid, text, text, numeric, numeric, numeric, jsonb, date, text, integer, text, text[], text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_upsert_deal(p_title text, p_id uuid DEFAULT NULL::uuid, p_contact_id uuid DEFAULT NULL::uuid, p_conversation_id uuid DEFAULT NULL::uuid, p_description text DEFAULT NULL::text, p_stage text DEFAULT NULL::text, p_value numeric DEFAULT NULL::numeric, p_cost numeric DEFAULT NULL::numeric, p_discount_percent numeric DEFAULT NULL::numeric, p_products jsonb DEFAULT NULL::jsonb, p_expected_close_date date DEFAULT NULL::date, p_assigned_to text DEFAULT NULL::text, p_probability integer DEFAULT NULL::integer, p_source text DEFAULT NULL::text, p_tags text[] DEFAULT NULL::text[], p_notes text DEFAULT NULL::text, p_instance text DEFAULT 'wpp_pink_test'::text) RETURNS evo.evolution_deals
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_row evo.evolution_deals;
BEGIN
  PERFORM zapp.fn_require_app_user();

  IF p_id IS NULL THEN
    INSERT INTO evo.evolution_deals(
      contact_id, conversation_id, title, description, stage,
      value, cost, discount_percent, products, expected_close_date,
      assigned_to, probability, source, tags, notes, instance_name, created_at, updated_at
    ) VALUES(
      p_contact_id, p_conversation_id, p_title, p_description, COALESCE(p_stage,'new'),
      p_value, p_cost, COALESCE(p_discount_percent,0), COALESCE(p_products,'[]'),
      p_expected_close_date, p_assigned_to, COALESCE(p_probability,10),
      p_source, p_tags, p_notes, p_instance, now(), now()
    ) RETURNING * INTO v_row;
  ELSE
    UPDATE evo.evolution_deals SET
      title=COALESCE(p_title,title), description=COALESCE(p_description,description),
      stage=COALESCE(p_stage,stage), value=COALESCE(p_value,value),
      assigned_to=COALESCE(p_assigned_to,assigned_to),
      probability=COALESCE(p_probability,probability),
      notes=COALESCE(p_notes,notes), updated_at=now()
    WHERE id=p_id RETURNING * INTO v_row;
  END IF;
  RETURN v_row;
END; $$;


--
-- Name: rpc_upsert_label(text, uuid, text, text, text, text, integer, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_upsert_label(p_name text, p_id uuid DEFAULT NULL::uuid, p_label_id text DEFAULT NULL::text, p_color text DEFAULT '#3B82F6'::text, p_label_type text DEFAULT 'custom'::text, p_description text DEFAULT NULL::text, p_sort_order integer DEFAULT NULL::integer, p_instance text DEFAULT 'wpp_pink_test'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_id uuid;
BEGIN
  IF p_id IS NOT NULL THEN
    UPDATE evo.evolution_labels
    SET name=COALESCE(p_name,name), color=COALESCE(p_color,color),
        description=COALESCE(p_description,description),
        sort_order=COALESCE(p_sort_order,sort_order), updated_at=NOW()
    WHERE id=p_id RETURNING id INTO v_id;
  ELSE
    INSERT INTO evo.evolution_labels(name, label_id, color, label_type, description, sort_order, instance_name)
    VALUES(p_name, COALESCE(p_label_id,'custom_'||gen_random_uuid()::text),
           p_color, p_label_type, p_description, p_sort_order, p_instance)
    ON CONFLICT(label_id) DO UPDATE
      SET name=EXCLUDED.name, color=EXCLUDED.color, updated_at=NOW()
    RETURNING id INTO v_id;
  END IF;
  RETURN v_id;
END; $$;


--
-- Name: rpc_upsert_service_channel(uuid, text, text, text, uuid, uuid, text, boolean, integer, boolean, text, text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_upsert_service_channel(p_id uuid DEFAULT NULL::uuid, p_name text DEFAULT NULL::text, p_display_name text DEFAULT NULL::text, p_channel_type text DEFAULT 'whatsapp'::text, p_whatsapp_connection_id uuid DEFAULT NULL::uuid, p_default_queue_id uuid DEFAULT NULL::uuid, p_routing_mode text DEFAULT 'manual'::text, p_sticky_enabled boolean DEFAULT false, p_sticky_ttl_hours integer DEFAULT 24, p_is_default boolean DEFAULT false, p_description text DEFAULT NULL::text, p_icon text DEFAULT NULL::text, p_color text DEFAULT '#3B82F6'::text) RETURNS zapp.service_channels
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_row zapp.service_channels;
  v_old zapp.service_channels;
BEGIN
  IF NOT zapp.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Access denied: admin role required';
  END IF;

  IF p_name IS NULL OR length(trim(p_name)) = 0 THEN
    RAISE EXCEPTION 'name is required';
  END IF;

  -- Se este vai ser default, desmarca os outros do mesmo tipo
  IF p_is_default THEN
    UPDATE zapp.service_channels
       SET is_default = false
     WHERE channel_type = p_channel_type
       AND (p_id IS NULL OR id <> p_id)
       AND is_default = true;
  END IF;

  IF p_id IS NULL THEN
    INSERT INTO zapp.service_channels (
      name, display_name, channel_type, whatsapp_connection_id,
      default_queue_id, routing_mode, sticky_enabled, sticky_ttl_hours,
      is_default, description, icon, color, created_by
    ) VALUES (
      trim(p_name), p_display_name, p_channel_type, p_whatsapp_connection_id,
      p_default_queue_id, p_routing_mode, p_sticky_enabled, p_sticky_ttl_hours,
      p_is_default, p_description, p_icon, p_color, auth.uid()
    )
    RETURNING * INTO v_row;

    INSERT INTO zapp.audit_logs (user_id, action, entity_type, entity_id, details)
    VALUES (auth.uid(), 'service_channel_created', 'service_channels', v_row.id::text,
            jsonb_build_object('name', v_row.name, 'type', v_row.channel_type));
  ELSE
    SELECT * INTO v_old FROM zapp.service_channels WHERE id = p_id;
    IF v_old.id IS NULL THEN RAISE EXCEPTION 'channel not found'; END IF;

    UPDATE zapp.service_channels SET
      name = trim(p_name),
      display_name = p_display_name,
      channel_type = p_channel_type,
      whatsapp_connection_id = p_whatsapp_connection_id,
      default_queue_id = p_default_queue_id,
      routing_mode = p_routing_mode,
      sticky_enabled = p_sticky_enabled,
      sticky_ttl_hours = p_sticky_ttl_hours,
      is_default = p_is_default,
      description = p_description,
      icon = p_icon,
      color = p_color
    WHERE id = p_id
    RETURNING * INTO v_row;

    INSERT INTO zapp.audit_logs (user_id, action, entity_type, entity_id, details)
    VALUES (auth.uid(), 'service_channel_updated', 'service_channels', v_row.id::text,
            jsonb_build_object(
              'before', jsonb_build_object('name', v_old.name, 'queue', v_old.default_queue_id, 'sticky', v_old.sticky_enabled),
              'after',  jsonb_build_object('name', v_row.name, 'queue', v_row.default_queue_id, 'sticky', v_row.sticky_enabled)
            ));
  END IF;

  RETURN v_row;
END;
$$;


--
-- Name: rpc_upsert_task(text, uuid, text, text, text, uuid, uuid, date, text, text[], text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_upsert_task(p_title text, p_id uuid DEFAULT NULL::uuid, p_description text DEFAULT NULL::text, p_task_type text DEFAULT 'follow_up'::text, p_assigned_to text DEFAULT NULL::text, p_contact_id uuid DEFAULT NULL::uuid, p_deal_id uuid DEFAULT NULL::uuid, p_due_date date DEFAULT NULL::date, p_priority text DEFAULT 'medium'::text, p_tags text[] DEFAULT NULL::text[], p_notes text DEFAULT NULL::text) RETURNS evo.evolution_tasks
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$ DECLARE v_row evolution_tasks; BEGIN IF p_id IS NULL THEN INSERT INTO evolution_tasks(title,description,task_type,assigned_to,contact_id,deal_id,due_date,priority,tags,notes,status,created_at,updated_at) VALUES(p_title,p_description,p_task_type,p_assigned_to,p_contact_id,p_deal_id,p_due_date,p_priority,p_tags,p_notes,'pending',now(),now()) RETURNING * INTO v_row; ELSE UPDATE evolution_tasks SET title=COALESCE(p_title,title), description=COALESCE(p_description,description), assigned_to=COALESCE(p_assigned_to,assigned_to), due_date=COALESCE(p_due_date,due_date), priority=COALESCE(p_priority,priority), notes=COALESCE(p_notes,notes), updated_at=now() WHERE id=p_id RETURNING * INTO v_row; END IF; RETURN v_row; END; $$;


--
-- Name: rpc_webhook_health_monitor(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_webhook_health_monitor() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'status', 'healthy',
    'events_last_hour', (SELECT count(*) FROM evolution_webhook_events WHERE created_at >= now()-interval '1 hour'),
    'events_last_24h', (SELECT count(*) FROM evolution_webhook_events WHERE created_at >= now()-interval '24 hours'),
    'last_event_at', (SELECT max(created_at) FROM evolution_webhook_events),
    'events_by_instance', (SELECT jsonb_object_agg(instance_name, cnt) FROM (SELECT instance_name, count(*) cnt FROM evolution_webhook_events WHERE created_at >= now()-interval '1 hour' GROUP BY instance_name) t),
    'events_by_type', (SELECT jsonb_object_agg(event_type, cnt) FROM (SELECT event_type, count(*) cnt FROM evolution_webhook_events WHERE created_at >= now()-interval '1 hour' GROUP BY event_type ORDER BY cnt DESC LIMIT 10) t)
  ) INTO v_result;
  RETURN v_result;
END;
$$;


--
-- Name: rpc_zapp_dashboard(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_zapp_dashboard() RETURNS TABLE(metric text, value bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  PERFORM zapp.fn_require_app_user();

  RETURN QUERY
  SELECT 'total_contacts'::text, count(*)::bigint FROM evolution_contacts WHERE deleted_at IS NULL
  UNION ALL
  SELECT 'total_messages', count(*) FROM evolution_messages WHERE deleted_at IS NULL
  UNION ALL
  SELECT 'total_stickers', count(*) FROM stickers WHERE is_active = true
  UNION ALL
  SELECT 'media_with_url', count(*) FROM evolution_messages WHERE media_url IS NOT NULL AND media_url != '' AND message_type IN ('image','video','audio','ptt','document','sticker') AND deleted_at IS NULL
  UNION ALL
  SELECT 'media_without_url', count(*) FROM evolution_messages WHERE (media_url IS NULL OR media_url = '') AND message_type IN ('image','video','audio','ptt','document','sticker') AND deleted_at IS NULL
  UNION ALL
  SELECT 'media_queue_pending', count(*) FROM media_download_queue WHERE status = 'pending'
  UNION ALL
  SELECT 'media_queue_done', count(*) FROM media_download_queue WHERE status = 'done'
  UNION ALL
  SELECT 'media_queue_failed', count(*) FROM media_download_queue WHERE status = 'failed'
  UNION ALL
  SELECT 'agents_online', count(*) FROM agent_presence WHERE status = 'online'
  UNION ALL
  SELECT 'sla_violations_open', count(*) FROM sla_violations WHERE resolved_at IS NULL
  UNION ALL
  SELECT 'outbound_pending', count(*) FROM outbound_message_queue WHERE status = 'pending'
  UNION ALL
  SELECT 'whatsapp_connections_active', count(*) FROM whatsapp_connections WHERE is_active = true AND status = 'connected';
END;
$$;


--
-- Name: rpc_zapp_health_check(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.rpc_zapp_health_check() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_queue_pending bigint;
  v_queue_failed bigint;
  v_queue_stuck bigint;
  v_urls_r2 bigint;
  v_urls_minio bigint;
  v_status text := 'healthy';
  v_alerts jsonb := '[]'::jsonb;
BEGIN
  PERFORM zapp.fn_require_app_user();

  SELECT count(*) INTO v_queue_pending FROM media_download_queue WHERE status='pending';
  SELECT count(*) INTO v_queue_failed FROM media_download_queue WHERE status='failed' AND retry_count >= 3;
  SELECT count(*) INTO v_queue_stuck FROM media_download_queue WHERE status='processing' AND processed_at < now() - interval '10 minutes';
  SELECT count(*) INTO v_urls_r2 FROM evolution_messages WHERE media_url LIKE 'https://zapp-media-proxy%';
  SELECT count(*) INTO v_urls_minio FROM evolution_messages WHERE media_url LIKE 'http://minio%';
  
  IF v_queue_pending > 5000 THEN
    v_alerts := v_alerts || jsonb_build_object('level', 'warning', 'msg', 'Fila de download > 5000 pendentes: ' || v_queue_pending);
    v_status := 'warning';
  END IF;
  IF v_queue_failed > 100 THEN
    v_alerts := v_alerts || jsonb_build_object('level', 'danger', 'msg', 'Downloads falharam definitivamente: ' || v_queue_failed);
    v_status := 'degraded';
  END IF;
  IF v_queue_stuck > 10 THEN
    v_alerts := v_alerts || jsonb_build_object('level', 'warning', 'msg', 'Downloads stuck: ' || v_queue_stuck);
  END IF;
  IF v_urls_minio > 0 THEN
    v_alerts := v_alerts || jsonb_build_object('level', 'info', 'msg', v_urls_minio || ' URLs MinIO internas restantes');
  END IF;
  
  RETURN jsonb_build_object(
    'status', v_status,
    'r2_bucket', 'zapp-whatsapp-media',
    'r2_urls', v_urls_r2,
    'minio_urls', v_urls_minio,
    'queue_pending', v_queue_pending,
    'queue_failed', v_queue_failed,
    'queue_stuck', v_queue_stuck,
    'alerts', v_alerts,
    'checked_at', now()
  );
END;
$$;


--
-- Name: FUNCTION rpc_zapp_health_check(); Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON FUNCTION zapp.rpc_zapp_health_check() IS 'Health check global ZAPP WEB com alertas de R2, fila e URLs';


--
-- Name: run_audit_log_purge(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.run_audit_log_purge() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_count integer;
BEGIN
  -- FIX 2026-07-04: zapp.contact_audit_log (era public)
  DELETE FROM zapp.contact_audit_log
  WHERE changed_at < now() - interval '2 years';
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN jsonb_build_object('rows_purged', v_count);
END;
$$;


--
-- Name: run_contact_purge(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.run_contact_purge() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_count int;
BEGIN
  DELETE FROM zapp.evolution_contacts
  WHERE deleted_at IS NOT NULL AND deleted_at < now() - interval '30 days';
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN jsonb_build_object('purged_contacts', v_count, 'purged_at', now());
END;
$$;


--
-- Name: run_lgpd_purge(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.run_lgpd_purge() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_count    integer;
  v_job_id   uuid;
  v_start    timestamptz := now();
BEGIN
  -- Log job start
  INSERT INTO zapp.scheduled_job_log (job_name, status)
  VALUES ('lgpd_purge', 'running')
  RETURNING id INTO v_job_id;

  -- Delete contacts deleted > 30 days ago
  DELETE FROM zapp.contacts
  WHERE deleted_at IS NOT NULL
    AND deleted_at < now() - interval '30 days';

  GET DIAGNOSTICS v_count = ROW_COUNT;

  -- Update log
  UPDATE zapp.scheduled_job_log
  SET
    finished_at   = now(),
    status        = 'success',
    rows_affected = v_count
  WHERE id = v_job_id;

  RETURN jsonb_build_object(
    'job_id',       v_job_id,
    'rows_purged',  v_count,
    'duration_ms',  EXTRACT(EPOCH FROM (now() - v_start)) * 1000
  );
EXCEPTION WHEN OTHERS THEN
  UPDATE zapp.scheduled_job_log
  SET finished_at = now(), status = 'error', error_msg = SQLERRM
  WHERE id = v_job_id;
  RAISE;
END;
$$;


