--
-- Name: sicoob_outbox_claim(integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.sicoob_outbox_claim(p_batch_size integer DEFAULT 10) RETURNS TABLE(id uuid, payload jsonb, status text, attempt_count integer, next_attempt_at timestamp with time zone, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
BEGIN
  RETURN QUERY
  WITH claimed AS (
    SELECT s.id
    FROM   zapp.sicoob_reply_outbox s
    WHERE  s.status = 'pending'
      AND  (s.next_attempt_at IS NULL OR s.next_attempt_at <= now())
    ORDER BY s.created_at ASC
    LIMIT  p_batch_size
    FOR UPDATE SKIP LOCKED
  )
  UPDATE zapp.sicoob_reply_outbox s
  SET    status = 'processing',
         attempt_count = attempt_count + 1,
         next_attempt_at = now() + INTERVAL '1 minute'
  FROM   claimed
  WHERE  s.id = claimed.id
  RETURNING s.id, s.payload, s.status, s.attempt_count, s.next_attempt_at, s.created_at;
END;
$$;


--
-- Name: skill_based_assign(uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.skill_based_assign(p_queue_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_agent_id UUID;
BEGIN
  SELECT qm.profile_id INTO v_agent_id
  FROM zapp.queue_members qm
  JOIN zapp.profiles p ON p.id = qm.profile_id
  WHERE qm.queue_id = p_queue_id
    AND qm.is_active = true
    AND p.is_active = true
    AND NOT EXISTS (
      SELECT 1 FROM zapp.queue_skill_requirements qsr
      WHERE qsr.queue_id = p_queue_id
      AND NOT EXISTS (
        SELECT 1 FROM zapp.agent_skills ags
        WHERE ags.profile_id = qm.profile_id
        AND ags.skill_name = qsr.skill_name
        AND ags.skill_level >= qsr.min_level
      )
    )
  ORDER BY (
    SELECT COUNT(*) FROM zapp.contacts c 
    WHERE c.assigned_to = qm.profile_id
  ) ASC
  LIMIT 1;
  
  IF v_agent_id IS NULL THEN
    SELECT qm.profile_id INTO v_agent_id
    FROM zapp.queue_members qm
    JOIN zapp.profiles p ON p.id = qm.profile_id
    WHERE qm.queue_id = p_queue_id
      AND qm.is_active = true
      AND p.is_active = true
    ORDER BY (
      SELECT COUNT(*) FROM zapp.contacts c 
      WHERE c.assigned_to = qm.profile_id
    ) ASC
    LIMIT 1;
  END IF;
  
  RETURN v_agent_id;
END;
$$;


--
-- Name: soft_delete_contact(uuid, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.soft_delete_contact(p_contact_id uuid, p_reason text DEFAULT 'manual_deletion'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  UPDATE zapp.contacts
  SET
    deleted_at     = now(),
    deleted_by     = auth.uid(),
    deleted_reason = p_reason,
    updated_at     = now()
  WHERE id = p_contact_id
    AND deleted_at IS NULL
    AND workspace_id = (
      SELECT workspace_id FROM zapp.profiles WHERE id = auth.uid()
    );

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Contact % not found or already deleted', p_contact_id;
  END IF;
END;
$$;


