-- Name: sync_interaction_from_zapp(text, text, text, text, text, text, text, integer, integer, text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.sync_interaction_from_zapp(p_phone text, p_channel text DEFAULT 'whatsapp'::text, p_direction text DEFAULT 'outbound'::text, p_assunto text DEFAULT NULL::text, p_resumo text DEFAULT NULL::text, p_conteudo text DEFAULT NULL::text, p_sentiment text DEFAULT 'neutro'::text, p_message_count integer DEFAULT 1, p_duration_seconds integer DEFAULT NULL::integer, p_agent_name text DEFAULT NULL::text, p_zapp_conversation_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
