    AS $$ DECLARE v_contact_id uuid; v_audit_id uuid; BEGIN SELECT id INTO v_contact_id FROM evo.evolution_contacts WHERE regexp_replace(coalesce(phone_number,''),'\D','','g') = regexp_replace(coalesce(p_phone,''),'\D','','g') AND deleted_at IS NULL ORDER BY last_message_at DESC NULLS LAST LIMIT 1; INSERT INTO evo.evolution_audit_log (action, entity_type, entity_id, performed_by, performed_by_type, metadata, created_at) VALUES ('interaction_sync','contact', v_contact_id, coalesce(p_agent_name, auth.uid()::text, 'system'), 'service', jsonb_build_object('phone',p_phone,'channel',p_channel,'direction',p_direction,'assunto',p_assunto,'resumo',p_resumo,'conteudo',left(p_conteudo,2000),'sentiment',p_sentiment,'message_count',p_message_count,'duration_seconds',p_duration_seconds,'zapp_conversation_id',p_zapp_conversation_id), now()) RETURNING id INTO v_audit_id; RETURN jsonb_build_object('success', true, 'contact_id', v_contact_id, 'audit_id', v_audit_id, 'matched', v_contact_id IS NOT NULL); END $$;


