--
-- Name: trg_create_followups_on_stage_change(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.trg_create_followups_on_stage_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
DECLARE
  v_delay_hours    NUMERIC;
  v_followup_type  TEXT;
  v_message        TEXT;
  v_instance       TEXT;
BEGIN
  IF TG_OP != 'UPDATE' THEN RETURN NEW; END IF;
  IF OLD.stage IS NOT DISTINCT FROM NEW.stage THEN RETURN NEW; END IF;
  IF NEW.deleted_at IS NOT NULL THEN RETURN NEW; END IF;

  v_instance := COALESCE(NEW.instance_name, 'wpp2');

  -- Buscar regra em evolution_followup_rules (schema real)
  SELECT r.delay_hours,
    COALESCE(r.trigger_config->>'followup_type', 'stage_' || NEW.stage),
    r.trigger_config->>'default_message'
  INTO v_delay_hours, v_followup_type, v_message
  FROM evo.evolution_followup_rules r
  WHERE r.trigger_type = 'stage_change'
    AND r.is_active = true
    AND r.trigger_config->>'stage' = NEW.stage
  ORDER BY r.sequence_order ASC LIMIT 1;

  -- Fallback padrão
  IF v_delay_hours IS NULL THEN
    CASE NEW.stage
      WHEN 'orcamento_enviado' THEN
        v_delay_hours := 24; v_followup_type := 'stage_orcamento';
        v_message := 'Olá! Gostaria de saber se recebeu nosso orçamento e se ficou alguma dúvida. Posso ajudar?';
      WHEN 'pagamento_pendente' THEN
        v_delay_hours := 48; v_followup_type := 'stage_pagamento';
        v_message := 'Oi! Notamos que o pagamento ainda está pendente. Posso ajudar ou facilitar o processo?';
      WHEN 'perdido' THEN
        v_delay_hours := 168; v_followup_type := 'stage_reativacao';
        v_message := 'Olá! Ficamos com saudades! Gostaríamos de entender como podemos atender melhor. Podemos conversar?';
      WHEN 'novo_pedido' THEN
        v_delay_hours := 2; v_followup_type := 'stage_confirmacao';
        v_message := 'Oi! Confirmamos seu pedido. Em breve enviaremos os próximos passos. Alguma dúvida?';
      ELSE
        RETURN NEW;
    END CASE;
  END IF;

  -- Dedup por tipo
  IF EXISTS (SELECT 1 FROM evo.evolution_followups
    WHERE deal_id=NEW.id AND followup_type=v_followup_type AND status IN ('pending','scheduled')) THEN
    RETURN NEW;
  END IF;

  INSERT INTO evo.evolution_followups (
    contact_id, conversation_id, deal_id, followup_type,
    scheduled_at, custom_message, status, instance_name,
    created_by, triggered_at, metadata
  ) VALUES (
    NEW.contact_id, NEW.conversation_id, NEW.id, v_followup_type,
    now() + (v_delay_hours || ' hours')::interval,
    v_message, 'pending', v_instance, 'trigger:stage_change', now(),
    jsonb_build_object('from_stage',OLD.stage,'to_stage',NEW.stage,
                       'deal_title',NEW.title,'deal_value',NEW.value,'delay_hours',v_delay_hours)
  );

  RETURN NEW;

-- EXCEPTION HANDLER: nunca bloquear o UPDATE principal
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'trg_create_followups_on_stage_change falhou para deal %: %', NEW.id, SQLERRM;
  RETURN NEW;
END;
$$;


