--
-- Name: trg_process_chat_event(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.trg_process_chat_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_data jsonb;
  v_jid text;
BEGIN
  IF NEW.event_type NOT IN ('chats.upsert','CHATS_UPSERT','chats.update','CHATS_UPDATE') THEN
    RETURN NEW;
  END IF;

  v_data := COALESCE(NEW.payload->'data', NEW.payload);
  v_jid := COALESCE(v_data->>'id', v_data->>'remoteJid', NEW.remote_jid);

  IF v_jid IS NOT NULL THEN
    INSERT INTO evolution_conversations (remote_jid, last_message_at, status)
    VALUES (v_jid, now(), 'aberta')
    ON CONFLICT (remote_jid) DO UPDATE SET
      last_message_at = now();
  END IF;

  NEW.processed := true;
  NEW.processed_at := now();
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  NEW.error_message := SQLERRM;
  NEW.processed := false;
  RETURN NEW;
END;
$$;


--
-- Name: trg_process_connection_event(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.trg_process_connection_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
DECLARE
  v_data  JSONB;
  v_state TEXT;
  v_inst  TEXT;
  v_key   TEXT;
BEGIN
  IF NEW.event_type NOT IN (
    'connection.update','CONNECTION_UPDATE',
    'status.instance','STATUS_INSTANCE',
    'logout.instance','LOGOUT_INSTANCE'
  ) THEN RETURN NEW; END IF;

  v_data  := COALESCE(NEW.payload->'data', NEW.payload);
  v_state := COALESCE(v_data->>'state', v_data->>'status', v_data->>'connection', 'unknown');
  v_inst  := COALESCE(NEW.instance_name, 'wpp2');
  v_key   := 'connection_status_' || v_inst;

  IF NEW.event_type IN ('logout.instance','LOGOUT_INSTANCE') THEN
    v_state := 'close';
  END IF;

  -- Atualizar chave de status (sempre, independente do state)
  INSERT INTO evo.evolution_settings (id, key, value, category, created_at, updated_at)
  VALUES (
    gen_random_uuid(), v_key,
    jsonb_build_object('state', v_state, 'instance', v_inst, 'event', NEW.event_type, 'updated_at', now()),
    'general', now(), now()
  )
  ON CONFLICT (key) DO UPDATE SET value=EXCLUDED.value, updated_at=now();

  -- Alerta de desconexão (v_state agora NUNCA é NULL graças ao COALESCE acima)
  IF v_state IN ('close','disconnected','close_failure','unknown') THEN
    -- 'unknown' também é tratado como possível desconexão
    IF v_state != 'unknown' THEN  -- evitar spam de alertas para states desconhecidos
      INSERT INTO evo.evolution_alerts (alert_type, severity, remote_jid, message)
      VALUES (
        'connection_lost', 'critical', NULL,
        'Instância ' || v_inst || ' desconectada: ' || v_state
      )
      ON CONFLICT DO NOTHING;
    END IF;
  ELSIF v_state IN ('open','connected') THEN
    UPDATE evo.evolution_alerts
    SET resolved_at=now(), acknowledged_at=now()
    WHERE alert_type='connection_lost' AND acknowledged=false AND resolved=false;
  END IF;

  NEW.processed    := true;
  NEW.processed_at := now();
  RETURN NEW;

EXCEPTION WHEN OTHERS THEN
  -- NUNCA bloquear o write principal
  RAISE WARNING 'trg_process_connection_event falhou para evento %: %', NEW.id, SQLERRM;
  NEW.error_message := SQLERRM;
  NEW.processed     := false;
  RETURN NEW;
END;
$$;


--
-- Name: trg_process_contact_event(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.trg_process_contact_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $_$
DECLARE
  v_data jsonb;
  v_contacts jsonb;
  v_c jsonb;
  v_jid text;
BEGIN
  IF NEW.event_type NOT IN ('contacts.upsert','CONTACTS_UPSERT','contacts.update','CONTACTS_UPDATE') THEN
    RETURN NEW;
  END IF;

  v_data := COALESCE(NEW.payload->'data', NEW.payload);

  -- Pode ser array ou objeto
  IF jsonb_typeof(v_data) = 'array' THEN
    v_contacts := v_data;
  ELSIF v_data ? 'contacts' AND jsonb_typeof(v_data->'contacts') = 'array' THEN
    v_contacts := v_data->'contacts';
  ELSE
    v_contacts := jsonb_build_array(v_data);
  END IF;

  FOR v_c IN SELECT * FROM jsonb_array_elements(v_contacts)
  LOOP
    v_jid := COALESCE(v_c->>'id', v_c->>'remoteJid');
    IF v_jid IS NULL THEN CONTINUE; END IF;

    INSERT INTO evolution_contacts (remote_jid, push_name, phone_number, profile_picture_url, instance_name)
    VALUES (
      v_jid,
      COALESCE(v_c->>'pushName', v_c->>'name', v_c->>'notify'),
      regexp_replace(v_jid, '@.*$', ''),
      COALESCE(v_c->>'profilePictureUrl', v_c->>'imgUrl'),
      NEW.instance_name
    )
    ON CONFLICT (remote_jid) DO UPDATE SET
      push_name = COALESCE(EXCLUDED.push_name, evolution_contacts.push_name),
      phone_number = COALESCE(EXCLUDED.phone_number, evolution_contacts.phone_number),
      profile_picture_url = COALESCE(EXCLUDED.profile_picture_url, evolution_contacts.profile_picture_url),
      updated_at = now();
  END LOOP;

  NEW.processed := true;
  NEW.processed_at := now();
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  NEW.error_message := SQLERRM;
  NEW.processed := false;
  RETURN NEW;
END;
$_$;


