--
-- Name: trg_process_message_update(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.trg_process_message_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_data jsonb;
  v_msg_id text;
  v_status text;
  v_raw text;
BEGIN
  IF NEW.event_type NOT IN ('messages.update','MESSAGES_UPDATE') THEN
    RETURN NEW;
  END IF;

  v_data := COALESCE(NEW.payload->'data', NEW.payload);
  v_msg_id := COALESCE(v_data->>'keyId', (v_data->'key'->>'id'));
  v_raw := COALESCE(v_data->>'status', '');

  -- Normalizar status
  CASE UPPER(v_raw)
    WHEN '0', 'ERROR', 'FAILED' THEN v_status := 'failed';
    WHEN '1', 'PENDING' THEN v_status := 'pending';
    WHEN '2', 'SENT', 'SERVER_ACK' THEN v_status := 'sent';
    WHEN '3', 'DELIVERED', 'DELIVERY_ACK' THEN v_status := 'delivered';
    WHEN '4', 'READ', 'READ_RECEIPT' THEN v_status := 'read';
    WHEN '5', 'PLAYED' THEN v_status := 'read';
    ELSE v_status := lower(v_raw);
  END CASE;

  IF v_msg_id IS NOT NULL AND v_status IS NOT NULL AND v_status <> '' THEN
    UPDATE evolution_messages SET status = v_status, status_at = now()
    WHERE message_id = v_msg_id;
  END IF;

  NEW.processed := true;
  NEW.processed_at := now();
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  NEW.error_message := SQLERRM;
  NEW.processed := false;
  RETURN NEW;
END;
$$;


