    LANGUAGE plpgsql
    AS $$ BEGIN RETURN NEW; END; $$;


--
-- Name: trg_queue_deal_for_bitrix(); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.trg_queue_deal_for_bitrix() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
DECLARE
  v_operation  TEXT;
  v_payload    JSONB;
  v_changed    BOOLEAN := false;
BEGIN
  IF NEW.deleted_at IS NOT NULL THEN RETURN NEW; END IF;

  -- FIX: Filtro mais específico — evita bloquear empresas reais com nomes como "QA Systems"
  -- Usar padrão com underscores (improvável em nomes comerciais) ou flag de metadata
  IF (NEW.title ILIKE '_TESTE_%' OR NEW.title ILIKE '_TEST_%' OR NEW.title ILIKE '_QA_%' OR NEW.title ILIKE '_SMOKE_%')
     OR (NEW.metadata->>'skip_bitrix_sync')::boolean = true
  THEN RETURN NEW; END IF;

  IF TG_OP = 'INSERT' THEN
    v_operation := 'create'; v_changed := true;
  ELSE
    v_changed := (
      (OLD.stage IS DISTINCT FROM NEW.stage) OR (OLD.value IS DISTINCT FROM NEW.value) OR
      (OLD.title IS DISTINCT FROM NEW.title) OR (OLD.assigned_to IS DISTINCT FROM NEW.assigned_to) OR
      (OLD.won IS DISTINCT FROM NEW.won) OR (OLD.lost IS DISTINCT FROM NEW.lost)
    );
    v_operation := 'update';
  END IF;

  IF NOT v_changed THEN RETURN NEW; END IF;

  v_payload := jsonb_build_object(
    'deal_id', NEW.id, 'deal_number', NEW.deal_number, 'title', NEW.title,
    'stage', NEW.stage, 'value', NEW.value, 'contact_id', NEW.contact_id,
    'assigned_to', NEW.assigned_to, 'won', COALESCE(NEW.won,false),
    'lost', COALESCE(NEW.lost,false), 'lost_reason', NEW.lost_reason,
    'instance_name', NEW.instance_name, 'created_at', NEW.created_at,
    'updated_at', NEW.updated_at, 'op', v_operation,
    'changed_fields', CASE WHEN TG_OP='UPDATE' THEN jsonb_build_object(
      'stage', (OLD.stage IS DISTINCT FROM NEW.stage), 'value', (OLD.value IS DISTINCT FROM NEW.value),
      'title', (OLD.title IS DISTINCT FROM NEW.title), 'assigned_to', (OLD.assigned_to IS DISTINCT FROM NEW.assigned_to),
      'won', (OLD.won IS DISTINCT FROM NEW.won), 'lost', (OLD.lost IS DISTINCT FROM NEW.lost)
    ) ELSE '{}'::jsonb END
  );

  -- Dedup update-sobre-update (dentro de 30s)
  IF v_operation = 'update' AND EXISTS (
    SELECT 1 FROM evo.evolution_bitrix_queue
    WHERE local_id=NEW.id AND entity_type='deal' AND operation='update'
      AND status='pending' AND created_at > now() - INTERVAL '30 seconds'
  ) THEN
    UPDATE evo.evolution_bitrix_queue SET payload=v_payload, next_attempt_at=now()
    WHERE local_id=NEW.id AND entity_type='deal' AND operation='update'
      AND status='pending' AND created_at > now() - INTERVAL '30 seconds';
    RETURN NEW;
  END IF;

  INSERT INTO evo.evolution_bitrix_queue (operation,entity_type,local_id,payload,status,attempts,max_attempts,next_attempt_at,created_at)
  VALUES (v_operation,'deal',NEW.id,v_payload,'pending',0,3,now(),now());
  RETURN NEW;
END; $$;


