--
-- Name: update_large_batch_safe(text, integer); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.update_large_batch_safe(update_query text, batch_size integer DEFAULT 10000) RETURNS TABLE(total_updated integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
DECLARE
  v_total_updated INT := 0;
  v_batch_updated INT;
  v_offset INT := 0;
BEGIN
  WHILE v_total_updated < 1000000 LOOP
    EXECUTE format('%s LIMIT %s OFFSET %s', update_query, batch_size, v_offset);
    GET DIAGNOSTICS v_batch_updated = ROW_COUNT;
    EXIT WHEN v_batch_updated = 0;
    
    v_total_updated := v_total_updated + v_batch_updated;
    v_offset := v_offset + batch_size;
  END LOOP;
  
  RETURN QUERY SELECT v_total_updated;
END;
$$;


--
-- Name: update_own_profile(text, text, text, text, text, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.update_own_profile(p_display_name text DEFAULT NULL::text, p_avatar_url text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_signature text DEFAULT NULL::text, p_birthday text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_profile_id UUID;
BEGIN
  SELECT id INTO v_profile_id FROM profiles WHERE user_id = auth.uid();
  IF v_profile_id IS NULL THEN
    RETURN FALSE;
  END IF;

  UPDATE profiles SET
    display_name = COALESCE(p_display_name, display_name),
    avatar_url = COALESCE(p_avatar_url, avatar_url),
    phone = COALESCE(p_phone, phone),
    email = COALESCE(p_email, email),
    signature = COALESCE(p_signature, signature),
    birthday = COALESCE(p_birthday, birthday),
    updated_at = now()
  WHERE id = v_profile_id;

  RETURN TRUE;
END;
$$;


