--
-- Name: upsert_contact_intelligence(uuid); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.upsert_contact_intelligence(p_contact_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
DECLARE
  v_ec     evo.evolution_contacts%ROWTYPE;
  v_msgs   int := 0;
  v_inb    int := 0;
  v_out    int := 0;
  v_last   timestamptz;
  v_eng    numeric(5,2);
  v_risk   text;
  v_disc   text := 'C';
  v_days   int;
  v_ratio  numeric(5,2) := 0;
BEGIN
  SELECT * INTO v_ec FROM evo.evolution_contacts WHERE id = p_contact_id LIMIT 1;
  IF NOT FOUND THEN RETURN; END IF;

  -- Stats de mensagens
  SELECT
    count(*),
    count(*) FILTER (WHERE NOT from_me),
    count(*) FILTER (WHERE from_me),
    max(created_at)
  INTO v_msgs, v_inb, v_out, v_last
  FROM evo.evolution_messages_wpp2 m
  WHERE m.deleted_at IS NULL AND m.contact_id = p_contact_id;

  IF COALESCE(v_ec.total_messages, 0) > v_msgs THEN v_msgs := v_ec.total_messages; END IF;

  v_days := CASE WHEN v_last IS NOT NULL
    THEN EXTRACT(DAY FROM (now() - v_last))::int
    WHEN v_ec.last_message_at IS NOT NULL
    THEN EXTRACT(DAY FROM (now() - v_ec.last_message_at))::int
    ELSE NULL END;

  v_eng := LEAST(100, GREATEST(0,
    COALESCE(v_ec.lead_score, 0)::numeric * 0.5
    + LEAST(50, v_msgs * 0.5)
    - COALESCE(v_days, 0) * 0.3
  ));

  v_risk := CASE
    WHEN v_eng < 20 OR COALESCE(v_days, 999) > 60 THEN 'high'
    WHEN v_eng < 50 OR COALESCE(v_days, 999) > 30 THEN 'medium'
    ELSE 'low' END;

  v_disc := CASE
    WHEN v_ec.lead_score >= 70 THEN 'D'
    WHEN v_inb > v_out AND v_msgs > 5 THEN 'I'
    WHEN v_inb > v_out * 1.5 THEN 'S'
    ELSE 'C' END;

  IF v_msgs > 0 THEN
    v_ratio := round((v_inb::numeric / v_msgs) * 100, 2);
  END IF;

  INSERT INTO zapp.contact_intelligence
    (contact_id, sentiment, engagement_score, predicted_value, risk_level,
     phone, contact_name, lead_status, total_messages, days_since_contact,
     disc_profile, inbound_ratio, created_at, updated_at)
  VALUES (
    p_contact_id,
    CASE WHEN v_inb > v_out * 2 THEN 'positive'
         WHEN v_out > v_inb * 3 THEN 'negative'
         ELSE 'neutral' END,
    v_eng,
    COALESCE(v_ec.total_purchases, 0),
    v_risk,
    COALESCE(v_ec.phone_number, split_part(v_ec.remote_jid::text, '@', 1)),
    COALESCE(v_ec.full_name, v_ec.push_name),
    v_ec.lead_status,
    v_msgs,
    v_days,
    v_disc,
    v_ratio,
    now(), now()
  )
  ON CONFLICT (contact_id) DO UPDATE SET
    sentiment          = EXCLUDED.sentiment,
    engagement_score   = EXCLUDED.engagement_score,
    predicted_value    = EXCLUDED.predicted_value,
    risk_level         = EXCLUDED.risk_level,
    phone              = EXCLUDED.phone,
    contact_name       = EXCLUDED.contact_name,
    lead_status        = EXCLUDED.lead_status,
    total_messages     = EXCLUDED.total_messages,
    days_since_contact = EXCLUDED.days_since_contact,
    disc_profile       = EXCLUDED.disc_profile,
    inbound_ratio      = EXCLUDED.inbound_ratio,
    updated_at         = now();
END;
$$;


--
-- Name: upsert_conversation_tags_atomic(uuid, jsonb, jsonb); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.upsert_conversation_tags_atomic(p_contact_id uuid, p_new_tags jsonb, p_old_tags jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
BEGIN
  INSERT INTO zapp.ai_conversation_tags (contact_id, tag_name, confidence, source)
  SELECT p_contact_id, (tag->>'name'), (tag->>'confidence')::numeric, COALESCE(tag->>'source', 'ai')
  FROM jsonb_array_elements(p_new_tags) AS tag
  WHERE tag->>'name' IS NOT NULL
  ON CONFLICT (contact_id, tag_name) DO UPDATE SET
    confidence = EXCLUDED.confidence,
    updated_at = now();
  IF p_old_tags IS NOT NULL THEN
    DELETE FROM zapp.ai_conversation_tags
    WHERE contact_id = p_contact_id
      AND tag_name NOT IN (SELECT tag->>'name' FROM jsonb_array_elements(p_old_tags) AS tag);
  END IF;
END;
$$;


--
-- Name: user_has_permission(uuid, text); Type: FUNCTION; Schema: zapp; Owner: -
--

CREATE FUNCTION zapp.user_has_permission(_user_id uuid, _permission_name text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
  SELECT
    (_user_id IS NOT DISTINCT FROM auth.uid())
    AND EXISTS (
      SELECT 1 FROM zapp.user_roles ur
      JOIN zapp.role_permissions rp ON rp.role = ur.role
      JOIN zapp.permissions p ON p.id = rp.permission_id
      WHERE ur.user_id = _user_id
        AND p.name = _permission_name
    )
$$;


