--
-- Name: ordens_compra; Type: TABLE; Schema: vendas; Owner: -
--

CREATE TABLE vendas.ordens_compra (
    id bigint NOT NULL,
    ano integer NOT NULL,
    mes integer NOT NULL,
    aba_origem text NOT NULL,
    linha_planilha integer NOT NULL,
    prioridade text,
    tipo_pedido text,
    data_entrega date,
    data_venda timestamp with time zone,
    pedido text,
    empresa text,
    cnpj text,
    cliente text,
    produto text,
    fornecedor text,
    cod_produto text,
    cor text,
    qtd_pedido numeric(14,3),
    qtd_faltante numeric(14,3),
    qtd_compra numeric(14,3),
    valor_compra_unid numeric(14,4),
    valor_compra_total numeric(14,2),
    valor_vendido_unid numeric(14,6),
    link_produto text,
    layout text,
    obs_vendedor text,
    tipo_gravacao text,
    cidade_estado text,
    vendedor text,
    status text,
    status_pagamento text,
    comprovante text,
    recibo_enviado text,
    observacoes text,
    favorecido text,
    chave_pix text,
    pagamento text,
    restante numeric(14,2),
    numero_fornecedor text,
    solicitante text,
    data_solicitacao timestamp with time zone,
    gravacao_fornecedor text,
    gravacao_valor_unid numeric(14,4),
    payload_raw jsonb,
    hash_linha text,
    sincronizado_em timestamp with time zone DEFAULT now() NOT NULL,
    criado_em timestamp with time zone DEFAULT now() NOT NULL,
    atualizado_em timestamp with time zone DEFAULT now() NOT NULL,
    excluido_em timestamp with time zone,
    hash_compras text,
    hash_update text,
    qtd_enviada numeric DEFAULT 0,
    status_envio text DEFAULT 'pendente'::text,
    ultimo_envio_em timestamp with time zone,
    ultima_cotacao_id uuid,
    ncm text,
    ncm_atualizado_em timestamp with time zone,
    ncm_fonte text,
    valor_compra_aprovado numeric,
    alteracao_valor_status text,
    CONSTRAINT chk_ncm_formato CHECK (((ncm IS NULL) OR (ncm ~ '^[0-9]{8}$'::text))),
    CONSTRAINT chk_status_envio CHECK ((status_envio = ANY (ARRAY['pendente'::text, 'parcial'::text, 'total'::text]))),
    CONSTRAINT ordens_compra_mes_check CHECK (((mes >= 1) AND (mes <= 12)))
);


--
-- Name: COLUMN ordens_compra.hash_compras; Type: COMMENT; Schema: vendas; Owner: -
--

COMMENT ON COLUMN vendas.ordens_compra.hash_compras IS 'MD5 de (produto + fornecedor + qtd_compra + valor_compra_unid + valor_compra_total). Usado pelo Fluxo 2 (n8n) para detectar mudanças nas 5 colunas editáveis.';


--
-- Name: COLUMN ordens_compra.qtd_enviada; Type: COMMENT; Schema: vendas; Owner: -
--

COMMENT ON COLUMN vendas.ordens_compra.qtd_enviada IS '[Onda 5] Quantidade já enviada via cotações aprovadas. Atualizada apenas pela função vendas.aplicar_envio_cotacao(). Não confundir com qtd_faltante que vem do sync n8n da planilha.';


--
-- Name: COLUMN ordens_compra.status_envio; Type: COMMENT; Schema: vendas; Owner: -
--

COMMENT ON COLUMN vendas.ordens_compra.status_envio IS '[Onda 5] Status de envio do item: pendente | parcial | total. Sincronizado com a coluna status via trigger trg_sync_status_envio quando status muda para ENTREGUE/CONCLUIDO.';


--
-- Name: COLUMN ordens_compra.ultimo_envio_em; Type: COMMENT; Schema: vendas; Owner: -
--

COMMENT ON COLUMN vendas.ordens_compra.ultimo_envio_em IS '[Onda 5] Timestamp do último envio físico aplicado via painel de cotação. NULL = nenhum envio via painel ainda (mesmo que status_envio=total via sync de status).';


--
-- Name: COLUMN ordens_compra.ultima_cotacao_id; Type: COMMENT; Schema: vendas; Owner: -
--

COMMENT ON COLUMN vendas.ordens_compra.ultima_cotacao_id IS '[Onda 5] UUID da última cotação que gerou baixa neste item. Referência informativa (não é FK formal para não bloquear deleção de cotações).';


--
-- Name: COLUMN ordens_compra.ncm; Type: COMMENT; Schema: vendas; Owner: -
--

COMMENT ON COLUMN vendas.ordens_compra.ncm IS '[Onda NF] Código NCM do produto (8 dígitos sem ponto). Populado por fluxo n8n consultando Bling API. Usado para emissão de NF.';


--
-- Name: COLUMN ordens_compra.ncm_atualizado_em; Type: COMMENT; Schema: vendas; Owner: -
--

COMMENT ON COLUMN vendas.ordens_compra.ncm_atualizado_em IS '[Onda NF] Timestamp da última atualização do NCM. NULL = nunca foi tentado popular.';


--
-- Name: COLUMN ordens_compra.ncm_fonte; Type: COMMENT; Schema: vendas; Owner: -
--

COMMENT ON COLUMN vendas.ordens_compra.ncm_fonte IS '[Onda NF] Fonte do NCM: bling_api | manual | mapa_cache. NULL = sem NCM.';


--
-- Name: v_pedidos; Type: VIEW; Schema: artes; Owner: -
--

CREATE VIEW artes.v_pedidos WITH (security_invoker='true') AS
 SELECT oc.id,
    oc.ano,
    oc.mes,
    oc.pedido,
    oc.prioridade,
    oc.tipo_pedido,
    (upper(COALESCE(oc.tipo_pedido, ''::text)) = 'EVENTO'::text) AS material_evento,
    oc.data_entrega,
    oc.data_venda,
    oc.empresa,
    oc.cliente,
    oc.cidade_estado,
    oc.produto,
    oc.fornecedor,
    oc.cor,
    oc.qtd_pedido,
    oc.qtd_compra,
    oc.valor_vendido_unid,
    oc.link_produto,
    oc.layout,
    oc.tipo_gravacao,
    oc.gravacao_fornecedor,
    oc.gravacao_valor_unid,
    oc.vendedor,
    oc.observacoes AS obs_pedido,
    oc.obs_vendedor,
    COALESCE(f.status, 'NA_FILA'::text) AS fechamento_status,
    f.motivo_pendencia,
    f.arquivo_url,
    f.arquivo_path,
    f.arquivo_tipo,
    f.arquivo_nome,
    f.arquivo_tamanho,
    f.responsavel AS fechamento_responsavel,
    f.iniciado_em,
    f.concluido_em,
    f.enviado_bitrix_em,
    f.observacoes AS fechamento_observacoes,
    f.atualizado_em AS fechamento_atualizado_em
   FROM (vendas.ordens_compra oc
     LEFT JOIN artes.fechamentos f ON ((f.ordem_compra_id = oc.id)))
  WHERE ((oc.excluido_em IS NULL) AND (((oc.ano = 2026) AND (oc.mes >= 5)) OR (oc.ano > 2026)));


