--

COMMENT ON VIEW evo.active_messages IS 'Fonte migrada 2026-07-11: evolution_messages_wpp2 (legado congelado) → evolution_messages (consolidada Lovable). 9 views dependentes preservadas via CREATE OR REPLACE.';


--
-- Name: evolution_webhook_events_v2; Type: TABLE; Schema: evo; Owner: -
--

CREATE TABLE evo.evolution_webhook_events_v2 (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    event_type text NOT NULL,
    instance_name text NOT NULL,
    remote_jid text,
    from_me boolean,
    message_type text,
    push_name text,
    payload jsonb NOT NULL,
    processed boolean DEFAULT false,
    processed_at timestamp with time zone,
    error_message text,
    status text DEFAULT 'pending'::text NOT NULL,
    retry_count integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT evolution_webhook_events_v2_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'processed'::text, 'failed'::text, 'dead_letter'::text])))
)
PARTITION BY RANGE (created_at);


--
-- Name: TABLE evolution_webhook_events_v2; Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON TABLE evo.evolution_webhook_events_v2 IS 'Tabela particionada por RANGE(created_at) mensal. Substitui evolution_webhook_events_* por instância. v1.3.0';


--
-- Name: active_webhook_events; Type: VIEW; Schema: evo; Owner: -
--

CREATE VIEW evo.active_webhook_events WITH (security_invoker='true') AS
 SELECT evolution_webhook_events_v2.id,
    evolution_webhook_events_v2.event_type,
    evolution_webhook_events_v2.instance_name,
    evolution_webhook_events_v2.remote_jid,
    evolution_webhook_events_v2.from_me,
    evolution_webhook_events_v2.message_type,
    evolution_webhook_events_v2.push_name,
    evolution_webhook_events_v2.payload,
    ((evolution_webhook_events_v2.processed IS NOT NULL) AND (evolution_webhook_events_v2.status = ANY (ARRAY['processed'::text, 'success'::text]))) AS processed,
    evolution_webhook_events_v2.processed_at,
    evolution_webhook_events_v2.error_message,
    evolution_webhook_events_v2.created_at,
        CASE evolution_webhook_events_v2.status
            WHEN 'processed'::text THEN 'success'::zapp.webhook_event_status
            WHEN 'processing'::text THEN 'pending'::zapp.webhook_event_status
            WHEN 'dead_letter'::text THEN 'failed'::zapp.webhook_event_status
            WHEN 'pending'::text THEN 'pending'::zapp.webhook_event_status
            WHEN 'failed'::text THEN 'failed'::zapp.webhook_event_status
            ELSE 'pending'::zapp.webhook_event_status
        END AS status
   FROM evo.evolution_webhook_events_v2;


