-- Name: TABLE evolution_burnin_tracker; Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON TABLE evo.evolution_burnin_tracker IS 'E10-02/E10-03: Singleton row tracking 72h burn-in start time. burn_in_start is reset to now() if a critical alert occurs (E10-03) or if any Baileys disconnection exceeds 120s (E10-02). Disconnections 30-120s produce a WARN alert but do NOT reset the counter.';


--
-- Name: evolution_business_hours; Type: TABLE; Schema: evo; Owner: -
--

CREATE TABLE evo.evolution_business_hours (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    day_of_week integer NOT NULL,
    open_time time without time zone NOT NULL,
    close_time time without time zone NOT NULL,
    is_closed boolean DEFAULT false,
    timezone character varying(50) DEFAULT 'America/Sao_Paulo'::character varying,
    created_at timestamp with time zone DEFAULT now()
);


--
-- Name: evolution_chatbot_responses; Type: TABLE; Schema: evo; Owner: -
--

CREATE TABLE evo.evolution_chatbot_responses (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    remote_jid text NOT NULL,
    response_text text NOT NULL,
    model_used text DEFAULT 'fallback'::text NOT NULL,
    tokens_used integer,
    response_time_ms integer,
    feedback text,
    created_at timestamp with time zone DEFAULT now()
);


--
-- Name: evolution_connection_history; Type: TABLE; Schema: evo; Owner: -
--

CREATE TABLE evo.evolution_connection_history (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    instance_name text DEFAULT 'wpp2'::text NOT NULL,
    state text NOT NULL,
    previous_state text,
    duration_seconds integer,
    metadata jsonb,
    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT evolution_connection_history_previous_state_check CHECK (((previous_state IS NULL) OR (previous_state = ANY (ARRAY['connecting'::text, 'connected'::text, 'disconnected'::text, 'qr_pending'::text, 'banned'::text, 'logged_out'::text])))),
    CONSTRAINT evolution_connection_history_state_check CHECK ((state = ANY (ARRAY['connecting'::text, 'connected'::text, 'disconnected'::text, 'qr_pending'::text, 'banned'::text, 'logged_out'::text])))
)
WITH (autovacuum_vacuum_threshold='25', autovacuum_analyze_threshold='25', autovacuum_vacuum_scale_factor='0.05', autovacuum_analyze_scale_factor='0.02');


--
-- Name: TABLE evolution_connection_history; Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON TABLE evo.evolution_connection_history IS 'Histórico imutável de mudanças de connectionStatus em whatsapp_connections. Populado pelo trigger trg_log_whatsapp_connection_state_change. Cada linha = uma transição de status com diff metadata.';


--
-- Name: evolution_contact_notes; Type: TABLE; Schema: evo; Owner: -
--

CREATE TABLE evo.evolution_contact_notes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    remote_jid character varying(255) NOT NULL,
    note_type character varying(50) DEFAULT 'general'::character varying,
    content text NOT NULL,
    is_pinned boolean DEFAULT false,
    created_by character varying(255),
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now()
);


--
-- Name: evolution_contact_rate_limits; Type: TABLE; Schema: evo; Owner: -
--

CREATE TABLE evo.evolution_contact_rate_limits (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    remote_jid text NOT NULL,
    message_count integer DEFAULT 1,
