    is_rate_limited boolean DEFAULT false,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now()
);


--
-- Name: evolution_conversations_comercial_01; Type: TABLE; Schema: evo; Owner: -
--

CREATE TABLE evo.evolution_conversations_comercial_01 (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    contact_id uuid,
    remote_jid character varying(50) NOT NULL,
    status character varying(30) DEFAULT 'aberta'::character varying,
    assigned_to character varying(100),
    department character varying(50),
    subject character varying(255),
    priority character varying(20) DEFAULT 'normal'::character varying,
    labels text[],
    message_count integer DEFAULT 0,
    first_message_at timestamp with time zone,
    last_message_at timestamp with time zone,
    last_inbound_at timestamp with time zone,
    last_outbound_at timestamp with time zone,
    first_response_at timestamp with time zone,
    first_response_seconds integer,
    resolution_at timestamp with time zone,
    resolution_seconds integer,
    is_bot_active boolean DEFAULT false,
    bot_session_id character varying(100),
    satisfaction_score integer,
    satisfaction_comment text,
    instance_name character varying(100) DEFAULT 'wpp2'::character varying NOT NULL,
    metadata jsonb,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    last_message_content text,
    last_message_type text,
    unread_count integer DEFAULT 0,
    CONSTRAINT evolution_conversations_priority_check CHECK (((priority IS NULL) OR ((priority)::text = ANY ((ARRAY['low'::character varying, 'normal'::character varying, 'high'::character varying, 'urgent'::character varying])::text[])))),
    CONSTRAINT evolution_conversations_status_check CHECK (((status IS NULL) OR ((status)::text = ANY ((ARRAY['aberta'::character varying, 'arquivada'::character varying])::text[]))))
);


