    cycles_since_last integer,
    details jsonb DEFAULT '{}'::jsonb,
    CONSTRAINT chk_heartbeat_not_far_future CHECK ((heartbeat_at <= (now() + '00:05:00'::interval)))
)
WITH (autovacuum_vacuum_scale_factor='0', autovacuum_vacuum_threshold='5', autovacuum_analyze_scale_factor='0', autovacuum_analyze_threshold='5');


--
-- Name: TABLE evolution_guardian_heartbeat; Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON TABLE evo.evolution_guardian_heartbeat IS 'Heartbeats do guardian bridge (Supabase←Evolution DB via dblink).
Constraints: UNIQUE(service_name,heartbeat_at), CHECK(heartbeat_at<=now()+5min).
pg_cron: guardian-heartbeat-sync (2-59/5 * * * *).
Adicionado ON CONFLICT DO NOTHING em fn_sync_guardian_heartbeat para evitar duplicatas.
Histórico: 28 duplicatas removidas, unique_pct 54%→100% em sessão 5 (10/07/2026).';


