--
-- Name: TABLE evolution_health_logs; Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON TABLE evo.evolution_health_logs IS 'Append-only health check log written by Hermes monitoring agent every 15 min. Partition by time may be warranted if row count exceeds 500K.';


