    instance_name character varying(100) NOT NULL,
    push_name text,
    media_type text,
    raw_data jsonb,
    deleted_at timestamp with time zone,
    edited_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now(),
    media_meta jsonb,
    audio_meme_id uuid,
    sticker_id uuid,
    link_preview jsonb,
    is_read boolean DEFAULT false NOT NULL,
    reply_to_id uuid,
    media_bucket text,
    media_path text,
    media_sha256 text,
    media_status text DEFAULT 'unknown'::text,
    transcription_status text,
    transcription text,
    error_code text,
    error_reason text,
    retry_attempt integer,
    retry_total integer,
    CONSTRAINT evolution_messages_direction_check CHECK (((direction IS NULL) OR ((direction)::text = ANY ((ARRAY['inbound'::character varying, 'outbound'::character varying])::text[])))),
    CONSTRAINT evolution_messages_status_check CHECK (((status IS NULL) OR ((status)::text = ANY ((ARRAY['received'::character varying, 'sent'::character varying, 'delivered'::character varying, 'read'::character varying, 'deleted'::character varying, 'pending'::character varying, 'played'::character varying, 'failed'::character varying])::text[]))))
)
WITH (autovacuum_enabled='true', autovacuum_vacuum_insert_scale_factor='0.01', autovacuum_vacuum_cost_limit='4000', autovacuum_vacuum_cost_delay='1', autovacuum_vacuum_scale_factor='0.05', autovacuum_vacuum_threshold='1000', autovacuum_analyze_scale_factor='0.05', autovacuum_analyze_threshold='500');

