--
-- Name: mv_daily_metrics; Type: MATERIALIZED VIEW; Schema: evo; Owner: -
--

CREATE MATERIALIZED VIEW evo.mv_daily_metrics AS
 SELECT (date_trunc('day'::text, em.created_at))::date AS day,
    em.instance_name,
    count(*) AS total_messages,
    count(*) FILTER (WHERE ((em.direction)::text = 'inbound'::text)) AS inbound,
    count(*) FILTER (WHERE ((em.direction)::text = 'outbound'::text)) AS outbound,
    count(*) FILTER (WHERE ((em.message_type)::text = 'sticker'::text)) AS stickers,
    count(*) FILTER (WHERE ((em.message_type)::text = 'image'::text)) AS images,
    count(*) FILTER (WHERE ((em.message_type)::text = ANY ((ARRAY['audio'::character varying, 'ptt'::character varying])::text[]))) AS audios,
    count(*) FILTER (WHERE ((em.message_type)::text = 'video'::text)) AS videos,
    count(*) FILTER (WHERE ((em.message_type)::text = 'document'::text)) AS documents,
    count(DISTINCT em.remote_jid) AS unique_contacts,
    count(DISTINCT em.conversation_id) AS unique_conversations
   FROM evo.evolution_messages em
  WHERE ((em.deleted_at IS NULL) AND (em.created_at >= (now() - '90 days'::interval)))
  GROUP BY ((date_trunc('day'::text, em.created_at))::date), em.instance_name
  ORDER BY ((date_trunc('day'::text, em.created_at))::date) DESC, em.instance_name
  WITH NO DATA;


