    CONSTRAINT vps_scenarios_id_check CHECK ((id ~ '^E[0-9]+-[0-9]+$'::text)),
    CONSTRAINT vps_scenarios_impact_check CHECK (((impact >= 1) AND (impact <= 5))),
    CONSTRAINT vps_scenarios_probability_check CHECK (((probability >= 1) AND (probability <= 5)))
);


