--
-- Name: mv_vps_category_breakdown; Type: MATERIALIZED VIEW; Schema: evo; Owner: -
--

CREATE MATERIALIZED VIEW evo.mv_vps_category_breakdown
WITH (autovacuum_vacuum_scale_factor='0.01', autovacuum_vacuum_threshold='2', autovacuum_analyze_scale_factor='0.01', autovacuum_vacuum_cost_delay='2') AS
 SELECT s.category,
    count(*) AS total,
    count(*) FILTER (WHERE (vs.status = 'done'::text)) AS done_count,
    count(*) FILTER (WHERE (vs.status = 'doing'::text)) AS doing_count,
    count(*) FILTER (WHERE s.is_blocker) AS blocker_count,
    (sum(s.risk_score))::integer AS total_risk,
    round(avg(s.risk_score), 1) AS avg_risk,
    round((((sum(
        CASE
            WHEN (vs.status = 'done'::text) THEN (s.risk_score)::integer
            ELSE 0
        END))::numeric / (NULLIF(sum(s.risk_score), 0))::numeric) * (100)::numeric), 1) AS coverage_pct,
    now() AS refreshed_at
   FROM (evo.vps_scenarios s
     JOIN evo.vps_scenario_status vs ON ((vs.scenario_id = s.id)))
  GROUP BY s.category
  ORDER BY (sum(s.risk_score)) DESC
  WITH NO DATA;


--
-- Name: vps_etapas; Type: TABLE; Schema: evo; Owner: -
--

CREATE TABLE evo.vps_etapas (
    id smallint NOT NULL,
    title text NOT NULL,
    severity text NOT NULL,
    color text NOT NULL,
    bg_color text NOT NULL,
    icon text NOT NULL,
    display_order smallint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT vps_etapas_id_check CHECK (((id >= 1) AND (id <= 20))),
    CONSTRAINT vps_etapas_severity_check CHECK ((severity = ANY (ARRAY['CRÍTICO'::text, 'ALTO'::text, 'MÉDIO'::text, 'BAIXO'::text])))
);


--
-- Name: TABLE vps_etapas; Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON TABLE evo.vps_etapas IS 'Etapas do plano VPS Evolution API — 10 fases sequenciais de recuperação';


--
-- Name: mv_vps_risk_dashboard; Type: MATERIALIZED VIEW; Schema: evo; Owner: -
--

CREATE MATERIALIZED VIEW evo.mv_vps_risk_dashboard
WITH (autovacuum_vacuum_scale_factor='0.01', autovacuum_vacuum_threshold='2', autovacuum_analyze_scale_factor='0.01', autovacuum_vacuum_cost_delay='2') AS
 SELECT e.id AS etapa_id,
    e.title AS etapa_title,
    e.severity,
    e.color,
    e.bg_color,
    e.icon,
    e.display_order,
    count(s.id) AS total_scenarios,
    count(*) FILTER (WHERE (vs.status = 'done'::text)) AS done_count,
    count(*) FILTER (WHERE (vs.status = 'doing'::text)) AS doing_count,
    count(*) FILTER (WHERE (vs.status = 'todo'::text)) AS todo_count,
    count(*) FILTER (WHERE s.is_blocker) AS blockers_total,
    count(*) FILTER (WHERE (s.is_blocker AND (vs.status <> 'done'::text))) AS blockers_open,
    (sum(s.risk_score))::integer AS total_risk,
    (sum(
        CASE
            WHEN (vs.status = 'done'::text) THEN (s.risk_score)::integer
            ELSE 0
        END))::integer AS done_risk,
    round((((sum(
        CASE
            WHEN (vs.status = 'done'::text) THEN (s.risk_score)::integer
            ELSE 0
        END))::numeric / (NULLIF(sum(s.risk_score), 0))::numeric) * (100)::numeric), 1) AS coverage_pct,
    max(s.risk_score) AS max_risk,
    round(avg(s.risk_score), 1) AS avg_risk,
    now() AS refreshed_at
   FROM ((evo.vps_etapas e
     JOIN evo.vps_scenarios s ON ((s.etapa_id = e.id)))
     JOIN evo.vps_scenario_status vs ON ((vs.scenario_id = s.id)))
  GROUP BY e.id, e.title, e.severity, e.color, e.bg_color, e.icon, e.display_order
  ORDER BY e.display_order
  WITH NO DATA;


--
-- Name: MATERIALIZED VIEW mv_vps_risk_dashboard; Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON MATERIALIZED VIEW evo.mv_vps_risk_dashboard IS 'Pre-computa metricas por etapa: totais, status breakdown, risco total/done, cobertura%. REFRESH CONCURRENTLY com index unico. Atualizar via fn_vps_refresh_dashboard().';


--
-- Name: ops_runbooks; Type: TABLE; Schema: evo; Owner: -
--

CREATE TABLE evo.ops_runbooks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    title text NOT NULL,
    category text NOT NULL,
    version text DEFAULT '1.0'::text NOT NULL,
    severity text DEFAULT 'P2'::text NOT NULL,
    summary text NOT NULL,
    symptoms jsonb,
    root_cause text,
    steps jsonb NOT NULL,
    prevention text,
    links jsonb,
    author text DEFAULT 'audit-ai-10-07-2026'::text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now()
);


--
-- Name: v_ack_loss_candidates; Type: VIEW; Schema: evo; Owner: -
--

CREATE VIEW evo.v_ack_loss_candidates WITH (security_invoker='true') AS
 SELECT d.id,
    d.event_type,
    d.instance_name,
    d.remote_jid,
    d.status,
    d.retry_count,
    d.error_message,
    d.created_at,
    d.queue_name,
        CASE
            WHEN ((d.error_message ~~* '%duplicate key%'::text) OR (d.error_message ~~* '%unique constraint%'::text) OR (d.error_message ~~* '%unique_violation%'::text)) THEN 'duplicate_write'::text
            WHEN ((d.error_message ~~* '%connection%timeout%'::text) OR (d.error_message ~~* '%query_timeout%'::text) OR (d.error_message ~~* '%statement timeout%'::text) OR (d.error_message ~~* '%connection refused%'::text) OR (d.error_message ~~* '%ECONNRESET%'::text) OR (d.error_message ~~* '%ETIMEDOUT%'::text)) THEN 'db_write_timeout'::text
            WHEN ((d.error_message ~~* '%supabase%'::text) OR (d.error_message ~~* '%postgre%'::text) OR (d.error_message ~~* '%23505%'::text) OR (d.error_message ~~* '%42P01%'::text)) THEN 'db_write_error'::text
            ELSE 'other_error'::text
        END AS failure_category,
    ((d.status = 'error'::text) AND (d.retry_count = 0)) AS likely_lost,
    ((d.retry_count >= d.max_retries) AND (d.status = 'error'::text)) AS retry_exhausted
   FROM evo.evolution_webhook_dlq d
  WHERE (d.event_type = ANY (ARRAY['messages.upsert'::text, 'messages.update'::text, 'messages.delete'::text, 'send.message'::text, 'message.ack'::text]))
  ORDER BY d.created_at DESC;


--
-- Name: VIEW v_ack_loss_candidates; Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON VIEW evo.v_ack_loss_candidates IS 'E8-06: DLQ entries for message events that failed after consumption from RabbitMQ. failure_category=db_write_timeout indicates highest ACK-before-persist risk. likely_lost=true means consumed+errored+never retried = at-most-once loss.';


--
-- Name: v_bootstrap_history; Type: VIEW; Schema: evo; Owner: -
--

CREATE VIEW evo.v_bootstrap_history WITH (security_invoker='true') AS
 SELECT evolution_bootstrap_log.id,
    evolution_bootstrap_log.instance_name,
    evolution_bootstrap_log.instance_id,
    evolution_bootstrap_log.triggered_by,
    (evolution_bootstrap_log.settings_applied ->> 'rejectCall'::text) AS reject_call,
    evolution_bootstrap_log.rabbitmq_events_count,
    evolution_bootstrap_log.status,
    evolution_bootstrap_log.notes,
    evolution_bootstrap_log.created_at
   FROM evo.evolution_bootstrap_log
  ORDER BY evolution_bootstrap_log.created_at DESC;


--
-- Name: v_dedup_failures; Type: VIEW; Schema: evo; Owner: -
--

CREATE VIEW evo.v_dedup_failures WITH (security_invoker='true') AS
 SELECT evolution_messages.message_id,
    count(*) AS duplicate_count,
    min(evolution_messages.created_at) AS first_seen,
    max(evolution_messages.created_at) AS last_seen,
    (max(evolution_messages.created_at) - min(evolution_messages.created_at)) AS time_spread,
    array_agg(DISTINCT evolution_messages.instance_name) AS instances,
    array_agg(DISTINCT evolution_messages.remote_jid) AS jids
   FROM evo.evolution_messages
  WHERE ((evolution_messages.message_id IS NOT NULL) AND (evolution_messages.created_at >= (now() - '24:00:00'::interval)))
  GROUP BY evolution_messages.message_id
 HAVING (count(*) > 1)
  ORDER BY (count(*)) DESC, (max(evolution_messages.created_at)) DESC;


--
-- Name: VIEW v_dedup_failures; Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON VIEW evo.v_dedup_failures IS 'E8-01: Duplicate message_id entries in evolution_messages (last 24h). Any row here means the consumer dedup Set missed this message_id.';


--
-- Name: v_pipeline_health; Type: VIEW; Schema: evo; Owner: -
--

CREATE VIEW evo.v_pipeline_health WITH (security_invoker='true') AS
 WITH ingest AS (
         SELECT count(*) FILTER (WHERE (m.created_at > (now() - '00:05:00'::interval))) AS msgs_5min,
            count(*) FILTER (WHERE (m.created_at > (now() - '01:00:00'::interval))) AS msgs_1h,
            max(m.created_at) AS last_ingest,
            (EXTRACT(epoch FROM (now() - max(m.created_at))))::integer AS lag_seconds
           FROM evo.evolution_messages m
        ), backfill AS (
         SELECT count(*) AS total_backfill_rows
           FROM evo.evolution_messages m
          WHERE (((m.raw_data ->> 'backfill'::text) = 'true'::text) AND (m.created_at > (now() - '24:00:00'::interval)))
        ), bootstrap AS (
         SELECT max(l.created_at) AS last_bootstrap,
            count(*) AS total_bootstraps
           FROM evo.evolution_bootstrap_log l
          WHERE (l.status = ANY (ARRAY['ok'::text, 'registered'::text]))
        )
 SELECT i.msgs_5min,
    i.msgs_1h,
    i.lag_seconds,
    i.last_ingest,
    b.total_backfill_rows AS backfill_24h,
    bo.last_bootstrap,
    bo.total_bootstraps,
        CASE
            WHEN (i.lag_seconds < 120) THEN 'HEALTHY'::text
            WHEN (i.lag_seconds < 600) THEN 'DEGRADED'::text
            ELSE 'CRITICAL'::text
        END AS pipeline_status,
        CASE
            WHEN (i.lag_seconds < 60) THEN 'HEALTHY'::text
            WHEN (i.lag_seconds < 300) THEN 'DEGRADED'::text
            ELSE 'CRITICAL'::text
        END AS strict_status,
        CASE
            WHEN (i.msgs_1h > 100) THEN 'high_traffic'::text
            WHEN (i.msgs_1h > 20) THEN 'normal_traffic'::text
            WHEN (i.msgs_1h > 0) THEN 'low_traffic'::text
            ELSE 'no_traffic'::text
        END AS traffic_level,
    now() AS checked_at,
        CASE
            WHEN ((EXTRACT(dow FROM (now() AT TIME ZONE 'America/Sao_Paulo'::text)) = ANY (ARRAY[(0)::numeric, (6)::numeric])) OR ((EXTRACT(hour FROM (now() AT TIME ZONE 'America/Sao_Paulo'::text)) < (8)::numeric) OR (EXTRACT(hour FROM (now() AT TIME ZONE 'America/Sao_Paulo'::text)) > (19)::numeric))) THEN
            CASE
                WHEN (i.lag_seconds < 600) THEN 'HEALTHY'::text
                WHEN (i.lag_seconds < 14400) THEN 'DEGRADED'::text
                ELSE 'CRITICAL'::text
            END
            ELSE
            CASE
                WHEN (i.lag_seconds < 120) THEN 'HEALTHY'::text
                WHEN (i.lag_seconds < 600) THEN 'DEGRADED'::text
                ELSE 'CRITICAL'::text
            END
        END AS business_hours_status,
    ((EXTRACT(dow FROM (now() AT TIME ZONE 'America/Sao_Paulo'::text)) <> ALL (ARRAY[(0)::numeric, (6)::numeric])) AND ((EXTRACT(hour FROM (now() AT TIME ZONE 'America/Sao_Paulo'::text)) >= (8)::numeric) AND (EXTRACT(hour FROM (now() AT TIME ZONE 'America/Sao_Paulo'::text)) <= (19)::numeric))) AS is_business_hours
   FROM ingest i,
    backfill b,
    bootstrap bo;


--
-- Name: VIEW v_pipeline_health; Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON VIEW evo.v_pipeline_health IS 'Fonte migrada 2026-07-11: _wpp2 → evolution_messages. Nota: lag alto fora do expediente é orgânico — o probe fn_pipeline_health_probe tem thresholds weekend-aware; esta view é a régua estrita intraday.';


--
-- Name: v_production_scorecard; Type: VIEW; Schema: evo; Owner: -
--

CREATE VIEW evo.v_production_scorecard WITH (security_invoker='true') AS
 SELECT 'wpp2'::text AS instance,
    ( SELECT v_pipeline_health.lag_seconds
           FROM evo.v_pipeline_health) AS ingest_lag_s,
    ( SELECT v_pipeline_health.pipeline_status
           FROM evo.v_pipeline_health) AS pipeline_status,
    ( SELECT v_pipeline_health.strict_status
           FROM evo.v_pipeline_health) AS strict_status,
    ( SELECT v_pipeline_health.traffic_level
           FROM evo.v_pipeline_health) AS traffic_level,
    ( SELECT v_pipeline_health.msgs_1h
           FROM evo.v_pipeline_health) AS msgs_last_hour,
    ( SELECT count(*) AS count
           FROM evo.evolution_messages m
          WHERE (m.deleted_at IS NULL)) AS total_messages,
    ( SELECT count(*) AS count
           FROM evo.evolution_contacts) AS total_contacts,
    ( SELECT count(*) AS count
           FROM evo.evolution_contacts c
          WHERE ((c.instance_name)::text = 'wpp2'::text)) AS wpp2_contacts,
    ( SELECT count(*) AS count
           FROM evo.evolution_conversations) AS total_conversations,
    ( SELECT count(*) AS count
           FROM evo.evolution_alerts a
          WHERE (a.resolved_at IS NULL)) AS open_alerts,
    ( SELECT count(*) AS count
           FROM evo.evolution_bootstrap_log l
          WHERE ((l.status = 'registered'::text) AND (l.created_at > (now() - '24:00:00'::interval)))) AS bootstrap_needed_24h,
    now() AS generated_at;


--
-- Name: VIEW v_production_scorecard; Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON VIEW evo.v_production_scorecard IS 'Fontes migradas 2026-07-11: evolution_messages_wpp2→evolution_messages · evolution_conversations_wpp2→evolution_conversations (consolidadas Lovable).';


--
-- Name: _consumer_dlq; Type: TABLE; Schema: zapp; Owner: -
--

CREATE TABLE zapp._consumer_dlq (
    id bigint NOT NULL,
    routing_key text NOT NULL,
    event_type text,
    instance text,
    payload jsonb,
    payload_hash text NOT NULL,
    attempts integer DEFAULT 1,
    last_error text,
    last_status text,
    status text DEFAULT 'pending'::text NOT NULL,
    first_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    last_attempt_at timestamp with time zone DEFAULT now() NOT NULL,
    replayed_at timestamp with time zone,
    CONSTRAINT consumer_dlq_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'retrying'::text, 'replayed'::text, 'abandoned'::text, 'failed'::text])))
);


--
-- Name: v_health_unified; Type: VIEW; Schema: evo; Owner: -
--

CREATE VIEW evo.v_health_unified WITH (security_invoker='true') AS
 WITH pipe AS (
         SELECT v_pipeline_health.msgs_5min,
            v_pipeline_health.msgs_1h,
            v_pipeline_health.lag_seconds,
            v_pipeline_health.last_ingest,
            v_pipeline_health.pipeline_status,
            v_pipeline_health.strict_status,
            v_pipeline_health.traffic_level,
            v_pipeline_health.business_hours_status
           FROM evo.v_pipeline_health
        ), mirror AS (
         SELECT (x.j ->> 'v2_status'::text) AS v2_status,
            ((x.j ->> 'v2_score'::text))::integer AS v2_score,
            ((x.j ->> 'v2_hours_dead'::text))::numeric AS v2_hours_dead,
            ((x.j ->> 'v2_last_event'::text))::timestamp with time zone AS v2_last_event,
            ((x.j ->> 'v2_total_rows'::text))::bigint AS v2_total_rows,
            ((x.j ->> 'v2_last_7d'::text))::bigint AS v2_last_7d,
            ((x.j ->> 'v2_last_24h'::text))::bigint AS v2_last_24h,
            ((x.j ->> 'v2_pending'::text))::bigint AS v2_pending,
            ((x.j ->> 'v2_processed_1h'::text))::bigint AS v2_processed_1h,
            ((x.j ->> 'audit_log_last'::text))::timestamp with time zone AS audit_log_last,
            ((x.j ->> 'audit_log_1h'::text))::bigint AS audit_log_1h,
            ((x.j ->> 'audit_healthy'::text))::boolean AS audit_healthy,
            ((x.j ->> 'divergence'::text))::boolean AS mirror_divergence,
            ((x.j ->> 'infra_fix_needed'::text))::boolean AS infra_fix_needed
           FROM ( SELECT evo.fn_v2_mirror_health() AS j) x
        ), hl AS (
         SELECT evolution_pipeline_health_log.checked_at AS health_log_at,
            (evolution_pipeline_health_log.pipeline_status)::text AS health_log_status,
            evolution_pipeline_health_log.gap_inbound_min,
            evolution_pipeline_health_log.webhook_events_1h,
            evolution_pipeline_health_log.probe_status,
            evolution_pipeline_health_log.probe_latency_ms,
            evolution_pipeline_health_log.notes
           FROM evo.evolution_pipeline_health_log
          ORDER BY evolution_pipeline_health_log.checked_at DESC
         LIMIT 1
        ), cs AS (
         SELECT evolution_pipeline_health_log.checked_at AS consumer_stats_at,
            evolution_pipeline_health_log.consumer_ok_count,
            evolution_pipeline_health_log.consumer_filas
           FROM evo.evolution_pipeline_health_log
          WHERE (evolution_pipeline_health_log.consumer_ok_count IS NOT NULL)
          ORDER BY evolution_pipeline_health_log.checked_at DESC
         LIMIT 1
        ), cr AS (
         SELECT count(*) AS cron_runs_24h,
            count(*) FILTER (WHERE (job_run_details.status = 'succeeded'::text)) AS cron_succeeded_24h,
            count(*) FILTER (WHERE (job_run_details.status = 'failed'::text)) AS cron_failed_24h,
            count(DISTINCT job_run_details.jobid) AS cron_jobs_24h,
            max(job_run_details.start_time) AS cron_last_run_at,
            COALESCE(jsonb_agg(DISTINCT jsonb_build_object('jobid', job_run_details.jobid, 'command', "left"(job_run_details.command, 80))) FILTER (WHERE (job_run_details.status = 'failed'::text)), '[]'::jsonb) AS cron_failed_jobs
           FROM cron.job_run_details
          WHERE (job_run_details.start_time > (now() - '24:00:00'::interval))
        ), ch AS (
         SELECT job_run_details.status AS consumer_halt_last_status
           FROM cron.job_run_details
          WHERE (job_run_details.jobid = 144)
          ORDER BY job_run_details.runid DESC
         LIMIT 1
        ), o401 AS (
         SELECT (0)::bigint AS http_401_hits_24h,
            NULL::bigint AS http_401_unique_ips,
            NULL::timestamp with time zone AS http_401_last_seen
        ), sc AS (
         SELECT v_production_scorecard.total_messages,
            v_production_scorecard.total_contacts,
            v_production_scorecard.total_conversations,
            v_production_scorecard.open_alerts,
            v_production_scorecard.bootstrap_needed_24h,
            v_production_scorecard.generated_at AS scorecard_at
           FROM evo.v_production_scorecard
        )
 SELECT now() AS checked_at,
    pipe.pipeline_status,
    pipe.strict_status,
    pipe.traffic_level,
    pipe.msgs_5min,
    pipe.msgs_1h,
    pipe.lag_seconds AS pipeline_lag_s,
    pipe.last_ingest AS last_ingest_at,
    pipe.business_hours_status,
    mirror.v2_status,
    mirror.v2_score,
    mirror.v2_hours_dead,
    mirror.v2_last_event AS v2_last_event_at,
    mirror.v2_total_rows,
    mirror.v2_last_7d,
    mirror.v2_last_24h,
    mirror.v2_pending,
    mirror.v2_processed_1h,
    mirror.audit_healthy,
    mirror.mirror_divergence,
    mirror.infra_fix_needed,
    ( SELECT count(*) AS count
           FROM evo.evolution_webhook_events_v2
          WHERE (evolution_webhook_events_v2.created_at > (now() - '24:00:00'::interval))) AS source_events_24h,
    ( SELECT count(*) AS count
           FROM evo.evolution_messages
          WHERE (evolution_messages.created_at > (now() - '24:00:00'::interval))) AS persisted_msgs_24h,
    hl.health_log_at,
    hl.health_log_status,
    hl.gap_inbound_min,
    hl.webhook_events_1h,
    hl.probe_status,
    hl.probe_latency_ms,
    cr.cron_runs_24h,
    cr.cron_succeeded_24h,
    cr.cron_failed_24h,
    cr.cron_jobs_24h,
    cr.cron_last_run_at,
    cr.cron_failed_jobs,
    cs.consumer_ok_count AS consumer_ok_count_last,
    cs.consumer_filas AS consumer_filas_last,
    cs.consumer_stats_at,
    ( SELECT count(*) AS count
           FROM zapp._consumer_dlq) AS consumer_dlq_rows,
    ( SELECT count(*) AS count
           FROM evo.evolution_api_consumers
          WHERE (evolution_api_consumers.status = 'active'::text)) AS api_consumers_active,
    ch.consumer_halt_last_status,
    o401.http_401_hits_24h,
    o401.http_401_unique_ips,
    o401.http_401_last_seen,
    sc.total_messages,
    sc.total_contacts,
    sc.total_conversations,
    sc.open_alerts,
    sc.bootstrap_needed_24h,
    sc.scorecard_at,
        CASE
            WHEN ((pipe.pipeline_status = 'CRITICAL'::text) OR (mirror.v2_status = ANY (ARRAY['critical'::text, 'dead'::text])) OR (cr.cron_failed_24h > 0) OR (hl.probe_status <> 'ok'::text)) THEN 'CRITICAL'::text
            WHEN ((pipe.pipeline_status = 'DEGRADED'::text) OR (mirror.v2_status = 'degraded'::text) OR (sc.open_alerts > 0) OR (( SELECT count(*) AS count
               FROM zapp._consumer_dlq) > 0)) THEN 'DEGRADED'::text
            ELSE 'HEALTHY'::text
        END AS overall_status
   FROM pipe,
    mirror,
    hl,
    cs,
    cr,
    ch,
    o401,
    sc;


--
-- Name: VIEW v_health_unified; Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON VIEW evo.v_health_unified IS 'Painel unico de saude (D-3 runbook-2 06/08)';


--
-- Name: v_incident_metrics_48h; Type: VIEW; Schema: evo; Owner: -
--

CREATE VIEW evo.v_incident_metrics_48h WITH (security_invoker='true') AS
 SELECT 'evolution_messages'::text AS metric,
    count(*) AS total,
    count(*) FILTER (WHERE (m.created_at > (now() - '01:00:00'::interval))) AS last_1h,
    min(m.created_at) AS first_seen,
    max(m.created_at) AS last_seen
   FROM evo.evolution_messages m
  WHERE (m.created_at > (now() - '48:00:00'::interval))
UNION ALL
 SELECT 'backfill_rows'::text AS metric,
    count(*) AS total,
    count(*) FILTER (WHERE (m.created_at > (now() - '01:00:00'::interval))) AS last_1h,
    min(m.created_at) AS first_seen,
    max(m.created_at) AS last_seen
   FROM evo.evolution_messages m
  WHERE (((m.raw_data ->> 'backfill'::text) = 'true'::text) AND (m.created_at > (now() - '48:00:00'::interval)))
UNION ALL
 SELECT 'bootstrap_events'::text AS metric,
    count(*) AS total,
    count(*) FILTER (WHERE (l.created_at > (now() - '01:00:00'::interval))) AS last_1h,
    min(l.created_at) AS first_seen,
    max(l.created_at) AS last_seen
   FROM evo.evolution_bootstrap_log l
  WHERE (l.created_at > (now() - '48:00:00'::interval));


--
-- Name: VIEW v_incident_metrics_48h; Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON VIEW evo.v_incident_metrics_48h IS 'Fonte migrada 2026-07-11: _wpp2 → evolution_messages (consolidada Lovable).';


--
-- Name: v_wpp2_uptime_24h; Type: VIEW; Schema: evo; Owner: -
--

CREATE VIEW evo.v_wpp2_uptime_24h WITH (security_invoker='true') AS
 WITH ws AS (
         SELECT (now() - '24:00:00'::interval) AS t
        ), hist AS (
         SELECT evolution_connection_history.created_at AS s,
            evolution_connection_history.state,
            lead(evolution_connection_history.created_at) OVER (ORDER BY evolution_connection_history.created_at) AS e
           FROM evo.evolution_connection_history
          WHERE ((evolution_connection_history.instance_name = 'wpp2'::text) AND (evolution_connection_history.created_at > ( SELECT ws.t
                   FROM ws)))
        ), first_state AS (
         SELECT COALESCE(( SELECT evolution_connection_history.state
                   FROM evo.evolution_connection_history
                  WHERE ((evolution_connection_history.instance_name = 'wpp2'::text) AND (evolution_connection_history.created_at <= ( SELECT ws.t
                           FROM ws)))
                  ORDER BY evolution_connection_history.created_at DESC
                 LIMIT 1), NULL::text) AS st
        ), has_hist AS (
         SELECT (EXISTS ( SELECT 1
                   FROM evo.evolution_connection_history
                  WHERE (evolution_connection_history.instance_name = 'wpp2'::text))) AS h
        ), spans AS (
         SELECT hist.s,
            hist.state,
            COALESCE(hist.e, now()) AS e,
            0 AS synth
           FROM hist
        UNION ALL
         SELECT ( SELECT ws.t
                   FROM ws) AS t,
            first_state.st,
            ( SELECT min(evolution_connection_history.created_at) AS min
                   FROM evo.evolution_connection_history
                  WHERE ((evolution_connection_history.instance_name = 'wpp2'::text) AND (evolution_connection_history.created_at > ( SELECT ws.t
                           FROM ws)))) AS min,
            1
           FROM first_state
          WHERE (first_state.st IS NOT NULL)
        )
 SELECT
        CASE
            WHEN ( SELECT has_hist.h
               FROM has_hist) THEN round(((100.0 * COALESCE(sum(
            CASE
                WHEN (spans.state = ANY (ARRAY['connected'::text, 'open'::text])) THEN EXTRACT(epoch FROM (spans.e - spans.s))
                ELSE (0)::numeric
            END), (0)::numeric)) / EXTRACT(epoch FROM '24:00:00'::interval)), 2)
            ELSE NULL::numeric
        END AS uptime_pct_24h,
        CASE
            WHEN ( SELECT has_hist.h
               FROM has_hist) THEN sum(
            CASE
                WHEN ((spans.state = ANY (ARRAY['connected'::text, 'open'::text])) AND (spans.synth = 0)) THEN 1
                ELSE 0
            END)
            ELSE NULL::bigint
        END AS connects_24h,
        CASE
            WHEN ( SELECT has_hist.h
               FROM has_hist) THEN sum(
            CASE
                WHEN (spans.state = ANY (ARRAY['logged_out'::text, 'disconnected'::text])) THEN 1
                ELSE 0
            END)
            ELSE NULL::bigint
        END AS disconnects_24h,
        CASE
            WHEN ( SELECT has_hist.h
               FROM has_hist) THEN max(
            CASE
                WHEN (spans.synth = 0) THEN spans.s
                ELSE NULL::timestamp with time zone
            END)
            ELSE NULL::timestamp with time zone
        END AS last_conn_event_at,
    now() AS checked_at
   FROM spans;


