--
-- Name: v_kpi_overview; Type: VIEW; Schema: evo; Owner: -
--

CREATE VIEW evo.v_kpi_overview WITH (security_invoker='true') AS
 WITH probe AS (
         SELECT evolution_pipeline_health_log.checked_at,
            evolution_pipeline_health_log.pipeline_status,
            evolution_pipeline_health_log.gap_inbound_min
           FROM evo.evolution_pipeline_health_log
          WHERE (evolution_pipeline_health_log.notes ~~ 'probe-15min%'::text)
          ORDER BY evolution_pipeline_health_log.checked_at DESC
         LIMIT 1
        ), reconcile AS (
         SELECT evolution_pipeline_health_log.checked_at,
            evolution_pipeline_health_log.notes
           FROM evo.evolution_pipeline_health_log
          WHERE (evolution_pipeline_health_log.notes ~~ 'reconcile-source-mirror%'::text)
          ORDER BY evolution_pipeline_health_log.checked_at DESC
         LIMIT 1
        ), msgs AS (
         SELECT count(*) FILTER (WHERE (evolution_messages.created_at >= (now() - '01:00:00'::interval))) AS msgs_1h,
            count(*) FILTER (WHERE (evolution_messages.created_at >= (now() - '24:00:00'::interval))) AS msgs_24h,
            max(evolution_messages.created_at) AS last_ingest
           FROM evo.evolution_messages
        ), audit AS (
         SELECT round(avg(webhook_audit_log.duration_ms) FILTER (WHERE (webhook_audit_log.duration_ms IS NOT NULL)), 1) AS avg_ms,
            round((percentile_cont((0.95)::double precision) WITHIN GROUP (ORDER BY ((webhook_audit_log.duration_ms)::double precision)))::numeric, 1) AS p95_ms,
            count(*) AS n_24h
           FROM zapp.webhook_audit_log
          WHERE (webhook_audit_log.created_at >= (now() - '24:00:00'::interval))
        ), dlq AS (
         SELECT ( SELECT count(*) AS count
                   FROM evo.evolution_webhook_dlq
                  WHERE (evolution_webhook_dlq.status = 'pending'::text)) AS dlq_evo_pending,
            ( SELECT count(*) AS count
                   FROM zapp._consumer_dlq
                  WHERE (_consumer_dlq.status = ANY (ARRAY['pending'::text, 'error'::text, 'failed'::text]))) AS dlq_consumer_open
        ), dedup AS (
         SELECT count(*) AS failures_24h
           FROM evo.v_dedup_failures
        ), ipw AS (
         SELECT (0)::bigint AS hits_24h,
            (0)::bigint AS hits_401
        ), up AS (
         SELECT v_wpp2_uptime_24h.uptime_pct_24h,
            v_wpp2_uptime_24h.connects_24h,
            v_wpp2_uptime_24h.disconnects_24h,
            v_wpp2_uptime_24h.last_conn_event_at,
            v_wpp2_uptime_24h.checked_at
           FROM evo.v_wpp2_uptime_24h
        )
 SELECT now() AS checked_at,
    p.gap_inbound_min AS gap_sync_min,
    p.pipeline_status AS gap_sync_status,
    p.checked_at AS gap_sync_checked_at,
        CASE
            WHEN (r.notes ~ 'msg=[0-9.]+%'::text) THEN ((regexp_match(r.notes, 'msg=([0-9.]+)%'::text))[1])::numeric
            ELSE NULL::numeric
        END AS mirror_msg_coverage_pct,
    r.checked_at AS mirror_coverage_checked_at,
    m.last_ingest AS last_ingest_at,
    m.msgs_1h,
    m.msgs_24h,
    round(((m.msgs_24h)::numeric / 24.0), 1) AS msgs_per_hour_avg_24h,
    d.failures_24h AS dedup_failures_24h,
    ( SELECT count(*) AS count
           FROM zapp.webhook_event_dedup) AS dedup_tracked_rows,
    a.avg_ms AS webhook_latency_avg_ms_24h,
    a.p95_ms AS webhook_latency_p95_ms_24h,
    a.n_24h AS webhook_events_24h,
        CASE
            WHEN (ipw.hits_24h > 0) THEN round(((100.0 * (ipw.hits_401)::numeric) / (ipw.hits_24h)::numeric), 2)
            ELSE NULL::numeric
        END AS pct_401_24h,
    ipw.hits_24h AS ipwatch_hits_24h,
    q.dlq_evo_pending,
    q.dlq_consumer_open,
    (q.dlq_evo_pending + q.dlq_consumer_open) AS dlq_total_open,
    NULL::numeric AS rabbitmq_backlog_messages,
    NULL::integer AS consumer_drop_total,
    'FONTES EXTERNAS: rabbitmq_backlog_messages -> rabbitmqctl list_queues (container rabbitmq) ou API :15672; consumer_drop_total -> logs evolution-rabbit-consumer [STATS] drop=N; pct_401_24h -> tabela evolution_ip_watch REMOVIDA em 2026-08-06 (fantasma, 0 linhas): usar access log Traefik (grep DownstreamStatus=401). wpp2_uptime_pct_24h -> evo.evolution_connection_history (spans connected/open, AG-EX-19).'::text AS notas,
    up.uptime_pct_24h AS wpp2_uptime_pct_24h,
    up.connects_24h AS wpp2_connects_24h,
    up.disconnects_24h AS wpp2_disconnects_24h,
    up.last_conn_event_at AS wpp2_last_conn_event_at
   FROM (((((((probe p
     CROSS JOIN reconcile r)
     CROSS JOIN msgs m)
     CROSS JOIN audit a)
     CROSS JOIN dlq q)
     CROSS JOIN dedup d)
     CROSS JOIN ipw ipw)
     CROSS JOIN up);


--
-- Name: VIEW v_kpi_overview; Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON VIEW evo.v_kpi_overview IS 'D-9: Painel de KPIs/SLAs do ecossistema Evolution. Fontes: gap_sync=evolution_pipeline_health_log (probe-15min), mirror_msg_coverage_pct=linha reconcile-source-mirror (notes msg=%), msgs=evolution_messages (wpp2 congelado), latencia=zapp.webhook_audit_log.duration_ms, dedup_failures=evo.v_dedup_failures, pct_401=evo.evolution_ip_watch (vazia - usar Traefik), dlq=evo.evolution_webhook_dlq + zapp._consumer_dlq, backlog/drop=externos. security_invoker=true.';


--
-- Name: v_logpatch_health; Type: VIEW; Schema: evo; Owner: -
--

CREATE VIEW evo.v_logpatch_health WITH (security_invoker='on') AS
 SELECT evolution_logpatch_audit.id,
    evolution_logpatch_audit.instance_name,
    evolution_logpatch_audit.patch_mode,
    evolution_logpatch_audit.booted_at,
    evolution_logpatch_audit.evolution_version,
    evolution_logpatch_audit.image_digest,
    evolution_logpatch_audit.logpatch_status,
    evolution_logpatch_audit.logpatch_detail,
        CASE
            WHEN (evolution_logpatch_audit.patch_mode = 'build-time'::text) THEN (evolution_logpatch_audit.logpatch_status = 'ok'::text)
            WHEN (evolution_logpatch_audit.patch_mode = 'runtime'::text) THEN (evolution_logpatch_audit.t1_ok AND evolution_logpatch_audit.t2_ok AND evolution_logpatch_audit.t3_ok AND evolution_logpatch_audit.t4_ok AND evolution_logpatch_audit.t5_ok AND (evolution_logpatch_audit.logpatch_status = 'ok'::text))
            ELSE false
        END AS is_healthy,
        CASE
            WHEN (evolution_logpatch_audit.patch_mode = 'build-time'::text) THEN 'N/A (build-time mode — Dockerfile VERIFY garante patches)'::text
            WHEN (evolution_logpatch_audit.t1_ok AND evolution_logpatch_audit.t2_ok AND evolution_logpatch_audit.t3_ok AND evolution_logpatch_audit.t4_ok AND evolution_logpatch_audit.t5_ok) THEN 'Todos os 5 patches ok'::text
            ELSE format('Patches falhos: %s'::text, string_agg(patches.patch_name, ', '::text) FILTER (WHERE (NOT patches.patch_ok)))
        END AS patch_summary
   FROM (evo.evolution_logpatch_audit
     CROSS JOIN LATERAL ( VALUES ('T1'::text,evolution_logpatch_audit.t1_ok), ('T2'::text,evolution_logpatch_audit.t2_ok), ('T3'::text,evolution_logpatch_audit.t3_ok), ('T4'::text,evolution_logpatch_audit.t4_ok), ('T5'::text,evolution_logpatch_audit.t5_ok)) patches(patch_name, patch_ok))
  GROUP BY evolution_logpatch_audit.id, evolution_logpatch_audit.instance_name, evolution_logpatch_audit.patch_mode, evolution_logpatch_audit.booted_at, evolution_logpatch_audit.evolution_version, evolution_logpatch_audit.image_digest, evolution_logpatch_audit.logpatch_status, evolution_logpatch_audit.logpatch_detail, evolution_logpatch_audit.t1_ok, evolution_logpatch_audit.t2_ok, evolution_logpatch_audit.t3_ok, evolution_logpatch_audit.t4_ok, evolution_logpatch_audit.t5_ok;


--
-- Name: VIEW v_logpatch_health; Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON VIEW evo.v_logpatch_health IS 'View de saúde dos boots com interpretação correta de patch_mode. Em build-time, t1_ok–t5_ok são N/A e is_healthy baseia-se apenas em logpatch_status=ok. security_invoker=on: permissões do caller, sem escalada.';


