--
-- Name: v_security_audit; Type: VIEW; Schema: evo; Owner: -
--

CREATE VIEW evo.v_security_audit WITH (security_invoker='true') AS
 WITH fns AS (
         SELECT 'FUNCTION'::text AS object_type,
            pg_proc.proname AS name,
                CASE pg_proc.prokind
                    WHEN 'f'::"char" THEN 'function'::text
                    WHEN 'p'::"char" THEN 'procedure'::text
                    ELSE 'trigger'::text
                END AS subtype,
            true AS security_definer,
            (NOT has_function_privilege('anon'::name, pg_proc.oid, 'EXECUTE'::text)) AS anon_blocked,
            NULL::boolean AS rls_enabled,
            NULL::bigint AS policy_count,
                CASE
                    WHEN has_function_privilege('anon'::name, pg_proc.oid, 'EXECUTE'::text) THEN '⚠ EXPOSTO a anon'::text
                    ELSE '✓ bloqueado'::text
                END AS status
           FROM pg_proc
          WHERE ((pg_proc.pronamespace = ('evo'::regnamespace)::oid) AND (pg_proc.prosecdef = true))
        ), tbls AS (
         SELECT 'TABLE'::text AS object_type,
            c.relname AS name,
            'table'::text AS subtype,
            NULL::boolean AS security_definer,
            (NOT (has_table_privilege('anon'::name, c.oid, 'SELECT'::text) OR has_table_privilege('anon'::name, c.oid, 'INSERT'::text))) AS anon_blocked,
            c.relrowsecurity AS rls_enabled,
            count(p.oid) AS policy_count,
                CASE
                    WHEN (NOT c.relrowsecurity) THEN '⚠ SEM RLS'::text
                    WHEN (has_table_privilege('anon'::name, c.oid, 'SELECT'::text) OR has_table_privilege('anon'::name, c.oid, 'INSERT'::text)) THEN '⚠ anon tem acesso'::text
                    WHEN (count(p.oid) = 0) THEN '✓ deny-all'::text
                    ELSE '✓ policies definidas'::text
                END AS status
           FROM ((pg_class c
             JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
             LEFT JOIN pg_policy p ON ((p.polrelid = c.oid)))
          WHERE ((n.nspname = 'evo'::name) AND (c.relkind = 'r'::"char"))
          GROUP BY c.relname, c.relrowsecurity, c.oid
        )
 SELECT fns.object_type,
    fns.name,
    fns.subtype,
    fns.security_definer,
    fns.anon_blocked,
    fns.rls_enabled,
    fns.policy_count,
    fns.status
   FROM fns
UNION ALL
 SELECT tbls.object_type,
    tbls.name,
    tbls.subtype,
    tbls.security_definer,
    tbls.anon_blocked,
    tbls.rls_enabled,
    tbls.policy_count,
    tbls.status
   FROM tbls;


--
-- Name: VIEW v_security_audit; Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON VIEW evo.v_security_audit IS 'Auditoria de segurança live do schema evo.
Filtre por status LIKE ''%⚠%'' para ver anomalias.
Criada: 10/07/2026 após descoberta de 18 funções expostas para anon (sessão 7 H02).
Executar após qualquer CREATE FUNCTION ou CREATE TABLE no schema evo.';


--
-- Name: v_spurious_close_events; Type: VIEW; Schema: evo; Owner: -
--

CREATE VIEW evo.v_spurious_close_events WITH (security_invoker='true') AS
 WITH disconnects AS (
         SELECT evolution_connection_history.instance_name,
            evolution_connection_history.created_at AS disconnected_at,
            lead(evolution_connection_history.state) OVER w AS next_state,
            lead(evolution_connection_history.created_at) OVER w AS next_state_at
           FROM evo.evolution_connection_history
          WHERE ((evolution_connection_history.state = 'disconnected'::text) AND (evolution_connection_history.created_at >= (now() - '24:00:00'::interval)))
          WINDOW w AS (PARTITION BY evolution_connection_history.instance_name ORDER BY evolution_connection_history.created_at)
        )
 SELECT disconnects.instance_name,
    disconnects.disconnected_at,
    disconnects.next_state,
    disconnects.next_state_at,
    (EXTRACT(epoch FROM (disconnects.next_state_at - disconnects.disconnected_at)))::integer AS reconnect_seconds,
    ((disconnects.next_state = ANY (ARRAY['connecting'::text, 'connected'::text])) AND ((disconnects.next_state_at - disconnects.disconnected_at) <= '00:00:30'::interval)) AS is_spurious
   FROM disconnects
  WHERE (disconnects.next_state IS NOT NULL)
  ORDER BY disconnects.disconnected_at DESC;


--
-- Name: VIEW v_spurious_close_events; Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON VIEW evo.v_spurious_close_events IS 'E1-12: Disconnection events from evolution_connection_history (last 24h) classified as spurious (Baileys auto-reconnected within 30s) vs real. is_spurious=true events are the ones the n8n consumer should filter out.';


--
-- Name: v_unused_index_candidates; Type: VIEW; Schema: evo; Owner: -
--

CREATE VIEW evo.v_unused_index_candidates WITH (security_invoker='true') AS
 SELECT a.schemaname,
    a.tablename,
    a.indexname,
    a.index_size_bytes,
    pg_size_pretty(a.index_size_bytes) AS index_size_pretty,
    a.idx_scan,
    a.index_type,
    a.is_unique,
    a.is_primary,
    a.recommendation,
    a.captured_at,
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM pg_indexes pi
              WHERE ((pi.schemaname = a.schemaname) AND (pi.indexname = a.indexname)))) THEN 'EXISTS'::text
            ELSE 'DROPPED'::text
        END AS current_state
   FROM evo.idx_usage_audit a
  WHERE ((a.captured_at = ( SELECT max(b.captured_at) AS max
           FROM evo.idx_usage_audit b)) AND (a.recommendation = 'CANDIDATE_DROP'::text) AND (a.idx_scan = 0))
  ORDER BY a.index_size_bytes DESC;


--
-- Name: VIEW v_unused_index_candidates; Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON VIEW evo.v_unused_index_candidates IS 'Candidatos a DROP de indexes: idx_scan=0 na captura mais recente. Recriar 2026-07-10. Validar antes de dropar.';


--
-- Name: vps_diagnostic_runs; Type: TABLE; Schema: evo; Owner: -
--

CREATE TABLE evo.vps_diagnostic_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    scenario_id text NOT NULL,
    ran_at timestamp with time zone DEFAULT now() NOT NULL,
    query_executed text NOT NULL,
    result_summary text,
    result_data jsonb,
    is_confirmed boolean,
    severity_actual text,
    CONSTRAINT vps_diagnostic_runs_severity_actual_check CHECK ((severity_actual = ANY (ARRAY['CRÍTICO'::text, 'ALTO'::text, 'MÉDIO'::text, 'BAIXO'::text, 'RESOLVED'::text, 'N/A'::text])))
);


--
-- Name: TABLE vps_diagnostic_runs; Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON TABLE evo.vps_diagnostic_runs IS 'Histórico de validações automáticas dos cenários contra o banco de produção';


--
-- Name: v_vps_go_live_checklist; Type: VIEW; Schema: evo; Owner: -
--

CREATE VIEW evo.v_vps_go_live_checklist WITH (security_invoker='true') AS
 SELECT s.id,
    s.etapa_id,
    e.title AS etapa_title,
    e.severity,
    s.title,
    s.risk_score,
    s.category,
    s.fix_action,
    s.linked_table,
    vs.status,
    vs.updated_at,
    vs.updated_by,
    vs.notes,
        CASE vs.status
            WHEN 'done'::text THEN 'PASSOU'::text
            WHEN 'doing'::text THEN 'EM ANDAMENTO'::text
            ELSE 'PENDENTE'::text
        END AS verdict,
    (vs.status = 'done'::text) AS passed,
    ( SELECT d.ran_at
           FROM evo.vps_diagnostic_runs d
          WHERE (d.scenario_id = s.id)
          ORDER BY d.ran_at DESC
         LIMIT 1) AS last_diagnostic_at,
    ( SELECT d.severity_actual
           FROM evo.vps_diagnostic_runs d
          WHERE (d.scenario_id = s.id)
          ORDER BY d.ran_at DESC
         LIMIT 1) AS diagnostic_severity
   FROM ((evo.vps_scenarios s
     JOIN evo.vps_etapas e ON ((e.id = s.etapa_id)))
     JOIN evo.vps_scenario_status vs ON ((vs.scenario_id = s.id)))
  WHERE s.is_blocker
  ORDER BY s.risk_score DESC, s.etapa_id;


--
-- Name: vps_comments; Type: TABLE; Schema: evo; Owner: -
--

CREATE TABLE evo.vps_comments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    scenario_id text NOT NULL,
    content text NOT NULL,
    author text DEFAULT 'user'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT vps_comments_content_check CHECK (((length(content) >= 1) AND (length(content) <= 2000)))
);


--
-- Name: TABLE vps_comments; Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON TABLE evo.vps_comments IS 'Anotações e comentários por cenário VPS — histórico de ações tomadas';


--
-- Name: v_vps_live_status; Type: VIEW; Schema: evo; Owner: -
--

CREATE VIEW evo.v_vps_live_status WITH (security_invoker='true') AS
 SELECT s.id,
    s.etapa_id,
    e.title AS etapa_title,
    e.severity,
    s.title,
    s.probability,
    s.impact,
    s.risk_score,
    s.category,
    s.is_blocker,
    s.fix_action,
    s.linked_table,
    vs.status,
    vs.updated_at AS status_updated_at,
    vs.updated_by,
    vs.notes AS status_notes,
    ( SELECT count(*) AS count
           FROM evo.vps_comments c
          WHERE (c.scenario_id = s.id)) AS comment_count,
    ( SELECT d.ran_at
           FROM evo.vps_diagnostic_runs d
          WHERE (d.scenario_id = s.id)
          ORDER BY d.ran_at DESC
         LIMIT 1) AS last_diagnostic_at,
    ( SELECT d.severity_actual
           FROM evo.vps_diagnostic_runs d
          WHERE (d.scenario_id = s.id)
          ORDER BY d.ran_at DESC
         LIMIT 1) AS diagnostic_severity
   FROM ((evo.vps_scenarios s
     JOIN evo.vps_etapas e ON ((e.id = s.etapa_id)))
     JOIN evo.vps_scenario_status vs ON ((vs.scenario_id = s.id)));


--
-- Name: VIEW v_vps_live_status; Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON VIEW evo.v_vps_live_status IS 'View LIVE (nao materializada) com join completo de scenarios+status+etapas+diagnostico. Sempre reflete o estado atual. Use para leituras pontuais ou quando REFRESH nao foi executado.';


--
-- Name: vps_performance_snapshots; Type: TABLE; Schema: evo; Owner: -
--

CREATE TABLE evo.vps_performance_snapshots (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    captured_at timestamp with time zone DEFAULT now() NOT NULL,
    system_health_score numeric(5,2),
    system_grade text,
    vps_health_score numeric(5,2),
    scenarios_done integer,
    scenarios_doing integer,
    scenarios_todo integer,
    blockers_open integer,
    total_risk integer,
    done_risk integer,
    db_size_mb numeric(8,1),
    evo_size_mb numeric(8,1),
    alert_count_open integer,
    alert_count_unacknowledged integer,
    idle_connections integer,
    cron_failures_24h integer,
    notes text
)
WITH (autovacuum_vacuum_scale_factor='0', autovacuum_vacuum_threshold='2', autovacuum_analyze_scale_factor='0', autovacuum_analyze_threshold='2');


--
-- Name: TABLE vps_performance_snapshots; Type: COMMENT; Schema: evo; Owner: -
--

COMMENT ON TABLE evo.vps_performance_snapshots IS 'Snapshot periodico combinando fn_system_health_score (sistema) + fn_vps_health_score (VPS tracker). Use para trend analysis: melhora gradual dos cenarios, correlacao entre saude do sistema e resolucao dos cenarios.';


