-- Name: COLUMN vales.historico_desconto; Type: COMMENT; Schema: financeiro; Owner: -
--

COMMENT ON COLUMN financeiro.vales.historico_desconto IS '[{valor, data, responsavel, obs}]';


--
-- Name: vendas_parcelas; Type: TABLE; Schema: financeiro; Owner: -
--

CREATE TABLE financeiro.vendas_parcelas (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    venda_id uuid NOT NULL,
    tipo text NOT NULL,
    numero_parcela smallint,
    data_vencimento date,
    valor numeric(14,2) NOT NULL,
    status text DEFAULT 'ABERTO'::text NOT NULL,
    data_pagamento date,
    forma_pagamento text,
    obs text,
    aba_origem text,
    ano_origem smallint,
    criado_em timestamp with time zone DEFAULT now() NOT NULL,
    atualizado_em timestamp with time zone DEFAULT now() NOT NULL,
    banco_id uuid,
    idboleto text,
    cnpj text,
    atualizado_por text,
    nf_numero text,
    CONSTRAINT vendas_parcelas_forma_pagamento_check CHECK (((forma_pagamento IS NULL) OR (forma_pagamento = ANY (ARRAY['BOLETO'::text, 'PIX'::text, 'TRANSFERENCIA'::text, 'DINHEIRO'::text, 'CARTAO'::text, 'DESCONTO'::text])))),
    CONSTRAINT vendas_parcelas_status_check CHECK ((status = ANY (ARRAY['ABERTO'::text, 'PAGO'::text, 'VENCIDA'::text, 'CANCELADA'::text]))),
    CONSTRAINT vendas_parcelas_tipo_check CHECK ((tipo = ANY (ARRAY['ENTRADA'::text, 'PARCELA'::text, 'FRETE'::text]))),
    CONSTRAINT vendas_parcelas_valor_check CHECK ((valor > (0)::numeric))
);


--
-- Name: COLUMN vendas_parcelas.forma_pagamento; Type: COMMENT; Schema: financeiro; Owner: -
--

COMMENT ON COLUMN financeiro.vendas_parcelas.forma_pagamento IS 'Forma de pagamento padronizada: BOLETO, PIX, TRANSFERENCIA, DINHEIRO, CARTAO. NULL quando não informado.';


--
-- Name: COLUMN vendas_parcelas.idboleto; Type: COMMENT; Schema: financeiro; Owner: -
--

COMMENT ON COLUMN financeiro.vendas_parcelas.idboleto IS 'ID do boleto no banco emissor (Sicoob: NF-sequencial, ex: 5034-1). Pra conciliação de recebimentos.';


--
-- Name: COLUMN vendas_parcelas.cnpj; Type: COMMENT; Schema: financeiro; Owner: -
--

COMMENT ON COLUMN financeiro.vendas_parcelas.cnpj IS 'CNPJ do cliente associado à parcela. Usado em Asaas pra conciliação automática de recebimentos.';


--
-- Name: COLUMN vendas_parcelas.atualizado_por; Type: COMMENT; Schema: financeiro; Owner: -
--

COMMENT ON COLUMN financeiro.vendas_parcelas.atualizado_por IS 'Nome do usuário do app financeiro que realizou a última alteração/baixa da parcela.';


--
-- Name: COLUMN vendas_parcelas.nf_numero; Type: COMMENT; Schema: financeiro; Owner: -
--

COMMENT ON COLUMN financeiro.vendas_parcelas.nf_numero IS 'Número da NF vinculada a esta parcela (referência à notas_fiscais.numero)';


--
-- Name: vendas_unificadas; Type: TABLE; Schema: financeiro; Owner: -
--

CREATE TABLE financeiro.vendas_unificadas (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    pedido_pai text NOT NULL,
    vendedor text,
    data_venda date,
    data_entrega date,
    mes_referencia smallint,
    ano_referencia smallint,
    mes_ano_referencia text,
    empresa text,
    razao_social text,
    cnpj text,
    cliente_contato text,
    cidade_estado text,
    valor_total numeric(14,2) DEFAULT 0 NOT NULL,
    valor_entrada numeric(14,2) DEFAULT 0 NOT NULL,
    valor_pago numeric(14,2) DEFAULT 0 NOT NULL,
    valor_restante numeric(14,2) GENERATED ALWAYS AS ((valor_total - valor_pago)) STORED,
    tipo_pagamento text,
    qtd_parcelas smallint DEFAULT 0 NOT NULL,
    boleto_emitido boolean DEFAULT false NOT NULL,
    situacao_pagamento text DEFAULT 'PENDENTE'::text NOT NULL,
    nf_venda text,
    nf_emitida_em timestamp with time zone,
    obs text,
    origem text DEFAULT 'MANUAL'::text NOT NULL,
    criado_em timestamp with time zone DEFAULT now() NOT NULL,
    atualizado_em timestamp with time zone DEFAULT now() NOT NULL,
    criado_por text,
    atualizado_por text,
    aba_origem_planilha text,
    grupo_unificacao_id uuid,
    unif_papel text,
    valor_total_original numeric,
    pedidos_unificados text[],
    CONSTRAINT chk_unif_papel CHECK (((unif_papel IS NULL) OR (unif_papel = ANY (ARRAY['LIDER'::text, 'MEMBRO'::text])))),
    CONSTRAINT vendas_unificadas_origem_check CHECK ((origem = ANY (ARRAY['PLANILHA'::text, 'BITRIX'::text, 'MANUAL'::text, 'API'::text, 'N8N'::text, 'MIGRACAO'::text, 'OPERACIONAL'::text]))),
    CONSTRAINT vendas_unificadas_situacao_pagamento_check CHECK ((situacao_pagamento = ANY (ARRAY['PENDENTE'::text, 'PAGANDO'::text, 'PAGO'::text, 'VENCIDO'::text, 'CANCELADO'::text])))
);


--
-- Name: COLUMN vendas_unificadas.aba_origem_planilha; Type: COMMENT; Schema: financeiro; Owner: -
--

COMMENT ON COLUMN financeiro.vendas_unificadas.aba_origem_planilha IS 'Nome da aba na planilha onde o vendedor lançou (ex: Vendas-Janeiro). É o critério "mês de controle do vendedor", diferente de mes_referencia que vem da data_venda. Pra dashboards bater com a planilha, filtrar por essa coluna.';


--
-- Name: COLUMN vendas_unificadas.grupo_unificacao_id; Type: COMMENT; Schema: financeiro; Owner: -
--

COMMENT ON COLUMN financeiro.vendas_unificadas.grupo_unificacao_id IS 'ID do grupo de unificacao; todos os pedidos do grupo compartilham. NULL = pedido normal.';


--
-- Name: COLUMN vendas_unificadas.unif_papel; Type: COMMENT; Schema: financeiro; Owner: -
--

COMMENT ON COLUMN financeiro.vendas_unificadas.unif_papel IS 'Papel no grupo: LIDER (carrega valor somado + parcelas) ou MEMBRO. NULL = nao unificado.';


--
-- Name: COLUMN vendas_unificadas.valor_total_original; Type: COMMENT; Schema: financeiro; Owner: -
--

COMMENT ON COLUMN financeiro.vendas_unificadas.valor_total_original IS 'Valor_total antes da unificacao (usado para desfazer).';


--
-- Name: COLUMN vendas_unificadas.pedidos_unificados; Type: COMMENT; Schema: financeiro; Owner: -
--

COMMENT ON COLUMN financeiro.vendas_unificadas.pedidos_unificados IS 'No LIDER: lista dos pedido_pai do grupo, para exibicao e busca.';


--
-- Name: vw_conciliacao_vendas; Type: VIEW; Schema: financeiro; Owner: -
--

CREATE VIEW financeiro.vw_conciliacao_vendas WITH (security_invoker='on') AS
 WITH oc_agg AS (
         SELECT regexp_replace(ordens_compra.pedido, '-(\d+)$'::text, ''::text) AS pedido_pai,
            ordens_compra.ano AS ano_oc,
            ordens_compra.mes AS mes_oc,
            max(ordens_compra.vendedor) AS vendedor_oc,
            max(ordens_compra.empresa) AS empresa_oc,
            count(*) AS qtd_itens_oc,
            sum((ordens_compra.qtd_pedido * ordens_compra.valor_vendido_unid)) AS valor_oc
           FROM vendas.ordens_compra
          WHERE (ordens_compra.excluido_em IS NULL)
          GROUP BY (regexp_replace(ordens_compra.pedido, '-(\d+)$'::text, ''::text)), ordens_compra.ano, ordens_compra.mes
        )
 SELECT COALESCE(v.pedido_pai, o.pedido_pai) AS pedido_pai,
    COALESCE((v.ano_referencia)::integer, o.ano_oc) AS ano,
    COALESCE((v.mes_referencia)::integer, o.mes_oc) AS mes,
    COALESCE(v.vendedor, o.vendedor_oc) AS vendedor,
    COALESCE(v.empresa, o.empresa_oc) AS empresa,
    v.valor_total AS valor_planilha,
    o.valor_oc AS valor_operacional,
    round((COALESCE(o.valor_oc, (0)::numeric) - COALESCE(v.valor_total, (0)::numeric)), 2) AS diferenca,
    o.qtd_itens_oc,
    v.situacao_pagamento,
    v.nf_venda,
        CASE
            WHEN (v.pedido_pai IS NULL) THEN 'SO_NO_OPERACIONAL'::text
            WHEN (o.pedido_pai IS NULL) THEN 'SO_NA_PLANILHA'::text
            WHEN (abs((COALESCE(o.valor_oc, (0)::numeric) - COALESCE(v.valor_total, (0)::numeric))) < (1)::numeric) THEN 'OK'::text
            WHEN (abs((COALESCE(o.valor_oc, (0)::numeric) - COALESCE(v.valor_total, (0)::numeric))) < (100)::numeric) THEN 'DIVERGENCIA_BAIXA'::text
            ELSE 'DIVERGENCIA_ALTA'::text
        END AS status_conciliacao
   FROM (financeiro.vendas_unificadas v
     FULL JOIN oc_agg o ON ((o.pedido_pai = v.pedido_pai)))
  WHERE (COALESCE((v.ano_referencia)::integer, o.ano_oc) >= 2026);


--
-- Name: VIEW vw_conciliacao_vendas; Type: COMMENT; Schema: financeiro; Owner: -
--

COMMENT ON VIEW financeiro.vw_conciliacao_vendas IS 'Reconciliação automática entre vendas.ordens_compra (operacional) e financeiro.vendas_unificadas (planilha). 
Status: OK | DIVERGENCIA_BAIXA (<R$ 100) | DIVERGENCIA_ALTA (>=R$ 100) | SO_NO_OPERACIONAL | SO_NA_PLANILHA';


--
-- Name: vw_emprestimos; Type: VIEW; Schema: financeiro; Owner: -
--

CREATE VIEW financeiro.vw_emprestimos WITH (security_invoker='on') AS
 SELECT e.id,
    e.colaborador_id,
    e.valor_total,
    e.quantidade_parcelas,
    e.valor_parcela,
    e.parcelas_pagas,
    e.data_inicio,
    e.data_solicitacao,
    e.data_liquidacao,
    e.liquidado_por,
    e.status,
    e.observacao,
    e.desconto_tipo,
    e.prorrogacoes,
    e.aditivos,
    e.criado_em,
    e.tipo_emprestimo,
        CASE
            WHEN (e.parcelas_pagas = 0) THEN (0)::numeric
            ELSE round((((e.parcelas_pagas)::numeric * e.valor_parcela) + COALESCE(( SELECT sum(((v.value)::numeric - e.valor_parcela)) AS sum
               FROM jsonb_each_text(COALESCE(e.prorrogacoes, '{}'::jsonb)) v(key, value)
              WHERE ((v.key ~ '^pago_'::text) AND ((SUBSTRING(v.key FROM 6))::integer <= e.parcelas_pagas))), (0)::numeric)), 2)
        END AS valor_pago,
    round(((((e.quantidade_parcelas - e.parcelas_pagas))::numeric * e.valor_parcela) + COALESCE(( SELECT sum((v.value)::numeric) AS sum
           FROM jsonb_each_text(COALESCE(e.prorrogacoes, '{}'::jsonb)) v(key, value)
          WHERE ((v.key ~ '^va_'::text) AND ((SUBSTRING(v.key FROM 4))::integer > e.parcelas_pagas))), (0)::numeric)), 2) AS valor_pendente,
    c.nome AS nome_colaborador,
    c.cpf AS cpf_colaborador,
    c.cidade,
    c.chave_pix,
    c.departamento,
    c.cargo
   FROM (financeiro.emprestimos e
     JOIN financeiro.colaboradores c ON ((c.id = e.colaborador_id)));


--
-- Name: vw_parcelas_lista; Type: VIEW; Schema: financeiro; Owner: -
--

CREATE VIEW financeiro.vw_parcelas_lista WITH (security_invoker='on') AS
 SELECT vp.id AS parcela_id,
    vp.venda_id,
    vp.tipo,
    vp.numero_parcela,
    vp.valor,
    vp.data_vencimento,
    vp.data_pagamento,
    vp.forma_pagamento,
    vp.banco_id,
    vp.idboleto,
    vp.cnpj AS cnpj_parcela,
    vp.obs AS obs_parcela,
    vp.atualizado_por AS parcela_atualizado_por,
    vp.criado_em AS parcela_criado_em,
    vp.ano_origem,
        CASE
            WHEN ((vp.status = 'ABERTO'::text) AND (vp.data_vencimento < CURRENT_DATE)) THEN 'VENCIDA'::text
            ELSE vp.status
        END AS status_efetivo,
    vp.status AS status_bruto,
        CASE
            WHEN ((vp.status = ANY (ARRAY['ABERTO'::text, 'VENCIDA'::text])) AND (vp.data_vencimento IS NOT NULL)) THEN (CURRENT_DATE - vp.data_vencimento)
            ELSE NULL::integer
        END AS dias_atraso,
    (EXTRACT(year FROM vp.data_vencimento))::smallint AS venc_ano,
    (EXTRACT(month FROM vp.data_vencimento))::smallint AS venc_mes,
    vu.pedido_pai,
    vu.empresa,
    vu.razao_social,
    vu.cnpj AS cnpj_cliente,
    vu.vendedor,
    vu.data_venda,
    vu.valor_total AS venda_valor_total,
    vu.valor_pago AS venda_valor_pago,
    vu.valor_restante AS venda_valor_restante,
    vu.situacao_pagamento AS venda_situacao,
    vu.nf_venda,
    vu.ano_referencia AS venda_ano,
    vu.mes_referencia AS venda_mes,
    b.nome AS banco_nome,
    b.titular AS banco_titular
   FROM ((financeiro.vendas_parcelas vp
     JOIN financeiro.vendas_unificadas vu ON ((vu.id = vp.venda_id)))
     LEFT JOIN financeiro.bancos b ON ((b.id = vp.banco_id)));


--
-- Name: VIEW vw_parcelas_lista; Type: COMMENT; Schema: financeiro; Owner: -
--

COMMENT ON VIEW financeiro.vw_parcelas_lista IS 'View consolidada para a tela /parcelas. ano_origem = ano da VENDA (USAR no filtro de ano da tela). venc_mes/venc_ano = derivados do vencimento (informativos, usados pro filtro de mes).';


--
-- Name: vw_parcelas_vencidas; Type: VIEW; Schema: financeiro; Owner: -
--

CREATE VIEW financeiro.vw_parcelas_vencidas WITH (security_invoker='on') AS
 SELECT p.id AS parcela_id,
    p.venda_id,
    v.pedido_pai,
    v.vendedor,
    v.empresa,
    v.cliente_contato,
    p.tipo,
    p.numero_parcela,
    p.valor,
    p.data_vencimento,
    p.status,
    (CURRENT_DATE - p.data_vencimento) AS dias_vencida,
    v.ano_referencia,
    v.mes_referencia,
    v.nf_venda
   FROM (financeiro.vendas_parcelas p
     JOIN financeiro.vendas_unificadas v ON ((v.id = p.venda_id)))
  WHERE ((p.status = ANY (ARRAY['ABERTO'::text, 'VENCIDA'::text])) AND (p.data_vencimento < CURRENT_DATE) AND (v.situacao_pagamento <> 'CANCELADO'::text))
  ORDER BY p.data_vencimento;


--
-- Name: vw_pedidos_sem_nf; Type: VIEW; Schema: financeiro; Owner: -
--

CREATE VIEW financeiro.vw_pedidos_sem_nf WITH (security_invoker='on') AS
 SELECT v.id,
    v.pedido_pai,
    v.vendedor,
    v.data_venda,
    v.empresa,
    v.razao_social,
    v.cliente_contato,
    v.valor_total,
    v.situacao_pagamento,
    (CURRENT_DATE - v.data_venda) AS dias_sem_nf
   FROM financeiro.vendas_unificadas v
  WHERE ((v.nf_venda IS NULL) AND (v.data_venda IS NOT NULL) AND (v.situacao_pagamento <> 'CANCELADO'::text) AND ((CURRENT_DATE - v.data_venda) >= COALESCE(( SELECT (config.valor)::integer AS valor
           FROM financeiro.config
          WHERE (config.chave = 'dias_alerta_nf_pendente'::text)), 3)))
  ORDER BY v.data_venda;


--
-- Name: vw_pendentes_nf_venda; Type: VIEW; Schema: financeiro; Owner: -
--

CREATE VIEW financeiro.vw_pendentes_nf_venda WITH (security_invoker='on') AS
 SELECT v.pedido_pai,
    v.empresa,
    v.cliente_contato,
    v.vendedor,
    v.data_entrega,
    v.valor_total,
    v.situacao_pagamento,
    (CURRENT_DATE - v.data_entrega) AS dias_sem_nf,
    v.id AS venda_id
   FROM (financeiro.vendas_unificadas v
     LEFT JOIN financeiro.notas_fiscais nf ON (((nf.pedido_pai = v.pedido_pai) AND (nf.tipo_nota = 'VENDA'::text) AND (nf.status = ANY (ARRAY['EMITIDA'::text, 'PROCESSANDO'::text, 'PENDENTE'::text])))))
  WHERE ((v.data_entrega IS NOT NULL) AND (v.nf_venda IS NULL) AND (v.situacao_pagamento <> 'CANCELADO'::text) AND (nf.id IS NULL) AND ((CURRENT_DATE - v.data_entrega) >= 0))
  ORDER BY (CURRENT_DATE - v.data_entrega) DESC NULLS LAST;


--
-- Name: VIEW vw_pendentes_nf_venda; Type: COMMENT; Schema: financeiro; Owner: -
--

COMMENT ON VIEW financeiro.vw_pendentes_nf_venda IS 'Pedidos com data_entrega passada, sem NF Venda registrada, prontos pra emissão. Substitui a verificação do GAS verificarNotasPendentes.';


--
-- Name: vw_proximos_vencimentos; Type: VIEW; Schema: financeiro; Owner: -
--

CREATE VIEW financeiro.vw_proximos_vencimentos WITH (security_invoker='on') AS
 SELECT p.id AS parcela_id,
    p.venda_id,
    v.pedido_pai,
    v.vendedor,
    v.empresa,
    v.cliente_contato,
    p.tipo,
    p.numero_parcela,
    p.valor,
    p.data_vencimento,
    p.status,
    (p.data_vencimento - CURRENT_DATE) AS dias_para_vencer,
    v.ano_referencia,
    v.mes_referencia,
    v.nf_venda
   FROM (financeiro.vendas_parcelas p
     JOIN financeiro.vendas_unificadas v ON ((v.id = p.venda_id)))
  WHERE ((p.status = 'ABERTO'::text) AND (p.data_vencimento >= CURRENT_DATE) AND (p.data_vencimento <= (CURRENT_DATE + 30)) AND (v.situacao_pagamento <> 'CANCELADO'::text))
  ORDER BY p.data_vencimento;


--
-- Name: vw_resumo_mensal; Type: VIEW; Schema: financeiro; Owner: -
--

CREATE VIEW financeiro.vw_resumo_mensal WITH (security_invoker='on') AS
 SELECT vendas_unificadas.ano_referencia,
    vendas_unificadas.mes_referencia,
    (count(*))::integer AS qtd_pedidos,
    (sum(vendas_unificadas.valor_total))::numeric(15,2) AS faturado,
    (sum(vendas_unificadas.valor_pago))::numeric(15,2) AS recebido,
    ((sum(vendas_unificadas.valor_total) - sum(vendas_unificadas.valor_pago)))::numeric(15,2) AS a_receber,
    (count(*) FILTER (WHERE (vendas_unificadas.situacao_pagamento = 'PAGO'::text)))::integer AS pedidos_pagos,
    (count(*) FILTER (WHERE (vendas_unificadas.situacao_pagamento = 'PAGANDO'::text)))::integer AS pedidos_pagando,
    (count(*) FILTER (WHERE (vendas_unificadas.situacao_pagamento = 'PENDENTE'::text)))::integer AS pedidos_pendentes,
    (sum(vendas_unificadas.valor_pago) FILTER (WHERE (vendas_unificadas.situacao_pagamento = 'PAGO'::text)))::numeric(15,2) AS recebido_de_pagos,
    (sum(vendas_unificadas.valor_pago) FILTER (WHERE (vendas_unificadas.situacao_pagamento = 'PAGANDO'::text)))::numeric(15,2) AS recebido_de_pagando,
        CASE
            WHEN (sum(vendas_unificadas.valor_total) > (0)::numeric) THEN round(((sum(vendas_unificadas.valor_pago) / sum(vendas_unificadas.valor_total)) * (100)::numeric), 1)
            ELSE (0)::numeric
        END AS pct_recebido
   FROM financeiro.vendas_unificadas
  GROUP BY vendas_unificadas.ano_referencia, vendas_unificadas.mes_referencia
  ORDER BY vendas_unificadas.ano_referencia, vendas_unificadas.mes_referencia;


--
-- Name: VIEW vw_resumo_mensal; Type: COMMENT; Schema: financeiro; Owner: -
--

COMMENT ON VIEW financeiro.vw_resumo_mensal IS 'Agregado mensal direto de vendas_unificadas. Fonte de verdade: coluna valor_pago (mantida pela equipe). NÃO depende de vendas_parcelas. Bate com a planilha Total Pago.';


--
-- Name: vw_resumo_vales_mes; Type: VIEW; Schema: financeiro; Owner: -
--

CREATE VIEW financeiro.vw_resumo_vales_mes WITH (security_invoker='on') AS
 SELECT v.mes_referencia,
    c.id AS colaborador_id,
    c.nome AS nome_colaborador,
    c.cidade,
    count(*) AS quantidade_vales,
    sum(v.valor) AS total_vales
   FROM (financeiro.vales v
     JOIN financeiro.colaboradores c ON ((c.id = v.colaborador_id)))
  GROUP BY v.mes_referencia, c.id, c.nome, c.cidade
  ORDER BY v.mes_referencia DESC, c.nome;


--
-- Name: vw_resumo_vendedor; Type: VIEW; Schema: financeiro; Owner: -
--

CREATE VIEW financeiro.vw_resumo_vendedor WITH (security_invoker='on') AS
 SELECT vendas_unificadas.vendedor,
    vendas_unificadas.ano_referencia,
    (count(*))::integer AS qtd_pedidos,
    (sum(vendas_unificadas.valor_total))::numeric(15,2) AS faturado,
    (sum(vendas_unificadas.valor_pago))::numeric(15,2) AS recebido,
    ((sum(vendas_unificadas.valor_total) - sum(vendas_unificadas.valor_pago)))::numeric(15,2) AS a_receber,
    (avg(vendas_unificadas.valor_total))::numeric(15,2) AS ticket_medio,
    (count(*) FILTER (WHERE (vendas_unificadas.situacao_pagamento = 'PAGO'::text)))::integer AS pedidos_pagos,
    (count(*) FILTER (WHERE (vendas_unificadas.situacao_pagamento = 'PAGANDO'::text)))::integer AS pedidos_pagando,
    (count(*) FILTER (WHERE (vendas_unificadas.situacao_pagamento = 'PENDENTE'::text)))::integer AS pedidos_pendentes,
        CASE
            WHEN (sum(vendas_unificadas.valor_total) > (0)::numeric) THEN round(((sum(vendas_unificadas.valor_pago) / sum(vendas_unificadas.valor_total)) * (100)::numeric), 1)
            ELSE (0)::numeric
        END AS pct_recebido
   FROM financeiro.vendas_unificadas
  WHERE (vendas_unificadas.vendedor IS NOT NULL)
  GROUP BY vendas_unificadas.vendedor, vendas_unificadas.ano_referencia
  ORDER BY vendas_unificadas.ano_referencia DESC, (sum(vendas_unificadas.valor_total)) DESC;


--
-- Name: VIEW vw_resumo_vendedor; Type: COMMENT; Schema: financeiro; Owner: -
--

COMMENT ON VIEW financeiro.vw_resumo_vendedor IS 'Agregado por vendedor direto de vendas_unificadas. Usa valor_pago como fonte de verdade.';


--
-- Name: vw_vales; Type: VIEW; Schema: financeiro; Owner: -
--

CREATE VIEW financeiro.vw_vales WITH (security_invoker='on') AS
 SELECT v.id,
    v.colaborador_id,
    v.valor,
    v.data_envio,
    v.banco,
    v.mes_referencia,
    v.observacao,
    v.criado_em,
    v.criado_por,
    c.nome AS nome_colaborador,
    c.cpf AS cpf_colaborador,
    c.cidade,
