-- Name: architecture_changelog_id_seq; Type: SEQUENCE OWNED BY; Schema: monitoring; Owner: -
--

ALTER SEQUENCE monitoring.architecture_changelog_id_seq OWNED BY monitoring.architecture_changelog.id;


--
-- Name: v_architecture_score; Type: VIEW; Schema: monitoring; Owner: -
--

CREATE VIEW monitoring.v_architecture_score WITH (security_invoker='true') AS
 WITH checks AS (
         SELECT fn_migration_readiness_check.check_name,
            fn_migration_readiness_check.category,
            fn_migration_readiness_check.status,
            fn_migration_readiness_check.detail,
            fn_migration_readiness_check.blocking
           FROM monitoring.fn_migration_readiness_check() fn_migration_readiness_check(check_name, category, status, detail, blocking)
        ), counts AS (
         SELECT count(*) FILTER (WHERE (checks.status ~~ '✅%'::text)) AS ok,
            count(*) AS total
           FROM checks
        )
 SELECT c.ok,
    c.total,
    round((((c.ok)::numeric / (NULLIF(c.total, 0))::numeric) * (10)::numeric), 1) AS score_automatico,
    ( SELECT max(architecture_changelog.score_after) AS max
           FROM monitoring.architecture_changelog) AS score_changelog,
    now() AS avaliado_em
   FROM counts c;


--
-- Name: v_connection_stats; Type: VIEW; Schema: monitoring; Owner: -
--

CREATE VIEW monitoring.v_connection_stats WITH (security_invoker='true') AS
 SELECT date_trunc('minute'::text, now()) AS snapshot_at,
    count(*) FILTER (WHERE (pg_stat_activity.datname = 'postgres'::name)) AS total_connections,
    count(*) FILTER (WHERE ((pg_stat_activity.datname = 'postgres'::name) AND (pg_stat_activity.state = 'active'::text))) AS active,
    count(*) FILTER (WHERE ((pg_stat_activity.datname = 'postgres'::name) AND (pg_stat_activity.state = 'idle'::text))) AS idle,
    count(*) FILTER (WHERE ((pg_stat_activity.datname = 'postgres'::name) AND (pg_stat_activity.state = 'idle in transaction'::text))) AS idle_in_tx,
    count(*) FILTER (WHERE (pg_stat_activity.application_name ~~ '%mcp%'::text)) AS mcp_conns,
    count(DISTINCT pg_stat_activity.client_addr) FILTER (WHERE (pg_stat_activity.application_name ~~ '%mcp%'::text)) AS mcp_unique_ips,
    count(*) FILTER (WHERE (pg_stat_activity.application_name ~~ '%PostgREST%'::text)) AS pgrst_conns,
    count(*) FILTER (WHERE (pg_stat_activity.application_name ~~ '%realtime%'::text)) AS realtime_conns,
    count(*) FILTER (WHERE ((pg_stat_activity.application_name ~~ '%pg_cron%'::text) OR (pg_stat_activity.application_name = ''::text))) AS internal_conns,
    ( SELECT (pg_settings.setting)::integer AS setting
           FROM pg_settings
          WHERE (pg_settings.name = 'max_connections'::text)) AS max_connections,
    round(((100.0 * (count(*) FILTER (WHERE (pg_stat_activity.datname = 'postgres'::name)))::numeric) / (( SELECT (pg_settings.setting)::integer AS setting
           FROM pg_settings
          WHERE (pg_settings.name = 'max_connections'::text)))::numeric), 1) AS pct_used,
    count(*) FILTER (WHERE ((pg_stat_activity.state = 'active'::text) AND (pg_stat_activity.backend_start < (now() - '00:05:00'::interval)))) AS long_running_active,
    count(*) FILTER (WHERE ((pg_stat_activity.state = 'idle in transaction'::text) AND (pg_stat_activity.state_change < (now() - '00:01:00'::interval)))) AS stuck_in_tx
   FROM pg_stat_activity;


--
-- Name: VIEW v_connection_stats; Type: COMMENT; Schema: monitoring; Owner: -
--

COMMENT ON VIEW monitoring.v_connection_stats IS 'Snapshot instantaneo do estado de conexoes PostgreSQL por aplicacao e tipo. Criado auditoria 2026-07-04.';


--
-- Name: v_cron_health; Type: VIEW; Schema: monitoring; Owner: -
--

CREATE VIEW monitoring.v_cron_health WITH (security_invoker='true') AS
 SELECT job.jobname,
    job.schedule,
    job.active,
        CASE
            WHEN ((job.command ~~* '%public.%'::text) OR (job.command ~~* '%fn_%'::text) OR (job.command ~~* '%rpc_%'::text)) THEN 'schema_ok'::text
            ELSE 'check_schema'::text
        END AS schema_status,
    "left"(job.command, 80) AS command_preview
   FROM cron.job
  ORDER BY job.jobname;


--
-- Name: v_db_health_overview; Type: VIEW; Schema: monitoring; Owner: -
--

CREATE VIEW monitoring.v_db_health_overview WITH (security_invoker='true') AS
 SELECT pg_size_pretty(pg_database_size(current_database())) AS tamanho_total,
    ( SELECT count(*) AS count
           FROM information_schema.tables
          WHERE (((tables.table_schema)::name = 'public'::name) AND ((tables.table_type)::text = 'BASE TABLE'::text))) AS tabelas_public,
    ( SELECT count(*) AS count
           FROM information_schema.tables
          WHERE ((tables.table_schema)::name = 'evo'::name)) AS objetos_evo,
    ( SELECT count(*) AS count
           FROM information_schema.tables
          WHERE ((tables.table_schema)::name = 'zapp'::name)) AS objetos_zapp,
    ( SELECT count(*) AS count
           FROM information_schema.tables
          WHERE ((tables.table_schema)::name = 'monitoring'::name)) AS objetos_monitoring,
    ( SELECT count(*) AS count
           FROM cron.job
          WHERE (job.active = true)) AS cron_jobs_ativos,
    ( SELECT count(*) AS count
           FROM (pg_proc p
             JOIN pg_namespace n ON ((n.oid = p.pronamespace)))
          WHERE (n.nspname = 'public'::name)) AS total_funcoes,
    ( SELECT count(*) AS count
           FROM monitoring.architecture_changelog) AS melhorias_aplicadas,
    now() AS coletado_em;


--
-- Name: v_index_health; Type: VIEW; Schema: monitoring; Owner: -
--

CREATE VIEW monitoring.v_index_health WITH (security_invoker='true') AS
 SELECT s.schemaname AS schema,
    s.relname AS tabela,
    s.indexrelname AS indice,
    s.idx_scan AS total_scans,
    pg_size_pretty(pg_relation_size((s.indexrelid)::regclass)) AS tamanho,
        CASE
            WHEN ((s.idx_scan = 0) AND (NOT i.indisprimary) AND (NOT i.indisunique)) THEN 'CANDIDATO_REMOCAO'::text
            WHEN (s.idx_scan < 10) THEN 'POUCO_USADO'::text
            WHEN (s.idx_scan < 100) THEN 'MODERADO'::text
            ELSE 'ATIVO'::text
        END AS situacao,
    a.amname AS tipo
   FROM (((pg_stat_user_indexes s
     JOIN pg_index i ON ((i.indexrelid = s.indexrelid)))
     JOIN pg_class c ON ((c.oid = s.indexrelid)))
     JOIN pg_am a ON ((a.oid = c.relam)))
  WHERE (s.schemaname = ANY (ARRAY['public'::name, 'zapp'::name, 'evo'::name]))
  ORDER BY s.idx_scan, (pg_relation_size((s.indexrelid)::regclass)) DESC;


--
-- Name: VIEW v_index_health; Type: COMMENT; Schema: monitoring; Owner: -
--

COMMENT ON VIEW monitoring.v_index_health IS 'Estado de uso de todos os indexes (public, zapp, evo). Identificar candidatos a remocao.';


--
-- Name: v_kpi_alertas; Type: VIEW; Schema: monitoring; Owner: -
--

CREATE VIEW monitoring.v_kpi_alertas WITH (security_invoker='true') AS
 SELECT evolution_alerts.severity,
    evolution_alerts.alert_type,
    count(*) FILTER (WHERE (NOT COALESCE(evolution_alerts.resolved, false))) AS abertos,
    count(*) FILTER (WHERE ((evolution_alerts.notified_at IS NULL) AND (NOT COALESCE(evolution_alerts.resolved, false)))) AS sem_notificacao,
    (round(avg((EXTRACT(epoch FROM (evolution_alerts.notified_at - evolution_alerts.created_at)) / (60)::numeric)) FILTER (WHERE (evolution_alerts.notified_at IS NOT NULL))))::integer AS min_medio_ate_notificar,
    max(evolution_alerts.created_at) AS ultimo_alerta
   FROM evo.evolution_alerts
  WHERE (evolution_alerts.created_at > (now() - '7 days'::interval))
  GROUP BY evolution_alerts.severity, evolution_alerts.alert_type
  ORDER BY evolution_alerts.severity, (count(*) FILTER (WHERE (NOT COALESCE(evolution_alerts.resolved, false)))) DESC;


