-- Name: v_kpi_resumo; Type: VIEW; Schema: monitoring; Owner: -
--

CREATE VIEW monitoring.v_kpi_resumo WITH (security_invoker='true') AS
 SELECT now() AS snapshot_at,
    ( SELECT count(*) AS count
           FROM zapp.whatsapp_connections
          WHERE (whatsapp_connections.is_active = true)) AS total_connections,
    ( SELECT count(*) AS count
           FROM zapp.whatsapp_connections
          WHERE ((whatsapp_connections.status = 'connected'::text) AND (whatsapp_connections.is_active = true))) AS connected_count,
    ( SELECT count(*) AS count
           FROM zapp.whatsapp_connections
          WHERE ((whatsapp_connections.status <> 'connected'::text) AND (whatsapp_connections.is_active = true))) AS disconnected_count,
    ( SELECT count(*) AS count
           FROM zapp.instance_registry
          WHERE (instance_registry.is_active = true)) AS registered_instances;


--
-- Name: instance_auth_events; Type: TABLE; Schema: zapp; Owner: -
--

CREATE TABLE zapp.instance_auth_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    instance_name text NOT NULL,
    event_type text,
    ip_address text,
    user_agent text,
    success boolean DEFAULT false,
    created_at timestamp with time zone DEFAULT now(),
    reason text,
    paused_until timestamp with time zone,
    investigated_at timestamp with time zone,
    source text,
    http_status integer,
    detail text,
    meta jsonb,
    status_code integer,
    CONSTRAINT instance_auth_events_reason_check CHECK (((reason IS NULL) OR (reason = ANY (ARRAY['invalid_signature'::text, 'auth_401'::text, 'auth_403'::text])))),
    CONSTRAINT instance_auth_events_source_check CHECK (((source IS NULL) OR (source = ANY (ARRAY['webhook'::text, 'evolution-api'::text]))))
);


