-- Name: COLUMN webhook_events_processed.instance; Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON COLUMN zapp.webhook_events_processed.instance IS 'Hotfix 2026-05-04: instance_name do Evolution (popular pela EF evolution-webhook).';


--
-- Name: COLUMN webhook_events_processed.responded; Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON COLUMN zapp.webhook_events_processed.responded IS 'Indica se o evento foi processado/respondido pelo consumer. DEFAULT TRUE: toda linha nesta tabela representa um evento processado com sucesso. Coluna mantida para compatibilidade futura de auditoria. Inserida como false ate 2026-07-11 (bug de design); corrigido em auditoria-exaustiva-20260711.';


--
-- Name: COLUMN webhook_events_processed.message_key_id; Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON COLUMN zapp.webhook_events_processed.message_key_id IS 'M-3 (2026-07-12): WhatsApp message WAMID (key.id from messages.upsert payload). NULL for non-message events. Used for secondary dedup on top of sha256 event hash so the same WhatsApp message is never double-processed even when raw body bytes differ.';


--
-- Name: COLUMN webhook_events_processed.payload; Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON COLUMN zapp.webhook_events_processed.payload IS 'Payload JSON original do webhook — opcional, para debugging e filtragem de event_types específicos (ex: reactions, status@broadcast) que chegam como messages.upsert mas não persistem mensagens.';


--
-- Name: v_kpi_webhook_saude; Type: VIEW; Schema: monitoring; Owner: -
--

CREATE VIEW monitoring.v_kpi_webhook_saude WITH (security_invoker='true') AS
 SELECT COALESCE(p.hora, e.hora) AS hora,
    COALESCE(p.processados, (0)::bigint) AS eventos_processados,
    COALESCE(e.invalid_sig, (0)::bigint) AS invalid_signature,
    COALESCE(e.auth_401, (0)::bigint) AS auth_401
   FROM (( SELECT date_trunc('hour'::text, webhook_events_processed.processed_at) AS hora,
            count(*) AS processados
           FROM zapp.webhook_events_processed
          WHERE (webhook_events_processed.processed_at > (now() - '48:00:00'::interval))
          GROUP BY (date_trunc('hour'::text, webhook_events_processed.processed_at))) p
     FULL JOIN ( SELECT date_trunc('hour'::text, instance_auth_events.created_at) AS hora,
            count(*) FILTER (WHERE (instance_auth_events.reason = 'invalid_signature'::text)) AS invalid_sig,
            count(*) FILTER (WHERE (instance_auth_events.reason = 'auth_401'::text)) AS auth_401
           FROM zapp.instance_auth_events
          WHERE (instance_auth_events.created_at > (now() - '48:00:00'::interval))
          GROUP BY (date_trunc('hour'::text, instance_auth_events.created_at))) e USING (hora))
  ORDER BY COALESCE(p.hora, e.hora) DESC;


--
-- Name: v_schema_inventory; Type: VIEW; Schema: monitoring; Owner: -
--

CREATE VIEW monitoring.v_schema_inventory WITH (security_invoker='true') AS
 SELECT tables.table_schema,
    count(*) FILTER (WHERE ((tables.table_type)::text = 'BASE TABLE'::text)) AS base_tables,
    count(*) FILTER (WHERE ((tables.table_type)::text = 'VIEW'::text)) AS views,
    count(*) AS total_objects
   FROM information_schema.tables
  WHERE (((tables.table_schema)::name <> ALL (ARRAY['pg_catalog'::name, 'information_schema'::name, 'auth'::name, 'storage'::name, 'realtime'::name, '_realtime'::name, 'graphql'::name, 'graphql_public'::name, 'net'::name, 'cron'::name, 'extensions'::name, 'supabase_functions'::name, 'vault'::name, 'parity_audit'::name])) AND ((tables.table_schema)::name !~~ 'pg_temp_%'::text))
  GROUP BY tables.table_schema
  ORDER BY (count(*)) DESC;


--
-- Name: v_slow_queries; Type: VIEW; Schema: monitoring; Owner: -
--

CREATE VIEW monitoring.v_slow_queries WITH (security_invoker='true') AS
 SELECT round((pg_stat_statements.mean_exec_time)::numeric, 0) AS mean_ms,
    pg_stat_statements.calls,
    round(((pg_stat_statements.total_exec_time / (1000)::double precision))::numeric, 1) AS total_sec,
    round((pg_stat_statements.stddev_exec_time)::numeric, 0) AS stddev_ms,
    (pg_stat_statements.rows / NULLIF(pg_stat_statements.calls, 0)) AS avg_rows,
    "left"(pg_stat_statements.query, 200) AS query_preview
   FROM extensions.pg_stat_statements
  WHERE ((pg_stat_statements.mean_exec_time > (100)::double precision) AND (pg_stat_statements.calls > 5))
  ORDER BY pg_stat_statements.total_exec_time DESC;


--
-- Name: VIEW v_slow_queries; Type: COMMENT; Schema: monitoring; Owner: -
--

COMMENT ON VIEW monitoring.v_slow_queries IS 'Top queries lentas do banco (mean > 100ms, calls > 5). Fonte: pg_stat_statements.';


--
-- Name: v_table_bloat; Type: VIEW; Schema: monitoring; Owner: -
--

CREATE VIEW monitoring.v_table_bloat WITH (security_invoker='true') AS
 SELECT pg_stat_user_tables.schemaname AS schema,
    pg_stat_user_tables.relname AS tabela,
    pg_stat_user_tables.n_live_tup AS live_rows,
    pg_stat_user_tables.n_dead_tup AS dead_rows,
        CASE
            WHEN ((pg_stat_user_tables.n_live_tup + pg_stat_user_tables.n_dead_tup) > 0) THEN round(((100.0 * (pg_stat_user_tables.n_dead_tup)::numeric) / ((pg_stat_user_tables.n_live_tup + pg_stat_user_tables.n_dead_tup))::numeric), 2)
            ELSE (0)::numeric
        END AS dead_pct,
    pg_size_pretty(pg_total_relation_size(((((pg_stat_user_tables.schemaname)::text || '.'::text) || (pg_stat_user_tables.relname)::text))::regclass)) AS tamanho_total,
    pg_stat_user_tables.last_autovacuum,
    pg_stat_user_tables.last_autoanalyze
   FROM pg_stat_user_tables
  WHERE ((pg_stat_user_tables.schemaname = ANY (ARRAY['public'::name, 'zapp'::name, 'evo'::name])) AND ((pg_stat_user_tables.n_live_tup + pg_stat_user_tables.n_dead_tup) > 100))
  ORDER BY
        CASE
            WHEN ((pg_stat_user_tables.n_live_tup + pg_stat_user_tables.n_dead_tup) > 0) THEN round(((100.0 * (pg_stat_user_tables.n_dead_tup)::numeric) / ((pg_stat_user_tables.n_live_tup + pg_stat_user_tables.n_dead_tup))::numeric), 2)
            ELSE (0)::numeric
        END DESC, pg_stat_user_tables.n_dead_tup DESC;


--
-- Name: VIEW v_table_bloat; Type: COMMENT; Schema: monitoring; Owner: -
--

COMMENT ON VIEW monitoring.v_table_bloat IS 'Tabelas com dead tuples (bloat). Candidatos a VACUUM urgente se dead_pct > 10%.';


--
-- Name: v_top_tables_by_size; Type: VIEW; Schema: monitoring; Owner: -
--

CREATE VIEW monitoring.v_top_tables_by_size WITH (security_invoker='true') AS
 SELECT pg_tables.schemaname,
    pg_tables.tablename,
    pg_size_pretty(pg_total_relation_size(((((pg_tables.schemaname)::text || '.'::text) || (pg_tables.tablename)::text))::regclass)) AS total_size,
    pg_total_relation_size(((((pg_tables.schemaname)::text || '.'::text) || (pg_tables.tablename)::text))::regclass) AS bytes_size,
    round((((pg_total_relation_size(((((pg_tables.schemaname)::text || '.'::text) || (pg_tables.tablename)::text))::regclass))::numeric * 100.0) / (NULLIF(pg_database_size(current_database()), 0))::numeric), 2) AS pct_of_db
   FROM pg_tables
  WHERE (pg_tables.schemaname = ANY (ARRAY['public'::name, 'evo'::name, 'zapp'::name, 'bpm'::name, 'email_app'::name, 'financeiro'::name, 'vendas'::name, 'artes'::name]))
  ORDER BY (pg_total_relation_size(((((pg_tables.schemaname)::text || '.'::text) || (pg_tables.tablename)::text))::regclass)) DESC
 LIMIT 25;


