--
-- Name: mv_disk_daily_summary; Type: MATERIALIZED VIEW; Schema: ops; Owner: -
--

CREATE MATERIALIZED VIEW ops.mv_disk_daily_summary AS
 SELECT date_trunc('day'::text, host_disk_log.checked_at) AS day,
    host_disk_log.host,
    min(host_disk_log.used_pct) AS pct_min,
    max(host_disk_log.used_pct) AS pct_max,
    round(avg(host_disk_log.used_pct), 1) AS pct_avg,
    percentile_cont((0.95)::double precision) WITHIN GROUP (ORDER BY ((host_disk_log.used_pct)::double precision)) AS pct_p95,
    count(*) AS samples,
    count(*) FILTER (WHERE (host_disk_log.tier = 'WARN'::text)) AS warn_count,
    count(*) FILTER (WHERE (host_disk_log.tier = 'THROTTLE'::text)) AS throttle_count,
    count(*) FILTER (WHERE (host_disk_log.tier = 'FREEZE'::text)) AS freeze_count,
    count(*) FILTER (WHERE (host_disk_log.tier = 'EMERGENCY'::text)) AS emergency_count,
    count(*) FILTER (WHERE (host_disk_log.transitioned = true)) AS transitions,
    max(host_disk_log.used_pct) FILTER (WHERE (host_disk_log.tier = ANY (ARRAY['WARN'::text, 'THROTTLE'::text, 'FREEZE'::text, 'EMERGENCY'::text]))) AS incident_peak_pct
   FROM ops.host_disk_log
  WHERE (host_disk_log.checked_at > (now() - '90 days'::interval))
  GROUP BY (date_trunc('day'::text, host_disk_log.checked_at)), host_disk_log.host
  ORDER BY (date_trunc('day'::text, host_disk_log.checked_at)) DESC, host_disk_log.host
  WITH NO DATA;


--
-- Name: MATERIALIZED VIEW mv_disk_daily_summary; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON MATERIALIZED VIEW ops.mv_disk_daily_summary IS 'Resumo diario de uso de disco por host. Atualizar com: REFRESH MATERIALIZED VIEW CONCURRENTLY ops.mv_disk_daily_summary';


