--
-- Name: v_auth_health; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_auth_health WITH (security_invoker='on') AS
 SELECT ( SELECT count(*) AS count
           FROM auth.sessions) AS total_sessions,
    ( SELECT count(DISTINCT sessions.user_id) AS count
           FROM auth.sessions) AS users_with_sessions,
    ( SELECT max(sub.session_count) AS max
           FROM ( SELECT count(*) AS session_count
                   FROM auth.sessions
                  GROUP BY sessions.user_id) sub) AS max_sessions_per_user,
    ( SELECT count(*) AS count
           FROM auth.refresh_tokens
          WHERE (refresh_tokens.created_at > (now() - '01:00:00'::interval))) AS new_tokens_last_hour,
    ( SELECT count(*) AS count
           FROM auth.refresh_tokens
          WHERE (NOT (refresh_tokens.session_id IN ( SELECT sessions.id
                   FROM auth.sessions)))) AS orphan_refresh_tokens,
    now() AS checked_at;


--
-- Name: VIEW v_auth_health; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON VIEW ops.v_auth_health IS 'Dashboard de saúde do sistema de autenticação GoTrue';


--
-- Name: v_auth_session_monitor; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_auth_session_monitor WITH (security_invoker='on') AS
 SELECT u.email,
    u.id AS user_id,
    count(s.id) AS session_count,
    max(s.created_at) AS newest_session,
    min(s.created_at) AS oldest_session,
    (EXTRACT(epoch FROM (max(s.created_at) - min(s.created_at))) / (3600)::numeric) AS session_span_hours,
    count(s.id) FILTER (WHERE (s.not_after IS NULL)) AS no_expiry_sessions,
        CASE
            WHEN (count(s.id) >= 15) THEN 'CRITICAL'::text
            WHEN (count(s.id) >= 10) THEN 'WARNING'::text
            WHEN (count(s.id) >= 5) THEN 'OK'::text
            ELSE 'HEALTHY'::text
        END AS status
   FROM (auth.users u
     LEFT JOIN auth.sessions s ON ((s.user_id = u.id)))
  GROUP BY u.id, u.email
 HAVING (count(s.id) > 0)
  ORDER BY (count(s.id)) DESC;


--
-- Name: VIEW v_auth_session_monitor; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON VIEW ops.v_auth_session_monitor IS 'Monitoramento de sessões GoTrue por usuario. status: CRITICAL>=15, WARNING>=10, OK>=5, HEALTHY<5';


--
-- Name: v_disk_current_state; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_disk_current_state WITH (security_invoker='true') AS
 WITH latest AS (
         SELECT DISTINCT ON (host_disk_log.host) host_disk_log.host,
            host_disk_log.mount,
            host_disk_log.used_pct,
            host_disk_log.avail_h,
            host_disk_log.total_h,
            host_disk_log.tier,
            host_disk_log.status,
            host_disk_log.transitioned,
            host_disk_log.checked_at
           FROM ops.host_disk_log
          ORDER BY host_disk_log.host, host_disk_log.id DESC
        ), pending AS (
         SELECT disk_actions_queue.target,
            count(*) AS pending_actions
           FROM ops.disk_actions_queue
          WHERE (disk_actions_queue.executed_at IS NULL)
          GROUP BY disk_actions_queue.target
        ), paused AS (
         SELECT paused_services.tier,
            count(*) AS paused_count
           FROM ops.paused_services
          WHERE (paused_services.unpaused_at IS NULL)
          GROUP BY paused_services.tier
        ), flags AS (
         SELECT bool_or(disk_actioner_flags.enabled) FILTER (WHERE (disk_actioner_flags.flag_name = 'shadow_mode'::text)) AS shadow_mode,
            bool_or(disk_actioner_flags.enabled) FILTER (WHERE (disk_actioner_flags.flag_name = 'auto_recover'::text)) AS auto_recover,
            bool_or(disk_actioner_flags.enabled) FILTER (WHERE (disk_actioner_flags.flag_name = 'throttle_lock'::text)) AS throttle_lock,
            bool_or(disk_actioner_flags.enabled) FILTER (WHERE (disk_actioner_flags.flag_name = 'freeze_lock'::text)) AS freeze_lock
           FROM ops.disk_actioner_flags
        )
 SELECT l.host,
    l.used_pct,
    l.avail_h,
    l.total_h,
    l.tier,
    l.status AS legacy_status,
    l.transitioned AS last_was_transition,
    l.checked_at AS last_check,
    age(now(), l.checked_at) AS staleness,
    COALESCE(p.pending_actions, (0)::bigint) AS pending_actions,
    COALESCE(ps.paused_count, (0)::bigint) AS services_paused,
    f.shadow_mode,
    f.auto_recover,
    f.throttle_lock,
    f.freeze_lock,
    ops.suggest_disk_action(l.tier) AS recommended_action
   FROM (((latest l
     CROSS JOIN flags f)
     LEFT JOIN pending p ON ((NOT (p.target IS DISTINCT FROM l.tier))))
     LEFT JOIN paused ps ON ((ps.tier = l.tier)));


--
-- Name: VIEW v_disk_current_state; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON VIEW ops.v_disk_current_state IS 'Estado atual do disco por host. BUG-03 fix: id DESC para determinismo.';


--
-- Name: v_disk_orphans_pending; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_disk_orphans_pending WITH (security_invoker='true') AS
 SELECT disk_orphans.volume_name,
    disk_orphans.size_str,
    disk_orphans.detected_at,
    (age(now(), disk_orphans.detected_at))::text AS age,
        CASE
            WHEN (age(now(), disk_orphans.detected_at) > '7 days'::interval) THEN 'URGENT'::text
            WHEN (age(now(), disk_orphans.detected_at) > '3 days'::interval) THEN 'REVIEW'::text
            ELSE 'NEW'::text
        END AS priority
   FROM ops.disk_orphans
  WHERE ((disk_orphans.deleted_at IS NULL) AND (disk_orphans.reviewed_at IS NULL))
  ORDER BY disk_orphans.detected_at DESC;


--
-- Name: VIEW v_disk_orphans_pending; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON VIEW ops.v_disk_orphans_pending IS 'Volumes Docker orfãos detectados, aguardando review. Marcar como revisado: UPDATE ops.disk_orphans SET reviewed_at=now() WHERE volume_name=...';


--
-- Name: v_health_deadman; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_health_deadman WITH (security_invoker='on') AS
 SELECT now() AS checked_at,
    ( SELECT count(*) AS count
           FROM zapp.whatsapp_connections
          WHERE (whatsapp_connections.is_active = true)) AS active_connections,
    ( SELECT count(*) AS count
           FROM zapp.whatsapp_connections
          WHERE ((whatsapp_connections.status = 'connected'::text) AND (whatsapp_connections.is_active = true))) AS connected_count,
    ( SELECT max(whatsapp_connections.last_connected_at) AS max
           FROM zapp.whatsapp_connections
          WHERE (whatsapp_connections.is_active = true)) AS last_conn_at,
    (EXTRACT(epoch FROM (now() - ( SELECT max(whatsapp_connections.last_connected_at) AS max
           FROM zapp.whatsapp_connections
          WHERE (whatsapp_connections.is_active = true)))) / (3600)::numeric) AS hours_since_last_conn;


--
-- Name: v_wal_health; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_wal_health WITH (security_invoker='true') AS
 SELECT pg_replication_slots.slot_name,
    pg_replication_slots.plugin,
    pg_replication_slots.active,
    pg_replication_slots.active_pid,
    pg_size_pretty(pg_wal_lsn_diff(pg_current_wal_lsn(), pg_replication_slots.restart_lsn)) AS restart_lag,
    pg_size_pretty(pg_wal_lsn_diff(pg_current_wal_lsn(), pg_replication_slots.confirmed_flush_lsn)) AS flush_lag,
    pg_wal_lsn_diff(pg_current_wal_lsn(), pg_replication_slots.restart_lsn) AS restart_lag_bytes,
        CASE
            WHEN (NOT pg_replication_slots.active) THEN 'CRITICAL'::text
            WHEN (pg_wal_lsn_diff(pg_current_wal_lsn(), pg_replication_slots.restart_lsn) > (((500 * 1024) * 1024))::numeric) THEN 'WARNING'::text
            WHEN (pg_wal_lsn_diff(pg_current_wal_lsn(), pg_replication_slots.restart_lsn) > (((100 * 1024) * 1024))::numeric) THEN 'ELEVATED'::text
            ELSE 'OK'::text
        END AS health_status,
    age(pg_replication_slots.catalog_xmin) AS catalog_xmin_age,
    now() AS checked_at
   FROM pg_replication_slots
  ORDER BY (pg_wal_lsn_diff(pg_current_wal_lsn(), pg_replication_slots.restart_lsn)) DESC;


