--
-- Name: automations; Type: TABLE; Schema: zapp; Owner: -
--

CREATE TABLE zapp.automations (
    actions jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    description text,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    is_active boolean DEFAULT false NOT NULL,
    last_triggered_at timestamp with time zone,
    name text NOT NULL,
    trigger_config jsonb DEFAULT '{}'::jsonb NOT NULL,
    trigger_count integer DEFAULT 0 NOT NULL,
    trigger_type text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    priority smallint DEFAULT 100 NOT NULL,
    cooldown_seconds integer DEFAULT 300 NOT NULL,
    channel_id uuid,
    department_id uuid,
    CONSTRAINT automations_cooldown_seconds_check CHECK ((cooldown_seconds >= 0)),
    CONSTRAINT automations_priority_check CHECK (((priority >= 1) AND (priority <= 999)))
);


--
-- Name: COLUMN automations.priority; Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON COLUMN zapp.automations.priority IS 'Ordem de avaliacao das regras (1=mais alta). Padrao 100.';


--
-- Name: COLUMN automations.cooldown_seconds; Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON COLUMN zapp.automations.cooldown_seconds IS 'Intervalo minimo entre disparos para mesma conversa (s). Padrao 300.';


--
-- Name: COLUMN automations.channel_id; Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON COLUMN zapp.automations.channel_id IS 'Canal restrito; NULL = todos os canais.';


--
-- Name: COLUMN automations.department_id; Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON COLUMN zapp.automations.department_id IS 'Departamento restrito; NULL = todos os departamentos.';


