--
-- Name: business_hours; Type: TABLE; Schema: zapp; Owner: -
--

CREATE TABLE zapp.business_hours (
    close_time time without time zone,
    created_at timestamp with time zone DEFAULT now(),
    day_of_week numeric NOT NULL,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    is_open boolean DEFAULT false,
    open_time time without time zone,
    updated_at timestamp with time zone DEFAULT now(),
    whatsapp_connection_id uuid NOT NULL,
    CONSTRAINT business_hours_day_of_week_check CHECK (((day_of_week >= (0)::numeric) AND (day_of_week <= (6)::numeric)))
);


--
-- Name: business_hours; Type: VIEW; Schema: public; Owner: -
