-- Name: contact_intelligence; Type: TABLE; Schema: zapp; Owner: -
--

CREATE TABLE zapp.contact_intelligence (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    contact_id uuid NOT NULL,
    sentiment text,
    engagement_score numeric,
    predicted_value numeric,
    risk_level text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    phone text,
    contact_name text,
    lead_status text,
    total_messages integer DEFAULT 0,
    days_since_contact integer,
    disc_profile text DEFAULT 'C'::text,
    inbound_ratio numeric(5,2) DEFAULT 0,
    CONSTRAINT ci_engagement_range CHECK (((engagement_score IS NULL) OR ((engagement_score >= (0)::numeric) AND (engagement_score <= (100)::numeric)))),
    CONSTRAINT ci_predicted_value_positive CHECK (((predicted_value IS NULL) OR (predicted_value >= (0)::numeric))),
    CONSTRAINT ci_risk_level_valid CHECK (((risk_level IS NULL) OR (risk_level = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text])))),
    CONSTRAINT contact_intelligence_disc_profile_check CHECK ((disc_profile = ANY (ARRAY['D'::text, 'I'::text, 'S'::text, 'C'::text]))),
    CONSTRAINT contact_intelligence_inbound_ratio_check CHECK (((inbound_ratio >= (0)::numeric) AND (inbound_ratio <= (100)::numeric)))
)
WITH (autovacuum_vacuum_scale_factor='0.05', autovacuum_vacuum_threshold='1000', autovacuum_analyze_scale_factor='0.05', autovacuum_analyze_threshold='500');

ALTER TABLE ONLY zapp.contact_intelligence REPLICA IDENTITY FULL;


--
-- Name: contacts; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.contacts WITH (security_invoker='on') AS
 SELECT ec.id,
    COALESCE(ec.full_name, ec.push_name, 'Sem nome'::character varying) AS name,
    COALESCE(ec.phone_number, ((split_part((ec.remote_jid)::text, '@'::text, 1))::character varying)::text) AS phone,
    ec.email,
    ec.profile_picture_url AS avatar_url,
    COALESCE(ec.lead_status, 'open'::character varying) AS status,
    ec.assigned_to,
    ec.queue_id,
    zapp.get_connection_id_for_instance((ec.instance_name)::text) AS whatsapp_connection_id,
    ec.last_message_at,
    ec.first_contact_at AS first_message_at,
    COALESCE(ec.message_count, 0) AS unread_count,
    false AS is_blocked,
    false AS is_favorite,
    NULL::text AS cpf,
    ec.company,
    ec.role_title AS "position",
    NULL::text AS address,
    NULL::text AS city,
    NULL::text AS state,
    'BR'::text AS country,
    ec.notes,
    ec.lead_source AS source,
    ec.remote_jid AS external_id,
    ec.raw_data AS metadata,
    ec.created_at,
    ec.updated_at,
    ec.remote_jid,
    ec.push_name,
    ec.instance_name,
    ec.lead_score,
    ec.total_purchases,
    ec.whatsapp_labels,
    ec.tags,
    (ec.push_name)::text AS nickname,
    NULL::text AS surname,
    (ec.role_title)::text AS job_title,
    (COALESCE(ec.lead_status, 'open'::character varying))::text AS contact_type,
    'normal'::text AS ai_priority,
    'neutral'::text AS ai_sentiment,
    'whatsapp'::text AS channel_type,
    NULL::uuid AS channel_connection_id,
    NULL::text AS group_category,
    0 AS risk_score,
    (ec.lead_source)::text AS lead_origin,
        CASE
            WHEN ((ec.lgpd_consent_at IS NOT NULL) AND (ec.lgpd_opt_out_at IS NULL)) THEN 'granted'::text
            WHEN (ec.lgpd_opt_out_at IS NOT NULL) THEN 'opt_out'::text
            ELSE 'unknown'::text
        END AS consent_status,
    ec.deleted_at,
    'whatsapp'::text AS channel,
    ec.last_message_at AS last_seen_at,
    zapp.get_default_workspace_id() AS workspace_id
   FROM evo.evolution_contacts ec
  WHERE (ec.deleted_at IS NULL);


--
-- Name: VIEW contacts; Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON VIEW zapp.contacts IS 'Visão unificada de contatos sobre evo.evolution_contacts. Usa funções STABLE no lugar dos antigos CTEs MATERIALIZED que geravam 121K seq_scans/hora em whatsapp_connections e workspaces. LEFT JOIN lógico via função elimina também o risco de 0 linhas por workspace vazia.';


--
-- Name: contact_intelligence; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.contact_intelligence WITH (security_invoker='true') AS
 SELECT ci.id,
    ci.contact_id,
    ci.sentiment,
    ci.engagement_score,
    ci.predicted_value,
    ci.risk_level,
    ci.disc_profile,
    ci.total_messages,
    ci.total_messages AS total_interactions,
    ci.engagement_score AS relationship_score,
    ci.days_since_contact,
    ci.inbound_ratio,
    ci.contact_name,
    ci.lead_status,
        CASE
            WHEN (ci.days_since_contact IS NOT NULL) THEN (now() - ((ci.days_since_contact || ' days'::text))::interval)
            ELSE NULL::timestamp with time zone
        END AS last_contact_at,
    ci.created_at,
    ci.updated_at,
    c.phone,
    c.remote_jid
   FROM (zapp.contact_intelligence ci
     LEFT JOIN zapp.contacts c ON ((c.id = ci.contact_id)));


--
-- Name: VIEW contact_intelligence; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.contact_intelligence IS 'Intelligence por contato (20.562 rows). relationship_score = engagement_score (alias RawIntel frontend). total_interactions = total_messages (alias RawIntel frontend). last_contact_at derivado de days_since_contact. phone/remote_jid via LEFT JOIN zapp.contacts.';


