--
-- Name: creditos; Type: TABLE; Schema: vendas; Owner: -
--

CREATE TABLE vendas.creditos (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    pedido text NOT NULL,
    fornecedor text,
    produto text,
    criado_em timestamp with time zone DEFAULT now() NOT NULL,
    criado_por text,
    quantidade numeric,
    valor_unitario numeric,
    valor_total numeric,
    numero_pedido text,
    status text DEFAULT 'DISPONIVEL'::text NOT NULL,
    pedido_abatido text,
    observacao text,
    tipo_reembolso text,
    CONSTRAINT creditos_status_check CHECK ((status = ANY (ARRAY['CREDITO DISPONIVEL'::text, 'AGUARDANDO DEVOLUÇÃO'::text, 'MATERIAL PRONTO PARA COLETA'::text, 'FORNECEDOR RECEBEU MATERIAL'::text, 'AGUARDANDO REEMBOLSO DO FORNECEDOR'::text, 'ABATIDO EM OUTRO PEDIDO'::text]))),
    CONSTRAINT creditos_tipo_reembolso_check CHECK (((tipo_reembolso IS NULL) OR (tipo_reembolso = ANY (ARRAY['REEMBOLSO EM DINHEIRO'::text, 'REEMBOLSO EM MERCADORIA'::text]))))
);


--
-- Name: creditos; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.creditos WITH (security_invoker='true') AS
 SELECT creditos.id,
    creditos.pedido,
    creditos.fornecedor,
    creditos.produto,
    creditos.criado_em,
    creditos.criado_por,
    creditos.quantidade,
    creditos.valor_unitario,
    creditos.valor_total,
    creditos.numero_pedido,
    creditos.status,
    creditos.pedido_abatido,
    creditos.observacao,
    creditos.tipo_reembolso
   FROM vendas.creditos;


