--
-- Name: extensions; Type: TABLE; Schema: zapp; Owner: -
--

CREATE TABLE zapp.extensions (
    id uuid NOT NULL,
    type text,
    settings jsonb,
    tenant_external_id text,
    inserted_at timestamp(0) without time zone NOT NULL,
    updated_at timestamp(0) without time zone NOT NULL
);


--
-- Name: extensions; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.extensions WITH (security_invoker='true') AS
 SELECT extensions.id,
    extensions.type,
    extensions.settings,
    extensions.tenant_external_id,
    extensions.inserted_at,
    extensions.updated_at
   FROM zapp.extensions;


--
-- Name: failed_messages; Type: TABLE; Schema: zapp; Owner: -
--

CREATE TABLE zapp.failed_messages (
    created_at timestamp with time zone DEFAULT now(),
    error_code text,
    error_message text,
    http_status numeric,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    idempotency_key text,
    instance_name text NOT NULL,
    last_attempt_at timestamp with time zone,
    last_retry_reason text,
    max_retries numeric NOT NULL,
    next_attempt_at timestamp with time zone,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    remote_jid text,
    retry_count integer NOT NULL,
    status text NOT NULL,
    succeeded_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now(),
    message_id text,
    next_retry_at timestamp with time zone,
    CONSTRAINT failed_messages_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'retrying'::text, 'succeeded'::text, 'abandoned'::text, 'failed'::text])))
);


--
-- Name: failed_messages; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.failed_messages WITH (security_invoker='true') AS
 SELECT failed_messages.created_at,
    failed_messages.error_code,
    failed_messages.error_message,
    failed_messages.http_status,
    failed_messages.id,
    failed_messages.idempotency_key,
    failed_messages.instance_name,
    failed_messages.last_attempt_at,
    failed_messages.last_retry_reason,
    failed_messages.max_retries,
    failed_messages.next_attempt_at,
    failed_messages.payload,
    failed_messages.remote_jid,
    failed_messages.retry_count,
    failed_messages.status,
    failed_messages.succeeded_at,
    failed_messages.updated_at,
    failed_messages.message_id,
    failed_messages.next_retry_at
   FROM zapp.failed_messages;


