CREATE TABLE zapp.media_download_queue (
    id bigint NOT NULL,
    message_id text NOT NULL,
    message_uuid uuid,
    remote_jid text NOT NULL,
    instance_name text DEFAULT 'wpp2'::text NOT NULL,
    media_type text NOT NULL,
    media_key text,
    direct_path text,
    mimetype text,
    file_length bigint,
    status text DEFAULT 'pending'::text NOT NULL,
    download_url text,
    storage_path text,
    retry_count integer DEFAULT 0,
    max_retries integer DEFAULT 3,
    error_message text,
    priority integer DEFAULT 0,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    processed_at timestamp with time zone,
    scan_status character varying(20) DEFAULT 'pending_scan'::character varying,
    scan_result text,
    scanned_at timestamp with time zone,
    next_retry_at timestamp with time zone DEFAULT now(),
    jitter_ms integer DEFAULT 0,
    worker_id text,
    locked_at timestamp with time zone,
    media_status_target text DEFAULT 'ready'::text,
    CONSTRAINT media_download_queue_scan_status_check CHECK (((scan_status)::text = ANY ((ARRAY['pending_scan'::character varying, 'scanning'::character varying, 'clean'::character varying, 'blocked'::character varying, 'skipped'::character varying])::text[]))),
    CONSTRAINT media_download_queue_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'done'::text, 'failed'::text, 'expired'::text, 'blocked'::text])))
)
WITH (autovacuum_vacuum_cost_delay='10', autovacuum_vacuum_scale_factor='0.05', autovacuum_vacuum_threshold='1000', autovacuum_analyze_scale_factor='0.05', autovacuum_analyze_threshold='500');


