    messages.media_filename,
    messages.media_size,
    messages.whatsapp_message_id,
    messages.whatsapp_timestamp,
    messages.status,
    messages.is_from_me,
    messages.sender_id,
    messages.reply_to_message_id,
    messages.quoted_message,
    messages.metadata,
    messages.is_deleted,
    messages.is_edited,
    messages.reaction,
    messages.latitude,
    messages.longitude,
    messages.external_id,
    messages.caption,
    messages.instance_name,
    messages.push_name,
    messages.remote_jid,
    messages.conversation_id,
    messages.created_at,
    messages.updated_at,
    messages.whatsapp_connection_id,
    messages.sender,
    messages.is_read,
    messages.agent_id,
    messages.transcription,
    messages.transcription_status,
    messages.status_updated_at,
    messages.channel_type,
    messages.channel_connection_id,
    messages.request_id,
    messages.error_code,
    messages.error_reason,
    messages.retry_attempt,
    messages.retry_total,
    messages.deleted_at,
    messages.link_preview,
    messages.media_meta,
    messages.media_mimetype,
    messages.media_type,
    messages.reply_to_id
   FROM zapp.messages;


