--
-- Name: mv_top_stickers; Type: MATERIALIZED VIEW; Schema: zapp; Owner: -
--

CREATE MATERIALIZED VIEW zapp.mv_top_stickers AS
 SELECT s.id,
    s.name,
    s.image_url,
    s.category,
    s.use_count,
    s.is_favorite,
    s.is_animated,
    s.created_at
   FROM zapp.stickers s
  WHERE (s.is_active = true)
  ORDER BY s.use_count DESC, s.created_at DESC
 LIMIT 100
  WITH NO DATA;


