--
-- Name: produtos_ncm_mapa; Type: TABLE; Schema: vendas; Owner: -
--

CREATE TABLE vendas.produtos_ncm_mapa (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    cod_produto text NOT NULL,
    nome_produto text,
    ncm text NOT NULL,
    fornecedor text,
    origem text DEFAULT 'bling_api'::text NOT NULL,
    validado boolean DEFAULT false NOT NULL,
    observacao text,
    criado_em timestamp with time zone DEFAULT now() NOT NULL,
    atualizado_em timestamp with time zone DEFAULT now() NOT NULL,
    criado_por text,
    confianca_ia text,
    justificativa_ia text,
    descricao_ncm text,
    modelo_ia text,
    CONSTRAINT chk_confianca_ia CHECK (((confianca_ia IS NULL) OR (confianca_ia = ANY (ARRAY['alta'::text, 'media'::text, 'baixa'::text])))),
    CONSTRAINT chk_ncm_mapa_formato CHECK ((ncm ~ '^[0-9]{8}$'::text)),
    CONSTRAINT chk_ncm_mapa_origem CHECK ((origem = ANY (ARRAY['bling_api'::text, 'manual'::text, 'inferido'::text, 'ia_gemini'::text, 'ia_outros'::text])))
);


--
-- Name: TABLE produtos_ncm_mapa; Type: COMMENT; Schema: vendas; Owner: -
--

COMMENT ON TABLE vendas.produtos_ncm_mapa IS '[Onda NF] Dicionário mestre de SKU → NCM. Cache do Bling + correções manuais. Usado pelo trigger trg_ncm_autopopulate para propagar NCM para vendas.ordens_compra.';


--
-- Name: COLUMN produtos_ncm_mapa.origem; Type: COMMENT; Schema: vendas; Owner: -
--

COMMENT ON COLUMN vendas.produtos_ncm_mapa.origem IS 'bling_api: buscado via Bling | manual: cadastrado por humano | inferido: deduzido por similaridade de nome';


--
-- Name: COLUMN produtos_ncm_mapa.validado; Type: COMMENT; Schema: vendas; Owner: -
--

COMMENT ON COLUMN vendas.produtos_ncm_mapa.validado IS 'true quando humano revisou e aprovou o NCM. NCMs do Bling vêm como false até alguém validar.';


--
-- Name: COLUMN produtos_ncm_mapa.confianca_ia; Type: COMMENT; Schema: vendas; Owner: -
--

COMMENT ON COLUMN vendas.produtos_ncm_mapa.confianca_ia IS '[Onda NF] Nível de confiança quando NCM veio de IA: alta | media | baixa. NULL para origens não-IA.';


--
-- Name: COLUMN produtos_ncm_mapa.justificativa_ia; Type: COMMENT; Schema: vendas; Owner: -
--

COMMENT ON COLUMN vendas.produtos_ncm_mapa.justificativa_ia IS '[Onda NF] Texto curto explicando o porquê da classificação pela IA. Auditoria/revisão humana.';


--
-- Name: COLUMN produtos_ncm_mapa.descricao_ncm; Type: COMMENT; Schema: vendas; Owner: -
--

COMMENT ON COLUMN vendas.produtos_ncm_mapa.descricao_ncm IS '[Onda NF] Descrição oficial do NCM segundo nomenclatura SEFAZ/RFB. Ex: "Mochilas e bolsas semelhantes".';


--
-- Name: COLUMN produtos_ncm_mapa.modelo_ia; Type: COMMENT; Schema: vendas; Owner: -
--

COMMENT ON COLUMN vendas.produtos_ncm_mapa.modelo_ia IS '[Onda NF] Modelo IA usado (ex: gemini-2.0-flash). Permite recalibrar conforme melhora.';


--
-- Name: produtos_ncm_mapa; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.produtos_ncm_mapa WITH (security_invoker='true') AS
 SELECT produtos_ncm_mapa.id,
    produtos_ncm_mapa.cod_produto,
    produtos_ncm_mapa.nome_produto,
    produtos_ncm_mapa.ncm,
    produtos_ncm_mapa.fornecedor,
    produtos_ncm_mapa.origem,
    produtos_ncm_mapa.validado,
    produtos_ncm_mapa.observacao,
    produtos_ncm_mapa.criado_em,
    produtos_ncm_mapa.atualizado_em,
    produtos_ncm_mapa.criado_por,
    produtos_ncm_mapa.confianca_ia,
    produtos_ncm_mapa.justificativa_ia,
    produtos_ncm_mapa.descricao_ncm,
    produtos_ncm_mapa.modelo_ia
   FROM vendas.produtos_ncm_mapa;


