--

CREATE VIEW public.whatsapp_official_credentials_safe WITH (security_invoker='true') AS
 SELECT whatsapp_official_credentials.id,
    whatsapp_official_credentials.connection_id,
    whatsapp_official_credentials.app_id,
    whatsapp_official_credentials.phone_number_id,
    whatsapp_official_credentials.waba_id,
    ((whatsapp_official_credentials.access_token IS NOT NULL) AND (length(whatsapp_official_credentials.access_token) > 0)) AS has_access_token,
    ((whatsapp_official_credentials.app_secret IS NOT NULL) AND (length(whatsapp_official_credentials.app_secret) > 0)) AS has_app_secret,
    whatsapp_official_credentials.created_at,
    whatsapp_official_credentials.updated_at
   FROM zapp.whatsapp_official_credentials;


