--
-- Name: v_itens_pedido_pendentes; Type: VIEW; Schema: vendas; Owner: -
--

CREATE VIEW vendas.v_itens_pedido_pendentes WITH (security_invoker='on') AS
 SELECT ordens_compra.id,
    ordens_compra.pedido,
        CASE
            WHEN (ordens_compra.pedido ~ '^.+-[0-9]+$'::text) THEN regexp_replace(ordens_compra.pedido, '-[0-9]+$'::text, ''::text)
            ELSE ordens_compra.pedido
        END AS pedido_pai,
    ordens_compra.empresa,
    ordens_compra.cnpj,
    ordens_compra.cidade_estado,
    ordens_compra.cliente,
    ordens_compra.produto,
    ordens_compra.cor,
    ordens_compra.cod_produto,
    ordens_compra.qtd_pedido,
    COALESCE(ordens_compra.qtd_compra, ordens_compra.qtd_pedido, (0)::numeric) AS qtd_compra,
    COALESCE(ordens_compra.qtd_enviada, (0)::numeric) AS qtd_enviada,
    GREATEST((COALESCE(ordens_compra.qtd_pedido, (0)::numeric) - COALESCE(ordens_compra.qtd_enviada, (0)::numeric)), (0)::numeric) AS qtd_pendente,
    GREATEST((COALESCE(ordens_compra.qtd_compra, ordens_compra.qtd_pedido, (0)::numeric) - COALESCE(ordens_compra.qtd_enviada, (0)::numeric)), (0)::numeric) AS qtd_disponivel_compra,
    COALESCE(ordens_compra.status_envio, 'pendente'::text) AS status_envio,
    ordens_compra.valor_vendido_unid,
    round((COALESCE(ordens_compra.valor_vendido_unid, (0)::numeric) / (4)::numeric), 2) AS valor_nf_remessa_unid,
    ordens_compra.ultimo_envio_em,
    ordens_compra.ultima_cotacao_id,
    ordens_compra.status,
    ordens_compra.data_venda,
    ordens_compra.data_entrega,
    ordens_compra.vendedor
   FROM vendas.ordens_compra
  WHERE (ordens_compra.excluido_em IS NULL);


--
-- Name: vw_pedidos_pai; Type: VIEW; Schema: vendas; Owner: -
--

CREATE VIEW vendas.vw_pedidos_pai WITH (security_invoker='on') AS
 WITH itens AS (
         SELECT regexp_replace(ordens_compra.pedido, '-(\d+)$'::text, ''::text) AS pedido_pai,
            ordens_compra.pedido AS pedido_item,
            ordens_compra.ano,
            ordens_compra.mes,
            ordens_compra.data_venda,
            ordens_compra.data_entrega,
            ordens_compra.empresa,
            ordens_compra.cnpj,
            ordens_compra.cliente,
            ordens_compra.cidade_estado,
            ordens_compra.vendedor,
            ordens_compra.prioridade,
            ordens_compra.tipo_pedido,
            ordens_compra.produto,
            ordens_compra.fornecedor,
            ordens_compra.cod_produto,
            ordens_compra.cor,
            ordens_compra.qtd_pedido,
            ordens_compra.qtd_compra,
            ordens_compra.qtd_faltante,
            ordens_compra.qtd_enviada,
            ordens_compra.valor_compra_unid,
            ordens_compra.valor_compra_total,
            ordens_compra.valor_vendido_unid,
            (ordens_compra.qtd_pedido * ordens_compra.valor_vendido_unid) AS valor_vendido_total,
            ordens_compra.layout,
            ordens_compra.tipo_gravacao,
            ordens_compra.gravacao_fornecedor,
            ordens_compra.gravacao_valor_unid,
            ordens_compra.status,
            ordens_compra.status_pagamento,
            ordens_compra.status_envio,
            ordens_compra.favorecido,
            ordens_compra.chave_pix,
            ordens_compra.pagamento,
            ordens_compra.obs_vendedor,
            ordens_compra.observacoes,
            ordens_compra.solicitante,
            ordens_compra.data_solicitacao,
            ordens_compra.criado_em,
            ordens_compra.atualizado_em,
            ordens_compra.ultima_cotacao_id
           FROM vendas.ordens_compra
          WHERE (ordens_compra.excluido_em IS NULL)
        )
 SELECT itens.pedido_pai,
    max(itens.ano) AS ano,
    max(itens.mes) AS mes,
    max(itens.data_venda) AS data_venda,
    max(itens.data_entrega) AS data_entrega,
    max(itens.empresa) AS empresa,
    max(itens.cnpj) AS cnpj,
    max(itens.cliente) AS cliente,
    max(itens.cidade_estado) AS cidade_estado,
    max(itens.vendedor) AS vendedor,
    max(itens.prioridade) AS prioridade,
    max(itens.tipo_pedido) AS tipo_pedido,
    count(*) AS qtd_itens,
    sum(itens.qtd_pedido) AS qtd_unidades_total,
    sum(itens.qtd_compra) AS qtd_unidades_compradas,
    sum(itens.qtd_faltante) AS qtd_faltantes,
    sum(itens.qtd_enviada) AS qtd_enviadas,
    sum(itens.valor_compra_total) AS custo_total,
    sum(itens.valor_vendido_total) AS valor_venda,
    (sum(itens.valor_vendido_total) - COALESCE(sum(itens.valor_compra_total), (0)::numeric)) AS margem_bruta,
        CASE
            WHEN (sum(itens.valor_vendido_total) > (0)::numeric) THEN (((sum(itens.valor_vendido_total) - COALESCE(sum(itens.valor_compra_total), (0)::numeric)) / sum(itens.valor_vendido_total)) * (100)::numeric)
            ELSE NULL::numeric
        END AS margem_perc,
        CASE
            WHEN bool_and((itens.status_envio = 'ENVIADO'::text)) THEN 'TODOS_ENVIADOS'::text
            WHEN bool_or((itens.status_envio = 'ENVIADO'::text)) THEN 'PARCIAL_ENVIADO'::text
            ELSE 'PENDENTE'::text
        END AS status_envio_geral,
    array_agg(DISTINCT itens.status_pagamento) FILTER (WHERE (itens.status_pagamento IS NOT NULL)) AS status_pagamento_itens,
    array_agg(DISTINCT itens.fornecedor) FILTER (WHERE (itens.fornecedor IS NOT NULL)) AS fornecedores,
    min(itens.criado_em) AS criado_em,
    max(itens.atualizado_em) AS atualizado_em
   FROM itens
  GROUP BY itens.pedido_pai;


