COMMENT ON VIEW vendas.vw_pedidos_pai IS 'Agregação de vendas.ordens_compra por pedido_pai. Cada linha = 1 pedido (capa).';


--
-- Name: vw_produtos_sem_codigo; Type: VIEW; Schema: vendas; Owner: -
--

CREATE VIEW vendas.vw_produtos_sem_codigo WITH (security_invoker='on') AS
 SELECT max(ordens_compra.produto) AS exemplo_nome_produto,
    max(ordens_compra.fornecedor) AS fornecedor_principal,
    count(*) AS qtd_ocorrencias,
    count(DISTINCT ordens_compra.pedido) AS qtd_pedidos_afetados,
    min(ordens_compra.data_venda) AS primeira_ocorrencia,
    max(ordens_compra.data_venda) AS ultima_ocorrencia
   FROM vendas.ordens_compra
  WHERE ((ordens_compra.cod_produto IS NULL) AND (ordens_compra.excluido_em IS NULL) AND (ordens_compra.produto IS NOT NULL))
  GROUP BY (upper(TRIM(BOTH FROM ordens_compra.produto)))
  ORDER BY (count(*)) DESC;


--
-- Name: VIEW vw_produtos_sem_codigo; Type: COMMENT; Schema: vendas; Owner: -
--

COMMENT ON VIEW vendas.vw_produtos_sem_codigo IS '[Onda NF] Lista de itens sem cod_produto agrupados por nome. Esses 195 casos precisam de cadastro manual de NCM via produtos_ncm_mapa ou correção do cod_produto.';


--
-- Name: vw_produtos_sem_ncm; Type: VIEW; Schema: vendas; Owner: -
--

CREATE VIEW vendas.vw_produtos_sem_ncm WITH (security_invoker='on') AS
 SELECT ordens_compra.cod_produto,
    max(ordens_compra.produto) AS exemplo_nome_produto,
    max(ordens_compra.fornecedor) AS fornecedor_principal,
    count(*) AS qtd_ocorrencias,
    count(DISTINCT ordens_compra.pedido) AS qtd_pedidos_afetados,
    round(sum(ordens_compra.valor_compra_total), 2) AS valor_compra_total_acumulado,
    min(ordens_compra.data_venda) AS primeira_ocorrencia,
    max(ordens_compra.data_venda) AS ultima_ocorrencia
   FROM vendas.ordens_compra
  WHERE ((ordens_compra.ncm IS NULL) AND (ordens_compra.excluido_em IS NULL) AND (ordens_compra.cod_produto IS NOT NULL))
  GROUP BY ordens_compra.cod_produto
  ORDER BY (count(*)) DESC;


--
-- Name: VIEW vw_produtos_sem_ncm; Type: COMMENT; Schema: vendas; Owner: -
--

COMMENT ON VIEW vendas.vw_produtos_sem_ncm IS '[Onda NF] Lista de produtos que ainda precisam ter NCM cadastrado. Agrupado por cod_produto. Usado pelo fluxo n8n de descoberta e pela tela de gestão de NCMs.';


--
-- Name: vw_status_ncm; Type: VIEW; Schema: vendas; Owner: -
--

CREATE VIEW vendas.vw_status_ncm WITH (security_invoker='on') AS
 WITH stats AS (
         SELECT count(*) AS total_itens,
            count(*) FILTER (WHERE (ordens_compra.ncm IS NOT NULL)) AS com_ncm,
            count(*) FILTER (WHERE (ordens_compra.ncm IS NULL)) AS sem_ncm,
            count(*) FILTER (WHERE ((ordens_compra.ncm IS NULL) AND (ordens_compra.cod_produto IS NOT NULL))) AS sem_ncm_com_sku,
            count(*) FILTER (WHERE ((ordens_compra.ncm IS NULL) AND (ordens_compra.cod_produto IS NULL))) AS sem_ncm_sem_sku,
            count(DISTINCT ordens_compra.cod_produto) FILTER (WHERE ((ordens_compra.ncm IS NOT NULL) AND (ordens_compra.cod_produto IS NOT NULL))) AS skus_unicos_com_ncm,
            count(DISTINCT ordens_compra.cod_produto) FILTER (WHERE ((ordens_compra.ncm IS NULL) AND (ordens_compra.cod_produto IS NOT NULL))) AS skus_unicos_sem_ncm
           FROM vendas.ordens_compra
          WHERE (ordens_compra.excluido_em IS NULL)
        ), mapa AS (
         SELECT count(*) AS skus_mapeados,
            count(*) FILTER (WHERE (produtos_ncm_mapa.validado = true)) AS skus_validados,
            count(*) FILTER (WHERE (produtos_ncm_mapa.origem = 'manual'::text)) AS origem_manual,
            count(*) FILTER (WHERE (produtos_ncm_mapa.origem ~~ 'ia%'::text)) AS origem_ia,
            count(*) FILTER (WHERE (produtos_ncm_mapa.origem = 'bling_api'::text)) AS origem_bling
           FROM vendas.produtos_ncm_mapa
        ), fontes AS (
         SELECT ordens_compra.ncm_fonte,
            count(*) AS qtd
           FROM vendas.ordens_compra
          WHERE ((ordens_compra.excluido_em IS NULL) AND (ordens_compra.ncm IS NOT NULL))
          GROUP BY ordens_compra.ncm_fonte
        )
 SELECT s.total_itens,
    s.com_ncm,
    s.sem_ncm,
    round((((s.com_ncm)::numeric / (NULLIF(s.total_itens, 0))::numeric) * (100)::numeric), 1) AS pct_cobertura,
    s.sem_ncm_com_sku,
    s.sem_ncm_sem_sku,
    s.skus_unicos_com_ncm,
    s.skus_unicos_sem_ncm,
    m.skus_mapeados,
    m.skus_validados,
    m.origem_manual,
    m.origem_ia,
    m.origem_bling,
    ( SELECT jsonb_object_agg(fontes.ncm_fonte, fontes.qtd) AS jsonb_object_agg
           FROM fontes) AS distribuicao_fontes
   FROM (stats s
     CROSS JOIN mapa m);


