--
-- Name: cookies_health_dashboard; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.cookies_health_dashboard WITH (security_invoker='on') AS
 SELECT cookies_config.id,
    cookies_config.servico,
    cookies_config.health_status,
    cookies_config.is_healthy,
        CASE
            WHEN ((cookies_config.expires_at IS NULL) AND (cookies_config.atualizado_em IS NOT NULL)) THEN (('Sem expiração configurada — última atualização há '::text || round((EXTRACT(epoch FROM (now() - cookies_config.atualizado_em)) / (86400)::numeric))) || ' dias'::text)
            WHEN (cookies_config.expires_at < now()) THEN (('EXPIRADO há '::text || round((EXTRACT(epoch FROM (now() - cookies_config.expires_at)) / (86400)::numeric))) || ' dias'::text)
            WHEN (cookies_config.expires_at < (now() + ((cookies_config.alerta_dias_antes || ' days'::text))::interval)) THEN (('EXPIRANDO EM '::text || round((EXTRACT(epoch FROM (cookies_config.expires_at - now())) / (86400)::numeric))) || ' dias'::text)
            ELSE (('Válido por mais '::text || round((EXTRACT(epoch FROM (cookies_config.expires_at - now())) / (86400)::numeric))) || ' dias'::text)
        END AS status_legivel,
    (round((EXTRACT(epoch FROM (now() - cookies_config.atualizado_em)) / (86400)::numeric)))::integer AS dias_desde_atualizacao,
    cookies_config.expires_at,
    cookies_config.atualizado_em AS ultima_atualizacao,
    cookies_config.last_health_check_at AS ultimo_health_check,
    cookies_config.health_error AS ultimo_erro,
    cookies_config.nota,
    cookies_config.alerta_dias_antes
   FROM zapp.cookies_config
  ORDER BY
        CASE cookies_config.health_status
            WHEN 'error'::text THEN 0
            WHEN 'expired'::text THEN 1
            WHEN 'expiring_soon'::text THEN 2
            WHEN 'unknown'::text THEN 3
            WHEN 'healthy'::text THEN 4
            ELSE NULL::integer
        END;


--
-- Name: VIEW cookies_health_dashboard; Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON VIEW zapp.cookies_health_dashboard IS 'Dashboard de saúde dos cookies. Mostra status legível e dias até expiração.';


