    email_threads.created_at,
    email_threads.gmail_account_id,
    email_threads.gmail_thread_id,
    email_threads.id,
    email_threads.is_important,
    email_threads.is_starred,
    email_threads.is_unread,
    email_threads.label_ids,
    email_threads.last_message_at,
    email_threads.message_count,
    email_threads.priority,
    email_threads.snippet,
    email_threads.status,
    email_threads.subject,
    email_threads.tags,
    email_threads.updated_at,
    email_threads.id AS thread_id,
    email_threads.gmail_thread_id AS email_thread_id,
    email_threads.gmail_account_id AS account_id,
        CASE
            WHEN email_threads.is_unread THEN GREATEST(COALESCE(email_threads.message_count, 1), 1)
            ELSE 0
        END AS unread_count,
    email_threads.first_reply_at,
    email_threads.frt_minutes,
    email_threads.sla_status
   FROM email_app.email_threads;


