--
-- Name: email_tracking_summary; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.email_tracking_summary WITH (security_invoker='on') AS
 SELECT m.user_id,
    count(*) AS total_tracked,
    count(*) FILTER (WHERE (m.open_count > 0)) AS total_opened,
    count(*) FILTER (WHERE (m.click_count > 0)) AS total_clicked,
    count(*) FILTER (WHERE (m.delivery_status = 'bounced'::text)) AS total_bounced,
    count(*) FILTER (WHERE (m.delivery_status = 'failed'::text)) AS total_failed,
    COALESCE(sum(m.open_count), (0)::bigint) AS sum_opens,
    COALESCE(sum(m.click_count), (0)::bigint) AS sum_clicks,
    round((((count(*) FILTER (WHERE (m.open_count > 0)))::numeric / (NULLIF(count(*), 0))::numeric) * (100)::numeric), 1) AS open_rate,
    round((((count(*) FILTER (WHERE (m.click_count > 0)))::numeric / (NULLIF(count(*) FILTER (WHERE (m.open_count > 0)), 0))::numeric) * (100)::numeric), 1) AS click_through_rate,
    min(m.created_at) AS first_tracked_at,
    max(m.created_at) AS last_tracked_at
   FROM email_app.email_tracked_messages m
  GROUP BY m.user_id;


