    first_response_time numeric(10,2),
    resolution_rate numeric(5,2) DEFAULT 0 NOT NULL,
    customer_satisfaction numeric(4,2) DEFAULT 0 NOT NULL,
    "timestamp" timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT queue_analytics_customer_satisfaction_check CHECK (((customer_satisfaction >= (0)::numeric) AND (customer_satisfaction <= (5)::numeric))),
    CONSTRAINT queue_analytics_resolution_rate_check CHECK (((resolution_rate >= (0)::numeric) AND (resolution_rate <= (100)::numeric)))
);

