--
-- Name: v_active_alerts; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_active_alerts WITH (security_invoker='on') AS
 SELECT evolution_alerts.id,
    evolution_alerts.alert_type,
    evolution_alerts.severity,
    evolution_alerts.message,
    evolution_alerts.payload,
    evolution_alerts.acknowledged,
    evolution_alerts.acknowledged_at,
    evolution_alerts.acknowledged_by,
    evolution_alerts.created_at
   FROM evo.evolution_alerts
  WHERE (evolution_alerts.acknowledged = false)
  ORDER BY
        CASE evolution_alerts.severity
            WHEN 'critical'::text THEN 1
            WHEN 'warning'::text THEN 2
            ELSE 3
        END, evolution_alerts.created_at DESC;


