    sc.first_response_minutes,
    sc.resolution_minutes,
    count(cs.id) AS total_conversations,
    count(cs.id) FILTER (WHERE (cs.first_response_breached = true)) AS first_response_breaches,
    count(cs.id) FILTER (WHERE (cs.resolution_breached = true)) AS resolution_breaches,
    count(cs.id) FILTER (WHERE (cs.resolved_at IS NOT NULL)) AS resolved_count,
    round(((100.0 * (count(cs.id) FILTER (WHERE (cs.first_response_breached = false)))::numeric) / (NULLIF(count(cs.id), 0))::numeric), 2) AS first_response_compliance_pct,
    round(((100.0 * (count(cs.id) FILTER (WHERE (cs.resolution_breached = false)))::numeric) / (NULLIF(count(cs.id), 0))::numeric), 2) AS resolution_compliance_pct,
    now() AS snapshot_at
   FROM ((zapp.sla_configurations sc
     LEFT JOIN zapp.conversation_sla cs ON ((cs.sla_configuration_id = sc.id)))
     LEFT JOIN zapp.queues q ON ((q.sla_policy_id = sc.id)))
  WHERE (sc.is_active = true)
  GROUP BY q.id, q.name, q.priority, sc.id, sc.name, sc.first_response_minutes, sc.resolution_minutes;


--
-- Name: v_alert_channels_health; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_alert_channels_health WITH (security_invoker='on') AS
 SELECT ac.id,
    ac.name,
    ac.channel_type,
    ac.is_active,
    ac.min_severity,
    COALESCE(( SELECT count(*) AS count
           FROM evo.evolution_alerts ea
          WHERE ((ea.created_at >= (now() - '24:00:00'::interval)) AND (ea.acknowledged = false) AND (ea.severity = ac.min_severity))), (0)::bigint) AS pending_alerts_24h,
        CASE
            WHEN ac.is_active THEN 'operational'::text
            ELSE 'disabled'::text
        END AS status,
    ac.created_at
   FROM zapp.alert_channels ac;


--
-- Name: v_alerts_active; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_alerts_active WITH (security_invoker='on') AS
 SELECT evolution_alerts.id,
    evolution_alerts.alert_type,
    evolution_alerts.severity,
    evolution_alerts.message,
    evolution_alerts.payload,
    evolution_alerts.acknowledged,
    evolution_alerts.created_at,
    evolution_alerts.resolved_at,
    'evolution'::text AS source
   FROM evo.evolution_alerts
  WHERE ((evolution_alerts.acknowledged = false) AND (evolution_alerts.resolved_at IS NULL))
UNION ALL
 SELECT security_alerts.id,
    security_alerts.alert_type,
    security_alerts.severity,
    security_alerts.description AS message,
    security_alerts.metadata AS payload,
    false AS acknowledged,
    security_alerts.created_at,
    security_alerts.resolved_at,
    'security'::text AS source
   FROM zapp.security_alerts
  WHERE ((security_alerts.is_resolved = false) OR (security_alerts.is_resolved IS NULL))
  ORDER BY 7 DESC;


--
-- Name: v_all_consent_audit; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_all_consent_audit WITH (security_invoker='on') AS
 SELECT lgpd_consent_audit.id,
    lgpd_consent_audit.contact_id,
    lgpd_consent_audit.consent_type,
    lgpd_consent_audit.given_at,
    lgpd_consent_audit.withdrawn_at,
    lgpd_consent_audit.verified_by_user_id,
    lgpd_consent_audit.audit_timestamp,
    now() AS archived_at,
    NULL::uuid AS archived_batch_id,
    'hot'::text AS storage_tier
   FROM zapp.lgpd_consent_audit
UNION ALL
 SELECT lgpd_consent_audit_archive.id,
    lgpd_consent_audit_archive.contact_id,
    lgpd_consent_audit_archive.consent_type,
    lgpd_consent_audit_archive.given_at,
    lgpd_consent_audit_archive.withdrawn_at,
    lgpd_consent_audit_archive.verified_by_user_id,
    lgpd_consent_audit_archive.audit_timestamp,
    lgpd_consent_audit_archive.archived_at,
    lgpd_consent_audit_archive.archived_batch_id,
    'archive'::text AS storage_tier
   FROM zapp.lgpd_consent_audit_archive;


--
-- Name: v_audio_memes_catalog; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_audio_memes_catalog WITH (security_invoker='on') AS
 SELECT audio_memes.category,
    count(*) AS total_memes,
    count(*) FILTER (WHERE audio_memes.is_favorite) AS favoritos,
    sum(audio_memes.use_count) AS total_usos,
    round(avg(audio_memes.duration_seconds), 1) AS avg_duration_s
   FROM zapp.audio_memes
  GROUP BY audio_memes.category
  ORDER BY (sum(audio_memes.use_count)) DESC NULLS LAST;


--
-- Name: v_audio_memes_full; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_audio_memes_full WITH (security_invoker='on') AS
 SELECT am.id,
    am.name,
    am.audio_url,
    am.category,
    am.duration_seconds,
    am.is_favorite,
    am.use_count,
    am.uploaded_by,
    am.created_at,
    COALESCE(msg.send_count, (0)::bigint) AS real_send_count
   FROM (zapp.audio_memes am
     LEFT JOIN ( SELECT evolution_messages.audio_meme_id,
            count(*) AS send_count
           FROM evo.evolution_messages
          WHERE (evolution_messages.audio_meme_id IS NOT NULL)
          GROUP BY evolution_messages.audio_meme_id) msg ON ((msg.audio_meme_id = am.id)))
  ORDER BY am.use_count DESC;


--
-- Name: v_backfill_stats; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_backfill_stats WITH (security_invoker='on') AS
 SELECT count(*) AS total_jids,
    count(*) FILTER (WHERE (audit_backfill_progress.status = 'pending'::text)) AS pending,
    count(*) FILTER (WHERE (audit_backfill_progress.status = 'fetching'::text)) AS fetching,
    count(*) FILTER (WHERE (audit_backfill_progress.status = 'ingesting'::text)) AS ingesting,
    count(*) FILTER (WHERE (audit_backfill_progress.status = 'completed'::text)) AS completed,
    count(*) FILTER (WHERE (audit_backfill_progress.status = 'error'::text)) AS errors,
    sum(audit_backfill_progress.source_msg_count) AS total_source_msgs,
    sum(audit_backfill_progress.records_ingested) FILTER (WHERE (audit_backfill_progress.status = 'completed'::text)) AS total_ingested,
    round(((100.0 * (count(*) FILTER (WHERE (audit_backfill_progress.status = 'completed'::text)))::numeric) / (NULLIF(count(*), 0))::numeric), 2) AS pct_done
   FROM archive.audit_backfill_progress;


--
-- Name: v_complete_dashboard; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_complete_dashboard WITH (security_invoker='on') AS
 SELECT ( SELECT count(*) AS count
           FROM evo.evolution_contacts
          WHERE (evolution_contacts.deleted_at IS NULL)) AS total_contacts,
    ( SELECT count(*) AS count
           FROM evo.evolution_messages) AS total_messages,
    ( SELECT count(*) AS count
           FROM evo.evolution_conversations) AS total_conversations,
    ( SELECT COALESCE(sum(evolution_deals.value), (0)::numeric) AS "coalesce"
           FROM evo.evolution_deals
          WHERE ((evolution_deals.stage)::text <> ALL ((ARRAY['perdido'::character varying, 'pedido_finalizado'::character varying])::text[]))) AS pipeline_value;


--
-- Name: v_connection_drift_score; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_connection_drift_score WITH (security_invoker='on') AS
 WITH last_reconcile AS (
         SELECT max(evolution_reconcile_jobs.applied_at) AS last_applied
           FROM evo.evolution_reconcile_jobs
          WHERE (evolution_reconcile_jobs.applied_at IS NOT NULL)
        ), last_state_changes AS (
         SELECT evolution_connection_history.instance_name,
            max(evolution_connection_history.created_at) AS last_change
           FROM evo.evolution_connection_history
          GROUP BY evolution_connection_history.instance_name
        )
 SELECT wc.instance_name,
    wc.name,
    wc.status,
    wc.health_status,
    wc.health_reason,
    wc.phone_number,
    wc.is_active,
    wc.last_health_check,
    (EXTRACT(epoch FROM (now() - wc.last_health_check)))::integer AS health_check_age_seconds,
        CASE
            WHEN (wc.last_health_check IS NULL) THEN 'never_checked'::text
            WHEN (wc.last_health_check < (now() - '00:15:00'::interval)) THEN 'stale'::text
            WHEN (wc.health_status = 'ok'::text) THEN 'healthy'::text
            WHEN (wc.health_status = 'degraded'::text) THEN 'degraded'::text
            WHEN (wc.health_status = ANY (ARRAY['down'::text, 'unknown'::text])) THEN 'unhealthy'::text
            ELSE 'unknown'::text
        END AS drift_classification,
    lsc.last_change AS last_status_change,
    ( SELECT last_reconcile.last_applied
           FROM last_reconcile) AS last_reconcile_at,
    (EXTRACT(epoch FROM (now() - ( SELECT last_reconcile.last_applied
           FROM last_reconcile))))::integer AS reconcile_age_seconds
   FROM (zapp.whatsapp_connections wc
     LEFT JOIN last_state_changes lsc ON ((lsc.instance_name = wc.instance_name)))
  ORDER BY wc.is_default DESC, wc.instance_name;


--
-- Name: VIEW v_connection_drift_score; Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON VIEW zapp.v_connection_drift_score IS 'KPI executivo de saúde das conexões WhatsApp. Classifica cada instância em healthy/degraded/unhealthy/stale/never_checked baseado em health_status + idade do health_check. Para uso em dashboards e gates anti-regressão.';


--
-- Name: v_connection_uptime; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_connection_uptime WITH (security_invoker='on') AS
 SELECT evolution_connection_history.instance_name,
    count(*) FILTER (WHERE (evolution_connection_history.state = 'open'::text)) AS times_connected,
    count(*) FILTER (WHERE (evolution_connection_history.state = 'close'::text)) AS times_disconnected,
    COALESCE(sum(evolution_connection_history.duration_seconds) FILTER (WHERE (evolution_connection_history.state = 'open'::text)), (0)::bigint) AS total_uptime_seconds,
    COALESCE(sum(evolution_connection_history.duration_seconds) FILTER (WHERE (evolution_connection_history.state = 'close'::text)), (0)::bigint) AS total_downtime_seconds,
    round(((100.0 * (COALESCE(sum(evolution_connection_history.duration_seconds) FILTER (WHERE (evolution_connection_history.state = 'open'::text)), (0)::bigint))::numeric) / (NULLIF(sum(evolution_connection_history.duration_seconds), 0))::numeric), 2) AS uptime_percentage
   FROM evo.evolution_connection_history
  WHERE (evolution_connection_history.created_at > (now() - '7 days'::interval))
  GROUP BY evolution_connection_history.instance_name;


--
-- Name: v_contact_360; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_contact_360 WITH (security_invoker='on') AS
 SELECT c.id,
    c.remote_jid,
    COALESCE(c.full_name, c.push_name) AS nome,
    c.phone_number,
    c.company,
    c.lead_status,
    c.lead_score,
    c.total_messages,
    c.last_message_at,
    c.assigned_to,
    ( SELECT json_agg(DISTINCT m.instance_name) AS json_agg
           FROM evo.evolution_messages m
          WHERE (m.contact_id = c.id)) AS instancias_interacao,
    ( SELECT json_agg(json_build_object('dept', ir.department, 'instance', ir.instance_name, 'last_msg', sub.last_msg)) AS json_agg
           FROM (( SELECT DISTINCT evolution_messages.instance_name,
                    max(evolution_messages.created_at) AS last_msg
                   FROM evo.evolution_messages
                  WHERE (evolution_messages.contact_id = c.id)
                  GROUP BY evolution_messages.instance_name) sub
             JOIN zapp.instance_registry ir ON (((ir.instance_name)::text = (sub.instance_name)::text)))) AS departamentos_contato,
    ( SELECT count(*) AS count
           FROM evo.evolution_deals d
          WHERE ((d.contact_id = c.id) AND ((d.stage)::text <> ALL (ARRAY[('perdido'::character varying)::text, ('pedido_finalizado'::character varying)::text])))) AS deals_ativos,
    ( SELECT COALESCE(sum(d.value), (0)::numeric) AS "coalesce"
           FROM evo.evolution_deals d
          WHERE ((d.contact_id = c.id) AND ((d.stage)::text <> ALL (ARRAY[('perdido'::character varying)::text, ('pedido_finalizado'::character varying)::text])))) AS pipeline_value
   FROM evo.evolution_contacts c
  WHERE (c.deleted_at IS NULL);


--
-- Name: v_contacts_by_tag; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_contacts_by_tag WITH (security_invoker='on') AS
 SELECT t.name AS tag_name,
    t.color,
    count(DISTINCT ta.entity_id) AS contact_count,
    array_agg(DISTINCT c.phone_number) FILTER (WHERE (c.phone_number IS NOT NULL)) AS phones
   FROM ((evo.evolution_tags t
     JOIN evo.evolution_tag_assignments ta ON (((t.id = ta.tag_id) AND ((ta.entity_type)::text = 'contact'::text))))
     JOIN evo.evolution_contacts c ON ((ta.entity_id = c.id)))
  GROUP BY t.id, t.name, t.color
  ORDER BY (count(DISTINCT ta.entity_id)) DESC;


--
-- Name: v_contacts_with_legacy; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_contacts_with_legacy WITH (security_invoker='on') AS
 SELECT evolution_contacts.id,
    evolution_contacts.remote_jid,
    evolution_contacts.phone_number,
    evolution_contacts.push_name,
    evolution_contacts.profile_picture_url,
    evolution_contacts.full_name,
    evolution_contacts.email,
    evolution_contacts.company,
    evolution_contacts.role_title,
    evolution_contacts.lead_status,
    evolution_contacts.lead_source,
    evolution_contacts.lead_score,
    evolution_contacts.whatsapp_labels,
    evolution_contacts.tags,
    evolution_contacts.assigned_to,
    evolution_contacts.first_contact_at,
    evolution_contacts.last_message_at,
    evolution_contacts.total_messages,
    evolution_contacts.total_purchases,
    evolution_contacts.notes,
    evolution_contacts.instance_name,
    evolution_contacts.raw_data,
    evolution_contacts.created_at,
    evolution_contacts.updated_at,
    evolution_contacts.deleted_at,
    evolution_contacts.message_count
   FROM evo.evolution_contacts
  WHERE (evolution_contacts.deleted_at IS NULL);


--
-- Name: v_cookie_health; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_cookie_health WITH (security_invoker='on') AS
 SELECT c.servico,
    c.is_healthy,
    c.health_status,
    c.last_health_check_at,
    c.health_error,
    c.expires_at,
    p.http_status AS last_probe_http,
    p.probe_ms AS last_probe_ms,
    p.response_preview AS last_probe_preview,
    (EXTRACT(epoch FROM (now() - c.last_health_check_at)) / (60)::numeric) AS mins_since_probe,
        CASE
            WHEN (c.last_health_check_at < (now() - '00:35:00'::interval)) THEN true
            ELSE false
        END AS probe_stale
   FROM (zapp.cookies_config c
     LEFT JOIN LATERAL ( SELECT cookie_probe_log.http_status,
            cookie_probe_log.probe_ms,
            cookie_probe_log.response_preview
           FROM zapp.cookie_probe_log
          WHERE (cookie_probe_log.servico = c.servico)
          ORDER BY cookie_probe_log.probed_at DESC
         LIMIT 1) p ON (true))
  ORDER BY c.servico;


--
-- Name: v_cron_status; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_cron_status WITH (security_invoker='on') AS
 SELECT evolution_settings.key AS job_name,
    evolution_settings.value AS schedule,
    evolution_settings.description,
        CASE
            WHEN (evolution_settings.key = 'cron_process_queue'::text) THEN ( SELECT count(*) AS count
               FROM evo.evolution_message_queue
              WHERE ((evolution_message_queue.status)::text = 'pending'::text))
            WHEN (evolution_settings.key = 'cron_check_tasks'::text) THEN ( SELECT count(*) AS count
               FROM evo.evolution_tasks
              WHERE (((evolution_tasks.status)::text = 'pending'::text) AND (evolution_tasks.due_date < CURRENT_DATE)))
            ELSE (0)::bigint
        END AS items_pending,
    evolution_settings.updated_at AS last_config_update
   FROM evo.evolution_settings
  WHERE (evolution_settings.key ~~ 'cron_%'::text);


--
-- Name: v_daily_sales_summary; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_daily_sales_summary WITH (security_invoker='on') AS
 SELECT date(evolution_deals.created_at) AS date,
    count(*) AS new_deals,
    sum(evolution_deals.value) AS total_value,
    sum(
        CASE
            WHEN ((evolution_deals.stage)::text = 'pago'::text) THEN evolution_deals.value
            ELSE (0)::numeric
        END) AS closed_value,
    sum(
        CASE
            WHEN ((evolution_deals.stage)::text = 'perdido'::text) THEN evolution_deals.value
            ELSE (0)::numeric
        END) AS lost_value,
    count(
        CASE
            WHEN ((evolution_deals.stage)::text = 'pago'::text) THEN 1
            ELSE NULL::integer
        END) AS won_count,
    count(
        CASE
            WHEN ((evolution_deals.stage)::text = 'perdido'::text) THEN 1
            ELSE NULL::integer
        END) AS lost_count
   FROM evo.evolution_deals
  WHERE (evolution_deals.created_at >= (now() - '30 days'::interval))
  GROUP BY (date(evolution_deals.created_at))
  ORDER BY (date(evolution_deals.created_at)) DESC;


--
-- Name: v_deleted_contacts; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_deleted_contacts WITH (security_invoker='on') AS
 SELECT evolution_contacts.id,
    evolution_contacts.push_name AS name,
    evolution_contacts.phone_number AS phone,
    evolution_contacts.email,
    evolution_contacts.last_message_at AS deleted_at,
    evolution_contacts.instance_name
   FROM evo.evolution_contacts
  WHERE ((evolution_contacts.lead_status)::text = 'deleted'::text);


--
-- Name: v_department_volume; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_department_volume WITH (security_invoker='on') AS
 SELECT ir.department,
    count(DISTINCT ir.instance_name) AS instancias,
    array_agg(ir.instance_name ORDER BY ir.instance_name) AS instance_names
   FROM zapp.instance_registry ir
  WHERE (ir.is_active = true)
  GROUP BY ir.department
  ORDER BY ir.department;


--
-- Name: v_dr_runbook; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_dr_runbook WITH (security_invoker='on') AS
 SELECT t.step_number,
    t.category,
    t.title,
    t.description,
    t.command_hint,
    t.estimated_minutes,
    t.severity,
    t.is_automated,
    t.created_at
   FROM ( VALUES (1,'database'::text,'Verificar saúde do banco'::text,'Checar conexões, dead tuples e locks ativos'::text,'SELECT * FROM public.fn_system_health_score()'::text,2,'critical'::text,true,now()), (2,'api'::text,'Verificar Evolution API'::text,'Confirmar que a instância wpp2 está conectada e respondendo'::text,'GET /instance/connectionState/wpp2'::text,3,'critical'::text,false,now()), (3,'pipeline'::text,'Checar pipeline de webhooks'::text,'Confirmar que eventos estão fluindo via RabbitMQ → Supabase'::text,'SELECT * FROM public.v_webhook_health'::text,2,'high'::text,true,now()), (4,'storage'::text,'Verificar R2 Cloudflare'::text,'Testar upload de arquivo de teste no bucket zapp-whatsapp-media'::text,'aws s3 ls s3://zapp-whatsapp-media --endpoint...'::text,5,'high'::text,false,now()), (5,'alerts'::text,'Verificar canais de alerta'::text,'Confirmar que canais WhatsApp/Discord/Email respondem'::text,'SELECT * FROM public.fn_test_alert_channel(1)'::text,3,'medium'::text,true,now()), (6,'vacuum'::text,'Manutenção do banco'::text,'Rodar VACUUM ANALYZE nas tabelas críticas se dead_pct > 10%'::text,'VACUUM ANALYZE public.webhook_events_processed'::text,5,'medium'::text,false,now()), (7,'cron'::text,'Verificar cron jobs'::text,'Confirmar que todos os jobs estão ativos e sem timeout recente'::text,'SELECT * FROM cron.job WHERE active = true'::text,2,'medium'::text,true,now()), (8,'app'::text,'Verificar Zapp Web'::text,'Confirmar que todos os endpoints de health respondem 200'::text,'curl https://zapp.promobrindes.com.br/health'::text,1,'low'::text,false,now())) t(step_number, category, title, description, command_hint, estimated_minutes, severity, is_automated, created_at);


--
-- Name: v_email_accounts_unified; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_email_accounts_unified WITH (security_invoker='on') AS
 SELECT gmail_accounts.id,
    'gmail'::text AS provider,
    gmail_accounts.created_at
   FROM email_app.gmail_accounts;


--
-- Name: v_evolution_dlq_open; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_evolution_dlq_open WITH (security_invoker='on') AS
 SELECT evolution_webhook_dlq.id,
    evolution_webhook_dlq.created_at,
    evolution_webhook_dlq.event_type,
    evolution_webhook_dlq.instance_name,
    evolution_webhook_dlq.remote_jid,
    evolution_webhook_dlq.status,
    evolution_webhook_dlq.retry_count,
    evolution_webhook_dlq.max_retries,
    evolution_webhook_dlq.next_retry_at,
    "left"(evolution_webhook_dlq.error_message, 300) AS error_message_preview,
        CASE
            WHEN (evolution_webhook_dlq.retry_count >= COALESCE(evolution_webhook_dlq.max_retries, 10)) THEN true
            ELSE false
        END AS exhausted,
    (EXTRACT(epoch FROM (now() - evolution_webhook_dlq.created_at)))::integer AS age_seconds
   FROM evo.evolution_webhook_dlq
  WHERE (evolution_webhook_dlq.status <> 'resolved'::text)
  ORDER BY evolution_webhook_dlq.created_at DESC;


--
-- Name: v_evolution_pipeline_dashboard; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_evolution_pipeline_dashboard WITH (security_invoker='on') AS
 SELECT now() AS checked_at,
    ( SELECT count(*) AS count
           FROM evo.active_messages
          WHERE (active_messages.created_at > (now() - '00:05:00'::interval))) AS msgs_5min,
    ( SELECT count(*) AS count
           FROM evo.active_messages
          WHERE (active_messages.created_at > (now() - '01:00:00'::interval))) AS msgs_1h,
    ( SELECT count(*) AS count
           FROM evo.active_messages
          WHERE (active_messages.created_at > (now() - '24:00:00'::interval))) AS msgs_24h,
    ( SELECT max(active_messages.created_at) AS max
           FROM evo.active_messages) AS last_message_at,
    ( SELECT count(*) AS count
           FROM zapp.webhook_audit_log
          WHERE ((webhook_audit_log.status = 'processed'::text) AND (webhook_audit_log.created_at > (now() - '00:05:00'::interval)))) AS audit_processed_5min,
    ( SELECT count(*) AS count
           FROM zapp.webhook_audit_log
          WHERE ((webhook_audit_log.status = 'rejected'::text) AND (webhook_audit_log.created_at > (now() - '00:05:00'::interval)))) AS audit_rejected_5min,
    ( SELECT count(*) AS count
           FROM zapp.webhook_audit_log
          WHERE (webhook_audit_log.created_at > (now() - '24:00:00'::interval))) AS audit_total_24h,
    ( SELECT round(avg(webhook_audit_log.duration_ms), 1) AS round
           FROM zapp.webhook_audit_log
          WHERE ((webhook_audit_log.status = 'processed'::text) AND (webhook_audit_log.created_at > (now() - '01:00:00'::interval)))) AS avg_duration_ms_1h,
    ( SELECT count(*) AS count
           FROM evo.evolution_alerts
          WHERE ((evolution_alerts.acknowledged = false) AND (evolution_alerts.created_at > (now() - '24:00:00'::interval)))) AS open_alerts_24h,
    pg_size_pretty(pg_database_size('postgres'::name)) AS db_size,
    ( SELECT count(*) AS count
           FROM evo.active_messages) AS total_messages_ever;


--
-- Name: v_evolution_source_tables_summary; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_evolution_source_tables_summary WITH (security_invoker='on') AS
 SELECT evolution_source_schema_map.table_name,
    max(evolution_source_schema_map.row_count_est) AS rows,
    count(*) AS num_columns,
    count(*) FILTER (WHERE (evolution_source_schema_map.data_type = 'jsonb'::text)) AS jsonb_cols,
    count(*) FILTER (WHERE (evolution_source_schema_map.data_type ~~ '%timestamp%'::text)) AS timestamp_cols,
        CASE
            WHEN (max(evolution_source_schema_map.row_count_est) >= 100000) THEN 'critical'::text
            WHEN (max(evolution_source_schema_map.row_count_est) >= 1000) THEN 'active'::text
            WHEN (max(evolution_source_schema_map.row_count_est) >= 1) THEN 'populated'::text
            ELSE 'empty'::text
        END AS status,
    max(evolution_source_schema_map.discovered_at) AS last_discovered
   FROM evo.evolution_source_schema_map
  GROUP BY evolution_source_schema_map.table_name
  ORDER BY (max(evolution_source_schema_map.row_count_est)) DESC;


