--
-- Name: v_guardrail_dashboard; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_guardrail_dashboard WITH (security_invoker='on') AS
 SELECT date(g.created_at) AS day,
    g.workspace_id,
    g.direction,
    count(*) AS total_checks,
    count(*) FILTER (WHERE (g.all_passed = true)) AS passed,
    count(*) FILTER (WHERE (g.all_passed = false)) AS blocked,
    round(avg(g.latency_ms), 1) AS avg_latency_ms
   FROM ai.guardrail_ml_logs g
  GROUP BY (date(g.created_at)), g.workspace_id, g.direction;


--
-- Name: v_hourly_metrics; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_hourly_metrics WITH (security_invoker='on') AS
 SELECT date_trunc('hour'::text, evolution_messages.created_at) AS hora,
    count(*) AS total,
    count(*) FILTER (WHERE ((evolution_messages.direction)::text = 'inbound'::text)) AS inbound,
    count(*) FILTER (WHERE ((evolution_messages.direction)::text = 'outbound'::text)) AS outbound
   FROM evo.evolution_messages
  WHERE (evolution_messages.created_at >= (now() - '24:00:00'::interval))
  GROUP BY (date_trunc('hour'::text, evolution_messages.created_at))
  ORDER BY (date_trunc('hour'::text, evolution_messages.created_at));


