--
-- Name: v_realtime_dashboard; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_realtime_dashboard WITH (security_invoker='on') AS
 SELECT ( SELECT count(*) AS count
           FROM evo.evolution_contacts
          WHERE (evolution_contacts.deleted_at IS NULL)) AS total_contatos,
    ( SELECT count(*) AS count
           FROM evo.evolution_contacts
          WHERE ((evolution_contacts.deleted_at IS NULL) AND (evolution_contacts.created_at >= (now() - '7 days'::interval)))) AS novos_7d,
    ( SELECT count(*) AS count
           FROM evo.evolution_messages
          WHERE (evolution_messages.created_at >= date_trunc('day'::text, now()))) AS mensagens_hoje,
    ( SELECT count(*) AS count
           FROM evo.evolution_messages
          WHERE (evolution_messages.created_at >= (now() - '7 days'::interval))) AS mensagens_7d,
    ( SELECT count(*) AS count
           FROM evo.evolution_conversations
          WHERE ((evolution_conversations.status)::text = ANY ((ARRAY['aberta'::character varying, 'open'::character varying, 'active'::character varying])::text[]))) AS conversas_abertas,
    ( SELECT count(*) AS count
           FROM evo.evolution_deals
          WHERE ((evolution_deals.stage)::text <> ALL ((ARRAY['perdido'::character varying, 'pedido_finalizado'::character varying])::text[]))) AS deals_ativos,
    ( SELECT COALESCE(sum(evolution_deals.value), (0)::numeric) AS "coalesce"
           FROM evo.evolution_deals
          WHERE ((evolution_deals.stage)::text <> ALL ((ARRAY['perdido'::character varying, 'pedido_finalizado'::character varying])::text[]))) AS pipeline_value;


--
-- Name: v_rls_impact_preview; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_rls_impact_preview WITH (security_invoker='on') AS
 WITH msg_window AS (
         SELECT evolution_messages.id,
            evolution_messages.conversation_id,
            evolution_messages.created_at
           FROM zapp.evolution_messages
          WHERE (evolution_messages.created_at >= (CURRENT_DATE - '7 days'::interval))
        UNION
         SELECT messages.id,
            messages.conversation_id,
            messages.created_at
           FROM zapp.messages
          WHERE (messages.created_at >= (CURRENT_DATE - '7 days'::interval))
        ), total_7d AS (
         SELECT count(DISTINCT msg_window.id) AS total
           FROM msg_window
        ), active_agents AS (
         SELECT profiles.id,
            profiles.name,
            profiles.email,
            profiles.role,
            profiles.user_id
           FROM zapp.profiles
          WHERE (profiles.is_active = true)
        ), agent_stats AS (
         SELECT aa.id AS profile_id,
            aa.name AS agent_name,
            aa.email AS agent_email,
            aa.role AS agent_role,
            aa.user_id,
            t.total AS visiveis_hoje,
            COALESCE(( SELECT count(DISTINCT m2.id) AS count
                   FROM msg_window m2
                  WHERE (m2.conversation_id IN ( SELECT tcm.conversation_id
                           FROM zapp.team_conversation_members tcm
                          WHERE (tcm.profile_id = aa.id)))), (0)::bigint) AS visiveis_apos
           FROM (active_agents aa
             CROSS JOIN total_7d t)
        )
 SELECT agent_stats.profile_id,
    agent_stats.agent_name,
    agent_stats.agent_email,
    agent_stats.agent_role,
    agent_stats.user_id,
    agent_stats.visiveis_hoje,
    agent_stats.visiveis_apos,
        CASE
            WHEN (agent_stats.visiveis_hoje = 0) THEN 100.0
            ELSE round((((agent_stats.visiveis_apos)::numeric / (agent_stats.visiveis_hoje)::numeric) * (100)::numeric), 1)
        END AS pct_retido,
        CASE
            WHEN (agent_stats.visiveis_hoje = 0) THEN 'SEM_DADOS'::text
            WHEN ((((agent_stats.visiveis_apos)::numeric / GREATEST((agent_stats.visiveis_hoje)::numeric, (1)::numeric)) * (100)::numeric) < (70)::numeric) THEN 'BLOQUEADO'::text
            ELSE 'OK'::text
        END AS status_impacto
   FROM agent_stats
  ORDER BY agent_stats.agent_name;


--
-- Name: v_sales_pipeline; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_sales_pipeline WITH (security_invoker='on') AS
 SELECT evolution_deals.stage,
    count(*) AS deals_count,
    sum(evolution_deals.value) AS total_value,
    sum(evolution_deals.weighted_value) AS weighted_value,
    avg(evolution_deals.value) AS avg_deal_value,
    avg(evolution_deals.probability) AS avg_probability
   FROM evo.evolution_deals
  WHERE ((evolution_deals.stage)::text <> ALL ((ARRAY['perdido'::character varying, 'pedido_finalizado'::character varying])::text[]))
  GROUP BY evolution_deals.stage
  ORDER BY
        CASE evolution_deals.stage
            WHEN 'novo_cliente'::text THEN 1
            WHEN 'novo_pedido'::text THEN 2
            WHEN 'orcamento_enviado'::text THEN 3
            WHEN 'pagamento_pendente'::text THEN 4
            WHEN 'pago'::text THEN 5
            WHEN 'em_producao'::text THEN 6
            WHEN 'pedido_enviado'::text THEN 7
            ELSE NULL::integer
        END;


--
-- Name: v_security_invoker_audit; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_security_invoker_audit WITH (security_invoker='on') AS
 SELECT n.nspname AS schema,
    c.relname AS view_name,
    pg_get_userbyid(c.relowner) AS owner,
        CASE
            WHEN (c.reloptions IS NULL) THEN 'MISSING'::text
            WHEN (array_to_string(c.reloptions, ','::text) ~~* '%security_invoker=true%'::text) THEN 'OK'::text
            WHEN (array_to_string(c.reloptions, ','::text) ~~* '%security_invoker=on%'::text) THEN 'OK'::text
            ELSE 'OTHER_OPTIONS'::text
        END AS risk_status,
    has_table_privilege('anon'::name, c.oid, 'SELECT'::text) AS anon_can_select,
    has_table_privilege('authenticated'::name, c.oid, 'SELECT'::text) AS auth_can_select
   FROM (pg_class c
     JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
  WHERE ((c.relkind = 'v'::"char") AND (n.nspname = ANY (ARRAY['public'::name, 'zapp'::name, 'evo'::name])))
  ORDER BY
        CASE
            WHEN (c.reloptions IS NULL) THEN 0
            ELSE 1
        END, n.nspname, c.relname;


--
-- Name: VIEW v_security_invoker_audit; Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON VIEW zapp.v_security_invoker_audit IS 'Auditoria contínua: detecta views sem security_invoker em public/zapp/evo. Usado pelo cron jobid 151.';


--
-- Name: v_security_posture; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_security_posture WITH (security_invoker='on') AS
 WITH rls AS (
         SELECT count(*) AS total,
            count(*) FILTER (WHERE c.relrowsecurity) AS com_rls
           FROM (pg_class c
             JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
          WHERE ((n.nspname = ANY (ARRAY['zapp'::name, 'evo'::name])) AND (c.relkind = 'r'::"char"))
        ), pol AS (
         SELECT count(*) AS total
           FROM pg_policies
          WHERE (pg_policies.schemaname = ANY (ARRAY['zapp'::name, 'evo'::name]))
        ), rls_gap AS (
         SELECT count(*) AS cnt
           FROM (pg_class c
             JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
          WHERE ((n.nspname = ANY (ARRAY['zapp'::name, 'evo'::name])) AND (c.relkind = 'r'::"char") AND c.relrowsecurity AND (NOT (EXISTS ( SELECT 1
                   FROM pg_policies p
                  WHERE ((p.schemaname = n.nspname) AND (p.tablename = c.relname))))))
        ), vw AS (
         SELECT count(*) AS total,
            count(*) FILTER (WHERE ((c.reloptions IS NOT NULL) AND (array_to_string(c.reloptions, ','::text) ~~* '%security_invoker%'::text))) AS com_inv
           FROM (pg_class c
             JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
          WHERE ((n.nspname = ANY (ARRAY['public'::name, 'zapp'::name, 'evo'::name])) AND (c.relkind = 'v'::"char"))
        ), sd AS (
         SELECT count(*) AS total,
            count(*) FILTER (WHERE (p.proconfig IS NULL)) AS sem_path
           FROM (pg_proc p
             JOIN pg_namespace n ON ((n.oid = p.pronamespace)))
          WHERE ((n.nspname = ANY (ARRAY['zapp'::name, 'evo'::name])) AND p.prosecdef)
        ), fn_a AS (
         SELECT count(*) AS cnt
           FROM (pg_proc p
             JOIN pg_namespace n ON ((n.oid = p.pronamespace)))
          WHERE ((n.nspname = ANY (ARRAY['zapp'::name, 'evo'::name, 'public'::name])) AND has_function_privilege('anon'::name, p.oid, 'EXECUTE'::text))
        ), st AS (
         SELECT count(*) FILTER (WHERE ((pg_policies.cmd = ANY (ARRAY['INSERT'::text, 'UPDATE'::text, 'DELETE'::text])) AND ((pg_policies.roles)::text ~~* '%anon%'::text))) AS anon_write,
            count(*) FILTER (WHERE ((pg_policies.cmd = 'SELECT'::text) AND ((pg_policies.roles)::text ~~* '%anon%'::text))) AS anon_read
           FROM pg_policies
          WHERE ((pg_policies.schemaname = 'storage'::name) AND (pg_policies.tablename = 'objects'::name))
        ), tg AS (
         SELECT count(*) AS total,
            count(*) FILTER (WHERE (t.tgenabled = 'D'::"char")) AS disabled
           FROM ((pg_trigger t
             JOIN pg_class c ON ((c.oid = t.tgrelid)))
             JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
          WHERE ((n.nspname = ANY (ARRAY['zapp'::name, 'evo'::name])) AND (NOT t.tgisinternal))
        ), hd AS (
         SELECT has_database_privilege('anon'::name, (current_database())::text, 'TEMP'::text) AS anon_temp,
            ( SELECT string_agg(s.s, ','::text) AS string_agg
                   FROM unnest(( SELECT pg_roles.rolconfig
                           FROM pg_roles
                          WHERE (pg_roles.rolname = 'anon'::name))) s(s)
                  WHERE (s.s ~~* 'statement_timeout%'::text)) AS anon_timeout
        )
 SELECT
        CASE
            WHEN ((rls.total = rls.com_rls) AND (vw.total = vw.com_inv) AND (fn_a.cnt = 0) AND (sd.sem_path = 0) AND (st.anon_write = 0) AND (rls_gap.cnt = 0) AND (NOT hd.anon_temp)) THEN 10
            ELSE (((((10 -
            CASE
                WHEN (rls.total <> rls.com_rls) THEN 3
                ELSE 0
            END) -
            CASE
                WHEN (vw.total <> vw.com_inv) THEN 3
                ELSE 0
            END) -
            CASE
                WHEN (fn_a.cnt > 0) THEN 2
                ELSE 0
            END) -
            CASE
                WHEN (st.anon_write > 0) THEN 1
                ELSE 0
            END) -
            CASE
                WHEN hd.anon_temp THEN 1
                ELSE 0
            END)
        END AS security_score,
        CASE
            WHEN ((rls.total = rls.com_rls) AND (vw.total = vw.com_inv) AND (fn_a.cnt = 0) AND (sd.sem_path = 0) AND (st.anon_write = 0) AND (NOT hd.anon_temp)) THEN '🟢 EXCELENTE'::text
            ELSE '🟡 PENDÊNCIAS'::text
        END AS grade,
    rls.total AS tabelas,
    rls.com_rls,
    (rls.total - rls.com_rls) AS sem_rls,
    pol.total AS policies,
    rls_gap.cnt AS rls_sem_policy,
    vw.total AS views,
    vw.com_inv AS views_invoker,
    (vw.total - vw.com_inv) AS views_sem_invoker,
    sd.total AS secdef,
    sd.sem_path AS secdef_sem_path,
    fn_a.cnt AS fn_anon,
    st.anon_write AS st_anon_w,
    st.anon_read AS st_anon_r,
    tg.total AS triggers,
    tg.disabled AS trig_off,
    hd.anon_temp,
    hd.anon_timeout
   FROM rls,
    pol,
    rls_gap,
    vw,
    sd,
    fn_a,
    st,
    tg,
    hd;


--
-- Name: v_sticker_catalog; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_sticker_catalog WITH (security_invoker='on') AS
 SELECT sc.slug AS category,
    sc.label_pt AS label,
    sc.emoji,
    count(s.id) AS total_stickers,
    count(s.id) FILTER (WHERE s.is_animated) AS animated,
    COALESCE(sum(s.use_count), (0)::bigint) AS total_uses,
    sc.sort_order
   FROM (zapp.sticker_categories sc
     LEFT JOIN zapp.stickers s ON (((s.category = sc.slug) AND (s.is_active = true))))
  WHERE (sc.is_active = true)
  GROUP BY sc.slug, sc.label_pt, sc.emoji, sc.sort_order
  ORDER BY sc.sort_order;


--
-- Name: v_sticker_top; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_sticker_top WITH (security_invoker='on') AS
 SELECT s.id,
    s.name,
    s.category,
    s.use_count,
    s.is_animated,
    s.tags,
    "left"(s.image_url, 60) AS url_preview,
    COALESCE(msg.real_sends, (0)::bigint) AS real_sends,
    COALESCE(fav.fav_count, (0)::bigint) AS fav_by_users
   FROM ((zapp.stickers s
     LEFT JOIN ( SELECT evolution_messages.sticker_id,
            count(*) AS real_sends
           FROM evo.evolution_messages
          WHERE (evolution_messages.sticker_id IS NOT NULL)
          GROUP BY evolution_messages.sticker_id) msg ON ((msg.sticker_id = s.id)))
     LEFT JOIN ( SELECT sticker_favorites.sticker_id,
            count(*) AS fav_count
           FROM zapp.sticker_favorites
          GROUP BY sticker_favorites.sticker_id) fav ON ((fav.sticker_id = s.id)))
  WHERE (s.is_active = true)
  ORDER BY s.use_count DESC NULLS LAST
 LIMIT 50;


--
-- Name: v_stickers_catalog; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_stickers_catalog WITH (security_invoker='on') AS
 SELECT sc.slug AS category,
    sc.label_pt AS label,
    sc.emoji,
    sc.sticker_count,
    sc.total_uses,
    sc.sort_order
   FROM zapp.sticker_categories sc
  WHERE (sc.is_active = true)
  ORDER BY sc.sort_order;


--
-- Name: v_stickers_full; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_stickers_full WITH (security_invoker='on') AS
 SELECT s.id,
    s.name,
    s.image_url,
    s.category,
    sc.label_pt AS category_label,
    sc.emoji AS category_emoji,
    s.is_animated,
    s.is_favorite AS is_global_favorite,
    s.use_count,
    s.tags,
    s.file_hash,
    s.mime_type,
    s.width,
    s.height,
    s.file_size,
    s.uploaded_by,
    s.created_at,
    COALESCE(msg.send_count, (0)::bigint) AS real_send_count
   FROM ((zapp.stickers s
     LEFT JOIN zapp.sticker_categories sc ON ((sc.slug = s.category)))
     LEFT JOIN ( SELECT evolution_messages.sticker_id,
            count(*) AS send_count
           FROM evo.evolution_messages
          WHERE (evolution_messages.sticker_id IS NOT NULL)
          GROUP BY evolution_messages.sticker_id) msg ON ((msg.sticker_id = s.id)))
  WHERE (s.is_active = true)
  ORDER BY s.use_count DESC;


--
-- Name: v_storage_policy_audit; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_storage_policy_audit WITH (security_invoker='on') AS
 SELECT p.policyname,
    p.tablename,
    p.cmd,
    (p.roles)::text AS roles,
    p.permissive,
        CASE
            WHEN (((p.roles)::text ~~* '%anon%'::text) AND (p.cmd = ANY (ARRAY['INSERT'::text, 'UPDATE'::text, 'DELETE'::text]))) THEN '🔴 CRITICAL: anon write'::text
            WHEN (((p.roles)::text ~~* '%public%'::text) AND (p.cmd = ANY (ARRAY['INSERT'::text, 'UPDATE'::text, 'DELETE'::text]))) THEN '🟡 WARNING: public write'::text
            WHEN (((p.roles)::text ~~* '%anon%'::text) AND (p.cmd = 'SELECT'::text)) THEN '🟡 WARNING: anon read'::text
            WHEN (((p.roles)::text ~~* '%public%'::text) AND (p.cmd = 'SELECT'::text)) THEN '⚪ INFO: public read'::text
            ELSE '🟢 OK'::text
        END AS risk_level,
    "left"(p.qual, 100) AS qual_preview
   FROM pg_policies p
  WHERE ((p.schemaname = 'storage'::name) AND (p.tablename = 'objects'::name))
  ORDER BY
        CASE
            WHEN ((p.roles)::text ~~* '%anon%'::text) THEN 0
            WHEN ((p.roles)::text ~~* '%public%'::text) THEN 1
            ELSE 2
        END, p.cmd;


--
-- Name: v_system_health; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_system_health WITH (security_invoker='on') AS
 SELECT ( SELECT count(*) AS count
           FROM evo.evolution_contacts) AS total_contacts,
    ( SELECT count(*) AS count
           FROM evo.active_messages
          WHERE (active_messages.created_at > (now() - '24:00:00'::interval))) AS messages_24h,
    ( SELECT count(*) AS count
           FROM evo.active_messages
          WHERE ((active_messages.status)::text = 'failed'::text)) AS total_failed,
    ( SELECT count(*) AS count
           FROM evo.active_messages
          WHERE ((active_messages.status)::text = 'sending'::text)) AS stuck_sending,
    ( SELECT count(*) AS count
           FROM evo.active_messages
          WHERE ((active_messages.status)::text = 'pending'::text)) AS pending,
    ( SELECT count(*) AS count
           FROM zapp.dead_letter_queue) AS dlq_size,
    ( SELECT count(*) AS count
           FROM zapp.app_error_logs
          WHERE (app_error_logs.created_at > (now() - '24:00:00'::interval))) AS errors_24h,
    ( SELECT count(*) AS count
           FROM pg_stat_activity
          WHERE (pg_stat_activity.state = 'active'::text)) AS active_connections,
    ( SELECT count(*) AS count
           FROM pg_stat_activity) AS total_connections,
    pg_size_pretty(pg_database_size('postgres'::name)) AS db_size,
    now() AS checked_at;


--
-- Name: VIEW v_system_health; Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON VIEW zapp.v_system_health IS 'Real-time system health metrics for monitoring dashboard';


--
-- Name: v_system_scorecard; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.v_system_scorecard WITH (security_invoker='on') AS
 SELECT jsonb_build_object('db_size_mb', ((pg_database_size(current_database()) / 1048576))::integer, 'cache_hit_pct', round(( SELECT ((sum(pg_statio_user_tables.heap_blks_hit) * 100.0) / NULLIF((sum(pg_statio_user_tables.heap_blks_hit) + sum(pg_statio_user_tables.heap_blks_read)), (0)::numeric))
           FROM pg_statio_user_tables), 1), 'total_tables_public', ( SELECT count(*) AS count
           FROM pg_stat_user_tables
          WHERE (pg_stat_user_tables.schemaname = 'public'::name)), 'active_connections', ( SELECT count(*) AS count
           FROM pg_stat_activity
          WHERE (pg_stat_activity.datname = current_database())), 'cron_jobs_active', ( SELECT count(*) AS count
           FROM cron.job
          WHERE (job.active = true)), 'messages_total', ( SELECT count(*) AS count
           FROM evo.active_messages), 'contacts_total', ( SELECT pg_stat_user_tables.n_live_tup
           FROM pg_stat_user_tables
          WHERE ((pg_stat_user_tables.schemaname = 'evo'::name) AND (pg_stat_user_tables.relname = 'evolution_contacts'::name))), 'media_queue_pending', ( SELECT count(*) AS count
           FROM zapp.media_download_queue
          WHERE (media_download_queue.status = 'pending'::text)), 'migration_v2_pct', round(((100.0 * (( SELECT count(*) AS count
           FROM evo.evolution_messages evolution_messages_v2))::numeric) / (NULLIF(( SELECT count(*) AS count
           FROM evo.evolution_messages_wpp2
          WHERE (evolution_messages_wpp2.created_at < (now() - '90 days'::interval))), 0))::numeric), 2)) AS scorecard;


