--
-- Name: vw_dlq_pending; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.vw_dlq_pending WITH (security_invoker='on') AS
 SELECT evolution_webhook_dlq.id,
    evolution_webhook_dlq.event_type,
    evolution_webhook_dlq.instance_name,
    evolution_webhook_dlq.remote_jid,
    evolution_webhook_dlq.error_message,
    evolution_webhook_dlq.retry_count,
    evolution_webhook_dlq.max_retries,
    evolution_webhook_dlq.next_retry_at,
    evolution_webhook_dlq.status,
    evolution_webhook_dlq.created_at,
        CASE
            WHEN (evolution_webhook_dlq.retry_count >= evolution_webhook_dlq.max_retries) THEN 'Excedeu tentativas'::text
            WHEN (evolution_webhook_dlq.next_retry_at <= now()) THEN 'Pronto para retry'::text
            ELSE 'Aguardando'::text
        END AS retry_status
   FROM evo.evolution_webhook_dlq
  WHERE (evolution_webhook_dlq.status = ANY (ARRAY['pending'::text, 'retrying'::text]))
  ORDER BY evolution_webhook_dlq.created_at DESC;


--
-- Name: vw_evolution_hot_leads; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.vw_evolution_hot_leads WITH (security_invoker='on') AS
 SELECT evolution_contacts.remote_jid,
    evolution_contacts.push_name,
    evolution_contacts.lead_score,
    evolution_contacts.total_messages,
    evolution_contacts.last_message_at,
    evolution_contacts.created_at
   FROM evo.evolution_contacts
  WHERE (evolution_contacts.lead_score >= 50)
  ORDER BY evolution_contacts.lead_score DESC, evolution_contacts.last_message_at DESC
 LIMIT 100;


--
-- Name: vw_evolution_queue_failures; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.vw_evolution_queue_failures WITH (security_invoker='on') AS
 SELECT evolution_message_queue.id,
    evolution_message_queue.status,
    evolution_message_queue.attempts,
    evolution_message_queue.max_attempts,
    evolution_message_queue.remote_jid,
    evolution_message_queue.message_type,
    evolution_message_queue.source,
    evolution_message_queue.created_at,
    evolution_message_queue.error_message,
        CASE
            WHEN ((evolution_message_queue.error_message ~~* '%dns error%'::text) OR (evolution_message_queue.error_message ~~* '%failed to lookup%'::text)) THEN 'transient:dns'::text
            WHEN (evolution_message_queue.error_message ~~* '%timeout%'::text) THEN 'transient:timeout'::text
            WHEN ((evolution_message_queue.error_message ~~* '%ECONNREFUSED%'::text) OR (evolution_message_queue.error_message ~~* '%ECONNRESET%'::text)) THEN 'transient:connection'::text
            WHEN ((evolution_message_queue.error_message ~~* '%HTTP 502%'::text) OR (evolution_message_queue.error_message ~~* '%HTTP 503%'::text) OR (evolution_message_queue.error_message ~~* '%HTTP 504%'::text)) THEN 'transient:upstream_5xx'::text
            WHEN ((evolution_message_queue.error_message ~~* '%401%'::text) AND (evolution_message_queue.error_message ~~* '%Unauthorized%'::text)) THEN 'whatsapp:logout_401'::text
            WHEN ((evolution_message_queue.error_message ~~* '%instance not connected%'::text) OR (evolution_message_queue.error_message ~~* '%status: close%'::text)) THEN 'whatsapp:disconnected'::text
            WHEN (evolution_message_queue.error_message ~~* '%AUTO-SKIPPED%'::text) THEN 'design:auto_skipped'::text
            WHEN (evolution_message_queue.error_message IS NULL) THEN 'unknown:no_error_msg'::text
            ELSE 'unknown:other'::text
        END AS error_category,
        CASE
            WHEN ((evolution_message_queue.error_message ~~* '%dns error%'::text) OR (evolution_message_queue.error_message ~~* '%timeout%'::text) OR (evolution_message_queue.error_message ~~* '%ECONN%'::text) OR (evolution_message_queue.error_message ~~* '%HTTP 5%'::text)) THEN true
            ELSE false
        END AS is_retriable,
        CASE
            WHEN (evolution_message_queue.error_message ~~* '%AUTO-SKIPPED%'::text) THEN false
            ELSE true
        END AS is_real_failure
   FROM evo.evolution_message_queue
  WHERE ((evolution_message_queue.status)::text = 'failed'::text);


--
-- Name: vw_evolution_queues_health; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.vw_evolution_queues_health WITH (security_invoker='on') AS
 WITH msg_q AS (
         SELECT 'evolution_message_queue'::text AS queue_name,
            count(*) FILTER (WHERE ((evolution_message_queue.status)::text = 'pending'::text)) AS pending,
            count(*) FILTER (WHERE (((evolution_message_queue.status)::text = 'pending'::text) AND (evolution_message_queue.created_at < (now() - '00:15:00'::interval)))) AS pending_old,
            count(*) FILTER (WHERE ((evolution_message_queue.status)::text = 'sent'::text)) AS sent,
            count(*) FILTER (WHERE ((evolution_message_queue.status)::text = 'delivered'::text)) AS delivered,
            count(*) FILTER (WHERE ((evolution_message_queue.status)::text = 'failed'::text)) AS failed
           FROM evo.evolution_message_queue
          WHERE (evolution_message_queue.created_at >= (now() - '24:00:00'::interval))
        ), bitrix_q AS (
         SELECT 'evolution_bitrix_queue'::text AS queue_name,
            count(*) FILTER (WHERE ((evolution_bitrix_queue.status)::text = 'pending'::text)) AS pending,
            count(*) FILTER (WHERE (((evolution_bitrix_queue.status)::text = 'pending'::text) AND (evolution_bitrix_queue.created_at < (now() - '00:15:00'::interval)))) AS pending_old,
            count(*) FILTER (WHERE ((evolution_bitrix_queue.status)::text = 'processed'::text)) AS sent,
            0 AS delivered,
            count(*) FILTER (WHERE ((evolution_bitrix_queue.status)::text = 'failed'::text)) AS failed
           FROM evo.evolution_bitrix_queue
          WHERE (evolution_bitrix_queue.created_at >= (now() - '24:00:00'::interval))
        ), mirror_q AS (
         SELECT 'evolution_mirror_media_queue'::text AS queue_name,
            count(*) FILTER (WHERE (evolution_mirror_media_queue.status = 'pending'::text)) AS pending,
            count(*) FILTER (WHERE ((evolution_mirror_media_queue.status = 'pending'::text) AND (evolution_mirror_media_queue.created_at < (now() - '01:00:00'::interval)))) AS pending_old,
            count(*) FILTER (WHERE (evolution_mirror_media_queue.status = 'uploaded'::text)) AS sent,
            0 AS delivered,
            count(*) FILTER (WHERE (evolution_mirror_media_queue.status = 'failed'::text)) AS failed
           FROM evo.evolution_mirror_media_queue
        ), combined AS (
         SELECT msg_q.queue_name,
            msg_q.pending,
            msg_q.pending_old,
            msg_q.sent,
            msg_q.delivered,
            msg_q.failed
           FROM msg_q
        UNION ALL
         SELECT bitrix_q.queue_name,
            bitrix_q.pending,
            bitrix_q.pending_old,
            bitrix_q.sent,
            bitrix_q.delivered,
            bitrix_q.failed
           FROM bitrix_q
        UNION ALL
         SELECT mirror_q.queue_name,
            mirror_q.pending,
            mirror_q.pending_old,
            mirror_q.sent,
            mirror_q.delivered,
            mirror_q.failed
           FROM mirror_q
        )
 SELECT combined.queue_name,
    combined.pending,
    combined.pending_old,
    combined.sent,
    combined.delivered,
    combined.failed,
        CASE
            WHEN (((combined.pending + combined.pending_old) = 0) AND (combined.failed = 0)) THEN 'healthy'::text
            WHEN (combined.pending_old > 100) THEN 'critical'::text
            WHEN (combined.pending_old > 10) THEN 'degraded'::text
            WHEN (combined.pending > 50) THEN 'busy'::text
            WHEN (combined.failed > 0) THEN 'warning_failures'::text
            ELSE 'healthy'::text
        END AS status_summary,
    round(((100.0 * (combined.sent)::numeric) / (NULLIF((combined.sent + combined.failed), 0))::numeric), 1) AS success_rate_pct
   FROM combined;


--
-- Name: vw_evolution_sales_funnel; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.vw_evolution_sales_funnel WITH (security_invoker='on') AS
 SELECT sm.stage_key,
    sm.label_name,
    sm.stage_order,
    count(DISTINCT c.remote_jid) AS contacts_count,
    round((((count(DISTINCT c.remote_jid))::numeric / (NULLIF(( SELECT count(DISTINCT evolution_contacts.remote_jid) AS count
           FROM evo.evolution_contacts), 0))::numeric) * (100)::numeric), 1) AS pct_of_total
   FROM (evo.evolution_stage_mapping sm
     LEFT JOIN evo.evolution_contacts c ON (((c.lead_status)::text = sm.stage_key)))
  GROUP BY sm.stage_key, sm.label_name, sm.stage_order
  ORDER BY sm.stage_order;


--
-- Name: vw_evolution_top_contacts; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.vw_evolution_top_contacts WITH (security_invoker='on') AS
 SELECT evolution_contacts.remote_jid,
    evolution_contacts.push_name,
    evolution_contacts.lead_score,
    evolution_contacts.total_messages,
    evolution_contacts.lead_status,
    evolution_contacts.last_message_at,
    evolution_contacts.created_at,
    (EXTRACT(day FROM (now() - evolution_contacts.created_at)))::integer AS days_as_contact
   FROM evo.evolution_contacts
  WHERE (evolution_contacts.push_name IS NOT NULL)
  ORDER BY evolution_contacts.lead_score DESC, evolution_contacts.total_messages DESC
 LIMIT 100;


--
-- Name: vw_groups_summary; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.vw_groups_summary WITH (security_invoker='on') AS
 SELECT g.id,
    g.group_jid,
    g.name,
    g.category,
    g.participant_count,
    g.is_community,
    g.is_monitored,
    g.auto_response_enabled,
    g.last_activity_at,
    ( SELECT count(*) AS count
           FROM evo.evolution_group_messages gm
          WHERE ((gm.group_id = g.id) AND (gm.created_at > (now() - '24:00:00'::interval)))) AS messages_today,
    ( SELECT count(*) AS count
           FROM evo.evolution_group_rules gr
          WHERE ((gr.group_id = g.id) AND (gr.is_active = true))) AS active_rules
   FROM evo.evolution_groups g
  WHERE (g.is_active = true)
