--
-- Name: vw_historico; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.vw_historico WITH (security_invoker='on') AS
 SELECT c.id_bitrix,
    c.nome,
    s.periodo,
    s.status,
    s.valor,
    s.lembretes,
    s.respondido_em
   FROM (zapp.solicitacoes_vale s
     JOIN zapp.colaboradores c ON ((c.id_bitrix = s.id_bitrix)))
