--
-- Name: vw_media_health_dashboard; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.vw_media_health_dashboard WITH (security_invoker='on') AS
 WITH stats AS (
         SELECT evolution_messages.message_type,
            count(*) AS total,
            count(*) FILTER (WHERE ((evolution_messages.media_url IS NOT NULL) AND (evolution_messages.media_url <> ''::text))) AS with_url,
            count(*) FILTER (WHERE ((evolution_messages.media_mimetype IS NOT NULL) AND (evolution_messages.media_mimetype <> ''::text))) AS with_mime,
            count(*) FILTER (WHERE (evolution_messages.created_at >= (now() - '24:00:00'::interval))) AS last_24h,
            count(*) FILTER (WHERE ((evolution_messages.created_at >= (now() - '24:00:00'::interval)) AND (evolution_messages.media_url IS NOT NULL) AND (evolution_messages.media_url <> ''::text))) AS last_24h_with_url
           FROM evo.evolution_messages
          WHERE (((evolution_messages.message_type)::text = ANY ((ARRAY['image'::character varying, 'video'::character varying, 'audio'::character varying, 'ptt'::character varying, 'document'::character varying, 'sticker'::character varying])::text[])) AND (evolution_messages.deleted_at IS NULL))
          GROUP BY evolution_messages.message_type
        )
 SELECT stats.message_type,
    stats.total,
    stats.with_url,
    round(((100.0 * (stats.with_url)::numeric) / (NULLIF(stats.total, 0))::numeric), 1) AS pct_with_url,
    stats.with_mime,
    stats.last_24h,
    stats.last_24h_with_url,
    round(((100.0 * (stats.last_24h_with_url)::numeric) / (NULLIF(stats.last_24h, 0))::numeric), 1) AS pct_24h_with_url,
        CASE
            WHEN (round(((100.0 * (stats.with_url)::numeric) / (NULLIF(stats.total, 0))::numeric), 1) >= (95)::numeric) THEN 'healthy'::text
            WHEN (round(((100.0 * (stats.with_url)::numeric) / (NULLIF(stats.total, 0))::numeric), 1) >= (50)::numeric) THEN 'degraded'::text
            ELSE 'critical'::text
        END AS health_status
   FROM stats
  ORDER BY stats.total DESC;


--
-- Name: VIEW vw_media_health_dashboard; Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON VIEW zapp.vw_media_health_dashboard IS 'Dashboard de saúde do pipeline de mídia por tipo';


--
-- Name: vw_media_pipeline_status; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.vw_media_pipeline_status WITH (security_invoker='on') AS
 WITH queue_stats AS (
         SELECT media_download_queue.status,
            count(*) AS total,
            count(*) FILTER (WHERE (media_download_queue.priority = 10)) AS priority_high,
            count(*) FILTER (WHERE (media_download_queue.priority = 5)) AS priority_medium,
            count(*) FILTER (WHERE (media_download_queue.priority = 1)) AS priority_low
           FROM zapp.media_download_queue
          GROUP BY media_download_queue.status
        ), msg_stats AS (
         SELECT count(*) AS total_media_msgs,
            count(*) FILTER (WHERE ((evolution_messages.media_url IS NOT NULL) AND (evolution_messages.media_url <> ''::text))) AS with_url,
            count(*) FILTER (WHERE ((evolution_messages.media_url IS NULL) OR (evolution_messages.media_url = ''::text))) AS without_url,
            count(*) FILTER (WHERE (evolution_messages.media_url ~~ 'https://s3.atomicabr%'::text)) AS s3_public,
            count(*) FILTER (WHERE (evolution_messages.media_url ~~ 'https://allrjhk%'::text)) AS supabase_cloud,
            count(*) FILTER (WHERE (evolution_messages.media_url ~~ 'http://minio%'::text)) AS minio_internal
           FROM evo.evolution_messages
          WHERE (((evolution_messages.message_type)::text = ANY ((ARRAY['image'::character varying, 'video'::character varying, 'audio'::character varying, 'ptt'::character varying, 'document'::character varying, 'sticker'::character varying])::text[])) AND (evolution_messages.deleted_at IS NULL))
        )
 SELECT ms.total_media_msgs,
    ms.with_url,
    ms.without_url,
    round(((100.0 * (ms.with_url)::numeric) / (NULLIF(ms.total_media_msgs, 0))::numeric), 1) AS pct_with_url,
    ms.s3_public,
    ms.supabase_cloud,
    ms.minio_internal,
    COALESCE(( SELECT queue_stats.total
           FROM queue_stats
          WHERE (queue_stats.status = 'pending'::text)), (0)::bigint) AS queue_pending,
    COALESCE(( SELECT queue_stats.total
           FROM queue_stats
          WHERE (queue_stats.status = 'processing'::text)), (0)::bigint) AS queue_processing,
    COALESCE(( SELECT queue_stats.total
           FROM queue_stats
          WHERE (queue_stats.status = 'done'::text)), (0)::bigint) AS queue_done,
    COALESCE(( SELECT queue_stats.total
           FROM queue_stats
          WHERE (queue_stats.status = 'failed'::text)), (0)::bigint) AS queue_failed,
        CASE
            WHEN (ms.minio_internal > 0) THEN 'HAS_INTERNAL_URLS'::text
            WHEN (COALESCE(( SELECT queue_stats.total
               FROM queue_stats
              WHERE (queue_stats.status = 'pending'::text)), (0)::bigint) > 100) THEN 'QUEUE_BACKLOG'::text
            WHEN (round(((100.0 * (ms.with_url)::numeric) / (NULLIF(ms.total_media_msgs, 0))::numeric), 1) >= (90)::numeric) THEN 'HEALTHY'::text
            WHEN (round(((100.0 * (ms.with_url)::numeric) / (NULLIF(ms.total_media_msgs, 0))::numeric), 1) >= (50)::numeric) THEN 'DEGRADED'::text
            ELSE 'CRITICAL'::text
        END AS overall_status
   FROM msg_stats ms;


--
-- Name: VIEW vw_media_pipeline_status; Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON VIEW zapp.vw_media_pipeline_status IS 'Dashboard completo do pipeline de midia: URLs, fila, status geral';


--
-- Name: vw_minio_decommission_check; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.vw_minio_decommission_check WITH (security_invoker='on') AS
 SELECT ( SELECT count(*) AS count
           FROM evo.evolution_messages
          WHERE ((evolution_messages.media_url ~~ 'http://minio%'::text) AND (evolution_messages.deleted_at IS NULL))) AS urls_minio_interno,
    ( SELECT count(*) AS count
           FROM evo.evolution_messages
          WHERE ((evolution_messages.media_url ~~ 'https://s3.atomicabr%'::text) AND (evolution_messages.deleted_at IS NULL))) AS urls_s3_atomicabr,
    ( SELECT count(*) AS count
           FROM evo.evolution_messages
          WHERE ((evolution_messages.media_url ~~ 'https://zapp-media-proxy%'::text) AND (evolution_messages.created_at > (now() - '24:00:00'::interval)) AND (evolution_messages.deleted_at IS NULL))) AS r2_novas_24h,
    'https://zapp-media-proxy.adm01.workers.dev/health'::text AS worker_health_url,
        CASE
            WHEN ((( SELECT count(*) AS count
               FROM evo.evolution_messages
              WHERE ((evolution_messages.media_url ~~ 'http://minio%'::text) AND (evolution_messages.deleted_at IS NULL))) = 0) AND (( SELECT count(*) AS count
               FROM evo.evolution_messages
              WHERE ((evolution_messages.media_url ~~ 'https://s3.atomicabr%'::text) AND (evolution_messages.deleted_at IS NULL))) = 0)) THEN 'SAFE_TO_DECOMMISSION'::text
            ELSE 'NOT_READY'::text
        END AS status;


--
-- Name: vw_missed_calls_pending; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.vw_missed_calls_pending WITH (security_invoker='on') AS
 SELECT c.id,
    c.call_id,
    c.remote_jid,
    c.call_type,
    c.created_at,
    c.missed_callback_sent,
    ct.full_name AS contact_name,
    ct.phone_number,
    (EXTRACT(epoch FROM (now() - c.created_at)) / (60)::numeric) AS minutes_since_call
   FROM (evo.evolution_calls c
     LEFT JOIN evo.evolution_contacts ct ON ((c.contact_id = ct.id)))
  WHERE ((c.call_status = 'missed'::text) AND (c.missed_callback_sent = false) AND (c.created_at > (now() - '24:00:00'::interval)))
  ORDER BY c.created_at DESC;


--
-- Name: vw_pendentes_atual; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.vw_pendentes_atual WITH (security_invoker='on') AS
 SELECT c.id_bitrix,
    c.nome,
    c.dialog_id,
    s.lembretes,
    s.disparado_em
   FROM (zapp.solicitacoes_vale s
     JOIN zapp.colaboradores c ON ((c.id_bitrix = s.id_bitrix)))
  WHERE ((s.status = 'PENDENTE'::text) AND (s.periodo = to_char((now() AT TIME ZONE 'America/Sao_Paulo'::text), 'YYYY-MM'::text)) AND (c.ativo = true));


--
-- Name: vw_r2_migration_status; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.vw_r2_migration_status WITH (security_invoker='on') AS
 SELECT ( SELECT count(*) AS count
           FROM evo.evolution_messages
          WHERE (evolution_messages.media_url ~~ 'https://zapp-media-proxy%'::text)) AS urls_r2_worker,
    ( SELECT count(*) AS count
           FROM evo.evolution_messages
          WHERE (evolution_messages.media_url ~~ 'https://allrjhk%'::text)) AS urls_supabase_cloud,
    ( SELECT count(*) AS count
           FROM evo.evolution_messages
          WHERE (evolution_messages.media_url ~~ 'http://minio%'::text)) AS urls_minio_interno,
    ( SELECT count(*) AS count
           FROM evo.evolution_messages
          WHERE (evolution_messages.media_url ~~ 'https://s3.atomicabr%'::text)) AS urls_s3_atomicabr,
    ( SELECT count(*) AS count
           FROM evo.evolution_messages
          WHERE (((evolution_messages.media_url IS NULL) OR (evolution_messages.media_url = ''::text)) AND ((evolution_messages.message_type)::text = ANY ((ARRAY['image'::character varying, 'video'::character varying, 'audio'::character varying, 'ptt'::character varying, 'document'::character varying, 'sticker'::character varying])::text[])) AND (evolution_messages.deleted_at IS NULL))) AS sem_url,
    ( SELECT count(*) AS count
           FROM zapp.media_download_queue
          WHERE (media_download_queue.status = 'pending'::text)) AS queue_pending,
    ( SELECT count(*) AS count
           FROM zapp.media_download_queue
          WHERE (media_download_queue.status = 'done'::text)) AS queue_done,
    ( SELECT count(*) AS count
           FROM zapp.media_download_queue
          WHERE (media_download_queue.status = 'failed'::text)) AS queue_failed,
    ( SELECT count(*) AS count
           FROM zapp.stickers
          WHERE (stickers.is_active = true)) AS stickers_total,
    'zapp-whatsapp-media'::text AS r2_bucket,
    'https://zapp-media-proxy.adm01.workers.dev'::text AS r2_worker_url;


--
-- Name: vw_recent_media; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.vw_recent_media WITH (security_invoker='on') AS
 SELECT m.id,
    m.message_id,
    m.remote_jid,
    m.media_type,
    m.mime_type,
    m.file_name,
    m.file_size,
    m.storage_url,
    m.caption,
    m.created_at,
    ct.full_name AS contact_name
   FROM (evo.evolution_media m
     LEFT JOIN evo.evolution_contacts ct ON ((m.remote_jid = (ct.remote_jid)::text)))
  ORDER BY m.created_at DESC
 LIMIT 100;


--
-- Name: vw_recent_media_gallery; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.vw_recent_media_gallery WITH (security_invoker='on') AS
 SELECT em.id,
    em.message_id,
    em.message_type AS media_type,
    zapp.fn_media_public_url(em.media_url) AS public_url,
    em.media_mimetype,
    em.media_filename,
    em.media_size,
    em.caption,
    em.from_me,
    em.remote_jid,
    em.instance_name,
    ec.full_name AS contact_name,
    ec.phone_number AS contact_phone,
    em.created_at,
        CASE
            WHEN (em.media_url ~~ 'https://s3.atomicabr%'::text) THEN 'minio_public'::text
            WHEN (em.media_url ~~ 'https://allrjhk%'::text) THEN 'supabase_cloud'::text
            ELSE 'other'::text
        END AS storage_provider
   FROM (evo.evolution_messages em
     LEFT JOIN evo.evolution_contacts ec ON ((ec.id = em.contact_id)))
  WHERE (((em.message_type)::text = ANY (ARRAY[('image'::character varying)::text, ('video'::character varying)::text, ('audio'::character varying)::text, ('ptt'::character varying)::text, ('document'::character varying)::text, ('sticker'::character varying)::text])) AND (em.media_url IS NOT NULL) AND (em.media_url <> ''::text) AND (em.deleted_at IS NULL))
  ORDER BY em.created_at DESC
 LIMIT 500;


--
-- Name: vw_resumo_mes; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.vw_resumo_mes WITH (security_invoker='on') AS
 SELECT solicitacoes_vale.periodo,
    count(*) FILTER (WHERE (solicitacoes_vale.status = 'PENDENTE'::text)) AS pendentes,
    count(*) FILTER (WHERE (solicitacoes_vale.status = 'SOLICITADO'::text)) AS solicitaram,
    count(*) FILTER (WHERE (solicitacoes_vale.status = 'RECUSADO'::text)) AS recusaram,
    COALESCE(sum(solicitacoes_vale.valor) FILTER (WHERE (solicitacoes_vale.status = 'SOLICITADO'::text)), (0)::numeric) AS valor_total,
    count(*) AS total
   FROM zapp.solicitacoes_vale
  WHERE (solicitacoes_vale.periodo = to_char((now() AT TIME ZONE 'America/Sao_Paulo'::text), 'YYYY-MM'::text))
  GROUP BY solicitacoes_vale.periodo;


--
-- Name: vw_sticker_categories; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.vw_sticker_categories WITH (security_invoker='on') AS
 SELECT COALESCE(stickers.category, 'sem_categoria'::text) AS category,
    count(*) AS total,
    count(*) FILTER (WHERE stickers.is_favorite) AS favorites,
    sum(stickers.use_count) AS total_uses,
    max(stickers.updated_at) AS last_used_at
   FROM zapp.stickers
  WHERE (stickers.is_active = true)
  GROUP BY stickers.category
  ORDER BY (sum(stickers.use_count)) DESC, (count(*)) DESC;


