-- Name: VIEW vw_sticker_categories; Type: COMMENT; Schema: zapp; Owner: -
--

COMMENT ON VIEW zapp.vw_sticker_categories IS 'Resumo de categorias de stickers com contagem de uso';


--
-- Name: vw_sticker_messages; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.vw_sticker_messages WITH (security_invoker='on') AS
 SELECT em.id,
    em.message_id,
    em.remote_jid,
    em.from_me,
    em.media_url,
    em.media_mimetype,
    em.status,
    em.instance_name,
    em.push_name,
    em.contact_id,
    em.created_at,
    ec.full_name AS contact_name,
    ec.phone_number AS contact_phone,
        CASE
            WHEN (em.media_url ~~ 'http://minio%'::text) THEN 'minio_local'::text
            WHEN (em.media_url ~~ 'https://allrjhk%'::text) THEN 'supabase_cloud'::text
            WHEN ((em.media_url IS NULL) OR (em.media_url = ''::text)) THEN 'missing'::text
            ELSE 'other'::text
        END AS storage_type,
        CASE
            WHEN ((em.media_url IS NOT NULL) AND (em.media_url <> ''::text)) THEN true
            ELSE false
        END AS has_media
   FROM (evo.evolution_messages em
     LEFT JOIN evo.evolution_contacts ec ON ((ec.id = em.contact_id)))
  WHERE (((em.message_type)::text = 'sticker'::text) AND (em.deleted_at IS NULL));


--
-- Name: vw_system_health; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.vw_system_health WITH (security_invoker='on') AS
 WITH wa_conn AS (
         SELECT whatsapp_connections.instance_name,
            whatsapp_connections.status,
            whatsapp_connections.health_status,
            whatsapp_connections.phone_number,
            whatsapp_connections.last_connected_at,
            whatsapp_connections.last_health_check,
            (EXTRACT(epoch FROM (now() - whatsapp_connections.last_connected_at)) / (3600)::numeric) AS hours_disconnected
           FROM zapp.whatsapp_connections
        ), msgs AS (
         SELECT max(evolution_messages_v2.created_at) AS last_message_at,
            count(*) FILTER (WHERE (evolution_messages_v2.created_at > (now() - '01:00:00'::interval))) AS msgs_1h,
            count(*) FILTER (WHERE (evolution_messages_v2.created_at > (now() - '24:00:00'::interval))) AS msgs_24h
           FROM evo.evolution_messages evolution_messages_v2
        ), alerts_open AS (
         SELECT count(*) AS total_open,
            count(*) FILTER (WHERE (evolution_alerts.severity = 'high'::text)) AS critical_open,
            count(*) FILTER (WHERE (evolution_alerts.alert_type = 'pipeline_health'::text)) AS pipeline_alerts
           FROM evo.evolution_alerts
          WHERE (evolution_alerts.resolved = false)
        ), reconcile AS (
         SELECT evolution_reconcile_jobs.dispatched_at,
            evolution_reconcile_jobs.http_status,
            evolution_reconcile_jobs.result
           FROM evo.evolution_reconcile_jobs
          ORDER BY evolution_reconcile_jobs.dispatched_at DESC
         LIMIT 1
        ), watermark AS (
         SELECT migration_watermark.last_created_at,
            migration_watermark.rows_migrated
           FROM evo.migration_watermark
          WHERE (migration_watermark.migration_name = 'wpp2_to_v2'::text)
        )
 SELECT now() AS checked_at,
    ( SELECT wa_conn.status
           FROM wa_conn
          WHERE (wa_conn.instance_name = 'wpp2'::text)) AS wpp2_status,
    ( SELECT wa_conn.health_status
           FROM wa_conn
          WHERE (wa_conn.instance_name = 'wpp2'::text)) AS wpp2_health,
    ( SELECT round(wa_conn.hours_disconnected, 1) AS round
           FROM wa_conn
          WHERE (wa_conn.instance_name = 'wpp2'::text)) AS wpp2_hours_offline,
    ( SELECT wa_conn.status
           FROM wa_conn
          WHERE (wa_conn.instance_name = 'wpp_pink_test'::text)) AS wpp_pink_status,
    ( SELECT COALESCE(msgs.msgs_1h, (0)::bigint) AS "coalesce"
           FROM msgs) AS msgs_last_1h,
    ( SELECT COALESCE(msgs.msgs_24h, (0)::bigint) AS "coalesce"
           FROM msgs) AS msgs_last_24h,
    ( SELECT msgs.last_message_at
           FROM msgs) AS last_message_at,
    ( SELECT alerts_open.total_open
           FROM alerts_open) AS alerts_open,
    ( SELECT alerts_open.critical_open
           FROM alerts_open) AS alerts_critical,
    ( SELECT reconcile.http_status
           FROM reconcile) AS last_reconcile_http,
    ( SELECT reconcile.dispatched_at
           FROM reconcile) AS last_reconcile_at,
    ( SELECT watermark.last_created_at
           FROM watermark) AS migration_watermark,
    ( SELECT watermark.rows_migrated
           FROM watermark) AS migration_rows;


--
-- Name: vw_unread_events; Type: VIEW; Schema: zapp; Owner: -
--

CREATE VIEW zapp.vw_unread_events WITH (security_invoker='on') AS
 SELECT evolution_realtime_events.id,
    evolution_realtime_events.event_type,
    evolution_realtime_events.entity_type,
    evolution_realtime_events.entity_id,
    evolution_realtime_events.remote_jid,
    evolution_realtime_events.title,
    evolution_realtime_events.body,
    evolution_realtime_events.data,
    evolution_realtime_events.priority,
    evolution_realtime_events.read,
    evolution_realtime_events.read_at,
    evolution_realtime_events.target_users,
    evolution_realtime_events.created_at,
        CASE evolution_realtime_events.priority
            WHEN 'urgent'::text THEN 1
            WHEN 'high'::text THEN 2
            WHEN 'normal'::text THEN 3
            ELSE 4
        END AS priority_order
   FROM evo.evolution_realtime_events
  WHERE ((evolution_realtime_events.read = false) AND (evolution_realtime_events.created_at > (now() - '24:00:00'::interval)))
  ORDER BY
        CASE evolution_realtime_events.priority
            WHEN 'urgent'::text THEN 1
            WHEN 'high'::text THEN 2
            WHEN 'normal'::text THEN 3
            ELSE 4
        END, evolution_realtime_events.created_at DESC;


