);


--
-- Name: webhook_idempotency; Type: TABLE; Schema: zapp; Owner: -
--

CREATE TABLE zapp.webhook_idempotency (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    source character varying(50) NOT NULL,
    webhook_id character varying(255) NOT NULL,
    status character varying(20) DEFAULT 'processing'::character varying NOT NULL,
    error_message text,
    received_at timestamp with time zone DEFAULT now() NOT NULL,
    processed_at timestamp with time zone,
    expires_at timestamp with time zone DEFAULT (now() + '24:00:00'::interval) NOT NULL,
    CONSTRAINT webhook_idempotency_status_check CHECK (((status)::text = ANY ((ARRAY['processing'::character varying, 'completed'::character varying, 'failed'::character varying, 'expired'::character varying])::text[])))
);

ALTER TABLE ONLY zapp.webhook_idempotency REPLICA IDENTITY FULL;


--
-- Name: webhook_reprocess_queue; Type: TABLE; Schema: zapp; Owner: -
--

CREATE TABLE zapp.webhook_reprocess_queue (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    connection_id uuid,
    payload jsonb NOT NULL,
    last_error text,
    attempts integer DEFAULT 0,
    max_attempts integer DEFAULT 5,
    next_retry_at timestamp with time zone DEFAULT now(),
    status text DEFAULT 'pending'::text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT webhook_reprocess_queue_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'failed'::text, 'completed'::text])))
);

ALTER TABLE ONLY zapp.webhook_reprocess_queue REPLICA IDENTITY FULL;


