--

CREATE VIEW zapp.workflow_step_runs WITH (security_invoker='on') AS
 SELECT workflow_step_runs.id,
    workflow_step_runs.workflow_run_id,
    workflow_step_runs.workflow_step_id,
    workflow_step_runs.step_order,
    workflow_step_runs.status,
    workflow_step_runs.input,
    workflow_step_runs.output,
    workflow_step_runs.error,
    workflow_step_runs.tokens_used,
    workflow_step_runs.cost_usd,
    workflow_step_runs.latency_ms,
    workflow_step_runs.started_at,
    workflow_step_runs.completed_at
   FROM ai.workflow_step_runs;


