--
-- Name: v_popular_tags _RETURN; Type: RULE; Schema: zapp; Owner: -
--

CREATE OR REPLACE VIEW zapp.v_popular_tags WITH (security_invoker='on') AS
 SELECT t.id,
    t.name,
    t.color,
    t.category,
    t.use_count,
    count(ta.id) AS current_assignments
   FROM (evo.evolution_tags t
     LEFT JOIN evo.evolution_tag_assignments ta ON ((t.id = ta.tag_id)))
  GROUP BY t.id
  ORDER BY t.use_count DESC, (count(ta.id)) DESC
 LIMIT 50;


--
-- Name: v_top_contacts _RETURN; Type: RULE; Schema: zapp; Owner: -
--

CREATE OR REPLACE VIEW zapp.v_top_contacts WITH (security_invoker='on') AS
 SELECT c.id,
    c.phone_number,
    COALESCE(c.full_name, c.push_name) AS name,
    c.company,
    c.lead_status,
    c.lead_score,
    c.total_messages,
    c.total_purchases,
    c.last_message_at,
    count(d.id) AS active_deals,
    sum(
        CASE
            WHEN ((d.stage)::text <> ALL (ARRAY[('perdido'::character varying)::text, ('pedido_finalizado'::character varying)::text])) THEN d.value
            ELSE (0)::numeric
        END) AS pipeline_value
   FROM (evo.evolution_contacts c
     LEFT JOIN evo.evolution_deals d ON ((c.id = d.contact_id)))
  GROUP BY c.id
  ORDER BY c.lead_score DESC, c.total_purchases DESC
 LIMIT 100;


