CREATE POLICY email_threads_manage_own ON email_app.email_threads TO authenticated USING (((gmail_account_id IN ( SELECT ga.id
   FROM (email_app.gmail_accounts ga
     JOIN zapp.profiles p ON ((p.id = ga.profile_id)))
  WHERE (p.user_id = auth.uid()))) OR (assigned_to IN ( SELECT profiles.id
   FROM zapp.profiles
  WHERE (profiles.user_id = auth.uid()))) OR (EXISTS ( SELECT 1
   FROM zapp.profiles
  WHERE ((profiles.user_id = auth.uid()) AND (profiles.role = ANY (ARRAY['admin'::text, 'supervisor'::text]))))))) WITH CHECK (((gmail_account_id IN ( SELECT ga.id
   FROM (email_app.gmail_accounts ga
     JOIN zapp.profiles p ON ((p.id = ga.profile_id)))
  WHERE (p.user_id = auth.uid()))) OR (EXISTS ( SELECT 1
   FROM zapp.profiles
  WHERE ((profiles.user_id = auth.uid()) AND (profiles.role = ANY (ARRAY['admin'::text, 'supervisor'::text])))))));


--
-- Name: email_threads email_threads_select_own_or_assigned; Type: POLICY; Schema: email_app; Owner: -
--

CREATE POLICY email_threads_select_own_or_assigned ON email_app.email_threads FOR SELECT TO authenticated USING (((gmail_account_id IN ( SELECT ga.id
   FROM (email_app.gmail_accounts ga
     JOIN zapp.profiles p ON ((p.id = ga.profile_id)))
  WHERE (p.user_id = auth.uid()))) OR (assigned_to IN ( SELECT profiles.id
   FROM zapp.profiles
  WHERE (profiles.user_id = auth.uid()))) OR (EXISTS ( SELECT 1
   FROM zapp.profiles
  WHERE ((profiles.user_id = auth.uid()) AND (profiles.role = ANY (ARRAY['admin'::text, 'supervisor'::text])))))));


