--
-- Name: evolution_media media_insert_auth; Type: POLICY; Schema: evo; Owner: -
--

CREATE POLICY media_insert_auth ON evo.evolution_media FOR INSERT TO authenticated WITH CHECK ((zapp.current_user_is_privileged() OR (EXISTS ( SELECT 1
   FROM evo.evolution_contacts c
  WHERE (((c.remote_jid)::text = evolution_media.remote_jid) AND (((c.assigned_to)::text = (auth.uid())::text) OR (c.assigned_to IS NULL)))))));


--
-- Name: evolution_media media_service; Type: POLICY; Schema: evo; Owner: -
--

CREATE POLICY media_service ON evo.evolution_media TO service_role USING (true) WITH CHECK (true);


--
-- Name: evolution_messages messages_delete; Type: POLICY; Schema: evo; Owner: -
--

CREATE POLICY messages_delete ON evo.evolution_messages FOR DELETE TO authenticated USING ((EXISTS ( SELECT 1
   FROM zapp.profiles p
  WHERE ((p.user_id = ( SELECT auth.uid() AS uid)) AND (p.role = ANY (ARRAY['admin'::text, 'supervisor'::text]))))));


--
-- Name: evolution_messages messages_insert_scoped; Type: POLICY; Schema: evo; Owner: -
--

CREATE POLICY messages_insert_scoped ON evo.evolution_messages FOR INSERT TO authenticated WITH CHECK ((( SELECT zapp.current_user_is_privileged() AS current_user_is_privileged) OR (EXISTS ( SELECT 1
   FROM evo.evolution_contacts c
  WHERE (((c.remote_jid)::text = evolution_messages.remote_jid) AND ((c.instance_name)::text = (evolution_messages.instance_name)::text) AND (((c.assigned_to)::text = ( SELECT (auth.uid())::text AS uid)) OR (c.assigned_to IS NULL)))))));


--
-- Name: evolution_messages messages_select_scoped; Type: POLICY; Schema: evo; Owner: -
--

CREATE POLICY messages_select_scoped ON evo.evolution_messages FOR SELECT TO authenticated USING ((( SELECT zapp.current_user_is_privileged() AS current_user_is_privileged) OR (EXISTS ( SELECT 1
   FROM evo.evolution_contacts c
  WHERE (((c.remote_jid)::text = evolution_messages.remote_jid) AND ((c.instance_name)::text = (evolution_messages.instance_name)::text) AND (((c.assigned_to)::text = ( SELECT (auth.uid())::text AS uid)) OR (c.assigned_to IS NULL)))))));


--
-- Name: evolution_messages messages_update; Type: POLICY; Schema: evo; Owner: -
--

CREATE POLICY messages_update ON evo.evolution_messages FOR UPDATE TO authenticated USING ((EXISTS ( SELECT 1
   FROM zapp.profiles p
  WHERE ((p.user_id = ( SELECT auth.uid() AS uid)) AND (p.role = ANY (ARRAY['admin'::text, 'supervisor'::text])))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM zapp.profiles p
  WHERE ((p.user_id = ( SELECT auth.uid() AS uid)) AND (p.role = ANY (ARRAY['admin'::text, 'supervisor'::text]))))));


