--

CREATE POLICY vps_comments_insert_authenticated ON evo.vps_comments FOR INSERT TO authenticated WITH CHECK (((content IS NOT NULL) AND ((length(content) >= 1) AND (length(content) <= 2000)) AND (scenario_id IN ( SELECT vps_scenarios.id
   FROM evo.vps_scenarios))));


