--
-- Name: vps_scenario_status vps_status_update_authenticated; Type: POLICY; Schema: evo; Owner: -
--

CREATE POLICY vps_status_update_authenticated ON evo.vps_scenario_status FOR UPDATE TO authenticated USING ((EXISTS ( SELECT 1
   FROM zapp.profiles p
  WHERE ((p.user_id = auth.uid()) AND (p.role = ANY (ARRAY['admin'::text, 'supervisor'::text])))))) WITH CHECK (((status = ANY (ARRAY['todo'::text, 'doing'::text, 'done'::text])) AND (updated_by IS NOT NULL) AND (length(updated_by) > 0) AND (EXISTS ( SELECT 1
   FROM zapp.profiles p
  WHERE ((p.user_id = auth.uid()) AND (p.role = ANY (ARRAY['admin'::text, 'supervisor'::text])))))));


