   FROM vendas.usuarios u
  WHERE ((u.id = auth.uid()) AND (u.ativo = true) AND (u.perfil = ANY (ARRAY['admin'::text, 'comprador'::text]))))) OR (EXISTS ( SELECT 1
   FROM financeiro.app_usuarios au
  WHERE ((au.email = auth.email()) AND (au.role = ANY (ARRAY['analista'::text, 'diretor'::text, 'admin'::text])) AND (au.ativo = true)))))) WITH CHECK (((EXISTS ( SELECT 1
   FROM vendas.usuarios u
  WHERE ((u.id = auth.uid()) AND (u.ativo = true) AND (u.perfil = ANY (ARRAY['admin'::text, 'comprador'::text]))))) OR (EXISTS ( SELECT 1
   FROM financeiro.app_usuarios au
  WHERE ((au.email = auth.email()) AND (au.role = ANY (ARRAY['analista'::text, 'diretor'::text, 'admin'::text])) AND (au.ativo = true))))));


